local P = LoreForeverPacks.Begin("LoreForever_Lang_svSE")
P.entries["quest:746"] = {n="Dwarven Digging",s="Dwarven Digging är ett uppdrag i Mulgore som Baine Bloodhoof ger i Bloodhoof Village. Baine oroar sig för att dvärgarnas utgrävningar ska reta upp de inhemska bestarna och vanhelga den heliga jorden. Därför ber han unga hordförsvarare sabotera arbetet genom att beslagta och slå sönder deras hackor.",h="Dwarven Digging är ett uppdrag i Mulgore som Baine Bloodhoof ger i Bloodhoof Village.",kw={"baine bloodhoof","bloodhoof village","dvärg","smedja","kodo","mulgore","hackor","prospektör"},ang={["class:Shaman"]="Schamaner förstår att vårdslösa utgrävningar stör berggrunden och rubbar den elementära balansen, vilket väcker oro bland landets andar och varelser.",["faction:Horde"]="Dvärgar som står på Alliansens sida tränger in i hordens hjärtland och undergräver den sköra freden som upprättades efter det tredje kriget. De visar tydlig brist på respekt för stammarnas gränser.",["profession:Mining"]="Gruvarbetare vördar rikedomarna som döljs i stenen, men dvärgarnas metoder i Mulgore saknar respekt och harmoni och leder i stället till hänsynslös förstörelse.",["race:Tauren"]="Jordemoderns kropp är helig. Att se främmande inkräktare borra sig in i Mulgore böljande stäpper är en kränkning som kräver ett omedelbart och bestämt svar."},sec={{t="Inkräktare i kullarna",b="Nordväst om Bloodhoof Village har dvärgiska prospektörer börjat märka ut en utgrävningsplats bland Mulgore böljande kullar. Explorer's League och dess utgrävningslag söker titanreliker och jordens hemligheter över hela Kalimdor, men deras verksamhet visar sällan respekt för ursprungsfolkens marker eller seder. För tauren är jorden en levande moder som ska vördas, inte skalas av och gröpas ur efter sten och metall."},{t="Att försvara den heliga jorden",b="Baine Bloodhoof inser att dvärgarnas maskiner och skoningslösa sprängningar hotar slätternas sköra harmoni. Förutom den fysiska förstörelsen oroar oljudet traktens djurliv och driver slättens kodos till ursinne. Genom att slå sönder prospektörernas verktyg vid deras egna smedjor hoppas tauren sända ett tydligt budskap och hejda intrånget innan bestående skada sker."}},faq={{q="Varför gräver dvärgar i Mulgore?",a="Dvärgiska prospektörer tror att jordens djup i centrala Kalimdor döljer hemligheter och forntida föremål. Men deras brist på respekt för stammarnas territorium och våldsamma gruvmetoder har lett till direkt konflikt med tauren.",al={"dvärgar i mulgore","varför är prospektörerna här","dvärgutgrävning i mulgore"}},{q="Vem ger uppdraget Dwarven Digging?",a="Uppdraget ges av Baine Bloodhoof, den unge sonen till Cairne Bloodhoof, den store hövdingen. Han finns i Bloodhoof Village i centrala Mulgore.",al={"uppdragsgivare för dwarven digging","vem startar dwarven digging"}},{q="Varför vill Baine att verktygen ska slås sönder i stället för att bara stjälas?",a="Baine vill göra utrustningen helt obrukbar för att genast stoppa utgrävningen. När verktygen förstörs i smedjorna blir budskapet både symboliskt och praktiskt: landet lämnar inte ifrån sig sina hemligheter genom våld och vanhelgande.",al={"varför slå sönder hackorna","förstöra dvärgarnas verktyg"}},{q="Hur påverkar grävandet djurlivet i Mulgore?",a="Det högljudda grävandet och de djupa såren i marken oroar de inhemska varelserna kraftigt, särskilt de väldiga kodos som strövar i kullarna. Fredliga hjordar blir lättretliga och aggressiva.",al={"arga kodos","varför är bestarna arga"}},{q="Var kan hackorna slås sönder?",a="Hackorna kan hamras till skrot vid vilken fungerande smedja som helst. Du kan använda smedjan mitt i dvärgarnas utgrävningsläger eller ta dem till smederna i Thunder Bluff.",al={"var finns smedjan","slå sönder prospektörernas hackor i smedjan"}},{q="Har det här uppdraget koppling till Explorer's League större närvaro i Kalimdor?",a="Ja. Dvärgexpeditioner från Ironforge har upprättat utposter över hela Kalimdor, bland annat i Mulgore, The Barrens och södra Kalimdor. De utlöser ofta skärmytslingar med hordens folk om territoriell självbestämmanderätt och heliga platser.",al={"explorer's league i mulgore","ironforge i kalimdor"}}},fx={["755e231a"]={q="Vad ska Broken Tools användas till?",a="Broken Tools är ett konkret bevis på att du har satt stopp för dvärgarnas verksamhet. I stället för att bara driva bort prospektörerna eller ta deras utrustning vill Baine Bloodhoof att deras hackor slås sönder vid en smedja och återlämnas till honom. Då säkerställs att arbetet upphör och att ett tydligt budskap sänds mot vanhelgandet av den heliga jorden.",al={"broken tools","varför broken tools","syftet med broken tools"}},["95107d94"]={q="Vilka är dvärgarna som gräver i Mulgore?",a="De är dvärgiska prospektörer som har slagit upp ett utgrävningsläger i de nordvästra kullarna i Mulgore. De drivs av rykten om att uråldriga hemligheter ligger begravda under slätterna och söker historiska reliker och kunskap om titanerna, utan tanke på den andliga skada som deras stenbrott orsakar landet och dess vilda djur.",al={"dvärgar i mulgore","vilka är dvärggrävarna","prospektörer i mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="The Hunt Begins",s="The Hunt Begins är en grundläggande övergångsrit för unga äventyrare i Camp Narache på Red Cloud Mesa. På uppdrag av Grull Hawkwind ger sig de nyinvigda ut för att jaga lokala plainstriders och skaffa kött och fjädrar åt byn. När uppdraget är slutfört har de tagit första steget mot att vinna Chief Hawkwinds respekt och så småningom få tillträde till Thunder Bluff.",h="The Hunt Begins är en grundläggande övergångsrit för unga äventyrare i Camp Narache på Red Cloud Mesa.",kw={"camp narache","chief hawkwind","fjädrar","grull hawkwind","the hunt begins","mulgore","plainstrider","red cloud mesa"},ang={["class:Hunter"]="Att smyga sig på de snabba plainstriders på Red Cloud Mesa är den första praktiska övningen i skytte, spårning och att hedra djuren som försörjer dig.",["race:Tauren"]="För unga shu'halo är det en viktig övergångsrit att fälla sina första plainstriders på platån. Det bekräftar bandet till landet och plikten att försörja Camp Narache."},sec={{t="En stams försörjning",b="På höjderna av Red Cloud Mesa flätas överlevnad och tradition samman. Tauren jagar av nödvändighet för att ge sitt folk mat och kläder, men ser också smygandet och jakten som ett viktigt prov på disciplin och en sport. När förråden i Camp Narache börjar sina vänder sig samhället till sina unga för att samla färskt plainstriderkött till matlagningen och tåliga fjädrar till stammens kläder."},{t="Att vinna erkännande",b="Ingen blivande hjälte lämnar Red Cloud Mesa för Mulgores vidsträckta trakter utan att först visa sitt värde. Grull Hawkwind bedömer de nyanländas karaktär och kräver att de visar vad de går för innan de får träffa hans far, Chief Hawkwind. En lyckad jakt visar inte bara självständighet, utan också hängivenhet till stammen."}},faq={{q="Vem ger det här uppdraget?",a="Grull Hawkwind ger det här uppdraget i Camp Narache. Han är son till byns ledare, Chief Hawkwind, och fungerar som en tidig mentor för unga jägare och äventyrare på Red Cloud Mesa.",al={"uppdragsgivare","vem startar the hunt begins","grull hawkwind"}},{q="Varför jagar man plainstriders i stället för andra djur?",a="Plainstriders är talrika över hela platån och ger både näringsrikt kött som fyller på de sinande matförråden och slitstarka fjädrar till traditionella taurenkläder och prydnader.",al={"varför plainstriders","plainstriderkött och fjädrar","jaga plainstriders"}},{q="Varför måste jag bevisa mitt värde innan jag får träffa Chief Hawkwind?",a="Taurens samhälle värdesätter praktiska insatser och jaktförmåga högt. Grull Hawkwind kräver att de nyinvigda visar grundläggande överlevnadskunskaper och lojalitet mot byn innan hövdingen tar emot dem och ger dem större ansvar.",al={"varför bevisa sig för chief hawkwind","chief hawkwinds godkännande","varför jaga först"}},{q="Vad är det större målet med prövningarna på Red Cloud Mesa?",a="Platån fungerar som en prövningsmark. När en ung tauren har visat Chief Hawkwind och de äldste i Camp Narache vad hen går för anses hen redo att bege sig ner till Mulgore slätter och ta sig in i huvudstaden Thunder Bluff.",al={"syftet med prövningarna på platån","varför är jag på red cloud mesa","lämna red cloud mesa"}},{q="Vad händer efter den här jakten?",a="Om du kommer tillbaka med köttet och fjädrarna får du Grulls godkännande och går direkt vidare till ”The Hunt Continues”, där de nyinvigda spårar större och mer svårfångat villebråd över platån.",al={"nästa uppdrag","fortsättning","vad händer efter the hunt begins"}},{q="Jagar tauren bara för att överleva?",a="Mat och resurser som läder, ben och fjädrar är viktiga, men tauren jagar också för sport och andlig samhörighet. Jakten vässar deras instinkter och hjälper stammarna att hålla sig alerta och starka.",al={"taurens syn på jakt","jaga för sport","varför jagar tauren"}}},fx={["395288c5"]={q="Varför vill Grull Hawkwind att det här blir gjort?",a="Grull Hawkwind ser något lovande i dig och vill att du bevisar ditt värde för stammen och hans far, Chief Hawkwind. Matförråden i Camp Narache börjar sina, och lägret behöver färska fjädrar. Genom att skicka dig för att samla in dem prövar han din jaktinstinkt samtidigt som byns nödvändiga förråd fylls på.",al={"varför vill grull att plainstriders jagas","grull hawkwinds motiv","varför jaga plainstriders åt grull"}},f26a5c4f={q="Vad ska Plainstrider Meat användas till?",a="Köttet samlas in för att fylla på Camp Naraches sinande matförråd. För att överleva på Red Cloud Mesa krävs en pålitlig tillgång på mat, och jakt på plainstriders ger det färska kött som behövs för att föda de unga jägarna och de äldre som bor i lägret.",al={"vad används plainstrider meat till","varför samla plainstrider meat","användning av plainstrider meat"}},fb1052a7={q="Vad ska Plainstrider Feather användas till?",a="Taurerna i Camp Narache använder plainstriderfjädrar till kläder och prydnader. Stammen tar vara på varje del av djuren de jagar och förvandlar den tåliga fjäderdräkten till praktiska kläder och utsmyckningar som passar livet på platån.",al={"vad används plainstrider feathers till","varför samla plainstriderfjädrar","användning av plainstrider feather"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="Poison Water",s="Poison Water inleder taurenfolkets arbete med att rena de heliga brunnarna i Mulgore från föroreningar. På uppdrag av Mull Thunderhorn i Bloodhoof Village samlar unga Horde-försvarare naturmaterial från slätterna för att skapa en återställande ritualtotem.",h="Poison Water inleder taurenfolkets arbete med att rena de heliga brunnarna i Mulgore från föroreningar.",kw={"bloodhoof village","reningstotem","mulgore","mull thunderhorn","plainstrider","poison water","prärievarg","winterhoof water well"},ang={["class:Druid"]="När gobliner förgiftar färskvattenkällor angriper de naturens balans direkt. Det kräver ett omedelbart svar för att bevara Mulgore sköra växt- och djurliv.",["class:Shaman"]="Att återställa förorenat vatten med totemer stärkta av djur visar grunderna i taurenfolkets schamanism: att samarbeta med traktens djurliv för att hela störningar i elementen.",["race:Tauren"]="Skändningen av färskvatten angriper kärnan i Jordmoderns gåvor och gör reningsritualen till en grundläggande plikt för varje tauren som blir vuxen i Mulgore."},sec={{t="Ett skändat land",b="Mulgore grässlätter är helig mark för taurenfolket, men lömska krafter har börjat hota deras livsnödvändiga vatten. Mull Thunderhorn, en äldste i Bloodhoof Village, upptäcker att goblinintränglingar och deras hantlangare har förorenat de dyrbara brunnar som försörjer stammarna och traktens djurliv. Föroreningen angriper direkt det andliga hjärtat hos det nomadfolk som nyligen bosatt sig här."},{t="Naturens kraft samlas",b="För att motverka industriella föroreningar förlitar sig Mull på traditionell tauren-schamanism i stället för grova botemedel. För att rena Winterhoof Water Well måste man skapa en kraftfull ritualtotem fylld med livskraften från Mulgore ursprungliga rovdjur. Han skickar jägare över de sydvästra slätterna för att spåra prärievargar efter deras tassar och vuxna plainstriders efter deras klor, så att landet kan använda sin egen kraft för att läka sina sår."}},faq={{q="Vem förgiftade brunnarna i Mulgore?",a="Goblinernas intrång och deras lejda hantlangare ligger bakom föroreningen av de heliga vattenhålen i Mulgore. Deras destruktiva industriella verksamhet och brist på respekt för naturens balans hotar både taurenstammarna och det lokala djurlivet.",al={"vem förorenade brunnarna","vem förgiftade mulgore","vem förorenade vattnet"}},{q="Varför behöver Mull Thunderhorn vargtassar och plainstriderklor?",a="Mull skapar traditionella reningstotemer av delar från Mulgore inhemska djur. Genom att ta vara på slätternas rovdjurs inneboende andar och styrka skapar han ett fokus som är kraftfullt nog att leda en vattenreningsritual.",al={"varför vargtassar","varför plainstriderklor","material till totem"}},{q="Vilken brunn ska det här uppdraget förbereda för rening?",a="Materialen samlas specifikt för att skapa reningstotemen till Winterhoof Water Well, den första i en rad förorenade brunnar som måste renas genom ritualer.",al={"vilken brunn är detta till","vilken vattenbrunn"}},{q="Var finns Mull Thunderhorn?",a="Mull Thunderhorn bor i Bloodhoof Village, den främsta taurenbosättningen mitt i Mulgore, kring Stonebull Lakes vatten.",al={"var finns mull thunderhorn","var finns mull","var lämnar man in poison water"}},{q="Var hittar man vargarna och plainstriders som behövs?",a="Prärievargar och vuxna plainstriders strövar omkring på slätterna sydväst om Bloodhoof Village.",al={"var hittar man prärievargar","var finns plainstriders","jaktmarker"}},{q="Vad händer när Mull får tassarna och klorna?",a="Mull binder samman de insamlade delarna till en Winterhoof Cleansing Totem och ber dig bära den direkt till Winterhoof Water Well för att utföra reningsriten.",al={"nästa uppdrag efter poison water","vad gör jag härnäst"}}},fx={["50414ce1"]={q="Varför vill Mull Thunderhorn att det här blir gjort?",a="Gobliner och deras hantlangare har förorenat de heliga vattenkällorna i Mulgore och angripit själva livsnerven i taurenfolkets hemland. För Mull Thunderhorn och invånarna i Bloodhoof Village innebär förorenade källor sjukdom och en kränkning av jordens heliga balans. Att rena dem är en brådskande andlig och praktisk plikt.",al={"mull thunderhorns motiv","varför rena vattenkällorna","varför uppdraget poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="The Ravaged Caravan",s="Morin Cloudstalker ber resenärer undersöka vraket efter en överfallen Venture Company-karavan nära Stonebull Lakes norra strand. Taurenerna satte karavanen i brand som hämnd för förlorade kamrater, men goblinskrotletare återvände för att bärga oskadat gods. En undersökning av de överlevande Supply Crate-lådorna avslöjar den verkliga industriella omfattningen av Venture Companys verksamhet i Mulgore.",h="Morin Cloudstalker ber resenärer undersöka vraket efter en överfallen Venture Company-karavan nära Stonebull...",kw={"morin cloudstalker","mulgore","ravaged caravan","stonebull lake","supply crate","venture company"},ang={["faction:Horde"]="Okontrollerad företagsutvidgning i Mulgore hotar Thunder Bluffs stabilitet. Hordens spejare måste därför störa Venture Companys logistik.",["profession:Mining"]="De robusta lådorna och logistikanteckningarna visar att Venture Company bedriver aggressiv mineralprospektering och utvinning över hela Mulgore.",["race:Tauren"]="Venture Companys maskiner ödelägger slätterna, och deras skogsröjning hotar ditt förfädersland. Därför är det avgörande för Mulgorets försvar att återta och förstöra deras förråd."},sec={{t="Hämnd vid sjön",b="De förkolnade resterna längs Stonebull Lakes norra strand vittnar om en snabb attack från taurenerna. Sörjande över två följeslagare som dödats i en tidigare skärmytsling överföll Morin Cloudstalker och hans krigare en beväpnad försörjningskaravan från Venture Company. Taurenerna ville utplåna inkräktarnas verksamhet och satte vagnarna i brand innan de lämnade det rykande vraket. De trodde att elden skulle förtära allt som goblinerna försökte frakta."},{t="Oavslutade affärer",b="Taurenerna upptäckte snart att Venture Companys bärgare letade bland de förkolnade resterna. Det tydde på att elden inte hade förstört det viktigaste godset. Morin skickar ut spejare för att undersöka vraket i stället för att riskera fler liv i blindo. Bland de sotiga resterna finns oskadade lådor märkta med Venture Company Mining Divisions insignier. De är packade för transport till centrala bearbetningsanläggningar."}},faq={{q="Varför förstördes karavanen?",a="Morin Cloudstalker och hans taurenkrigare överföll och brände karavanen som hämnd efter att två av deras spejare dödats i en tidigare sammanstötning med Venture Company.",al={"vem förstörde karavanen","varför brinner karavanen","karavanattack"}},{q="Var ligger Ravaged Caravan?",a="De brända vagnarna står längs Stonebull Lakes norra strand, öster om Bloodhoof Village i Mulgore.",al={"karavanens plats","var ligger karavanen","ravaged caravan plats"}},{q="Varför återvänder goblinerna till vraket?",a="Venture Company skickade dit bärgare eftersom elden inte förstörde allt deras gods. De försöker hämta hållbara försörjningslådor märkta för leverans till företagets centrala bearbetningsanläggningar.",al={"varför är bärgarna här","venture companys bärgare","vad vill goblinerna ha"}},{q="Vad finns i försörjningslådorna?",a="Lådorna bär Venture Company Mining Divisions insignier och innehåller mineralresurser märkta för raffinering och bearbetning vid företagets främsta industrianläggningar.",al={"lådornas innehåll","vad finns i lådan","förseglad försörjningslåda"}},{q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker är en tauren-spejare och spårare som är stationerad öster om Bloodhoof Village. Han har i uppgift att bevaka fientliga intrång i centrala Mulgore, särskilt från Venture Company.",al={"vem är morin","morin cloudstalkers roll"}},{q="Vad avslöjar karavanen om Venture Company?",a="Den visar att Venture Companys närvaro i Mulgore inte bara består av ett utforskningsteam, utan av en organiserad industriell utvinningsverksamhet med beväpnade försörjningsleder och centraliserade raffineringsnätverk.",al={"venture companys närvaro i mulgore","varför är gobliner i mulgore"}}},fx={["89fc7cfd"]={q="Varför vill Morin Cloudstalker att karavanens lådor undersöks?",a="Morin och hans krigare överföll Venture Companys karavan vid Stonebull Lake för att hämnas fallna kamrater. De brände vagnarna och trodde att elden skulle förinta allt av värde. När han såg goblinernas asätare leta igenom vraket förstod han att något värdefullt eller farligt hade överlevt lågorna. Han behöver att du undersöker lådorna för att ta reda på vad Venture Company transporterade genom Mulgore och varför de är så ivriga att återfå det.",al={"varför undersöka karavanen","morin cloudstalkers motiv","varför söka igenom försörjningslådorna"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="The Journey Has Just Begun",s="Efter Onyxias fall lär sig skickliga läderarbetare i Orgrimmar hur hennes fjäll kan skydda mot den svarta drakflygeln. Overlord Runthak erkänner deras hantverk och lär dem en sällsynt teknik för att tillverka skyddande mantlar, som behövs mot lågorna i Blackrock Spire.",h="Efter Onyxias fall lär sig skickliga läderarbetare i Orgrimmar hur hennes fjäll kan skydda mot den svarta...",kw={"blackrock","yngelmamma","kappa","läderarbete","runthak","nefarian","onyxia","fjäll"},ang={["faction:Horde"]="För Horde är skyddsutrustning smidd av fallna fiender avgörande för att värna styrkorna mot ytterligare drakförödelse."},sec={{t="En yngelmammas arv",b="Onyxias fall är en triumf för Horde, men den svarta drakflygeln är fortfarande ett hot. Yngelmammans fjällklädda skinn står emot drakeld. Hordes ledare söker hantverkare som kan förvandla drakens kvarlevor till skyddande rustning i stället för att låta dem gå till spillo."},{t="Skydd mot skuggflamma",b="Overlord Runthak lär begåvade läderarbetare att sy Onyxia Scale Cloak. Kunskapen är ingen tom uppvisning eller prestigemarkör. Djupt inne i Blackrock Mountain andas Onyxias bror Nefarian ut förödande eld. Utan yngelmammans fjälls förtrollade skydd skulle varje förtrupp som möter Lord of Blackrock förvandlas till aska."}},faq={{q="Vem erbjuder uppdraget och var finns personen?",a="Overlord Runthak erbjuder detta i Orgrimmar. Han erkänner Hordes mästare med mästerlig skicklighet i läderarbete som hjälpte till att besegra Onyxia.",al={"uppdragsgivare runthak","var finns overlord runthak","uppdragsstart"}},{q="Vilket krav måste uppfyllas för att få uppdraget?",a="Endast skickliga läderarbetare som har slutfört efterspelet efter Onyxias nederlag kan få detta, till exempel de som slutfört ”Victory for the Horde” eller ”A Most Puzzling Circumstance”.",al={"krav på läderarbete","hur får man uppdraget","förkunskapskrav"}},{q="Vad lär Overlord Runthak ut?",a="Overlord Runthak lär läderarbetare tekniken för att tillverka Onyxia Scale Cloak av fjäll från den fallna yngelmodern.",al={"recept som uppdragsbelöning","onyxia cloak-mönster","vad lär jag mig"}},{q="Varför är Onyxia Scale Cloak viktig?",a="Manteln skyddar bäraren mot Nefarians dödliga, brännande andedräkt. Utan dess unika skydd skulle det vara livsfarligt att möta ynglets herre.",al={"varför tillverka en kappa","kappans syfte","nefarian-kappa"}},{q="Vem är Lord of Blackrock?",a="Nefarian är Lord of Blackrock, en mäktig svart drake och Onyxias bror. Han smider planer från höjderna i Blackrock Mountain för att härska över de dödliga raserna.",al={"vem är lord of blackrock","nefarian identitet","blackrocks herre"}},{q="Varför säger uppdraget att resan just har börjat?",a="Onyxia har dräpts, men det större kriget mot den svarta drakflygeln och Nefarians planer i Blackrock Mountain har bara trappats upp.",al={"titelns betydelse","varför resan just har börjat"}}},fx={cb1b5404={q="Varför vill Overlord Runthak att det här blir gjort?",a="Overlord Runthak vill utrota Black Dragonflight fullständigt. Onyxias nederlag var en stor triumf, men hennes avkomma hemsöker fortfarande riket under hennes bror Nefarians befäl. Genom att lära ut den uråldriga tekniken att smida skyddskappor av yngelmammans fjäll ser Runthak till att Hordens mästare får det avgörande skydd de behöver för att stå emot Nefarians dödliga Shadow Flame och avsluta kriget.",al={"varför ger runthak det här uppdraget","overlord runthaks motiv","runthaks mål"}}},fp="26,199,22.250.0,27.344.1,49.139.0,49.183.0,33.118.0,40.147.0,29.158.0,57.142.0"}
P.entries["quest:7497"] = {n="The Journey Has Just Begun",s="I Stormwind känner Major Mattingly igen hantverkaren som besegrade Onyxia. Han lär ut hantverket som krävs för att göra en mantel av hennes fjäll.",h="I Stormwind känner Major Mattingly igen hantverkaren som besegrade Onyxia.",kw={"svarta drakflykten","blackrock","läderbearbetning","major mattingly","nefarian","onyxia","onyxia scale cloak","stormwind"},ang={["faction:Alliance"]="Som allianshjälte för du vidare Stormwinds seger över Onyxia i den kommande offensiven mot hennes bror Nefarian vid Blackrock Mountain."},sec={{t="En sällsynt skicklighet",b="Få av dem som hjälpte till att besegra Onyxia kan också bearbeta hennes skinn. När en hantverkare med mästerlig läderbearbetning rapporterar till Major Mattingly i Stormwind inser officeren hur viktiga dessa färdigheter är inför striderna som väntar."},{t="Skydd mot den svarta drakflykten",b="Onyxias död innebär inte att den svarta drakflykten har slutat vara ett hot. Major Mattingly lär hantverkaren att behandla och sy ihop hennes fjäll till en Onyxia Scale Cloak. Plagget skyddar bäraren mot den eldiga andedräkten från hennes bror Nefarian, Lord of Blackrock."}},faq={{q="Vem erbjuder uppdraget The Journey Has Just Begun?",a="Major Mattingly i Stormwind City erbjuder det till allianshjältar som kämpade i fälttåget mot Onyxia och har mästerlig läderbearbetning.",al={"vem ger uppdraget the journey has just begun","var hittar jag the journey has just begun","uppdragsgivare för the journey has just begun"}},{q="Vad lär man sig i det här uppdraget?",a="Major Mattingly lär mästerliga läderarbetare att göra en Onyxia Scale Cloak av Onyxias fjäll.",al={"vilket recept får jag","onyxia cloak recept","belöning för the journey has just begun"}},{q="Varför behövs Onyxia Scale Cloak?",a="Manteln har behandlats för att skydda bäraren mot Nefarians, Lord of Blackrocks, eldiga andedräkt.",al={"varför behöver jag onyxia cloak","vad används onyxia scale cloak till","skydd mot skuggflamma"}},{q="Vem är Lord of Blackrock som Major Mattingly nämner?",a="Lord of Blackrock är Nefarian, en mäktig svart drake och Onyxias bror. Han härskar över Blackrock Spire och fortsätter den svarta drakflyktens planer.",al={"vem är lord of blackrock","vem är nefarian","mattinglys drakvarning"}},{q="Varför måste hjälten vara läderarbetare för att få den här kunskapen?",a="Att bearbeta drakfjäll utan att förstöra deras magiska skydd kräver en mästerlig läderarbetares avancerade skicklighet.",al={"varför krävs läderbearbetning","kan vem som helst få uppdraget","krav på läderbearbetning"}},{q="Löser Onyxias död hotet från den svarta drakflykten i Stormwind?",a="Nej. Onyxia är död, men hennes bror Nefarian befaller fortfarande över Blackrock Mountain och smider planer mot alliansen och de dödliga folken.",al={"är stormwind säkert nu","onyxia är död, vad händer nu","svarta drakflykten efter onyxia"}}},fx={b42a6800={q="Varför delar Major Mattingly med sig av den här kunskapen?",a="Major Mattingly vet att dråpet på Onyxia bara var det första angreppet. Yngelmamman är död, men hennes släkte hotar fortfarande Azeroth från Blackrock Mountains höjder. För att utplåna den återstående svarta drakflocken måste mästarna överleva Nefarians brännande lågor. Mattingly delar med sig av den här särskilda tekniken så att Alliansens hjältar kan tillverka skyddskappor av Onyxias fjäll och avsluta kriget.",al={"varför lär mattingly dig","major mattinglys motiv","mattinglys skäl"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="The Legend of Stalvan",s="Utredningen om Stalvan Mistmantle leder från Duskwood till ett ensligt hem i sydöstra Elwynn Forest. Marshal Haggard, en åldrad veteran med försämrad syn, visar dig en kista på övervåningen med en gammal bunt papper som lämnades kvar när han flyttade in.",h="Utredningen om Stalvan Mistmantle leder från Duskwood till ett ensligt hem i sydöstra Elwynn Forest.",kw={"duskwood","elwynn forest","bleknad journal page","forlorn spirit","marshal haggard","stalvan"},ang={["faction:Alliance"]="När Stalvans arv nystas upp blottas mörka kapitel som ligger gömda inom Elwynns annars fridfulla landsbygdsgränser.",["race:Human"]="Stalvans väg slingrar sig genom vanliga mänskliga bosättningar och blir en varnande berättelse om isolering och ondska som döljer sig mitt framför ögonen på alla."},sec={{t="En veterans vind",b="Marshal Haggard bor långt från staden, i utkanten av sydöstra Elwynn Forest, nära gränsen till Duskwood och Redridge. När han flyttade in i sitt avskilda hem hittade han en kista på övervåningen, full av gamla pergament. Hans sviktande syn blev allt grumligare, så han gav upp försöken att läsa dem och lät dokumenten ligga orörda tills en utredare frågar om Stalvan."},{t="Kvarhängande skuggor",b="Papperen i kistan på övervåningen är inga vanliga rester från ett hushåll. När någon rör vid Stalvans tillhörigheter väcks ofta rastlös magi, som lockar fram en Forlorn Spirit bunden till Mistmantles förflutna. Den gömda journal page ger en direkt inblick i Stalvans privata anteckningar och konkreta bevis för att den tillbakadragne lärde lämnade spår i Elwynn innan han försvann."}},faq={{q="Vem är Marshal Haggard?",a="Marshal Haggard är en åldrad veteran med nästan ingen syn, som lever stillsamt i en avskild stuga i sydöstra Elwynn Forest. Han har kvar papper som sedan länge glömts bort och som tillhörde Stalvan Mistmantle, och som han hittade i sitt hus.",al={"marshal haggard","haggard elwynn","vem är haggard"}},{q="Varför ledde spåret tillbaka till Elwynn Forest?",a="Ledtrådar från Darkshire och Moonbrook följer Stalvans vandringar genom södra Stormwind. På Haggards gård fanns gamla papper som Stalvan hade lämnat efter sig.",al={"varför elwynn forest","stalvan elwynn","varför bege sig till haggard"}},{q="Vad finns i kistan på övervåningen?",a="Kistan innehåller en bleknad journal page skriven av Stalvan Mistmantle, bevarad bland en bunt pergament som Haggard aldrig lyckades undersöka ordentligt.",al={"kista på övervåningen","bleknad journal page","vad finns i kistan"}},{q="Varför anfaller en ande när kistan öppnas?",a="En Forlorn Spirit hemsöker relikerna från Stalvans forna liv och visar sig våldsamt när en främling stör hans personliga anteckningar och minnen.",al={"forlorn spirit","varför anfaller anden","ande i haggards hus"}},{q="Hur för utredningen om Stalvan framåt?",a="Den bleknade sidan ger förstahandsbevis med Stalvans egen handstil och hjälper dig att pussla ihop berättelsen om hans förflutna.",al={"stalvans mysterium","vad avslöjar sidan","steg i stalvans uppdragskedja"}},{q="Varför kunde Marshal Haggard inte läsa papperen själv?",a="Med åren har Haggards syn blivit grumlig och svag, så han kan inte tyda liten eller bleknad handstil på de gamla dokumenten.",al={"haggard blind","varför haggard behöver hjälp"}}},fx={["7284e072"]={q="Varför vill Marshal Haggard att det här blir gjort?",a="Marshal Haggard är en gammal soldat som lever ett stillsamt pensionärsliv, men han har fortfarande kvar en riksofficers instinkter. När du söker sanningen om Stalvan Mistmantle minns han de bortkastade pergamenten som låg kvar i kistan när han tog över huset. Han har ingen egen del i den mörka gåtan, men vill hjälpa dig med undersökningen så gott han kan, även om hans sviktande syn hindrar honom från att själv granska pappren.",al={"varför hjälpa haggard","marshal haggards motiv","varför vill haggard ha dagboken"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="The Hunt Continues",s="The Hunt Continues är en tidig övergångsrit som Grull Hawkwind ger i Camp Narache. Uppdraget går ut på att samla pälsar från mountain cougars i de södra kullarna, så att stammens barn får kläder och deras tält kan lagas.",h="The Hunt Continues är en tidig övergångsrit som Grull Hawkwind ger i Camp Narache.",kw={"camp narache","chief hawkwind","grull hawkwind","mountain cougar-pälsar","red cloud mesa","taurenjakt","the hunt continues"},ang={["class:Hunter"]="Uppgiften stärker jaktens grundläggande filosofi på slätterna: att spåra djur med ett syfte, bara ta det som behövs och aldrig se djur som ren underhållning eller troféer.",["race:Tauren"]="För unga tauren som blir vuxna på Red Cloud Mesa är det en viktig övergångsrit att lära sig att varje del av ett djur ska tjäna stammen, från mat till kläder och skydd."},sec={{t="Jaktens syfte",b="I Camp Narache får unga jägare lära sig att jakt aldrig är ett nöje eller ett sökande efter troféer. Grull Hawkwind skickar ut unga äventyrare till de södra kullarna på Red Cloud Mesa för att spåra mountain cougars. Uppgiften handlar inte bara om att visa sin skicklighet i strid, utan betonar ansvaret för samhället och visar att riktiga jägare måste skaffa viktiga förnödenheter åt sitt folk."},{t="Skydd åt stammen",b="Livet på platån kräver tåliga material som står emot väder och vind. Grull förklarar att cougarhudarna behövs akut för att sy kläder åt stammens barn och laga de slitna hudtälten i Camp Narache. Den som visar sig kunna skaffa dessa värdefulla pälsar vinner de äldstes tacksamhet, och Grull lovar att själv berätta för sin far, Chief Hawkwind, om jägarens osjälviska insats."}},faq={{q="Varför behöver stammen pälsar från mountain cougars?",a="Pälsarna från mountain cougars är viktiga och användbara resurser för Camp Narache. Grull Hawkwind förklarar att hudarna behövs för att tillverka varma kläder åt stammens barn och för att laga och förstärka byns tält.",al={"varför jaga cougars","vad används cougarpälsar till","användning av mountain cougar-pälsar"}},{q="Vem ger uppdraget?",a="Jakten ges av Grull Hawkwind, en framstående jägare i Camp Narache och son till Chief Hawkwind. Han vägleder nybörjare i de viktiga uppgifter som krävs för att stötta bosättningen.",al={"vem ger the hunt continues","uppdragsgivare i camp narache"}},{q="Var finns mountain cougars?",a="Mountain cougars strövar omkring på de klippiga åsarna och böljande kullarna strax söder om Camp Narache på Red Cloud Mesa.",al={"var finns cougars","mountain cougars plats","var hittar man mountain cougar"}},{q="Hur är Grull Hawkwind släkt med Chief Hawkwind?",a="Grull Hawkwind är son till Chief Hawkwind, stammens ledare i Camp Narache. Om du skaffar de pälsar som behövs lovar Grull att tala med sin far för din räkning och berätta om dina generösa dåd.",al={"hur imponerar man på chief hawkwind","chief hawkwinds son"}},{q="Vad lär jakten ut om tauren-traditionen?",a="Bland tauren betraktas jakt aldrig som sport eller troféjakt. Varje djur som fälls ska försörja samhället. Genom att använda hud, kött och ben för att trygga stammens överlevnad visar man respekt för slätterna.",al={"taurens jaktfilosofi","varför jaga i mulgore"}},{q="Varför är pälsar från mountain cougars så värdefulla?",a="Cougarpälsar är tjocka och tåliga, och lämpar sig väl för att stå emot vädret på de vindpinade slätterna. De ger värme åt små barn och är tillräckligt starka för att laga bostäder, så byns äldste värdesätter dem högt.",al={"är cougarpälsar värdefulla","varför värderas cougarpälsar högt"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="The Ravaged Caravan",s="En undersökning av en förstörd transport i Mulgore avslöjar att goblinernas industrimän har skaffat sig ett olagligt fäste i taurenfolkets territorium. När spejare återfinner dokument ur en förseglad låda bekräftar de att Venture Company systematiskt utvinner landets mineralrikedomar. Upptäckten får Bloodhoof Outrunners att organisera ett aktivt försvar av sina förfäders slätter.",h="En undersökning av en förstörd transport i Mulgore avslöjar att goblinernas industrimän har skaffat sig ett...",kw={"bloodhoof village","morin cloudstalker","mulgore","outrunners","ravaged caravan","supply crate","venture company","dokument från venture company"},ang={["class:Druid"]="Druider håller landets balans helig, och Venture Companys destruktiva, rökfyllda dagbrottsbrytning är en skändning som måste renas bort.",["faction:Horde"]="Horden förlitar sig på Mulgore lojalitet och stabilitet. Om utländska handelskarteller tillåts skövla kullarna hotas tryggheten i själva Thunder Bluff.",["profession:Mining"]="Den högvärdiga malmen i lådan bevisar att Mulgore östra kullar döljer rika underjordiska ådror som utomstående skyndar sig att exploatera.",["race:Tauren"]="För taurenfolket är det en förolämpning mot Jordmodern och en krigshandling mot deras nyvunna fred att se grova industrimaskiner riva upp Mulgore slätter där deras förfäder levde."},sec={{t="Bevis på exploatering",b="Vraket av en härjad karavan öster om Bloodhoof Village berättar en oroande historia. I en förseglad Supply Crate ligger en stor mängd bruten malm och mineraler, tillsammans med en bunt dokument från Venture Company. Dokumenten ger obestridliga bevis för att det giriga Venture Company har inlett en otillåten gruvdrift djupt inne i Mulgore fridfulla dalar."},{t="Outrunners håller vakt",b="Morin Cloudstalker och hans fellow Outrunners har hållit noggrann uppsikt över Mulgore gränser, medvetna om att utomstående fraktioner vill utnyttja deras fridfulla hemland. När dokumenten överlämnas bekräftas Morins värsta farhågor: rök över de östra kullarna signalerar en växande kommersiell invasion. Taurenfolket har inget annat val än att driva tillbaka fördärvarna innan kullarna blir helt utarmade."}},faq={{q="Vad finns i den förseglade Supply Crate?",a="När lådan bänds upp syns en fullpackad blandning av bruten malm, råa mineraler och en bunt dokument från Venture Company som beskriver deras verksamhet.",al={"byte i supply crate","vad finns i lådan","lådans innehåll"}},{q="Vem är Morin Cloudstalker?",a="Morin Cloudstalker är en tauren Outrunner som är stationerad vid vägen öster om Bloodhoof Village, mot gränsen till The Barrens. Hans uppgift är att patrullera Mulgore och hålla uppsikt över utländska hot.",al={"vem är morin","morins roll","outrunner morin"}},{q="Varför är Venture Company i Mulgore?",a="Venture Company vill hänsynslöst utnyttja Mulgore rika naturresurser och malmådror och gräver sig in i kullarna utan hänsyn till jorden eller dess ursprungsfolk.",al={"varför är gobliner här","venture companys mål i mulgore","vad vill gobliner ha"}},{q="Varifrån kom karavanen?",a="Karavanen tillhörde Venture Company och transporterade bruten malm och verksamhetsdokument från deras verksamhet vid kullarna innan den förstördes längs vägen.",al={"vems karavan var det","karavanens ursprung","vem angrep karavanen"}},{q="Vart leder den här undersökningen härnäst?",a="Med dokumenten i hand skickar Morin Cloudstalker krigare för att konfrontera Venture Companys ledning direkt och slå sönder deras gruvdrift i de östra kullarna.",al={"what comes next","uppdrag efter ravaged caravan","uppföljning av karavanen"}},{q="Varför hotar detta taurenfolket?",a="Taurenfolket ser landet som heligt och vördar Jordmodern. Venture Companys hänsynslösa dagbrottsbrytning och industriella föroreningar skändar aktivt Mulgore orörda landskap.",al={"varför bryr sig taurenfolket","hotet från venture company","hot mot mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="A Humble Task",s="A Humble Task är en tidig pliktceremoni som Chief Hawkwind ger i Camp Narache. Medan hövdingen tar hand om viktiga angelägenheter för stammen på Red Cloud Mesa ber han en ung äventyrare bege sig sydost och se till sin åldriga mor vid den lokala vattenkällan. Uppdraget betonar gemensamt ansvar, vördnad för äldre och den dagliga harmoni som är grundläggande för taurenfolkets levnadssätt.",h="A Humble Task är en tidig pliktceremoni som Chief Hawkwind ger i Camp Narache.",kw={"a humble task","camp narache","chief hawkwind","greatmother hawkwind","mulgore","red cloud mesa","vattenkälla"},ang={["faction:Horde"]="Den stillsamma, lantliga prägeln på Naraches uppgifter visar hur taurenfolkets fridfulla gemenskapsfilosofi står i kontrast till den hårdare, överlevnadsinriktade uthållighet som präglar resten av den gryende Horden.",["race:Tauren"]="För unga taurenkrigare visar svaret på hövdingens uppmaning att de följer grundsatserna i Earth Mothers lära: respekt för äldre och orubbligt engagemang för stammens gemensamma välmående."},sec={{t="Gemenskap och plikt",b="I skuggan av Camp Narache förväntas varje medlem av stammen dra sitt strå till stacken och bidra till livets harmoni. För unga tauren som blir vuxna mäts stammens plikter inte bara i stridsförmåga mot quilboars eller rovdjur; de börjar med grundläggande socialt ansvar. Chief Hawkwind visar detta ideal i praktiken: eftersom hans ledarskap inom administration och försvar binder honom vid hans post, litar han på att oerfarna äventyrare ser till samhällets utsatta äldre."},{t="Källan sydost om Narache",b="Mulgore är beroende av viktiga naturliga vattenkällor utspridda utanför lägrets gränser vid Red Cloud Mesa. Tidigt på morgonen lämnade Greatmother Hawkwind byn obevakad för att hämta färskt vatten från källan i sydost. I ett land där territoriella vilddjur och Bristleback quilboars tränger sig på väcker det stilla oro när en äldre person är borta i flera timmar, så Hawkwind skickar hjälp för att försäkra sig om att hon är oskadd."}},faq={{q="Vem ger uppdraget och var hittar jag personen?",a="Chief Hawkwind, ledaren för Camp Narache på Red Cloud Mesa i Mulgore, ger uppdraget. Han står i lägrets centrala paviljong och överblickar de lokala angelägenheterna.",al={"vem ger a humble task","var hämtar jag uppdraget","chief hawkwinds plats"}},{q="Var finns Greatmother Hawkwind?",a="Greatmother Hawkwind finns strax sydost om Camp Narache, där hon sköter vattenkällan på mesans lägre nivå.",al={"greatmother hawkwinds plats","var finns modern","vattenkällans plats"}},{q="Varför tittar inte Chief Hawkwind till sin mor själv?",a="Chief Hawkwind måste stanna i Camp Narache för att sköta viktiga angelägenheter för stammen och vägleda unga krigare. Som hövding förlitar han sig på stammens gemensamma ansvar och litar på att framväxande äventyrare tar hand om byns angelägenheter i hans ställe.",al={"varför kan hövdingen inte gå","varför tittar inte hawkwind till henne","chief hawkwind upptagen"}},{q="Är Greatmother Hawkwind i fara vid källan?",a="Även om slätterna omkring henne hyser aggressiva bergspumor och striders hittas Greatmother Hawkwind välbehållen vid källan, glatt överraskad över att någon gjorde sig besväret att se till en äldre person.",al={"är hon i säkerhet","blir greatmother attackerad","fara vid vattenkällan"}},{q="Vilken kulturell betydelse har uppdraget för tauren?",a="Taurenkulturen värdesätter familjen, gemenskapens sammanhållning och vördnad för äldre högt. Uppdraget lär unga hjältar att sann styrka grundar sig i ödmjuk tjänst och att skydda sina närmaste, inte i att jaga personlig ära.",al={"taurenkultur och a humble task","varför är det här en ödmjuk uppgift","taurenfolkets äldre"}},{q="Vad händer när jag har hittat Greatmother Hawkwind?",a="När du talar med Greatmother Hawkwind slutför hon uppgiften och ber dig om ytterligare hjälp med att bära den fyllda Water Pitcher tillbaka till lägret.",al={"nästa uppdrag","fortsättning på a humble task","vad gör jag när jag hittat modern"}}},fx={b1d313d3={q="Varför vill Chief Hawkwind att du ser till hans mor?",a="Hans gamla mor lämnade Camp Narache tidigt på morgonen för att hämta vatten från brunnen åt sydost, och hon har varit borta länge. Taurenlivet bygger på gemensamt ansvar och omsorg, så även om Hawkwind oroar sig för hennes välbefinnande håller hans plikter som hövding honom kvar i lägret.",al={"varför vill hawkwind få det här gjort","chief hawkwinds motiv","varför se till greatmother hawkwind"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="A Humble Task",s="A Humble Task är en inledande tjänsterit i Red Cloud Mesa, där en äldre prövar en spirande äventyrares ödmjukhet och flit. Genom att bära färskt brunnsvatten över slätterna till ledaren i Camp Narache lär sig unga tauren att tjänsten för folket börjar med de enklaste sysslorna.",h="A Humble Task är en inledande tjänsterit i Red Cloud Mesa, där en äldre prövar en spirande äventyrares...",kw={"camp narache","chief hawkwind","greatmother hawkwind","humble task","mulgore","red cloud mesa","earthmothers riter","water pitcher"},ang={["faction:Horde"]="Familjen Hawkwinds lärdomar visar hur tauren håller samman och överlever i Mulgore och utgör en fredlig men orubblig hörnsten i Thralls Horde.",["race:Tauren"]="Att hämta vatten åt de äldre förkroppsligar taureners grundläggande dygd att ta hand om gemenskapen och visar att du är redo att följa Earthmothers väg."},sec={{t="Ungdomens kraft",b="Greatmother Hawkwind har vandrat längs många stigar under sitt långa liv, och även om hennes själ fortfarande är stadig bär benen henne inte längre över slätterna med samma fart som i ungdomen. Hon håller till nära brunnen vid Red Cloud Mesas södra utkant och sköter sina plikter med tålmodig beslutsamhet. När blivande stamförsvarare korsar hennes väg leder hon deras ungdomliga energi mot praktiska behov i samhället och ger dem chansen att visa sitt värde genom tjänst snarare än våld."},{t="Tjänst för stammen",b="Uppgiften går ut på att bära en fylld vattenkanna tillbaka nordväst till Camp Narache och överlämna den direkt till bosättningens ledare, Chief Hawkwind, som råkar vara Greatmothers son. I taurenernas samhälle kräver överlevnad på Mulgore torra slätter gemensamt arbete och tillförlitlig tillgång till färskt vatten. Att visa respekt för samhällets äldre genom att ta på sig deras bördor ses som grundstenen i att bli en sann beskyddare av stammen."},{t="En väg mot Thunder Bluff",b="Chief Hawkwind ser mer än en avklarad syssla när en ung vandrare kommer med vatten från hans mor. Enligt taureners sed börjar en individs beredskap att försvara sitt folk i vidare länder med ödmjukhet och en spontan vilja att hjälpa till. Genom att visa denna stillsamma disciplin fångar den unga äventyraren hövdingens uppmärksamhet och får en rekommendation till Earthmothers urgamla riter, de verkliga andliga prövningar som öppnar vägen till Thunder Bluff."}},faq={{q="Vem är Greatmother Hawkwind?",a="Greatmother Hawkwind är en äldre medlem av familjen Hawkwind som håller till vid brunnen i Red Cloud Mesa. Hon är mor till Chief Hawkwind, ledaren i Camp Narache, och vägleder unga tauren i att lära sig ödmjukhet och stammens värderingar.",al={"greatmother hawkwind","vem ger en ödmjuk uppgift","hawkwind-äldste"}},{q="Var ligger brunnen?",a="Brunnen ligger sydost om Camp Narache på Red Cloud Mesas gräsbevuxna slätter. Kannor med färskt brunnsvatten står bredvid den, redo för resenärer och lägerförvaltare att bära tillbaka.",al={"brunnens plats","var finns brunnen","hitta vattenkanna"}},{q="Vem är Chief Hawkwind?",a="Chief Hawkwind är hövdingen som styr Camp Narache i Red Cloud Mesa. Han leder unga taureners träning och andliga riter och förbereder dem för att ge sig ut och tjäna den större stammen i Mulgore.",al={"chief hawkwind","vem är hövdingen","ledaren i camp narache"}},{q="Varför ses den här sysslan som en viktig prövning?",a="Taureners kultur värdesätter ödmjukhet, stöd till samhället och respekt för de äldre högt. Att utföra vardagliga och oglamorösa plikter visar att en äventyrare bryr sig om att hålla sitt folk vid liv, inte bara om personlig ära i strid.",al={"varför bära vatten","varför en ödmjuk uppgift","är uppdraget viktigt"}},{q="Vad händer när A Humble Task är slutförd?",a="När du slutför uppgiften bevisar du din disciplin för Chief Hawkwind, som sedan ber dig genomgå Earthmothers riter, en rad traditionella prövningar som alla tauren måste klara när de blir vuxna.",al={"what comes next","nästa uppdrag","efter humble task"}},{q="Vart leder den här vägen till slut?",a="När du vinner de äldres respekt i Camp Narache är du redo att lämna den avskilda platån bakom dig och färdas ut på Mulgore vida slätter, och till sist mot huvudstadens höga platåer i Thunder Bluff.",al={"framtida resmål","vart är vi på väg","målet thunder bluff"}}},fx={["57bce500"]={q="Varför vill Greatmother Hawkwind att det här blir gjort?",a="Greatmother Hawkwind medger att hennes åldrande ben inte längre har sin forna kraft, vilket gör enkla vardagssysslor runt Red Cloud Mesa långsamma och tröttande. Än viktigare är att hon ser det här rutinärendet som en viktig moralisk läxa för dig. Att leverera livsnödvändigt dricksvatten till hennes son, Chief Hawkwind, blir ett tidigt prov på om du har den ödmjukhet, det tålamod och den gemenskapsanda som förväntas av en sann tjänare åt stammen.",al={"greatmother hawkwinds motiv","varför hämta vatten åt chief hawkwind","varför uppdraget a humble task"}},b511fd77={q="Vad ska Water Pitcher användas till?",a="Water Pitcher är ett enkelt lerkärl med nyhämtat vatten från brunnen på Red Cloud Mesa, avsett att ge Camp Narache rent vatten. Att bära det prövar din hängivenhet till gemensamma sysslor och ser till att även nybörjare bland äventyrarna lär sig värdet av att försörja sina närmaste innan de söker större ära i strid.",al={"water pitchers syfte","varför water pitcher","vad är vattenkannan"}},["19ad5d96"]={q="Varför ber Greatmother Hawkwind dig i stället för att göra det själv?",a="Greatmother Hawkwind är gammal och medger att hennes ben inte längre har sin forna styrka. Därför tar det mycket längre tid än förr att bära tunga vattenkärl. När en arbetsför nybörjare som du dyker upp tar hon chansen att både lätta sin egen börda och pröva om du är villig att utföra oglamoröst vardagsarbete för lägret.",al={"varför gör inte greatmother det själv","varför be mig hämta vatten","varför kan inte hawkwind hämta vatten"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="Winterhoof Cleansing",s="Winterhoof Cleansing är en rit som Mull Thunderhorn i Bloodhoof Village anförtrott åt Hordens äventyrare. Efter att goblinernas verksamhet förorenat de lokala källorna måste en välsignad totem bäras in på Venture Companys område för att rena Winterhoof Water Well. Att återställa källan är ett viktigt första steg för att läka de förgiftade vattnen i centrala Mulgore.",h="Winterhoof Cleansing är en rit som Mull Thunderhorn i Bloodhoof Village anförtrott åt Hordens äventyrare.",kw={"bloodhoof village","rening","mulgore","mull thunderhorn","gift","totem","venture company","vattenbrunn","winterhoof"},ang={["class:Druid"]="När törstigt djurliv genast återvänder till den renade källan blir det tydligt hur viktigt det är att läka naturen där civilisationen hotar att skövla den.",["class:Shaman"]="Att kanalisera andar genom totemer för att motverka onaturlig industriell förorening är själva kärnan i en shamans band till elementens vatten.",["faction:Horde"]="Att trygga Mulgore färskvatten stabiliserar taurenfolkets nyligen bosatta kärnland och stärker den unga Hordens södra pelare.",["race:Tauren"]="Brunnarna i Mulgore är heliga livskällor som Jordmodern skänkt. Att försvara dem mot goblinernas girighet är både en samhällsplikt och en helig förpliktelse för varje tauren."},sec={{t="Ett skövlat land",b="Mulgore slätter täcks av gräs och är beroende av ett känsligt nätverk av förfädernas vattenbrunnar för att försörja både vilt och de utspridda taurenstammarna. Nyligen flyttade Venture Companys hänsynslösa industriella legosoldater in bland de böljande kullarna sydost om Bloodhoof Village. Deras verksamhet har förorenat de lokala grundvattenmagasinen och gjort Winterhoof Water Well stinkande och giftig. Vilda djur undviker det förorenade vattnet, och de närliggande lägren står inför en överhängande kris om förgiftningen sprider sig längre genom jorden."},{t="Ritualen för renande vatten",b="För att motverka industrins smuts täljer och förtrollar Mull Thunderhorn en rituell reningstotem, fylld med Jordmoderns välsignelser. Men för att leverera botemedlet måste man trotsa beväpnade busar från Venture Company, som har lagt beslag på källan. När äventyraren placerar totemen direkt vid brunnens mynning skingras det förorenade avrinningvattnet, så att rent, livgivande vatten åter kan stiga upp ur jordens djup."}},faq={{q="Var ligger Winterhoof Water Well?",a="Winterhoof Water Well ligger i kullarna sydost om Bloodhoof Village i Mulgore. Den patrulleras flitigt av goblinarbetare och legosoldater som arbetar för Venture Company.",al={"winterhoof-brunnens läge","var ligger winterhoof-brunnen","hur hittar man winterhoof-brunnen"}},{q="Varför förgiftades brunnen?",a="Venture Company upprättade gruvdrift och utgrävningar i närheten, vilket gjorde att giftigt industriellt avfall och skräp kunde sippra direkt ner i grundvattenmagasinet. Därmed blev den naturliga källan odrickbar för det lokala djurlivet och taurenfolket.",al={"vem förgiftade vattnet","varför är brunnen smutsig","venture company-brunnen"}},{q="Vem är Mull Thunderhorn?",a="Mull Thunderhorn är en andlig äldste som håller till i Bloodhoof Village. Han är djupt lyhörd för jordens hälsa och tillverkar ceremoniella totemer för att råda bot på den miljöförstörelse som utomstående inkräktare orsakat.",al={"vem är mull","mull thunderhorns roll"}},{q="Vad händer efter att brunnen har renats?",a="När Winterhoof Water Well åter rinner klart och djurlivet börjar dricka säkert ur den leder Mull Thunderhorn din uppmärksamhet mot andra skadade brunnar i Mulgore, med början vid Thunderhorn Totem.",al={"what comes next","efter winterhoof cleansing","vad gör mull härnäst"}},{q="Vilka vaktar brunnen?",a="Brunnen är ockuperad av arbetare och lejda män som anställts av Venture Company, ett samvetslöst syndikat lett av gobliner som utarmar landområden på naturresurser utan hänsyn till det lokala ekosystemet.",al={"vem vaktar winterhoof-brunnen","vilka fiender finns vid brunnen"}},{q="Hur fungerar reningstotemen?",a="Totemen är snidad enligt taurenfolkets heliga riter och skyddsritualer. Den åkallar naturandar och Jordmoderns välsignelser för att rena källflödet från onaturliga kemiska föroreningar.",al={"reningstotemens historia","hur fungerar mulls totem"}}},fx={["16ee77f0"]={q="Varför vill Mull Thunderhorn att Winterhoof Water Well renas?",a="Winterhoof Water Well är avgörande för Mulgore och dess överlevnad. Vattnet har förorenats och hotar både det lokala djurlivet och stammarna som är beroende av det. Mull Thunderhorn har förberett en vigd reningstotem, men dess kraft måste föras direkt till platsen för att läka vattnet och återställa harmonin i landet.",al={"varför rena winterhoof well","mull thunderhorns motiv","varför rena vattnet i winterhoof"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Service to the Horde",s="Det juvelprydda hänget finns nu hos Zor Lonetree i Orgrimmar. Du lämnade det efter Report to Zor, och Zor har mer att säga dig.",h="Det juvelprydda hänget finns nu hos Zor Lonetree i Orgrimmar.",kw={"dustwallow marsh","hänge","report to zor","tjänst åt horden","zor lonetree"},sec={{t="Zor Lonetree i Orgrimmar",b="Du bar det juvelprydda hänget till Zor Lonetree i Orgrimmar, och nu finns hänget hos Zor. Återvänd till Zor Lonetree för att få höra mer om vad du har gjort för Horden."},{t="Zors sista ord",b="Zor säger att lärda behöver tid för att studera hänget. Som tack för din tjänst åt Horden erbjuder Zor en liten gåva och säger att det du har gjort hedrar både dig och Horden."}},faq={{q="Vem har hänget nu?",a="Zor Lonetree i Orgrimmar, efter att du bar det dit från Nazeer Bloodpike i Brackenwall Village.",al={"vem tar hänget","vem ger det här uppdraget","zor lonetrees roll"}},{q="Vilket uppdrag kommer före det här?",a="Det följer på Report to Zor, där du tog det juvelprydda hänget till Zor Lonetree.",al={"vilket uppdrag kom före","förutsättning för tjänst åt horden","föregående uppdrag"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Rites of the Earthmother",s="Rites of the Earthmother inleder en initiands andliga resa på Red Cloud Mesa. Under Chief Hawkwinds ledning söker resenärer upp Seer Graytongue i de södra kullarna vid Camp Narache. Att genomgå dessa vördnadsvärda ceremonier ses som ett avgörande mandomsprov för tauren som nått vuxen ålder.",h="Rites of the Earthmother inleder en initiands andliga resa på Red Cloud Mesa.",kw={"camp narache","chief hawkwind","jordmodern","red cloud mesa","rites of the earthmother","seer graytongue","tauren"},ang={["class:Druid"]="Druidkandidater inleder sin väg mot harmoni med naturen genom att respektera stammens äldstes och siarnas heliga vägledning.",["class:Shaman"]="För blivande schamaner är riter välsignade av stammens siare ett viktigt första steg mot gemenskap med elementen och andarna i Mulgore.",["faction:Horde"]="En förståelse för dessa heliga prövningar ger inblick i den andliga kärnan hos taurenfolkets allierade, som nyligen anslutit sig till Horde.",["race:Tauren"]="Rites of the Earthmother utgör den grundläggande andliga resan för unga tauren och prövar om de är redo att tjäna sin stam och vörda Jordmodern."},sec={{t="Prövningarnas tröskel",b="På Red Cloud Mesa vägleder Chief Hawkwind unga tauren som vill bevisa sig inför Seer Graytongue. Graytongue bor i de stilla kullarna strax söder om Camp Narache och vakar över ungdomarnas andliga början. Den enkla färden markerar den formella tröskeln mellan lägerlivets vardag och de allvarliga åtaganden som stamtraditionen kräver."},{t="Att omfamna Jordmodern",b="Jordmodern står i centrum för taurenfolkets skapelseberättelse och vardagsliv. Hennes riter är heliga prövningar av mognad, uthållighet och andligt djup. Som Seer Graytongue varnar alla som kommer till hans helgedom är det ingen lätt uppgift att inleda Rites of the Earthmother; det kräver fullständig hängivenhet åt mesans traditioner."}},faq={{q="Vem ger uppdraget Rites of the Earthmother?",a="Uppdraget inleds av Chief Hawkwind i Camp Narache, som skickar unga äventyrare till Seer Graytongue i de omgivande kullarna.",al={"vem inleder rites of the earthmother","uppdragsgivare"}},{q="Var hittar jag Seer Graytongue?",a="Seer Graytongue bor i kullarna strax söder om Camp Narache på Red Cloud Mesa i Mulgore.",al={"var finns seer graytongue","graytongues plats","hitta graytongue"}},{q="Vad är Rites of the Earthmother?",a="Rites of the Earthmother är traditionella, heliga övergångsriter som unga tauren genomgår för att visa sin vishet, styrka och hängivenhet till sitt folk och dess tro.",al={"vad är rites of the earthmother","berättelsen om jordmoderns prövningar"}},{q="Vem är Seer Graytongue?",a="Seer Graytongue är en respekterad andlig äldste som bor söder om Camp Narache och vakar över samt vägleder initiander genom Jordmoderns heliga prövningar.",al={"vem är seer graytongue","graytongues roll"}},{q="Vem är Chief Hawkwind?",a="Chief Hawkwind är stamledaren som styr Camp Narache på Red Cloud Mesa. Hans uppgift är att förbereda unga tauren innan han skickar dem till siarna.",al={"vem är chief hawkwind","hawkwinds roll"}},{q="Vad krävs för att slutföra uppgiften?",a="Du behöver bara färdas söderut från Camp Narache in i kullarna och tala med Seer Graytongue för att meddela att du är redo för prövningarna.",al={"vad behöver jag göra","hur slutför jag uppdraget"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Thunderhorn Totem",s="Thunderhorn Totem är en uppgift från Mull Thunderhorn i Bloodhoof Village om att tillverka en helig reningstotem. För att bekämpa föroreningarna som gobliner sprider i Mulgore genom vattenkällorna måste unga hjältar i Horde samla naturliga klor från rovdjur på slätterna. På så vis binds landets urkraft till rituellt trä.",h="Thunderhorn Totem är en uppgift från Mull Thunderhorn i Bloodhoof Village om att tillverka en helig...",kw={"bloodhoof village","rening","cougar claws","flatland cougar","mulgore","mull thunderhorn","prairie stalker","stalker claws","thunderhorn totem","vattenkälla"},ang={["class:Hunter"]="För att samla klorna måste du förstå slätternas inhemska smygjägare och hedra bytet för att bevara ekosystemet.",["class:Shaman"]="Totemisk återställning bygger på att åkalla landets levande andar för att rena vatten som förorenats av onaturlig och vårdslös verksamhet.",["race:Tauren"]="Att försvara Mulgore's grundvatten från utländsk exploatering är en helig plikt för stammen. Den följer Jordmoderns uppmaning att leva i balans i stället för att plundra."},sec={{t="Jakten på slätternas rovdjur",b="När Venture Companys industriella exploatering förgiftar Mulgore's dyrbara vattenkällor arbetar Mull Thunderhorn skyndsamt med att skapa botemedel. Thunderhorn Cleansing Totem kräver naturliga essenser från slätternas mest fokuserade jägare: prairie stalkers och flatland cougars. När du tar klorna från dessa rovdjur som strövar öster och väster om Bloodhoof Village, leder ritualen vilddjurens råa, oförstörda jaktkraft direkt in i totemen."},{t="Jaktens natur",b="Tauren-traditionen ser en djup skillnad mellan jakt för försörjning eller andlig balans och goblinernas hänsynslösa plundring. Mull betonar att den renhet med vilken inhemska rovdjur jagar är avgörande för att rena förorenad jord. Där goblinernas maskiner förorenar källorna med olja och industriavfall ger djurens naturliga styrka, när de kämpar med landet, den andliga kraft som behövs för att återställa Thunderhorn Water Well."}},faq={{q="Varför behöver Mull Thunderhorn klor från rovdjur?",a="Mull använder klorna från prairie stalkers och flatland cougars för att leda slätternas rena, ursprungliga rovdjursande in i en reningstotem. Han tror att de naturliga jägarnas rena ande motverkar konstgjord, industriell förorening.",al={"varför klor","syftet med stalker claws","syftet med cougar claws"}},{q="Vem förorenar vattnet i Mulgore?",a="Goblinerna från Venture Company som verkar i Mulgore förorenar marken och vattnet. Deras hänsynslösa utvinning av resurser och gruvriggar leder giftigt slam in i grundvattnet som försörjer stammarnas brunnar.",al={"vem förgiftade brunnen","varför är brunnen förgiftad","vad förgiftade mulgore"}},{q="Var finns prairie stalkers och flatland cougars?",a="Båda djurarterna strövar på de öppna slätterna i centrala Mulgore, främst utspridda över de böljande savannerna direkt öster och väster om Bloodhoof Village.",al={"stalker-plats","var hittar man cougars","platser för cougar claws"}},{q="Vad händer när Thunderhorn Totem har tillverkats?",a="När Mull har snidat och förtrollat totemen med hjälp av klorna skickar han dig direkt till den förgiftade Thunderhorn Water Well för att utföra reningsritualen och driva bort giftet.",al={"vad händer härnäst","efter thunderhorn totem","fortsättning på totemuppdraget"}},{q="Hur hänger detta samman med den tidigare reningen vid Winterhoof Well?",a="Det här ingår i stammarnas pågående arbete med att bevara Mulgore's heliga vatten. Winterhoof Water Well renades först, och nu hotar föroreningen brunnen Thunderhorn längre norrut.",al={"kopplingen till winterhoof","föregående totemuppdrag"}},{q="Varför använder tauren inte bara örtmedel i stället för djurklor?",a="Taurenernas rituella hantverk hämtar kraft från naturens olika elementära och fysiska aspekter. Toppredatorernas skarpa renhet ger en aktiv, kämpande andlig kraft som särskilt behövs för att skära igenom goblinernas aggressiva industrigifter.",al={"varför inte örter","material till shamanistiska totemer"}}},fx={cb047e40={q="Varför vill Mull Thunderhorn att det här blir gjort?",a="Vattnet i Thunderhorn Water Well blir allt mer förorenat för varje timme som går, förgiftat av vårdslösa goblinverksamheter i närheten. Mull Thunderhorn måste skapa en helig reningstotem för att rena brunnen innan föroreningen sprider sig vidare genom jorden och skadar hans folk.",al={"varför vill mull ha det här","mull thunderhorns motiv","varför tillverka thunderhorn totem"}},["43953f1d"]={q="Vilka ska du jaga efter klorna?",a="Du ska jaga de vilda rovdjur som stryker omkring på Mulgore-slätterna: präriesmygare och slättpumor. De strövar naturligt omkring öster och väster om Bloodhoof Village och lever och jagar som en del av landets naturliga balans.",al={"vad ska jag jaga","vilka är målen","byten för thunderhorn totem"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Rite of Strength",s="Kraftprovet är det första provet i Jordmoderns traditionella riter, som unga tauren genomgår i Camp Narache. För att visa sitt mod och försvara stammen måste de unga tauren driva bort Bristleback-kvillyborrar som tränger in i Brambleblade Ravine och lämna sina bälten till Chief Hawkwind.",h="Kraftprovet är det första provet i Jordmoderns traditionella riter, som unga tauren genomgår i Camp Narache.",kw={"brambleblade ravine","bristleback","camp narache","chief hawkwind","jordmodern","mulgore","kvillyborre","kraftprov","seer graytongue"},ang={["faction:Horde"]="Genom att försvara platån säkras ett av Horde viktigaste rekryteringsområden, så att unga krigare och schamaner tryggt kan växa upp och hjälpa den nya alliansen.",["race:Tauren"]="Varje ung tauren börjar sin färd genom dessa urgamla riter och visar sig redo att skydda sitt folk mot hotet från kvillyborrarna innan hen lämnar Red Cloud Mesa."},sec={{t="Det första provet",b="För en ung tauren som vill vinna stamäldstarnas erkännande och så småningom bli accepterad i Thunder Bluff är det en viktig plikt att genomföra Jordmoderns riter. Seer Graytongue utdelar Kraftprovet som det första provet. Det kräver fysiskt mod och beslutsamt handlande för att försvara Red Cloud Mesa, och prövar om en ung tauren kan möta stammens dödsfiender utan att vackla."},{t="Hotet från Bristleback",b="Provet utspelar sig i Brambleblade Ravine, en taggig ravin öster om Camp Narache där Bristleback-kvillyborrar håller till. Dessa aggressiva inkräktare tränger ständigt in på stammens förfäders marker, överfaller jaktlag och plundrar lägrets förråd i skydd av mörkret. Att döda dem och ta deras bälten visar både tapperhet och att bosättningen kan hållas trygg."}},faq={{q="Vad är syftet med Kraftprovet?",a="Det är det första steget i Jordmoderns riter och ska pröva en ung taurenes mod i strid. Genom att undanröja hot mot lägret förtjänar den unga tauren rätten att gå vidare mot verklig respekt i Thunder Bluff.",al={"varför göra kraftprovet","kraftprovets historia","syftet med kraftprovet"}},{q="Vem tilldelar och bedömer provet?",a="Seer Graytongue ger den unga tauren uppdraget och förklarar provets andliga och praktiska krav. När tolv Bristleback-bälten har samlats in ska beviset på tapperhet lämnas direkt till Chief Hawkwind i Camp Narache.",al={"vem ger kraftprovet","vem lämnar in kraftprovet"}},{q="Var ligger Brambleblade Ravine?",a="Brambleblade Ravine ligger öster om Camp Narache på Red Cloud Mesa. Det är en taggig ravin som vimlar av fientliga Bristleback-kvillyborrar.",al={"var ligger brambleblade ravine","brambleblades läge"}},{q="Varför angrips Bristleback?",a="Bristleback tränger in på stammens förfäders jaktmarker. De överfaller gång på gång taurenjägare och stjäl förnödenheter från Camp Narache i mörkret, vilket gör dem till stammens direkta fiender.",al={"varför döda bristleback","vad gjorde kvillyborrarna"}},{q="Varför samla bälten i stället för andra troféer?",a="Bälten är konkreta bevis på besegrade krigare. De visar att den unga tauren mötte kvillyborrarna på nära håll och besegrade vuxna stridskämpar, i stället för att bara leta efter saker på avstånd.",al={"varför bristleback-bälten","varför bälten"}},{q="Vad händer när Kraftprovet är avklarat?",a="Att klara Kraftprovet bevisar den unga taurens tapperhet och gör att hen kan gå vidare till Jordmoderns följande prov. Därmed fortsätter den formella vägen mot vuxenlivet och en andlig ställning inom stammen.",al={"vad händer efter kraftprovet","nästa jordmodersrit"}}},fx={f38315d5={q="Varför skickar Seer Graytongue dig till Bristlebacks?",a="Seer Graytongue vägleder ungdomarna i Camp Narache genom Earthmothers heliga riter. I ditt första prov måste han pröva din kampvilja mot ett verkligt och överhängande hot mot stammen. Bristleback-kvilloarna tränger in på taurenmark, överfaller jägare och stjäl i skydd av mörkret. Genom att skicka dig att möta dem ser Graytongue till att du skyddar ditt folk, bevisar din styrka och vinner stammens respekt.",al={"varför vill graytongue ha det här","seer graytongues motiv","varför rite of strength"}},e0dd8e68={q="Varför skickas du ensam för att klara det här provet?",a="Rite of Strength är en personlig övergångsrit, inte en enkel lägersyssla. Medan lägrets krigare bevakar området måste varje ung tauren på egen hand visa mod och stridsförmåga innan hen erkänns som vuxen i Thunder Bluff. Provet kräver att du själv möter ditt folks fiender, så att de äldste vet att du kan försvara stammen när det behövs.",al={"varför jag ska klara rite of strength","varför inte skicka vakter mot bristlebacks","varför måste jag slåss mot bristlebacks"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="Thunderhorn Cleansing",s="Thunderhorn Cleansing är en viktig andlig ritual i Mulgore. Den ger resenärer i uppdrag att rena den förorenade Thunderhorn Water Well. Med en rituell totem från Mull Thunderhorn återställer äventyrare källan som är livsviktig för den lokala stammen. En lyckad rening får Thunderhorn-förfädernas innerliga uppskattning.",h="Thunderhorn Cleansing är en viktig andlig ritual i Mulgore.",kw={"förfädernas andar","bloodhoof village","reningstotem","jordmodern","mulgore","mull thunderhorn","thunderhorn cleansing","thunderhorn water well"},ang={["class:Druid"]="När förgiftat vatten renas hejdas fördärvets spridning genom Mulgore ekosystem, och slätternas naturliga harmoni bevaras.",["class:Shaman"]="Att kanalisera förfädernas kraft genom totemer för att läka förorenade källor är själva grunden för schamanens kall.",["faction:Horde"]="När du hjälper taurenfolket att skydda sina heliga källor stärks banden mellan den unga Horden och dess stolta Shu'halo-allierade.",["race:Tauren"]="När du återställer de heliga källorna hedrar du Jordmodern och skyddar ditt folk medan de bygger ett varaktigt och fredligt hem i Mulgore."},sec={{t="En förgiftad livsnerv",b="Brunnar över Mulgore slättland är livsviktiga för taurenfolkets nomadstammar, som nyligen slagit sig ned på gräsmarkerna. När giftiga ämnen förorenar dessa underjordiska källor drabbas både djurlivet och närliggande bosättningar hårt. Thunderhorn Water Well ligger norr om Bloodhoof Village och har förorenats. För att läka det sargade landet krävs ett målmedvetet andligt ingripande."},{t="Förfädernas rening",b="För att motverka fördärvet tillverkar Mull Thunderhorn en helgad Cleansing Totem, laddad med andlig kraft. När äventyrare bär reliken till det förgiftade vattnet kan de leda förfädernas kraft in i källan, skingra gifterna och återställa naturens rena balans. Mull får direkt bekräftelse på att uppdraget lyckats när Thunderhorn-förfädernas andar besöker honom i en dröm och uttrycker sin bestående tacksamhet."}},faq={{q="Var ligger Thunderhorn Water Well?",a="Thunderhorn Water Well ligger på slätterna norr om Bloodhoof Village i Mulgore. Den är en av flera viktiga vattenkällor för de lokala taurenklanerna.",al={"thunderhorn-brunnens plats","var ligger brunnen","var använder jag totemen"}},{q="Vem inleder reningsritualen?",a="Mull Thunderhorn inleder ritualen. Han finns i Bloodhoof Village, där han tillverkar särskilda totemer för att läka Mulgore och dess sargade miljö.",al={"vem ger uppdraget","mull thunderhorns plats","uppdragsgivare"}},{q="Varför måste brunnarna i Mulgore renas?",a="Brunnarna i Mulgore har förgiftats och fördärvats på onaturlig väg. Det hotar slätternas sköra balans och överlevnaden för taurenstammarna som är beroende av rent vatten.",al={"varför rena brunnarna","vad hände med vattnet","varför är brunnen förgiftad"}},{q="Hur vet Mull att ritualen lyckades?",a="När ritualen vid brunnen är fullbordad visar sig Thunderhorn-klanens förfäders andar direkt för Mull i en dröm. De prisar äventyrarens insats och framför sitt tack från förfäderna.",al={"förfädernas dröm","hur mull får veta","resultat efter brunnens rening"}},{q="Vad händer efter att Thunderhorn-brunnen renats?",a="Att rena Thunderhorn-brunnen är en del av en större insats för att skydda Mulgore källor. Därefter skickar Mull resenärer vidare för att hjälpa en annan utsatt region genom att tillverka Wildmane Totem.",al={"vad händer sedan","nästa uppdrag efter thunderhorn","nästa wildmane totem"}},{q="Vad är Thunderhorn Cleansing Totem?",a="Thunderhorn Cleansing Totem är ett rituellt snidat andligt redskap som Mull Thunderhorn har tillverkat särskilt för att rena den förorenade brunnen som tillhör hans klan och förfäder.",al={"reningstotem","vad är totemföremålet","mulls totem"}}},fx={da3030fe={q="Varför behöver Mull Thunderhorn att du renar brunnen?",a="Mull Thunderhorn har tillverkat ritualens fokus, men att rena helig mark är en tjänste- och hedersrit för blivande mästare bland tauren och deras allierade. När du själv bär Thunderhorn Cleansing Totem till den förorenade brunnen visar du din hängivenhet till Earthmother och din klans förfädersandar. Då vinner du gunst och vägledning från förfäderna som vakar över vattnet.",al={"varför jag för mull thunderhorn","varför skickar mull dig","varför utföra reningsritualen"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Wildmane Totem",s="Wildmane Totem är det tredje och sista steget i Mull Thunderhorns arbete med att skapa renande totem för Mulgore förgiftade brunnar. För att återställa Wildmane Well kräver ritualen offer från de mest vildsinta rovdjuren i området: alfavargar på prärien.",h="Wildmane Totem är det tredje och sista steget i Mull Thunderhorns arbete med att skapa renande totem för...",kw={"bloodhoof village","mulgore","mull thunderhorn","alfavarg på prärien","thunder bluff","totem","vattenbrunn","wildmane"},ang={["class:Hunter"]="Att spåra upp de listiga alfavargarna kring de höga klipporna prövar en jägares respekt för vildmarken och dess farligaste rovdjur.",["class:Shaman"]="Schamaner uppskattar de varsamma riter som krävs för att harmonisera rovdjurstotem med elementärt vatten och rena bort giftiga plågor.",["race:Tauren"]="Reningen av förfädernas brunnar understryker taurenfolkets skyldighet att återställa den ekologiska balansen och hedra de offer som Jordmodern kräver."},sec={{t="Den sista brunnen",b="När materialen för att helga brunnarna Winterhoof och Thunderhorn har säkrats återstår bara en förorenad källa i centrala Mulgore: Wildmane Well. Det förgiftade vattnet över slätterna hotar både flyttande djurliv och bosättningar, och därför krävs kraftfulla ursprungsingredienser för att återställa jordens naturliga balans."},{t="Rovdjurets styrka",b="För att motverka den starka fördärvskorruptionen som dröjer kvar i vattnet i norr behöver Mull Thunderhorn ett offer präglat av vildsinthet. Alfavargar på prärien strövar över gräsmarkerna, särskilt kring de höga klipporna nedanför Thunder Bluff. När du tar deras tänder kanaliseras Mulgore främsta jägares obevekliga drivkraft och motståndskraft direkt in i det renande totemet."},{t="Offer och balans",b="I taurenfolkets andliga tradition har det emotionell och elementär tyngd att ta hjälp av landets varelser. Mull ser insamlingen av alfavargtänder inte som en erövring, utan som en dyster nödvändighet där Mulgore rovdjur offras för att hela Jordmoderns sargade vatten."}},faq={{q="Vad behövs Wildmane Totem till?",a="Mull Thunderhorn skapar totemet för att rena Wildmane Well, den sista förorenade vattenkällan som hotar taurenfolket i Mulgore.",al={"varför skapa wildmane totem","wildmane totem syfte"}},{q="Varför behövs just alfavargtänder?",a="För att rena den djupa föroreningen i Wildmane Well måste man kanalisera ett topprovdjurs vilda, obevekliga styrka. Tänderna från flockens ledare ger den nödvändiga ursprungskraften.",al={"varför vargtänder","syftet med alfavargtänder"}},{q="Var finns alfavargar på prärien i Mulgore?",a="Alfavargar på prärien strövar på de norra slätterna i Mulgore. De håller ofta till på gräsmarkerna kring foten av Thunder Bluff.",al={"alfavarg på prärien plats","var hittar man alfavargar på prärien"}},{q="Vem skapar totemet?",a="Mull Thunderhorn, en andlig äldste som håller till i Bloodhoof Village, skapar varje renande totem efter att en novis har samlat in de nödvändiga offergåvorna.",al={"vem skapar totemet","totem uppdragsgivare"}},{q="Vad händer när Wildmane Totem har skapats?",a="När Mull Thunderhorn har satt ihop totemet av alfavargtänder skickas du norrut med det för att utföra själva reningen vid Wildmane Well.",al={"what comes next","nästa uppdrag efter wildmane totem"}},{q="Hur speglar ritualen taurenfolkets tro?",a="Taurenfolket ser det som ett högtidligt utbyte med naturen att ta ett djurs liv. Mull erkänner vargarnas offer med både sorg över deras död och stolthet över deras roll i att hela jorden.",al={"taurenfolkets totemfilosofi","mull thunderhorns tro"}}},fx={["054e923c"]={q="Varför vill Mull Thunderhorn att Wildmane Totem tillverkas?",a="Bara en förorenad vattenkälla återstår att rena i Mulgore, den som tillhör Wildmane-klanen. Mull Thunderhorn har vigt sig åt att rena jordens heliga källor, och att tillverka den sista reningstotemen med hjälp av landets rovdjursande är nödvändigt för att fullborda den heliga riten och återställa rent vatten åt stammen.",al={"varför vill mull ha wildmane totem","mull thunderhorns motiv","varför tillverka wildmane totem"}},["2aa23a29"]={q="Vad används Prairie Alpha Tooth till?",a="Prärievargalphans tänder står för offer och den vilda livskraften hos Mulgore-slätternas främsta rovdjur. Mull Thunderhorn binder åtta av dessa huggtänder i Wildmane Totem, så att dess ande kan blidka naturens ordning och stärka ritualen som krävs för att rena vattnet i Wildmane Water Well.",al={"vad prairie alpha tooth används till","vad prärievargalphans tänder används till","tänder till wildmane totem"}},eb5f4bd0={q="Varför jagar du prärievargalfor?",a="Du ska jaga prärievargalfor, de dominerande flockledarna som strövar på slätterna runt foten av Thunder Bluff. Deras styrka och vildhet förkroppsligar slätternas naturliga balans och ger Mull Thunderhorn den kraftfulla essens han behöver för den sista vattenreningsritualen.",al={"varför döda prärievargalfor","mål: prärievargalfa","vem ska du jaga"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="The Jasperlode Mine",s="Kobolder har tagit över Jasperlode Mine i östra Elwynn. Marshal Dughan skickar ut spejare för att ta reda på hur långt angreppet har spridit sig.",h="Kobolder har tagit över Jasperlode Mine i östra Elwynn.",kw={"azora","dughan","elwynn","fargodeep","goldshire","jasperlode","kobold","gruva","spejare"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur sårbara Stormwinds hemtrakter har blivit utan centralt kungligt stöd, nu när både Fargodeep och Jasperlode har gått förlorade.",["profession:Mining"]="Som gruvarbetare ser du värdefulla fyndigheter i Jasperlodes tunnlar, men kobolder som tagit området står mellan dig och malmen.",["race:Human"]="Som människa ser du hur Elwynns landsbygdsinfrastruktur sviktar när gränsområdenas resurser försvinner nära huvudstaden."},sec={{t="Ett andra intrång",b="Efter att kobolder svärmade in i Fargodeep-tunnlarna söder om Goldshire befarade Marshal Dughan att de nått andra gruvor. Jasperlode ligger i de klippiga utlöparna nordost om Tower of Azora och förser kungariket med råsten och metall. Dughan kan inte avvara Stormwinds vakter från patrullerna i staden, så han skickar självständiga äventyrare österut för att undersöka om kobolderna även tagit den här gruvan."},{t="Överansträngt försvar",b="Spejare som når Jasperlodes kamrar upptäcker att kobolder har drivit bort de mänskliga gruvarbetarna och befäst de mörka gångarna. Marshal Dughan drabbas av ännu ett bakslag medan krisen växer. Kung Varian Wrynn är försvunnen, och kungliga trupper hålls borta från avlägsna områden. Den lokala garnisonen har för få soldater för att rensa gruvorna, vilket gör att kungarikets hjärta får brist på mineraler och omringas av hot."}},faq={{q="Var ligger Jasperlode Mine?",a="Jasperlode Mine ligger i de norra utlöparna i östra Elwynn Forest. Färdas österut från Goldshire längs huvudvägen, passera Tower of Azora och fortsätt sedan norrut upp i kullarna.",al={"var ligger jasperlode","jasperlode mines läge","hitta jasperlode"}},{q="Varför behöver Marshal Dughan en spejare i stället för att skicka vakter?",a="Marshal Dughan har för få vakter att avvara. Kung Varian Wrynn är försvunnen, och det politiska dödläget i huvudstaden har gjort att de lokala styrkorna är hårt ansträngda när de skyddar gårdar och städer mot banditer och gnoller. Därför förlitar sig Dughan på civila spejare.",al={"varför skicka äventyrare","varför inga vakter från stormwind","var är vakterna"}},{q="Varför tar kobolder över Elwynns gruvor?",a="Kobolder gräver tunnlar mot mineralådror och fuktiga grottor. När Stormwinds militära närvaro minskade blev de djärvare och trängde in i mänskliga gruvor som Fargodeep och Jasperlode för att lägga beslag på guld, malm och territorium.",al={"varför kobolder i jasperlode","vad vill kobolderna ha","orsak till koboldangreppet"}},{q="Vad händer efter att man har spejat i Jasperlode Mine?",a="När du rapporterar att Jasperlode har fallit står Marshal Dughan inför förlusten av gruvor i öster och hot från flera håll. Han riktar uppmärksamheten mot västra Elwynn, där Riverpaw-gnoller sätter Westbrook Garrison under hård press.",al={"vad händer efter jasperlode","uppföljning efter jasperlode"}},{q="Varför är förlusten av Jasperlode Mine betydelsefull för Stormwind?",a="Elwynns gruvor förser Stormwind med malmen och stenen som staden behöver för sin ekonomi och för att smida vapen och rustningar. Förlusten av Fargodeep och Jasperlode stoppar mineralutvinningen och försvagar kungarikets återhämtning.",al={"varför jasperlode är viktigt","jasperlodes betydelse"}},{q="Vem äger Tower of Azora i närheten?",a="Tower of Azora är ett litet magikertorn längs den östra vägen genom Elwynn Forest. Theocritus, Azoras ärkemagiker, råder där, och Azoras tjänare sköter tornet. Resenärer använder det som landmärke på vägen till de östra utlöparna.",al={"vad är tower of azora","vem bor i azoras torn"}}},fx={a973508b={q="Varför vill Marshal Dughan att Jasperlode Mine undersöks?",a="Marshal Dughan har redan bekräftat att kobolder har tagit över Fargodeep Mine och fruktar att angreppet inte är en isolerad händelse. Han behöver veta om hotet också har spridit sig österut till Jasperlode Mine. Att säkra Elwynns resurser och förstå hela omfattningen av det växande hotet är avgörande för att försvara Goldshire och skydda Stormwinds viktiga handelsvägar.",al={"dughans motiv för jasperlode","varför undersöka jasperlode","varför behöver dughan få jasperlode undersökt"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmane Cleansing",s="Wildmane Cleansing markerar höjdpunkten i taurenfolkets ritualer för att rena Mulgore livsviktiga vattenhål. På uppdrag av Mull Thunderhorn i Bloodhoof Village tar hjältar den färdiga Wildmane Cleansing Totem norrut för att rena den sista förgiftade brunnen. När de driver tillbaka goblinernas föroreningar återställs balansen på slätterna och taurenstammarnas pastorala försörjning tryggas.",h="Wildmane Cleansing markerar höjdpunkten i taurenfolkets ritualer för att rena Mulgore livsviktiga vattenhål.",kw={"bloodhoof village","rening","jordmodern","mulgore","mull thunderhorn","totem","venture company","vattenbrunn","wildmane"},ang={["class:Druid"]="Att återställa naturen efter goblinernas miljöförstörelse speglar direkt Cenarionordens uppdrag att läka skadade ekosystem och skydda grönskande betesmarker.",["class:Shaman"]="Att använda rituella totemer för att motverka mekaniska föroreningar visar shamanens plikt att upprätthålla harmoni mellan naturens element och levande samhällen.",["race:Tauren"]="Att återställa Mulgore tre förfädersbrunnar är en grundläggande övergångsrit som bevisar en ung krigares hängivenhet till att bevara Jordmoderns gåvor."},sec={{t="Att rena Jordmoderns gåva",b="Vattnet är heligt livsblod över Mulgore solbelysta slätter och uppehåller hjordarna, jorden och de nomadiska stammar som nyligen samlats kring Thunder Bluff. När Venture Company och gobliner som trängde in i området började förorena dessa grundvattenkällor med giftigt industriavfall insåg taurenäldste att ett existentiellt hot hade uppstått. Efter reningen av Winterhoof Water Well och Thunderhorn Water Well återstår Wildmane Water Well som den tredje och sista förorenade platsen som kräver andlig hjälp."},{t="Wildmane Totem",b="Wildmane Cleansing Totem har tillverkats av särskilda beståndsdelar som samlats in i regionen och kanaliserar förfädernas andars och jordelementets återställande kraft. När totemen planteras intill det stinkande vattnet norr om Thunder Bluff skingras de giftiga kemikalierna, toxinerna drivs ut och det naturliga flödet återupplivas. Genom att fullborda ritualen skyddar tauren sitt folk från sjukdom och sänder ett tydligt budskap om att de inte tolererar skändningen av sin heliga mark."}},faq={{q="Varför förgiftades Wildmane Water Well?",a="Goblinernas verksamhet, driven av industriell girighet och skogsavverkning, förde in gift och kemiskt avfall i Mulgore underjordiska vatten och hotade både det lokala djurlivet och stammarnas bosättningar.",al={"vem förgiftade brunnen","varför är brunnen smutsig","goblingift"}},{q="Var ligger Wildmane Water Well?",a="Wildmane Water Well ligger på slätterna, rakt norr om Thunder Bluffs väldiga mesas.",al={"wildmane-brunnens plats","var ligger wildmane-brunnen","hitta wildmane-brunnen"}},{q="Vem inleder denna reningsritual?",a="Mull Thunderhorn, en äldste i Bloodhoof Village, vägleder dig när du skapar totemerna och skickar dig att rena brunnarna.",al={"vem ger uppdraget wildmane cleansing","uppdragsgivare","mull thunderhorns plats"}},{q="Vilka andra brunnar ingår i reningsarbetet?",a="Wildmane Water Well är den tredje av tre livsviktiga vattenkällor. Söderut ligger först Winterhoof Water Well och sedan Thunderhorn Water Well.",al={"andra brunnar","brunnar i mulgore","winterhoof- och thunderhorn-brunnarna"}},{q="Hur fungerar reningstotemen?",a="Totemen är fylld med förfädernas magi och renade naturämnen och kanaliserar återställande andlig energi ner i grundvattnet för att neutralisera goblinernas föroreningar.",al={"hur reningstotemen fungerar","hur renar totemen vattnet"}},{q="Vad innebär det för Bloodhoof Village att ritualen fullbordas?",a="När de tre brunnarna renas får alla stammar i centrala Mulgore garanterat säkert dricksvatten, och tauren hedrar sin heliga plikt att läka Jordmodern efter industriell exploatering.",al={"uppdragets resultat","varför rena brunnarna","taurenfolkets historia och betydelse"}}},fx={["119d5a48"]={q="Varför vill Mull Thunderhorn att Wildmane Well renas?",a="Mull Thunderhorn vakar över Mulgore och dess andliga balans och livsviktiga resurser. Venture Companys smutsiga verksamhet förgiftade landets värdefulla vattenkällor och hotar stammarnas och deras hjordars överlevnad. Wildmane Well är den sista av de tre uråldriga källorna som fortfarande är förorenad, och att rena den är avgörande för att hela Earth Mother och säkra dricksvatten åt Bloodhoof Village och Thunder Bluff.",al={"mull thunderhorns motiv","varför rena wildmane well","varför bryr sig mull om källorna"}},b4cee6a1={q="Vad är Wildmane Cleansing Totem?",a="Wildmane Cleansing Totem är ett rituellt förberett föremål som Mull Thunderhorn har tillverkat för att kanalisera förfädernas andar och jordandar. När det aktiveras vid den förorenade Wildmane Water Well norr om Thunder Bluff stöter totemen bort det giftiga slammet som goblinernas föroreningar lämnat efter sig. Då renas grundvattnet och källan återfår sitt naturliga, orörda tillstånd.",al={"använda wildmane cleansing totem","vad är wildmane totem","syftet med reningstotemen"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="Swoop Hunting",s="Swoop Hunting är en jakttradition där spårning och skytte sätts på prov, och den erbjuds av Harken Windtotem i Bloodhoof Village. För att visa sin list och sitt tålamod utmanas jägare och resenärer att smyga sig på de skygga fåglarna över Mulgore. Att återvända med oskadade troféfjädrar visar både hängivenhet till jakten och respekt för Jordmoderns naturliga prövningar.",h="Swoop Hunting är en jakttradition där spårning och skytte sätts på prov, och den erbjuds av Harken Windtotem...",kw={"bloodhoof village","harken windtotem","mulgore","swoop-fågel","swoop-jakt","taurenprövning","trophy swoop quill"},ang={["class:Druid"]="När druider spårar swoop-fåglar över vindpinade platåer kommer de närmare rovfåglarna som upprätthåller balansen på Mulgore himmel.",["class:Hunter"]="Jakten ger en tidig mästarklass i att leda luftburet byte, bedöma beteendemönster och utföra precisa angrepp mot vaksamma rovdjur.",["race:Tauren"]="För unga tauren och vandrare är jakten på Mulgore snabba swoop-fåglar en vördad övergångsrit som vässar spårningsinstinkterna och upprätthåller förfädernas jakttraditioner."},sec={{t="Ett prov för skarpa ögon",b="Mulgore grässtäpper myllrar av bestar, men få prövar en förföljares instinkter som de inhemska swoop-fåglarna. Dessa stora rovfåglar smälter sömlöst in mot himlen och slätterna, kretsar ovanför eller flyger lågt över det höga gräset. Till skillnad från långsamma plainstriders eller betande kodo kräver swoop-fåglar skärpt fokus och snabba fötter för att hinnas ikapp. Därför är jakten en traditionell prövning för unga jägare som vill vinna anseende bland stammarna."},{t="Jaktens kännetecken",b="För Harken Windtotem handlar insamlingen av troféfjädrar mindre om att gallra bland vilda djur och mer om att odla disciplin. I taurenkulturen visar troféer från en svår jakt list och uthållighet. När äventyraren överlämnar de oskadade fjädrarna till de äldre i Bloodhoof Village visar det att hen kan försörja och försvara samhället, och att hovarna är snabba och sinnena skarpa nog att bemästra den större världen."}},faq={{q="Varför ber Harken Windtotem dig jaga swoop-fåglar?",a="Harken Windtotem ger jägare i uppdrag att spåra swoop-fåglar genom Mulgore för att pröva deras list, snabbhet och hängivenhet. Oskadade troféfjädrar är ett erkänt bevis på jägarens skicklighet och ger ära bland tauren i Bloodhoof Village.",al={"varför jaga swoop-fåglar","syftet med harken windtotems uppdrag","syftet med swoop-jakten"}},{q="Var brukar man stöta på swoop-fåglar?",a="Swoop-fåglar finns utspridda över Mulgore öppna slätter. De svävar ovanför prärierna eller spanar efter byte i gräset utanför bosättningar som Bloodhoof Village.",al={"var finns swoop-fåglar","swoop-fåglarnas platser i mulgore","hitta swoop-fåglar"}},{q="Varför är swoop-fåglar svåra att jaga?",a="Till skillnad från flockdjur som rör sig tillsammans över slätterna är swoop-fåglar snabba och vaksamma rovfåglar som håller sig utspridda och observanta. För att smyga sig på dem krävs skarp syn för att upptäcka deras flyktvägar och snabba steg för att fälla dem innan de kommer undan.",al={"varför är swoop-fåglar svåra att fånga","swoop-fåglars beteende"}},{q="Vad betyder troféfjädrarna för tauren?",a="I taurenfolkets traditioner står troféfjädrar från swoop-fåglar för tålamod, skarp syn och en lyckad jakt. Att visa upp dem betyder att jägaren har de instinkter som krävs för att försörja och skydda stammen.",al={"vad troféfjädrar från swoop betyder","fjädrarnas betydelse"}},{q="Vem är Harken Windtotem?",a="Harken Windtotem är en respekterad tauren från Bloodhoof Village som håller uppsikt över nykomlingar och blivande jägare. Hen bedömer deras påhittighet genom traditionella prövningar på slätterna.",al={"vem ger uppdraget swoop hunting","harken windtotems bakgrund"}},{q="Påverkar jakten naturens balans i Mulgore?",a="Taurenfolket ser jakt som en helig dialog med Jordmodern, inte som urskillningslöst dödande. Att samla fjädrar är ett måttfullt disciplinprov som hedrar bytesdjurets list och bevarar stammens balans.",al={"är swoop-jakt överjakt","swoop-fåglarnas balans i mulgore"}}},fx={["0d785fcd"]={q="Varför skickar Harken Windtotem en utomstående för att jaga swoops i stället för att jaga dem själv?",a="Harken Windtotem skickar dig inte för att han själv inte kan jaga, utan för att pröva ditt värde. För tauren kräver det skarp syn, tålamod och snabba hovar att spåra den listiga swoopen över slätterna. När Harken ber dig ta med deras fjädrar tillbaka får du chansen att visa Bloodhoof Village din skicklighet och beslutsamhet och bevisa att du är en jägare av verklig förmåga.",al={"varför skickas jag att jaga swoops","varför behöver harken mig","varför kan harken inte jaga swoops"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ser en talang för diskretion hos dig och ber dig gå in i Venture Companys gruva. Han vill att du tar Seaforium Mining Charges från gruvans förrådsvagnar.",h="Boarton Shadetotem ser en talang för diskretion hos dig och ber dig gå in i Venture Companys gruva.",kw={"sprängmateriel","boarton shadetotem","mask","gruva","seaforium mining charges","diskretion","thunder bluff","venture company"},ang={["class:Rogue"]="Boarton tror att du som rogue har en talang för diskretion och ber dig gå in i Venture Companys gruva."},sec={{t="Ett diskret tillvägagångssätt",b="Boarton Shadetotem i Thunder Bluff tror att du kan gå diskret till väga. Han ger dig en mask och ber dig gå in i Venture Companys närbelägna gruva. Där ska du ta Seaforium Mining Charges från vagnar med sprängmateriel och ta med dem tillbaka till honom."}},faq={{q="Vem ber mig gå in i gruvan?",a="Boarton Shadetotem i Thunder Bluff ber dig gå in i Venture Companys gruva.",al={"vem är boarton","boarton shadetotem","vem gav detta"}},{q="Vad letar jag efter i gruvan?",a="Du ombeds ta Seaforium Mining Charges från vagnar med sprängmateriel.",al={"vad ska stjälas","gruvförråd","seaforium-laddningar"}},{q="Varför ger Boarton mig en mask?",a="Boarton ger dig en mask för att gå in i Venture Companys närbelägna gruva.",al={"mask förklädnad","varför masken","infiltrera gruvan"}},{q="Var ligger Venture Companys gruva?",a="Gruvan ligger sydost om Thunder Bluff.",al={"gruvans läge","var ligger gruvan","venture companys gruva"}},{q="Vem tas materielen från?",a="Materielen finns i Venture Companys gruva.",al={"vem äger materielen","venture companys materiel","bolagets gruva"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ber dig göra en salva av Windfury Cones som finns norr om Thunder Bluff. Han hoppas att den ska få sår från en klinga att bränna med bitter kraft.",h="Boarton Shadetotem ber dig göra en salva av Windfury Cones som finns norr om Thunder Bluff.",kw={"boarton shadetotem","harpyor","mortel och mortelstöt","salva","stalk with the earthmother","thunder bluff","windfury cones"},sec={{t="En bitter salva",b="Boarton Shadetotem i Thunder Bluff vill ha en giftig salva, gjord av kottar som samlas nära harpyornas bon i norr. Du ska krossa Windfury Cones i en mortel med en mortelstöt och sedan ge honom resultatet. Han varnar för att den färdiga salvan kan göra ont även på huden."}},faq={{q="Vem ber om salvan?",a="Boarton Shadetotem i Thunder Bluff ber dig tillreda en salva av Windfury Cones.",al={"vem vill ha salvan","boarton shadetotems begäran"}},{q="Var växer Windfury Cones?",a="Harpyorna norr om Thunder Bluff bygger sina bon i ett träd som producerar det giftiga hartset. Nedfallna kottar ligger runt deras bon.",al={"var finns kottar","var finns windfury cone"}},{q="Vad är salvan tänkt att göra?",a="När salvan stryks på en klinga ska den få en motståndares sår att bränna och förvandla blodet till salt.",al={"vad gör salvan","giftig salva för klingor"}},{q="Varför varnar Boarton för att röra vid den?",a="Boarton säger att även hudkontakt med den färdiga salvan kan göra ont.",al={"varning för salva på huden","är salvan farlig"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="An Ambassador of Evil",s="Historian Karnik vill att Ambassador Infernus från Angor Fortress röjs ur vägen. Du ska återvända till Badlands och ta med bevis på att du dödat honom till Advisor Belgrum i Ironforge.",h="Historian Karnik vill att Ambassador Infernus från Angor Fortress röjs ur vägen.",kw={"advisor belgrum","ambassador infernus","angor fortress","badlands","historian karnik","ironforge","ragnaros","shadowforge","uldaman"},sec={{t="Ambassadören i Angor Fortress",b="Ragnaros själv skickade Ambassador Infernus till Angor Fortress för att övervaka Shadowforge medan de söker efter förlorade artefakter i Uldaman. Många dvärgar har redan mist livet, och dödstalet stiger. Karnik vågar inte gissa hur många artefakter Shadowforge kan hitta och använda mot Ironforge. Du ska återvända till Badlands, döda Infernus och ta med bevis på segern till Belgrum. Tiden är knapp, eftersom Ragnaros inte väntar på att de ska förbereda sig."},{t="Belgrums tack",b="Belgrum berömmer din hängivenhet till Ironforge och dvärgafolket och skickar bud till Karnik om din framgång. Hjälp kommer också att skickas till Badlands för att återta utgrävningsplatsen. Belgrum har ytterligare en sak att be dig om, i kung Bronzebeards namn."}},faq={{q="Vem är Ambassador Infernus?",a="Ragnaros själv skickade Infernus till Angor Fortress för att övervaka Shadowforge medan de söker efter förlorade artefakter i Uldaman.",al={"vem är infernus","infernus bakgrund","ambassador infernus bakgrund"}},{q="Var finns Ambassador Infernus?",a="I Angor Fortress, i Badlands.",al={"var hittar man ambassador infernus","ambassador infernus plats","var är infernus"}},{q="Varför vill Karnik att Ambassador Infernus dödas?",a="Shadowforges sökande i Uldaman har redan kostat många dvärgar livet, och Karnik fruktar att artefakterna de hittar kan användas mot Ironforge.",al={"varför döda ambassador infernus","vad gör infernus i uldaman","hot mot ironforge i badlands"}},{q="Vem ger och avslutar det här uppdraget?",a="Historian Karnik i Ironforge ger uppdraget, och du lämnar bevis på segern till Advisor Belgrum i Ironforge.",al={"vem startar an ambassador of evil","vem lämnar in an ambassador of evil","uppdragsgivare för an ambassador of evil"}},{q="Vilket bevis behövs?",a="Ambassador Infernus' Bracer, som du visar Advisor Belgrum som bevis på din seger.",al={"vad behöver jag från infernus","bevis på ambassador infernus","infernus armband"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ber dig att filéa en Raw Brilliant Smallfish i Thunder Bluff. Han hoppas att övningen ska avslöja en fallenhet för subtila konster.",h="Boarton Shadetotem ber dig att filéa en Raw Brilliant Smallfish i Thunder Bluff.",kw={"boarton shadetotem","knife set","raw brilliant smallfish","stalk with the earthmother","subtila konster","thunder bluff"},sec={{t="Ett sista prov",b="Boarton Shadetotem i Thunder Bluff ber dig att visa vad som faller sig naturligt med hans Knife Set. Ta med en Raw Brilliant Smallfish till honom och filéa den inför honom. Han hoppas att detta mindre direkta prov ska avslöja en dold talang."},{t="Avskedsord",b="Boarton Shadetotem ser att du saknar den skurkaktiga precision han sökte. Han ger dig en avskedsgåva och låter dig resa vidare, med en önskan om att Horde får hjältar som du."}},faq={{q="Vem ber mig att filéa en fisk?",a="Boarton Shadetotem i Thunder Bluff ber dig att filéa en Raw Brilliant Smallfish med hans Knife Set.",al={"vem är boarton","boarton shadetotem","fisk kniv uppdrag"}},{q="Varför vill Boarton att jag ska filéa en fisk?",a="Boarton hoppas att övningen ska locka fram en dold fallenhet för subtila konster.",al={"varför filéa fisk","vad testar boarton","småfiskprov"}},{q="Vilken fisk ber Boarton om?",a="Boarton ber om en Raw Brilliant Smallfish.",al={"vilken fisk","rå småfisk","lysande fisk"}},{q="Var ska jag filéa fisken?",a="Filéa en Raw Brilliant Smallfish framför Boarton Shadetotem i Thunder Bluff.",al={"var finns fiskuppdraget","thunder bluff fisk","var används knife set"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="Rites of the Earthmother",s="Rites of the Earthmother markerar en ung taurenkrigares övergång från avskilda Red Cloud Mesa till Mulgore slätter. Efter att du visat vad du går för i Camp Narache skickar Chief Hawkwind dig norrut till Bloodhoof Village med en snidad totem, för att fortsätta de uråldriga prövningarna under Baine Bloodhoof.",h="Rites of the Earthmother markerar en ung taurenkrigares övergång från avskilda Red Cloud Mesa till Mulgore...",kw={"baine bloodhoof","bloodhoof village","cairne bloodhoof","camp narache","chief hawkwind","mulgore","rites of the earthmother","totem of hawkwind"},ang={["faction:Horde"]="De traditionella riterna stärker stammarnas gemenskap i hela Mulgore och ser till att Hordens nya försvarare besitter både krigarkraft och djup andlig förankring.",["race:Tauren"]="Varje ung tauren måste vandra Earthmothers väg för att bevisa sitt värde för de äldste och finna sin plats bland de förenade stammarna."},sec={{t="Lämna mesan",b="I generationer har unga tauren testat sin styrka i Camp Naraches trygga famn på Red Cloud Mesa. De inledande prövningarna visar att man har disciplin och beslutsamhet nog att överleva, men Earthmothers heliga riter kräver långt mer än att överleva bland traktens vilda djur. Chief Hawkwind märker när en novis har vuxit ur mesans skyddade jaktmarker och måste ta steget in i den större gemenskapen."},{t="En gåva till Baine",b="För att underlätta färden mellan Narache och de centrala bosättningarna ger Chief Hawkwind dig en handskuren totem som introduktion. Med emblemet i handen följer du den slingrande stigen till Bloodhoof Village och presenterar dig för Baine Bloodhoof, byns unge hövding och son till överhövding Cairne Bloodhoof. Totemen visar att du är redo för de kommande andliga och visdomsprövningarna."}},faq={{q="Vad är syftet med det här uppdraget?",a="Det är en övergångsrit som leder dig ut ur startområdet Camp Narache och vidare mot Bloodhoof Village, där du får möta nästa del av taurenfolkets ceremoniella prövningar.",al={"varför rites of the earthmother","vad gör uppdraget","syftet med uppdraget"}},{q="Vem är Baine Bloodhoof?",a="Baine Bloodhoof är son till överhövding Cairne Bloodhoof. Han leder Bloodhoof Village och är en respekterad lokal hövding som övervakar de pågående andliga och stridsmässiga prövningarna för unga tauren.",al={"vem är baine","baine bakgrund","cairnes son"}},{q="Vad är Totem of Hawkwind?",a="Det är en trätem som Chief Hawkwind i Camp Narache har snidat för hand. Den fungerar som en officiell legitimation och ett godkännande, som visar Baine Bloodhoof att du har förtjänat Hawkwinds välsignelse att genomgå fler riter.",al={"totem of hawkwind","hawkwinds totem","snidad totem"}},{q="Vilka riter följer efter detta?",a="När du kommer till Bloodhoof Village och träffar Baine får du uppdraget Rite of Vision, som prövar din andliga samhörighet genom heliga syner från förfäderna.",al={"nästa riter","vad kommer efter","nästa uppdrag"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village ligger norr om Camp Narache, vid Stonebull Lakes strand i centrala Mulgore. Följ bara huvudvägen ner från mesan och fortsätt norrut.",al={"var ligger bloodhoof village","hur hittar man bloodhoof village","vägen till bloodhoof"}},{q="Varför måste Earthmothers riter genomföras?",a="Rites of the Earthmother är djupt heliga traditioner bland tauren. Den som klarar alla riter visar fysisk uthållighet, andlig samhörighet och visdom, och vinner därmed erkännande från Thunder Bluffs äldste.",al={"varför earthmothers riter","syftet med taurenfolkets prövningar","rites of the earthmother bakgrund"}}},fx={["4a33bb81"]={q="Varför skickar Chief Hawkwind dig till Bloodhoof Village?",a="Chief Hawkwind har väglett dig genom de inledande prövningarna på Red Cloud Mesa, men Camp Narache har inget mer att lära dig. För att fullborda Earthmothers heliga riter och vinna Thunder Bluffs äldstes acceptans måste du skaffa dig mer erfarenhet på Mulgore slätter. Genom att skicka dig till Baine Bloodhoof med sitt snidade totem överlåter Hawkwind ansvaret för din andliga och fysiska utveckling åt en ledare som kan pröva om du är redo för verkligt vuxenliv.",al={"varför skickas jag till bloodhoof","chief hawkwinds motiv","varför earthmothers riter"}},["9c980781"]={q="Varför måste du själv överlämna totemen?",a="Resan är inte ett enkelt kuriruppdrag, utan en viktig del av din övergångsrit. När du lämnar Red Cloud Mesas skyddade område och följer den öppna vägen in i Mulgore visar du din självständighet och uthållighet. Genom att själv lämna över Totem of Hawkwind kan Baine Bloodhoof se dig, känna igen Hawkwinds personliga rekommendation som är inristad i träet och bedöma din karaktär på nära håll.",al={"varför ska jag ta med totemen","varför kan hawkwind inte skicka en budbärare","varför jag ska genomgå earthmothers riter"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="The Venture Co.",s="Undersökningen av en skövlad Venture Company-karavan i Mulgore avslöjar att allt fler aggressiva Venture Company-goblins gräver sig in i de östra kullarna. Efter att deras formella ansökningar om gruvtillstånd avslagits blankt valde företaget ändå att bryta i Jordemoderns jord, vilket fick Morin Cloudstalker att beställa ett dödligt svar.",h="Undersökningen av en skövlad Venture Company-karavan i Mulgore avslöjar att allt fler aggressiva Venture...",kw={"goblin","gruvrättigheter","morin cloudstalker","mulgore","ravaged caravan","venture co","venture co-gruvan","venture company"},ang={["faction:Horde"]="När du försvarar Mulgore mot kommersiell exploatering visar du din hängivenhet till att skydda Cairne Bloodhoofs folk medan de arbetar för att trygga sitt nya hemland.",["profession:Mining"]="Venture Company ägnar sig enbart åt hänsynslös utvinning och tar genvägar som destabiliserar landet, utan hänsyn till den naturliga balansen eller säker gruvdrift.",["race:Tauren"]="För tauren är Jordemodern helig. Venture Companys dagbrottsbrytning är inte bara ett intrång, utan en våldsam skändning av deras förfäders hem som kräver att de omedelbart drivs bort med våld."},sec={{t="Industriellt intrång",b="Tauren i Mulgore vördar landet som en förlängning av Jordemodern och värnar dess orörda slätter och balanserade djurliv. När Venture Company vände sig till stammarna för att få rätt att spränga och gräva ut de böljande kullarna efter råmalm avslogs deras ansökningar kategoriskt. Oavskräckt av stammarnas påbud och territoriella självbestämmande smög det hänsynslösa kartellen in tunga maskiner, arbetare och förmän direkt i Mulgore östra bergsryggar för att bedriva olaglig gruvdrift."},{t="Ett otvetydigt budskap",b="Tauren-spejare som Morin Cloudstalker inser att företagens girighet inte går att resonera med genom diplomatiska vädjanden när hackorna väl träffar stenen. Dokument som återfunnits i en skövlad Venture Co.-karavan bekräftar företagets gruvdrift, och Morin skickar därför Horde-mästare för att slå ner både slavdrivarna som viner med piskorna och arbetarna som driver borrarna. Den blodiga vedergällningen ska få Venture Company att inse att priset för intrång är alldeles för högt."}},faq={{q="Varför är Venture Company i Mulgore?",a="Venture Company upprättade en olaglig utpost och gruva längs Mulgore östra kullar för att utvinna mineraler och naturresurser. Efter att tauren formellt nekat dem gruvrättigheter struntade kartellen i stammarnas auktoritet och satte ändå upp sin verksamhet.",al={"varför finns gobliner i mulgore","venture co:s motiv i mulgore","vad vill venture co ha"}},{q="Vem beordrade attacken mot gruvarbetarna?",a="Morin Cloudstalker, en tauren som håller vakt nära Bloodhoof Village, ger ordern. Han ser kartellens vägran att godta stammarnas avslag som ett direkt övertramp som kräver våld, inte fler samtal.",al={"vem ger uppdraget","morin cloudstalkers roll","uppdragsgivare"}},{q="Var ligger Venture Company-gruvan?",a="Venture Companys huvudgruva ligger i bergsfoten öster om Ravaged Caravan och Bloodhoof Village. En mindre grupp företagsanställda kan också påträffas vid en utpost gömd bland klipporna nordost om Thunder Bluffs norra hissar.",al={"venture co-gruvans plats","var finns förmännen","var hittar man venture co"}},{q="Försökte tauren någonsin förhandla med goblinerna?",a="Ja. Venture Company ansökte formellt hos tauren om gruvrättigheter i Mulgore. Stamledarna vägrade låta dem dagbrottsbryta sina förfäders marker, men goblinerna valde helt enkelt att gräva utan tillstånd ändå.",al={"gav tauren tillstånd till gruvdrift","gruvrättigheter i mulgore","bad goblinerna om tillstånd"}},{q="Tillhör de här goblinerna Steamwheedle Cartel?",a="Nej. Venture Company är en oberoende, beryktat rovlysten industrikartell som skiljer sig från neutrala handelsgrupper som Steamwheedle Cartel. De har fientliga relationer med lokalbefolkningen överallt där de utvinner resurser.",al={"är det här ratchet-gobliner","är venture co vänligt","venture company-fraktionen"}},{q="Hur hänger detta ihop med de skövlade karavanerna?",a="Den skövlade karavanen var en Venture Company-konvoj som tauren förstörde. Gruvavdelningens lådor och dokument som återfanns bland vrakresterna avslöjade företagets verksamhet i Mulgore och ledde till anfallet mot deras gruva.",al={"kopplingen till karavanen","attackerade venture co karavaner","kopplingen till den skövlade karavanen"}}},fx={f6df914e={q="Varför vill Morin Cloudstalker att Venture Co. angrips?",a="Venture Company nekades officiellt gruvrättigheter i Mulgore, men ignorerade avslaget och började ändå samla utrustning och arbetare. Morin Cloudstalker kan inte låta dem förstöra landet och plundra dess naturtillgångar ostraffat. Eftersom diplomati och tydliga avslag inte har hejdat deras girighet anser han att tauren måste ge dem ett omisskännligt och kraftfullt budskap: intrång och stöld tolereras inte.",al={"morin cloudstalkers motiv","varför attackera venture co.","varför vill morin döda venture co."}},eda5096c={q="Vilka skickas du att strida mot vid gruvan?",a="Du skickas mot Venture Co. Supervisors och Workers som är stationerade vid deras gruvdrift i östra Mulgore. Dessa gobliner och inhyrda arbetare gräver djupt i de heliga kullarna för att utvinna mineraler utan stammens tillstånd. De leds av vinstdrivna förmän som driver företagets aggressiva och olagliga expansion.",al={"målen i venture co.-uppdraget","vilka är arbetarna i venture co.","vem ska jag slåss mot i gruvan"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="Supervisor Fizsprocket",s="Supervisor Fizsprocket är en högt uppsatt tillsyningsman för Venture Company, stationerad i gruvgångarna i Mulgore. På uppdrag av Morin Cloudstalker går hordeäventyrare in i gruvan för att sätta stopp för goblinernas planerade plundring, döda honom och återta hans detaljerade skrivplatta.",h="Supervisor Fizsprocket är en högt uppsatt tillsyningsman för Venture Company, stationerad i gruvgångarna i...",kw={"skrivplatta","fizsprocket","gruva","morin cloudstalker","mulgore","tillsyningsman","venture company"},ang={["faction:Horde"]="Genom att hjälpa tauren mot företagets framryckande plundrare stärker du hordens skydd av de nyligen erövrade kärnområdena i Kalimdor.",["race:Tauren"]="Venture Companys öppna plan att fördriva din stam och plundra den heliga jorden gör dödandet av Fizsprocket till en nödvändig handling för att försvara ert område."},sec={{t="En plan mot slätterna",b="Dokument som återfanns i en förstörd karavan från Venture Company visade att företaget inte bara grävde efter malm – de utarbetade medvetet planer för att driva bort tauren från Mulgore för gott. Genom att fördriva lokalbefolkningen ville det glupska företaget få fria händer att tömma de böljande kullarna och djupa underjordiska ådrorna på alla naturresurser."},{t="Slå till mot förmannen",b="Morin Cloudstalker, rasande över företagets övergrepp som planerats mot hans folk, skickar hjältar till Venture Company-gruvan strax öster om de skövlade handelsvagnarna. Supervisor Fizsprocket leder verksamheten långt inne i de högra gångarna, omgiven av arbetare och underordnade chefer. När Fizsprocket fälls och hans skrivplatta tas i beslag slås den lokala samordningen sönder, och viktig information om företagets framtida planer kommer fram."}},faq={{q="Vem är Supervisor Fizsprocket?",a="Supervisor Fizsprocket är en chef för Venture Company som leder arbetet i gruvgångarna i östra Mulgore. Han övervakar arbetsstyrkan som gräver i jorden och genomför företagets strategier för att utöka verksamheten i regionen.",al={"fizsprocket","vem är fizsprocket","fizsprockets bakgrund"}},{q="Varför vill Morin Cloudstalker att Fizsprocket ska dö?",a="Morin hittade dokument i en plundrad karavan som bevisade att Venture Company planerade att driva bort tauren från deras förfäders land för vinnings skull. Fizsprocket är den direkte tillsyningsmannen som genomför dessa beräknande utsugningsplaner.",al={"varför döda fizsprocket","morin cloudstalkers motiv"}},{q="Var finns Supervisor Fizsprocket?",a="Han finns inne i Venture Company-gruvan, rakt öster om Ravaged Caravan i Mulgore. Följ den bortre högra gången inne i gruvan till en kammare där han står omgiven av arbetare och tillsyningsmän.",al={"var finns fizsprocket","fizsprockets gruva","fizsprockets karta"}},{q="Vilket bevis på Fizsprockets nederlag kräver Morin?",a="Morin Cloudstalker kräver Fizsprockets personliga skrivplatta, som innehåller räkenskaper och anteckningar som kan avslöja ytterligare planer från Venture Company i Mulgore.",al={"dödsbevis","fizsprockets skrivplatta"}},{q="Varför är Venture Company i Mulgore?",a="Venture Company är ett skrupelfritt handelskartell som vill skövla orörd mark på timmer, mineraler och värdefulla rikedomar under jord, utan minsta hänsyn till ursprungsbefolkningen eller den ekologiska balansen.",al={"venture company i mulgore","varför är gobliner i mulgore"}},{q="Driver dödandet av Fizsprocket bort Venture Company helt?",a="Nej. Fizsprockets död stör deras lokala ledning och ger Morin Cloudstalker viktiga anteckningar om deras planer, men Venture Company förblir ett ihållande hot i kullarna i Mulgore.",al={"är venture company borta","efter fizsprockets död"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="Mazzranache",s="Maur Raincaller i Bloodhoof Village har fallit offer för ett giftigt bett från Mazzranache, en legendarisk strider som terroriserade hans farfar en generation tidigare. Taurenen har drabbats av feber och deliriska mardrömmar och behöver ett kraftfullt läkemedel bryggt av Mulgore-vildmarkens djur innan infektionen tar hans liv.",h="Maur Raincaller i Bloodhoof Village har fallit offer för ett giftigt bett från Mazzranache, en legendarisk...",kw={"bloodhoof village","flatland cougar","maur raincaller","mazzranache","mulgore","plainstrider","prairie wolf","swoop"},ang={["class:Hunter"]="När du spårar prärievargar, pumor, striders och swoops genom Mulgore får du praktisk övning i att läsa slätten och förstå savannens olika djur.",["faction:Horde"]="Att trygga Bloodhoof Village mot Mulgore-vildmarkens hårda faror är avgörande för att skapa fred och stabilitet i taurenfolkets hemland.",["race:Tauren"]="Läkemedlet som Maur brygger återspeglar taurenfolkets urgamla sed att hämta botemedel direkt från Jordemoderns flora och fauna."},sec={{t="En slättens sägen",b="I åratal betraktade Maur Raincaller Mazzranache som föga mer än en skrämmande familjesägen som hans farfar hade fört vidare. Den äldre taurenen berättade om en ovanligt vildsint strider med glödande röda ögon, rakbladsvassa klor och ett giftigt bett som trotsade det fredliga sinnelaget hos de flesta djuren i Mulgore. När Maur stötte på besten ute på den öppna grässlätten visade sig sägnen vara alltför verklig. Han blev svårt sårad och kämpade för att ta sig tillbaka i säkerhet."},{t="En kamp mot infektionen",b="Varelsens gift verkar snabbt och orsakar hög feber och mardrömslikt delirium. För att driva ut giftet innan det blir dödligt förlitar sig traditionell taurenmedicin på den lokala faunans livskraft. Maur behöver ett Prairie Wolf Heart, ett Flatland Cougar Femur, en Plainstrider Scale och en Swoop Gizzard. Genom att förena essenserna från dessa olika jägare och asätare kan han brygga en blandning som hejdar den nekrotiska spridningen och hjälper honom att återhämta sig."}},faq={{q="Vad är Mazzranache?",a="Mazzranache är en ökänd strider som strövar omkring på Mulgore-slätterna. Till skillnad från vanliga striders är den känd för sin färgstarka fjäderdräkt, demoniska röda ögon, vassa klor och ovanligt giftiga bett. Den har terroriserat resande i flera generationer.",al={"vem är mazzranache","vad är mazzranache för slags best","mazzranaches bakgrund"}},{q="Vem är Maur Raincaller?",a="Maur Raincaller är en tauren som bor i Bloodhoof Village. När han färdades genom Mulgore överföll Mazzranache honom och bet honom i axeln. Nu ligger han sängbunden med en livshotande, giftig infektion.",al={"maur raincaller","vem gav mig uppdraget","vem är den sjuka taurenen"}},{q="Varför behöver Maur delar från fyra olika djur?",a="Traditionella taurenläkemedel hämtar kraft från slättdjurens naturliga styrka och andliga essenser för att neutralisera starka gifter. Ett varghjärta, den täta märgen i ett puma-lårben, en striders fjäll och en swoops kräva bildar tillsammans ett motgift starkt nog att motverka Mazzranaches gift.",al={"varför varghjärta och pumalårben","varför ingredienser från djur","ingredienser till mazzranaches motgift"}},{q="Dödade Maurs farfar Mazzranache?",a="Nej. Maurs farfar kämpade mot den vildsinta stridern för många år sedan, men kunde inte besegra den. Han överlevde och förde vidare varningshistorier om dess klara färger och våldsamma attacker till sina efterkommande.",al={"besegrade farfar mazzranache","maurs farfar och mazzranache","vem kämpade mot mazzranache tidigare"}},{q="Ska jag jaga Mazzranache?",a="Nej. Maurs främsta mål är att överleva febern. Uppdraget går helt ut på att samla ingredienserna till hans läkemedel, inte på att jaga den legendariska fågeln.",al={"ska jag döda mazzranache","var finns mazzranache","jaga mazzranache"}},{q="Var ligger Bloodhoof Village?",a="Bloodhoof Village ligger i centrala Mulgore, söder om Thunder Bluff och strax öster om Stonebull Lake. Det är den främsta bosättningen för unga taurenkrigare som ger sig ut på de vidsträckta slätterna.",al={"var ligger bloodhoof village","bloodhoof village läge"}}},fx={["3b88d77e"]={q="Varför vill Maur Raincaller att detta görs?",a="Maurs liv står direkt på spel. När han färdades över Mulgore slätter stötte han på Mazzranache, en legendarisk plainstrider som är känd för att ha terroriserat hans farfar. Odjuret bet honom våldsamt och giftigt i axeln. En förlamande feber har brutit ut, gett honom vanvettiga mardrömmar och sprider sig stadigt genom kroppen. Utan de animaliska ingredienser som behövs för att brygga ett läkemedel kommer den rasande infektionen snart att döda honom.",al={"maur raincallers motiv","varför hjälpa maur raincaller","vad hände med maur"}},ce37bf7e={q="Varför behöver Maur en utomstående i stället för att bota sig själv?",a="Maur är för svårt skadad och febrig för att själv jaga Mulgore vilddjur. Mazzranaches giftiga bett har gjort honom omtöcknad och utmattad, så han är bunden till Bloodhoof Village. Tiden håller på att rinna ut innan infektionen blir dödlig, så han måste förlita sig på förbipasserande resenärer för att spåra upp de snabba pumorna, swoops, vargarna och plainstriders som behövs till läkemedlet.",al={"varför kan maur inte skaffa delarna","varför behöver maur dig","varför jag ska ta mig an mazzranache"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="Rite of Vision",s="Rite of Vision är ett avgörande mognadsprov inom Rites of the Earthmother, där en ung äventyrarens andliga mognad sätts på prov. Baine Bloodhoof inleder uppdraget och hänvisar de prövande till byns siare, Zarlman Two-Moons. Resan är nödvändig för alla som söker de äldstes välsignelse och respekt på Thunder Bluffs höjder.",h="Rite of Vision är ett avgörande mognadsprov inom Rites of the Earthmother, där en ung äventyrarens andliga...",kw={"baine bloodhoof","bloodhoof village","mulgore","rite of vision","rites of the earthmother","taurenprov","thunder bluff","zarlman two-moons"},ang={["class:Druid"]="Att möta Earthmothers visioner direkt stärker druidens kall att lyssna noga till den levande världens visdom och viskningar.",["class:Shaman"]="Att söka upp Zarlman Two-Moons och vandra på visionernas väg känns djupt besläktat med schamanens plikt att balansera världsliga angelägenheter mot förfädernas vilja.",["faction:Horde"]="Att genomgå dessa traditionella heliga riter visar din lojalitet och vördnad för taurenkulturen inför de äldste som hjälper till att vägleda Horden.",["race:Tauren"]="Rite of Vision är en viktig kulturell milstolpe för varje ung tauren och markerar övergången till att bli en betrodd försvarare och andevandrare för stammen."},sec={{t="Ett heligt steg på vägen",b="I generationer har de nomadiska tauren vänt sig till Earthmother för vägledning när folket färdats över Kalimdors slätter. Nu när de samlats inom Mulgore trygga gränser är deras andliga traditioner fortfarande samhällets hörnsten. Rite of Vision är ett av de uråldriga proven som kallas Rites of the Earthmother. Tidigare prov prövar en noviss fysiska styrka och band till jakten, men Rite of Vision kräver en inre resa där unga tauren och hedrade allierade får möta andarna direkt."},{t="Siarens vägledning",b="Innan någon andlig vision kan sökas måste en person med djup kunskap om forntida visdom förbereda den prövande. I Bloodhoof Village vilar det ansvaret på den vördnadsvärde schamanen Zarlman Two-Moons. Baine Bloodhoof har anförtrott honom att förbereda resenärer, och Zarlman har skarp blick nog att känna igen dem som vandrar på förfädernas väg. Han erbjuder de inledande riterna och heliga förberedelserna som krävs för att genomtränga den fysiska världens slöja."}},faq={{q="Vad är Rite of Vision?",a="Rite of Vision är en helig ritual inom Rites of the Earthmother. Den ska vidga en äventyrarens andliga syn, så att hen kan möta förfädernas andar och visa de äldste i Thunder Bluff sin andliga beredskap.",al={"uppdraget rite of vision","vad är rite of vision","lore om rite of vision"}},{q="Vem ger uppdraget?",a="Uppdraget ges av Baine Bloodhoof, son till överhövdingen Cairne Bloodhoof. Baine vakar över bosättningen Bloodhoof Village och hänvisar värdiga resenärer till byns andliga äldste.",al={"vem ger rite of vision","uppdragsgivare för rite of vision"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en erfaren tauren-schaman och den andliga ledaren i Bloodhoof Village. Han förbereder resenärer och noviser som vill genomgå heliga prov som Rite of Vision.",al={"vem är zarlman","lore om zarlman two-moons"}},{q="Varför är Rites of the Earthmother viktiga för tauren?",a="Rites of the Earthmother är en traditionell övergångsrit för tauren som når vuxen ålder. Att klara dem visar fysisk förmåga, andlig samklang och varaktig respekt för landet, och ger de högsta äldstes heder.",al={"vad rites of the earthmother betyder","varför genomföra rites of the earthmother"}},{q="Kan andra än tauren genomgå Rite of Vision?",a="Ja. Hordens allierade som färdas genom Mulgore och vinner Bloodhoof-stammens förtroende får vandra på Earthmothers väg. De visar respekt för taurentraditionen och vinner de äldstes välvilja.",al={"kan orcher genomgå rite of vision","andra än tauren och earthmother"}},{q="Var äger provet rum?",a="Provet börjar i Bloodhoof Village, en framstående tauren-bosättning nära Stonebull Lakes stränder i centrala Mulgore, söder om Thunder Bluff.",al={"var finns rite of vision","platsen för rite of vision"}}},fx={["1fa313da"]={q="Varför vill Baine Bloodhoof att du genomgår Rite of Vision?",a="Baine Bloodhoof förbereder dig för att följa dina förfäders väg och visa ditt värde för taurenfolket. När du blir vuxen i Mulgore måste du genomgå Earthmothers heliga riter för att kommunicera med andarna, lära dig vörda landet och till sist vinna de äldstes respekt i Thunder Bluff. Baine hänvisar dig till byns mystiker Zarlman Two-Moons så att du kan inleda den andliga prövningen på rätt sätt.",al={"varför baine skickar dig på rite of vision","baine bloodhoofs motiv för rite of vision","varför genomgå rite of vision"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="Gathering Leather",s="Gathering Leather är ett enkelt bytesuppdrag som Veren Tallstrider erbjuder på Thunder Bluffs höjder. För att försörja huvudstaden och sätta unga jägare på prov byter Veren ett knippe garvade Light Leather-hudar mot hantverksvaror. Uppdraget visar hur djupt taurenfolkets tradition sitter: att förvandla bytet från jakten på slätterna till nödvändiga kläder och rustningar.",h="Gathering Leather är ett enkelt bytesuppdrag som Veren Tallstrider erbjuder på Thunder Bluffs höjder.",kw={"gathering leather","läderhantverk","light leather","mulgore","taurenjakt","thunder bluff","veren tallstrider"},ang={["class:Hunter"]="Jägare som ger sig ut på Mulgore slätter är naturligt skickliga på att spåra byte och ta till vara de Light Leather-hudar Veren behöver.",["faction:Horde"]="När hantverkare i Thunder Bluff får råmaterial stärks den unga huvudstaden medan den befäster sitt försvar och sina handelsnätverk.",["race:Tauren"]="För taurenjägare är det en viktig kulturell sed, som förts vidare genom generationer, att hedra det fallna djuret genom att göra dess hud till användbara varor."},sec={{t="Att försörja Thunder Bluff",b="I den nyetablerade huvudstaden på Mulgore höga platåer går hantverk och överlevnad hand i hand. Veren Tallstrider bearbetar hudar till kläder och skyddande rustningar som Thunder Bluffs växande befolkning behöver. I stället för att själv samla in allt uppmuntrar han unga äventyrare på väg ut över slätterna att ta med sig sitt byte hem. På så vis blir vanlig jakt en hedervärd samhällsinsats."},{t="Jaktens väg",b="För tauren är jakten på gräsmarkernas bestar ingen sport, utan en hedervärd gärning som ger stammen mat, kläder och skydd. Veren Tallstrider söker jägare som vill ära sin klan och ber särskilt om Light Leather från traktens djur. Som ersättning för tolv välbevarade hudar ger han jägaren hållbara varor och stärker därmed den ömsesidiga hjälp som håller ihop taurens samhälle."}},faq={{q="Vem är Veren Tallstrider?",a="Veren Tallstrider är läderarbetare i Thunder Bluff. Han tillverkar kläder och skyddande rustningar åt taurenfolket och byter sina färdiga varor mot färska hudar från slättens jägare.",al={"veren tallstrider","vem ger uppdraget gathering leather","uppdragsgivare för läder i thunder bluff"}},{q="Vad behöver Veren Tallstrider?",a="Veren ber om tolv bitar Light Leather, från bestar i Mulgore och närliggande områden, för att tillverka varor åt Thunder Bluff.",al={"krav för gathering leather","vad ska veren ha","material till gathering leather"}},{q="Var utspelar sig uppdraget?",a="Uppdraget börjar och slutar hos Veren Tallstrider på Thunder Bluff, men för att slutföra det måste du jaga vilda bestar på gräsmarkerna nedanför.",al={"var finns veren tallstrider","plats för gathering leather"}},{q="Varför lägger tauren så stor vikt vid jakt på bestar?",a="Taurenkulturen ser jakten som en helig balans med Jordmodern. Varje del av ett fällt djur tas till vara: köttet mättar stammen, medan ben och garvade hudar blir verktyg, tält och slitstarka rustningar.",al={"taurenfolkets jaktkultur","varför jaga för läder","taurenfolkets läderlore"}},{q="Kan alla äventyrare i Horde utföra uppgiften?",a="Ja, alla resande som är lojala mot Horde och som Veren anser ivriga att pröva sin styrka på slätterna kan hjälpa honom att samla in hudar.",al={"vem kan göra gathering leather","är gathering leather bara för horde"}},{q="Vad händer när hudarna har lämnats in?",a="Veren granskar hudarnas kvalitet, berömmer jägaren för arbetet och ger ett tillverkat utrustningsföremål som skälig betalning.",al={"lämna in gathering leather","veren tallstriders belöning"}}},fx={["1249c214"]={q="Varför vill Veren Tallstrider ha Light Leather?",a="Veren Tallstrider är en läderarbetare som tillverkar kläder och rustningar åt Thunder Bluffs invånare. För att förse staden och hålla sitt hantverk vid liv behöver han jägare som levererar fina hudar från Mulgore slätter.",al={"varför veren behöver läder","veren tallstriders motiv","varför light leather till veren"}},cd30155e={q="Vad används Light Leather till?",a="Lädret blir till nödvändiga kläder, skyddande rustningar och användbara varor åt tauren som bor högt uppe på Thunder Bluffs platåer, liksom utrustning som tillverkas i utbyte åt resande jägare.",al={"vad light leather används till","användning av light leather","hur veren använder light leather"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="Kodo Hide Bag",s="Kodo Hide Bag är ett handelsuppdrag från Veren Tallstrider, en skicklig tauren-läderarbetare på de höga platåerna i Thunder Bluff. I utbyte mot grundläggande hantverksmaterial lär han ut den traditionella metoden för att sy slitstarka resväskor av tåligt djurskinn. Det är ett tidigt mandomsprov för lärlingar i läderarbete i Mulgore.",h="Kodo Hide Bag är ett handelsuppdrag från Veren Tallstrider, en skicklig tauren-läderarbetare på de höga...",kw={"coarse thread","kodo","kodo hide bag","läderarbete","light leather","mulgore","thunder bluff","veren tallstrider"},ang={["faction:Horde"]="Thunder Bluffs hantverkare tillhandahåller viktiga förnödenheter som håller Hordens jägare, spejare och krigare utrustade i centrala Kalimdor.",["race:Tauren"]="För Shu'halo är det ett viktigt steg att lära sig tillverka pålitlig utrustning av den mäktiga kodon, både för att hedra Jordmoderns gåvor och bevara förfädernas seder."},sec={{t="En lektion på platån",b="På Thunder Bluffs hantverkshöjder håller Veren Tallstrider fast vid den gamla nomadtraditionen att inte slösa något från jakten. För att få lära sig av honom måste en blivande läderarbetare ge honom garvat Light Leather och slitstark tråd. Genom att visa att de behärskar grundmaterialen bevisar lärlingarna att de är redo att tillverka varor värdiga att bära överlevnadsutrustning genom Kalimdors karga vidder."},{t="Kodonts anda",b="För tauren är kodon en symbol för uthållighet, styrka och beslutsamhet. Dess tjocka hud skyddar mot törnen, bitande vind och djurklor. Att tillverka väskor och kläder av kodohud är inte bara praktiskt, utan också ett uttryck för vördnad för djuret som gett Shu'halo näring och transport genom otaliga generationer på Mulgore slätter."}},faq={{q="Vem erbjuder uppdraget Kodo Hide Bag?",a="Uppdraget erbjuds av Veren Tallstrider, en tauren-tränare i läderarbete och handelsman i Thunder Bluff.",al={"uppdragsgivare","var får man uppdraget kodo hide bag","veren tallstriders plats"}},{q="Vem kan ta sig an uppgiften?",a="Endast äventyrare som tränat i läderarbete och nått minst lärlingsnivå 10 kan få denna träningsuppgift av Veren Tallstrider.",al={"vem kan ta uppdraget","uppdragskrav","yrkeskrav"}},{q="Vilka material behöver Veren Tallstrider?",a="Han behöver fyra stycken Light Leather och fyra spolar Coarse Thread för att fylla på sina handelsvaror innan han delar med sig av sitt mönster.",al={"vilka föremål behövs","material till kodo hide bag","föremål att lämna in för uppdraget"}},{q="Varför är kodohud betydelsefull för tauren-hantverkare?",a="Kodon förkroppsligar motståndskraft och fysisk styrka, egenskaper som tauren värdesätter högt. Att tillverka slitstark utrustning av deras hudar hedrar djurets ande och ger samtidigt resenärer användbara, tåliga saker när de färdas över slätterna.",al={"varför kodohud","kodons betydelse för tauren","kodons vikt"}},{q="Vad lär Veren Tallstrider ut när uppdraget är slutfört?",a="När Veren fått materialet lär han hantverkaren den särskilda kunskap som behövs för att sy en Kodo Hide Bag.",al={"uppdragsbelöning","vad får jag","väskmönster"}},{q="Var kan man få tag på materialen som behövs?",a="Light Leather får man genom att flå vilddjur på låg nivå i Mulgore och närliggande områden, medan Coarse Thread kan köpas direkt av handels- och skräddarleverantörer.",al={"var får man light leather","var får man coarse thread"}}},fx={c94273ea={q="Varför vill Veren Tallstrider att detta görs?",a="Veren Tallstrider är stolt över att fostra nästa generation taurenläderarbetare. Mulgore kodo-djur vördas för sin styrka och uthållighet, och att tillverka en traditionell väska av deras hudar är en grundläggande färdighet. Genom att be dig samla material till hans hantverk prövar Veren din hängivenhet och påhittighet innan han lär dig hantverkets tekniker.",al={"varför veren tallstrider vill ha läder","veren tallstriders motiv","varför uppdraget med kodo-skinnväskan"}},["1f62e959"]={q="Vad ska Light Leather användas till?",a="Light Leather är det grundläggande hantverksmaterial som Veren Tallstrider behöver i utbyte mot sin undervisning. Att bearbeta garvade hudar är kärnan i taurenfolkets läderhantverk. Genom att skaffa fint läder visar du att du behärskar grunderna i att behandla djurhudar innan du lär dig sy särskilda behållare som kodo-skinnväskor.",al={"vad light leather används till","varför ta med light leather","syftet med light leather"}},["7d0f7d7f"]={q="Vad ska Coarse Thread användas till?",a="Coarse Thread är ett viktigt basmaterial inom sömnad och läderarbete, som används för att foga samman tjocka hudar. För att tillverka hållbara packar som klarar Mulgore slätter behöver hantverkaren en stark tråd som inte brister under tung belastning eller hårt väder.",al={"varför coarse thread","syftet med coarse thread","vad coarse thread används till"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="A Sticky Situation",s="Gilveradin Sunchaser har originalförpackningen till Hinterlands Honey Ripple som Dran Droffers vill ha och hjälper till att packa den mot en avgift på två extra flaskor. Flaskorna finns i lådor runt den övergivna Horde-basen nära Skulk Rock.",h="Gilveradin Sunchaser har originalförpackningen till Hinterlands Honey Ripple som Dran Droffers vill ha och...",kw={"dran droffers","gilveradin sunchaser","the hinterlands","hinterlands honey ripple","geléer","skulk rock","slemvarelser"},sec={{t="En fråga om förpackning",b="Dran Droffers söker efter drycken, och Gilveradin Sunchaser har originalförpackningen till den. Hjälpen är inte gratis: Gilveradin vill ha två extra flaskor som ersättning. Tio flaskor Hinterlands Honey Ripple ska samlas in och tas tillbaka till lägret."},{t="Skulk Rocks ruiner",b="Lådorna står runt den övergivna Horde-basen nära Skulk Rock. Vidriga slemvarelser och geléer klänger sig fast vid ruinerna, och enligt rykten leds de av någon sorts mästargele."}},faq={{q="Vem vill ha Hinterlands Honey Ripple förpackad?",a="Dran Droffers är den som söker efter drycken, och Gilveradin Sunchaser har originalförpackningen till den, som är avsedd för Maltons far.",al={"vem behöver drycken","dran droffers dryck","vem är förpackningen till"}},{q="Vad tar Gilveradin betalt för förpackningen?",a="Gilveradin begär två extra flaskor av drycken som avgift. Tio flaskor ska hämtas från lådorna.",al={"varför tio flaskor","gilveradins avgift","varför så mycket dryck"}},{q="Var finns lådorna med Hinterlands Honey Ripple?",a="De finns i lådor runt den övergivna Horde-basen nära Skulk Rock i The Hinterlands.",al={"dryckens plats","var finns honungsdrycken","skulk rocks lådor"}},{q="Vad finns vid det övergivna lägret vid Skulk Rock?",a="Vidriga slemvarelser och geléer klänger sig fast vid ruinerna, och enligt rykten leds de av en mästargele.",al={"skulk rocks monster","vad finns vid skulk rock","geléer vid skulk rock"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="The Demon Scarred Cloak",s="Demon Scarred Cloak är en trasig fäll från den legendariska vita vargen Ghost Howl, som strövar över Mulgore grässlätter. Fällen bär ett bestående sår från tidigare strider mot Burning Legion och visar att besten befriats från sitt lidande. När du lämnar den till äldste i Bloodhoof Village får en tragisk lokal legend sitt slut.",h="Demon Scarred Cloak är en trasig fäll från den legendariska vita vargen Ghost Howl, som strövar över Mulgore...",kw={"burning legion","demon scarred cloak","ghost howl","mulgore","skorn whitecloud","vit varg"},ang={["class:Druid"]="Druider ser den demonärrade fällen som en dyster påminnelse om att landet och dess vilda invånare fortfarande bär oläkta sår från demonernas invasion av Kalimdor.",["class:Hunter"]="Att spåra upp en ensam, ärrad alfavarg som Ghost Howl är en viktig övergångsrit. Det ger stor uppskattning och en mästerjägares gåva från den äldre Skorn Whitecloud.",["race:Tauren"]="För Shu'halo är jakten på Ghost Howl ingen grym handling eller erövring, utan en dyster ritual som ska ge en plågad varelse frid från Burning Legions kvardröjande besmittelse."},sec={{t="En relik från demoniska sår",b="Ghost Howl är en svårfångad vit varg, känd i hela Mulgore för sin vildhet och sin sorgsna ylande röst. När besten dödas lämnar den efter sig en fäll som tydligt märkts av ondskefull demonisk korruption. Spåren går tillbaka till vargens desperata strider mot Burning Legions invaderande demoner. Konfrontationen lämnade Ghost Howl sårad till kropp och själ långt efter att det tredje kriget tagit slut."},{t="Frid åt en plågad ande",b="Tauren i Mulgore hyser djup respekt för hemlandets vilda djur och vördar dem som Jordmoderns barn. När du visar den ärrade manteln för Skorn Whitecloud i Bloodhoof Village bekräftar det att den plågade rovbesten är död. Skorn förstår vilken skicklighet som krävdes för att spåra upp och besegra Ghost Howl och uttrycker det dystra hoppet att vargens plågade ande äntligen funnit frid i döden."}},faq={{q="Vad är Demon Scarred Cloak?",a="Det är den trasiga huden från Ghost Howl, en legendarisk vit varg i Mulgore. Fällen har synliga ärr från kaoskrafter, efter en gammal strid mot Burning Legion.",al={"vad är demon scarred cloak","föremålet demon scarred cloak","ghost howls fäll"}},{q="Varifrån kommer demonärren på manteln?",a="Ghost Howl fick sina sår i strider mot Burning Legion, när de demoniska inkräktarna trängde fram över Kalimdor under det tredje kriget.",al={"varför är ghost howl ärrad","hur fick ghost howl sina ärr","ghost howl och legionen"}},{q="Vem ska jag lämna manteln till?",a="Lämna manteln till Skorn Whitecloud, en äldre taurenjägare som bor i Bloodhoof Village i Mulgore.",al={"var lämnar jag in demon scarred cloak","vem vill ha demon scarred cloak","lämna in till skorn whitecloud"}},{q="Varför bryr sig Skorn Whitecloud om Ghost Howl?",a="Skorn Whitecloud är en pensionerad jägare som känner igen Ghost Howl som en mäktig best, svårt plågad av demonisk korruption. Han respekterar skickligheten som krävdes för att fälla en sådan varelse och hoppas att dess ande äntligen kan få ro.",al={"skorn whiteclouds historia","varför vill skorn ha ghost howl"}},{q="Var hittar man Ghost Howl?",a="Ghost Howl är en sällsynt vit varg som strövar över Mulgore öppna slätter. Den ses oftast på de norra eller centrala fälten mellan Red Cloud Mesa och Thunder Bluff.",al={"var hittar man ghost howl","ghost howls plats","ghost howls uppdykning"}},{q="Varför hoppas tauren att vargens ande finner frid?",a="Taurenkulturen betonar harmoni med naturen och vördnad för vilda andar. Eftersom demonisk korruption gav Ghost Howl ett liv i ändlöst lidande ses dess nederlag som en barmhärtig befrielse till Jordmodern.",al={"taurens tro och ghost howl","ghost howls ande"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="WANTED: Overseer Maltorius",s="En efterlysning tillkännager att Overseer Maltorius, en avfälling till agent inom Thorium Brotherhood och nyanställd befälhavare för Dark Iron Slag Pit-besättningen i The Cauldron, ska dö. På order av Overseer Oilfist ska hans huvud föras tillbaka som bevis till Lookout Captain Lolo Longstriker.",h="En efterlysning tillkännager att Overseer Maltorius, en avfälling till agent inom Thorium Brotherhood och...",kw={"belöning","cauldron","lolo longstriker","overseer maltorius","overseer oilfist","searing gorge","the slag pit","thorium brotherhood"},sec={{t="Pris på en förrädare",b="Overseer Maltorius, en förrädisk Dark Iron-dvärg, finns någonstans i djupet av The Cauldrons Slag Pit. Ordern är att döda honom, ta hans huvud och föra det tillbaka till Lookout Captain Lolo Longstriker för belöningen."}},faq={{q="Vem är Overseer Maltorius?",a="En förrädisk Dark Iron-dvärg. Efterlysningen kallar honom en avfälling till agent inom Thorium Brotherhood och nyanställd befälhavare för Dark Irons besättning i The Cauldrons Slag Pit.",al={"maltorius bakgrund","vem är maltorius","overseer maltorius bakgrund"}},{q="Var finns Overseer Maltorius?",a="Långt nere i Slag Pit, som tillhör The Cauldron.",al={"maltorius plats","var finns maltorius","hur hittar man overseer maltorius"}},{q="Vem beordrade att Overseer Maltorius skulle dö?",a="Overseer Oilfist, som enligt efterlysningen gav ordern.",al={"vem utfärdade efterlysningen","vem vill se maltorius död","vem beordrade mordet"}},{q="Vem tar emot beviset på Maltorius död?",a="Lookout Captain Lolo Longstriker i Searing Gorge. Maltorius huvud är beviset som efterfrågas.",al={"vem ska få maltorius huvud","vart ska maltorius huvud föras","lolo longstrikers plats"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Du har fått tag i en gigantisk, utsmyckad kudde som en gång tillhörde Chambermaid Pillaclencher. Evonice Sootsmoker i Searing Gorge vill säkert ha den.",h="Du har fått tag i en gigantisk, utsmyckad kudde som en gång tillhörde Chambermaid Pillaclencher.",kw={"chambermaid pillaclencher","evonice sootsmoker","kolla hur stor den är","kudde","searing gorge"},sec={{t="En kudde åt Evonice",b="Kudden som Chambermaid Pillaclencher hade är nu din. Evonice Sootsmoker vill säkert gärna lägga beslag på den. Ta med den till henne i Searing Gorge och se vad hon erbjuder dig för besväret."}},faq={{q="Vem vill ha Chambermaid Pillaclenchers kudde?",a="Evonice Sootsmoker i Searing Gorge väntade sig att vilja ha den väldigt gärna.",al={"vem ska jag ta kudden till","evonice sootsmoker kudde","vart ska kudden"}},{q="Var kommer kudden ifrån?",a="Den tillhörde Chambermaid Pillaclencher och är gigantisk och utsmyckad.",al={"kuddedrop","vem släpper kudden","chambermaids kudde"}},{q="Var hittar man Evonice Sootsmoker?",a="I Searing Gorge.",al={"evonices plats","var finns evonice sootsmoker","evonice searing gorge"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="Rite of Vision",s="Synriten är ett grundläggande andligt prov för unga tauren som lämnar Red Cloud Mesa och ger sig ut i det större Mulgore. För att skingra slöjan och få vägledning från förfädernas andar måste de invigda samla naturliga ingredienser och brygga Water of the Seers under Zarlman Two-Moons vakande öga i Bloodhoof Village.",h="Synriten är ett grundläggande andligt prov för unga tauren som lämnar Red Cloud Mesa och ger sig ut i det...",kw={"bärnstall","bloodhoof village","jordmodern","mulgore","synriten","water of the seers","brunnsstenar","zarlman two-moons"},ang={["class:Druid"]="Druider hyser stor vördnad för bärnstall och brunnsstenar och ser dem som direkta uttryck för växtligheten och de livgivande vattendrag som upprätthåller balansen i Mulgore.",["class:Shaman"]="Schamaner känner igen tillredningen av Water of the Seers som en traditionell jordningsritual. Den stämmer anden så att den kan läsa osynliga element innan den samtalar direkt med andar.",["race:Tauren"]="För tauren är Synriten en viktig kulturell milstolpe som knyter en blivande krigare, jägare eller mystiker till Jordmoderns och förfädernas andliga arv."},sec={{t="Landets ingredienser",b="Innan någon vision kan uppenbaras måste den invigde visa djup förståelse för naturens gåvor i Mulgore. Zarlman Two-Moons ber sökaren samla brunnsstenar nära de heliga gemensamma vattenbrunnarna och bärnstall som fallit vid rötterna till Mulgore gamla träd. Dessa naturelement är inte bara fysiska föremål. För tauren bär de på Jordmoderns slumrande magi och livskraft, redo att ledas in i ritualen."},{t="Att brygga Water of the Seers",b="När ingredienserna har samlats blandar Zarlman stenarna och bärnstallen till den kraftfulla Water of the Seers. När den dricks intill byns stamflamma klarnar sinnet och en eterisk vägledare kallas fram. Att följa denna uppenbarelse över slätterna är ritualens verkliga kärna. Det prövar den invigdes förmåga att röra sig mellan den fysiska världen och landets andliga viskningar."}},faq={{q="Vad är syftet med Synriten?",a="Synriten är ett andligt prov för tauren som nått vuxen ålder och söker sin väg. Genom att tillreda och dricka Water of the Seers lär sig den invigde att tala med andar och följa förfädernas omen över Mulgore slätter.",al={"vad är synriten","varför genomföra synriten","synritens syfte"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en tauren-schaman och siare i Bloodhoof Village. Han leder andliga prov för unga äventyrare, tillreder rituella brygder som Water of the Seers och tolkar Jordmoderns tecken.",al={"vem är zarlman","zarlman two-moons roll","uppdragsgivaren zarlman"}},{q="Var hittar man brunnsstenar och bärnstall?",a="Brunnsstenar samlas från marken nära sötvattenbrunnarna som finns utspridda över Mulgore. Bärnstall ligger vid foten av de stora, utbredda träden i det omgivande gräslandskapet.",al={"var hittar man bärnstall","brunnsstenarnas plats","ingredienser till synriten"}},{q="Vad händer efter att man druckit Water of the Seers?",a="Om man dricker brygden nära stamflamman öppnas den andliga synen och en spöklik djurvägledare visar sig. Sökaren måste följa anden över slätterna för att upptäcka nästa steg på sin heliga resa.",al={"vad händer härnäst i synriten","water of the seers effekt","fortsättning på visionsuppdraget"}},{q="Varför vördar tauren vattenbrunnarna så djupt?",a="Vatten är Mulgore livsblod och en dyrbar gåva från Jordmodern. Brunnarna är heliga gemensamma samlingsplatser som ger näring åt både landet och dess hjordar, så stenarna intill dem är laddade med andlig kraft.",al={"taurenernas vattenbrunnar","varför är brunnarna heliga","vatten i mulgore"}},{q="Leder det här uppdraget vidare till fler ritualer?",a="Ja. Uppgiften ingår i en ceremoni med flera steg. När Zarlman har tillrett Water of the Seers måste de invigda dricka den, följa visionen som visar sig och uppsöka äldre ledare runt om i Mulgore.",al={"nästa uppdrag i synriten","är synriten en uppdragskedja","taurenernas ritualkedja"}}},fx={["6b13f1a7"]={q="Varför vill Zarlman Two-Moons att detta görs?",a="Som stammens schaman ansvarar Zarlman Two-Moons för att vägleda lovande unga äventyrare genom taurenfolkets heliga traditioner. Han kan inte bara skänka dig andlig visdom. Du måste själv vinna Jordmoderns och dina förfäders välvilja genom att delta i ritualen, med början i att samla in landets heliga element.",al={"zarlman two-moons motiv","varför zarlman skickar dig","varför zarlman vill att du genomgår rite of vision"}},cc7474fb={q="Vad ska Well Stones användas till?",a="Well Stones samlas in från de heliga vattenbrunnarna runtom i Mulgore. De är genomsyrade av naturmagi från Jordmoderns renaste källor och är en av de viktiga ingredienser som Zarlman Two-Moons behöver för att brygga det mystiska Water of the Seers.",al={"syftet med well stones","varför behövs well stone","användning av well stone"}},["4efb8f2d"]={q="Vad ska Ambercorn användas till?",a="Ambercorn faller från de mäktiga träden i Mulgore och bär på landets växtlivs naturliga essens. Tillsammans med Well Stones, och efter att Zarlman Two-Moons låtit det dra, ger den de magiska egenskaper som krävs för att brygga Water of the Seers och skänka dig syner från förfäderna.",al={"syftet med ambercorn","vad ambercorn används till","varför skaffa ambercorn"}},["761f0189"]={q="Varför måste du samla ingredienserna i stället för att Zarlman Two-Moons gör det?",a="Rite of Vision är en personlig prövning i andlig utveckling, inte ett rutinärende. För att kommunicera med andarna måste du visa vördnad för landet och samklang med det genom att själv söka upp dess naturliga gåvor. Om någon annan samlade ingredienserna skulle ritualens heliga syfte gå förlorat.",al={"varför måste jag skaffa ambercorn","varför samlar inte zarlman in well stones","varför jag ska genomgå rite of vision"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="Rite of Vision",s="Synriten är höjdpunkten i en uråldrig prövning som unga taurer genomgår i Bloodhoof Village. Genom att dricka det heliga Water of the Seers vid stammens lägereld kallar de prövade fram en andlig vägvisare som leder dem mot deras öde.",h="Synriten är höjdpunkten i en uråldrig prövning som unga taurer genomgår i Bloodhoof Village.",kw={"bloodhoof village","spökvarg","mulgore","synriten","seer wiserunner","stamlägereld","water of the seers","zarlman two-moons"},ang={["class:Druid"]="Riten stärker vördnaden för naturen och den andliga ödmjukheten inför vägledning från djurformer.",["class:Shaman"]="Att följa en förfädersande i vargskepnad är en tidig läxa i att vandra mellan världar och förankrar en schamans band till andarna som vägleder horden.",["race:Tauren"]="För unga taurer är Synriten en djupt helig övergång till vuxenlivet som visar deras gemenskap med förfäderna och lydnad inför andlig vägledning."},sec={{t="Water of the Seers",b="Efter att ha samlat de nödvändiga ritualörterna och klarat de första trosprövningarna får den prövade Water of the Seers av byns schaman, Zarlman Two-Moons. Denna kraftfulla dryck måste intas framför den dånande stamlägerelden mitt i Bloodhoof Village. När den dricks med fokuserat och vördnadsfullt sinne vidgar det heliga vattnet drickarens sinnen bortom den fysiska synen och överbryggar slöjan mellan den materiella världen och andevärlden."},{t="Att följa Ghost Wolf",b="När brygden har druckits framträder en eterisk gestalt ur lågorna: en uråldrig spökvarg. Anden talar inte och slåss inte, utan travar tyst mot nordväst över Mulgore slätter. En sann prövad måste följa dess stilla väg, spåra dess färd bort från byn och djupt in bland de klippiga kullarna, där eremiten Seer Wiserunner väntar i avskild meditation."},{t="En vandring mot visdom",b="Att nå Seer Wiserunner vid mynningen till hans bergsgrotta innebär att synen har fullbordats. Vandringen över de gräsbevuxna kullarna prövar den prövades tålamod, tillit till förfädernas vägledning och samhörighet med Jordmodern. Den som klarar denna rit får som ung äventyrare rätt att genomgå det yttersta vuxenprovet: Visdomsriten."}},faq={{q="Vad händer när jag dricker Water of the Seers?",a="När du dricker vattnet nära stamlägerelden i Bloodhoof Village öppnas dina andliga sinnen. Strax efteråt visar sig en spöklik varg framför lågorna och vägleder dig.",al={"hur fungerar water of the seers","dricka water of the seers","vad gör vattnet"}},{q="Vart leder anden mig?",a="Den andliga vargen travar mot nordväst från Bloodhoof Village över kullarna i Mulgore och leder dig raka vägen till en klippgrotta där Seer Wiserunner bor.",al={"vart går spökvargen","vem leder vargen till","vargens mål"}},{q="Vem är Zarlman Two-Moons?",a="Zarlman Two-Moons är en framstående taurenschaman i Bloodhoof Village som har i uppgift att förbereda de prövade för andligt vuxenliv genom förfädernas riter och heliga brygder.",al={"vem ger synriten","zarlman two-moons roll"}},{q="Vem är Seer Wiserunner?",a="Seer Wiserunner är en äldre taurenmystiker som lever i begrundan bland klipporna nordväst om Bloodhoof Village. Prövade som följer sin andesyn finner honom och kan slutföra prövningen.",al={"vem är wiserunner","searen i grottan i mulgore"}},{q="Varför måste vattnet drickas nära stamlägerelden?",a="Stamlägerelden fungerar som ett heligt fäste för Bloodhoof Villages förfädersandar. Kombinationen av dess välsignade lågor och det heliga vattnet låter synen överbrygga till den vakna världen.",al={"varför stamlägereld","synriten vid lägerelden"}},{q="Vilken rit följer efter Synriten?",a="När de har fullbordat Synriten med Seer Wiserunner får de prövade i uppdrag att genomgå Visdomsriten, den sista andliga prövningen under deras första tid i Mulgore.",al={"nästa uppdrag efter synriten","what comes next"}}},fx={["659b3713"]={q="Varför vill Zarlman Two-Moons att jag genomgår Rite of Vision?",a="Som schaman i Bloodhoof Village vägleder Zarlman Two-Moons unga tauren längs deras förfäders heliga stigar. När du nu har samlat ingredienserna till Water of the Seers ger han dig brygden så att du kan kommunicera direkt med andarna, bevittna din syn och ta nästa steg mot att upptäcka ditt öde inom stammen.",al={"varför rite of vision","zarlman two-moons motiv","syftet med rite of vision"}},b8c8221c={q="Varför måste jag genomföra ritualen själv?",a="Earthmothers riter är djupt personliga prövningar av mognad och andligt uppvaknande. Ingen vakt eller äldste kan följa andarnas väg åt dig. Bara din egen ande kan ta emot vägledningen som ska visa dig din plats och uppgift bland taurenfolket.",al={"varför måste jag genomföra ritualen","varför jag ska genomgå rite of vision","varför kan inte någon annan genomföra ritualen"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="Fuel for the Zapping",s="På The Forgotten Coast i Feralas har Zorbin Fandazzle öppnat en ingenjörsverkstad mot bättre vetande, och de lokala elementalerna är en plåga. De är också en idealisk källa till råkraft för att förädla Ultra-Shrinker, och det är vattenelementalernas kärnor Zorbin vill ha.",h="På The Forgotten Coast i Feralas har Zorbin Fandazzle öppnat en ingenjörsverkstad mot bättre vetande, och de...",kw={"feralas","the forgotten coast","sea elemental","sea spray","ultra-shrinker","vattenelementkärna","zorbin fandazzle"},sec={{t="Kraft från bränningarna",b="Zorbin Fandazzle förbannar elementalismens tygellösa krafter och kallar kustens elementaler för plågoandar. Ändå räknar Zorbin också med dem som en idealisk källa till råkraft vid förädlingen av Ultra-Shrinker. Zorbin vill att du ger kustens Sea Elementals och Sea Sprays vad de tål, behåller deras vattenelementkärnor och tar med dem till Zorbin vid kajen."},{t="Zorbins tack",b="Zorbin är förtjust: kärnorna räcker till fortsatt arbete ett tag, och det finns nu färre elementaler längs kusten. Zorbin tillägger att det varit en anledning att gråta om nätterna att öppna verkstaden på vad som kanske är den sämsta plats man kan tänka sig. Zorbin visar sin tacksamhet med en betalning, trots att det anstränger Zorbins ekonomi."}},faq={{q="Vem efterfrågar elementalernas kärnor?",a="Zorbin Fandazzle, som driver en ingenjörsverkstad på The Forgotten Coast i Feralas, nära kajen där.",al={"vem ger bränsle till zappningen","zorbin fandazzle uppdragsgivare","vem startar fuel for the zapping"}},{q="Varför behöver Zorbin Fandazzle vattenelementkärnor?",a="Zorbin anser att de lokala elementalerna är en idealisk källa till råkraft för att förädla Ultra-Shrinker, och det är vattenelementalernas kärnor Zorbin vill ha.",al={"varför vattenelementkärnor","vad används kärnor till","bränsle till ultra-shrinker"}},{q="Var samlas elementalernas kärnor in?",a="Zorbin vill att du tar dem från Sea Elementals och Sea Sprays som strövar omkring på The Forgotten Coast i Feralas.",al={"var hittar man kärnor","sea elemental plats","var finns sea sprays"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="What the Flux?",s="Master Smith Burninate säger att Maltorius tog med sig receptet på Fiery Flux när han lämnade klanen. Det är värt mer än en obefläckad arkansk kristall. Burninate vill ha tillbaka de hemliga planerna och är säker på att de finns nära Maltorius, djupt nere i The Slag Pit.",h="Master Smith Burninate säger att Maltorius tog med sig receptet på Fiery Flux när han lämnade klanen.",kw={"burninate","the cauldron","fiery flux","maltorius","planer","searing gorge","the slag pit"},sec={{t="Det stulna receptet",b="Master Smith Burninate kallar Maltorius en förrädare som lämnade klanen med receptet på Fiery Flux. Burninate skulle slå vad om att receptet följde med Maltorius nya befordran bland Dark Irons, och vill ha tillbaka de hemliga planerna."},{t="Ner i The Slag Pit",b="Burninate är säker på att planerna finns nära Maltorius, nere i djupet av The Slag Pit. Secret Plans: Fiery Flux är det Burninate vill ha tillbaka."}},faq={{q="Vem stal receptet på Fiery Flux?",a="Maltorius, som Master Smith Burninate kallar en förrädare mot deras klan.",al={"vem stal receptet","vem tog planerna","vad förrädaren gjorde med flux"}},{q="Var finns de hemliga planerna?",a="Burninate tror att de finns nära Maltorius, djupt nere i The Slag Pit i The Cauldron.",al={"var finns planerna","plats för secret plans: fiery flux","var hittar man planerna för fiery flux"}},{q="Vem ber om att planerna ska hämtas tillbaka?",a="Det är Burninate, en mästersmed, som vill ha dem tillbaka.",al={"vem ger uppdraget what the flux","vad är flux uppdragsgivare"}},{q="Varför är planerna viktiga för Burninate?",a="Burninate säger att receptet på Fiery Flux är värt mer än en obefläckad arkansk kristall, och att det var klanens egen hemlighet.",al={"varför är fiery flux viktigt","betydelsen av receptet på fiery flux"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="Curse These Fat Fingers",s="Hansel Heavyhands i Searing Gorge kan inte längre dela ut stryk som förr, eftersom fingrarna har svullnat. Hansel ber dig gå och banka på de tunga krigsgolemerna åt dem.",h="Hansel Heavyhands i Searing Gorge kan inte längre dela ut stryk som förr, eftersom fingrarna har svullnat.",kw={"the cauldron","tjocka fingrar","hansel heavyhands","tunga krigsgolemer","searing gorge","blodkorvar från thelsamar"},sec={{t="Fingrar som prinskorvar",b="Hansel Heavyhands säger att klimatet i Gorge, med sin tunna luft, får Hansels fingrar att svullna tills de liknar enorma blodkorvar från Thelsamar. Därför kan Hansel inte längre dela ut stryk som förut och behöver att du sköter Hansels ärenden i stället."},{t="Först på listan",b="Först på Hansels dagordning står de tunga krigsgolemerna i Gorge, som Hansel vill att du bankar hårt på. Tjugo av dem ska förstöras. De strövar omkring i områdena runt The Cauldron, och du återvänder till Hansel när tillräckligt många har fallit."}},faq={{q="Vem är Hansel Heavyhands?",a="Någon i Searing Gorge vars svullna fingrar hindrar dem från att slåss, så de ber dig sköta bankandet.",al={"hansel heavyhands","vem ger uppdraget curse these fat fingers","vem ger uppdraget"}},{q="Varför kan Hansel inte slåss mot golemerna själv?",a="Hansel skyller på klimatet och den tunna luften i Gorge, som får fingrarna att svullna. De liknar dem vid enorma blodkorvar från Thelsamar.",al={"varför har hansel tjocka fingrar","lore om tjocka fingrar","hansels svullna händer"}},{q="Vilka fiender måste besegras?",a="Tjugo tunga krigsgolemer.",al={"vilka fiender ska jag slåss mot","vad vill hansel döda"}},{q="Var finns de tunga krigsgolemerna?",a="De strövar omkring i områdena runt The Cauldron i Searing Gorge.",al={"var finns golemerna","plats för tunga krigsgolemer"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="Fiery Menace!",s="Hansel Heavyhands säger att varje gång han vill ha en stund för att koppla av och tänka över sitt liv, ger makthavarna honom ännu ett uppdrag. Större lavaspindlar ställer till oreda i Searing Gorge, och han vill att du dödar tjugo av dem.",h="Hansel Heavyhands säger att varje gång han vill ha en stund för att koppla av och tänka över sitt liv, ger...",kw={"brännande hot","större lavaspindlar","hansel heavyhands","oilfist","searing gorge","spindlar"},sec={{t="Ännu ett uppdrag åt Hansel",b="Hansel Heavyhands klagar över att makthavarna aldrig lämnar honom i fred. Större lavaspindlar ställer till oreda, och han vill hellre att du sköter dödandet än att han gör det."},{t="De större lavaspindlarna",b="Oilfist säger att spindlarna skjuter eld från ett olämpligt ställe, vilket gör barnen upprörda. Hansel vill att tjugo större lavaspindlar dödas. De finns på platåerna och vid lavapölarna i Searing Gorge."}},faq={{q="Vem skickar dig efter spindlarna?",a="Hansel Heavyhands i Searing Gorge, som hoppades få en lugn stund men fick ännu ett uppdrag.",al={"uppdragsgivare","vem ger uppdrag","hansel"}},{q="Varför måste spindlarna dödas?",a="Större lavaspindlar ställer till oreda, och Oilfist säger att sättet de skjuter eld på gör barnen upprörda.",al={"varför döda spindlar","vad gjorde spindlarna","spindelproblem"}},{q="Vem berättade för Hansel om spindlarna?",a="Oilfist, som säger att spindlarna skjuter eld från ett olämpligt ställe.",al={"vem klagade på spindlarna","oilfist"}},{q="Hur många större lavaspindlar måste dödas?",a="Hansel ber dig ta kål på tjugo stycken.",al={"hur många spindlar","antal spindlar"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="Again With the Zapped Giants",s="Zorbin Fandazzle vet att du redan har samlat in rester, men kan alltid använda fler. Zorbin's Ultra-Shrinker står till ditt förfogande igen för jättarna i Feralas, och Zorbin väntar vid bryggorna på The Forgotten Coast. Zorbin kan inte betala i närheten av lika mycket den här gången, men lovar att sprida ordet om dina tjänster.",h="Zorbin Fandazzle vet att du redan har samlat in rester, men kan alltid använda fler.",kw={"feralas","the forgotten coast","jättar","miniatyriseringsrest","steamwheedle cartel","ultra-shrinker","zorbin fandazzle"},sec={{t="En repris med Ultra-Shrinker",b="Zorbin Fandazzle medger att du redan har samlat in rester, men kallar detta en repris och säger att det alltid finns plats för fler. Zorbin ber dig att zappa jättar i Feralas en gång till med Ultra-Shrinker och ta med tio miniatyriseringsrester från de förminskade jättarna till bryggorna på The Forgotten Coast. Eftersom Zorbin inte kan erbjuda i närheten av lika mycket i gengäld, lovar Zorbin att lovorda dina tjänster bland goblinvänner, som har rätt stora öron."},{t="Zorbins tack",b="Zorbin är överlycklig över att du har ställt upp igen, trots att betalningen är mindre än du är van vid. Zorbin insisterar på att ryktet om dina stordåd för goblinernas sak redan sprids genom Steamwheedle Cartels maktens korridorer."}},faq={{q="Vem ber om fler rester?",a="Zorbin Fandazzle, som väntar vid bryggorna på The Forgotten Coast i Feralas.",al={"uppdragsgivare","zorbin plats","vem ger uppdraget again with the zapped giants"}},{q="Vad hände före detta?",a="Det här följer på Zapped Giants, då du för första gången samlade in rester åt Zorbin Fandazzle.",al={"förutsättning","föregående uppdrag","vad ska jag göra först"}},{q="Hur samlar jag in resterna?",a="Zorbin's Ultra-Shrinker används på valfri sorts jätte i Feralas för att förminska den, och resterna finns på de förminskade jättarna.",al={"hur får jag tag på rester","miniatyriseringsrest","hur förminskar jag jättar"}},{q="Var hittar jag jättarna?",a="Jättarna finns längs Feralas västra kust.",al={"jättarnas plats","var finns jättarna i feralas","jättar vid forgotten coast"}},{q="Kommer Zorbin att ta emot fler rester en annan gång?",a="Zorbin säger att det alltid går att använda fler rester, så du är välkommen tillbaka med ytterligare tio.",al={"kan uppdraget upprepas","kan jag upprepa again with the zapped giants","upprepbart jätteuppdrag"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="Refuel for the Zapping",s="Zorbin Fandazzle behöver fler vattenelementarkärnor. Det är svårt att slå upp en butik på The Forgotten Coast, så ersättningen blir mindre, men Zorbin lovar att berätta för alla inom hörhåll om din hjälp och säger sig ha vänner i Cartel.",h="Zorbin Fandazzle behöver fler vattenelementarkärnor.",kw={"feralas","the forgotten coast","sea elemental","sea spray","steamwheedle cartel","vattenelementarkärna","zorbin fandazzle"},sec={{t="Mer av samma",b="Zorbin Fandazzle skämtar om den heroiska bedriften att samla slem inifrån elementarvarelser och undrar om du vill ha mer av samma. Bortsett från dramatiken behöver Zorbin fler vattenelementarkärnor. Att etablera butiken här är en desperat affär, så det finns lite att ge i gengäld, men Zorbin lovar att berätta för alla inom hörhåll hur du hjälpte till och säger att du kan lita på det eftersom Zorbin känner folk i Cartel. Sex kärnor behövs. Ta dem från Sea Elementals och Sea Sprays på The Forgotten Coast och ta dem till Zorbin nära kajen."},{t="Zorbins tack",b="Zorbin är nöjd och medger att betalningen kanske inte är den högsta du någonsin får för ett sådant arbete. Zorbins kamrater i Steamwheedle Cartel får höra om dina insatser, och om du vill ha mer att göra behöver Zorbin fortfarande fler kärnor och liknande saker."}},faq={{q="Vem efterfrågar vattenelementarkärnorna?",a="Zorbin Fandazzle, som finns vid kajen på The Forgotten Coast i Feralas.",al={"vem ger uppdraget","vem är zorbin fandazzle","var finns zorbin"}},{q="Varifrån kommer vattenelementarkärnorna?",a="De tas från Sea Elementals och Sea Sprays på The Forgotten Coast i Feralas.",al={"var får man kärnor","plats för vattenelementarkärna","vilka fiender släpper kärnor"}},{q="Varför behöver Zorbin Fandazzle fler kärnor?",a="Zorbin säger bara att det behövs fler vattenelementarkärnor, samtidigt som Zorbin kämpar för att få en butik på plats vid kusten.",al={"varför vill zorbin ha kärnor","zorbin fandazzles motiv","vad används kärnorna till"}},{q="Vad hände före detta?",a="Det följer på Fuel for the Zapping, då du först samlade elementarkärnor åt Zorbin.",al={"föregående uppdrag","förutsättningsuppdrag","vilket uppdrag kommer först"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurs? Whateverosaur is More Like It",s="Hansel Heavyhands säger att hans liktornar har liktornar, och han kan inte döda något med fötterna i så bedrövligt skick. Scrange och Burninate bad honom rensa The Slag Pit från incendosaurs, så han skickar dig i stället för att döda tjugo.",h="Hansel Heavyhands säger att hans liktornar har liktornar, och han kan inte döda något med fötterna i så...",kw={"burninate","the cauldron","hansel heavyhands","incendosaur","scrange","searing gorge","the slag pit"},sec={{t="Liktornar på liktornar",b="Hansel Heavyhands är inte i skick att slåss. Scrange och Burninate bad honom döda incendosaurs så att expeditionsgrupper kan ta sig ner i The Slag Pits lavapölar och utforska dem. Hansel lämnar över arbetet till dig."},{t="Lavapölarna",b="Incendosaurs håller till i lavapölarna nere i The Slag Pit, inne i The Cauldron. Hansel vill att tjugo dödas och vill inte se dig igen förrän du har gjort det."}},faq={{q="Vem är Hansel Heavyhands?",a="Det är han som ger dig det här uppdraget i Searing Gorge. Scrange och Burninate bad honom ta hand om incendosaurs, men han kan inte på grund av sina liktornar.",al={"hansel heavyhands","vem ger uppdraget","vem ger det här uppdraget"}},{q="Varför behöver incendosaurs rensas bort?",a="Scrange och Burninate vill att expeditionsgrupper ska utforska The Slag Pits lavapölar. Det sägs att incendosaurs där orsakar alla möjliga problem.",al={"varför döda incendosaurs","incendosaurernas syfte","varför rensa the slag pit"}},{q="Var hittar man incendosaurs?",a="Nere i lavapölarna i The Slag Pit, inne i The Cauldron.",al={"incendosaurernas plats","var ligger the slag pit","var finns lavapölarna"}},{q="Varför jagar inte Hansel dem själv?",a="Han säger att hans liktornar har liktornar, och att fötterna är i alltför bedrövligt skick för att döda något.",al={"varför slåss inte hansel","hansels fötter","hansels liktornar"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass",s="En efterlysning gäller två stulna föremål: ett mörkt järnmunstycke och en Lookout's Spyglass. Thorium Brotherhood är säkra på att skrupelfria, avundsjuka Dark Iron-dvärgar från Searing Gorge tog dem, och den som hittar dem ska lämna dem till Taskmaster Scrange mot betalning.",h="En efterlysning gäller två stulna föremål: ett mörkt järnmunstycke och en Lookout's Spyglass.",kw={"dark iron","scrange","searing gorge","smide","kikare","thorium brotherhood","munstycke"},sec={{t="Stöldgods",b="Efterlysningen kallar kikaren ett fint redskap för utkikare och munstycket ett smidesredskap som inte kan ersättas. Det enda man vet är att Dark Iron-dvärgar definitivt tog dem. Den som hittar dem ska återlämna dem till Taskmaster Scrange."}},faq={{q="Vem satte upp efterlysningen?",a="Efterlysningen kommer från Thorium Brotherhood, som är säkra på att Dark Iron-dvärgar tog föremålen.",al={"vem vill ha de stulna föremålen","vem gav uppdraget","uppdragsgivare för stulet smidesmunstycke"}},{q="Vem stal redskapen?",a="Thorium Brotherhood är säkra på att det var skrupelfria och avundsjuka Dark Iron-dvärgar från Searing Gorge.",al={"vem tog munstycket","vem stal kikaren","vem har de stulna föremålen"}},{q="Vem ska få tillbaka föremålen?",a="Taskmaster Scrange i Searing Gorge.",al={"var lämnar jag in det här","vem är taskmaster scrange","vem får kikaren"}},{q="Vad används de stulna föremålen till?",a="Munstycket är ett smidesredskap som inte kan ersättas, och kikaren är ett värdefullt övervakningsredskap för utkikare.",al={"vad är ett smidesmunstycke","varför vill brödraskapet ha munstycket","vad gör kikaren"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="JOB OPPORTUNITY: Culling the Competition",s="En anslagstavla meddelar att Taskmaster Scrange söker dugliga arbetare som kan slå ut konkurrenterna i Searing Gorge. Arbetet går ut på att döda Dark Iron Taskmasters och Dark Iron Slavers tills kläderna är tillräckligt blodiga, och sedan återvända till Scrange.",h="En anslagstavla meddelar att Taskmaster Scrange söker dugliga arbetare som kan slå ut konkurrenterna i...",kw={"slå ut konkurrenterna","dark iron slaver","dark iron taskmaster","ledig tjänst","searing gorge","taskmaster scrange"},sec={{t="En ledig tjänst",b="Scrange vill att sökande ger sig ut genom ravinen och slaktar de Dark Iron Taskmasters och Dark Iron Slavers de stöter på: femton av varje. Kom tillbaka när kläderna är tillräckligt blodiga. Du märker när det är dags, och du ska inte fråga."}},faq={{q="Vem erbjuder det här jobbet?",a="Taskmaster Scrange i Searing Gorge, som vill ha hjälp med att slå ut konkurrenterna.",al={"vem erbjuder det här uppdraget","vem vill få taskmasters dödade","vem är taskmaster scrange"}},{q="Vilka fiender måste dödas?",a="Femton Dark Iron Taskmasters och femton Dark Iron Slavers.",al={"vad ska jag döda","mål för ledig tjänst","vilka är konkurrenterna"}},{q="Hur ser Scrange att arbetet är klart?",a="På klädernas skick. Scrange väger dig med och utan kläderna för att vara säker.",al={"hur bevisar jag dödandena","krav på blodiga kläder","hur kontrollerar scrange"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="Rite of Wisdom",s="Visdomsriten är det avslutande provet i Jordemoderns traditionella riter, som unga äventyrare genomgår i Mulgore. Efter att ha renat sin syn genom Synsriten reser de sökande till Red Rocks heliga gravplats för att tala med en Ancestral Spirit och ta emot de dödas välsignelse.",h="Visdomsriten är det avslutande provet i Jordemoderns traditionella riter, som unga äventyrare genomgår i...",kw={"ancestral spirit","mulgore","red rocks","visdomsriten","jordemoderns riter","seer wiserunner","thunder bluff","water of the seers"},ang={["class:Druid"]="Riten visar balansen mellan de levandes värld och den eviga cykel som Jordemodern vakar över, och förankrar unga druider i deras plikt mot landet.",["class:Shaman"]="Att tala direkt med en Ancestral Spirit stärker den grundläggande shamanplikten att hedra de döda och hålla tron på andarna som vakar över Mulgore.",["race:Tauren"]="För shu'halo är det högtidliga ögonblicket då de tar emot ansvaret från förfäderna vid Red Rocks kulmen på övergången till vuxenlivet och på att bli accepterade bland stammens äldste."},sec={{t="Provet vid Red Rocks",b="Efter att ha klarnat sin varseblivning genom Synsriten skickas unga väktare öster om Thunder Bluff, mot Red Rocks. Denna uråldriga gravplats rymmer de fysiska kvarlevorna och de dröjande andarna efter dem som kämpade och dog för att skapa en fredlig tillvaro i Mulgore. För att klara provet måste du närma dig viloplatsen med vördnad och söka gemenskap, samtidigt som du möter de territoriella hot som strövar omkring i kullarna för att söka de ärade dödas råd."},{t="Att ta emot ansvaret",b="På toppen av Red Rocks är mötet med en Ancestral Spirit inte ett prov på stridsstyrka, utan på andlig beredskap och kontinuitet. Andarna som vilar där representerar den generation som kämpade sida vid sida med Cairne Bloodhoof för att grunda Thunder Bluff och skydda stammarna. Genom att ta emot deras välsignelse ärver den sökande officiellt den högtidliga plikten att skydda staden och förtjänar sin plats som erkänd vuxen och försvarare, värdig att stolt träda in i Thunder Bluff."}},faq={{q="Vad är syftet med Visdomsriten?",a="Visdomsriten fullbordar Jordemoderns riter och förenar ungdomens visionära gemenskap med vuxenlivets högtidliga ansvar. Genom att få förfädernas andars välsignelse visar de sökande att de respekterar föregångarnas uppoffringar och är redo att försvara Thunder Bluff.",al={"varför göra visdomsriten","vad gör visdomsriten","visdomsritens syfte"}},{q="Vem skickar dig på Visdomsriten?",a="Seer Wiserunner, i sin grotta nordväst om Bloodhoof Village, skickar iväg invigda på detta prov när de har klarat Synsriten och druckit av Water of the Seers.",al={"vem ger visdomsriten","var börjar jag visdomsriten"}},{q="Var hittar du Ancestral Spirit?",a="Ancestral Spirit finns vid Red Rocks, en uråldrig tauren-gravplats bland de klippiga höjderna rakt öster om Thunder Bluff.",al={"var finns ancestral spirit","var är anden","var hittar jag ancestral spirit"}},{q="Varför måste du först genomgå Synsriten?",a="Endast de som har druckit av Water of the Seers och fått sin andliga syn renad kan uppfatta och ta emot de uråldriga andarnas välsignelse vid Red Rocks.",al={"varför göra synsriten först","krav för synsriten","krav på water of the seers"}},{q="Vad händer när du har fullbordat Visdomsriten?",a="När de invigda har vunnit förfädernas godkännande får de instruktioner om att göra sin officiella färd till Thunder Bluffs höga höjder.",al={"vad händer efter visdomsriten","nästa uppdrag efter visdomsriten"}},{q="Vilka varelser hotar området vid Red Rocks?",a="Den heliga gravplatsen vid Red Rocks har trängts in på av aggressiva Palemane gnolls, som lurar längs de klippiga stigarna upp till den uråldriga gravplatsen.",al={"fiender vid red rocks","vad vaktar red rocks","gnolls vid red rocks"}}},fx={["740e2883"]={q="Varför skickar Seer Wiserunner dig på Visdomens rit?",a="Seer Wiserunner vägleder lovande unga taurer genom Earthmothers traditionella riter. Efter att ha sett dig uthärda synen från Water of the Seers skickar han dig till Red Rocks, där du kan få förfädernas välsignelse. För Wiserunner och de äldre säkerställer riten att endast de som är andligt redo och erkända av förfäderna välkomnas till Thunder Bluff som stammens beskyddare.",al={"seer wiserunners motiv","varför visdomens rit","varför skicka mig på visdomens rit"}},["8728f84f"]={q="Varför måste du gå i stället för att Seer Wiserunner går själv?",a="Visdomens rit är en personlig övergångsrit, inget ärende som någon annan kan utföra åt dig. För att vinna de äldres förtroende och rätten att gå in i Thunder Bluff måste du själv söka upp Ancestral Spirit vid Red Rocks och visa den andliga klarhet du fått från Water of the Seers. Uppdraget att skydda staden kan bara tilldelas dig direkt.",al={"varför jag på visdomens rit","varför går inte seer wiserunner själv","varför måste jag söka upp ancestral spirit"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="Zukk'ash Infestation",s="På Camp Mojache har Hadoken Swiftstrider hört talas om insektsliknande varelser, Zukk'ash, söder om gnollerna. Om de hetsar upp gnollerna till vansinne är de ett lika stort hot som gnollerna, kanske större. Du skickas in i deras hem, The Writhing Deep, för att minska deras antal och ta med tjugo ryggsköldar tillbaka.",h="På Camp Mojache har Hadoken Swiftstrider hört talas om insektsliknande varelser, Zukk'ash, söder om gnollerna.",kw={"camp mojache","ryggsköld","feralas","gnoller","hadoken swiftstrider","insekter","the writhing deep","zukk'ash"},sec={{t="Fienden söder om gnollerna",b="Hadoken Swiftstrider tror att fienden söder om gnollerna är en ras av insektsliknande varelser. Om de kan tänka spelar knappt någon roll för Hadoken. Om de driver gnollerna till vansinne mot Camp Mojache är de lika farliga som gnollerna själva, eller farligare. Du ska ta dig djupt in i deras tillhåll, som kallas The Writhing Deep, och minska deras antal. Tjugo Zukk'ash-ryggsköldar blir ditt bevis, och Hadoken vill höra vad du hittar."},{t="Hadokens dom",b="När du återvänder är Hadoken nöjd. Inget mindre än en fullskalig invasion kan få slut på Zukk'ash-närvaron, men du har gett lägret tid att utforma en ordentlig strategi. Ryggsköldarna ska analyseras, eftersom lägret måste lära sig allt om dessa varelser. Det här har tyvärr blivit ett mycket större problem än någon hade väntat sig."}},faq={{q="Vem skickar dig efter Zukk'ash?",a="Hadoken Swiftstrider, vid Camp Mojache i Feralas.",al={"uppdragsgivare","hadoken swiftstrider","vem startar zukk'ash infestation"}},{q="Vad är Zukk'ash?",a="Hadoken tror att de är en ras av insektsliknande varelser söder om gnollerna. Om de kan tänka spelar ingen roll för Hadoken, bara att de kanske driver gnollerna till vansinne.",al={"vad är zukk'ash","zukk'ash-insekter","insekter i the writhing deep"}},{q="Var ligger The Writhing Deep?",a="Det är där Zukk'ash-insekterna håller till, söder om gnollerna.",al={"the writhing deeps plats","var ligger the writhing deep","var finns insekterna"}},{q="Varför vill Hadoken ha Zukk'ash-ryggsköldar?",a="Hadoken vill ha ryggsköldarna som bevis på ditt arbete mot Zukk'ash.",al={"varför ryggsköldar","användning av zukk'ash-ryggsköld","ryggsköldarnas syfte"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="Stinglasher",s="Under spaningen av The Writhing Deep upptäckte en av Hadoken Swiftstriders spejare en jättelik insekt, långt större än de andra, som strövade omkring i den förvridna terrängen. Den har fått namnet Stinglasher, och Hadoken vill att du fäller den och för tillbaka dess sekretkörtlar till Camp Mojache.",h="Under spaningen av The Writhing Deep upptäckte en av Hadoken Swiftstriders spejare en jättelik insekt, långt...",kw={"camp mojache","feralas","körtlar","hadoken swiftstrider","insekt","stinglasher","the writhing deep","zukk'ash"},sec={{t="En jätte bland insekterna",b="En spejare i The Writhing Deep såg en insekt som var mycket större än de andra och strövade omkring i den förvridna terrängen. Den verkar också utstråla en aura som skiljer den från de andra. Den har fått namnet Stinglasher. Dess inälvor skulle vara ovärderliga att studera medan Hadoken kommer på hur det nya hotet ska hanteras, så Hadoken vill att du skär ut dess sekretkörtlar och för dem direkt till Camp Mojache."},{t="Hadokens tack",b="Hadoken är mycket imponerad. Om Stinglasher verkligen är en av de starkaste insekterna kommer det med tiden att bli värdefullt att studera besten, och Hadokens uppdrag är att se till att lägret försvarar sig tillräckligt länge för att dra nytta av det. En belöning i mynt ges, tillsammans med tack från hela lägret."}},faq={{q="Vem skickar dig efter Stinglasher?",a="Hadoken Swiftstrider, i Camp Mojache i Feralas.",al={"uppdragsgivare","vem ger stinglasher","hadoken swiftstrider"}},{q="Var hittar man Stinglasher?",a="Stinglasher strövar omkring i den förvridna terrängen i The Writhing Deep.",al={"stinglashers plats","var finns stinglasher","writhing deeps plats"}},{q="Vad skiljer Stinglasher från de andra insekterna?",a="En spejare rapporterade om en jättelik insekt, som verkar utstråla en aura som de andra saknar.",al={"varför stinglasher","vad är stinglasher","stinglashers aura"}},{q="Varför vill Hadoken ha Stingslashers körtlar?",a="Hadoken säger att det vore ovärderligt att studera dess inälvor medan en plan mot det nya hotet utarbetas.",al={"varför samla körtlar","stinglashers körtlar syfte"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="Zukk'ash Report",s="Hadoken Swiftstrider säger att du har gjort dubbelt så bra ifrån dig mot Zukk'ash-insekterna som hotar Camp Mojache, men faran är långt ifrån över. En sista tjänst för horden: ta med ett dokument med allt ni lärt er om Zukk'ash till Orgrimmar, till Zilzibin Drumlore.",h="Hadoken Swiftstrider säger att du har gjort dubbelt så bra ifrån dig mot Zukk'ash-insekterna som hotar Camp...",kw={"camp mojache","drag","feralas","hadoken swiftstrider","orgrimmar","silithider","zilzibin drumlore","zukk'ash report"},sec={{t="Ett dokument till Drag",b="Hadoken Swiftstrider har ett dokument som sammanfattar allt lägret lärt sig om Zukk'ash-insekterna. Faran de utgör är långt ifrån över, och Hadoken ber dig ta med det till Orgrimmar. Där, i Drag, bor Zilzibin Drumlore, en expert på främmande varelser som dessa, och Hadoken hoppas att kunskapen som samlats hittills kommer till nytta."},{t="Expertens dom",b="Zilzibin har väntat på rapporten. Han kallar varelserna du mötte för ett uråldrigt hot som horden gång på gång väljer att ignorera, och säger att Hadoken gjorde klokt i att skicka både rapporten och dig. Zukk'ash är inget annat än varelser som kallas silithider. Vissa tror att de är ett tanklöst irritationsmoment, men Zilzibin försäkrar dig om att de utgör ett mycket större hot än något Alliansen kan uppbåda."}},faq={{q="Vem skickar rapporten till Orgrimmar?",a="Hadoken Swiftstrider vid Camp Mojache i Feralas ger dig dokumentet.",al={"vem ger zukkashrapporten","vem startar zukkashrapporten","uppdragsgivare"}},{q="Till vem överlämnas rapporten?",a="Till Zilzibin Drumlore, som bor i Drag i Orgrimmar.",al={"vart går rapporten","vem får zukkashrapporten","drumlores plats"}},{q="Varför förs dokumentet till Orgrimmar?",a="Zilzibin Drumlore är expert på främmande varelser som Zukk'ash, och Hadoken hoppas att kunskapen som lägret samlat kommer till nytta.",al={"varför skicka till orgrimmar","rapportens syfte"}},{q="Vad hände före den här leveransen?",a="Den följer på dina insatser mot Zukk'ash-insekterna i Zukk'ash Infestation och Stinglasher.",al={"tidigare uppdrag","förkunskapskrav"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="Improved Quality",s="Pratt McGrubben har hört talas om ännu finare hudar än de senaste. I norra Feralas, inne i Rage Scar Hold, strövar en annan flock yetier, tuffare än dem du mötte tidigare. Tio av deras hudar behövs vid Feathermoon Stronghold.",h="Pratt McGrubben har hört talas om ännu finare hudar än de senaste.",kw={"feathermoon stronghold","feralas","improved quality","pratt mcgrubben","rage scar hold","thorium","yetihud","yetier"},sec={{t="En tuffare flock yetier",b="Efter The Mark of Quality har Pratt McGrubben fått ett tips om en ännu finare tillgång på hudar. I norra Feralas, inne i Rage Scar Hold, lever en annan flock yetier, tuffare än dem du mötte tidigare. Pratt McGrubben betalar generöst för tio av deras hudar, om du tar dem tillbaka till Feathermoon Stronghold så att saken kan avgöras. Om de håller samma kvalitet som hudarna från Feral Scar kan de visa sig vara lika tåliga som thorium."},{t="Pratts tack",b="Hudarna är ännu bättre än väntat. Pratt McGrubben kan redan se att de blir mycket hårdare när de har garvats ordentligt, och som tack ger han dig en av sina senaste skapelser."}},faq={{q="Vem efterfrågar hudar från Rage Scar-yetierna?",a="Pratt McGrubben, vid Feathermoon Stronghold i Feralas.",al={"vem ger improved quality","uppdragsgivare för improved quality","pratt mcgrubben"}},{q="Var lever Rage Scar-yetierna?",a="Inne i Rage Scar Hold, i norra Feralas.",al={"rage scar-yetiernas plats","var ligger rage scar hold","var får man tag på rage scar-hudar"}},{q="Hur många hudar behövs?",a="Pratt McGrubben vill ha tio hudar från Rage Scar-yetierna.",al={"hur många yetihudar","föremål som behövs för improved quality"}},{q="Vad kom före det här?",a="Det följer på The Mark of Quality, där du tog hand om den första flocken yetier.",al={"förutsättningsuppdrag","vilket uppdrag leder till improved quality","föregående uppdrag"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="Improved Quality",s="Jangdor Swiftstrider har hört talas om hudar som är ännu bättre än de förra. Längst uppe i norra Feralas, inne i Rage Scar Hold, strövar en annan flock yetier, tuffare än dem du mötte tidigare. Tio av deras hudar behövs i Camp Mojache.",h="Jangdor Swiftstrider har hört talas om hudar som är ännu bättre än de förra.",kw={"camp mojache","feralas","förbättrad kvalitet","jangdor swiftstrider","rage scar hold","rage scar-yeti","yetihudar"},sec={{t="En tuffare flock yetier",b="Efter The Mark of Quality har Jangdor Swiftstrider fått ett spår till en ännu finare tillgång på hudar. Längst uppe i norra Feralas, inne i Rage Scar Hold, lever en annan flock yetier, tuffare än dem du mötte tidigare. Jangdor Swiftstrider betalar bra för tio av deras hudar, om du tar med dem tillbaka till Camp Mojache och gör upp saken. Om de håller samma kvalitet som Feral Scar-hudarna kan de visa sig vara lika tåliga som thorium."},{t="Jangdors tack",b="Hudarna är ännu bättre än väntat. Jangdor Swiftstrider kan redan se att de blir mycket hårdare när de har garvats ordentligt, och som tack ger han dig ett av sina senaste alster."}},faq={{q="Vem efterfrågar Rage Scar-yetiernas hudar?",a="Jangdor Swiftstrider i Camp Mojache i Feralas.",al={"vem ger förbättrad kvalitet","uppdragsgivare för förbättrad kvalitet","jangdor swiftstrider"}},{q="Var lever Rage Scar-yetierna?",a="Inne i Rage Scar Hold, i norra Feralas.",al={"rage scar-yetiernas plats","var ligger rage scar hold","var får man tag på rage scar-hudar"}},{q="Hur många hudar behövs?",a="Jangdor Swiftstrider vill ha tio hudar från Rage Scar-yetier.",al={"hur många yetihudar","föremål som behövs för förbättrad kvalitet"}},{q="Vad hände före det här?",a="Det följer på The Mark of Quality, då du tog itu med den första flocken yetier.",al={"förutsättningsuppdrag","vilket uppdrag leder till förbättrad kvalitet","föregående uppdrag"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Pristine Yeti Hide",s="Du har fått tag på ett yetiskinn som är ovanligt tjockt och segt, segare än något du sett från yetierna i Rage Scar. Pratt McGrubben vid Feathermoon Stronghold söker yetiskinn, och det här kan intressera honom.",h="Du har fått tag på ett yetiskinn som är ovanligt tjockt och segt, segare än något du sett från yetierna i...",kw={"feathermoon stronghold","feralas","pratt mcgrubben","orört yetiskinn","rage scar","yetiskinn"},sec={{t="Ett ovanligt skinn",b="Skinnet är orört och tydligt tjockare och kraftigare än skinnen från yetierna i Rage Scar. Pratt McGrubben vid Feathermoon Stronghold i Feralas vill köpa yetiskinn, så det här är värt att ta med till honom."},{t="Pratts reaktion",b="Pratt är häpen och undrar högt om det här kan vara det bästa yetiskinn som finns. Han betalar dig för det, mer än ett vanligt skinn brukar inbringa, och tror att något särskilt kan tillverkas av det."}},faq={{q="Vem vill ha det orörda yetiskinnet?",a="Pratt McGrubben vid Feathermoon Stronghold i Feralas, som vill köpa yetiskinn.",al={"vem tar emot orört yetiskinn","var ska jag lämna yetiskinnet","pratt mcgrubben yetiskinn"}},{q="Vad gör skinnet speciellt?",a="Det är ovanligt tjockt och segt, och överträffar till och med skinnen från yetierna i Rage Scar.",al={"var får man orört yetiskinn","vad gör skinnet speciellt","yetiskinn i feralas"}},{q="Var finns Pratt McGrubben?",a="Vid Feathermoon Stronghold i Feralas.",al={"var finns pratt mcgrubben","var lämnar man orört yetiskinn"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="Restoring Fiery Flux Supplies via Kingsblood",s="Efter What the Flux? vill Master Smith Burninate fylla på det sinande förrådet av Fiery Flux i Searing Gorge. Burninate vill ha incendosaur scales, Kingsblood och kol, och tar emot allt du kan erbjuda.",h="Efter What the Flux?",kw={"burninate","kol","fiery flux","incendosaur","kingsblood","searing gorge","thorium brotherhood"},sec={{t="Fiery Flux sökes",b="Master Smith Burninate har inte tid med tomt prat. Förrådet av Fiery Flux börjar sina, och Burninate ber om incendosaur scales, Kingsblood och kol: två scales, fyra Kingsblood och kol. Burninate tar emot allt du kan erbjuda."}},faq={{q="Vem ber om de här varorna?",a="Master Smith Burninate i Searing Gorge, som tar emot varorna personligen.",al={"vem ger det här uppdraget","burninate fiery flux","var lämnar man in"}},{q="Vilka material vill Burninate ha?",a="Två incendosaur scales, fyra Kingsblood och lite kol.",al={"vilka föremål behöver jag","material till fiery flux","föremål att lämna till burninate"}},{q="Vad kom före den här begäran?",a="Steget som heter What the Flux?, som Burninate gav dig tidigare.",al={"förutsättning för uppdraget","föregående uppdrag fiery flux","förutsättningen what the flux"}},{q="Varför vill Burninate ha de här varorna?",a="Burninate säger att förrådet av Fiery Flux sinar och vill fylla på det.",al={"varför fiery flux","burninates motiv"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="Perfect Yeti Hide",s="Du har hittat ett yetiskinn som mycket väl kan vara perfekt: ovanligt tjockt och slitstarkt, bättre än skinnen från yetierna i Rage Scar. Jangdor Swiftstrider på Camp Mojache letar efter yetiskinn.",h="Du har hittat ett yetiskinn som mycket väl kan vara perfekt: ovanligt tjockt och slitstarkt, bättre än...",kw={"camp mojache","feralas","jangdor swiftstrider","perfect yeti hide","rage scar","yetiskinn"},sec={{t="Ett skinn att visa upp",b="Skinnet är tydligt tjockare och tåligare än skinnen från yetierna i Rage Scar. Jangdor Swiftstrider på Camp Mojache i Feralas vill köpa yetiskinn, så det här är värt att ta dit."},{t="Jangdors omdöme",b="Jangdor blir överlycklig och kallar det det finaste yetiskinn han någonsin har sett. En passande belöning är på sin plats, mer än han brukar betala för ett enda skinn, och han är övertygad om att något särskilt kan tillverkas av det."}},faq={{q="Vem är intresserad av Perfect Yeti Hide?",a="Jangdor Swiftstrider på Camp Mojache i Feralas, som vill köpa yetiskinn.",al={"vem vill ha skinnet","vem lämnar in perfect yeti hide","jangdor yetiskinn"}},{q="Varför anses det här skinnet vara speciellt?",a="Det är ovanligt tjockt och slitstarkt och kan mycket väl vara perfekt, bättre än skinnen från yetierna i Rage Scar.",al={"varför är det perfekt","vad gör skinnet speciellt"}},{q="Var finns Jangdor Swiftstrider?",a="På Camp Mojache i Feralas.",al={"var finns jangdor swiftstrider","vart ska perfect yeti hide tas"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="Journey into Thunder Bluff",s="Journey into Thunder Bluff är den avslutande pilgrimsfärden som markerar slutet på en ung hjältes prövningar i Mulgore. Efter att ha fullgjort Earthmothers heliga riter under andarnas ledning får äventyraren audiens hos taurenfolkets överhövding, Cairne Bloodhoof.",h="Journey into Thunder Bluff är den avslutande pilgrimsfärden som markerar slutet på en ung hjältes prövningar...",kw={"ancestral spirit","cairne bloodhoof","high rise","journey into thunder bluff","mulgore","earthmothers riter","thunder bluff"},ang={["faction:Horde"]="Att tauren gärna välkomnar allierade folk som fullgör deras heliga traditioner visar på den ömsesidiga respekten som håller det unga Horde samman.",["race:Tauren"]="För en ung tauren är stunden framför Cairne Bloodhoof efter Earthmothers riter den avgörande tröskeln till vuxenlivet och stamheder."},sec={{t="En avslutad övergångsrit",b="Innan någon resenär eller ung krigare kan hävda att de har bevisat sitt värde i Mulgore måste de genomgå Earthmothers uråldriga riter. Prövningarna sätter styrka, syn och visdom på prov över slätterna och vid landets förfädersplatser. När Ancestral Spirit har bekräftat den sista riten anses initianden värdig att träda in i Thunder Bluff, inte som en vanlig besökare utan som en hedrad försvarare av taurenfolket."},{t="Upp till High Rise",b="Uppdraget leder resenären från den heliga mark där andarna vandrar rakt till Thunder Bluffs höga höjder. Staden ligger på mesas och är en fredens fyr, uthuggen ur röd sten och sammanbunden av svepande repbroar och väldiga träplattformshissar. Där väntar taurenfolkets överhövding, Cairne Bloodhoof, på High Rise för att personligen välkomna dem som har vandrat förfädernas väg."}},faq={{q="Vem skickar dig på den här resan?",a="Du får uppdraget av en Ancestral Spirit efter att du har fullgjort Rite of Wisdom, det sista steget i Earthmothers traditionella riter.",al={"vem ger uppdraget","uppdrag från ancestral spirit","uppdragsgivare"}},{q="Var hittar jag Cairne Bloodhoof?",a="Cairne Bloodhoof finns på High Rise, den centrala upphöjda mesan i Thunder Bluff, med utsikt över de omgivande röda platåerna och slätterna.",al={"var finns cairne","var är cairne","ledare i thunder bluff"}},{q="Vad innebär det att fullgöra det här uppdraget?",a="Det markerar den formella avslutningen på startäventyren i Mulgore. När du visar dig för Cairne blir du erkänd av taurenfolkets ledning och redo att ta dig an uppgifter för hela Horde.",al={"varför besöka cairne","riternas betydelse","betydelsen av resan till thunder bluff"}},{q="Är det bara tauren som genomför den här resan?",a="Även om det är en djupt traditionell övergångsrit för tauren får alla medlemmar i Horde som visar sin hängivenhet genom Earthmothers riter samma ära och skickas för att träffa överhövdingen.",al={"kan orcher göra detta","vem kan göra resan till thunder bluff","folk"}},{q="Vad händer när jag har talat med Cairne?",a="Cairne välkomnar dig till sitt hem, erkänner dina bedrifter och visar vägen vidare in i de större konflikter som Horde står inför i Kalimdor.",al={"nästa uppdrag","vad händer efter cairne","efter journey into thunder bluff"}},{q="Hur tar man sig till High Rise i Thunder Bluff?",a="Ta de stora mekaniska hissarna från slätterna nedanför upp till mesorna. Gå sedan över rep- och träbroarna mot den centrala plattformen på High Rise, där överhövdingens hydda står.",al={"ta sig till high rise","hur tar man sig till cairne","hissar i thunder bluff"}}},fx={["74afb15b"]={q="Varför skickar Ancestral Spirit dig till Thunder Bluff?",a="Genom att överleva prövningarna i Mulgore och tala med andarna har du visat din visdom, styrka och hängivenhet genom Earthmothers riter. Ancestral Spirit skickar dig till Thunder Bluff så att taurerna och deras högste ledare, Cairne Bloodhoof, kan erkänna dina gärningar. Att stå inför högstamledaren markerar att du formellt välkomnas in i deras samhälle som en hedrad förkämpe.",al={"varför skickar ancestral spirit dig","ancestral spirits motiv","varför gå till cairne"}},c86a41a9={q="Varför måste du själv överlämna budskapet till Cairne Bloodhoof?",a="Earthmothers riter är en helig, personlig prövning. Ancestral Spirit är en andevarelse som är bunden till Mulgore heliga marker och varken kan eller vill bära budskap från den jordiska världen. Eftersom det var din ande och beslutsamhet som prövades tillhör äran att själv möta högstamledaren Cairne Bloodhoof enbart dig.",al={"varför jag till cairne","varför måste jag besöka cairne","varför måste jag träffa cairne bloodhoof"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="Rites of the Earthmother",s="Den här prövningen, som High Chieftain Cairne Bloodhoof själv har utsett, låter blivande hjältar spåra upp den väldiga kodon Arra'chea över Mulgore slätter. Även om en novis redan har genomgått de traditionella övergångsriterna, förväntar sig Cairne att hans folk ständigt visar sin styrka, spårningsförmåga och hängivenhet till stammen på nytt. Att återvända med Arra'cheas horn visar att en äventyrare är redo att tjäna den större Horde bortom mesas högplatåer.",h="Den här prövningen, som High Chieftain Cairne Bloodhoof själv har utsett, låter blivande hjältar spåra upp...",kw={"arra'chea","bloodhoof","cairne","earthmother","horn","jakt","kodo","mulgore","thunder bluff"},ang={["class:Hunter"]="Att smyga sig på en ensam, vandrande koloss som Arra'chea över de gyllene slätterna förkroppsligar de uråldriga jaktfilosofier som taurenfolkets spårmästare för vidare genom generationerna.",["faction:Horde"]="När Arra'chea fälls får Thunder Bluff viktig föda, läder och material. Det visar den gemensamma överlevnadsanda som håller den unga Horde vid liv.",["race:Tauren"]="Att stå inför Cairne Bloodhoof och göra anspråk på Arra'cheas horn är den yttersta övergångsriten för en ung shu'halo och bevisar att din skicklighet hedrar både dina förfäder och Mulgore hjordar."},sec={{t="En hövdings måttstock",b="Att nå Thunder Bluff markerar slutet på en taurenungdoms enkla dagar, men High Chieftain Cairne Bloodhoof låter inte unga jägare vila på lagrarna. För Cairne är det bara början på ansvaret för United Tauren Tribes att förtjäna en plats bland de höga klipporna. I stället för att skicka noviser mot obetydliga skadedjur kräver han bevis på verklig fältvana: att spåra upp och ta till vara på ett av Mulgore mest berömda vandrande djur."},{t="Jakten på Arra'chea",b="Bytet är Arra'chea, en enorm och legendarisk kodo vars vindlande vandring går över de gyllene grässlätterna nordost om Thunder Bluff. Att fälla en sådan varelse kräver mer än råstyrka; det kräver tålmodig smygjakt över den öppna savannen och respekt för slätternas titan. Att föra Arra'cheas horn tillbaka till High Rise ger inte bara personlig ära, utan också förnödenheter åt staden, eftersom Cairne genast skickar ut flåare och samlare så att inget av det heliga djuret går till spillo."}},faq={{q="Vem ger det här uppdraget?",a="High Chieftain Cairne Bloodhoof själv ger dig uppdraget från sin plats högst upp på Thunder Bluffs höga klippor.",al={"uppdragsgivare","vem ger rites of the earthmother","cairnes uppdrag"}},{q="Vad är Arra'chea?",a="Arra'chea är en respektingivande och berömd kodo som strövar över Mulgore slätter. Hans väldiga horn bevisar en jägares spårningsförmåga och stridsduglighet.",al={"vem är arra'chea","vad är arra'chea","arra'cheas bakgrund"}},{q="Var hittar jag Arra'chea?",a="Arra'chea strövar vanligtvis längs en vid cirkelbana nordost om Thunder Bluffs klippor och går långsamt medurs runt de öppna, böljande slätterna.",al={"var finns arra'chea","arra'cheas plats","arra'cheas väg"}},{q="Varför ber Cairne mig jaga den här varelsen när jag redan har genomfört de tidigare riterna?",a="I taurenkulturen är den första platsen man förtjänar inte slutet på ens plikter. Cairne lär ut att styrka, ödmjukhet och jaktförmåga måste visas gång på gång för att stammen ska bestå.",al={"varför göra uppdraget","varför döda arra'chea","syftet med riterna"}},{q="Vad händer med Arra'cheas kropp när hornet har tagits?",a="För att följa taurenfolkets tradition att hedra sitt byte skickar Cairne ut en insamlingsgrupp som hämtar köttet och skinnet från det fällda djuret, så att bytet ger Thunder Bluff mat och kläder.",al={"arra'cheas kött","vad händer med kodon","kadaverets bakgrund"}},{q="Är det här samma uppdrag som de tidiga nybörjarriterna?",a="Nej. De tidiga prövningarna i Camp Narache lär en novis grunderna i Rites of the Earthmother, medan den avslutande prövningen i Thunder Bluff är Cairnes personliga test av ditt fortsatta värde som jägare.",al={"skillnader mellan rites of the earthmother","vilket uppdrag med riterna","camp narache-riterna"}}},fx={d7a516d7={q="Vad ska Horn of Arra'chea användas till?",a="Hornet är ett fysiskt bevis på att du lyckats med jakten. Taurernas tradition sätter stor ära i konsten att spåra och fälla mäktiga bestar. När du överlämnar Arra'cheas horn direkt till högstamledaren Cairne Bloodhoof visar du att du har skickligheten som krävs för att försörja och skydda ditt folk.",al={"vad horn of arra'chea används till","varför ta med arra'cheas horn","syftet med horn of arra'chea"}},a7e696eb={q="Varför skickar Cairne Bloodhoof dig i stället för stadsvakterna?",a="Den här jakten är ingen försvarsuppgift eller enkel insamling av resurser. Den är en traditionell prövning. Du kan ha klarat Earthmothers första riter för att nå Thunder Bluff, men Cairne förväntar sig att varje jägare i stammen fortsätter bevisa sitt värde och sin självständighet genom stordåd, i stället för att luta sig mot tidigare meriter.",al={"varför skicka mig","varför inte skicka vakterna efter arra'chea","varför behöver cairne mig"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="This Is Going to Be Hard",s="Lucien Tosselwrench ger dig kugghjul nummer fem till Lotwil Veriatus och går i skydd, med en inbjudan att följa med.",h="Lucien Tosselwrench ger dig kugghjul nummer fem till Lotwil Veriatus och går i skydd, med en inbjudan att...",kw={"badlands","kugghjul fem","lotwil veriatus","lucien tosselwrench","bojor","det här blir svårt"},sec={{t="I skydd",b="Lucien räcker över kugghjulet och säger att du ska ta det till Lotwil Veriatus. Lucien väntar i skydd och du är välkommen att följa med. När du når Lotwil, som fortfarande böjer sig över bojorna, sträcks en hand fram och fingrarna vinkar otåligt efter kugghjulet."},{t="Skapar historia",b="Lotwil tar kugghjulet och säger att det är perfekt. Lotwil ber dig att ställa dig åt sidan medan förberedelserna görs för att skapa mer historia. Lotwil fortsätter arbeta febrilt."}},faq={{q="Vem lämnar över kugghjulet till Lotwil?",a="Lucien Tosselwrench ger dig kugghjul nummer fem att ta till Lotwil Veriatus.",al={"vem ger kugghjulet","var får jag kugghjul fem","lucien kugghjul"}},{q="Vart går Lucien?",a="Lucien går i skydd och säger att du är välkommen att följa med.",al={"varför gömmer sig lucien","lucien skydd"}},{q="Vad gör Lotwil när du kommer med kugghjulet?",a="Lotwil arbetar med en uppsättning bojor och sträcker otåligt fram handen efter kugghjulet utan att titta upp.",al={"vad gör lotwil","lotwil bojor","lotwils framsteg"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="This Is Going to Be Hard",s="Lotwil Veriatus förklarar bojorna färdiga och ber Lucien, Servo och dig att bevittna hur en mäktig elementarvarelse kallas fram.",h="Lotwil Veriatus förklarar bojorna färdiga och ber Lucien, Servo och dig att bevittna hur en mäktig...",kw={"badlands","elementarvarelse","fam'retor guardian","lotwil veriatus","lucien","servo","shackles of elemental binding"},sec={{t="En banbrytande dag",b="Lotwil ropar att bojorna är klara och att tiden är inne, och kallar Lucien och Servo att bevittna det tillsammans med dig. Lotwil beskriver bojorna som alkemi, ingenjörskonst och det mystiska i perfekt förening, och tänker kalla fram en mäktig elementarvarelse under vad som utropas till en banbrytande dag för alla där."},{t="Efter framkallningen",b="Resultatet blir inte som Lotwil väntat sig, och Lotwil ber dig hämta Shackles of Elemental Binding när Fam'retor Guardian har besegrats. Efteråt är Lotwil osäker på vad som gick fel, men glad att magierna fanns till hands för att återföra varelsen till planet den kom ifrån."}},faq={{q="Vem är Lotwil Veriatus?",a="Lotwil Veriatus har tillverkat Shackles of Elemental Binding, där alkemi, ingenjörskonst och det mystiska kombineras. Lucien och Servo är där tillsammans med Lotwil i Badlands.",al={"vem är lotwil","lotwil veriatus"}},{q="Vad är Shackles of Elemental Binding?",a="Det är bojorna som Lotwil just har färdigställt, en kombination av alkemi, ingenjörskonst och det mystiska, avsedda för en mäktig elementarvarelse som Lotwil tänker kalla fram.",al={"vad är bojorna","shackles of elemental binding"}},{q="Vilka kallar Lotwil till att bevittna det?",a="Lotwil kallar Lucien och Servo att bevittna framkallningen tillsammans med dig.",al={"vem är lucien","vem är servo"}},{q="Vad kommer före det här steget?",a="Det följer på steget där du tog med cog #5 till Lotwil.",al={"föregående uppdrag","vad ledde hit"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="The Lord of Blackrock",s="Nefarians avhuggna huvud förs till Stormwind Keep efter hans nederlag i Blackwing Lair. Highlord Bolvar Fordragon tar emot trofén, ett tecken på att härskaren över Blackrock Mountain har fallit. Segern är en av Alliansens största militära triumfer i mannaminne.",h="Nefarians avhuggna huvud förs till Stormwind Keep efter hans nederlag i Blackwing Lair.",kw={"blackrock mountain","blackwing lair","highlord bolvar fordragon","head of nefarian","lord of blackrock","nefarian","stormwind keep"},ang={["faction:Alliance"]="För Alliansen är överlämnandet av Nefarians huvud en krönande militär bedrift. Det krossar drakflockens planer mot människornas länder.",["race:Human"]="Som människa vet du att Blackrock Mountain har skickat otaliga intrång och ränker mot Stormwind. Härskarens nederlag ger riket den hämnd och lättnad det länge har väntat på."},sec={{t="Ett segermonument",b="Nefarian, yngelmästare över Black Dragonflight och härskare över Upper Blackrock Spire, har länge hotat de omgivande människorikena. Hans nederlag sätter stopp för hans förvridna experiment och planer. När hans stridssargade huvud förs tillbaka till Stormwind blir det ett bevis på att Alliansens största hjältar har besegrat Lord of Blackrock."},{t="Audiens i Stormwind Keep",b="Highlord Bolvar Fordragon styr riket från tronsalen i Stormwind Keep. Drakens avhuggna huvud chockerar det kungliga hovet och inger vördnad. Riket är pressat av inre politiska stridigheter och hot utifrån, och segern stärker moralen och får en plats i Alliansens historia."}},faq={{q="Vad handlar uppdraget Lord of Blackrock om?",a="Du tar Nefarians avhuggna huvud i Blackwing Lair och bär trofén till Stormwind City. Där överlämnar du det till Highlord Bolvar Fordragon för rikets räkning.",al={"uppdraget lord of blackrock","nefarian huvud uppdrag alliansen","head of nefarian stormwind"}},{q="Vem är Nefarian?",a="Nefarian är en mäktig svart drake och son till Deathwing. Han härskar från Blackwing Lair i Blackrock Mountain, för befäl över orcherna i Blackrock och utför ondskefulla experiment för att skapa den kromatiska drakflocken.",al={"vem är nefarian","lord of blackrock","nefarian historia"}},{q="Vem är Highlord Bolvar Fordragon?",a="Highlord Bolvar Fordragon är paladinen som styr Stormwind som regent medan kung Varian Wrynn är borta. Han håller hov i tronsalen i Stormwind Keep och vakar över den unge prins Anduin Wrynn.",al={"bolvar fordragon","vem är bolvar","highlord bolvar"}},{q="Varför förs trofén till Stormwind Keep?",a="Nefarians herravälde i Blackrock Mountain hotar Stormwind och hela den södra kontinenten. När hans huvud förs till rikets militära ledning bekräftas drakens nederlag, och folket får en seger att samlas kring.",al={"varför stormwind","varför föra huvudet till keep","varför bolvar"}},{q="Vad händer när huvudet har överlämnats till Bolvar?",a="Highlord Bolvar Fordragon blir häpen och förklarar att triumfen ska skrivas in i historien. Nästa del av händelsen innebär att huvudet sätts upp offentligt så att alla i Stormwind kan se det.",al={"vad händer sedan","lord of blackrock del två","överlämna nefarian huvud"}},{q="Påverkar överlämnandet av huvudet hela staden?",a="Ja. Nefarians huvud förs till huvudstaden och sätts upp ovanför stadsportarna. Det tillkännager drakens död för invånare och soldater och stärker Stormwinds försvarare med beslutsamhet.",al={"stadsvälsignelse","stridsrop","head of nefarian välsignelse"}}},fx={["150c64a2"]={q="Varför är det viktigt att föra Head of Nefarian till Stormwind?",a="Nefarian var den svarta drake som låg bakom hoten från Blackrock Spire, manipulerade dödliga riken och skapade monstruösa arméer alldeles intill Stormwind. När du överlämnar hans avhuggna huvud till Highlord Bolvar Fordragon bevisar du utan tvivel att draksläktets terror är krossad. Alliansen får en monumental seger att fira och visa upp inför riket.",al={"varför föra head of nefarian till stormwind","head of nefarians betydelse","varför överlämna nefarians huvud"}},["7e2ee731"]={q="Varför måste du bära huvudet till Stormwind i stället för de kungliga vakterna?",a="Du och dina följeslagare kämpade er igenom Blackwing Lair och fällde själva drakherren. Som förkämparna som besegrade honom har ni rätt att föra det makabra bytet tillbaka till Stormwind Keep. Då får Highlord Bolvar Fordragon höra nyheten direkt från hjältarna som faktiskt dödade besten.",al={"varför måste jag överlämna nefarians huvud","varför inte kungliga vakter med nefarians huvud","varför jag med nefarians trofé"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="The Lord of Blackrock",s="Vid Stormwinds portar samlas Alliansen för att fira segern över Blackrock. När du har rapporterat till Grand Admiral Jes-Tereth i Stormwind Keep beger sig hjältarna till Valley of Heroes, där Field Marshal Stonebridge förbereder en offentlig högtid för staden.",h="Vid Stormwinds portar samlas Alliansen för att fira segern över Blackrock.",kw={"blackrock","drakdräpare","nefarian","samlande rop","stonebridge","stormwind","valley of heroes"},ang={["class:Warrior"]="Dragonslayerns samlande rop ger styrka åt kämpar som ger sig av för att försvara riket.",["faction:Alliance"]="Nefarians huvud i Valley of Heroes förenar Alliansens raser. Invånare från Ironforge, Darnassus och Gnomeregan ser att de mörka krafter som plågar Eastern Kingdoms kan besegras.",["race:Human"]="För Stormwinds kungarike undanröjer besegrandet av Blackrocks härskare ett allvarligt drakhot vid den norra gränsen."},sec={{t="En stads triumf",b="Alliansens fälttåg mot Blackrock-klanen och den svarta drakflygelns avkomma når sitt offentliga slut. När Nefarians avhuggna huvud har visats upp inne i Stormwind Keep skickar Highlord Bolvar Fordragon mästarna genom staden till Valley of Heroes. Där väntar Field Marshal Stonebridge på att ta emot trofén och inleda firandet."},{t="Alliansen samlas",b="Field Marshal Stonebridge höjer Nefarians avhuggna huvud över de stora valven vid Stormwinds huvudingång. Hela staden ser det, och Dragonslayerns samlande rop inger försvararna, de besökande dignitärerna och invånarna mod. De vet att Deathwings avkomma har lidit ett förkrossande nederlag."}},faq={{q="Vad händer när du slutför det här uppdraget?",a="Field Marshal Stonebridge hänger Nefarians avhuggna huvud högt på stenvalvet vid Valley of Heroes. Dragonslayerns samlande rop stärker sedan vänligt sinnade kämpar och vakter i hela Stormwind City.",al={"lämna in uppdraget med nefarianhuvudet","vad gör stonebridge","utlöser det samlande ropet"}},{q="Vem är Field Marshal Stonebridge?",a="Field Marshal Stonebridge är en högt uppsatt officer i Stormwinds armé, stationerad i Valley of Heroes nära stadens ingång. Hon ordnar offentliga högtider för att fira militära segrar, bland annat genom att visa upp besegrade drakfienders huvuden.",al={"stonebridge","field marshal stonebridge"}},{q="Varför skickar Highlord Bolvar Fordragon dig hit?",a="När Highlord Bolvar Fordragon får besked om Nefarians nederlag i tronsalen skickar han dig till stadsportarna. Där kan Alliansens militär visa upp segern öppet och höja stridsmoralen i huvudstaden.",al={"bolvar","varför gå till valley of heroes"}},{q="Påverkar inlämningen hela staden?",a="Ja. När Stonebridge tar emot trofén ljuder en kungörelse genom Stormwind, och Dragonslayerns samlande rop når alla inom stadens gränser.",al={"nefarian-världsförstärkning","får stormwind en förstärkning"}},{q="Var ligger Valley of Heroes?",a="Valley of Heroes är den storslagna väg som leder in i Stormwind City. Väldiga statyer kantar den och hedrar hjältarna från Andra kriget som gick genom The Dark Portal.",al={"var ligger valley of heroes","var finns stonebridge"}},{q="Vem var ”Blackrocks herre”?",a="Den svarta draken Nefarian var Blackrocks herre. Han är Deathwings son och härskar över de övre spirorna på Blackrock Mountain.",al={"vem är blackrocks herre","nefarian identitet"}}},fx={["3a42f3f3"]={q="Varför skickar Bolvar dig i stället för att gå själv?",a="Du och dina följeslagare var förkämparna som trotsade höjderna i Blackwing Lair och fällde Nefarian. Som segrare är det med rätta du som får äran att överlämna drakens avhuggna huvud till Stormwinds militära ledning och sätta igång stadens firande.",al={"varför skicka mig","varför inte bolvar","varför måste jag överlämna huvudet"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="The Lord of Blackrock",s="Nefarians avhuggna huvud förs från Blackrock Mountain till Orgrimmar som bevis på segern. Det överlämnas till krigshövding Thrall och markerar att en mäktig fiende till Horden har fallit.",h="Nefarians avhuggna huvud förs från Blackrock Mountain till Orgrimmar som bevis på segern.",kw={"blackrock","blackwing lair","deathwing","drakdödare","thrall","nefarian","orgrimmar","rallying cry"},ang={["class:Warrior"]="För dig som krigare är det ett stort bevis på krigarära att bära en drakhärskares väldiga, avhuggna skalle till krigshövdingen.",["faction:Horde"]="Nefarians fall återupprättar Hordens heder och befriar Blackrock-regionen från draken som förslavade den avfälliga Dark Horde.",["race:Orc"]="För dig som orch innebär det hämnd att överlämna Nefarians huvud till Thrall, efter bestens manipulation av Rend Blackhand och förslavning av orchklanerna för sina experiment."},sec={{t="En trofé av förödelse",b="Nefarian har äntligen fallit. Han låg bakom Blackwing Lair och ledde den svarta drakflocken i Eastern Kingdoms. Hans väldiga, stridsärrade huvud bevisar att han är död. För Hordens krigare innebär det stor ära att föra trofén från Blackrock Mountains brinnande höjder över Stora havet till Durotar."},{t="Krigshövdingens dom",b="Trofén förs fram till krigshövding Thrall. Han känner väl till Blackrock Mountains fördärv. Han befriade sitt folk från interneringslägren och ledde dem bort från den gamla Hordens demoniska blodtörst. Deathwings son har fallit, och orcherna i Blackrock är fria från den mörka drakens grymma herravälde."},{t="Faderns skuggor",b="Nefarians död sätter stopp för den svarta drakflyktens förvridna experiment, men faran kvarstår. När Thrall ser drakens avhuggna huvud säger han att Deathwing säkert rör på sig när han får höra om sin sons undergång. Segern är verklig, och ännu större fasor sover fortfarande under världen."}},faq={{q="Vem är Nefarian?",a="Nefarian är en mäktig svart drake och Deathwings son. Från sitt näste på toppen av Blackrock Mountain utförde han förvridna experiment för att skapa den kromatiska drakflykten och manipulerade dödliga raser, särskilt Dark Horde, så att de gjorde hans vilja.",al={"nefarian bakgrund","vem är nefarian","svart drakhärskare"}},{q="Varför överlämnas trofén till Thrall?",a="Thrall är Hordens krigshövding. Han ledde orcherna ut ur interneringslägren och bort från den gamla Hordens demoniska blodtörst. Därför hör beviset på att draken som förslavade orcherna i Blackrock och Dark Horde har fallit hemma i hans händer.",al={"varför thrall","vem får huvudet"}},{q="Vad händer i Orgrimmar när huvudet lämnas in?",a="När Nefarians huvud återförs och sätts upp i Orgrimmar firar staden. Hordens medlemmar i närheten av huvudstaden får Drakdödarens stridsrop, som stärker deras stridsförmåga.",al={"huvudets förstärkning","orgrimmar världsbonus","rallying cry-bonus"}},{q="Har uppdraget en motsvarighet för Alliansen?",a="Ja. Alliansens hjältar överlämnar Nefarians huvud till Highlord Bolvar Fordragon i Stormwind Keep, vilket ger deras stad samma välsignelse.",al={"alliansens version","motsvarighet för alliansen"}},{q="Varför är Deathwing ett bekymmer?",a="Deathwing är Nefarians far och överhuvud för Black Dragonflight. Att besegra hans son undanröjer inte faran från drakfadern.",al={"den onde rör på sig","vem är den onde"}},{q="Var kommer huvudet ifrån?",a="Head of Nefarian tas från Nefarians lik på toppen av Blackwing Lair efter att han har besegrats.",al={"hur får man tag på head of nefarian","uppdragsstartföremål"}}},fx={d14146dc={q="Varför måste Head of Nefarian föras till Orgrimmar?",a="När du hugger loss det väldiga, stridsärrade huvudet från den fallna draken får du ett obestridligt bevis på att Blackrock Spires härskare har besegrats. Att föra denna monstruösa trofé tillbaka till Orgrimmar visar Hordens överlägsna styrka, firar en monumental seger över Black Dragonflight och låter krigschefens råd bekräfta att Nefarians förvridna experiment i berget äntligen har upphört.",al={"varför föra nefarians huvud","head of nefarians betydelse","varför ge huvudet till eitrigg"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="The Lord of Blackrock",s="I Orgrimmar förs Nefarians avhuggna huvud fram inför Horden. När Thrall bekräftar att den svarta draken är död skickar han segraren till High Overlord Saurfang i Valley of Strength, så att alla får se trofén.",h="I Orgrimmar förs Nefarians avhuggna huvud fram inför Horden.",kw={"blackwing lair","thrall","head of nefarian","saurfang","orgrimmar","nefarian","valley of strength"},ang={["faction:Horde"]="För Horden bevisar den offentliga visningen av Nefarian den reformerade Hordens styrka mot den svarta draken som manipulerade orcherna i Blackrock Mountain. Den stärker Thralls nya ordning.",["race:Orc"]="Som orch kan du känna en djup lättnad när draken som höll Blackrock-klanen i sitt våld faller. Hans nederlag lyfter en vanärande skugga från ditt folk."},sec={{t="En trofé åt horden",b="Nefarians huvud når Orgrimmar efter att den svarta draken har dödats högst upp i Blackwing Lair. Hövding Thrall bekräftar att Deathwings son har fallit och skickar sedan segraren till High Overlord Saurfang i Valley of Strength. Där förbereds kvarlevorna för offentlig visning, som en varning till fienderna och en stridsrop för den sanna Horden."},{t="Göra anspråk på arvet",b="Nefarian härskade över Blackrock Mountains höjder och tvingade Blackrock-orcherna och Dark Horde att lyda honom. Genom att fälla honom och höja hans huvud i Valley of Strength utdelar Thralls Horde ett hårt slag mot Black Dragonflight. Saurfang uppmanar hela Orgrimmar att jubla åt Rallying Cry of the Dragonslayer."}},faq={{q="Vad är syftet med uppdraget?",a="När du har bevisat för Thrall att Nefarian är död rapporterar du till High Overlord Saurfang i Orgrimmars Valley of Strength. Det avhuggna huvudet visas upp offentligt och du hedras.",al={"vad gör uppdraget","överlämning av lord of blackrock","varför gå till saurfang"}},{q="Vem är High Overlord Saurfang?",a="High Overlord Saurfang är en veteran bland orchkrigare och en av Hordens största mästare. Han är stationerad i Orgrimmars Valley of Strength, där han tar emot huvudet och låter montera det så att alla kan se det.",al={"vem är saurfang","high overlord saurfangs roll"}},{q="Varför visas Nefarians huvud upp?",a="Nefarians monterade huvud bevisar att härskaren över Blackrock Mountain har fallit. Visningen stärker moralen hos Orgrimmars försvarare, och alla i staden får Rallying Cry of the Dragonslayer.",al={"varför sätta upp nefarian huvud","nefarian huvud visas upp orgrimmar"}},{q="Vem var Nefarian?",a="Nefarian var en mäktig svart drake och son till Deathwing. Från Blackwing Lair högst upp på Blackrock Mountain styrde han Blackrock-orcherna och Dark Horde och avlade fram den kromatiska drakflocken.",al={"vem var nefarian","nefarian berättelse"}},{q="Var finns High Overlord Saurfang?",a="Saurfang finns i Valley of Strength, Orgrimmars centrala entrédistrikt.",al={"var finns saurfang","saurfangs plats"}},{q="Vilken roll spelar Thrall här?",a="Hövding Thrall tar först emot Nefarians huvud. När han har bekräftat att draken är död skickar han dig till Saurfang för att låta montera trofén officiellt.",al={"varför thrall","thralls inblandning"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="A Donation of Wool",s="I Darnassus samlas ylletyg in för att fylla på stadens förråd. Dina sextio tygstycken ger dig erkännande för din generositet.",h="I Darnassus samlas ylletyg in för att fylla på stadens förråd.",kw={"darnassus","donation","erkännande","förråd","ylle","ylletyg"},sec={{t="Förråd av ylletyg",b="Darnassus behöver sextio stycken ylletyg från dig. Andra runt om i riket förväntas stå för resten av förråden. Din donation ger dig fullt erkännande för din generositet."}},faq={{q="Vad behöver Darnassus?",a="Darnassus behöver ylletyg för att fylla på sina förråd.",al={"ylledonation","vilket tyg vill darnassus ha"}},{q="Hur mycket ylletyg behöver jag donera?",a="Du behöver donera sextio stycken ylletyg.",al={"hur många ylletyg","sextio ylletyg"}},{q="Varför samlar Darnassus in ylletyg?",a="Darnassus samlar in ylletyg för att fylla på sina förråd.",al={"varför ylletyg","ylleinsamling"}},{q="Vad får jag för att donera ylletyg?",a="Din donation av sextio tygstycken ger dig fullt erkännande från Darnassus för din generositet.",al={"erkännande för ylledonation","belöning för att donera ylletyg"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="The Legend of Stalvan",s="Det här uppdraget blir en vändpunkt i avslöjandet av Stalvan Mistmantles historia och för utredarna från Elwynn Forest tillbaka till den skuggiga staden Darkshire. Med hjälp av Marshal Haggards minnen från tjänstgöringen tar du med en återfunnen dagbokssida till Tavernkeep Smitts på Scarlet Raven Tavern för att identifiera den kusliga handstilen.",h="Det här uppdraget blir en vändpunkt i avslöjandet av Stalvan Mistmantles historia och för utredarna från...",kw={"darkshire","duskwood","elwynn","dagbok","marshal haggard","mistmantle","scarlet raven tavern","stalvan","tavernkeep smitts"},ang={["faction:Alliance"]="Uppdraget visar de starka banden mellan rikets forna försvarare och knyter samman pensionerade vakter från Stormwind med samhällsbärare runt om i Kingdom of Stormwind.",["race:Human"]="Det här steget blottar de mörka minnen som gömmer sig i mänskliga bosättningar och visar hur tidigare tragedier i Elwynn och Darkshire vägrar förbli begravda."},sec={{t="Ett spår från Marshal",b="Efter att ha återfunnit en sliten, trasig dagbokssida i Marshal Haggards kista i Elwynn Forest kan den pensionerade befälhavaren inte läsa den bleknade skriften på grund av sin sviktande syn. Haggard inser att spåret leder tillbaka över floden och minns hur han tidigare ledde Stormwind Guard. Han minns också kvällarna på Scarlet Raven Tavern i Darkshire. Han hänvisar dig till Tavernkeep Smitts, en krögare vars långa tjänstgöring har gjort honom till en inofficiell väktare av lokal historia och rykten."},{t="Tillbaka till Scarlet Raven",b="När du tar dig tillbaka genom Duskwoods dystra skogar visar du det bleknade manuskriptet för Smitts bakom disken. Smitts mjuknar genast när han hör namnet på sin gamle bekant Haggard, men beklagar veteranens sviktande hälsa. När krögaren får syn på pergamentet försvinner hans sorglösa uppsyn genast och ersätts av oro. Han känner igen den särpräglade handstilen utan minsta tvivel, och utredningen kommer allt närmare den fasansfulla sanningen om Stalvans vansinne."}},faq={{q="Varför skickar Marshal Haggard mig tillbaka till Darkshire?",a="Marshal Haggard börjar bli gammal och är nästan blind, så han kan inte själv undersöka den återfunna dagbokssidan. Han minns att Tavernkeep Smitts på Scarlet Raven Tavern kunde mycket om lokal historia och traditioner när Haggard tjänstgjorde i Stormwind Guard. Därför är Smitts den perfekta personen att identifiera handstilen.",al={"varför åka till darkshire","haggard till darkshire","varför smitts"}},{q="Var finns Tavernkeep Smitts?",a="Tavernkeep Smitts sköter baren på Scarlet Raven Tavern, som ligger på östra sidan av Darkshire i Duskwood.",al={"var är smitts","smitts plats","scarlet raven tavern plats"}},{q="Vilket föremål har du med dig till Tavernkeep Smitts?",a="Du tar med en A Faded Journal Page, ett utdrag ur Stalvan Mistmantles försvunna dagbok som tidigare hittades inlåst i Marshal Haggards fotkista.",al={"vilket föremål","bleknad dagbokssida","stalvans dagbokssida"}},{q="Känner Tavernkeep Smitts igen handstilen?",a="Ja. Så snart Smitts granskar den bleknade sidan känner han igen handstilen och blir tydligt orolig. Hans igenkänning ger sökandet efter Stalvan ett nytt spår.",al={"känner smitts igen handstilen","smitts reaktion på dagboken"}},{q="Hur känner Smitts Marshal Haggard?",a="Smitts tog emot Haggard för många år sedan, när Haggard ledde patruller från Stormwind Guard in i Duskwood och ofta besökte Scarlet Raven Tavern för att ta sig en drink.",al={"smitts och haggards relation","hur smitts känner haggard"}},{q="Vad händer härnäst i sökandet efter Stalvan?",a="Ta den bleknade dagbokssidan till Smitts på Scarlet Raven Tavern och följ spåret han ger dig.",al={"vad händer härnäst","nästa steg för stalvan","fortsättning på stalvans uppdragskedja"}}},fx={bf062962={q="Varför vill Marshal Haggard att det här ska göras?",a="Marshal Haggard kan inte läsa den blekta dagbokssidan eftersom synen sviktar. Han minns Tavernkeep Smitts som en gammal bekant med stor kunskap om lokal historia och ber dig ta sidan till honom i Darkshire.",al={"varför vill haggard få detta gjort","marshal haggards motiv","varför hjälpa till att hitta stalvan"}},c297959a={q="Varför skickar Marshal Haggard dig i stället för att gå själv?",a="Haggard är en gammal, pensionerad marskalk som lever isolerat och snabbt förlorar synen. Vägarna genom skogarna är farliga, och han saknar helt enkelt ungdomen och orken att ta sig över gränsen till Duskwood. Han förlitar sig på att en kapabel resenär som du uträttar hans ärende och visar dagbokssidan för hans gamla bekant.",al={"varför kan inte haggard gå","varför behöver haggard mig","varför besöker inte haggard smitts"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="The Battleboars",s="The Battleboars är en jakt som markerar övergången till vuxenlivet och som Grull Hawkwind ger i Camp Narache. Unga taurer får i uppgift att hålla efter de grymma, krigstränade vildsvinen i Brambleblade Ravine för att försvara stammens marker och ge bosättningens unga mat.",h="The Battleboars är en jakt som markerar övergången till vuxenlivet och som Grull Hawkwind ger i Camp Narache.",kw={"stridsvildsvin","brambleblade ravine","bristleback","camp narache","grull hawkwind","mulgore","quilboar","red cloud mesa"},ang={["class:Hunter"]="När unga jägare möter bestar som Bristlebacks tränat för att sprida ondska lär de sig se den skarpa skillnaden mellan vilda djur och djur som förvandlats till krigsvapen.",["profession:Cooking"]="Begäran om flanker och trynen visar taurernas grundläggande matfilosofi: grovt och segt kött kan alltid kokas ner till mustiga, mättande grytor.",["race:Tauren"]="Uppdraget visar hur taurerna balanserar försvaret av Jordmoderns områden med att se till att inget som tas i strid går till spillo. Fiendens krigsdjur blir till mat åt lägrets kalvar."},sec={{t="Ett hot vid gränsen",b="Öster om Red Cloud Mesa ligger Brambleblade Ravine, en törnsnårig ravin som hålls av Bristleback quilboar. När spänningarna mellan Shu'halo och quilboar övergår i öppet krig har Bristlebacks tränat grymma stridsvildsvin att känna av taurernas gränser och terrorisera deras traditionella jaktmarker. Om de lämnas åt sig själva hotar dessa aggressiva bestar inte bara jaktstigarna utan även säkerheten i Camp Narache."},{t="Mat åt stammen",b="För taurerna fyller jakten både ett försvarsbehov och ett behov av gemensam försörjning. Grull Hawkwind instruerar de invigda att ta med trynen och flankerna från de fällda stridsvildsvinen. Inte ens bestar som tränats av quilboar går till spillo; köttet och brosket tas till vara för att laga mustig gryta åt stammens unga. På så vis blir ett quilboar-vapen till näring för nästa generation tauriska försvarare."}},faq={{q="Varför anfaller stridsvildsvinen mesan?",a="Stridsvildsvinen har medvetet fötts upp och tränats av Bristleback quilboar som bor i Brambleblade Ravine. Quilboar använder dem som anfallsdjur för att trakassera taurerna och tränga in på Red Cloud Mesas stammars jaktmarker.",al={"stridsvildsvinens aggressivitet","varför är stridsvildsvin fientliga","stridsvildsvin anfaller"}},{q="Vem skickar ut spelarna på den här jakten?",a="Grull Hawkwind, en framstående jägare och äldre som är stationerad i Camp Narache, leder unga taurer genom de avslutande proven i deras tidiga träning.",al={"uppdragsgivare för stridsvildsvinen","vem ger uppdraget the battleboars","grull hawkwinds roll"}},{q="Var hittar man stridsvildsvinen?",a="De strövar omkring nära och inne i Brambleblade Ravine, en oländig kanjon strax öster om Camp Narache vid Red Cloud Mesas östra kant.",al={"stridsvildsvinens plats","var finns stridsvildsvin","vildsvin i brambleblade ravine"}},{q="Vad händer med köttet från vildsvinen?",a="Stridsvildsvinens flanker och trynen tas tillbaka till Camp Narache och får sjuda till gryta åt bosättningens barn och äldre. På så vis följer man taurernas tradition att ta till vara på allt som jagas.",al={"vad används stridsvildsvinens flanker till","vad används vildsvinsköttet till","vildvinsgryta"}},{q="Hur passar uppdraget in i den lokala konflikten med quilboar?",a="Uppdraget är en tidig introduktion till det öppna kriget mellan taurerna och Bristleback-stammen. Genom att hålla efter deras krigsdjur minskar antalet bestar som trakasserar taurernas jaktmarker, och Bristlebacks i Brambleblade Ravine får ett tydligt budskap.",al={"kriget mellan taurer och quilboar","konflikten med bristleback","quilboars historia"}},{q="Vilket uppdrag kommer före The Battleboars?",a="Före det kommer The Hunt Continues, ett tidigare uppdrag från Grull Hawkwind som går ut på att lära känna Red Cloud Mesas jaktmarker.",al={"förutsättning för the battleboars","föregående uppdrag till the battleboars","the hunt continues uppdragskedja"}}},fx={b70ec92c={q="Varför vill Grull Hawkwind att stridsgaltarna dödas?",a="Stridsgaltarna har trängt ut från Brambleblade Ravine och in på Red Cloud-stammens urgamla jaktmarker. De har fötts upp och tränats till att vara våldsamma av Bristleback quilboar, och deras ökande aggressivitet hotar Camp Narache direkt. Grull Hawkwind tänker ge quilboar ett tydligt besked genom att minska deras krigsbestånd och samtidigt göra jakten till mat åt stammens unga.",al={"varför vill grull hawkwind döda stridsgaltar","grull hawkwinds motiv för stridsgaltarna","varför döda stridsgaltar i mulgore"}},["58a19c3f"]={q="Vad är stridsgaltar?",a="Stridsgaltar är vildsinta bestar som Bristleback quilboar föder upp och tränar i Brambleblade Ravine. Till skillnad från de vilda bergspumorna och slättlöparna som hör hemma på Red Cloud Mesa har de här galtarna medvetet tränats för krig och ondska. De fungerar som levande vapen i Bristlebacks pågående kamp mot taurerna.",al={"vilka är stridsgaltarna","vad är stridsgaltar","stridsgaltarnas bakgrund"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="A Donation of Wool",s="I Ironforge hjälper ulldonationer till att fylla förråden. Sextio stycken ger dig fullt erkännande för din generositet.",h="I Ironforge hjälper ulldonationer till att fylla förråden.",kw={"donation","ironforge","erkännande","sextio stycken","förråd","ull","ylletyg"},ang={["faction:Alliance"]="Som resenär i Alliance får du erkännande från Ironforge för din donation av ull."},sec={{t="Ullförråd",b="Ironforge ber dig om sextio stycken ylletyg. Förråden behöver bara så mycket från dig. Andra förväntas ge tillräckligt för att stödja insamlingen."}},faq={{q="Hur mycket ull behöver Ironforge från mig?",a="Sextio stycken ylletyg till Ironforge.",al={"mängd ull att donera","hur mycket ull","sextio ull"}},{q="Vad får jag för att donera ull?",a="Ge Ironforge sextio stycken ylletyg, så får du fullt erkännande för din generositet.",al={"belöning för ulldonation","vad får man för ull","erkännande från ironforge"}},{q="Varför samlar Ironforge in ull?",a="Ironforge samlar in ylletyg för att fylla på sina förråd.",al={"ullinsamling","varför donera ull","ironforge ull"}}},fp="18,110,11.148.0,42.42.0,32.93.0,33.51.0"}
P.entries["quest:7807"] = {n="A Donation of Wool",s="A Donation of Wool är en materialbeställning som Gnomeregan Exiles har ordnat för att samla in viktiga textilier. De landsförvisade gnomerna har förlorat sin teknologiskt avancerade hemstad och förlitar sig på sextio stycken ylletyg från generösa äventyrare runtom i riket för att hålla sitt samhälle vid liv. Den som bidrar får formellt erkännande bland gnomernas flyktingar.",h="A Donation of Wool är en materialbeställning som Gnomeregan Exiles har ordnat för att samla in viktiga...",kw={"tyginsamling","a donation of wool","gnom","gnomeregan","gnomeregan exiles","textilier","ylletyg"},ang={["faction:Alliance"]="När du bidrar med råmaterial till de landsförvisade gnomerna stärker du solidariteten inom alliansen och hjälper till att försörja en viktig allierad som fördrivits från sitt hem i bergen.",["profession:Tailoring"]="Skräddare som samlar in eller väver ylletyg har gott om textilier som flyktingar desperat behöver till grundläggande kläder och förnödenheter.",["race:Gnome"]="När du samlar in ylle hjälper du dina fördrivna släktingar bland gnomerna att fylla på förråden medan de försöker överleva och återuppbygga utanför Gnomeregan."},sec={{t="Ett fördrivet folks behov",b="Efter att Gnomeregan föll för trogginvasion och radioaktiv förorening fördrevs de överlevande gnomerna från sin högteknologiska metropol. Som flyktingar får de främst husrum hos sina dvärgkusiner i Ironforge, men Gnomeregan Exiles har stora logistiska svårigheter. Återkommande insamlingar av basvaror som tyg är viktiga för att hålla folket klätt, försett med förnödenheter och organiserat medan de överlever utanför sina förfäders hallar."},{t="Textilinsamlingen",b="För att undvika att enskilda välgörare belastas för hårt ber insamlingens organisatörer varje frivillig att bidra med exakt sextio stycken ylletyg. Genom att samla in mindre bidrag från hela riket kan de landsförvisade få ihop de stora mängder textilier som behövs till sängkläder, bandage och kläder utan att lägga en ohållbar börda på en enskild leverantör. Som tack erbjuder gnomerna formellt erkännande bland sitt folk till alla som vill hjälpa till med återuppbyggnaden."}},faq={{q="Varför behöver Gnomeregan Exiles ylletyg?",a="Gnomeregan Exiles samlar in resurser för att bygga upp ett grundlager av textilier. Efter att ha drivits bort från sin hemstad behöver folket viktiga material som ylletyg för att försörja flyktingarna och hålla verksamheten igång.",al={"varför ylle","vad används ylle till","syftet med yllebidraget"}},{q="Hur mycket ylletyg behövs?",a="Insamlingen ber varje bidragsgivare skänka sextio stycken ylletyg vid ett enda tillfälle. Organisatörerna räknar med att få in denna mängd från givare runtom i riket för att täcka det övergripande behovet.",al={"hur mycket ylle","bidragsmängd","behövt ylle"}},{q="Vem organiserar insamlingen?",a="Representanter för Gnomeregan Exiles samordnar textilinsamlingen och tar emot bidrag för de fördrivna gnomerna som nu får skydd hos sina allierade.",al={"vem tar emot bidraget","vem tar emot ylle","bidragsmottagare"}},{q="Kan du skänka ylletyg mer än en gång?",a="Beställningen begränsas till ett enda bidrag på sextio stycken från varje givare. De landsförvisade uppger att deras förråd just nu bara behöver den mängden från dig, eftersom de förlitar sig på en större grupp bidragsgivare runtom i riket för att nå sin kvot.",al={"kan jag bidra igen","kan uppdraget upprepas","fler yllebidrag"}},{q="Vilket erkännande erbjuder Gnomeregan Exiles?",a="Om du bidrar med sextio stycken ylle får du fullt erkännande och tacksamhet från Gnomeregan Exiles. Det visar din lojalitet och ditt stöd till deras fördrivna folk under en kris.",al={"anseende hos gnomeregan exiles","gnomernas anseende","erkännande för de landsförvisade"}},{q="Varför är gnomerna landsförvisade?",a="Gnomerna tvingades fly från sitt underjordiska hem Gnomeregan efter en katastrof och en trogginvasion. Nu är de beroende av tillfälliga läger, hjälp från allierade och materialinsamlingar medan de lever som flyktingar.",al={"varför är gnomerna landsförvisade","var ligger gnomeregan","gnomernas flyktingkris"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:78091"] = {n="Earning Your Salt",s="Ursula Deline i Stormwind har gått med på att studera en klot åt dig, men kräver en tjänst i gengäld. För att få veta vad hon upptäcker måste du bege dig till Redridge Mountains och röva åt dig förberedda kallsalter från Blackrock-klanen.",h="Ursula Deline i Stormwind har gått med på att studera en klot åt dig, men kräver en tjänst i gengäld.",kw={"blackrock clan","blackrock summoner","earning your salt","redridge mountains","stormwind","kallarens salt","ursula deline"},ang={["class:Warlock"]="Ursula Deline studerar ett klot åt dig, men bara om du hämtar de förberedda salter som Blackrock-kallare använder för att stärka sina riter."},sec={{t="Ritual Salt",b="Blackrock-kallare i Redridge Mountains bär på särskilt behandlade salter som stärker deras mörka riter. Ursula Deline vägrar undersöka ett klot åt dig förrän du skaffat en förråd från lägren. När du återvänder till Stormwind med saltet i hand har hon lovat att berätta vad hennes studier visar."}},faq={{q="Vem är Ursula Deline?",a="Ursula Deline är en forskare i Stormwind som går med på att undersöka ett klot åt dig i utbyte mot ritualkomponenter.",al={"vem vill ha kallarens salt","vem ger uppdraget earning your salt","vem är ursula deline"}},{q="Varför behöver Ursula kallarens salt?",a="Svartkonstnärer från Blackrock-klanen använder särskilt preparerade salter för att stärka sina åkallningsriter, och Ursula kräver ett förråd innan hon delar med sig av sin forskning.",al={"varför vill ursula ha salt","vad används kallarens salt till","varför samla salt"}},{q="Var hittar man kallarens salt?",a="Saltet bärs av Blackrock-kallare som slagit läger i Redridge Mountains.",al={"var hittar man kallarens salt","var finns blackrock summoners","var får jag tag på saltet"}},{q="Vad erbjuder Ursula i gengäld?",a="Ursula lovar att studera ett klot och dela med sig av sina forskningsresultat när du återvänder med saltet.",al={"vad lovar ursula","vad studerar ursula","vad får du i gengäld"}}},fp="17,233,11.314.0,21.114.0,37.145.0,35.82.0,33.101.0"}
P.entries["quest:781"] = {n="Attack on Camp Narache",s="Attack on Camp Narache är en viktig upptäckt i quilboarernas håla i Brambleblade Ravine. En smutsfläckad karta avslöjar att den aggressiva Bristleback-stammen planerar en samordnad belägring av Camp Narache. När planerna överlämnas till Chief Hawkwind får Camp Narache tid att kalla på hjälp från Bloodhoof Village.",h="Attack on Camp Narache är en viktig upptäckt i quilboarernas håla i Brambleblade Ravine.",kw={"attackplaner","bloodhoof village","brambleblade ravine","bristleback","camp narache","chief hawkwind","dirt-stained map","quilboar","red cloud mesa"},ang={["faction:Horde"]="Om tauren behåller sitt fäste i Mulgore kan Horde bevara sitt viktiga södra fäste i centrala Kalimdor.",["race:Tauren"]="För unga taurenkrigare som genomför sina första riter på platån visar du din lojalitet mot stammen genom att stoppa den här kartan, och skyddar dina fränder från en plötslig massaker."},sec={{t="En plan bland snåren",b="När unga taurenäventyrare spanar djupt inne i grottorna i Brambleblade Ravine hittar de en grov, smutsfläckad karta på klippgolvet. Vid närmare granskning visar pergamentet taktiska markeringar som Bristleback-quilboarerna gjort med avsikt. Quilboarerna nöjer sig inte med enstaka plundringståg, utan samordnar en fullskalig, långvarig belägring av Camp Narache."},{t="Varna hövdingen",b="När attackplanerna förs tillbaka till Camp Narache får Chief Hawkwind viktig information. Han inser vilket allvarligt hot det relativt försvarslösa lägret och dess unga lärlingar står inför och förbereder sig på att skicka bud till Bloodhoof Village efter förstärkningar. Den beslagtagna kartan förvandlar ett möjligt katastrofalt bakhåll till ett försvar man är beredd på."}},faq={{q="Var hittar man Bristleback-attackplanerna?",a="Planerna finns på en smutsfläckad karta inne i en grotta i Brambleblade Ravine, strax uppför stigen till höger om Chief Sharptusks hydda.",al={"kartans plats","var finns dirt-stained map","hitta planerna"}},{q="Vem tar emot Bristleback-attackplanerna?",a="Planerna ska överlämnas direkt till Chief Hawkwind mitt i Camp Narache.",al={"vem ska få planerna","vem får kartan","uppdragets slutperson"}},{q="Varför anfaller Bristleback-quilboarerna Camp Narache?",a="Bristleback-stammen vill driva bort tauren från Red Cloud Mesa och återta Mulgore:s jaktmarker och heliga slätter åt sitt eget folk.",al={"varför anfalla camp narache","quilboarernas motiv i mulgore","bristleback-belägring"}},{q="Hur tänker Chief Hawkwind stoppa belägringen?",a="Tack vare förvarningen från den beslagtagna kartan tänker Chief Hawkwind kalla på sina fränder i Bloodhoof Village för att förstärka platån och slå tillbaka anfallet.",al={"hawkwinds plan","förstärkningar till camp narache"}},{q="Måste man prata med någon innan man hämtar kartan i uppdraget?",a="Nej. Uppdraget börjar direkt vid Dirt-stained Map på grottgolvet i Brambleblade Ravine. När du hämtar den blir den till attackplanerna.",al={"uppdragets start","dirt-stained map som uppdragsstart","hur startar man attack on camp narache"}},{q="Vad händer om Camp Narache faller?",a="Camp Narache är den främsta tillflyktsorten för unga taurenkrigare och deras övergångsriter. Om lägret går förlorat äventyras säkerheten på Red Cloud Mesa och Mulgore förlorar sina andliga träningsmarker.",al={"vad står på spel vid camp narache","varför försvara narache"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="Arena Master",s="Finns det mer i att bemästra arenan än så här? Short John Mithril, piraten bakom Gurubashi-evenemanget, kanske har svaret. Du hittar honom i Stranglethorn Arena.",h="Finns det mer i att bemästra arenan än så här?",kw={"arenamästare","gurubashi","pirat","short john mithril","stranglethorn arena","stranglethorn vale"},sec={{t="På jakt efter piraten",b="Vad du än har vunnit i Gurubashi verkar det krävas mer för att bemästra arenan. Short John Mithril, piraten som ordnar tävlingarna där, kanske vet vad. Leta efter honom i Stranglethorn Arena."},{t="Short Johns ord",b="Short John Mithril säger att en enda prydnadssak inte räcker för att göra dig till arenans mästare. Nu, säger han, är det dags att verkligen pröva din styrka."}},faq={{q="Vem ska jag prata med?",a="Short John Mithril, piraten bakom Gurubashi-evenemanget.",al={"vem ska jag prata med","lämna in arenamästare","vart ska jag gå"}},{q="Var finns Short John Mithril?",a="I Stranglethorn Arena, vid Gurubashi i Stranglethorn Vale.",al={"gurubashi plats","var ligger stranglethorn arena","arenans plats"}},{q="Vad antyds om att bli arenans mästare?",a="Bara att det verkar krävas mer för att bemästra arenan än vad du har gjort hittills, och att piraten bakom Gurubashi-evenemanget kanske vet.",al={"hur blir jag arenamästare","är jag arenamästare än"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Nar'thalas Almanac är ett sällsynt akademiskt manuskript om forntida magiska studier, eftertraktat av arkivarier som vill utöka bibliotekets samling. När volymen återbördas hamnar förlorad arkan kunskap i trygga händer, där forskare kan studera dess bortglömda insikter.",h="Nar'thalas Almanac är ett sällsynt akademiskt manuskript om forntida magiska studier, eftertraktat av...",kw={"almanacka","arkan","bok","bibliotek","magiska verk","nar'thalas","narthalas","skrift"},ang={["class:Mage"]="Magiker förstår det enorma akademiska värdet i återfunna texter om forntida arkana traditioner, vilket gör bidrag till bibliotekets magiska samling särskilt betydelsefulla.",["faction:Alliance"]="Lärda och kuratorer vid Alliansens arkiv förlitar sig på företagsamma äventyrare som söker upp sällsynta manuskript och utökar rikets samlade kunskap.",["race:NightElf"]="Nar'thalas var en gång ett forntida centrum för kaldorei-forskning om arkan magi, innan Sunderingen krossade den gamla världen. En almanacka med det namnet blir därmed en gripande länk till nattalvernas forntida historia."},sec={{t="En relik från forntida studier",b="Nar'thalas Almanac är en sällsynt skrift om arkan forskning med rötter i nattalvernas uråldriga lärdomstraditioner från tiden före Sunderingen. För dem som förvaltar stora arkiv innebär det att säkra en sådan text att rädda århundraden av kunskap från glömskan och ge hyllorna ett viktigt historiskt verk. Äventyrare som finner dessa länge försummade skrifter hjälper till att överbrygga klyftan mellan bortglömd forntid och modern akademisk förståelse."},{t="Utöka arkiven",b="Arkivarier och forskare söker ständigt efter förlorade avhandlingar, fältanteckningar och krönikor som skingrats över Azeroth. Om Nar'thalas Almanac förs till ett bibliotek som tar hand om den, kan den bevaras, katalogiseras och studeras i stället för att lämnas att förfalla bland ruiner eller hamna i vårdslösa händer. Varje räddad volym ger lärda nya insikter i gångna tiders arkan konst."}},faq={{q="Vad är Nar'thalas Almanac?",a="Nar'thalas Almanac är ett forntida manuskript om magisk lärdom som kuratorer söker för att berika ett biblioteks historiska arkiv. Äventyrare som återfinner sådana sällsynta verk överlämnar dem till lärda, så att deras bevarade insikter kan katalogiseras.",al={"vad är nar'thalas almanac","uppdraget nar'thalas almanac","information om almanackan"}},{q="Vem samlar in Nar'thalas Almanac?",a="Almanackan överlämnas till bibliotekets lärda, som intresserar sig för forntida magiska texter och historiska arkiv. Dessa kuratorer söker aktivt efter tillskott som utökar den gemensamma kunskapen om världens arkana arv.",al={"vem vill ha almanackan","vart ska almanackan","lämna in almanackan"}},{q="Vad syftar namnet Nar'thalas på?",a="Nar'thalas var ett forntida kaldorei-center för lärdom och magiska studier, grundat före den Stora Sunderingen. Bevarade texter med anknytning till namnet utgör fragment av förgrunderingens arkanism och alviska kunskap.",al={"vad är nar'thalas","nar'thalas historia","var ligger nar'thalas"}},{q="Varför samlas magiska texter in till biblioteket?",a="Många historiska dokument och magiska avhandlingar har förskingrats, gått förlorade eller begravts i ruiner över Azeroth. Lärda förlitar sig på återfunna skrifter för att bredda sin förståelse av arkana strömmar och skydda ömtåliga dokument från att gå helt förlorade.",al={"varför samla magiska verk","bibliotekets syfte","varför böcker är viktiga"}},{q="Kan andra magiska verk föras till biblioteket?",a="Lärda välkomnar alla återfunna avhandlingar, verk eller bortglömda manuskript som kastar ljus över arkan teori och forntida historia. De söker ständigt efter tillskott som kan berika hyllorna.",al={"fler magiska böcker","andra verk","fler texter"}},{q="Är Nar'thalas Almanac farlig att hantera?",a="Almanackan är en sammanställning av studier, inte en oberäknelig förbjuden artefakt. Den fungerar främst som ett värdefullt uppslagsverk för historiker och utövare som studerar historisk magi.",al={"är almanackan farlig","har almanackan mörk magi","säker att läsa"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="Bibliotekarien ber dig att ta med magiska verk till samlingen. Varje bok tillför kunskap till biblioteket.",h="Bibliotekarien ber dig att ta med magiska verk till samlingen.",kw={"samling","dalaran digest","kunskap","bibliotekarie","bibliotek","magiska verk"},sec={{t="Samlingen",b="Bibliotekarien välkomnar magiska verk som kan vara till nytta för biblioteket. Du tar med en bok till samlingen och bidrar därmed till bibliotekets växande kunskap."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien ber dig att ta med magiska verk som kan vara till nytta för samlingen.",al={"vad ska tas med","biblioteksbok","magiska verk"}},{q="Vart ska jag ta boken?",a="Ta boken till bibliotekarien som bad dig att lägga till den i samlingen.",al={"var finns bibliotekarien","bibliotekets plats"}},{q="Varför samlar bibliotekarien på magiska verk?",a="Ditt bidrag tillför mer kunskap till samlingen.",al={"varför samla böcker","bibliotekets syfte"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Bewitchments and Glamours",s="I Ironforge söker biblioteket magiska skrifter till sina hyllor. Du kan hjälpa dess förvaltare att bredda sina kunskaper genom att lämna in böcker som kan berika samlingen.",h="I Ironforge söker biblioteket magiska skrifter till sina hyllor.",kw={"bewitchments and glamours","böcker","samling","ironforge","bibliotek","magiska skrifter"},sec={{t="En växande samling",b="Lämna in magiska skrifter till biblioteket i Ironforge, där varje tillskott kan bredda förvaltarnas kunskaper."}},faq={{q="Vad vill biblioteket ha?",a="Biblioteket söker magiska skrifter som kan berika dess samling.",al={"vad vill de ha","biblioteksböcker","magiska skrifter"}},{q="Var ska jag lämna in de magiska skrifterna?",a="Lämna in de magiska skrifterna till biblioteket i Ironforge.",al={"var lämna in böcker","var ligger biblioteket","ironforge bibliotek"}},{q="Varför samlar de på magiska skrifter?",a="Biblioteket säger att skrifterna kommer att utöka dess kunskaper.",al={"varför samla magiska böcker","vad är samlingen till för"}}},fp="25,168,20.103.0,27.64.0,35.52.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="Secrets of the Dreamers ger äventyrare i uppdrag att återfinna sällsynta magiska skrifter som kan berika forskarnas arkiv. Genom att lämna in dessa avhandlingar hjälper upptäcktsresande bibliotekets lärda att utöka samlingen av forntida kunskap.",h="Secrets of the Dreamers ger äventyrare i uppdrag att återfinna sällsynta magiska skrifter som kan berika...",kw={"magisk","dreamers","bibliotek","magiska verk","lärda","secrets of the dreamers","böcker"},ang={["class:Druid"]="Med tanke på hänvisningen till Dreamers har skrifter knutna till naturmagi och The Emerald Dream stor betydelse för dem som utövar Cenarionkonsterna.",["class:Mage"]="Lärda magiker är särskilt lämpade att söka efter obskyra böcker och magiska texter runt om i Azeroth för att berika institutionernas arkiv.",["faction:Alliance"]="Alliansens lärda, särskilt de som ansvarar för stora samlingar, förlitar sig på äventyrliga förkämpar som återfinner förlorad kunskap på farliga platser."},sec={{t="Återfinna glömd kunskap",b="Uppdraget Secrets of the Dreamers går ut på att återfinna sällsynta magiska texter och historiska avhandlingar från hela riket. Lärda som ägnar sig åt att dokumentera Azeroths magiska mysterier förlitar sig på resande äventyrare som gräver fram glömda verk och för dem tryggt till arkiven. I stället för att låta dyrbar kunskap förfalla i forntida ruiner eller privata gömmor ser dessa insamlingar till att viktig lärdom studeras och bevaras för kommande generationer."},{t="Utöka arkiven",b="När avhandlingarna lämnas in införlivar arkivarierna dem i sina permanenta samlingar, vilket utökar bibliotekets förståelse av magiska fenomen. I ett bibliotek som detta söker forskare ständigt efter obskyra manuskript om allt från The Emerald Dream till magisk teori. Arbetet blir aldrig helt färdigt, och de lärda tar gärna emot fler magiska skrifter som hittas ute i världen."}},faq={{q="Vad är syftet med uppdraget Secrets of the Dreamers?",a="Secrets of the Dreamers är ett uppdrag där du återfinner magiska verk och obskyr kunskap för att utöka en lärd samling. Äventyrare hittar relevanta föremål ute i världen och lämnar in dem för att berika forskarnas arkiv.",al={"vad är secrets of the dreamers","uppdraget secrets of the dreamers","vad gör man i det här uppdraget"}},{q="Vem samlar in de magiska texterna?",a="Uppdraget tas emot och lämnas in hos en lärd som ansvarar för ett biblioteks samling och ber resande äventyrare att ta med magiska verk.",al={"vem vill ha secrets of the dreamers","vem ger det här uppdraget","var lämnar man in secrets of the dreamers"}},{q="Var förvaras de återfunna verken?",a="De återfunna skrifterna läggs direkt till ett institutionsbiblioteks växande arkiv, så att sällsynt kunskap och magiska upptäckter katalogiseras och bevaras åt Alliansens lärda och forskare.",al={"vad är det för samling","vilket bibliotek är det till","vart tar böckerna vägen"}},{q="Vad syftar titeln på med ”Dreamers”?",a="Dreamers syftar traditionellt på druider som är knutna till The Emerald Dream eller forntida sovande väsen bundna till naturens sömn. Magiska verk som bär på deras hemligheter bevarar en mystisk urkraft.",al={"vilka är dreamers","dreamers i berättelsen","varför heter det dreamers"}},{q="Kan du lämna in fler magiska verk efter att du har slutfört uppdraget?",a="Arkivarierna välkomnar gärna fler bidrag. När du under dina resor hittar ytterligare magiska verk som kan berika samlingen uppmuntras du att lämna in dem och bidra till fortsatt forskning.",al={"kan jag lämna in fler böcker","kan uppdraget göras om","fler magiska verk"}},{q="Varför är det viktigt för de lärda att samla in dessa magiska skrifter?",a="Bibliotek och forskare runt om i Alliansen försöker ständigt fördjupa sin förståelse av det magiska, naturliga och dunkla. Förlorade eller utspridda avhandlingar innehåller insikter som hjälper lärda att upptäcka världens djupare historia och mysterier.",al={"varför samla magiska böcker","varför behöver biblioteket magiska böcker"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="Arcanic Systems Manual",s="Arcanic Systems Manual är ett magiskt verk som efterfrågas till Library i Ironforge. Det hjälper biblioteket att utöka sin kunskap.",h="Arcanic Systems Manual är ett magiskt verk som efterfrågas till Library i Ironforge.",kw={"arcanic","arcanic systems manual","samling","ironforge","bibliotek","magiska verk","handbok"},sec={{t="En plats i biblioteket",b="Library i Ironforge välkomnar magiska verk som kan berika dess samling. Du tar med ett att lägga till, och ditt bidrag hjälper bibliotekets kunskap att växa."}},faq={{q="Vad är Arcanic Systems Manual?",a="Det är ett magiskt verk som efterfrågas till Library i Ironforge.",al={"arcanic handbok","vilken handbok"}},{q="Vem vill ha handboken?",a="Någon på Library i Ironforge ber dig att ta med magiska verk som kan berika dess samling.",al={"vem bad om den","handbok åt vem"}},{q="Varför ta med handboken till biblioteket?",a="Bibliotekets kunskap växer genom bidrag av magiska verk.",al={"varför skänka den","vad är den till för"}}},fp="22,131,22.150.0,35.57.0,21.100.0,36.69.0"}
P.entries["quest:78146"] = {n="Goaz Scrolls",s="Bibliotekarien ber dig att ta med Goaz Scrolls till samlingen. Ditt bidrag utökar bibliotekets kunskap.",h="Bibliotekarien ber dig att ta med Goaz Scrolls till samlingen.",kw={"samling","goaz scrolls","kunskap","bibliotek","magiska verk","rullar"},sec={{t="En växande samling",b="Bibliotekarien tackar dig för att du bidrar med Goaz Scrolls. Fler magiska verk skulle också kunna hjälpa biblioteket, och bibliotekarien tar gärna emot dem."}},faq={{q="Vad används Goaz Scrolls till?",a="Goaz Scrolls utökar bibliotekets samling och kunskap.",al={"goaz scrolls syfte","varför ta med rullar","rullar bibliotek"}},{q="Vem ber om Goaz Scrolls?",a="En bibliotekarie ber dig att ta med Goaz Scrolls till samlingen.",al={"vem vill ha goaz scrolls","rullarnas givare","biblioteksperson"}},{q="Vart ska rullarna?",a="Goaz Scrolls är avsedda för bibliotekets samling.",al={"vart ta rullar","goaz scrolls plats","bibliotekets rullar"}},{q="Vad mer skulle vara till nytta för biblioteket?",a="Bibliotekarien tar gärna emot andra magiska verk som kan vara till nytta för biblioteket.",al={"andra magiska verk","fler biblioteksböcker","vad mer att ta med"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="En bibliotekarie ber dig att utöka samlingen i Ironforge med magiska verk. Dina upptäckter utökar bibliotekets kunskap.",h="En bibliotekarie ber dig att utöka samlingen i Ironforge med magiska verk.",kw={"samling","crimes against anatomy","ironforge","bibliotekarie","bibliotek","magiska verk"},sec={{t="Till samlingen",b="Biblioteket i Ironforge söker magiska verk som kan berika dess samling. Du kan lämna dina upptäckter till bibliotekarien, vars kunskap växer genom dessa bidrag. Fler verk kan ännu komma till nytta för biblioteket."}},faq={{q="Vem efterfrågar magiska verk?",a="En bibliotekarie i Ironforge ber dig att ta med magiska verk som kan berika samlingen.",al={"vem vill ha böcker","bibliotekets förfrågan"}},{q="Var ska jag lämna verken?",a="Lämna dem till bibliotekarien i Library i Ironforge.",al={"var ligger biblioteket","var lämna böcker"}},{q="Varför samla magiska verk?",a="Verken hjälper till att utöka bibliotekets kunskap.",al={"varför böcker","vad används magiska verk till"}}},fp="22,129,18.219.0,27.91.0,27.56.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="Biblioteket i Ironforge tar gärna emot magiska verk till sin samling. Dina upptäckter hjälper till att utöka dess kunskap.",h="Biblioteket i Ironforge tar gärna emot magiska verk till sin samling.",kw={"samling","ironforge","kunskap","bibliotek","magiska verk","runor","trollkarlskungar"},sec={{t="Samlingen",b="Bibliotekets föreståndare tackar dig när samlingen växer genom dina insatser. Fler magiska verk kan utöka dess kunskap, och föreståndaren tar gärna emot dem till biblioteket."}},faq={{q="Vad vill biblioteket ha?",a="Biblioteket tar gärna emot magiska verk som kan berika dess samling.",al={"vad vill de ha","biblioteksböcker","magiska verk"}},{q="Var ligger biblioteket?",a="Biblioteket ligger i Ironforge.",al={"bibliotekets läge","var ligger biblioteket","biblioteket i ironforge"}},{q="Varför lämna in magiska verk?",a="Dina insatser utökar bibliotekets kunskap.",al={"varför böcker","till vad","hjälpa biblioteket"}}},fp="27,111,14.168.0,27.67.0,21.28.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="Library i Ironforge söker magiska verk till sin samling. Dina fynd hjälper till att utöka dess kunskap.",h="Library i Ironforge söker magiska verk till sin samling.",kw={"samling","fury of the land","ironforge","kunskap","bibliotek","magiska verk"},sec={{t="En plats för kunskap",b="På Library i Ironforge ombeds du att ta med magiska verk som kan vara till nytta för samlingen. Bibliotekarien välkomnar det du har hittat och uppmanar dig att ta med mer om du hittar något."}},faq={{q="Vad vill biblioteket ha?",a="Library söker magiska verk som kan vara till nytta för samlingen.",al={"vad behöver de","biblioteksböcker","magiska verk"}},{q="Vart ska jag ta magiska verk?",a="Ta dem till bibliotekarien på Library i Ironforge.",al={"vart ska böcker lämnas","bibliotekets läge","lämna verk"}},{q="Varför samlar de på magiska verk?",a="Bibliotekarien säger att varje bidrag utökar deras kunskap.",al={"varför samla magiska böcker","bibliotekets samling","till vad"}}},fp="16,105,21.187.0,27.64.0,35.56.0,38.61.0"}
P.entries["quest:7815"] = {n="Snapjaws, Mon!",s="I The Hinterlands kan Katoom the Angler från Revantusk Village knappt hålla linan i vattnet, eftersom saltvattens-snapjaws hela tiden förstör den och stjäl hans bete. Han vill att du dödar femton av sköldpaddorna.",h="I The Hinterlands kan Katoom the Angler från Revantusk Village knappt hålla linan i vattnet, eftersom...",kw={"fiskare","bete","fiske","hinterlands","katoom","revantusk","snapjaws","sköldpaddor"},sec={{t="Problem på kroken",b="Katoom uppmanar dig att inte låta snapjaw-sköldpaddornas stora ögon lura dig och kallar dem en plåga. Enligt honom kan han inte fiska i ens fem minuter innan en av dem sliter av linan och smiter med betet. Som en tjänst åt honom själv och hans grannar i byn ber han dig utrota hela gänget. Det handlar om femton stycken."}},faq={{q="Vem ber dig jaga sköldpaddorna?",a="Katoom the Angler, en fiskare från Revantusk i The Hinterlands.",al={"vem ger uppdraget om snapjaws","uppdragsgivare för snapjaws","katoom the angler"}},{q="Varför vill Katoom att saltvattens-snapjaws ska dödas?",a="Katoom säger att de sliter av fiskelinan och stjäl betet, så han inte kan fiska i fred i ens fem minuter.",al={"varför döda snapjaws","sköldpaddsproblem","varför döda sköldpaddor i revantusk"}},{q="Hur många snapjaws måste dödas?",a="Femton saltvattens-snapjaw-sköldpaddor.",al={"hur många sköldpaddor","antal snapjaws","antal snapjaws mon"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="Gammerita, Mon!",s="Katoom the Angler från Revantusk Village i The Hinterlands har förlorat sitt bästa bete till Gammerita, saltvattenssnapjawernas ledare. Du får i uppdrag att hitta henne och ta tillbaka det.",h="Katoom the Angler från Revantusk Village i The Hinterlands har förlorat sitt bästa bete till Gammerita...",kw={"fiskare","gammerita","hinterlands","katoom","bete","revantusk","snapjaw","sköldpadda"},sec={{t="En tjuv bland sköldpaddorna",b="Katoom beskriver Gammerita som en ovanlig sköldpadda: hon leder saltvattenssnapjawerna, och Katoom kallar henne en tjuv. Hon bet av linan och tog hans bästa bete. Sedan dess har fiskarna inte nappat som förr."},{t="Ta tillbaka betet",b="Katoom vill att du hittar Gammerita och hämtar betet ur hennes mage. Gammerita håller till vid kusten bland de andra sköldpaddorna."},{t="Katooms förhoppningar",b="Med betet tillbaka och färre snapjawer omkring sig räknar Katoom med att fiskarna ska komma i mängder."}},faq={{q="Vem är Katoom the Angler?",a="En fiskare från Revantusk i The Hinterlands som ber dig jaga Gammerita.",al={"vem är katoom","katoom revantusk","katooms plats"}},{q="Vad är Gammerita?",a="En ovanlig sköldpadda som leder saltvattenssnapjawerna och som Katoom kallar en tjuv.",al={"vem är gammerita","vad är gammerita","gammerita sköldpadda"}},{q="Varför vill Katoom döda Gammerita?",a="Gammerita bet av Katooms bästa bete från linan, och sedan dess har fiskarna inte nappat som förr. Katoom vill få tillbaka betet ur hennes mage.",al={"varför döda gammerita","vad stal gammerita","katooms motiv"}},{q="Var kan Gammerita hittas?",a="Vid kusten, där hon håller till bland de andra saltvattenssnapjawsköldpaddorna.",al={"var finns gammerita","gammeritas plats","hitta gammerita"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.102.0,18.102.0,36.138.0,29.77.0"}
P.entries["quest:782"] = {n="Broken Alliances",s="I Kargath vill Gorn återupprätta Hordens heder efter alliansen med Deathwing. Ogerhövdingen Boss Tho'grun anlitades för att hjälpa till att hitta Sign of the Earth, men vände sig mot Horden och behöll den. Du ska ta tillbaka den vid Camp Boff.",h="I Kargath vill Gorn återupprätta Hordens heder efter alliansen med Deathwing.",kw={"badlands","blacklash","camp boff","deathwing","gorn","hematus","kargath","lethlor ravine","sign of the earth","tho'grun"},sec={{t="En legohär vänder sig mot Horden",b="Under Andra kriget stod Horden på draken Deathwings sida. Blacklash och Hematus, två av hans löjtnanter, låstes in i Lethlor Ravine, långt österut. Gorn menar att dessa fördärvade forna allierade måste tystas för att Hordens heder ska återupprättas. Horden behövde Sign of the Earth för att öppna drakarnas fängelse och anlitade ogrelegosoldater under Boss Tho'grun för att hitta den. Tho'grun vände sig mot dem, övermannade dem och behöll den själv."},{t="Camp Boff",b="Gorn skickar dig sydost om Kargath till Camp Boff för att döda Tho'grun och föra tillbaka Sign of the Earth. Gorn blir glad när Tho'grun är död och säger att ogres inte längre tillhör Horden."},{t="Vad tecknet öppnar",b="När Tho'grun är död räknar Gorn med att ogres hamnar i oordning, en liten seger som leder till en större. Med Sign of the Earth i Hordens händer kan de svarta drakarnas fängelse i Lethlor öppnas och befria dem från ändlös fångenskap, men också leda dem mot undergången."}},faq={{q="Vem är Gorn?",a="Gorn är Hordens företrädare i Kargath som skickar dig efter Sign of the Earth och vill återupprätta Hordens heder genom att tysta dess fördärvade forna allierade.",al={"vem ger uppdraget broken alliances","gorn kargath","gorns bakgrund"}},{q="Varför vill Gorn att Boss Tho'grun ska dö?",a="Horden anlitade Tho'grun och hans ogrelegosoldater för att hjälpa till att få tag i Sign of the Earth. Tho'grun vände sig mot dem, övermannade dem och behöll den.",al={"varför döda thogrun","tho'gruns förräderi","boss thogrun bakgrund"}},{q="Var ligger Camp Boff?",a="Camp Boff ligger sydost om Kargath.",al={"camp boff plats","var är thogrun","hitta boss thogrun"}},{q="Vad är Sign of the Earth?",a="Det är en nyckel som behövs för att låsa upp drakarnas fängelse i Lethlor Ravine.",al={"sign of the earth","vad gör sign of the earth"}},{q="Vilka drakar är fängslade i Lethlor Ravine?",a="Blacklash och Hematus, två av Deathwings löjtnanter från tiden då Horden var allierad med honom under Andra kriget.",al={"vem finns i lethlor ravine","blacklash och hematus","deathwings löjtnanter"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="A Donation of Wool",s="Thunder Bluff söker ulltyg, och du kan få fullt erkännande där genom att skänka sextio stycken. Andra givare förväntas bidra med tillräckligt med förnödenheter för att stödja insamlingen.",h="Thunder Bluff söker ulltyg, och du kan få fullt erkännande där genom att skänka sextio stycken.",kw={"tyginsamling","donation","erkännande","sextio stycken","thunder bluff","ull","ulltyg"},sec={{t="En tygdonation",b="Thunder Bluff samlar in ulltyg. Skänk sextio stycken för att få fullt erkännande för din generositet. Andra givare i riket förväntas bidra med tillräckligt för att stödja insamlingen."}},faq={{q="Vad vill Thunder Bluff ha för donationer?",a="Thunder Bluff tar emot donationer av ulltyg.",al={"ulldonation","vilket tyg behövs","skänka ull"}},{q="Hur mycket ulltyg ska jag skänka?",a="Skänk sextio stycken ulltyg för att få fullt erkännande från Thunder Bluff.",al={"hur mycket ull","sextio tygstycken","donationsmängd"}},{q="Vad får jag för att skänka ull?",a="Din gåva på sextio stycken ulltyg ger dig fullt erkännande från Thunder Bluff.",al={"erkännande för ulldonation","vad innebär erkännandet","donationsbelöning"}},{q="Varför samlar Thunder Bluff in ull?",a="Thunder Bluff förväntar sig att andra givare i riket bidrar med tillräckligt med ulltyg för att stödja donationsinsamlingen.",al={"varför ullinsamling","vad används ull till","varför samla in tyg"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="A Donation of Wool",s="I Orgrimmar ber uppdraget A Donation of Wool om hjälp med att samla in tyg. Staden har ull i sina förråd och räknar med att fler givare bidrar med tillräckligt för insamlingen.",h="I Orgrimmar ber uppdraget A Donation of Wool om hjälp med att samla in tyg.",kw={"a donation of wool","donation","orgrimmar","erkännande","sextio bitar","ull","ylletyg"},sec={{t="Ull till Orgrimmar",b="Orgrimmar ber dig att skänka sextio stycken ulltyg. I gengäld lovar staden erkännande. Det finns redan en del ull i förråden, och andra givare väntas bidra till insamlingen."}},faq={{q="Vad ber Orgrimmar om?",a="Orgrimmar tar emot donationer av ulltyg.",al={"vad vill de ha","ulldonation"}},{q="Hur mycket ull behöver jag skänka?",a="Orgrimmar ber om sextio stycken ulltyg.",al={"hur mycket ull","sextio ull"}},{q="Vad får jag för att skänka ull?",a="Du får fullt erkännande från Orgrimmar för att skänka sextio stycken ulltyg.",al={"erkännande för donation","belöning för ull"}},{q="Varför samlar Orgrimmar in ull?",a="Orgrimmar samlar in ull för att stödja sin donationskampanj.",al={"ullinsamling","varför ull"}},{q="Har Orgrimmar redan ull?",a="Ja. Orgrimmar har ull i sina förråd och räknar med att andra givare bidrar med tillräckligt för insamlingen.",al={"ullförråd","hur mycket ull"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="En lapp från C ber dig att ensam hämta Horn of Xelthos från Shadowfang Keep. Veenix i Stonetalon Mountains kan hjälpa dig genom porten till borggården.",h="En lapp från C ber dig att ensam hämta Horn of Xelthos från Shadowfang Keep.",kw={"c","hemligt avlämningsställe","horn of xelthos","pyrewood village","shadowfang keep","stonetalon mountains","veenix","xelthos"},sec={{t="I det tysta",b="C lämnar lappen nära Pyrewood Village och anger Veenix som kontakt i Stonetalon Mountains. Horn of Xelthos ligger någonstans inne i Shadowfang Keep, där det vanligtvis krävs förstärkning för att ta sig in. C vill att arbetet sköts i det tysta, så du ska gå ensam och ta med hornet tillbaka till det hemliga avlämningsstället."}},faq={{q="Vem ber om Horn of Xelthos?",a="C lämnar en lapp där du ombeds hämta Horn of Xelthos och lämna det på det hemliga avlämningsstället nära Pyrewood Village.",al={"vem är c","vem vill ha hornet","c hornuppdrag"}},{q="Var finns Horn of Xelthos?",a="Horn of Xelthos finns någonstans inne i Shadowfang Keep.",al={"var finns hornet","hornets plats","hitta xelthos"}},{q="Varför måste jag gå ensam?",a="C säger att arbetet kräver diskretion, så du ska ta dig in i Shadowfang Keep ensam.",al={"varför ensam","varför gå ensam","ingen förstärkning"}},{q="Vem är Veenix?",a="Veenix är C:s kontakt i Stonetalon Mountains och kan hjälpa dig förbi porten till borggården i Shadowfang Keep.",al={"veenix hjälp","vem är veenix","kontakt vid porten"}},{q="Var ska jag lämna tillbaka hornet?",a="Lämna tillbaka hornet på C:s hemliga avlämningsställe nära Pyrewood Village.",al={"var lämna tillbaka hornet","hemliga avlämningsställets plats","lämna in hornet"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="En kontakt från Venture Co. erbjuder sprängämnen för att ta sig förbi Shadowfangs port, men ber dig först hitta en arbetsorder. En annan arbetare från Venture Co. i närheten bör ha en.",h="En kontakt från Venture Co.",kw={"sprängämnen","port","goblin lockpicks","shadowfang","venture co.","arbetsorder"},sec={{t="A Work Order",b="En kontakt från Venture Co. hör att du planerar att ta dig in i Shadowfang ensam. Sprängämnen kan hjälpa dig förbi porten, men kontakten behöver en arbetsorder för att få leveransen att se korrekt ut i företagets bokföring. En annan arbetare från Venture Co. i närheten bör ha dokumentet."}},faq={{q="Varför behöver de en arbetsorder?",a="Kontakten från Venture Co. behöver en arbetsorder för att få sprängämnena att se legitima ut i företagets bokföring.",al={"varför arbetsorder","varför pappersarbete","goblin lockpicks"}},{q="Vad ska sprängämnena användas till?",a="Sprängämnena ska hjälpa dig förbi Shadowfangs port.",al={"vad är sprängämnena till för","shadowfangs port","ta sig förbi porten"}},{q="Vem kan ha arbetsordern?",a="En annan arbetare från Venture Co. i närheten bör ha en arbetsorder.",al={"vem har arbetsorder","hitta pappersarbete","arbetsorder från venture co."}},{q="Ska jag ta mig in i Shadowfang ensam?",a="Kontakten från Venture Co. förstår att du planerar att ta dig in i Shadowfang ensam.",al={"shadowfang ensam","ta sig in ensam","ta sig in i shadowfang"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="Stalking the Stalkers",s="Huntsman Markhor från byn Revantusk i The Hinterlands pekar ut Silvermane-vargarna som ett av de största hoten mot byns jägare. Du får i uppdrag att vända på steken och jaga jägarna.",h="Huntsman Markhor från byn Revantusk i The Hinterlands pekar ut Silvermane-vargarna som ett av de största...",kw={"vargar i the hinterlands","huntsman markhor","revantusk","revantusk village","silvermane howler","silvermane stalker","stalking the stalkers"},sec={{t="Vargar i bakhåll",b="Markhor påpekar att många troll redan har fallit offer för vildmarken i The Hinterlands och räknar Silvermane-vargarna bland de största hoten mot jägarna i Revantusk. Vargarna väntar gömda bland buskarna och i terrängen, och kastar sig över sitt byte när tillfället är det rätta. Markhor tänker inte låta det stå oemotsagt och uppmanar dig att tänka som en Silvermane och vända jakten mot jägarna genom att fälla varenda en."},{t="Vad Markhor begär",b="Markhor vill att du dödar femton Silvermane Stalkers och femton Silvermane Howlers. Markhor tillägger att vargarna håller till ute i vildmarken i The Hinterlands."},{t="Revantusks tack",b="När det är gjort tackar Markhor dig å Revantusks vägnar för det du har gjort för dem."}},faq={{q="Vem ber dig jaga vargarna?",a="Huntsman Markhor från byn Revantusk i The Hinterlands.",al={"vem ger stalking the stalkers","uppdragsgivare stalking the stalkers","markhor uppdrag"}},{q="Varför är Silvermane-vargarna ett sådant hot?",a="Markhor räknar dem bland de största hoten mot jägarna i Revantusk: de gömmer sig bland buskarna och i terrängen och slår till när tillfälle ges, och många troll har redan gått förlorade ute i vildmarken.",al={"varför döda silvermane-vargar","silvermane-vargarnas hot","varför gallra ut vargar i the hinterlands"}},{q="Vilka vargar ska gallras ut?",a="Femton Silvermane Stalkers och femton Silvermane Howlers.",al={"vilka vargar ska dödas","mål för stalking the stalkers","vargarter i the hinterlands"}},{q="Var hittar man vargarna?",a="Markhor säger att de håller till ute i vildmarken i The Hinterlands.",al={"var finns silvermane-vargar","silvermane stalker plats","silvermane howler plats"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="Hunt the Savages",s="Huntsman Markhor från byn Revantusk i The Hinterlands kallar de vilda ugglebestarna några av områdets mest argsinta varelser och ber dig döda tjugo av dem.",h="Huntsman Markhor från byn Revantusk i The Hinterlands kallar de vilda ugglebestarna några av områdets mest...",kw={"the hinterlands","jakten på vildarna","huntsman markhor","ugglebestar","revantusk","revantusk village","vild ugglebest"},sec={{t="Klor och näbbar",b="Markhor beskriver de vilda ugglebestarna som några av The Hinterlands mer argsinta varelser och säger att deras klor och näbbar har kostat Revantusk många goda krigare. Markhor vill att du dödar varenda en du ser, tills du inte står ut med mer blodspillan. Sedan ska ditt bidrag vägas och bedömas. Tjugo måste falla."},{t="Rensa sinnet",b="Markhors råd inför jakten är att rensa sinnet från orena tankar och förena dig med vildmarken. Ugglebestarna finns ute i The Hinterlands vildmarker."},{t="Markhors dom",b="Efter jakten kallar Markhor dig en värdig vän till Revantusk."}},faq={{q="Vem erbjuder den här jakten?",a="Huntsman Markhor från byn Revantusk i The Hinterlands.",al={"vem ger jakten på vildarna","uppdragsgivare för jakten på vildarna","huntsman markhor uppdrag"}},{q="Varför vill Markhor att de vilda ugglebestarna dödas?",a="Markhor kallar dem argsinta och säger att de har krävt många goda krigare från Revantusk med sina klor och näbbar.",al={"varför döda vilda ugglebestar","orsak till ugglebestjakten","varför jaga vildarna"}},{q="Var finns de vilda ugglebestarna?",a="Markhor säger att de håller till i The Hinterlands vildmarker.",al={"vilda ugglebestars plats","var finns vilda ugglebestar","ugglebestar i the hinterlands"}},{q="Hur många vilda ugglebestar måste dödas?",a="Tjugo vilda ugglebestar.",al={"hur många ugglebestar ska dödas","krav för jakten på vildarna"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="A Threat Within",s="Frivilliga svarar på Stormwinds uppmaning i Northshire Valley, där det lokala försvaret behöver hjälp. I Northshire Abbey förklarar Marshal McBride att rikets styrkor är hårt ansatta utomlands, så garnisonerna hemma saknar folk när oroligheter uppstår.",h="Frivilliga svarar på Stormwinds uppmaning i Northshire Valley, där det lokala försvaret behöver hjälp.",kw={"ett hot inifrån","kloster","elwynn forest","marshal mcbride","northshire","rekrytering","stormwind guard","frivilliga"},ang={["faction:Alliance"]="Som medlem av Alliansen ser du hur åtaganden i avlägsna länder lämnar även dess kärnland utsatt för oroligheter på hemmaplan.",["race:Human"]="Som mänsklig försvarare från Northshire är ditt svar på Marshal McBrides uppmaning ditt första officiella löfte att skydda ditt hemland och kungariket Stormwind."},sec={{t="Ett rike med spridda styrkor",b="Northshire Valley gav en gång ro för bön, jordbruk och klosterstudier. Nu är dalen Elwynn Forests första försvarslinje mot oroligheter på hemmaplan. Stormwinds reguljära styrkor tjänstgör på avlägsna fronter, så kärnlandet saknar soldater. Med få vakter i närheten måste Stormwind Guard kalla på varje villig frivillig som kommer till klostret."},{t="Marshalens uppmaning",b="Marshal McBride leder försvaret av Northshire Valley från Northshire Abbey medan trycket ökar. Avlägsna faror hotar Alliansen, samtidigt som banditer, skadedjur och ohyra från underjorden utnyttjar bristen på soldater i hemtrakterna. Du svarar på uppmaningen att tjänstgöra i dalen och börjar med marken kring klostret, medan hoten sprider sig över Elwynn."}},faq={{q="Vad är syftet med det här uppdraget?",a="Marshal McBride kallar nyanlända till Northshire Valley för att delta i försvaret. Du går in i Northshire Abbey och rapporterar till honom.",al={"uppdraget hot inifrån","vad är det här för uppdrag","introduktionsuppdrag northshire"}},{q="Vem är Marshal McBride?",a="Marshal McBride är den högste officeren i Stormwind Guard vid Northshire Abbey. Han leder försvaret av dalen och ger rekryterna uppdrag att hantera hot på landsbygden i närheten.",al={"marshal mcbride","vem är mcbride","klostrets befälhavare"}},{q="Varför rekryterar Stormwind frivilliga i stället för att skicka reguljära soldater?",a="Stormwinds reguljära styrkor tjänstgör utomlands för att skydda Alliansen. Eftersom garnisonerna i kärnlandet saknar soldater förlitar sig lokala befälhavare på frivilliga för att försvara hemtrakterna.",al={"varför frivilliga","var är vakterna","varför har stormwind för få soldater"}},{q="Vilka hot plågar Northshire Valley just nu?",a="Kobolder härjar i de närliggande gruvorna och kullarna, medan sjuka eller rovgiriga skadedjur stör vingårdarna. Rövare och fredlösa utnyttjar också dalens försvagade garnison.",al={"hot i dalen","vad anfaller northshire","problem i northshire"}},{q="Vart leder det här uppdraget härnäst?",a="När du har rapporterat till Marshal McBride skickas du för att rensa kullarna från kobolder, hjälpa lokala bönder och arbetare samt undersöka den växande närvaron av organiserade banditer.",al={"nästa uppdrag","vad kommer efter hot inifrån","mcbrides uppföljning"}},{q="Varför används Northshire Abbey som militär ledningspost?",a="Northshire Abbey är en helig plats för studier och tro, men dess stenmurar och centrala läge gör det till dalens praktiska bas. Eftersom den lokala myndigheten är hårt pressad har Stormwind Guard upprättat sitt högkvarter i klostret.",al={"varför militär i klostret","northshires kyrka militär","soldater i det heliga klostret"}}},fx={["2039075b"]={q="Varför skickar Deputy Willem dig till Marshal McBride?",a="Deputy Willem är stationerad utanför Northshire Abbey för att så snabbt som möjligt bedöma nyanlända som är stridsdugliga. Kungarikets militär är hårt ansträngd och flera kriser närmar sig Northshires gränser, så han behöver se till att varje kapabel frivillig tas in i tjänst. I stället för att själv dela ut uppdrag skickar Willem dig direkt till sin befälhavare, Marshal McBride, så att du kan få en formell genomgång och skickas dit dalens försvar sviktar mest.",al={"varför tala med mcbride","willems motiv"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="Avenging the Fallen",s="Huntsman Markhor från Revantusk Village säger att Wildhammer tränar gryfer att döda troll, och han vill att regionens äldre gryfer, Skylords, utrotas. Du ska döda en Razorbeak Skylord och ta med dess fjäderplym tillbaka till honom.",h="Huntsman Markhor från Revantusk Village säger att Wildhammer tränar gryfer att döda troll, och han vill att...",kw={"avenging the fallen","gryp","the hinterlands","huntsman markhor","razorbeak skylord","revantusk village","skylords fjäderplym","wildhammer"},sec={{t="Att döda Skylords",b="Markhor, en jägare från Revantusk Village i The Hinterlands, är bitter över att Wildhammer tränar gryfer att döda troll. Rättvisan ska hinna ikapp dem, lovar han, men först vill han att du ger dig på regionens äldre gryfer, Skylords. Döda en och återvänd med dess fjäderplym. Razorbeak Skylord är en sällsynt ras som brukar hålla till i The Hinterlands vildmarker, och Markhor klandrar den för att den föder upp mordiska ungar."},{t="Fjäderplymen granskad",b="Markhor granskar fjäderplymen och undrar högt hur många jägare besten slukade innan den fick möta rättvisan genom din hand."}},faq={{q="Vem erbjuder jakten?",a="Huntsman Markhor erbjuder den i Revantusk Village i The Hinterlands.",al={"uppdragsgivare","vem ger avenging the fallen","var finns markhor"}},{q="Varför vill Huntsman Markhor att en Skylord ska dödas?",a="Markhor säger att Wildhammer tränar gryfer att döda troll, och han vill att regionens äldre gryfer, Skylords, ska utrotas. Han säger att Razorbeak Skylord är en sällsynt ras som föder upp mordiska ungar.",al={"varför döda razorbeak skylord","varför döda skylord","varför jaga gryfer"}},{q="Var kan man hitta en Razorbeak Skylord?",a="Markhor säger att denna sällsynta ras håller till i The Hinterlands vildmarker.",al={"var finns skylord","var finns razorbeak skylord","var finns skylords fjäderplym"}},{q="Vad måste du ta med tillbaka till Markhor?",a="Döda en Razorbeak Skylord och återvänd till Markhor med dess fjäderplym.",al={"vilket föremål behöver jag","målet med avenging the fallen","skylord-byte"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="A Donation of Wool",s="Ett troll från Darkspear samlar in ulldonationer, och dina sextio stycken Wool Cloth blir en del av en större insamling.",h="Ett troll från Darkspear samlar in ulldonationer, och dina sextio stycken Wool Cloth blir en del av en större...",kw={"insamling","darkspear","donation","förråd","troll","ull","wool cloth"},sec={{t="En gemensam insamling",b="Trollen i Darkspear samlar in Wool Cloth för att fylla på sina förråd. Insamlaren kan ta emot dina sextio stycken nu, medan hjälp från andra väntas slutföra insamlingen."}},faq={{q="Vad samlas in?",a="Trollen i Darkspear samlar in Wool Cloth.",al={"vad behöver de","ulldonation"}},{q="Hur mycket Wool Cloth behöver de från mig?",a="Insamlaren behöver sextio stycken Wool Cloth från dig.",al={"hur mycket ull","sextio tyg"}},{q="Varför samlar trollen in ull?",a="Trollen samlar in ull för att fylla på sina förråd.",al={"varför ull","till vad"}},{q="Kan jag lämna tyget nu?",a="Ja. Insamlaren kan ta emot dina sextio stycken Wool Cloth nu.",al={"var lämna ull","donera nu"}}},fp="18,103,19.181.0,24.46.0,41.56.0,35.56.0,25.66.0"}
P.entries["quest:7839"] = {n="Vilebranch Hooligans",s="Smith Slagtree från Revantusk Village säger att Vilebranch-troll invaderade byn och stal hans verktyg. Han har reservverktyg, men den stulna uppsättningen var en gåva från en godhjärtad gnom som räddade hans liv när han var en ung orch, och han vill ha den tillbaka.",h="Smith Slagtree från Revantusk Village säger att Vilebranch-troll invaderade byn och stal hans verktyg.",kw={"agol'watha","the hinterlands","markhor","revantusk village","shaol'watha","skulk rock","slagtrees förlorade verktyg","smith slagtree","vilebranch"},sec={{t="En gåva från en gnom",b="Vilebranch-troll invaderade Revantusk Village och stal Smith Slagtree verktyg. Han har reservverktyg, men den stulna uppsättningen var en gåva från en godhjärtad gnom som räddade hans liv när han var en ung orch. Han säger att verktygen betyder allt för honom och ber dig hämta tillbaka dem."},{t="Var verktygen sågs",b="Slagtree säger att Markhor rapporterade att han sett verktygen nära templen Agol'watha och Shaol'watha, i den nordöstra delen av The Hinterlands. Han tillägger att du också bör undersöka Skulk Rock och varnar för att områdets Vilebranch-troll är hänsynslösa och mordiska."}},faq={{q="Varför är de här stulna verktygen så viktiga för Smith Slagtree?",a="Uppsättningen var en gåva från en godhjärtad gnom som räddade Slagtrees liv när han var en ung orch. Han har reservverktyg, men säger att de här betyder allt för honom.",al={"varför bryr sig slagtree om sina verktyg","slagtree förlorade verktyg lore","varför är slagtrees verktyg speciella"}},{q="Vem stal verktygen från Revantusk Village?",a="Vilebranch-troll invaderade byn och stal Smith Slagtree verktyg.",al={"vem tog verktygen","vem stal slagtrees verktyg"}},{q="Vart fördes de försvunna verktygen?",a="Markhor såg dem nära templen Agol'watha och Shaol'watha, i den nordöstra delen av The Hinterlands. Slagtree säger också att du ska undersöka Skulk Rock.",al={"var finns slagtrees verktyg","var hittar man verktygen","slagtree verktygens plats"}},{q="Vem rapporterade att verktygen hade setts efter räden?",a="Markhor var den som berättade för Slagtree var verktygen hade setts.",al={"vem såg verktygen","vem rapporterade om de stulna verktygen"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="Vanquish the Betrayers",s="Vid Tiragarde Keep håller Kul Tiran-styrkor ett kustfäste i Durotar. Gar'Thok har beordrat en Horde-attack mot löjtnant Benedicts garnison, vars närvaro bryter den bräckliga freden med Theramore.",h="Vid Tiragarde Keep håller Kul Tiran-styrkor ett kustfäste i Durotar.",kw={"daelin proudmoore","durotar","gar'thok","kul tiras","löjtnant benedict","marinsoldater","razor hill","sjömän","tiragarde keep","vanquish the betrayers"},ang={["faction:Horde"]="Kul Tirans ockupation av Tiragarde Keep är en pågående krigshandling vid Durotars gräns. När Benedicts styrkor drivs bort visar Horde att den kan försvara sitt nybyggda hem mot främmande flottor.",["race:Orc"]="Orcher hedrar vapenvilan med Jaina vid Mount Hyjal, men Kul Tiras väcker bittra minnen av det andra kriget. Att strida mot Benedicts marinsoldater handlar om överlevnad och stolthet över förfäderna.",["race:Troll"]="Tiragarde Keep ligger oroväckande nära Sen'jin Village, Darkspear-folkets bosättning. Att driva bort dess fientliga sjömän hjälper till att skydda trollens sårbara nya hem."},sec={{t="En bruten vapenvila",b="Thrall ledde Horde över Great Sea till Kalimdor, där han förenade sig med Lady Jaina Proudmoore mot Burning Legion vid Mount Hyjal. Freden bröts när Jainas främmande far, storamiral Daelin Proudmoore, förde Kul Tiras flotta till Durotar. Han beskyllde alla orcher för den gamla Hordes grymheter och intog kustfästen, däribland Tiragarde Keep. Daelin dog vid Theramore, men resterna av hans flotta vägrar fortfarande alla överenskommelser och ger inte upp sitt hat."},{t="Benedicts återkomst",b="Tiragarde Keep föll en kort tid efter storamiralens nederlag, men reserver från Kul Tiras under löjtnant Benedict återtog det. Fästningen ligger mellan Razor Hill och Sen'jin Village. Därifrån trakasserar sjömän och marinsoldater resenärer och hotar Durotars östra sjövägar. Gar'Thok ser deras position som ett omedelbart hot mot Durotars säkerhet och kallar Hordes krigare till angrepp mot Benedicts befäl."}},faq={{q="Varför anfaller Kul Tiran-människor Durotar?",a="De är rester av storamiral Daelin Proudmoores expeditionsflotta. Daelin avvisade fredlig samexistens mellan människor och orcher och ville förgöra Durotar. Även efter hans död ockuperar hans lojalister fortfarande kustfästen som Tiragarde Keep och trotsar Horde.",al={"varför finns människor i durotar","kul tiras anfaller","tiragarde keep människornas bakgrund"}},{q="Vem är löjtnant Benedict?",a="Löjtnant Benedict leder reserverna från Kul Tiran som håller Tiragarde Keep. Efter storamiral Proudmoores nederlag samlade Benedict de överlevande marinsoldaterna och sjömännen, återtog kustbefästningen och inledde ständiga angrepp mot orcherna.",al={"vem är benedict","löjtnant benedicts bakgrund","ledare för tiragarde keep"}},{q="Stöder Jaina Proudmoore de här människorna?",a="Nej. Jaina slöt en överenskommelse med krigshövding Thrall för att de skulle överleva tillsammans och motarbetade aktivt sin fars aggressiva korståg för att bevara freden. Trupperna vid Tiragarde Keep är rester från Kul Tiras som avvisar Theramores diplomati och ser Jainas vapenvila som förräderi.",al={"stödjer jaina dem","alliansen mellan theramore och kul tiras","jaina proudmoore tiragarde"}},{q="Varför kallas de \"förrädare\"?",a="Gar'Thok kallar dem förrädare eftersom deras invasion bröt den överenskommelse som Thrall och Jaina Proudmoore slöt för att besegra Archimonde under det tredje kriget. Deras fortsatta militära närvaro på Hordes suveräna territorium trotsar de gränser som upprättades på Kalimdor efter kriget.",al={"varför förrädare","vem förrådde vem","förrädarnas betydelse"}},{q="Var ligger Tiragarde Keep?",a="Tiragarde Keep ligger på Durotars östkust, söder om Razor Hill och strax nordost om Sen'jin Village. Dess höga stenmurar blickar ut över kustvattnen och ger inkräktarna en strategisk bas nära Hordes bosättningar.",al={"tiragarde keep plats","var ligger tiragarde keep","var hittar man benedict"}}},fx={["6a077d02"]={q="Varför vill Gar'Thok att Tiragarde Keep rensas?",a="Gar'Thok ansvarar för försvaret av Razor Hill och östra Durotar. Att fientliga Kul Tiran-styrkor återtagit Tiragarde Keep hotar orchernas hemland direkt och trotsar freden mellan Thrall och Jaina Proudmoore. Om en beväpnad människofästning tillåts ligga kvar på Durotars kust utsätts närliggande bosättningar och försörjningsleder omedelbart för invasionsrisk.",al={"gar'thoks motiv","varför rensa tiragarde keep","varför anfaller gar'thok människor"}},["902328ad"]={q="Vilka ska du slå ut i Tiragarde Keep?",a="Du ska slå ut de kvarvarande Kul Tiran-sjöstridskrafterna som ockuperar Tiragarde Keep: sjömännen, marinsoldaterna och deras befälhavare, Lieutenant Benedict. Dessa soldater är resterna av storamiral Daelin Proudmoores flotta och håller en obehörig väpnad landstigning långt inne på Hordens suveräna territorium.",al={"vem ska dödas i tiragarde keep","vilka är målen","mål för att besegra förrädarna"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="Lard Lost His Lunch",s="Lard, från byn Revantusk i The Hinterlands, är hungrig och rädd. En Vilebranch slog till Lard under en privat picknick, och Lard flydde utan maten. Du ombeds hämta den från en ö i norr.",h="Lard, från byn Revantusk i The Hinterlands, är hungrig och rädd.",kw={"the hinterlands","ö","lard","mat","picknick","revantusk village","vilebranch"},sec={{t="En avbruten picknick",b="Lard hade picknick på en hemlig plats när en Vilebranch, ful och elak enligt Lard, slog till Lard med en stor käpp. Lard rusade till Revantusk och lämnade maten kvar. Nu är Lard hungrig och rädd för att gå tillbaka."},{t="Ön i norr",b="Picknickplatsen ligger på en ö i norr. Lard hoppas att du går dit, hittar maten och tar tillbaka den, och ser upp för Vilebranch-trollen."},{t="Lards tack",b="Maten visar sig vara en enorm köttbit. Lard slukar den, tackar dig och lovar dig en särskild picknickkorg som tack för hjälpen."}},faq={{q="Vem är Lard?",a="En invånare i Revantusk i The Hinterlands, hungrig och rädd efter att en Vilebranch slog till Lard med en stor käpp.",al={"lard the hinterlands","vem är lard","lard revantusk"}},{q="Var tappade Lard bort maten?",a="På en undangömd picknickplats på en ö i norr.",al={"var är lards mat","lards picknickplats","lards hemliga plats"}},{q="Varför lämnade Lard maten kvar?",a="En Vilebranch slog till Lard med en stor käpp under picknicken, och Lard sprang tillbaka till Revantusk utan maten.",al={"varför sprang lard","vem attackerade lard"}},{q="Vad bör du se upp för på ön?",a="Lard pekar ut Vilebranch-trollen som faran på ön.",al={"vilebranch på ön","faror på lards ö"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="Message to the Wildhammer",s="I Revantusk Village i The Hinterlands säger Otho Moji'ko att Wildhammer sluter avtal med trollens fiender, och den här gången är högalverna deras partner. Otho vill skicka ett budskap till Wildhammer-dvärgarna, skrivet i Highvale-högalvernas blod vid Quel'Danil Lodge.",h="I Revantusk Village i The Hinterlands säger Otho Moji'ko att Wildhammer sluter avtal med trollens fiender...",kw={"highvale","hinterlands","budskap till wildhammer","otho mojiko","quel'danil lodge","revantusk village","wildhammer"},sec={{t="Ett budskap i blod",b="Wildhammer knyter nya allianser med trollens fiender, och den här gången är högalverna deras partner. Otho Moji'ko spottar åt tanken. Dvärgarna förtjänar ett budskap, skrivet i deras nya vänners blod: slakta varje Highvale-högälv du stöter på och lämna kropparna som en varning. Highvale Outrunners, Scouts, Marksmen och Rangers samlas vid Quel'Danil Lodge, i nordvästra The Hinterlands."},{t="Nytt från Revantusk Village",b="När du återvänder förklarar Otho att Revantusk också knyter nya allianser och berömmer ditt arbete."}},faq={{q="Vem erbjuder det här uppdraget?",a="Otho Moji'ko, som står i Revantusk Village.",al={"vem ger budskap till wildhammer","otho mojiko uppdrag"}},{q="Var finns Highvale-högalverna?",a="De samlas vid Quel'Danil Lodge, i nordvästra The Hinterlands.",al={"quel danil lodge plats","var finns highvale-alver","var hittar man highvale-scouter"}},{q="Varför vill Otho Moji'ko att högalverna ska attackeras?",a="Otho säger att Wildhammer sluter avtal med trollens fiender, och att de nu samarbetar med högalverna. Otho vill skicka ett budskap till Wildhammer-dvärgarna, skrivet i högalvernas blod.",al={"varför attackera quel danil","varför döda högalver i hinterlands"}},{q="Vilka Highvale-alver vill Otho att du ska slakta?",a="Highvale Outrunners, Scouts, Marksmen och Rangers vid Quel'Danil Lodge.",al={"vilka highvale-alver","highvale marksman","highvale ranger"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="Another Message to the Wildhammer",s="Efter det första meddelandet säger Otho Moji'ko i Revantusk Village att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner. Motbjudande, men det kan användas mot dem. Otho vill att gryfer i The Hinterlands dödas för sina fjädrar.",h="Efter det första meddelandet säger Otho Moji'ko i Revantusk Village att Wildhammer och deras gryfer står...",kw={"grýf","hinterlands","long elegant feather","otho moji'ko","revantusk village","wildhammer"},sec={{t="Ett fjädermeddelande",b="Efter Highvale-högalverna har Otho Moji'ko ett nytt meddelande att skicka. Det sägs att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner, vilket Otho tycker är motbjudande men användbart. Döda gryferna du stöter på i The Hinterlands och samla in deras Long Elegant Feathers. Gryfer sägs leva i varje del av området. Av fjädrarna ska Otho göra det sista meddelandet."},{t="Othos förtjusning",b="Otho räknar med att det sista meddelandet ska skrämma bort Wildhammer eller göra dem väldigt, väldigt arga. Otho är förtjust över att bara ett steg återstår innan Wildhammer inser att troll inte kan trotsas."}},faq={{q="Vem ger det här uppdraget?",a="Otho Moji'ko, som står i Revantusk Village.",al={"vem ger ett nytt meddelande till wildhammer","uppdragsgivare för ännu ett meddelande","otho mojiko"}},{q="Varför vill Otho Moji'ko ha gryffjädrar?",a="Otho säger att Wildhammer och deras gryfer står varandra lika nära som en troll och en partner, och vill använda det mot dem. Fjädrarna ska ingå i det sista meddelandet.",al={"varför gryffjädrar","varför döda gryfer i hinterlands"}},{q="Var finns gryfer?",a="Gryfer sägs leva i alla delar av The Hinterlands.",al={"gryffplatser i hinterlands","var finns hinterlands gryfer"}},{q="Vad föregick det här meddelandet?",a="Det följer på Message to the Wildhammer, där Otho lät döda Highvale-högalver som en varning till dvärgarna.",al={"vad kommer före another message to the wildhammer","message to the wildhammer uppdragskedja"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="The Final Message to the Wildhammer",s="Otho Moji'ko ger dig ett spjut dränkt i blod och bundet med gripfjädrar. Du ska ta det till Aerie Peak, i västra The Hinterlands, och stöta ner det i jorden bredvid brunnen mitt i staden.",h="Otho Moji'ko ger dig ett spjut dränkt i blod och bundet med gripfjädrar.",kw={"aerie peak","gripfjädrar","hinterlands","otho moji'ko","revantusk village","spjut","wildhammer"},sec={{t="Ett spjut till Aerie Peak",b="Efter Another Message to the Wildhammer ger Otho Moji'ko dig det sista meddelandet: ett spjut dränkt i blod och bundet med gripfjädrar. Bär det till Aerie Peak och plantera det mitt i staden, bredvid brunnen, för att visa dvärgarna att trollen menar allvar. Otho hoppas att du kommer tillbaka levande och varnar för rasande Wildhammer-dvärgar och stökigt Alliance-folk."},{t="Othos förhoppning",b="Otho önskar att han hade fått se dvärgarnas ansikten och undrar högt om de packar sina väskor och lämnar staden. Otho lovar dig stort mojo för dådet."}},faq={{q="Vem skickar dig för att plantera spjutet?",a="Otho Moji'ko, som står i Revantusk Village.",al={"uppdragsgivare","vem ger uppdraget","otho mojiko"}},{q="Var måste spjutet planteras?",a="Bredvid brunnen mitt i Aerie Peak, i västra The Hinterlands.",al={"spjutets plats","var ska jag placera spjutet","aerie peak-brunnen"}},{q="Vad består det sista meddelandet av?",a="Ett spjut dränkt i blod och bundet med gripfjädrar.",al={"vad är spjutet","spjut med gripfjädrar","föremålet sista meddelandet"}},{q="Vad kom före detta i kedjan?",a="Det följer på Another Message to the Wildhammer, där Otho bad om gripfjädrar till detta sista meddelande.",al={"föregående uppdrag","förkunskapskrav","wildhammer-meddelandekedjan"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="Cannibalistic Cousins",s="Mystic Yayo'jin i Revantusk Village kallar Vilebranch-trollen ett fördärvat släkte som ger sig på andra troll och humanoider. Eftersom Zul'jin inte är där för att utrota dem ber hon dig döda deras Scalpers och Soothsayers nära templen i norr-nordost.",h="Mystic Yayo'jin i Revantusk Village kallar Vilebranch-trollen ett fördärvat släkte som ger sig på andra troll...",kw={"agol'watha","cannibalistic cousins","mystic yayo'jin","revantusk village","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},sec={{t="Tre stammar, ett land",b="Tre trollstammar lever i Hinterlands, och Mystic Yayo'jin säger att de, bortsett från att vara troll i samma land, har lite gemensamt. Hon kallar Vilebranch, med rätta, ett fördärvat släkte som ger sig på andra troll och humanoider. Zul'jin skulle lätt ha utrotat dem, men Zul'jin är inte där, och Revantusk får klara sig på egen hand."},{t="Där Vilebranch samlas",b="Yayo'jin ber dig döda Vilebranch Scalpers och Soothsayers, som håller till runt templen Shaol'watha och Agol'watha, i Hinterlands nord-nordöstra del."},{t="Yayo'jins beröm",b="När du kommer tillbaka förklarar Yayo'jin att inte ens Zul'jin hade kunnat göra det bättre."}},faq={{q="Vem erbjuder det här uppdraget?",a="Mystic Yayo'jin, som står i Revantusk Village.",al={"uppdragsgivare för cannibalistic cousins","vem ger cannibalistic cousins","mystic yayo'jin"}},{q="Varför vill Yayo'jin att Vilebranch ska utrotas?",a="Hon kallar Vilebranch ett fördärvat släkte som ger sig på andra troll och humanoider, och säger att det faller på dig att utrota regionens avskum.",al={"varför revantusk slåss mot vilebranch","vilebranch-kannibalism","konflikten mellan revantusk och vilebranch"}},{q="Var hittar man Vilebranch-trollen?",a="Runt templen Shaol'watha och Agol'watha, i Hinterlands nord-nordöstra del.",al={"shaol'wathas plats","agol'wathas plats","var finns vilebranch soothsayers"}},{q="Vilka Vilebranch vill Yayo'jin att du ska utrota?",a="Vilebranch Scalpers och Vilebranch Soothsayers.",al={"mål för cannibalistic cousins","vem ska jag döda för cannibalistic cousins"}},{q="Var är Zul'jin?",a="Inte i Hinterlands just nu. Yayo'jin säger att om Zul'jin vore där skulle han lätt utrota Vilebranch, men han är inte där, så Revantusk får klara sig på egen hand.",al={"är zul'jin här","var är zul'jin i hinterlands","zul'jins status"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="Kidnapped Elder Torntusk!",s="Primal Torntusk från Revantusk Village säger att Vilebranch-vildar rövade bort hennes partner, Elder Torntusk, under en djärv nattlig räd. Spioner säger att han lever och hålls fången på toppen av Jintha'alor, och hon ber dig rädda honom.",h="Primal Torntusk från Revantusk Village säger att Vilebranch-vildar rövade bort hennes partner, Elder...",kw={"elder torntusk","hakkar","hexx","hinterlands","jintha'alor","primal torntusk","revantusk","torntusk","vilebranch"},sec={{t="En nattlig räd",b="Vilebranch-vildar slog till mot Revantusk Village vid midnatt och tog Elder Torntusk, Primal Torntusks partner. Hennes spioner säger att han fortfarande lever och hålls fången på toppen av Jintha'alor, Vilebranchs huvudstad i södra Hinterlands. Primal Torntusk fruktar att byn inte skulle klara av att förlora honom."},{t="Den ansiktslösa blodguden",b="Det sägs att Vile Priestess Hexx gör fången redo att offras till Hakkar, den ansiktslösa blodguden."},{t="När du når honom",b="När du når Elder får du veta att du måste skynda dig, för vakterna känner säkert redan till att du har kommit."}},faq={{q="Vem tog Elder Torntusk?",a="Vilebranch-vildar tog honom under en djärv nattlig räd mot Revantusk Village.",al={"vem kidnappade elder torntusk","vem tog torntusk","torntusks kidnappare"}},{q="Var hålls Elder Torntusk fången?",a="Hennes spioner säger att han hålls fången på toppen av Jintha'alor, Vilebranchs huvudstad i södra Hinterlands.",al={"elder torntusks plats","var är elder torntusk","var hålls torntusk fången"}},{q="Vilket öde väntar Elder Torntusk på toppen av Jintha'alor?",a="Det sägs att Vile Priestess Hexx gör honom redo att offras till Hakkar, den ansiktslösa blodguden.",al={"varför tillfångatogs torntusk","vad vill vilebranch med torntusk","hexx offrar torntusk"}},{q="Vem är Primal Torntusk?",a="Primal Torntusk är Elder Torntusks partner, och hon ber dig rädda honom.",al={"vem är primal torntusk","primal torntusks partner"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="Recover the Key!",s="I Jintha'alor är Elder Torntusk fjättrad och ber dig befria honom. Hitah'ya the Keeper har hans nyckel i en bevakad grotta i närheten.",h="I Jintha'alor är Elder Torntusk fjättrad och ber dig befria honom.",kw={"elder torntusk","hinterlands","hitah'ya the keeper","jintha'alor","recover the key","revantusk","nyckel till bojorna"},sec={{t="Väktarens grotta",b="Efter Kidnapped Elder Torntusk! hittar du Elder Torntusk fjättrad i Jintha'alor. Hitah'ya the Keeper har nyckeln till hans bojor i en grotta i närheten, där hon är väl bevakad. Elder Torntusk ber dig döda henne och hämta tillbaka nyckeln. Då kan han lossa sina bojor och återvända hem."},{t="Elder Torntusks tack",b="Med nyckeln kan Elder Torntusk resa sig. Han tackar dig och säger att Revantusk ska få höra om dina bedrifter."}},faq={{q="Vem har nyckeln till Elder Torntusks bojor?",a="Hitah'ya the Keeper har nyckeln till Elder Torntusks bojor. Han säger att hon är i en grotta i närheten, där hon är väl bevakad.",al={"vem har nyckeln","hitahya the keeper","var finns nyckeln till bojorna"}},{q="Var hålls Elder Torntusk fången?",a="Elder Torntusk hålls fången i Jintha'alor.",al={"var är elder torntusk","torntusks plats","jintha'alor torntusk"}},{q="Varför behöver Elder Torntusk nyckeln?",a="Nyckeln öppnar Elder Torntusks bojor. Han säger att han kan återvända hem när han är fri.",al={"varför behövs nyckeln till bojorna","vad är nyckeln till för"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="Return to Primal Torntusk",s="Elder Torntusk ber dig återvända till hans partner, Primal Torntusk, i Revantusk Village och berätta att han är på väg hem.",h="Elder Torntusk ber dig återvända till hans partner, Primal Torntusk, i Revantusk Village och berätta att han...",kw={"elder torntusk","the hinterlands","jintha'alor","primal torntusk","revantusk","revantusk village"},sec={{t="Nyheter till hans partner",b="Elder Torntusk är fri från sina bojor och ber dig återvända till Revantusk Village. Där ska du berätta för hans partner, Primal Torntusk, att han är på väg hem."},{t="Byborna är tacksamma",b="Primal Torntusk säger att du har gjort mycket för Revantusk och att byn står i stor tacksamhetsskuld till dig."}},faq={{q="Vem skickar dig på den här resan?",a="Elder Torntusk ber dig framföra nyheten om hans räddning till hans partner.",al={"vem startar return to primal torntusk","elder torntusk uppdragsgivare"}},{q="Var finns Primal Torntusk?",a="Primal Torntusk finns i Revantusk Village i The Hinterlands.",al={"var finns primal torntusk","primal torntusk plats","var lämnar man in return to primal torntusk"}},{q="Vad ska jag säga till Primal Torntusk?",a="Att Elder Torntusk är på väg hem.",al={"vad ska sägas till primal torntusk","meddelande till torntusk"}},{q="Vad hände före den här resan?",a="Den följer efter Recover the Key!, efter det tidigare försöket som började med Kidnapped Elder Torntusk!",al={"föregående uppdrag","primal torntusk uppdragskedja"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="Separation Anxiety",s="Huntsman Markhor i Revantusk Village har förlorat sin tvillingbror Malkhor, som togs av Vilebranch i samma räd som tog Torntusks partner. Malkhor fick ett snabbt och brutalt slut, och hans kvarlevor åts upp av Vilebranchs slemvarelser och vargar. Markhor säger att hans brors liv inte längre går att rädda, men att hans själ fortfarande kan räddas, och ber dig återfinna kvarlevorna.",h="Huntsman Markhor i Revantusk Village har förlorat sin tvillingbror Malkhor, som togs av Vilebranch i samma...",kw={"ben","hinterlands","jintha'alor","malkhor","markhor","revantusk","skalle","vilebranch","yayo'jin"},sec={{t="En tvillings förlust",b="Markhor säger att många i byn har förlorat nära och kära i vildmarken, och att hans egen förlust är hans tvilling Malkhor. Vilebranch tog Malkhor under räden då de också tog Torntusks partner. Malkhor var dömd att dö, och hans tillfångatagare gav honom en snabb och brutal död."},{t="Där kvarlevorna finns",b="Vilebranch matade sina slemvarelser och vargar med det som återstod av Malkhor. En avfallsgrop full av slemvarelser och ett varggryt ligger båda nära toppen av templet i Jintha'Alor. Hans ben ligger mitt i en slampöl nära det översta planet, och hans skalle ligger på själva översta planet. Markhor tänker ta kvarlevorna till Yayo'jin, som ska förbereda dem för en riktig begravning."}},faq={{q="Vem var Huntsman Malkhor?",a="Malkhor var Huntsman Markhors tvillingbror. Vilebranch tog honom under räden då de också tog Torntusks partner och gav honom en snabb och brutal död.",al={"vem är malkhor","markhors bror","malkhors historia"}},{q="Vart fördes Malkhors kvarlevor?",a="Vilebranch matade sina slemvarelser och vargar med hans kvarlevor. Hans skalle ligger på Jintha'Alors översta plan, och hans ben ligger i en slampöl nära det översta planet.",al={"var finns benen","var finns malkhors skalle","kvarlevor i jintha'alor"}},{q="Vem ska förbereda Malkhor för begravningen?",a="Markhor säger att han ska ta kvarlevorna till Yayo'jin, som ska förbereda dem för en riktig begravning.",al={"begravning för malkhor","vem är yayo'jin","yayo'jin"}},{q="Varför behöver Markhor få tillbaka benen?",a="Markhor kan inte längre rädda sin brors liv, men säger att hans brors själ fortfarande kan räddas. Därför vill han att kvarlevorna återfinns.",al={"varför återfinna kvarlevor","rädda malkhors själ","rädda hans själ"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="Dark Vessels",s="Primal Torntusk i Revantusk Village säger att Vilebranch slåss med övernaturlig vildsinthet, ett verk av Vile Priestess Hexx mörka magivävnader. Över hela Jintha'alor finns mörka kärl med besmittat blod, som utstrålar en mörk magi från den ansiktslösa blodguden. Torntusk ber dig stjäla dem och föra tillbaka dem, så att besmittelsen kan avlägsnas.",h="Primal Torntusk i Revantusk Village säger att Vilebranch slåss med övernaturlig vildsinthet, ett verk av Vile...",kw={"blodgud","dark vessels","jintha'alor","primal torntusk","revantusk village","besmittat blod","vile priestess hexx","vilebranch"},sec={{t="Vilebranchs vrede",b="Var du än går i Jintha'alor hittar du kärl med besmittat blod. De utstrålar den ansiktslösa blodgudens mörka kraft, som stärker Vilebranch och driver dem till vansinne. Torntusk tror att om kärlen förs bort och besmittelsen avlägsnas, så släpper blodguden sitt grepp om dem."},{t="När kärlen återvänt",b="När du har kärlen i din hand lyfts den mörka energi som tvingar Vilebranch, men bara för stunden. Torntusk påminner dig om att alltid vara vaksam mot ondskan, eftersom en fallen prästinna snart ersätts av en annan."}},faq={{q="Vem ger uppdraget Dark Vessels?",a="Primal Torntusk ger det i Revantusk Village i The Hinterlands.",al={"vem ger dark vessels","uppdragsgivare för dark vessels"}},{q="Var finns de besmittade kärlen?",a="Mörka kärl med besmittat blod finns över hela Jintha'alor i The Hinterlands.",al={"var finns dark vessels","plats för kärl med besmittat blod","hitta besmittat blod"}},{q="Varför är Vilebranch-trollen så vildsinta?",a="Primal Torntusk ger Vile Priestess Hexx mörka magivävnader skulden. Kärlen med besmittat blod bär också på den ansiktslösa blodgudens kraft, som stärker Vilebranch och driver dem till vansinne.",al={"varför är vilebranch galna","vilebranchs vansinne","vilebranchs vildsinthet"}},{q="Vad planerar Primal Torntusk att göra med kärlen?",a="Torntusk planerar att avlägsna besmittelsen från dem för att blodguden ska släppa sitt grepp om Vilebranch.",al={"varför samla in kärlen","vad händer med blodkärlen"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
P.entries["quest:786"] = {n="Thwarting Kolkar Aggression",s="Lar Prowltusk har hittat invasionsplaner i Kolkar Crag, väster om Sen'jin Village. Kolkar-centaurerna planerar att anfalla Durotars bosättningar och Orgrimmar.",h="Lar Prowltusk har hittat invasionsplaner i Kolkar Crag, väster om Sen'jin Village.",kw={"durotar","kolkar","kolkar crag","lar prowltusk","orgrimmar","sen'jin village","thwarting kolkar aggression","valley of trials"},ang={["faction:Horde"]="När du stoppar Kolkars offensiv slipper den unga Horden en utmattande strid på flera fronter vid tröskeln till sitt nya hem.",["race:Orc"]="Som orch vet du att Valley of Trials är platsen där unga orcher genomgår sina vuxenritualer. Centaurernas aggression där är en förolämpning mot orchernas krigarkultur.",["race:Troll"]="Som Darkspear-troll vet du att Sen'jin Village inte får falla för ett centauranfall efter att ditt folk förlorat sitt urgamla öhem."},sec={{t="En invasion hotar",b="Lar Prowltusk, en trollspårare som spanar i västra Durotar, smög sig in i Kolkar Crag i skydd av natten. Där upptäckte han att Kolkar-centaurerna planerade mer än enstaka räder längs kusten. Tre centaurledare hade delat upp invasionsplanerna mellan sig, med anfall riktade mot Valley of Trials, Sen'jin Village och Orgrimmars portar."},{t="Anfall i ravinerna",b="Du skickas in i Kolkar Crag för att förstöra de tre anfallsrullarna innan centaurerna hinner slå till. Deras läger ligger i de torra kanjonerna, och varje rulle tillhör en annan ledare. Lar Prowltusk tror att Horden skulle besegra en fullskalig invasion, men genom att bränna planerna kan Durotars försvarare slippa kostsamma strider medan deras unga nation finner fotfäste."}},faq={{q="Vem erbjuder uppdraget Thwarting Kolkar Aggression?",a="Lar Prowltusk, en Darkspear-trollspejare, erbjuder uppdraget strax utanför Sen'jin Village, längs Durotars södra klippor.",al={"uppdragsgivare","vem ger uppdraget","var finns lar prowltusk"}},{q="Vilka mål planerar Kolkar-centaurerna att anfalla?",a="Kolkar-planerna pekar ut Valley of Trials, Sen'jin Village och Orgrimmar som mål.",al={"centaurernas mål","vad är anfallsplanerna","tre mål"}},{q="Var ligger Kolkar Crag?",a="Kolkar Crag ligger väster om Sen'jin Village, bortom de klippiga åsarna i södra Durotar.",al={"var ligger kolkar crag","var finns ravinen","centaurby durotar"}},{q="Var i ravinen finns anfallsplanerna?",a="Tre olika Kolkar-ledare har invasionsrullarna i läger utspridda över klippområdet.",al={"var finns anfallsplanerna","var finns rullarna","centaurledare"}},{q="Varför vill Kolkar invadera Durotar?",a="Kolkar är en aggressiv centaurklan som hör hemma i Kalimdors torra trakter. De ser de anländande orcherna och Darkspear Trolls som inkräktare på sitt territorium och sina jaktmarker.",al={"varför anfaller centaurerna","centaurernas motiv","kolkar-lore"}},{q="Vad händer när planerna förstörs?",a="Genom att förstöra planerna stör du Kolkars samordnade anfall och skyddar Durotars bosättningar från en plötslig belägring.",al={"följder av uppdraget","stoppas centaurernas anfall"}}},fx={a839716d={q="Varför vill Lar Prowltusk att anfallsplanerna förstörs?",a="Lar Prowltusk spanade vid Kolkar Crag och upptäckte att kentaurerna förbereder en invasion från tre håll, riktad mot Sen'jin Village, Valley of Trials och själva Orgrimmar. Horden skulle till sist krossa ett sådant anfall, men Prowltusk vill bränna deras planer och stoppa invasionen innan den börjar. På så sätt slipper Durotars försvarare onödigt blodspillan och oroligheter.",al={"varför förstöra anfallsplanerna","lar prowltusks motiv","varför hejda kolkars aggression"}},["4d134dbe"]={q="Vilka är Kolkar-kentaurerna vid Kolkar Crag?",a="Kolkar är en brutal kentaurklan som har etablerat ett fäste bland klipporna längs Durotars västra ås. De är stridslystna och revirhävdande, och hyser ett djupt hat mot de nyanlända orcherna och Darkspear Trolls. De gör regelbundet räder från sitt läger och smider planer för att driva bort Horden från området.",al={"vilka är kolkar här","kentaurerna vid kolkar crag","varför finns kolkar i durotar"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="Wanted: Vile Priestess Hexx and Her Minions",s="Primal Torntusk har beordrat att Vile Priestess Hexx och hennes undersåtar ska ställas inför rätta, och ett storslaget pris väntar den som dödar prästinnan och hennes elitvakt Aman'zasi. Du hittar dem högst upp på Jintha'alor i The Hinterlands.",h="Primal Torntusk har beordrat att Vile Priestess Hexx och hennes undersåtar ska ställas inför rätta, och ett...",kw={"aman'zasi","hexx","hinterlands","jintha'alor","primal torntusk","revantusk village","vile priestess hexx","vilebranch"},sec={{t="Ett angrepp mot Jintha'alor",b="Primal Torntusk har beordrat att Vile Priestess Hexx och hennes undersåtar ska ställas inför rätta. Målen är prästinnan själv och Aman'zasi-vakterna, hennes elitstyrka. De finns högst upp på Jintha'alor i The Hinterlands. När de har dödats rapporterar du tillbaka till Torntusk i Revantusk Village."}},faq={{q="Vem utfäste belöningen för Vile Priestess Hexx?",a="Uppmaningen till vapen utfärdades på order av Primal Torntusk, och ett storslaget pris utlovas till den som dödar prästinnan och hennes vakt.",al={"vem vill att hexx ska dö","vem utfärdade belöningen","uppdragsgivare för priestess hexx"}},{q="Var hittar man Vile Priestess Hexx och hennes vakter?",a="De finns högst upp på Jintha'alor i The Hinterlands.",al={"var finns hexx","vile priestess hexx plats","aman'zasi-vakternas plats"}},{q="Vem måste dödas för att uppdraget ska slutföras?",a="Prästinnan Hexx själv, tillsammans med hennes elitvakt Aman'zasi från Vilebranch.",al={"hexx-belöningens mål","vem ska dödas för hexx"}},{q="Var lämnar man in belöningen?",a="Rapportera till Primal Torntusk i Revantusk Village när prästinnan och hennes vakt har dödats.",al={"var lämnar man in hexx-belöningen","primal torntusks plats"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="Job Opening: Guard Captain of Revantusk Village",s="Gardekapten Malkhor har försvunnit, och Revantusks garde behöver en ny kapten. Den som vill ha posten måste utrota Vilebranch Berserkers, Shadow Hunters, Blood Drinkers och Soul Eaters och sedan lämna in en ansökan till Primal Torntusk i The Hinterlands.",h="Gardekapten Malkhor har försvunnit, och Revantusks garde behöver en ny kapten.",kw={"berserker","bloddrickare","gardekapten","malkhor","revantusk","skuggjägare","själsätare","torntusk","vilebranch"},sec={{t="En ledig post",b="En vapenbroderlig uppmaning tillkännager att gardekapten Malkhor har försvunnit, så Revantusks garde återigen står utan kapten. Den som vill leda det uppmanas att utföra arbetet som anges i meddelandet och sedan lämna in en ansökan till Primal Torntusk."},{t="Bevisa ditt värde",b="Den som söker posten ska utrota fyra typer av Vilebranch: Berserkers, Shadow Hunters, Blood Drinkers och Soul Eaters. När det är gjort återvänder du till Primal Torntusk i Revantusk Village."}},faq={{q="Varför är posten som gardekapten ledig?",a="Gardekapten Malkhor har försvunnit, och meddelandet säger att Revantusks kaptenspost åter är ledig.",al={"varför är gardekaptensposten ledig","vad hände med malkhor","vem var föregående kapten"}},{q="Vem tar emot ansökan när fienderna har dödats?",a="Ansökningar lämnas till Primal Torntusk i Revantusk Village.",al={"vem lämnar jag in det till","var lämnar jag in ansökan","vem bedömer de sökande"}},{q="Vilka fiender måste besegras för att kvalificera sig?",a="Den som söker posten måste utrota Vilebranch Berserkers, Shadow Hunters, Blood Drinkers och Soul Eaters.",al={"vilka vilebranch ska dödas","mål för den lediga tjänsten","vem ska jag döda för att bli gardekapten"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:78676"] = {n="The Eye of Bhossca",s="C skickar dig efter Eye of Bhossca, som sägs finnas i Scarlet Monastery. Artefakten ska lämnas tillbaka på en dold avlämningsplats nära Pyrewood Village.",h="C skickar dig efter Eye of Bhossca, som sägs finnas i Scarlet Monastery.",kw={"artefakt","bhossca","c","dold avlämningsplats","förklädnad","eye of bhossca","pyrewood village","scarlet monastery"},sec={{t="C:s begäran",b="En lapp i kistan innehåller en ny begäran från C, nära Pyrewood Village. Eye of Bhossca sägs finnas någonstans i Scarlet Monastery, och C vill att du hämtar den. Precis som vid Shadowfang Keep ska du gå in ensam. En förklädnad som finns på klostrets område kan göra det lättare att ta sig fram."}},faq={{q="Vem ber om Eye?",a="C ber dig hämta Eye of Bhossca och lämna den på en dold avlämningsplats nära Pyrewood Village.",al={"vem vill ha den","vem är c","c:s begäran om eye"}},{q="Var finns Eye of Bhossca?",a="Enligt C:s källor finns Eye of Bhossca någonstans i Scarlet Monastery.",al={"var finns eye","eye:s plats","hitta bhossca"}},{q="Varför vill C ha Eye?",a="C kallar Eye of Bhossca en artefakt och säger att den är det senaste föremålet någon åtrår.",al={"varför eye","vad ska c ha den till","varför hämta den"}},{q="Vart ska jag ta Eye?",a="Du ska lämna tillbaka Eye på C:s dolda avlämningsplats nära Pyrewood Village.",al={"vart ska den lämnas","plats för dold avlämning","var finns kistan"}},{q="Måste jag gå ensam?",a="C kräver att du går in i Scarlet Monastery ensam och utför uppdraget på egen hand.",al={"ensam?","kan jag ta med hjälp","eye ensam"}},{q="Skulle en förklädnad hjälpa?",a="C säger att en förklädnad kan göra det lättare att ta sig runt och föreslår att du letar efter en på klostrets område.",al={"förklädnad till eye","behöver jag förklädnad","var finns förklädnaden"}}},fp="18,145,11.282.0,26.92.0,28.76.0,24.82.0,24.65.0,22.79.0,22.105.0"}
P.entries["quest:78699"] = {n="The Eye of Bhossca",s="En lapp till dig väntar i en kista. Avsändaren skriver bara initialen C.",h="En lapp till dig väntar i en kista.",kw={"bhossca","c","kista","eye of bhossca","hålla utkik","lapp"},sec={{t="Lappen",b="En kista innehåller en lapp till dig. Avsändaren säger att hen ska hålla utkik efter dig och skriver sedan bokstaven C."}},faq={{q="Vem lämnade lappen?",a="Lappen är signerad med initialen C; hela namnet anges inte.",al={"vem är c","vem skrev den","c-lappen"}},{q="Vad står det i lappen?",a="Avsändaren säger att hen ska hålla utkik efter dig och skriver initialen C.",al={"vad finns i kistan","eye of bhossca-lappen","vad skrev c"}},{q="Var finns lappen?",a="Lappen ligger i en kista.",al={"var finns lappen","lapp i kista"}}},fp="18,74,8.119.0,18.61.0,23.84.0,18.25.0"}
P.entries["quest:787"] = {n="The New Horde",s="I Valley of Trials kallar veteranen Eitrigg nya rekryter till The Den. Han skickar dig till Gornek för att inleda träningen och berättar varför han återvände till Horde och vad Thrall hoppas att den ska bli.",h="I Valley of Trials kallar veteranen Eitrigg nya rekryter till The Den.",kw={"burning legion","durotar","eitrigg","gornek","new horde","the den","thrall","valley of trials"},ang={["faction:Horde"]="För Horde kännetecknas Thralls styre av ett fullständigt brott med demoniskt slaveri till förmån för heder, överlevnad och förfädernas arv.",["race:Orc"]="Som ork på väg in i Valley of Trials möter du Eitrigg, det levande minnet av ditt folks tragiska förflutna och dess återupprättelse under Thrall.",["race:Troll"]="Som troll från Darkspear tränar du tillsammans med orkerna i Valley of Trials och delar Thralls vision om ömsesidig överlevnad och heder."},sec={{t="En veterans återkomst",b="Eitrigg står i Valley of Trials på hövding Thralls order, redo att bedöma och vägleda Hordes nyaste hopp. Efter Second War övergav han Old Horde, desillusionerad av Burning Legions korrumpering av den. Han levde i stillsam exil tills människor tillfångatog honom. Thrall räddade Eitrigg, och veteranen valde att återvända när han fick höra om den unge hövdingens dröm: en hedervärd Horde med rötter i förfädernas shamanism och helt fri från demoniska herrar."},{t="Rapportera till The Den",b="Innan du beger dig bortom Valley of Trials karga raviner skickar Eitrigg dig till den skuggiga grottan The Den för att tala med Gornek. Gornek brukar inte linda in sina ord om hur råa de nya aspiranterna är. Hans tillsyn ser till att bara de som behärskar disciplin och överlevnad får komma in i Durotars vidsträckta områden."}},faq={{q="Vem är Eitrigg?",a="Eitrigg är en åldrande orkisk veteran som på nära håll bevittnade hur Burning Legion korrumperade Old Horde. Desillusionerad drog han sig undan i stillsam, självvald exil i Lordaeron. Människor tillfångatog honom, och Thrall befriade honom senare. Eitrigg svor trohet till Thralls reformerade Horde och hjälper nu till att övervaka rekrytträningen i Valley of Trials.",al={"vem är eitrigg","eittriggs bakgrund","eitriggs historia"}},{q="Varför talar Eitrigg om ”New Horde”?",a="Den ursprungliga Horde manipulerades och förslavades av demonisk blodtörst under Burning Legions inflytande. Thralls New Horde gjorde sig fri från demonisk kontroll, återupplivade traditionella shamanistiska seder och sökte en hedervärd, självständig framtid för orker och deras allierade i Kalimdor.",al={"vad är new horde","skillnaden mellan old och new horde","new hordes betydelse"}},{q="Var finns Gornek?",a="Gornek är stationerad strax innanför ingången till The Den, i den framträdande grottan som huggits ut ur Valley of Trials norra klippvägg.",al={"var finns gornek","hitta gornek","gorneks plats"}},{q="Vad händer efter att du rapporterat till Gornek?",a="När du rapporterar till Gornek godtar han dig som en av Eitriggs lärlingar och ger dig dina första uppdrag ute i fält. Du hjälper till att försvara dalen och bevisa att du är redo att tjäna Horde.",al={"uppdraget efter the new horde","vad gör gornek","gornek-uppdrag"}},{q="Varför gick Eitrigg i exil?",a="Eitrigg övergav Horde eftersom han avskydde den demoniska korruptionen och den meningslösa slakt som orkestrerades av häxmästare i Burning Legions tjänst under de tidigare krigen.",al={"varför lämnade eitrigg horde","orsaken till eittriggs exil","eittrigg och demonisk fördärvning"}},{q="Varför tränas rekryterna i Valley of Trials?",a="Valley of Trials erbjuder unga orker och nykomlingar bland deras allierade en avskild, karg plats i Durotar där de under veterantränarnas uppsikt får möta farliga bestar och skorpider innan de beger sig ut i den större världen.",al={"varför valley of trials","valley of trials syfte","träning i valley of trials"}}},fx={["42eb0b46"]={q="Varför skickar Eitrigg dig till Gornek?",a="Krigschef Thrall gav Eitrigg i uppdrag att övervaka träningen av alla nya rekryter som kommer till Valley of Trials. Eitrigg hälsar nykomlingarna välkomna och lär dem om en Horde som befriats från demonisk korruption, medan Gornek sköter de praktiska uppgifterna som ska pröva och härda dig. Eitrigg skickar dig till honom så att din prövning och träning kan börja officiellt.",al={"varför träffa gornek","eitriggs motiv","varför rapportera till gornek"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:7881"] = {n="Carnival Boots",s="Arbetare vid Darkmoon Faire söker slitstarka skor från skickliga hantverkare. I utbyte mot förstklassiga stövlar lämnar karnevalsarbetarna över värdefulla mässbiljetter.",h="Arbetare vid Darkmoon Faire söker slitstarka skor från skickliga hantverkare.",kw={"karneval","karnevalstövlar","hantverksskicklighet","darkmoon faire","darkmoon faire-biljett"},sec={{t="Skodon till Darkmoon Faire",b="Samlare och hantverkare tar med slitstarka karnevalstövlar till Darkmoon Faire, där karnevalsarbetare byter värdefulla biljetter mot förstklassigt hantverk. Varje par hjälper det kringresande nöjesfältet att hålla sig på fötter."}},faq={{q="Varför behöver Darkmoon Faire stövlar?",a="Darkmoon Faire tar emot slitstarka, välgjorda skor för att utrusta arbetarna och karnevalsområdet och erbjuder prisbiljetter i utbyte.",al={"karnevalstövlarnas syfte","varför stövlar till darkmoon faire"}},{q="Vad används Darkmoon Faire-biljetter till?",a="Biljetter som tjänas in på karnevalen kan samlas och bytas mot olika priser och kuriositeter från Darkmoon Faire.",al={"vad kan darkmoon faire-biljetter köpas för","syftet med mässbiljetter"}},{q="Vilken sorts stövlar tar karnevalen emot?",a="Karnevalsarbetare granskar stövlarna för att kontrollera hantverkets kvalitet och hållbarhet innan de lämnar över biljetter.",al={"stövelbyte vid darkmoon faire","krav på karnevalstövlar"}}},fp="14,153,22.199.0,39.134.0,41.110.0,44.106.0"}
P.entries["quest:78823"] = {n="Terror of the Desert Skies",s="En grov teckning visar en stor rovfågel som väckte fruktan och vördnad. Hemet Nesingwary i Stranglethorn Vale kanske vet mer om den.",h="En grov teckning visar en stor rovfågel som väckte fruktan och vördnad.",kw={"rovfågel","hemet nesingwary","primitiv teckning","stranglethorn vale","skräcken från öknens himlar"},sec={{t="En skrämmande bild",b="Du får Primitive Drawing tillsammans med en begäran om att ta den till Hemet Nesingwary i Stranglethorn Vale. De breda penseldragen visar en stor rovfågel, och konstnärens fruktan och vördnad är tydliga i bilden. Hemet ombeds bedöma vad den föreställer."}},faq={{q="Vad föreställer teckningen?",a="Primitive Drawing föreställer en stor rovfågel.",al={"fågelteckning","vad finns på bilden"}},{q="Vem kan berätta om fågeln?",a="Hemet Nesingwary i Stranglethorn Vale kanske kan berätta mer om varelsen.",al={"vem vet något om den","fågelspecialist"}},{q="Vart ska jag ta teckningen?",a="Ta Primitive Drawing till Hemet Nesingwary i Stranglethorn Vale.",al={"vart ska teckningen lämnas","hemet teckning"}}},fp="26,133,15.242.0,27.51.0,31.87.0,28.70.0"}
P.entries["quest:78830"] = {n="Terror of the Desert Skies",s="Hemet Nesingwary har hört talas om Gharrik, en väldig fågel som jagar i Badlands. Han lånar dig en bur för levande bete och vill ha en av hennes fjädrar.",h="Hemet Nesingwary har hört talas om Gharrik, en väldig fågel som jagar i Badlands.",kw={"badlands","camp cagg","crimson trophy quill","gharrik","väldig fågel","hemet nesingwary","levande bete"},sec={{t="En ökenjägare",b="En teckning får Hemet Nesingwary att tänka på Gharrik, som han hört talas om under en annan expedition. Den väldiga fågeln sägs härska över Badlands som områdets främsta rovdjur. Du ombeds leta efter henne nordost om Camp Cagg, där hon senast sågs, och använda levande bete för att locka fram henne. Det finns ont om smådjur i Badlands, så Hemet lånar dig en bur så att du kan fånga bete någon annanstans. Han hoppas få en av Gharriks fjädrar."}},faq={{q="Vem är Gharrik?",a="Gharrik är en väldig fågel som sägs vara det främsta rovdjuret i Badlands.",al={"fågeln gharrik","ökenfågel","vem är gharrik"}},{q="Var sågs Gharrik senast?",a="Gharrik sågs senast nordost om Camp Cagg i Badlands.",al={"gharriks plats","var finns gharrik","nordost om camp cagg"}},{q="Varför vill Hemet ha en fjäder?",a="Hemet säger att en fjäder från Gharrik skulle bli ett fint pris och göra dig till lägrets samtalsämne.",al={"gharriks fjäder","fjäder som pris","varför fjäder"}},{q="Var kan du hitta bete?",a="Det finns ont om smådjur i Badlands, så Hemet säger att du får hitta levande bete någon annanstans och lånar dig en bur att fånga det i.",al={"levande bete","bete till gharrik","bur för bete"}},{q="Vem skickade mig efter Gharrik?",a="Hemet Nesingwary ber dig leta efter Gharrik och ta med en av hennes fjädrar tillbaka.",al={"gharriks uppdragsgivare","hemet gharrik","vem vill ha fjädern"}}},fp="26,142,15.407.0,15.68.0,28.64.0,28.90.0,24.119.0,26.75.0"}
P.entries["quest:789"] = {n="Sting of the Scorpid",s="Sting of the Scorpid är ett tidigt prov som Gornek ger Hordens rekryter i The Den i Valley of Trials. Noviserna får i uppdrag att jaga giftiga scorpid-arbetare nordväst om lägret och återvända med tio svansar för att bevisa att de är redo för strid. Uppgiften lär dem att överleva faror på slagfältet och respektera även de minsta motståndarna.",h="Sting of the Scorpid är ett tidigt prov som Gornek ger Hordens rekryter i The Den i Valley of Trials.",kw={"motgift","durotar","gornek","scorpid","scorpid-arbetare","sting of the scorpid","the den","valley of trials","gift"},ang={["class:Warrior"]="Gornek ser jakten på scorpid-djur som en grundläggande lektion i kampvilja. Han påminner krigarna om att beslutsamma slag övervinner hårda skal och att arrogans mot mindre fiender leder till nederlag.",["race:Orc"]="För unga orcher som blir vuxna i Valley of Trials är jakten på giftiga scorpid-djur ett viktigt prov på uthållighet och uppmärksamhet på slagfältet, under Gorneks uppsikt.",["race:Troll"]="Darkspear Trolls som tränar tillsammans med Horden i Valley of Trials måste också bevisa sin skicklighet mot de lokala scorpid-djuren innan de beger sig längre in i Durotar."},sec={{t="Stingerprovet",b="I Valley of Trials solstekta kanjon prövar Gornek Hordens novisrekryter genom att skicka dem mot den lokala faunan. De giftiga scorpid-djur som strövar omkring på den torra marken nordväst om The Den har kuvat både härdade krigare och klumpiga nykomlingar. För att bevisa sin stridsduglighet måste de unga hjältarna bege sig bland klipporna, döda scorpid-arbetare och återvända med tio av deras avskurna svansar som bevis på sin skicklighet."},{t="Gift och vaksamhet",b="De giftiga rovdjuren är dödliga, men deras gift ger också räddning åt skadade noviser. I The Den förvaras lager av motgift som bryggs direkt av utvunnet scorpid-gift och används för att behandla fallna noviser. Gornek betonar också en grundläggande taktisk sanning: i stridens kaos är arrogans dödlig, och även den minsta fiende har tillräckligt med dödligt gift för att fälla en mäktig krigare."}},faq={{q="Vem ger uppdraget Sting of the Scorpid?",a="Gornek, stridsmästaren som ansvarar för novisernas träning i The Den i Valley of Trials, ger unga krigare och äventyrare det här provet.",al={"vem ger sting of the scorpid","uppdragsgivare för scorpid","gornek-uppdrag"}},{q="Var finns scorpid-djuren?",a="Scorpid-arbetare finns i stort antal direkt nordväst om The Den i Valley of Trials, där de strövar omkring i den torra, röda kanjonen.",al={"var hittar man scorpid-djur","scorpid-plats","scorpid-djur i valley of trials"}},{q="Vad kräver Gornek av jakten?",a="Gornek kräver tio Scorpid Worker Tails som konkret bevis på att rekryten har mött de giftiga bestarna och segrat i strid.",al={"vad släpper scorpid-djur","föremål från scorpid-uppdrag","scorpid-svansar"}},{q="Hur tillverkas motgiftet mot scorpid-gift?",a="Motgiftet mot scorpid-stick bryggs direkt av gift som utvinns ur varelsernas egna gaddar. The Den har gott om det i lager för noviser som underskattar sitt byte.",al={"botemedel mot scorpid-gift","motgiftets bakgrund","hur görs scorpid-motgift"}},{q="Vilken lärdom vill Gornek att rekryterna ska få?",a="Gornek använder jakten för att lära noviskrigare att varje motståndare, stor som liten, kan vara dödlig. Övermod i strid mot varelser som verkar obetydliga kan snabbt visa sig vara ödesdigert.",al={"gorneks lärdom","varför jaga scorpid-djur","syftet med scorpid-provet"}},{q="Erbjuder Gornek mer träning efter jakten?",a="När du lämnar över svansarna förklarar Gornek att han inte har mer att lära dig i The Den och skickar dig vidare ut i Durotar för att fortsätta tjäna Horden.",al={"vad händer efter sting of the scorpid","gorneks nästa uppdrag","lär gornek ut mer"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:7890"] = {n="Heavy Grinding Stone",s="En marknadsbiträde ber dig ta med Heavy Grinding Stones. För leveransen får du biljetter till marknaden.",h="En marknadsbiträde ber dig ta med Heavy Grinding Stones.",kw={"marknad","slipstenar","heavy grinding stone","sötsaker","biljetter"},sec={{t="På marknaden",b="Marknadsbiträdet tackar dig och säger att stenarna redan får musklerna att växa. Som tack får du biljetter och en varning om att inte äta för mycket sötsaker. Biträdet vill att du håller dig stark och redo att slåss."}},faq={{q="Vad vill biträdet ha?",a="Biträdet vill ha Heavy Grinding Stones.",al={"vad är heavy grinding stone","stenar till marknaden"}},{q="Vad får jag för att ta med stenarna?",a="Biträdet ger dig biljetter till marknaden.",al={"stenbiljetter","biljetter till marknaden"}},{q="Varför nämner biträdet sötsaker?",a="Biträdet varnar dig för att äta för mycket sötsaker och säger att du behöver hålla dig i stridsform.",al={"för mycket sötsaker","sötsaker på marknaden"}}},fp="20,101,12.221.0,29.42.0,38.46.0,38.95.0"}
P.entries["quest:79"] = {n="The Legend of Stalvan",s="Det här uppdraget är ögonblicket då ryktena om Stalvan Mistmantle blir till obestridliga bevis för ett brutalt brott. Tavernkeep Smitts lämnar över sedan länge gömda, leriga dagbokssidor och hänvisar utredaren direkt till Night Watch Commander Althea Ebonlocke.",h="Det här uppdraget är ögonblicket då ryktena om Stalvan Mistmantle blir till obestridliga bevis för ett...",kw={"darkshire","duskwood","ebonlocke","utredning","mistmantle","lerig dagbok","night watch","smitts","stalvan"},ang={["class:Paladin"]="Att dra fram sedan länge begravda mord i ljuset fullgör en paladins kall och kräver att de oskyldiga liv som våldsamt släckts i Duskwoods skuggor får rättvisa.",["class:Rogue"]="Att pussla ihop handskriftsprover från värdshus och dammiga kistor speglar det tålmodiga detektivarbete som ofta krävs för att spåra svårfångade villebråd.",["faction:Alliance"]="Utredningen visar hur de södra områdena måste förlita sig på kringvandrande hjältar från Alliance för att skipa rättvisa när Stormwinds officiella stöd helt uteblir."},sec={{t="Ett genombrott i Darkshire",b="I åratal förblev en besökande adelsfamiljs hemska öde en olöst tragedi i Duskwood. Tavernkeep Smitts och Marshal Haggard, då ledare för Stormwind Guard, undersökte först massakern och hittade några sönderrivna, leriga dagbokssidor. Utan handskriftsprover eller andra dokument som styrkte uppgifterna förblev anteckningarna ett kallt spår, oförmögna att officiellt knyta brottet till den enstöring som sades hålla till i vildmarken. Bevisen som samlats in i Elwynn, Westfall och Duskwood kopplar till slut handstilen till Stalvan Mistmantle och gör byskvallret till ett solklart mordfall."},{t="Lämna över till vakten",b="Darkshire är ständigt belägrat av odöda, vildsinta bestar och värre fasor som stryker omkring i skogens dunkel. Commander Althea Ebonlocke har föga tålamod med skrönor eller obestyrkta misstankar när hennes stads överlevnad hänger på en skör tråd. Genom att överlämna de leriga sidorna överbryggas klyftan mellan en avlägsen historia och omedelbar militär rättvisa. Med konkreta bevis för en massaker på Duskwoods mark tvingas Night Watch till slut inse att Stalvan Mistmantle inte bara är en excentrisk eremit eller en spökhistoria, utan en farlig rymling som måste ställas till svars."}},faq={{q="Vilka bevis hade Tavernkeep Smitts hela tiden?",a="För flera år sedan slog sig Smitts ihop med Haggard för att undersöka slakten på besökande adelsmän. De hittade sönderrivna, leriga dagbokssidor på platsen, men saknade jämförbara handskriftsprover som kunde bevisa att Stalvan Mistmantle hade skrivit dem. Fram till nu.",al={"smitts dagbokssidor","muddy journal pages","vad hittade smitts"}},{q="Varför rapporterade inte Smitts det här till Commander Ebonlocke tidigare?",a="Utan bevis som kopplade handstilen på de leriga sidorna till den tillbakadragne läraren hade Smitts och Haggard bara indicier. Obestyrkta rykten till Commander Ebonlocke skulle ha avfärdats som ett onödigt slöseri med Night Watchs knappa tid.",al={"varför vänta så länge","varför hålla sidorna hemliga","varför berättade inte smitts för vakten"}},{q="Vem är Commander Althea Ebonlocke?",a="Commander Althea Ebonlocke leder Night Watch, den hårt ansatta stadsmilisen som försvarar Darkshire och patrullerar Duskwoods vägar mot odöda och rovdjur i skogen.",al={"vem är ebonlocke","althea ebonlockes roll","befälhavare i darkshire"}},{q="Vilken massaker ägde rum i Duskwood?",a="En besökande adelsfamilj slaktades i Duskwood för flera år sedan. Rykten pekade på deras före detta lärare, Stalvan Mistmantle, men de lokala utredarna saknade först de avgörande bevis som krävdes för att åtala honom.",al={"vilken massaker","slakten på adelsmännen","vem mördades"}},{q="Var i den övergripande utredningen passar det här steget in?",a="Det här steget markerar övergången från privat utredning till formell rättvisa. Efter att ha gått igenom register, skolhandlingar och familjekistor i tre områden lämnar du över de samlade bevisen till de lokala myndigheterna, så att de kan godkänna åtgärder mot Stalvan.",al={"steg i stalvans uppdragskedja","hur långt in i kedjan är det här","är det här slutet på uppdraget"}},{q="Varför är Night Watch så ovilliga att utreda gamla brott?",a="Darkshire hotas dagligen av omedelbar undergång från kringvandrande vidunder, worgenflockar och spindlar. Commander Ebonlocke måste sätta varje tillgänglig vaktman på att försvara staden, så gamla fall kräver obestridliga bevis innan hon kan avvara folk.",al={"varför är ebonlocke upptagen","darkshires försvarsprioritering","night watchs prioriteringar"}}},fx={["3928db26"]={q="Varför vill Tavernkeep Smitts att du talar med Commander Ebonlocke?",a="Smitts har i tysthet följt legenden om Stalvan i åratal, ända sedan besökande adelsmän slaktades utanför Darkshire. När han och Haggard undersökte den hemska platsen då, hittade de leriga dagbokssidor men saknade handskriftsprov som kunde knyta dem till eremiten i skogen. Nu när din utredning har grävt fram prover som bevisar att Stalvan skrivit dem, har Smitts äntligen obestridliga bevis för mördarens identitet. Han vill att du genast lägger fram sanningen så att stadens försvarare officiellt kan konfrontera mördaren.",al={"varför skickar smitts dig till ebonlocke","tavernkeep smitts motiv","varför berätta för ebonlocke nu"}},["225fd2ad"]={q="Varför skickar Smitts dig i stället för att rapportera det själv?",a="Smitts sköter baren på Scarlet Raven Tavern och hade bara några lösa fragment från den ursprungliga slakten. Det var du som följde spåren genom Elwynn, Westfall och Duskwood och hittade breven och dagböckerna som knyter handstilen till Stalvan. Eftersom du fann de avgörande ledtrådarna som fogar samman hela pusslet, behöver Commander Ebonlocke höra hela berättelsen direkt från utredaren som bevisade det.",al={"varför pratar smitts inte med ebonlocke","varför ska jag rapportera om stalvan","varför rapportera till ebonlocke"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:7900"] = {n="Torn Bear Pelts",s="Du lämnar sönderrivna björnfällar till någon som tänker låta sy dem till mjukisdjur. Biljetter erbjuds som betalning.",h="Du lämnar sönderrivna björnfällar till någon som tänker låta sy dem till mjukisdjur.",kw={"björnfällar","färg","mjukisdjur","stoppning","biljetter","sönderrivna björnfällar"},sec={{t="En ny användning",b="Mottagaren tänker låta sy björnfällarna till mjukisdjur, med stoppning och färg. Som betalning erbjuder hen dig biljetter."}},faq={{q="Vad ska björnfällarna användas till?",a="De ska sys till mjukisdjur med stoppning och färg.",al={"syfte med sönderrivna björnfällar","vad blir det av fällarna"}},{q="Vad får jag för fällarna?",a="Mottagaren erbjuder dig biljetter som betalning.",al={"betalning för fällar","biljetter för fällar"}},{q="Vem ska sy leksakerna?",a="Mottagaren säger att någon ska sy fällarna till mjukisdjur.",al={"vem tillverkar mjukisdjur","vem syr björnarna"}}},fp="15,113,9.124.0,28.69.0,28.44.0,22.62.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="'... and that note you found' börjar vid de svalnande glöden från en nyligen övergiven lägerplats, omgiven av utspridda förnödenheter. Bland askan ligger ett förkolnat, blåsigt pergament med en gåta om att finna ett ”tvillingland”. När inga andra vägvisare finns kvar är den förkolnade biten den enda ledtråden till vad som lämnats kvar.",h="'...",kw={"and that note you found","blåsig lapp","förkolnad lapp","glöd","nyligen slocknad eld","utspridda förnödenheter","tvillingland"},sec={{t="Glöd i vildmarken",b="Bredvid det svaga skenet från en nyligen slocknad lägereld ligger utspridda förnödenheter och en skadad, blåsbildad pappersbit. Den som stannade här gav sig av nyligen och lämnade bara svalnande glöd och ett pergamentfragment som nätt och jämnt undkom lågorna. Scenen tyder på brådska eller ett plötsligt avbrott, med förnödenheter utsatta för väder och vind."},{t="En gåtfull gåta",b="På den överlevande pergamentbiten står en enda gåtfull uppmaning: ”Allt som brinner går inte förlorat. Finn tvillinglandet, finn platsen.” Ingen underskrift, inga koordinater eller ytterligare sammanhang överlevde elden. Den förkolnade biten är den enda ledtråden för den som råkar hitta den."}},faq={{q="Vad står det på lappen som hittades vid lägerplatsen?",a="Den förkolnade, blåsiga lappen innehåller ett kryptiskt meddelande: ”Allt som brinner går inte förlorat. Finn tvillinglandet, finn platsen.” Den är den enda ledtråden som lämnats kvar vid den övergivna lägerplatsen.",al={"vad står det på lappen","lappens text","blåsig lapp"}},{q="Vem lämnade lappen?",a="Det är fortfarande okänt vem som skrev den. Den hittades bland utspridda förnödenheter intill glöden från en nyligen slocknad lägereld, vilket tyder på att den som skrev eller bar lappen nyligen gav sig av eller tvingades lämna platsen i brådska.",al={"varifrån kom lappen","vem skrev lappen","vem gjorde upp elden"}},{q="Vad syftar ”tvillinglandet” på?",a="Lappen talar kryptiskt om ett ”tvillingland” och uppmanar läsaren att söka efter en motsvarande eller spegelvänd plats. Det förkolnade fragmentet ger ingen ytterligare förklaring, så betydelsen förblir en olöst gåta för resenärer.",al={"vad är tvillingland","ledtråd om tvillingland"}},{q="Hur följer du ledtrådarna på lappen?",a="Eftersom ingen tydlig destination är markerad på en karta är de förkolnade resterna av lappen din enda vägledning. För att följa gåtan måste du söka efter ett land eller en plats som motsvarar lappens kryptiska beskrivning.",al={"vad ska man göra med lappen","vart leder uppdraget"}},{q="Varför övergavs lägerplatsen?",a="Platsen visar tecken på ett plötsligt uppbrott eller en störning. Utspridda förnödenheter har lämnats kvar intill den falnande glöden. Förutom den blåsiga pappersbiten finns inga andra identifierbara tillhörigheter eller spår kvar.",al={"vem övergav förnödenheterna","utspridda förnödenheter vid lägerplats"}},{q="Finns det några andra ledtrådar vid elden?",a="Inga fler skrifter eller markörer finns kvar vid lägerelden. Lågorna förstörde nästan allt och lämnade bara pappersfragmentet med blåsor som bevis på att någon vilade här.",al={"avslöjar elden något mer","ledtrådar vid lägerplatsen"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="I Westfall finns en förkolnad lapp kvar intill en döende lägereld. Det korta meddelandet pekar mot en plats som kallas tvillinglandet.",h="I Westfall finns en förkolnad lapp kvar intill en döende lägereld.",kw={"bränd lapp","lägereld","förkolnad lapp","glöd","lapp","tvillingland","westfall"},ang={["class:Rogue"]="Som skurk vet du hur man tyder gåtfulla ledtrådar som lämnats på gömda lägerplatser. Sådant kommer naturligt för den som lever på viskningar, hemligheter och dolda meddelanden.",["faction:Alliance"]="Som ävent yrare i Alliansen som försöker återställa ordningen i Westfall ställs du inför ännu ett mysterium vid kungarikets gräns: ett oidentifierat läger och en gåtfull chiffertext."},sec={{t="En döende eld",b="På Westfalls övergivna fält och vindpinade slätter hittar resande läger som lämnats av lösdrivare, laglösa och desperata vandrare. Det här lilla lägret kan ha övergivits i hast eller i hemlighet. Förråden ligger kvar och glöden lyser fortfarande. En förkolnad papperslapp ligger bland det utspridda skräpet."},{t="Det gåtfulla meddelandet",b="Den brända lappen bär två korta meningar: ”Allt som brinner är inte förlorat. Hitta tvillinglandet, hitta platsen.” Orden pekar bort från Westfall, men ger ingen tydlig riktning. Vilken plats delar namn, geografi eller öde med detta land?"}},faq={{q="Vad står det på lappen?",a="Den brända lappen lyder: ”Allt som brinner är inte förlorat. Hitta tvillinglandet, hitta platsen.” Det är den enda ledtråden på den övergivna lägerplatsen.",al={"lappens text","vad står skrivet på lappen","ord på den brända lappen"}},{q="Var hittades lappen?",a="Lappen ligger bland resterna av en eld och utspridda förråd i Westfalls vildmark.",al={"lappens plats","var är lappen","lägereldens plats"}},{q="Vem lämnade lägerelden?",a="Ingen vet vem som lämnade lägret. Den som gjorde upp elden gav sig av nyligen och lämnade utspridda förnödenheter och det förkolnade meddelandet bland glöden.",al={"vem lämnade lappen","lägereldens ägare","lappens upphovsperson"}},{q="Vad syftar ”tvillinglandet” på?",a="”Tvillinglandet” syftar på en annan region med en koppling till landet där lappen hittades, men det brända meddelandet ger ingen närmare förklaring.",al={"tvillinglandets betydelse","vad är tvillinglandet","var ligger tvillinglandet"}},{q="Varför brändes lappen?",a="Lappen är blåsbränd och förkolnad av glöden. Någon kan ha försökt förstöra den i hast eller lämnat den slarvigt när lågorna falnade.",al={"varför brändes den","försökte någon bränna lappen","förkolnad lapp"}},{q="Har detta koppling till Defias Brotherhood?",a="Westfall är översvämmat av Defias Brotherhood och utblottade ockupanter, men det gåtfulla meddelandet antyder något mer svårbegripligt än vanlig kommunikation mellan banditer.",al={"defias-lapp","är det defias","broderskapets lägereld"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7901"] = {n="Soft Bushy Tails",s="På Darkmoon Faire bidrar en begäran om yviga svansar med priser till mässans besökare. Mässan hoppas att nöjda besökare tar med sig andra.",h="På Darkmoon Faire bidrar en begäran om yviga svansar med priser till mässans besökare.",kw={"darkmoon faire","priser","soft bushy tails","svansar","biljetter","besökare"},sec={{t="Priser på mässan",b="Nöjda besökare betyder mer för Darkmoon Faire. Svansarna du tar med blir priser till dem som kommer, och nöjda besökare kanske berättar för sina vänner att de också ska besöka mässan. Mässan ger dig biljetter och välkomnar dig att trivas där."}},faq={{q="Vad ska de yviga svansarna användas till?",a="Darkmoon Faire ska använda dem som priser till sina besökare.",al={"varför svansar","användning av yviga svansar","svansar till mässan"}},{q="Varför vill mässan ha nöjda besökare?",a="Nöjda besökare kanske berättar för sina vänner om mässan och lockar dit fler besökare.",al={"varför nöjda besökare","besökare på mässan","fler besökare på mässan"}},{q="Vad ger mässan dig?",a="Mässan ger dig biljetter.",al={"biljetter till mässan","vad får jag","biljetter för svansar"}}},fp="16,143,12.228.0,29.60.0,39.78.0,29.28.0"}
P.entries["quest:7905"] = {n="The Darkmoon Faire",s="Du bär med dig en Free Ticket Voucher till Gelvas Grimgate inne på nöjesfältet Darkmoon Faire. Kupongen är avsedd för honom.",h="Du bär med dig en Free Ticket Voucher till Gelvas Grimgate inne på nöjesfältet Darkmoon Faire.",kw={"nöjesfält","darkmoon faire","free ticket voucher","gelvas grimgate","kupong"},sec={{t="En kupong till Gelvas",b="Gelvas Grimgate är inne på nöjesfältet Darkmoon Faire, och du bär med dig en Free Ticket Voucher till honom. Kupongen väntar på att överlämnas."}},faq={{q="Vem är kupongen till?",a="Free Ticket Voucher är till Gelvas Grimgate, som är inne på nöjesfältet Darkmoon Faire.",al={"kupong till vem","gelvas kupong"}},{q="Var är Gelvas Grimgate?",a="Gelvas Grimgate är inne på nöjesfältet Darkmoon Faire.",al={"var är gelvas","gelvas plats"}},{q="Vad ska jag ta med till Gelvas?",a="Ta med Free Ticket Voucher till Gelvas Grimgate.",al={"vilken kupong","biljettkupong"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="Det här uppdraget går ut på att återfinna ärkemagiker Antonidas fullständiga memoarer, efterlämnade av den vördnade ledaren för Kirin Tor. Den sällsynta boken fanns ursprungligen i Ironforges storslagna arkiv och ger oersättliga insikter i Dalarans historia och den höga arkanistiska läran.",h="Det här uppdraget går ut på att återfinna ärkemagiker Antonidas fullständiga memoarer, efterlämnade av den...",kw={"antonidas","arkanisk","ärkemagiker antonidas","självbiografi","dalaran","hall of explorers","ironforge","kirin tor","bibliotek","magiker"},ang={["class:Mage"]="Ärkemagiker Antonidas var en av Kirin Tors största ledare och ett föredöme inom arkanisk lärdom. Att studera hans liv och personliga skrifter ger viktiga insikter för alla som utövar den arkaniska konsten.",["faction:Alliance"]="Antonidas var en av grundpelarna i Alliansen av Lordaeron mot orchernas hord och Scourge, vilket gör hans personliga memoarer till en skattad historisk källa i hela Alliansen.",["race:Dwarf"]="Boken kommer från det stora biblioteket i Hall of Explorers i Ironforge, men forskarna som tar emot den verkar inte bekymra sig om att beröva dvärgarnas arkivarier en så sällsynt bok.",["race:Human"]="Antonidas var en vördad mänsklig ärkemagiker som ledde Kirin Tor och Dalaran genom andra och tredje kriget, vilket gör hans ocensurerade självbiografi till en värdefull del av människornas historia."},sec={{t="Den store magikerns ord",b="Ärkemagiker Antonidas var ett av Azeroths skarpaste sinnen och tjänade i årtionden som vördad ledare för Kirin Tor och härskare över Dalaran. Hans ocensurerade självbiografi skildrar hans väg genom leden i Violet Citadel, hans bemästrande av det arkana och hans ledarskap under de omvälvande andra och tredje krigen. För forskare och magiutövare ger Antonidas egna minnen en oöverträffad inblick i Dalarans inre angelägenheter och den arkaniska konsten."},{t="Från Ironforges stora bibliotek",b="Innan det fick sitt nya hem förvarades detta sällsynta manuskript i Ironforges storslagna bibliotek, tillsammans med uråldriga titanförmål och dvärgahistorier i Hall of Explorers. Dvärgarna har stora samlingar av texter som hämtats från ruiner och främmande kungariken runtom Azeroth, vilket gör deras arkiv till en skattkammare av sällsynt litteratur. Arkaniska forskare på andra håll vill dock gärna lägga beslag på sådana verk till sina egna samlingar, övertygade om att de upptagna dvärgarna i arkivet aldrig skulle märka att en enda volym saknas."}},faq={{q="Vem var ärkemagiker Antonidas?",a="Ärkemagiker Antonidas var sedan länge ledare för Kirin Tor och härskare över den magiska stadsstaten Dalaran. Som legendarisk mästare i det arkana var han en viktig rådgivare åt Alliansen av Lordaeron under andra kriget och varnade kung Terenas för pesten innan han föll i Dalarans försvar under tredje kriget.",al={"vem var antonidas","ärkemagiker antonidas bakgrund","antonidas historia"}},{q="Vad är den ocensurerade självbiografin?",a="Det är den fullständiga, ocensurerade självbiografi som ärkemagiker Antonidas själv skrev och där han berättar om sitt liv, sin lärdom och sitt ledarskap i Dalaran. Med tanke på hans ställning som Kirin Tors överhuvud är hans personliga skrifter en ovärderlig historisk och magisk källa.",al={"vad är det här för bok","ocensurerad självbiografi bok","antonidas bok"}},{q="Var kommer den här boken ifrån?",a="Boken hämtades från biblioteket i Ironforge, som ligger i dvärgarnas fäste Hall of Explorers. Dvärgiska upptäcktsresande och arkivarier samlar ofta historiska och magiska texter från de östra kontinenterna.",al={"var kommer boken ifrån","kommer den från ironforge","bok från biblioteket i ironforge"}},{q="Varför är folk ute efter den här boken?",a="Forskare och bibliotekarier letar ständigt efter mäktiga eller historiska magiska texter för att utöka sina arkiv och bevara arkanisk kunskap, särskilt verk skrivna av legendariska magiker som annars kan gå förlorade eller gömmas undan i utländska samlingar.",al={"varför samla på magiska böcker","vem vill ha antonidas bok","varför vill biblioteket ha den"}},{q="Vad hände med ärkemagiker Antonidas?",a="Ärkemagiker Antonidas dog under tredje kriget när den fallne prinsen Arthas Menethil och Scourge invaderade Dalaran. Antonidas reste en mäktig magisk barriär för att försvara staden och dess hemligheter, men Arthas bröt igenom försvaret och dödade honom för att lägga beslag på Medivhs bok.",al={"dog antonidas","hur dog antonidas","vad hände med antonidas"}},{q="Kommer Ironforges bibliotek att märka att boken är borta?",a="Mottagaren avfärdar lättsamt all oro för att dvärgarna ska märka att boken saknas och funderar på att Ironforges väldiga arkiv är så omfattande att en enda saknad bok troligen går helt obemärkt förbi.",al={"kommer ironforge sakna boken","stöld från biblioteket i ironforge"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="Archmage Theocritus' Research Journal är en arkan volym som dokumenterar undersökningarna av Tower of Azoras mästarmagiker. När den lämnas till de lärda i Ironforge Library tillför journalen värdefulla magiska insikter till det stora dvärgarkivet.",h="Archmage Theocritus' Research Journal är en arkan volym som dokumenterar undersökningarna av Tower of Azoras...",kw={"arkan kunskap","archmage theocritus","ironforge","ironforge library","forskningsjournal","theocritus","tower of azora"},ang={["class:Mage"]="De lärda inom arkana studier värdesätter återfunna anteckningar från framstående personer som Archmage Theocritus, vars forskning hjälper till att skydda historiska magiska avhandlingar i Ironforges arkiv.",["faction:Alliance"]="Att säkra sällsynta texter och journaler berikar det storslagna kunskapsarkivet i Ironforges hjärta, till gagn för alla Alliansens lärda."},sec={{t="En mästares fältanteckningar",b="Archmage Theocritus är känd i hela Alliansen som en ansedd magiker stationerad i Tower of Azora, i den östra delen av Elwynn Forest. Under många år av ensamma studier har Theocritus undersökt märkliga artefakter, avvikelser i ley-linjer och magiska hot i närheten, och dokumenterat sina upptäckter i detaljerade journaler. Att återfinna en sådan volym ger en sällsynt möjlighet att studera de personliga observationerna från en högt uppsatt ärkemagiker i Kirin Tor."},{t="Utöka Ironforge-arkiven",b="Explorers' League och förvaltarna av Ironforge Library underhåller ett av kontinentens största arkiv. Genom att överlämna Archmage Theocritus' Research Journal till dem ser äventyrare till att dess arkana insikter bevaras och katalogiseras tillsammans med Khaz Modans historiska volymer. Bibliotekarierna välkomnar aktivt fler magiska upptäckter som kan bredda deras gemensamma kunskap."}},faq={{q="Vad är Archmage Theocritus' Research Journal?",a="Det är en vetenskaplig forskningsjournal som tillhör magikern Archmage Theocritus. Den lämnades in till Ironforge Library för att bevara arkan kunskap och utöka arkiven.",al={"lämna in theocritus journal","vad är theocritus journal"}},{q="Vem är Archmage Theocritus?",a="Archmage Theocritus är en berömd mänsklig magiker som bor i Tower of Azora i Elwynn Forest och studerar forntida magiska störningar och artefakter.",al={"vem är theocritus","archmage theocritus bakgrund"}},{q="Vart förs journalen?",a="Journalen förs till arkivarierna på biblioteket i Ironforge, som samlar sällsynta dokument och magiska handskrifter till sin samling.",al={"var lämnar jag in theocritus journal","vem vill ha theocritus journal"}},{q="Varför vill biblioteket ha journalen?",a="De lärda på Ironforge Library vill bevara arkan kunskap och studera sällsynta avhandlingar från mästarmagiker för att utöka sina historiska dokument.",al={"varför samla magiska journaler","syftet med theocritus journal"}},{q="Kan fler magiska verk lämnas till biblioteket?",a="Ja, förvaltarna uppmuntrar äventyrare att fortsätta leta efter förlorade magiska verk och historiska texter runt om i världen för att berika arkivsamlingen.",al={"fler journaler att lämna in","finns det fler böcker till biblioteket"}},{q="Vilken sorts forskning finns i journalen?",a="Journalen innehåller anteckningar och observationer som Archmage Theocritus sammanställde under sina omfattande undersökningar av magiska fenomen och arkan kunskap.",al={"vad finns i theocritus journal","innehållet i theocritus journal"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="Rumi of Gnomeregan: The Collected Works handlar om att återfinna och lämna in en sammanställd volym med gnomiska skrifter för att utöka ett biblioteks samling. Genom att överlämna dessa sällsynta texter hjälper äventyrare lärda att bevara värdefull historisk och magisk kunskap, så att den inte går förlorad.",h="Rumi of Gnomeregan: The Collected Works handlar om att återfinna och lämna in en sammanställd volym med...",kw={"samlade verk","gnomeregan-lore","gnomiska skrifter","bibliotek","magiska verk","rumi of gnomeregan"},ang={["class:Mage"]="Magikunniga lärda värdesätter sällsynta och märkliga skrifter som återfinns runtom i Azeroth, särskilt verk som ökar den gemensamma förståelsen för magisk teori och historia.",["faction:Alliance"]="Alliansens lärda och intendenter söker ständigt efter värdefull litteratur och magiska texter för att återfinna och skydda dem till nytta för Alliansens gemensamma kunskap.",["race:Gnome"]="För gnomer som vill bevara sin kultur och sina intellektuella bidrag efter Gnomeregans fall är det en viktig angelägenhet för arvet att Rumi och andra tänkares samlade skrifter förvaras tryggt i arkiven."},sec={{t="Att bevara gnomiskt tänkande",b="Rumi of Gnomeregan: The Collected Works är ett försök att bevara betydelsefull gnomisk litteratur och intellektuella bedrifter. Efter den förödande förlusten av Gnomeregan till trogginvasionen spreds många av gnomernas skriftliga arv, begravdes eller hotades av förstörelse. Lärda och arkivarier vid bibliotek och lärosäten söker aktivt efter överlevande manuskript, avhandlingar och samlade skrifter för att gnomiska tänkares visdom och uppfinningsrikedom inte ska gå förlorad med tiden."},{t="Återvinning till arkiven",b="När äventyrare hittar dessa samlingsverk ute i världen och lämnar in dem till arkiven införlivar intendenternas dem ivrigt i sina växande samlingar. Arkivarier ser varje återfunnet manuskript som ett tillskott till den gemensamma kunskapen och uppmuntrar resande att lämna in fler magiska eller historiska texter de hittar. Tack vare dessa bidrag förblir kunskapen tillgänglig för lärda, magiker och historiker som arbetar för att bevara Azeroths lärdomsarv."}},faq={{q="Vad är Rumi of Gnomeregan: The Collected Works?",a="Rumi of Gnomeregan: The Collected Works är ett uppdrag där man återfinner och skänker en betydelsefull samling gnomiska skrifter. En äventyrare lämnar in dessa litterära verk till en lärd som bygger upp ett biblioteks samling, så att värdefull kunskap bevaras och studeras.",al={"uppdraget rumi of gnomeregan","vad är rumi of gnomeregan","vem är rumi"}},{q="Var lämnar man in dessa samlingsverk?",a="Samlingsverken lämnas in till en intendent eller lärd som ansvarar för ett biblioteks samling. Mottagarna söker efter betydelsefulla skrifter och magiska avhandlingar för att utöka sina arkiv.",al={"var lämnar jag in rumi-skrifterna","vem tar emot rumi-böcker","lämna in rumi-samlingen"}},{q="Varför vill biblioteket ha dessa samlingsverk?",a="Lärda och arkivarier samlar aktivt in sällsynta texter, historiska avhandlingar och magiska manuskript från hela världen för att bevara viktig lärdom, särskilt skrifter med ursprung i Gnomeregan.",al={"varför samla in rumi-böcker","syftet med rumi of gnomeregan","varför biblioteket vill ha rumi"}},{q="Vem är Rumi of Gnomeregan?",a="Rumi of Gnomeregan är en intellektuell eller magisk författare vars samlade skrifter eftersöks av arkivarier. Eftersom Gnomeregan till stor del har blivit översvämmat av fiender är överlevande samlingar av gnomiskt tänkande och kunnande dyrbara vittnesmål om deras lärda traditioner.",al={"vem var rumi of gnomeregan","rumi-lore","rumi författare"}},{q="Kan man ta med fler böcker till biblioteket efter detta?",a="Ja, arkivarierna välkomnar fler fynd. Intendenter uppmuntrar äventyrare att fortsätta leta efter sällsynta eller betydelsefulla magiska avhandlingar och historiska verk som kan läggas till samlingen.",al={"finns det fler böcker att hitta","kan jag ta med fler texter","fler magiska verk till biblioteket"}},{q="Vem kan slutföra uppdraget?",a="Uppdraget utförs av äventyrare i Alliansen som hjälper lärda att bevara historisk och esoterisk litteratur. Alla som återfinner dessa värdefulla texter kan lämna in dem till arkiven och bidra till den lärda forskningen.",al={"krav för rumi-uppdraget","vem kan lämna in rumi-skrifterna","rumi endast för alliansen"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="Ta'zo ber dig att ta med magiska verk till biblioteket i Ironforge. Varje tillskott utökar dess samling och kunskap.",h="Ta'zo ber dig att ta med magiska verk till biblioteket i Ironforge.",kw={"samling","ironforge","kunskap","lärdomar","bibliotek","magiska verk","ta'zo"},sec={{t="Ett biblioteks samling",b="I Library of Ironforge ber Ta'zo dig att ta med något till samlingen. Magiska verk som kan vara till nytta för biblioteket är välkomna, och dina insatser hjälper till att utöka dess kunskap."}},faq={{q="Vem ber om magiska verk?",a="Ta'zo ber dig att ta med magiska verk som kan vara till nytta för biblioteket i Ironforge.",al={"vem är ta'zo","ta'zo bibliotek","ta'zo"}},{q="Vad vill Ta'zo att du tar med till biblioteket?",a="Ta'zo ber om magiska verk som kan vara till nytta för bibliotekets samling.",al={"vad ta med till ta'zo","magiska böcker","bibliotekets samling"}},{q="Var förvarar Ta'zo samlingen?",a="Samlingen finns i Library of Ironforge.",al={"var är ta'zo","ironforge bibliotek","bibliotekets läge"}},{q="Varför ber Ta'zo om magiska verk?",a="Ta'zo säger att bibliotekets kunskap växer genom dina insatser.",al={"varför magiska verk","utöka kunskap","hjälpa biblioteket"}}},fp="20,123,22.183.0,32.82.0,44.73.0,37.46.0,37.64.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="The Apothecary's Metaphysical Primer är en specialiserad magisk text som eftertraktas av samlingsansvariga för att berika vetenskapliga arkiv. När du lämnar in den hjälper du till att bevara sällsynt alkemisk och mystisk teori för forskare och magiker.",h="The Apothecary's Metaphysical Primer är en specialiserad magisk text som eftertraktas av samlingsansvariga...",kw={"alkemi","apotekare","undercity","bibliotek","magiska verk","metafysisk skrift","tome"},ang={["class:Mage"]="Utövare av magi värdesätter metafysiska skrifter för deras djupa insikter i magisk teori, alkemiska samspel och de grundläggande lagarna för besvärjelser.",["faction:Horde"]="Hordens lärda och äventyrare hjälper Owen Thadd i Undercity genom att återfinna sällsynta avhandlingar som stärker bibliotekets samlingar av mystiska verk."},sec={{t="Ett lärdt förvärv",b="The Apothecary's Metaphysical Primer är en vetenskaplig text som behandlar esoteriska och magiska principer. Samlingsansvariga som vill utöka sina arkiv välkomnar sådana avhandlingar och lägger till skriften direkt i sin samling av magiska referensverk."},{t="Utöka arkiven",b="Att bevara specialiserade avhandlingar är viktigt för bibliotek som Owen Thadds samling i Undercity. Genom att lämna över sällsynta skrifter om mystisk och alkemisk teori hjälper utforskare till att se till att sällsynta metafysiska insikter arkiveras säkert och är tillgängliga för forskare, i stället för att gå förlorade i vildmarken."}},faq={{q="Vad är The Apothecary's Metaphysical Primer?",a="The Apothecary's Metaphysical Primer är en sällsynt vetenskaplig text som eftertraktas av samlingsansvariga för att berika deras samling av magisk litteratur och fördjupa deras förståelse av metafysiska vetenskaper.",al={"vad är the apothecary's metaphysical primer","uppdraget med den metafysiska skriften","vad är det här för bok"}},{q="Vem vill att du lämnar in skriften?",a="Boken lämnas till Owen Thadd i Undercity, som söker efter magiska verk och mystiska avhandlingar för att bevara kunskap åt forskare och magiker.",al={"vem vill ha den här boken","var lämnar jag in skriften","vem tar emot skriften"}},{q="Varför samlar biblioteket på sådana verk?",a="Bibliotek och arkiv samlar metafysiska och magiska verk för att systematiskt utöka sina samlingar av lärdomar och hjälpa lärda, alkemister och mystiker att studera mystiska principer.",al={"varför vill biblioteket ha skriften","syftet med att samla in skriften","varför samla på magiska böcker"}},{q="Kan du ta med fler magiska verk till biblioteket?",a="Lärda som har i uppgift att katalogisera magisk litteratur välkomnar alla ytterligare mystiska och vetenskapliga fynd du gör som kan bidra till deras arkiv.",al={"finns det fler böcker att lämna in","kan jag ta med andra böcker","fler biblioteksböcker"}},{q="Vilken sorts lärdomar finns i en metafysisk skrift?",a="Inom magisk vetenskap handlar metafysik om den grundläggande naturen hos magiska energier, de osynliga krafter som styr verkligheten och hur fysiska reagenser samverkar med mystiska krafter.",al={"vad betyder metafysik i wotlk classic","metafysik i wow-lore","vad är apotekarmetafysik"}},{q="Vem skrev The Apothecary's Metaphysical Primer?",a="Den apotekare som skrev verket nämns inte vid namn i arkiven, men apotekare och lärda sammanställer ofta skrifter som sammanfattar praktisk alkemi, örtblandningar och mystiska formler.",al={"vem skrev apothecary primer","författaren till apothecary primer","vem är apotekaren"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="Ataeric: On Arcane Curiosities handlar om att lämna in återfunna magiska skrifter för att utöka en lärd samlings arkiv. Genom att samla in obskyra texter och avhandlingar från fältet vill forskare fördjupa sin förståelse för arkan forskning och bevara mystisk kunskap.",h="Ataeric: On Arcane Curiosities handlar om att lämna in återfunna magiska skrifter för att utöka en lärd...",kw={"arkan","arkana kuriositeter","ataeric","bibliotek","magiska verk","lärda"},ang={["class:Mage"]="Magiker har ett naturligt intresse för arkan forskning, vilket gör bidrag till lärda bibliotek och återfinnandet av magiska avhandlingar direkt relevanta för deras hantverk.",["race:Dwarf"]="Dvärgiska lärda och Explorers' League värdesätter insamling av skriftliga dokument, föremål och esoterisk kunskap högt."},sec={{t="Att bevara arkan kunskap",b="Lärda och arkivarier över hela Azeroth förlitar sig på kringvandrande äventyrare för att återfinna sällsynta böcker och bortglömda avhandlingar på farliga platser. I det här uppdraget söker en forskare magiska skrifter för att vidga en institutions förståelse för de arkaniska konsterna. Varje återfunnen bok hjälper till att sammanfoga mystiska bruk som annars kunde förbli utspridda eller gå förlorade."},{t="Ett växande arkiv",b="När kuratorn tar emot skrifterna införlivar hen dem direkt i arkivets samling. Biblioteket betraktar inte insamlingen som avslutad, utan efterlyser fortsatt alla magiska skrifter som upptäcks runt om i världen, så att samlingen kan växa i takt med forskningen."}},faq={{q="Vad är syftet med det här uppdraget?",a="Ataeric: On Arcane Curiosities handlar om att lämna in en lärd eller magisk text till en samlare som vill utöka ett biblioteks samling av esoterisk kunskap.",al={"vad är det här för uppdrag","ataeric-uppdrag","lämna in arkaniska skrifter"}},{q="Vem samlar in de arkaniska skrifterna?",a="Ataeric är avhandlingens författare. Den lämnas in till en forskare eller kurator som samlar magiska verk och sällsynta böcker för att berika ett biblioteks arkiv.",al={"vem vill ha det här","vem får boken","vem är ataeric"}},{q="Vilket bibliotek har nytta av dessa skrifter?",a="Texten eftersöks för att utöka en akademisk samling och gynna det lärda bibliotek som tar emot verket.",al={"vilket bibliotek gäller det","vart tar böckerna vägen"}},{q="Finns det fler magiska verk att samla in?",a="Den lärde uppmuntrar särskilt äventyrare att lämna in fler magiska verk som de hittar under sina resor, så att kunskapssamlingen hela tiden kan växa.",al={"kan man lämna in fler","återkommande magiska verk","fler böcker till biblioteket"}},{q="Varför söker biblioteket efter arkaniska skrifter?",a="Forskare letar ständigt efter sällsynta avhandlingar för att bättre förstå arkan magis nyanser och bevara historisk, mystisk kunskap.",al={"vad studerar biblioteket","varför samla arkaniska böcker"}},{q="Varför är det viktigt att återfinna arkaniska verk?",a="Arkaniska texter innehåller ofta instabil eller svårtolkad kunskap. Därför är det bättre att förvara och studera dem i ett särskilt bibliotek än att låta dem förbli förlorade ute i fältet.",al={"är det här farligt","risker med arkan magi"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="Baxtan: On Destructive Magics är ett akademiskt inlämningsuppdrag där en äventyrare lämnar Baxtans avhandling om destruktiva besvärjelser till en bibliotekslärd. Att återfinna sådana verk hjälper bibliotekets arkivarier att fördjupa sin förståelse av instabila arkana energier.",h="Baxtan: On Destructive Magics är ett akademiskt inlämningsuppdrag där en äventyrare lämnar Baxtans avhandling...",kw={"arkana","baxtan","bok","destruktiv magi","bibliotek","magi","volym"},ang={["class:Mage"]="Akademiska avhandlingar om destruktiv magi intresserar naturligt magiker, som studerar balansen mellan arkan kraft och destruktiva krafter.",["class:Warlock"]="De som utövar instabila eller förbjudna krafter förstår varför forskare vill studera destruktiv arkana magier.",["faction:Alliance"]="När kunskapen i Alliansens bibliotek växer stärks den akademiska grunden för hela Alliansen."},sec={{t="En volym om förödande konster",b="Uppdraget speglar forskarnas pågående arbete med att katalogisera och bevara arkan kunskap. När äventyrare hittar texter om destruktiv magis instabila natur ser noggrann akademisk förvaring till att dessa konsters kraft och faror blir förstådda i stället för att gå förlorade."},{t="Att vårda bibliotekets kunskap",b="Biblioteket förvarar historia, vetenskap och arkana kunskaper. Dess lärde ansvarar för att skaffa sällsynta volymer och välkomnar resenärer som återfinner bortglömda avhandlingar på farliga platser runt om i världen, så att bibliotekets samlade kunskap kan växa."}},faq={{q="Vad är uppdraget ”Baxtan: On Destructive Magics”?",a="Uppdraget går ut på att lämna Baxtans avhandling om destruktiv magis till en bibliotekslärd och därmed bidra till samlingen av magiska verk.",al={"vad är baxtan on destructive magics","vad är det här för uppdrag","baxtans uppdrag"}},{q="Vem är Baxtan?",a="Baxtan är författaren till avhandlingen On Destructive Magics. Den lärde som tar emot den samlar in betydelsefulla volymer och magiska avhandlingar till biblioteket.",al={"vem är baxtan","baxtan npc","var finns baxtan"}},{q="Vilken sorts böcker letar Baxtan efter?",a="Bibliotekets lärde söker akademiska och magiska verk som kan berika samlingen och välkomnar fler avhandlingar om magi som upptäcks runt om i världen.",al={"vilken sorts böcker vill baxtan ha","baxtans boksamling","fler böcker till baxtan"}},{q="Vart tar den här magiska kunskapen vägen?",a="Texterna som samlas in förs till bibliotekets samling, där kunskap om arkana och farliga konster bevaras för studier.",al={"vart tar boken vägen","vilket bibliotek","ironforges bibliotekssamling"}},{q="Varför samlar biblioteket verk om destruktiv magi?",a="Forskare katalogiserar destruktiv magi för att bättre förstå riskerna, de teoretiska mekanismerna och uttrycken för mäktiga arkana energier.",al={"varför studera destruktiv magi","lore om destruktiv magi"}},{q="Kan du ta med fler magiska verk till Baxtan?",a="Ja. Den lärde uppmanar äventyrare att fortsätta ta med alla ytterligare magiska verk de hittar, vilket visar att arbetet med att samla kunskap pågår.",al={"finns det fler uppdrag för baxtan","kan jag lämna in fler böcker"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="Carry Your Weight",s="Högst upp i vakttornet med utsikt över Razor Hill ber Furl Scornbrow unga äventyrare från Horden att samla kanvas från fientliga människor och kentaurer. Veteranen, vars kropp är täckt av ärr, är för gammal för frontlinjen och tillverkar förnödenheter som hjälper dem på deras färd.",h="Högst upp i vakttornet med utsikt över Razor Hill ber Furl Scornbrow unga äventyrare från Horden att samla...",kw={"canvas scraps","carry your weight","durotar","furl scornbrow","kolkar","razor hill","razor hill watchtower","tiragarde"},ang={["faction:Horde"]="Som ung soldat i Horden i Durotar förlitar du dig på erfarna veteraner som Furl Scornbrow. De påminner nykomlingar om att hedra Horden genom att utföra de plikter hemlandet kräver, vare sig det gäller att vakta en utpost eller sy kanvas.",["profession:Tailoring"]="Som skräddare ser du Furls robusta gränslandshantverk i varje väska. Han förvandlar bortkastad, kraftig kanvas från mänskliga inkräktare och kentaurplundrare till slitstark utrustning för att överleva i vildmarken.",["race:Orc"]="Som ork ser du i Furl en äldre som bröt sig fri från demonisk fördärvelse och korsade havet med Thrall. Liksom andra i sin generation ägnar han sina sista år åt att vårda framtiden för sitt unga land."},sec={{t="En veterans uppdrag",b="Furl Scornbrow stred vid hövding Thralls sida i Durotar och vid Mount Hyjal. Åldern och gamla skador har gjort veteranen långsammare, och han svingar inte längre sin yxa i strid. Från vakttornet i Razor Hill håller Furl ständig uppsikt och slår larm vid intrång. Från sin post stöder han nästa generation försvarare."},{t="Insamlad presenning",b="När Hordens grepp om regionen hårdnar blir signalhornets larm allt ovanligare, vilket ger Furl fler timmar att tillverka praktisk utrustning. Stadig kanvas är en bristvara i Durotars torra raviner, men Kul Tiran-inträngarna längs den östra kusten och de nomadiska Kolkar-kentaurerna som strövar över slätterna bär på gott om den. Kanvas som bärgats från dessa fientliga styrkor ger Furl tyg att sy praktiska väskor av åt aktiva spejare."}},faq={{q="Vem är Furl Scornbrow?",a="Furl Scornbrow är en åldrande orkveteran som är stationerad högst upp i vakttornet ovanför Razor Hill. Han stred vid Thralls sida när Durotar grundades och anslöt sig till styrkorna som besegrade Archimonde vid Mount Hyjal. Även om han inte längre kan strida vid frontlinjen håller Furl vakt och tillverkar fältutrustning åt unga krigare från Horden.",al={"vem är furl","furl scornbrows historia","vem ger carry your weight"}},{q="Var hittar man presenningsbitar i Durotar?",a="Kanvasrester kan samlas från Kul Tiran-människor längs Durotars östra kust och från nomadiska Kolkar-kentaurer som strövar över slätterna. Båda bär på stadig kanvas som går att bärga från deras tillhörigheter.",al={"var hittar man presenningsbitar","vem släpper presenningsbitar","platser med presenningsbitar"}},{q="Var ligger vakttornet där Furl finns?",a="Furls vakttorn står på de höga, klippiga branterna rakt nordväst om Razor Hill. En slingrande stig bakom bosättningen leder upp till toppen och dess utsiktstorn av trä.",al={"var finns furl scornbrow","razor hill watchtower plats","hitta razor hill watchtower"}},{q="Vad tillverkar Furl av presenningsbitarna?",a="Furl syr ihop kanvasresterna till praktiska väskor åt unga äventyrare som färdas genom Durotar. Det extra utrymmet hjälper dem att bära med sig förnödenheter, proviant och bärgade vapen genom den hårda vildmarken.",al={"vad tillverkar furl","vad används presenningen till","belöning för presenningsbitar"}},{q="Varför tillverkar en gammal krigare väskor i stället för att strida?",a="Åldern och gamla skador har gjort att Furl inte längre kan hålla jämna steg med fältets krav på snabbhet och styrka. Han finner ära i pensionen genom att hålla vakt över Razor Hill och tillverka utrustning som hjälper yngre kämpar att försvara riket.",al={"varför tillverkar furl saker","varför stannar furl i tornet","varför strider inte furl"}},{q="Vilket krig stred Furl i?",a="Furl stred under hövding Thrall under det tredje kriget, hjälpte till att slå sig ned i Durotar och kämpade mot den brinnande legionen vid Mount Hyjal. Han deltog i den tillfälliga men nödvändiga vapenvilan mellan Horden, nattalverna och Alliansen för att besegra Archimonde.",al={"fur l stridshistoria","vad gjorde furl tidigare","archimonde furl"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="En väderbiten lapp i The Barrens leder resenärer mot Stepping Stones, ett bergsrefugium nära Desolace. Där står det att två kurirer gjorde leveranser åt The New Plague och kallar det som hände dem för vanliga olyckor bland alkemister.",h="En väderbiten lapp i The Barrens leder resenärer mot Stepping Stones, ett bergsrefugium nära Desolace.",kw={"desolace","legosoldater","berg","the new plague","lapp","royal apothecary society","stepping stones","the barrens"},ang={["class:Rogue"]="Som skurk vet du hur man spårar anonyma informatörer och bedömer hemliga meddelanden som lämnats mellan Desolace och The Barrens.",["faction:Horde"]="Som kringvandrande hordemedlem i The Barrens måste du överväga om rapporter om dödliga pestleveranser på Kalimdors mark hotar dina områden och allianser.",["race:Undead"]="För resande Forsaken är en antydan om Royal Apothecary Society och dess arbete med blight en akut säkerhetsfråga, eller en farlig sammansvärjning inifrån."},sec={{t="En lapp i vildmarken",b="Ett sönderrivet meddelande hänger på en träplanka vid ett avlägset läger i The Barrens. Legosoldater, stråtrövare och kringvandrande främlingar passerar genom sådana läger för att få kortvarigt skydd, långt från The Crossroads och Ratchets blickar. Bland vildmarkens vanliga tecken ger lappen ett skäl att se bortom lägret och mot bergen."},{t="Viskningar om The New Plague",b="Den anonyma skribenten säger att två agenter gjorde leveranser åt The New Plague och kallar sedan det som hände dem för vanliga olyckor bland alkemister. Lappen föreslår att ni möts vid ett bergsrefugium mellan The Barrens och Desolace, där ni kan diskutera saken i säkerhet."}},faq={{q="Vad handlar lappen som hittades i Stepping Stones om?",a="Lappen säger att två kurirer som gjorde leveranser åt The New Plague mötte en plötslig död, vilket skribenten kallar vanliga olyckor bland alkemister. Skribenten föreslår en mötesplats i bergen för att diskutera vad som hände.",al={"lappen i stepping stones","vad handlar lappen om","uppdragstext för stepping stones"}},{q="Vart säger lappen att du ska gå?",a="Skribenten hänvisar dig till ett avskilt refugium i bergen mellan The Barrens och Desolace.",al={"vart gå i stepping stones","avskild plats i bergen","stepping stones plats"}},{q="Vad är The New Plague som nämns i brevet?",a="The New Plague är en dödlig blandning som utvecklats i Undercity av Forsakens Royal Apothecary Society. Den ska förgöra både Scourge och levande fiender, och testerna samt kurirernas färder över kontinenterna präglas av hemlighetsmakeri och livsfara.",al={"vad är the new plague","royal apothecary och pesten","apotekarnas leveranser"}},{q="Vem skrev lappen som satt fast på plankan?",a="Lappen är anonym och sitter fastnålad på en grovhuggen träplanka vid ett avlägset läger. Skribenten föreslår en mötesplats i bergen mellan The Barrens och Desolace.",al={"vem skrev lappen","författaren till stepping stones","vem väntar i bergen"}},{q="Varför skulle kurirer åt Forsaken befinna sig i Kalimdor?",a="Forsaken-alkemister samlar exotiska gifter, sporer och reagenser från Kalimdors växter och djur och samordnar sedan leveranser via Hordens utposter och vildmarksleder.",al={"forsaken i the barrens","varför the new plague i kalimdor","apotekare i the barrens"}},{q="Varför används avlägsna läger för sådana här lappar?",a="Utanför de större bosättningarna breder The Barrens ut sig och styrs löst. Neutrala rastställen, legosoldaters viloplatser och laglösa läger låter resenärer, smugglare och informatörer lämna diskreta meddelanden, undan Horden och regionens vaktposter.",al={"berättelser om avlägsna läger","legosoldatläger i the barrens"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="Vile Familiars",s="I Valley of Trials kryper Vile Familiars ut ur en närbelägen grotta. Zureetha Fargaze upptäckte en dold Burning Blade Coven när hon höll uppsikt över dalens prövningar. Rekryter skickas ut för att jaga de små demoner som sprider sig över Durotars röda jord.",h="I Valley of Trials kryper Vile Familiars ut ur en närbelägen grotta.",kw={"burning blade","burning blade coven","durotar","impdjävlar","the den","valley of trials","vile familiars","zureetha fargaze"},ang={["class:Warlock"]="Som ork- eller trollhäxmästare möter du avfälliga skuggmagiker som missbrukar demoniska pakter för att ödelägga, i stället för att styra kaosenergierna mot Hordens överlevnad.",["faction:Horde"]="Som medlem av Horden möter du Burning Blades försök att korrumpera Durotar inifrån innan den unga Horden hinner etablera sin suveränitet ordentligt.",["race:Orc"]="Som ork möter du kaosfördärv på dina heliga träningsplatser, en bitter påminnelse om att Skuggrådets arv ännu ruttnar trots Thralls förkastande av demoniskt slaveri."},sec={{t="En skugga i dalen",b="Valley of Trials prövar unga orcher och Darkspear Trolls i styrka, disciplin och lojalitet mot Thralls Horde. Prövningarna var tänkta att ställa rekryterna mot skorpider och vildsvin, inte demonisk korrumpering. Men en grotta i nordost hyser agenter från Burning Blade, som har bildat en hemlig kult under dalens uppsyningsmäns näsor."},{t="Gallra bland impdjävlarna",b="Zureetha Fargaze, en instruktör som vägleder nykomlingar nära The Den, upptäckte fördärvet innan det hann ta över ravinen. Vile Familiars strömmar nu ut ur grottmynningen och kastar eld mot alla som kommer för nära. Innan Horden kan röja ut mästarna som gömmer sig där skickas unga rekryter för att slå ner dessa mindre tjänare och hålla dalen säker."}},faq={{q="Vem ger uppdraget Vile Familiars?",a="Zureetha Fargaze ger dig uppdraget. Hon väntar precis utanför ingången till The Den, mitt i Valley of Trials.",al={"uppdragsgivare för vile familiars","vem ger vile familiars","var hämtar man vile familiars"}},{q="Vad är Vile Familiars?",a="Vile Familiars är små, imp-liknande demoner som åkallas och binds av Burning Blades kultister. De är mindre hantlangare och husdjur som använder eld mot inkräktare.",al={"vad är vile familiars","vile familiars bakgrund","typ av fiende vile familiars"}},{q="Var ligger Burning Blade Coven?",a="Burning Blade Coven gömmer sig i en grotta i nordöstra Valley of Trials, bortom de kringströvande Mottled Boars och Scorpid Workers.",al={"burning blade coven plats","var ligger burning blade coven","grotta i valley of trials"}},{q="Varför finns Burning Blade i Valley of Trials?",a="Burning Blade är en hemlig kult som vill underminera Thralls nya Horde och sprida demoniskt fördärv. Från Valley of Trials kan de hålla sig gömda samtidigt som de hotar Hordens nyaste kämpar medan den etablerar sin suveränitet.",al={"varför är burning blade här","burning blades motiv","vad vill burning blade"}},{q="Vad händer när man har slutfört Vile Familiars?",a="När antalet Vile Familiars utanför grottan har minskat skickar Zureetha Fargaze in dig i grottan för att möta kultisternas ledare och återta en Burning Blade Medallion.",al={"uppföljning till vile familiars","vad händer efter vile familiars","uppdrag med burning blade medallion"}},{q="Måste jag gå djupt in i grottan för att hitta de bekanta?",a="Nej. Vile Familiars håller till inne i grottan, men många svärmar kring ingången och över ravinens botten utanför grottmynningen.",al={"finns vile familiars inne i grottan","var dödar man vile familiars","farma vile familiars"}}},fx={edfaf791={q="Varför vill Zureetha Fargaze att de avskyvärda bekantskaparna dödas?",a="Zureetha Fargaze kom till Valley of Trials för att vägleda nya rekryter, men upptäckte en växande korrumpering alldeles vid Hordens tröskel. Den fördolda Burning Blade-kulten har upprättat en hemlig församling i grottorna i närheten, och deras tillkallade imps sprider sig över dalen. För att skydda prövningsmarkerna och rena bort den demoniska smittan innan den sprider sig vidare behöver hon få deras förtrupp undanröjd.",al={"varför döda avskyvärda bekantskapare","zureetha fargazes motiv","varför vill zureetha att avskyvärda bekantskapare dödas"}},["67a24c10"]={q="Varför skickar Zureetha dig i stället för att själv ta hand om bekantskaparna?",a="Du är i Valley of Trials för att bevisa att du förtjänar att tjäna Horden. Medan Zureetha samordnar insatsen mot de fördolda kultisterna och håller vakt utanför The Den, fyller det två syften att skicka iväg dig: det hejdar den demoniska invasionen som hotar dalen, samtidigt som det blir ett viktigt elddop mot de mörka makter som undergräver ditt folk.",al={"varför skicka mig","varför slåss inte zureetha","varför måste jag döda bekantskaparna"}}},fp="14,220,22.318.0,16.332.0,35.113.0,24.147.0,41.137.0,49.243.0,45.170.1,57.130.0"}
P.entries["quest:79229"] = {n="Highway Robbery",s="I Desolace bär ett plundrat läger spår av ett våldsamt angrepp. Du söker någon som kan förklara vad som hänt.",h="I Desolace bär ett plundrat läger spår av ett våldsamt angrepp.",kw={"angrepp","lägerplats","kentaur","desolace","dvärg","highway robbery","människa","plundrat läger","asätare"},sec={{t="Ett plundrat läger",b="Två människor och en dvärg ligger bland resterna av ett läger i Desolace. Märkena på deras ben tyder på ett brutalt angrepp, medan de stulna förnödenheterna visar att ett djur inte låg bakom det. Såren stämmer inte heller med kentaurernas vapen. Du ombeds hitta någon i Desolace som känner markerna och kan förklara tecknen."}},faq={{q="Vilka angreps vid lägret?",a="Kvarlevorna tyder på att två människor och en dvärg angreps.",al={"vem dog vid lägret","offer vid lägret","människor och dvärg"}},{q="Vad hände vid lägret?",a="Lägret plundrades, och kvarlevorna visar spår av ett brutalt angrepp.",al={"vad hände här","plundrat läger","angrepp vid lägret"}},{q="Låg ett djur bakom det?",a="De plundrade förnödenheterna tyder på att inget djur låg bakom angreppet.",al={"djurangrepp","djuret gjorde det","vem angrep dem"}},{q="Orsakades såren av kentaurer?",a="Såren stämmer inte med kentaurernas vapen.",al={"kentaurangrepp","kentaurvapen","var det kentaurerna"}},{q="Vem kan förklara angreppet?",a="Du ombeds hitta någon i Desolace som är van att leta efter fynd i markerna.",al={"vem känner till lägret","fråga en asätare","vem ska jag hitta"}}},fp="15,119,16.330.0,33.63.0,30.73.0,26.65.0,33.41.0,27.80.0"}
P.entries["quest:79235"] = {n="On the Lam",s="Ett karavanrykte pekar ut rövare från Horde som flydde Desolace efter angrepp på människors och dvärgars läger. Du skickas mot Booty Bay för att hitta en av dem.",h="Ett karavanrykte pekar ut rövare från Horde som flydde Desolace efter angrepp på människors och dvärgars...",kw={"alliance-marskalk","booty bay","karavaner","desolace","horde","rövare","on the lam"},sec={{t="Ett spår till Booty Bay",b="En karavankontakt berättar om angrepp på människors och dvärgars läger i Desolace och pekar sedan ut Booty Bay. Offren och våldet har fått karavanerna att misstänka rövare från Horde. En Alliance-marskalk förföljde banditerna, som lämnade Desolace. Nu får du i uppdrag att hitta en av dem."}},faq={{q="Vem angrep lägren?",a="Ett karavanrykte skyller angreppen på människors och dvärgars läger i Desolace på en grupp rövare från Horde.",al={"vem gjorde det","lägerangripare"}},{q="Vart tog rövarna vägen?",a="Banditerna flydde från Desolace efter att en Alliance-marskalk förföljt dem. Booty Bay föreslås som en plats att leta på efter en av dem.",al={"vart de flydde","rövarnas plats"}},{q="Varför leta i Booty Bay?",a="Kontakten föreslår Booty Bay eftersom personer med tvivelaktigt rykte passerar genom hamnen, och en rövare kanske söker en båt.",al={"varför booty bay","var hitta rövaren"}},{q="Vad letar jag efter?",a="Du letar efter en av rövarna från Desolace.",al={"målet med on the lam","hitta en"}}},fp="10,150,20.286.0,23.97.0,27.116.0,22.130.0,22.55.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="I Booty Bay söker en legosoldat vid namn Tokal en drink i utbyte mot sanningen bakom de senaste attackerna mot mänskliga och dvärgläger. Rykten pekar ut Horden, men Tokal hävdar att hennes grupp arbetade på ett privat legosoldatskontrakt.",h="I Booty Bay söker en legosoldat vid namn Tokal en drink i utbyte mot sanningen bakom de senaste attackerna...",kw={"booty bay","cherry for your thoughts","cherry grog","marskalk","legosoldat","plundring","privat kontrakt","tokal"},ang={["faction:Alliance"]="Alliansens medlemmar blir intresserade av att få veta att plundrarna som angrep mänskliga och dvärgiska läger inte agerade på Hordens uppdrag, utan anlitades av en privat uppdragsgivare.",["faction:Horde"]="Hordens äventyrare kan känna sig upprättade av Tokals erkännande, som klargör att attackerna mot Alliansens läger utfördes på privata legosoldatskontrakt och inte var officiell aggression från Hordens sida."},sec={{t="Viskningar i Booty Bay",b="I den livliga hamnen Booty Bay håller sig Tokal undan medan hon håller utkik efter lagens väktare. En rad våldsamma räder ödelade nyligen mänskliga och dvärgläger, och rykten spreds om att Horden låg bakom attackerna. När resenärer närmar sig, och uppenbart inte arbetar för marskalken som utreder saken, avvisar Tokal snabbt den allmänna berättelsen och erbjuder en annan version i utbyte mot en drink."},{t="Privata legosoldater",b="Tokal medger villigt att hon deltog i plundringen av mänskliga och dvärgläger, men förnekar bestämt att räderna utfördes på Hordens uppdrag. I stället hävdar hon att hennes skara arbetade på privat kontrakt åt en okänd tredje part. Innan hon berättar hela historien om vem som finansierade operationen och varför, kräver hon att få en uppfriskande Cherry Grog."}},faq={{q="Vem är Tokal?",a="Tokal är en operatör eller legosoldat som sökt skydd i piraternas tillflyktsort Booty Bay. Hon granskas för de senaste räderna mot mänskliga och dvärgiska bosättningar och erbjuder sig att berätta hela historien om vem hon arbetade för till den som bjuder henne på en Cherry Grog.",al={"vem är tokal","tokal booty bay","uppdragsgivare för cherry grog"}},{q="Varför vill Tokal ha en Cherry Grog?",a="Tokal vill inte berätta känsliga detaljer om sina tidigare kontrakt när hon är törstig. En Cherry Grog får henne att lätta på tungans band och förklara vem som privat finansierade räderna mot Alliansens läger.",al={"varför köpa cherry grog","cherry grog tokal","vad vill tokal ha"}},{q="Låg Horden bakom plundringen av de mänskliga och dvärgiska lägren?",a="Enligt Tokal beordrade Horden inte räderna mot de mänskliga och dvärgiska lägren. Rykten påstod att Horden låg bakom, men hon hävdar att hennes grupp arbetade på ett privat legosoldatskontrakt.",al={"vem anlitade tokal","attackerade horden alliansens läger","låg horden bakom räderna"}},{q="Varför oroar Tokal sig för en marskalk?",a="Tokal fruktar att en marskalk som utreder plundringen av mänskliga och dvärgiska bosättningar är henne på spåren. Hon försäkrar sig noga om att ingen som närmar sig henne i Booty Bay är en agent utsänd för att ställa henne inför rätta.",al={"vem är marskalken","gömmer sig tokal för marskalken","marskalken letar efter tokal"}},{q="Var får du tag på Cherry Grog åt Tokal?",a="Cherry Grog är en dryck som går att få från värdshusvärdar och bartendrar i Booty Bay. När du ger Tokal en mugg av drycken får hon som hon vill och berättar sin historia.",al={"var får man tag på cherry grog","cherry grog plats","grog i booty bay"}},{q="Varför håller Tokal till i Booty Bay?",a="Booty Bay är en neutral hamn för fribytare, utanför både Alliansens och Hordens strikta jurisdiktion. För en legosoldat på flykt efter att ha plundrat mänskliga och dvärgiska läger är det ett idealiskt gömställe.",al={"varför är tokal i booty bay","tokals gömställe"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:79242"] = {n="No Honor Among Thieves",s="En före detta tjuv pekar ut Illari Duskfeather som Night Elf-ledaren som övergav gänget. Du får veta var hennes gömställe ligger vid Arathi Highlands kust och var hon har gömt sitt stöldgods.",h="En före detta tjuv pekar ut Illari Duskfeather som Night Elf-ledaren som övergav gänget.",kw={"arathi highlands","förråd","gömställe","illari duskfeather","marshal","night elf","ingen heder bland tjuvar","stulet byte","tjuvar"},ang={["race:NightElf"]="Som Night Elf får du veta att Illari Duskfeather ledde ett gäng tjuvar och övergav dem när marshalen förföljde dem."},sec={{t="Ett förrått gäng",b="Marshalen är gänget på spåren när Illari Duskfeather överger dem. En överlevande tjuv tror att de användes som syndabockar, men kan inte säga varför. Han lämnar jakten åt den som är villig att följa spåren. Illari nämnde en gång ett gömställe vid Arathi Highlands kust, där hennes stöldgods finns kvar."}},faq={{q="Vem är Illari Duskfeather?",a="Illari Duskfeather är en Night Elf som ledde ett gäng tjuvar. Hon gav dem information om lägren och behöll bara några av deras mer sällsynta fynd.",al={"illari","vem är illari","illari duskfeathers bakgrund"}},{q="Varför lämnade Illari gänget?",a="Den överlevande tjuven vet inte varför Illari övergav gänget när marshalen var dem på spåren.",al={"varför lämnade hon","illaris motiv","varför överge tjuvarna"}},{q="Var hittar jag Illari?",a="Illari nämnde en gång ett gömställe vid Arathi Highlands kust.",al={"illaris plats","var är illari","gömställe i arathi"}},{q="Vad vill gänget ha av Illari?",a="En tidigare medlem i gänget pekar ut Illaris gömställe och hennes förråd av stöldgods.",al={"illaris förråd","stulet gods","vad finns i hennes gömställe"}},{q="Vem var gängets boss?",a="Illari Duskfeather, en Night Elf, var gängets boss.",al={"tjuvboss","gängledare","vem ledde tjuvarna"}}},fp="22,194,15.303.0,26.140.0,30.100.0,24.65.0,36.90.0,24.53.0"}
P.entries["quest:793"] = {n="Broken Alliances",s="Gorn skickar dig till Lethlor Ravine längst österut i Badlands, där de svarta drakarna Blacklash och Hematus hålls bundna av jordens sigill. Detta följer på det första Broken Alliances.",h="Gorn skickar dig till Lethlor Ravine längst österut i Badlands, där de svarta drakarna Blacklash och Hematus...",kw={"den svarta drakflygeln","blacklash","orcherna från blackrock","gorn","hematus","lethlor ravine","jordens sigill","sign of the earth"},sec={{t="Tre runstenar",b="Tre runstenar håller jordens sigill stängt. Var och en vilar i en pelare i Lethlor Ravine: Diamond, Opal och Amethyst. Sign of the Earth, som Gorn ger dig, drar ut stenarna och öppnar sigillet. Otaliga drakar har sitt hem i ravinen, och Blacklash och Hematus är mäktiga motståndare. Gorn vill att båda dödas och att deras bojor förs tillbaka."},{t="Vad Gorn tänker göra",b="Gorn säger att den svarta drakflygeln fortfarande är allierad med de fredlösa orcherna från Blackrock och att både drakar och orcher måste tyglas eller drivas bort. När Blacklash och Hematus har dödats kan Horden rikta blicken västerut mot Blackrock Spire."}},faq={{q="Vem ger det här uppdraget?",a="Gorn ger det, som nästa steg efter det första Broken Alliances.",al={"uppdragsgivare för broken alliances","gorns plats","vem ger broken alliances"}},{q="Var ligger Lethlor Ravine?",a="Res till Badlands längst österut. Otaliga drakar har sitt hem i ravinen.",al={"lethlor ravines plats","hur man tar sig till lethlor ravine","var ligger lethlor ravine"}},{q="Hur befriar du Blacklash och Hematus?",a="Sign of the Earth drar ut en runsten ur var och en av de tre pelarna. När stenarna sätts i jordens sigill blir båda drakarna fria.",al={"hur man tillkallar blacklash","jordens sigill","pelarna diamond opal amethyst"}},{q="Vad måste föras tillbaka till Gorn?",a="Blacklashs bojor, Hematus kedjor och Sign of the Earth, när båda drakarna har dödats.",al={"föremål att lämna in för broken alliances","vad gorn vill ha tillbaka","blacklashs bojor"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79358"] = {n="Storm, Earth, and Fire",s="Veyric Thunderhame ber dig samla förvridna elementartotemer i Arathi Highlands. Han hoppas lära sig hur andra folk utövar shamanism och hitta ett sätt att motverka quilboarernas elementmagi.",h="Veyric Thunderhame ber dig samla förvridna elementartotemer i Arathi Highlands.",kw={"arathi highlands","motritual","quilboar","shamanism","storm jord och eld","thousand needles","förvridna totemer","veyric thunderhame"},ang={["class:Shaman"]="Som shaman ombeds du hjälpa Veyric att lära sig hur folken i Azeroth utövar shamanism och förstå de förvridna elementen."},sec={{t="En motritual",b="Veyric Thunderhame i Arathi Highlands behöver din hjälp efter att quilboarerna översvämmat Thousand Needles. Han säger att deras bruk av elementen har väckt vrede, och att en motritual kräver bättre kunskap om dessa förvridna krafter. En bok beskriver hur Azeroths många folk utövar shamanism. Veyric ber dig ta med förvridna eld-, jord-, luft- och vattentotemer så att han kan lära sig av dem."}},faq={{q="Vem ber om totemerna?",a="Veyric Thunderhame i Arathi Highlands ber dig samla förvridna eld-, jord-, luft- och vattentotemer.",al={"vem vill ha totemerna","veyric ber om"}},{q="Varför behöver Veyric totemerna?",a="Veyric vill förstå de förvridna elementen medan han försöker skapa en motritual mot quilboarernas elementmagi.",al={"varför totemer","vad ska de användas till"}},{q="Vad hände i Thousand Needles?",a="Quilboarerna översvämmade Thousand Needles, och Veyric säger att deras bruk av elementen har väckt vrede.",al={"översvämningen i thousand needles","vad gjorde quilboarerna"}},{q="Vad beskriver boken?",a="Boken beskriver Azeroths många folk och hur de utövar shamanism.",al={"bok om shamanism","vad står i boken"}},{q="Vilka totemer ber Veyric om?",a="Han ber om förvridna eld-, jord-, luft- och vattentotemer.",al={"typer av totemer","eld jord luft vatten"}}},fp="22,198,16.393.0,29.102.0,32.125.0,34.101.0,28.79.0,33.55.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="En uppmaning att återgälda elementens hjälp sänder dig till Razorfen Kraul. Quilboar förvrider elementarkraft, och deras planer hotar dessa länder.",h="En uppmaning att återgälda elementens hjälp sänder dig till Razorfen Kraul.",kw={"charlga razorflank","elementens hjälp","elementen","quilboar","quilboarernas planer","razorfen kraul"},ang={["class:Shaman"]="Som schaman har du bemästrat elementen och ombeds återgälda deras hjälp genom att skydda dem från quilboarernas planer."},sec={{t="En kallelse till elementen",b="Elementen har hjälpt dig, och nu ombeds du att återgälda den tjänsten. Quilboar förvrider deras kraft för egna syften och verkar vilja utöka sitt inflytande inom dessa gränser. Du skickas till Razorfen Kraul för att stoppa deras planer och skydda länderna."}},faq={{q="Varför ska jag bege mig till Razorfen Kraul?",a="Quilboar förvrider elementen för egna syften och verkar utöka sitt inflytande. Du ombeds stoppa deras planer och skydda länderna.",al={"varför razorfen kraul","varför bege sig till kraul","orsak till elementens hjälp"}},{q="Vem är Charlga Razorflank?",a="Charlga Razorflank är quilboaren du skickas till Razorfen Kraul för att besegra.",al={"vem är charlga","charlga razorflank","razorflank"}},{q="Vilka uppgifter ska jag samla in?",a="Du ombeds samla in uppgifter om quilboarernas planer.",al={"quilboarernas planer","vilka uppgifter","information om planer"}},{q="Varför ska jag hjälpa elementen?",a="Du har fått hjälp av elementen och ombeds återgälda den tjänsten genom att skydda länderna från quilboarernas planer.",al={"varför elementens hjälp","hjälpa elementen","återgälda elementen"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="Prate Cloudseer ber dig hjälpa till att hindra quilboarerna från att översvämma Thousand Needles genom förvriden schamanism. En bok avsedd för din träning kan hjälpa till att skingra den annalkande stormen.",h="Prate Cloudseer ber dig hjälpa till att hindra quilboarerna från att översvämma Thousand Needles genom...",kw={"prate cloudseer","quilboar","storm jord och eld","thousand needles","bok","förvriden schamanism","förvridna totem"},sec={{t="En storm närmar sig",b="Prate Cloudseer hade tänkt fortsätta din träning, men hotet i Thousand Needles kan inte vänta. Du har sett att quilboarerna inte är att ta lätt på. Prate ger dig en bok avsedd för studier och ber dig samla förvridna eld-, jord-, luft- och vattentotem. Boken kan innehålla ett sätt att skingra stormen de frammanar."}},faq={{q="Vem ber om hjälp?",a="Prate Cloudseer ber dig samla förvridna totem i Thousand Needles.",al={"vem är prate","prate cloudseer","cloudseer"}},{q="Vad försöker quilboarerna göra?",a="Prate säger att quilboarerna tänker översvämma Thousand Needles genom förvriden schamanism.",al={"quilboarernas plan","varför totem","quilboarernas storm"}},{q="Vad ger Prate mig?",a="Prate ger dig en bok som var avsedd för studier och kan hjälpa till att skingra den annalkande stormen.",al={"bok","vad är boken","studiebok"}},{q="Vilka totem behöver Prate?",a="Prate ber dig samla förvridna eld-, jord-, luft- och vattentotem.",al={"totemtyper","eld jord luft vatten","vilka totem"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Grant's Shield",s="Sirra Von’Indie söker Grant Valors stridsklubba i Raven Hill Cemetery, där hans ande ännu kämpar mot de odöda. Vapnen kan hjälpa henne att lära sig mer om den stolte hjälten.",h="Sirra Von’Indie söker Grant Valors stridsklubba i Raven Hill Cemetery, där hans ande ännu kämpar mot de odöda.",kw={"darkshire","grant valor","grants stridsklubba","grants sköld","raven hill cemetery","sirra von'indie","odöda","familjen valor"},sec={{t="En fallen hjälte",b="Sirra Von’Indie i Darkshire ber dig att hitta Grant Valors stridsklubba bland skeletten i Raven Hill Cemetery. Grants vålnad lämnade kvar hans sköld, och hans ande kämpar fortfarande mot de odöda där. Stridsklubban kan ge en ledtråd om vilken varelse som skadade honom, och Sirra vill studera vapnen."},{t="Vapnen",b="I Darkshire begrundar Sirra Von’Indie hur en simpel varelse kunde besegra Grant Valor. Hon säger att ett enda felsteg kan göra en människa invalid för livet. Hon tror att vapnen berättar mycket om sin ägare, och hon tar sig tid att studera dem."}},faq={{q="Vem var Grant Valor?",a="Grant Valor var far i familjen Valor och en hjälte i Raven Hill. Hans vålnad kämpar fortfarande mot de odöda.",al={"grant valor","vem är grant","grants bakgrund"}},{q="Var finns Grants stridsklubba?",a="Grants stridsklubba finns på ett av skeletten i Raven Hill Cemetery.",al={"grants stridsklubba","hitta grants stridsklubba","stridsklubbans plats"}},{q="Varför letar jag efter Grants stridsklubba?",a="Sirra Von’Indie ber dig att hitta stridsklubban så att hon kan lära sig mer av Grants vapen.",al={"varför hitta stridsklubban","uppdrag grants sköld","vad vill sirra"}},{q="Vart ska jag ta stridsklubban?",a="Lämna tillbaka Grants stridsklubba till Sirra Von’Indie i Darkshire.",al={"lämna tillbaka stridsklubban","sirras plats","var är von'indie"}},{q="Vad hände med Grant?",a="Grant skadades av en varelse i Raven Hill Cemetery. Hans ande kämpar fortfarande mot de odöda där.",al={"grant skadad","hur skadades grant","grant valors sköld"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="Silvia's Sword",s="Sirra Von'Indi ber dig undersöka Silvia Valors svärd och Defias nära Raven Hill. Klingan tillhörde en vakt som skyddade civila och deras hem.",h="Sirra Von'Indi ber dig undersöka Silvia Valors svärd och Defias nära Raven Hill.",kw={"addle's stead","darkshire","defias","vakt","raven hill","silvia valor","silvias svärd","sirra von'indi","ouppklarade angelägenheter"},sec={{t="En vakts klinga",b="Sirra Von'Indi i Darkshire frågar dig om Silvia Valor, vakten vars svärd lämnades kvar. Silvia ägnade sitt liv åt att försvara civila och deras hem. Hennes ande besöker fortfarande gårdar, och Defias har bosatt sig på Addle's Stead, söder om Raven Hill. Sirra ser Defias som en utgångspunkt för att ta reda på vad Silvia ville."},{t="Klingan undersöks",b="På Addle's Stead är Defias den första ledtråden till Silvia Valors ouppklarade angelägenheter. När du återvänder till Sirra Von'Indi i Darkshire beskriver hon Silvia som en skicklig krigare och försvarare, men med en snäv syn på vilka som förtjänade skydd. Sirra kan inte avgöra vad Silvia vill med svärdet, så hon undersöker klingan vidare."}},faq={{q="Vem var Silvia Valor?",a="Silvia Valor var en vakt i Raven Hill som ägnade sitt liv åt att skydda civila och deras hem.",al={"silvia valors bakgrund","vem är silvia","silvia vakt i raven hill"}},{q="Varför besöker Silvias ande gårdar?",a="Silvias ande besöker fortfarande gårdar, och Sirra misstänker att hennes ouppklarade angelägenheter kan ha med Defias på Addle's Stead att göra.",al={"varför är silvia ett spöke","varför hemsöker hon gårdar","silvias ouppklarade angelägenheter"}},{q="Vem frågar om Silvias svärd?",a="Sirra Von'Indi i Darkshire ber dig undersöka Silvia Valors svärd.",al={"vem gav silvias svärd","sirra von'indi svärd","svärdgivare i darkshire"}},{q="Var har Defias bosatt sig?",a="Defias har bosatt sig på Addle's Stead, söder om Raven Hill.",al={"defias addle's stead","var finns defias","raven hill defias"}},{q="Vad tycker Sirra om Silvia?",a="Sirra beskriver Silvia som en skicklig krigare och försvarare, men säger att Silvia hade en snäv syn på vilka som förtjänade skydd.",al={"sirras åsikt om silvia","silvia krigare","hurdan vakt var silvia"}},{q="Vad gör Sirra med svärdet?",a="Sirra undersöker Silvia Valors klinga vidare.",al={"vad händer med klingan","sirra undersöker svärdet","silvias svärd nästa steg"}}},fp="14,162,15.339.0,17.332.1,21.95.0,43.124.0,30.73.0,41.73.0,32.116.0,34.43.0"}
P.entries["quest:79364"] = {n="Eyes on the Sky",s="En lapp varnar för att Razormane utför en ritual i det fördolda i Thousand Needles. Du ombeds söka ett svar på hotet från stormar och stigande tidvatten.",h="En lapp varnar för att Razormane utför en ritual i det fördolda i Thousand Needles.",kw={"elementartrolldom","eyes on the sky","hirzek","prate cloudseer","quilboar","razormane","stigande tidvatten","ritual","stormar","thousand needles"},sec={{t="Ett växande hot",b="Lappen du hittade pekar mot Razormane i Thousand Needles, där en ritual pågår i det fördolda. Rasande stormar och stigande tidvatten väcker farhågor om att kanjonen kan översvämmas. Quilboar kan använda elementarkrafter som de lärt sig av Hirzek, en schaman. Återvänd till dina allierade och tala med Prate Cloudseer."}},faq={{q="Vad står det på lappen?",a="Det står att Razormane har grävt sig in i Thousand Needles för en ritual i det fördolda, medan stormarna rasar och tidvattnet stiger.",al={"lapp i thousand needles","vilken lapp","razormanes lapp"}},{q="Vem är Hirzek?",a="Hirzek är en schaman som lärde quilboar trolldom som förvrider elementen.",al={"hirzek","hirzek schaman","vem är hirzek"}},{q="Vilket hot utgör quilboar?",a="Faran man fruktar är att quilboar skulle kunna använda elementarkrafter för att översvämma kanjonen.",al={"hot från quilboar","razormanes ritual","vad gör quilboar"}},{q="Vem ska jag tala med?",a="Du ombeds tala med Prate Cloudseer i Thousand Needles.",al={"vart gå","vem ska hittas","prate cloudseer"}}},fp="15,160,18.309.0,23.116.0,14.76.0,33.85.0,24.64.0"}
P.entries["quest:79365"] = {n="With Wind Beneath Your Wings",s="En Squall-breakers Potion ger kortvarigt skydd mot stormens element. Du skickas tillbaka till Rau Cliffrunner vid Freewind Post i Thousand Needles.",h="En Squall-breakers Potion ger kortvarigt skydd mot stormens element.",kw={"freewind post","rau cliffrunner","squall-breakers potion","storm","thousand needles"},sec={{t="Tillbaka till Freewind",b="En storm hotar fortfarande dina vänner, och dryckens skydd varar bara en kort stund. Återvänd till Rau Cliffrunner vid Freewind Post i Thousand Needles, där dina vänner väntar och behöver hjälp."}},faq={{q="Vad gör drycken?",a="Squall-breakers Potion skyddar dig mot stormens element under en kort stund.",al={"skydd från dryck","squall-breakers potion"}},{q="Vem ska jag återvända till?",a="Återvänd till Rau Cliffrunner vid Freewind Post i Thousand Needles.",al={"vart ska jag gå","rau cliffrunner"}},{q="Varför ska jag tillbaka?",a="Du skickas tillbaka till dina vänner som behöver hjälp.",al={"vänner som behöver hjälp","återvända till vänner"}}},fp="28,152,16.197.0,24.92.0,23.63.0,20.48.0"}
P.entries["quest:79366"] = {n="Heed My Call",s="Rau Cliffrunner ber dig använda Twisted Totems mot Razormane-ritualen. De korrumperade elementalerna hotar att lämna markerna orenade.",h="Rau Cliffrunner ber dig använda Twisted Totems mot Razormane-ritualen.",kw={"korrumperade elementaler","earthen ring","hör min kallelse","quilboar","rau cliffrunner","razormane","ritual","steam pools","twisted totems"},sec={{t="Vid Steam Pools",b="Med Twisted Totems i handen är du redo att avbryta Razormane-ritualen. Rau Cliffrunner ber dig börja vid Steam Pools i väster, där alla element finns i överflöd. quilboar kommer att göra motstånd. Använd totemen mot ritualen och dess korrumperade elementaler."},{t="Raus tack",b="Rau Cliffrunner frågar om du har några nyheter om stormen. När du återvänder vet han att markens dån har tystnat och tackar dig för att du gjort Earthen Ring stolta."}},faq={{q="Vad vill Rau Cliffrunner att jag ska göra?",a="Rau Cliffrunner ber dig använda Twisted Totems för att avbryta quilboar-ritualen.",al={"rau cliffrunner uppgift","vad vill rau"}},{q="Var ska jag börja?",a="Rau Cliffrunner visar dig vägen till Steam Pools i väster, där alla element finns i överflöd.",al={"var börja","steam pools"}},{q="Vad är Twisted Totems till för?",a="Twisted Totems är avsedda att frammana de korrumperade elementaler som quilboar åkallar.",al={"twisted totems","totemernas syfte"}},{q="Vem utför ritualen?",a="Rau Cliffrunner säger att det är Razormanes ritual och att quilboar åkallar korrumperade elementaler.",al={"vem utför ritualen","razormane-ritualen"}},{q="Varför skulle quilboar göra motstånd?",a="Rau varnar för att quilboar inte kommer att sitta sysslolösa medan du sätter käppar i hjulet för deras planer.",al={"quilboar gör motstånd","varför anfaller de mig"}}},fp="12,142,18.283.0,12.170.1,40.84.0,21.95.0,32.87.0,29.117.0,30.78.0"}
P.entries["quest:794"] = {n="Burning Blade Medallion",s="Zureetha Fargaze skickar unga Horde-initierade in i Burning Blade Covens grotta i Valley of Trials. De möter en dold kultist och söker en mörk relik, Burning Blade Medallion. Dess närvaro tyder på att demonisk korrumpering slår rot nära Horde.",h="Zureetha Fargaze skickar unga Horde-initierade in i Burning Blade Covens grotta i Valley of Trials.",kw={"burning blade","samlingsplats","durotar","medaljong","the den","valley of trials","häxmästare","yarrog baneshadow","zureetha fargaze"},ang={["class:Shaman"]="Som shaman hjälper du Zureetha Fargaze att avslöja den demoniska korrumpering som vanhelgar Durotars jord genom att återta den besudlade reliken.",["class:Warlock"]="Som häxmästare påminner konfrontationen med Yarrog dig om farorna med otillåten demonisk dyrkan bortom de sanktionerade, noggrant dolda pakter som ingås under Thralls styre.",["faction:Horde"]="Som medlem av Horde visar den här sista prövningen att du är redo att ge dig ut i Durotars större vildmarker och försvara den unga nationen.",["race:Orc"]="Som orch visar jakten på Yarrog Baneshadow hur det nya Horde kämpar för att rensa sina träningsområden från den gamla sedens kvardröjande demoniska smitta."},sec={{t="Ett dolt hot i dalen",b="Unga orcher och troll ställs inför prövningar i strid och överlevnad i Valley of Trials, medan ett hot samlas i närheten. Med hjälp av spådomar känner häxmästaren Zureetha Fargaze att de vidriga småtjänarna på de norra klipporna bara är förtruppen till en mörkare närvaro. Djupt inne i en närbelägen grotta har Burning Blade-kulten bildat en dold sammanslutning, där dess anhängare utövar mörka konster och förvarar farliga reliker med demonisk kraft."},{t="Konfrontera Yarrog Baneshadow",b="Yarrog Baneshadow, en orchhäxmästare och agent för Burning Blade, bär på medaljongen. Han väntar på en upphöjd klipphylla djupt inne i den underjordiska hålan, där han befaller felfurstar och brukar mörk magi utom uppsynhåll för Valley-väktarna. Genom att besegra honom och ta medaljongen stör du kultens lokala ledarskap innan dess ritualer sprider sig längre in i Durotar."},{t="Den kvarhängande skuggan",b="Medaljongen bekräftar Zureetha Fargazes farhågor. Samlingen i Valley of Trials har slagits sönder, men reliken visar att Burning Blade är organiserat och målmedvetet. Dess räckvidd sträcker sig bortom initiationsområdet, och det unga Horde står inför större demoniska sammansvärjningar i hela Durotar."}},faq={{q="Var hittar jag Burning Blade Coven?",a="Burning Blade Coven ligger i en grotta bland klipporna norr och väster om The Den i Valley of Trials, omgiven av vidriga imp-liknande småtjänare.",al={"samlingsplatsens grotta","var ligger grottan","burning blade-grottan i valley of trials"}},{q="Vem bär på Burning Blade Medallion?",a="Yarrog Baneshadow bär på medaljongen. Han befinner sig djupt inne i grottan, på en upphöjd klipphylla bortom en grund vattenpöl.",al={"vem släpper medaljongen","yarrog baneshadow","medaljongfiende"}},{q="Vad är Burning Blade?",a="Burning Blade är en förrädisk kult av felförvridna orcher och häxmästare som dyrkar demoniska makter. Dess medlemmar smider ränker mot Thralls nya Horde från gömda hålor och läger.",al={"vilka är burning blade","burning blade-kulten","vad är burning blade"}},{q="Varför är medaljongen så viktig för Zureetha Fargaze?",a="Zureetha Fargaze såg medaljongen genom spådomar. Det kraftfulla föremålet göder kultens mörka ritualer och bevisar att demoniska agenter infiltrerar Valley of Trials.",al={"varför vill zureetha ha den","vad är medaljongen","zureetha fargaze medaljong"}},{q="Utplånas kulten i Durotar när Yarrog besegras?",a="Nej. Yarrog är besegrad och grottan i Valley of Trials renad, men Zureetha varnar för att den här samlingen bara är en liten cell och att Burning Blade har större ambitioner i hela Durotar.",al={"är burning blade förstört","är de borta","efter burning blade-medaljongen"}},{q="Vad händer när jag lämnar in medaljongen?",a="När du har dräpt Yarrog och återfått reliken har du visat ditt värde och är redo att lämna Valley of Trials. Du skickas för att rapportera till Sen'jin Village på Durotars sydkust.",al={"nästa uppdrag","what comes next","efter det här uppdraget"}}},fx={["29893710"]={q="Vad är Burning Blade Medallion till för?",a="Genom sina spådomar identifierade Zureetha Fargaze medaljongen som ett kraftfullt föremål med svart magi, gömt djupt inne i Burning Blade Coven. Den bärs av Yarrog Baneshadow och fungerar som en artefakt med demonisk kraft och en symbol för skuggorådets kvardröjande inflytande alldeles vid Hordens tröskel.",al={"burning blade medallions syfte","vad gör burning blade medallion","varför är medaljongen kraftfull"}}},fp="23,237,29.405.0,29.348.1,20.290.1,40.143.0,44.124.0,26.183.0,54.170.0,53.177.0,44.191.0"}
P.entries["quest:79442"] = {n="The Tempest's Weapons",s="En gammal schaman i Alterac Mountains kan veta hur Stormens öga ska användas. Du tar med artefakten till honom så att han kan skapa något med dess stormmagi.",h="En gammal schaman i Alterac Mountains kan veta hur Stormens öga ska användas.",kw={"alterac mountains","bath'rah","bath'rah the windwatcher","eye of the tempest","schaman","stormelementarmagi","tempestens vapen"},ang={["class:Shaman"]="Som schaman tar du med en kraftfull artefakt med stormelementarmagi till Bath'rah, en gammal schaman med sinne för den magin."},sec={{t="En gammal schaman",b="Efter striden med elementarerna tar du med Eye of the Tempest till Bath'rah the Windwatcher i Alterac Mountains. Han har sinne för stormelementarmagi och ser kraft i artefakten. Bath'rah säger att det var länge sedan han arbetade med något liknande och uppmanar dig att ta väl hand om den."}},faq={{q="Vem är Bath'rah?",a="Bath'rah the Windwatcher är en gammal schaman i Alterac Mountains med sinne för stormelementarmagi.",al={"bath'rah the windwatcher","gammal schaman","vem är bathrah"}},{q="Vad är Eye of the Tempest?",a="Eye of the Tempest är en kraftfull artefakt med koppling till stormelementarmagi.",al={"tempestens öga","ögonartefakt","vad är ögat"}},{q="Varför ta med Eye till Bath'rah?",a="Bath'rah kanske kan skapa något med Eye of the Tempest eftersom han förstår sig på stormelementarmagi.",al={"varför bathrah","tempestens vapen-uppdrag","vart ta ögat"}},{q="Vad säger Bath'rah om artefakten?",a="Bath'rah kallar Eye of the Tempest kraftfull och säger att det var länge sedan han skapade något med en liknande artefakt.",al={"bath'rahs reaktion","vad säger han","ögats slutförande"}}},fp="21,147,13.305.0,16.105.0,31.84.0,30.113.0,42.112.0"}
P.entries["quest:79535"] = {n="Basilisks: Should Petrification be Feared?",s="En bibliotekarie ber dig hämta magiska verk som kan berika bibliotekets samling. Dina fynd hjälper till att utöka dess kunskap.",h="En bibliotekarie ber dig hämta magiska verk som kan berika bibliotekets samling.",kw={"basilisker","samling","kunskap","bibliotek","magiska verk","förstening"},sec={{t="En växande samling",b="Bibliotekarien tackar dig för att du har utökat samlingen. Dina insatser tillför biblioteket ny kunskap, och fler magiska verk kan vara välkomna där."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien välkomnar magiska verk som kan berika samlingen.",al={"biblioteksuppdrag","vad ska jag hämta"}},{q="Varför vill bibliotekarien ha magiska verk?",a="Bibliotekarien säger att de kan berika biblioteket och utöka dess kunskap.",al={"varför böcker","vad är de till för"}},{q="Vad händer när jag lämnar in något?",a="Bibliotekarien tackar dig och säger att dina insatser utökar bibliotekets kunskap.",al={"samlingens utveckling","vad lade jag till"}}},fp="42,133,20.151.0,29.71.0,29.73.0,36.79.0"}
P.entries["quest:79624"] = {n="Anyone Can Cook",s="Ett oläsligt recept verkar beskriva en kötträtt, och du misstänker att det är skrivet av en ogre. Hitta en ogre som kan läsa det.",h="Ett oläsligt recept verkar beskriva en kötträtt, och du misstänker att det är skrivet av en ogre.",kw={"anyone can cook","oläsligt recept","kötträtt","ogre","recept","skonk","översättning"},ang={["profession:Cooking"]="Som kock har du anledning att undra vilken sorts kötträtt det oläsliga receptet beskriver."},sec={{t="Ett märkligt recept",b="Receptet är skrivet på ett språk du inte kan läsa, och det verkar handla om en kötträtt. Ogrernas språk är din bästa gissning, med tanke på varifrån det kom och vad det beskriver. Du hoppas hitta en ogre som kan översätta det."}},faq={{q="Vad är det ett recept på?",a="Det verkar vara ett recept på någon sorts kötträtt.",al={"receptets syfte","vilken maträtt","köttrecept"}},{q="Vilket språk är receptet skrivet på?",a="Du förstår inte språket. Ogrernas språk är din bästa gissning.",al={"receptets språk","vilken skrift","kan inte läsa receptet"}},{q="Vem kan läsa receptet?",a="Du letar efter en ogre som kan läsa det.",al={"översätta receptet","vem kan läsa det","ogre som kan läsa"}},{q="Vem är Skonk?",a="Skonk är en ogre som lyssnar efter receptet.",al={"skonk","vem är skonk","ogren skonk"}}},fp="15,112,16.213.0,23.44.0,39.60.0,24.44.0,13.49.0"}
P.entries["quest:79677"] = {n="A Quick Grocery Run",s="Skonk ber dig samla ingredienser till en maträtt i Arathi Highlands. Han lärde sig laga mat efter att andra ogrer hånat hans storlek och stridsförmåga.",h="Skonk ber dig samla ingredienser till en maträtt i Arathi Highlands.",kw={"arathi highlands","matlagning","maträtt","ingredienser","ogre","skonk","retande"},ang={["profession:Cooking"]="Som kock kan du hjälpa Skonk att samla ingredienser till en maträtt som han kan laga."},sec={{t="Skonks ingredienser",b="Skonk, en ogre i Arathi Highlands, behöver ingredienser till en maträtt som han kan laga. Andra ogrer skrattade åt hans storlek och kallade honom svag, så han började laga mat. Du samlar ingredienserna och tar dem till honom."}},faq={{q="Vem är Skonk?",a="Skonk är en ogre som lärde sig laga mat efter att andra ogrer hånat hans storlek och stridsförmåga.",al={"skonk","vem är skonk"}},{q="Varför lagar Skonk mat?",a="Andra ogrer skrattade åt Skonk för att han var mindre och kallade honom svag, så han lärde sig laga mat i stället för att slåss.",al={"varför laga mat","skonk matlagning"}},{q="Vad behöver Skonk?",a="Skonk behöver ingredienser till en maträtt som han kan laga.",al={"ingredienser","vilka ingredienser"}},{q="Vart ska jag ta ingredienserna?",a="Ta ingredienserna till Skonk i Arathi Highlands.",al={"var är skonk","lämna ingredienser"}}},fp="19,143,19.214.0,13.92.0,20.107.0,21.47.0,33.51.0"}
P.entries["quest:79678"] = {n="Taste Testing",s="Skonk ber dig smaka på en ny rätt som lagats över öppen eld. Provsmakningen är hans sätt att dela den med en ny vän som har hjälpt honom.",h="Skonk ber dig smaka på en ny rätt som lagats över öppen eld.",kw={"rätt","eld","mat","recept","skonk","provsmakning","smakprov"},sec={{t="En ny rätt",b="Skonk har en ny rätt klar över elden och vill dela den med dig. Efter alla tjänster du har gjort honom tycker han att du också ska få smaka. Receptet är redo att provas."}},faq={{q="Vem är Skonk?",a="Skonk lagar en ny rätt och bjuder in dig att smaka på den.",al={"skonk","vem är skonk"}},{q="Vad vill Skonk att jag ska göra?",a="Skonk vill att du provar receptet tillsammans med honom.",al={"provsmakning","vad vill skonk"}},{q="Varför delar Skonk med sig av rätten?",a="Skonk säger att du har gjort honom många tjänster, så han vill att du ska prova hans nya rätt.",al={"varför mat","varför dela"}},{q="Vad tycker Skonk om receptet?",a="Efter provsmakningen säger Skonk att receptet är utsökt.",al={"är den god","smaka på receptet"}}},fp="13,131,10.189.0,13.55.0,30.45.0,30.78.0,36.54.0"}
P.entries["quest:79947"] = {n="Geomancy: The Stone-Cold Truth",s="En bibliotekarie söker magiska verk till biblioteket i Ironforge. Ditt bidrag kan hjälpa till att utöka dess kunskap.",h="En bibliotekarie söker magiska verk till biblioteket i Ironforge.",kw={"samling","geomanti","ironforge","bibliotek","magiska verk","stenkall sanning"},sec={{t="En växande samling",b="Bibliotekarien i Ironforge ber dig ta med magiska verk som kan gynna Library. Samlingen växer tack vare dina insatser, och bibliotekarien välkomnar fler upptäckter."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien ber dig ta med magiska verk som kan gynna Library i Ironforge.",al={"vad vill de ha","förfrågan från biblioteket"}},{q="Varifrån kommer förfrågan?",a="Förfrågan kommer från Library i Ironforge.",al={"var ligger biblioteket","biblioteket i ironforge"}},{q="Varför ta med magiska verk?",a="Bibliotekarien säger att Librarys kunskap utökas tack vare dina insatser.",al={"varför magiska böcker","vad ska de användas till"}}},fp="30,110,20.179.0,29.90.0,27.48.0,24.72.0"}
P.entries["quest:79948"] = {n="Defensive Magics 101",s="Biblioteket i Ironforge söker magiska verk till sin samling. Du kan bredda dess kunskap genom att ta med verk som kan berika hyllorna.",h="Biblioteket i Ironforge söker magiska verk till sin samling.",kw={"samling","försvarsmagi","ironforge","kunskap","bibliotek","magiska verk"},sec={{t="En växande samling",b="Bibliotekets samling kan växa tack vare dig. Ta med magiska verk som kan berika hyllorna till dess föreståndare, så växer bibliotekets kunskap."}},faq={{q="Vad behöver biblioteket?",a="Biblioteket söker magiska verk som kan berika dess samling.",al={"bibliotekets behov","vad man ska ta med","magiböcker"}},{q="Varifrån kommer önskemålet?",a="Önskemålet kommer från biblioteket i Ironforge.",al={"vem som önskar det","bibliotekets önskemål","biblioteket i ironforge"}},{q="Varför ta med magiska verk?",a="Magiska verk som tas med till biblioteket utökar dess kunskap.",al={"varför samla på magi","vad det hjälper med","bibliotekets samling"}}},fp="20,150,20.153.0,27.66.0,27.48.0,24.58.0"}
P.entries["quest:79949"] = {n="A Web of Lies: Debunking Myths and Legends",s="En bibliotekarie söker magiska verk för att utöka bibliotekets samling. Du kan ta med skrifter som kan berika hyllorna.",h="En bibliotekarie söker magiska verk för att utöka bibliotekets samling.",kw={"böcker","samling","ironforge","kunskap","bibliotekarie","bibliotek","magiska verk"},sec={{t="En växande samling",b="Bibliotekarien på biblioteket i Ironforge välkomnar verk till samlingen. Magiska skrifter kan utöka bibliotekets kunskap, och dina upptäckter kan hjälpa den att växa."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien söker magiska verk som kan berika samlingen.",al={"vad behöver bibliotekarien","bibliotekets önskemål","vad ska tas till biblioteket"}},{q="Var ska jag lämna böckerna?",a="Ta de magiska verken till bibliotekarien på biblioteket i Ironforge.",al={"var ligger biblioteket","biblioteket i ironforge","var ska magiska verk lämnas"}},{q="Varför samla på magiska verk?",a="Bibliotekarien säger att samlingen utökar bibliotekets kunskap.",al={"varför ta med böcker","vad ska samlingen användas till","bibliotekets syfte"}}},fp="42,122,20.178.0,29.68.0,31.69.0,26.68.0"}
P.entries["quest:79950"] = {n="Demons and You",s="En bibliotekarie ber dig lägga till ett magiskt verk i samlingen. Ditt arbete bidrar till bibliotekets kunskap.",h="En bibliotekarie ber dig lägga till ett magiskt verk i samlingen.",kw={"samling","demons and you","ironforge","kunskap","bibliotek","magiska verk"},sec={{t="En bibliotekssamling",b="En bibliotekarie i biblioteket i Ironforge ber dig bidra med ett magiskt verk. Tack vare dig växer samlingen, och bibliotekarien välkomnar fler verk som kan vara till nytta för biblioteket."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien ber dig ta med ett magiskt verk till bibliotekets samling.",al={"vad ska jag ta med","bibliotekets önskemål","demons and you-uppdraget"}},{q="Var finns samlingen?",a="Samlingen finns i biblioteket i Ironforge.",al={"var ligger det","bibliotekets plats","biblioteket i ironforge"}},{q="Varför ta med magiska verk till biblioteket?",a="Bibliotekarien säger att ditt arbete utökar bibliotekets kunskap.",al={"varför skänka böcker","vad är syftet","bibliotekets syfte"}}},fp="14,118,20.188.0,34.81.0,24.46.0,39.62.0"}
P.entries["quest:79951"] = {n="Mummies: A Guide to the Unsavory Undead",s="En bibliotekarie söker magiska verk till samlingen om mumier och obehagliga odöda. Ditt bidrag hjälper till att utöka bibliotekets kunskap.",h="En bibliotekarie söker magiska verk till samlingen om mumier och obehagliga odöda.",kw={"böcker","samling","bibliotek","magiska verk","mumier","obehagliga odöda"},sec={{t="En växande samling",b="Bibliotekets samling är beroende av verk som besökare tar med sig. Du ombeds bidra med något om mumier och obehagliga odöda, och fler magiska böcker kan också vara till nytta. Varje sådant verk kan utöka bibliotekets kunskap."}},faq={{q="Vad samlar bibliotekarien på?",a="Bibliotekarien söker verk om mumier och obehagliga odöda, samt andra magiska böcker som kan vara till nytta för biblioteket.",al={"mummieböcker","guide till odöda","vilka böcker vill de ha"}},{q="Varför ta med en bok till biblioteket?",a="Verk som tas med till bibliotekarien utökar bibliotekets kunskap.",al={"varför ge bort en bok","vad får biblioteket ut av det","hjälpa biblioteket"}},{q="Kan jag ta med andra magiska böcker?",a="Ja. Bibliotekarien välkomnar andra magiska verk som kan vara till nytta för biblioteket.",al={"andra magiska böcker","fler magiska verk","vad mer kan jag ta med"}}},fp="39,144,20.229.0,33.127.0,32.64.0,32.79.0"}
P.entries["quest:79952"] = {n="RwlRwlRwlRwl!",s="En förvaltare vid Library i Ironforge välkomnar magiska verk till samlingen. Dina bidrag hjälper kunskapen där att växa.",h="En förvaltare vid Library i Ironforge välkomnar magiska verk till samlingen.",kw={"samling","ironforge","kunskap","bibliotek","magiska verk","rwl"},sec={{t="En växande samling",b="Förvaltaren tackar dig när magiska verk blir en del av Library i Ironforge. Varje tillskott breddar kunskapen där. Förvaltaren välkomnar fler verk som kan gynna samlingen."}},faq={{q="Vad önskar bibliotekets förvaltare?",a="Förvaltaren välkomnar magiska verk som kan gynna samlingen på Library.",al={"biblioteksböcker","magiska verk","vad man ska ta med"}},{q="Var finns den här samlingen?",a="Samlingen tillhör Library i Ironforge.",al={"bibliotekets plats","ironforge bibliotek","var ligger biblioteket"}},{q="Varför ta med magiska verk?",a="Dina bidrag hjälper bibliotekets kunskap att växa.",al={"varför böcker","hjälpa biblioteket","vad är poängen"}}},fp="13,123,20.182.0,34.76.0,25.51.0,24.53.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job är ett uppdrag där du ska hitta en reservgömma högt uppe på en bergssida. Den förbereddes för en snabb flykt och gömdes nära en naturskön utsiktsplats vid klippkanten. Förrådet skyddas av uppfinningsrikt dvärghantverk.",h="Wet Job är ett uppdrag där du ska hitta en reservgömma högt uppe på en bergssida.",kw={"dvärgteknik","örnnäste","budväska","bergssida","pergament","reservgömma","förnödenheter","wet job"},ang={["class:Rogue"]="Att gömma undan nödförråd för en hastig flykt är självklart för dem som lever i skuggorna.",["profession:Engineering"]="Gömman visar prov på dvärgarnas uppfinningsrika teknik och fungerar som ett pålitligt nödförråd, dolt i karg terräng.",["race:Dwarf"]="Dvärghantverket hyllas när förrådet hämtas fram, och visar hur hållbart deras bergshantverk är."},sec={{t="En Emergency Cache",b="Den som arbetar under farliga förhållanden vet att man aldrig ska ge sig av utan en reservplan. I Wet Job ska du hitta ett förråd som gömts undan bland karga höjder. Det ligger redo som en nödfallsåtgärd om en snabb flykt skulle bli nödvändig, så att du kan hämta förnödenheterna om planerna går om intet."},{t="Örnnästet",b="Anvisningarna leder rakt mot en naturskön utsiktsplats i bergen, poetiskt beskriven som huggen ur tidens vattenfall. Högt uppe på klippväggen ligger det som kallas örnnästet. Där vilar en väderbiten budväska, delvis begravd i jorden. Den skyddar proviant och pergament mot väder och vind med pålitligt dvärghantverk."}},faq={{q="Vad handlar uppdraget Wet Job om?",a="Wet Job är ett uppdrag där du ska hämta en gömd nödfallsgömma som ligger undanstoppad i terrängen. Den som förberedde gömman såg till att det fanns förnödenheter om en snabb flykt skulle bli nödvändig.",al={"vad är wet job","uppdraget wet job","vad är wet job för ett uppdrag"}},{q="Vem lämnade reservförrådet?",a="Gömman placerades där av någon som förberedde ett nödförråd ifall en snabb flykt skulle bli nödvändig. När du hämtar det hittar du en budväska med pergament och förnödenheter, tillverkade med imponerande dvärgteknik.",al={"vem lämnade gömman","vems förnödenheter är det här","vem gömde reservförrådet"}},{q="Var är gömman dold?",a="Ledtråden pekar mot en naturskön bergssida, beskriven som huggen ur tidens vattenfall. Sökandet leder särskilt mot ett örnnäste högt uppe på klippväggen, där en budväska sticker upp ur jorden.",al={"var finns gömman","wet job plats","örnnästets plats"}},{q="Vad finns i budväskan?",a="När du gräver fram den begravda budväskan hittar du viktiga förnödenheter och ett undanstoppat pergament, skyddade av anmärkningsvärt tåligt dvärghantverk.",al={"vad finns i gömman","föremål i wet job","vad hittar man"}},{q="Varför heter uppdraget Wet Job?",a="Titeln brukar ofta syfta på hemliga eller kladdiga fältuppdrag, men här har den en direkt koppling till landmärkena i bergen, omgivna av dimma, tidens vattenfall och fuktig jord som döljer väskan.",al={"varför heter det wet job","betydelsen av namnet wet job"}},{q="Hur kommer dvärgtekniken in i bilden?",a="När du gräver fram och öppnar gömman hyllas förrådets konstruktion och pålitlighet som ett underverk av dvärgteknik, byggt för att klara att ligga begravt utomhus.",al={"kopplingen till dvärgteknik","är det här dvärgiskt"}}},fp="7,154,18.194.0,16.273.0,32.80.0,27.162.0,26.163.0,35.84.0,31.103.0,36.101.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist kretsar kring ett gåtfullt brev i en verktygslåda vid en dimhöljd utsiktsplats högt över marken. Brevet avslöjar att en ensam vaktpost vakar över en väderbiten barrikad av lojalitet mot Old Kingdoms och Eagle and Fist. Lägerelden har nyligen fått nytt bränsle, men vakten gav sig av i all hast.",h="Eagle's Fist kretsar kring ett gåtfullt brev i en verktygslåda vid en dimhöljd utsiktsplats högt över marken.",kw={"barrikad","lägereld","eagle's fist","vikt brev","utkikspost","old kingdoms","fallskärmsglykare","verktygslåda"},ang={["profession:Engineering"]="I sin anteckning pekar vakten ut platsen som en idealisk startpunkt för en fallskärmsglykare. Det fångar intresset hos ingenjörer som uppskattar flygspaning och mekanisk flygning."},sec={{t="En dold utsiktsplats",b="Undangömt i en oansenlig verktygslåda vid en naturskön utsiktsplats ligger ett noggrant vikt brev. Författaren begrundar den höga utsiktens dominerande läge och nämner hur man därifrån kan fatta besluten eller sväva över landskapet med en fallskärmsglykare. Den ensliga posteringen, fuktad av dimmigt vattenstänk, bjuder på en otrolig utsikt över historiska marker."},{t="Lojalitet mot Old Kingdoms",b="Brevets skribent bekänner en djup och orubblig lojalitet till ”Eagle and Fist” och påpekar att man bäst tjänar saken genom att hålla ett visst avstånd. Skribenten medger att den lokala barrikaden har förfallit, liksom Old Kingdoms som den en gång skyddade från faror, men den trogna vakten lovar att aldrig helt överge sin post."},{t="En hastig avfärd",b="Den som bemannade utsiktsplatsen gav sig av i all hast. Besökare som hittar posteringen upptäcker en lägereld som nyligen fått färsk ved, men vakten är spårlöst försvunnen. Kvar finns bara verktygen, de glödande kolen och det gåtfulla brevet."}},faq={{q="Vad är Eagle's Fist?",a="Eagle's Fist är ett möte kring en dold verktygslåda med ett noggrant vikt brev, vid en dimhöljd utsiktsplats med vy över en gammal barrikad. Där finns lägret efter en mystisk spejare som nyligen flydde.",al={"vad är eagle's fist","eagle's fist uppdrag","vad är det här för uppdrag"}},{q="Vem skrev brevet i verktygslådan?",a="Författaren är en oidentifierad spejare eller vaktpost som är hängiven Old Kingdoms och en grupp eller trohet känd som Eagle and Fist. Personen håller ensam vakt vid den förfallna barrikaden.",al={"vem skrev anteckningen","vem lämnade brevet","författaren till brevet i verktygslådan"}},{q="Vad syftar ”Eagle and Fist” på?",a="Brevet nämner lojalitet till ”Eagle and Fist”, som bäst tjänas genom att hålla avstånd. Den exakta organisationen förblir en gåta, men den är knuten till försvaret av det som återstår av Old Kingdoms.",al={"vad är eagle and fist","betydelsen av eagle and fist","vem är eagle and fist"}},{q="Varför övergavs lägret?",a="Spejaren gav sig av hastigt och lämnade en lägereld som nyligen fått färsk ved. Ingen vet vart spejaren tog vägen, men platsen beskrivs som perfekt för att ge sig av med en fallskärmsglykare.",al={"vart tog spejaren vägen","varför gav de sig av","vem lade ved på lägerelden"}},{q="Vilken barrikad försvaras?",a="Författaren beklagar att barrikaden har sett bättre dagar och jämför dess slitna skick med mänsklighetens fallna Old Kingdoms, som den en gång försvarade. Ändå svär skribenten att aldrig överge bevakningen.",al={"vilken barrikad","vilka old kingdoms","barrikadens historia"}},{q="Vad är det här för utkikspost?",a="Utsiktsplatsen bjuder på en otrolig panoramavy och fuktig luft från vattenstänk. Det tyder på en hög klippa eller utsiktsplats nära ett enormt vattenfall eller en forsande flod.",al={"var ligger det här","varför är det vattenstänk här","eagle's fist plats"}}},fp="12,190,14.236.0,27.295.0,17.175.1,21.129.0,42.145.0,40.167.0,30.161.0,33.151.0,34.147.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place markerar platsen för en nyligen övergiven lägerplats, vars enda besökare försvann för bara ett ögonblick sedan. En sönderriven lapp avslöjar att den mystiske skribenten har tagit sitt arbete under jorden för att hålla det borta från fel händer.",h="This Must Be The Place markerar platsen för en nyligen övergiven lägerplats, vars enda besökare försvann för...",kw={"övergiven lägerplats","utrustningspackning","gömställe","sovsäck","this must be the place","sönderriven lapp","under jorden"},sec={{t="En hastig avfärd",b="En hastig avfärd har ägt rum på den här avskilda platsen, där en okänd resenär nyligen slog läger. Kvar finns bara en sovsäck som inte spänts fast ordentligt och rullas ut under fötterna, tungt kanvastyg hoprullat över diverse utrustning och en liten pappersbit, precis stor nog för ett hastigt avskedsmeddelande. Den som slog läger här försvann ögonblick innan någon hann ifatt."},{t="Ner under jorden",b="Meddelandet som lämnats kvar avslöjar att skribenten bestämde sig för att åter ta sitt arbete under jorden, så att det inte skulle hamna i fel händer. Det är fortfarande oklart om lappen är ett sista farväl eller en diskret ledtråd till forskarens nästa hemliga tillflyktsort. Den övergivna utrustningen ligger kvar för den som råkade hitta platsen."}},faq={{q="Vem skrev den sönderrivna lappen?",a="Lappen avslöjar inte vem som skrev den. Skribenten förklarar bara att hen har bestämt sig för att ta sitt arbete under jorden för att hindra att det hamnar i fel händer. En övergiven lägerplats och utrustning finns kvar.",al={"vem skrev lappen","lappens skribent","vem lämnade meddelandet"}},{q="Vilket arbete tas under jorden?",a="Vad skribentens arbete går ut på avslöjas inte. Hen nämner att arbetet åter ska tas under jorden, enbart för att skydda forskningen eller skapelserna från ospecificerade fiender som kan missbruka dem.",al={"vilket arbete under jorden","varför ta arbetet under jorden","vilket arbete"}},{q="Vart tog lägerplatsens besökare vägen?",a="Den som vistades här packade hastigt ihop och smet iväg bara ögonblick innan någon anlände. Målet är okänt, men lappen antyder att hen kan ha flyttat till ett annat avskilt gömställe.",al={"missade jag dem","vart tog de vägen","var är skribenten"}},{q="Vad lämnades kvar på lägerplatsen?",a="Resenären lämnade kvar en sovsäck som inte spänts fast ordentligt och rullas ut på marken, tungt kanvastyg hoprullat över diverse utrustning och en övergiven packning med blandad utrustning.",al={"vad lämnades kvar","förnödenheter på lägerplatsen","vad fanns i packningen"}},{q="Är det här en ledtråd till ett annat gömställe?",a="Den sönderrivna pappersbiten gör det oklart om det är avskedsord eller avsiktliga smulor som leder till skribentens nästa underjordiska fristad.",al={"finns det ett annat gömställe","nästa lägerplats","fler ledtrådar"}},{q="Vilka är de ”fel händer” som nämns i lappen?",a="Lappen säger inte vilka de ”fel händerna” är. Skribenten fruktade uppenbarligen förföljelse eller stöld och gav sig därför hastigt av innan hens arbete kunde äventyras.",al={"vilka är de fel händerna","vad betyder fel händer","vem förföljer skribenten"}}},fp="22,180,17.289.0,20.253.1,24.175.0,37.140.0,37.143.0,37.175.0,42.106.0,48.127.0"}
P.entries["quest:79980"] = {n="Scramble",s="Scramble är en gömd skattjakt där äventyrare följer koordinater nedför en brant klippsida. Med hjälp av en asätaranteckning gräver resenärer fram en begravd budväska med överlevnadsutrustning och ett smutsigt pergament.",h="Scramble är en gömd skattjakt där äventyrare följer koordinater nedför en brant klippsida.",kw={"förråd","klippsida","budväska","pergament","scramble","gömställe","förnödenheter"},sec={{t="Den nordliga leden",b="Ett kryptiskt meddelande visar vägen till ett gömt förråd för den som är tillräckligt klurig för att hitta det. Skribenten blandar avslappnad uppmuntran med exakta anvisningar: gå hundra steg rakt norrut nedför en förrädisk klippsida för att hitta förnödenheter som lämnats åt en resenär."},{t="Budväskan grävs fram",b="När du följer anvisningarna nedför den branta klippväggen hittar du en begravd budväska. I väskan, som grävts fram ur jorden, finns praktisk överlevnadsutrustning och ännu ett smutsigt pergament instucket bland sakerna. Det tyder på att den här korta skattjakten är en del av en större led."}},faq={{q="Vad är uppdraget Scramble?",a="Scramble är ett uppdrag där en äventyrare följer en skattjakt till ett gömt förråd med överlevnadsutrustning. En skriftlig anteckning säger åt den som hittar den att gå norrut nedför en förrädisk klippa och hämta nedgrävda förnödenheter.",al={"uppdraget scramble","vad är scramble","scramble-förråd"}},{q="Var finns det gömda förrådet?",a="Enligt anvisningarna ligger förrådet nedgrävt ungefär hundra steg rakt norrut, nedför en brant klippsida. Du måste gå försiktigt för att nå dit utan att tumla nedför klippväggen.",al={"var finns förrådet","hur hittar man förrådet","förrådets plats"}},{q="Vem lämnade anteckningen och förrådet?",a="Författarens exakta identitet nämns inte. Skribenten lämnade informella, praktiska anteckningar så att en upptäcktsresande kunde hitta sina nödförnödenheter. Förrådet fanns kvar orört.",al={"vem skrev scramble-anteckningen","vem lämnade förrådet","scrambles författare"}},{q="Vad finns i det nedgrävda förrådet?",a="När du gräver fram förrådet hittar du en begravd budväska med överlevnadsutrustning och ett smutsigt pergament instucket bland sakerna.",al={"scramble-belöningar","vad finns i scramble-förrådet","väskans innehåll"}},{q="Vad är det smutsiga pergamentet som hittas med förnödenheterna?",a="Det smutsiga pergamentet ligger instucket i den begravda budväskan bland förnödenheterna. Du hittar det när väskan dras upp ur marken.",al={"smutsigt pergament scramble","vad står det på pergamentet","scramble-anteckning"}},{q="Vilka faror finns på vägen till förrådet?",a="Den största faran är att ta sig nedför den branta klippsidan norrut. Ett felsteg kan leda till brutna fotleder eller allvarliga fall.",al={"faror med scramble","klippan vid scramble","scrambles klippsida"}}},fp="8,163,19.246.0,28.196.1,27.156.0,34.127.0,32.143.0,32.89.0,52.133.0,48.99.0"}
P.entries["quest:8"] = {n="A Rogue's Deal",s="En till synes enkel tjänst åt Calvin Montague i Deathknell skickar en resenär till Gallows' End Tavern i Brill. Uppdraget går ut på att leverera ett mystiskt, oadresserat meddelande till Innkeeper Renee, under förevändning att det rör sig om en vanlig kurirleverans.",h="En till synes enkel tjänst åt Calvin Montague i Deathknell skickar en resenär till Gallows' End Tavern i...",kw={"brill","calvin montague","deathknell","gallows' end","innkeeper renee","nondescript letter","rogue","tirisfal glades"},ang={["class:Rogue"]="Calvin Montagues privata kuriruppdrag ger en inblick i de informella affärer som pågår kring Deathknell och Brill.",["faction:Horde"]="Leveransen går raka vägen till Brill och visar nyanlända allierade regionens centrum för Forsakens administration och vila i Tirisfal.",["race:Undead"]="För nyligen uppståndna Forsaken markerar det här uppdraget deras allra första resa bort från tryggheten på Deathknells kyrkogård och mot Brills livliga nav."},sec={{t="En vänlig kurir",b="Calvin Montague sitter och slappar bland Deathknells dystra gravar och ruinlika kapell. Han framstår som en utmattad kämpe, tyngd av alla Scourge-zombier och spindlar som krälar omkring. Han säger sig bara behöva hjälp med att leverera ett meddelande till Brill och lämnar över ett omärkt brev till förbipasserande äventyrare. Hans lättsamma sätt och löfte om generös betalning får uppgiften att verka som en harmlös tjänst, avsedd att visa nyvakna Forsaken vägen till regionens huvudort."},{t="Gallows' End Tavern",b="Vägen går österut genom Tirisfal Glades fördärvade träd och förbi Cold Hearth Manor, fram till bosättningen Brill. Bakom disken på den lokala tavernan hälsar Innkeeper Renee först nykomlingar med en oroande solig uppsyn och ömmar för sina gästers trivsel. Men när hon får Montagues brev bryter hennes gästfrihet genast samman. Hon slutar med sina påklistrade artigheter, låtsas ha fått ett meddelande från en älskad mor, skäller ut kuriren för att snoka och kräver att de köper något eller går. När du återvänder till Calvin väntar ännu en överraskning: i stället för att betala som utlovat utmanar han kuriren på duell."}},faq={{q="Vem är Calvin Montague?",a="Calvin Montague är en rogue i Deathknell som ber nyvakna resenärer att bära ett brev till Innkeeper Renee i Brill. Han framställer det som en enkel tjänst och lovar bra betalt.",al={"calvin montague","vem ger uppdraget a rogue's deal","uppdragsgivare"}},{q="Vad står det i Nondescript Letter?",a="Brevets exakta innehåll finns inte nedtecknat. Calvin ger kuriren ett omärkt meddelande att leverera till Innkeeper Renee i Brill.",al={"innehållet i nondescript letter","vad står det i brevet","calvins brev"}},{q="Varför beter sig Innkeeper Renee så märkligt?",a="Renee sköter tavernan i Brill och hävdar att hennes korrespondens är privat. Du får se hur hon reagerar på leveransen genom att ge henne Montagues brev.",al={"innkeeper renees attityd","varför är renee falsk","renees ursäkt om sin mor"}},{q="Betalar Calvin Montague verkligen för leveransen?",a="Montague lovar bra betalt för leveransen. När brevet når henne erbjuder Renee mat eller vatten. Återvänd sedan till Calvin för att fortsätta uppgörelsen om den utlovade betalningen.",al={"lurade calvin mig","var är mina pengar","montagues belöning"}},{q="Var ligger Brill?",a="Brill ligger nordost om Deathknell. Följ huvudvägen österut från startdalen, sväng åt höger efter Cold Hearth Manor och korsa en täckt bro in till bosättningen.",al={"hur tar jag mig till brill","vägen till brill","vägbeskrivning till brill"}},{q="Vad händer efter att brevet lämnats till Renee?",a="Fortsättningen är ännu ett uppdrag med namnet ”A Rogue's Deal”. Återvänd till Calvin Montague i Deathknell för att fortsätta dina mellanhavanden med honom.",al={"nästa uppdrag","fortsättningen på a rogue's deal","vad gör jag efter renee"}}},fx={df83fdd9={q="Varför vill Calvin Montague att brevet levereras?",a="Calvin Montague säger att han har kämpat mot mer än sin beskärda del av tanklösa zombier och spindlar kring Deathknell och bara behöver någon som uträttar ett ärende åt honom. I stället för att själv gå hela vägen uppför vägen till Brill erbjuder han sig att betala dig bra för att lämna hans förseglade, intetsägande brev direkt till Innkeeper Renee.",al={"calvin montagues motiv","varför skicka brevet till renee","varför vill calvin att detta görs"}}},fp="14,136,18.299.0,23.469.1,23.175.0,38.112.0,40.147.0,51.194.0,23.161.0,46.100.1"}
P.entries["quest:80"] = {n="The Legend of Stalvan",s="Det här avgörande steget i utredningen av Stalvan Mistmantle för fram bevisen inför Darkshires myndigheter. Med en blodfläckad dagbokssida i handen skickar Commander Althea Ebonlocke utredaren till Clerk Daltry för att en gång för alla fastställa handstilen.",h="Det här avgörande steget i utredningen av Stalvan Mistmantle för fram bevisen inför Darkshires myndigheter.",kw={"althea ebonlocke","blodfläckad dagbokssida","clerk daltry","darkshire","duskwood","stalvans legend","night watch","stalvan mistmantle"},ang={["faction:Alliance"]="Utredningen visar hur gränsstäder som Darkshire försöker upprätthålla lag, ordning och civila register trots att de belägras av odöda och skuggvarelser.",["race:Human"]="För människorna i de södra kungadömena berör det här uppdraget sammanlänkade tragedier som knyter samman Stormwinds adel, Duskwoods nybyggare och de utspridda godsen i Elwynn."},sec={{t="Snaran dras åt",b="Efter att ha följt spåret av dagbokssidor som återfunnits i Duskwood och de omgivande mänskliga områdena har Night Watch äntligen bevis som verkar fälla den svårfångade läraren Stalvan Mistmantle. Commander Althea Ebonlocke har misstänkt mannen en tid, men för att kunna döma honom krävs fullständig visshet. En enda blodfläckad sida räcker inte för att fälla honom förrän det utan tvivel har bevisats att de makabra anteckningarna är skrivna av Stalvan själv."},{t="Skrivkunnig blick",b="För att överbrygga klyftan mellan misstanke och visshet förlitar sig Night Watch på Darkshires stadsarkivarie, Clerk Daltry. Daltry har ansvarat för stadens register i åratal och granskat otaliga liggare och namnteckningar, vilket gör honom till en auktoritet på handstilsidentifiering. Genom att jämföra den nyfunna dagbokssidan direkt med Stalvans äldre namnteckningar i stadens handlingar får man den sista, obestridliga bekräftelsen på hans mörka förfall och skuld."}},faq={{q="Varför behöver Commander Ebonlocke Clerk Daltrys bekräftelse?",a="Commander Althea Ebonlocke vill försäkra sig om att Stalvans skuld är fastställd bortom allt tvivel innan hon agerar. Clerk Daltry sköter Darkshires stadsregister och har lång erfarenhet av att granska namnteckningar. Därför är han särskilt lämpad att avgöra om den blodfläckade sidan stämmer med Stalvans handstil i stadens handlingar.",al={"varför daltry","varför kontrollera handstilen","clerk daltrys uppgift"}},{q="Var passar det här steget in i berättelsen om Stalvan?",a="Det här är det elfte kapitlet i den långa utredningen. Det utspelar sig direkt efter att den blodfläckade dagbokssidan återfunnits och är den sista bekräftelsen av bevisen innan Night Watch vidtar avgörande åtgärder mot Stalvan.",al={"vilken del är det här","hur långt in i kedjan","ordning på stalvans uppdragskedja"}},{q="Var finns Clerk Daltry i Darkshire?",a="Clerk Daltry finns i Darkshires stadshus, där han sköter samhällets lokala handlingar och fastighetsregister.",al={"daltrys plats","var finns clerk daltry","hitta daltry"}},{q="Vilka bevis tog utredaren med sig till Darkshire?",a="Utredaren bär på en blodfläckad dagbokssida som återfanns under den pågående sökningen efter Stalvan. Texten beskriver hans mörka tankar och upplevelser, men handstilen måste kontrolleras mot officiella handlingar.",al={"vilka är bevisen","vilken sida är det här","blodfläckad sidas bakgrund"}},{q="Bekräftar Clerk Daltry att handstilen är Stalvans?",a="Ja. Daltry jämför den blodfläckade sidan med namnteckningarna i stadsregistret och bekräftar att handstilen stämmer. Därmed får Ebonlocke den visshet hon ville ha innan hon agerar.",al={"stämmer handstilen","är det stalvan","skrev stalvan det"}},{q="Varför är Night Watch så försiktiga med att anklaga Stalvan?",a="Även i Duskwoods oroliga och avskilda skogar strävar Night Watch efter att upprätthålla lag och ordning. Att anklaga en före detta lärd för fruktansvärda brott kräver konkreta, verifierbara bevis, inte bara rykten eller spekulationer.",al={"varför behövs bevis","varför inte bara döda stalvan","ebonlockes misstankar"}}},fx={["5aad2c8f"]={q="Varför låter Commander Althea Ebonlocke dig ta sidan till Clerk Daltry?",a="Commander Ebonlocke ansvarar för försvaret av Duskwood och Darkshire och håller uppsikt över bosättningens ytterområde medan du har skött fältarbetet kring Stalvan Mistmantle. Eftersom du lämnade den blodfläckade dagbokssidan direkt till henne går det snabbast om du lämnar den till Clerk Daltry i stadshuset, så att han kan kontrollera handstilen medan hon stannar i tjänst.",al={"varför jag till ebonlocke","varför pratar inte ebonlocke med daltry","varför skicka mig till daltry"}}},fp="21,201,15.372.0,15.329.1,62.286.0,62.202.0,43.119.0,54.194.0,55.183.1,58.219.0"}
P.entries["quest:80001"] = {n="Rekindle",s="En släckt eldstad har torr ved som är redo att fatta eld. Du använder dina färdigheter som spejare.",h="En släckt eldstad har torr ved som är redo att fatta eld.",kw={"torr ved","släckt eld","eldstad","rekindle","spejarfärdigheter"},sec={{t="Vid eldstaden",b="Veden är torr nog att fatta eld. Du använder dina färdigheter som spejare vid den släckta eldstaden."}},faq={{q="Vad handlar Rekindle om?",a="En släckt eldstad har torr ved som är redo att fatta eld, och du använder dina färdigheter som spejare.",al={"uppdraget rekindle","tända elden igen","eldstad"}},{q="Vad är det för fel på eldstaden?",a="Eldstaden är släckt, men veden är torr nog att fatta eld.",al={"problem med eldstaden","varför brinner det inte","släckt eld"}},{q="Vad står det när uppdraget är slutfört?",a="Det står att du använder dina färdigheter som spejare.",al={"rekindles slut","vad händer när uppdraget är slutfört","spejarfärdigheter"}}},fp="8,96,15.107.0,23.98.0,32.75.0,29.54.0"}
P.entries["quest:804"] = {n="Sarkoth",s="I Valley of Trials väntar Hana'zua på hjälp efter att Sarkoths gift lämnat honom strandsatt. Du har dödat den skorpiden som skadade honom; nu behöver Gornek få besked vid The Den så att hjälp kan nå spejaren.",h="I Valley of Trials väntar Hana'zua på hjälp efter att Sarkoths gift lämnat honom strandsatt.",kw={"darkspear","durotar","gornek","hana'zua","sarkoth","skorpide","the den","valley of trials"},ang={["faction:Horde"]="Som medlem i Horden lär du dig att överlevnad i ett hårt och obarmhärtigt land bygger på att man hjälper varandra. Att inte lämna någon kamrat bakom sig lärs ut redan från en novis första steg.",["race:Orc"]="Som ork vet du att personlig styrka spelar roll. Att försvara en utslagen allierads heder visar hjärtat hos en sann krigare.",["race:Troll"]="Som troll kan du stärka det unga bandet mellan Darkspear-stammen och Thralls orcher genom att rädda Hana'zua från en långsam död av gift."},sec={{t="En spejares belägenhet",b="Hana'zua, en Darkspear-spejare, ligger strandsatt på de höga klipporna i Valley of Trials. Sarkoths gift har gjort honom för svag för att ta sig nerför de förrädiska stigarna ensam. Du har hämnats honom genom att döda skorpiden, men han kan fortfarande inte ta sig över de torra stenarna utan hjälp. En förbipasserande novis måste föra besked ner till träningslägret."},{t="Heder i The Den",b="Gornek väntar vid The Den på din rapport. När han får höra om Hana'zua och hans belägenhet inser han faran från Sarkoth och ordnar hjälp åt spejaren. Hordens befälhavare hedrar dem som lägger sin egen träning åt sidan för att försvara och rädda en fallen främling. Ett sådant uppförande visar att en novis är värdig innan marschen in i själva Durotar börjar."}},faq={{q="Vem är Hana'zua och varför är han strandsatt?",a="Hana'zua är en ung Darkspear-trollspejare som är strandsatt högt uppe i Valley of Trials. Sarkoth överföll och förgiftade honom, så han är för svag för att klättra ner ensam.",al={"hanazua","vem är hanazua","varför är trollen skadad"}},{q="Vem är Gornek?",a="Gornek är en orkisk tillsynsman vid The Den i Valley of Trials. Han bedömer nya rekryter, delar ut överlevnadsuppgifter och samordnar hjälp när noviser möter dödliga hot i ravinen.",al={"gornek","var finns gornek","ledare vid the den"}},{q="Vad är Sarkoth?",a="Sarkoth stryker omkring på de klippiga höjderna ovanför Valley of Trials som en ökänd, övervuxen skorpide. Dess gift och ursinne gör den till en legendarisk fara för unga orcher och troll under prövningarna.",al={"odjuret sarkoth","vad är sarkoth för monster"}},{q="Överlever Hana'zua sina skador?",a="Gornek lovar att skicka hjälp till Hana'zua så snart han får höra din rapport. Det berättas inte vad som sedan händer med spejaren.",al={"överlever trollen","mår hanazua bra","hanazua räddad"}},{q="Varför berömmer Gornek denna handling så mycket?",a="Det förväntas att du överlever prövningarna. Att lägga dina egna uppgifter åt sidan för att försvara en främlings heder och hjälpa denne att överleva speglar de värderingar som den nya Horden vill ingjuta i sina krigare.",al={"varför bryr sig gornek","gorneks tal om heder"}},{q="Var ligger The Den?",a="The Den är den centrala träningsgrottan och samlingsplatsen mitt i Valley of Trials i sydvästra Durotar.",al={"var ligger the den","the den plats durotar"}}},fx={["88c1d5d5"]={q="Varför ber Hana'zua dig rapportera till Gornek?",a="Hämnden för nederlaget mot Sarkoth har stärkt Hana'zua i hans beslutsamhet att överleva, men hans svåra sår gör honom helt orörlig i dalen. Han kan inte ta sig tillbaka till The Den på egen hand. Genom att skicka dig med besked om sitt tillstånd hoppas han att Gornek ska skicka hjälp innan han dukar under för skadorna eller väder och vind.",al={"varför skicka till gornek","hana'zuas motiv","varför meddela gornek"}},["66b1c5a1"]={q="Varför kan Hana'zua inte själv återvända till The Den?",a="Hana'zua blev svårt sargad och lämnades att dö av Sarkoth under sin prövning. Han har inte kraft nog att stå upp, än mindre att krypa över den stekheta kanjonbottnen till säkerhet utan hjälp. Eftersom inga andra krigare finns i närheten är du hans enda livlina som kan meddela Gornek innan det är för sent.",al={"varför behöver hana'zua hjälp","varför kan hana'zua inte gå","varför jag hana'zua"}}},fp="7,210,16.336.0,16.328.0,39.166.0,14.182.0,16.184.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="Report to Sen'jin Village",s="Zureetha Fargaze skickar bud från Valley of Trials till Sen'jin Village. Burning Blade-kultister har varit aktiva i dalen, och hon ber unga initiater att varna Darkspear Trolls. Master Gadrin berättar för dem att mörk magi hotar de närliggande Echo Isles.",h="Zureetha Fargaze skickar bud från Valley of Trials till Sen'jin Village.",kw={"burning blade","darkspear","durotar","echo isles","master gadrin","sen'jin village","valley of trials","zureetha fargaze"},ang={["faction:Horde"]="Som medlem av Thralls Horde ser du hur dess grundande folk delar varningar för att skydda varandras unga bosättningar.",["race:Orc"]="Som ung ork lämnar du Valley of Trials för att hjälpa Darkspear, ett tidigt prov på heder och solidaritet med de allierade som stod vid Thralls sida över Stora havet.",["race:Troll"]="Som Darkspear-äventyrare återvänder du till Sen'jin Village för att möta ditt folks fördrivning och deras kamp för att återta Echo Isles."},sec={{t="Lämna The Den",b="Unga initiater lämnar Valley of Trials efter att ha visat sin stridsduglighet och återfunnit mörka medaljonger från Burning Blade Coven. Zureetha Fargaze inser att demonerna på den heliga prövningsplatsen inte är något enskilt irritationsmoment; de vittnar om en farsot som sprider sig över Durotar. Hon skickar de beprövade kämparna österut förbi ravinens mynning och sedan söderut mot kusten för att varna Darkspear-stammen."},{t="Skuggor över kusten",b="I Sen'jin Village framför resenärerna sin varning för Master Gadrin, den äldre häxdoktorn som leder Darkspear i exil. Gadrin säger att Burning Blade inte har tågat fram över byns stränder. Ändå har mörk magi fått fäste i närheten på Echo Isles, och förräderi hotar trollen där. Den unga Hordens fotfäste är fortfarande bräckligt medan allierade skyndar till varandras försvar, samtidigt som stamstridigheter och demonisk korruption angriper deras flanker."}},faq={{q="Varför skickar Zureetha Fargaze bort folk från Valley of Trials?",a="Demonisk aktivitet i Valley of Trials får Zureetha Fargaze att frukta att Burning Blade är ett organiserat hot mot hela Durotar. Hon skickar beprövade initiater bortom dalen för att varna allierade bosättningar och ta reda på hur långt kultens inflytande har spridit sig.",al={"varför lämna dalen","varför bege sig till sen'jin","zureetha fargazes order"}},{q="Vem är Master Gadrin?",a="Master Gadrin är en äldre häxdoktor och andlig ledare för Darkspear Trolls i Sen'jin Village. Han ger råd åt hövdingen Vol'jin och sköter stammens angelägenheter samtidigt som han möter hot mot deras kustnära tillflyktsort.",al={"master gadrins historia","vem är gadrin"}},{q="Har Burning Blade angripit Sen'jin Village?",a="Nej, Burning Blade har inte anfallit Sen'jin Village. Master Gadrin varnar för att mörk magi och förräderi har fått fäste i närheten på Echo Isles och utsätter trollen för fara.",al={"är burning blade i sen'jin","kult i sen'jin"}},{q="Var ligger Sen'jin Village?",a="Sen'jin Village ligger österut, bortom huvudravinens mynning från Valley of Trials, och sedan söderut vid vägskälet längs Durotars sydöstra kust.",al={"hur tar man sig till sen'jin","vägbeskrivning till sen'jin village"}},{q="Vilket hot på Echo Isles nämner Master Gadrin?",a="Master Gadrin fruktar att Zalazane, en trollhäxdoktor från den egna stammen, har förrått Darkspear. Zalazane använde lömska förbannelser för att förslava sina fränder och ta kontroll över Echo Isles, och drev de överlevande Darkspear-trollen till fastlandets stränder.",al={"problem på echo isles","vad hände på echo isles"}},{q="Vad händer efter rapporten till Master Gadrin?",a="Efter att ha hört din rapport och beskrivit trollens svåra läge ber Gadrin dig att hjälpa till mot farorna som hotar kusten. Senare order skickar dig sedan nordväst till Orgnil Soulscar i Razor Hill.",al={"nästa uppdrag efter rapport till sen'jin","vad gör man efter gadrin"}}},fx={["54845e0f"]={q="Varför skickar Zureetha Fargaze dig till Master Gadrin i stället för en vakt?",a="Du har själv konfronterat Burning Blade inne i deras församling i Valley of Trials och hämtat bevis på att de finns där. Du har bevisat din lojalitet och styrka genom dina prövningar och är därför bäst lämpad att ge Master Gadrin en ögonvittnesskildring av kultens infiltration.",al={"varför skicka mig","varför jag zureetha","varför inte skicka en budbärare till sen'jin"}}},fp="25,237,15.395.0,22.434.1,70.235.0,21.202.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="Dark Storms",s="I Durotar korrumperar Burning Blade-kultister landet från Thunder Ridge. Orgnil Soulscar i Razor Hill har fått veta att goblinhäxmästaren Fizzle Darkstorm leder dem och ber dig göra slut på hotet.",h="I Durotar korrumperar Burning Blade-kultister landet från Thunder Ridge.",kw={"burning blade","dark storms","durotar","fizzle darkstorm","fizzle's claw","orgnil soulscar","razor hill","thunder ridge"},ang={["class:Shaman"]="Som schaman vet du att Fizzles mörka riter och hans undersåtar stör Thunder Ridges naturandar och hetsar dess bestar. Den elementära balansen måste återställas.",["class:Warlock"]="Som häxmästare ser du hur Fizzles vårdslösa hängivenhet åt felkraft gör honom till ett hot och en skam för disciplinerade utövare inom Horde.",["faction:Horde"]="Som medlem av Horde hjälper du till att säkra Durotars hjärta mot demonisk undergrävning, så att Horde kan rikta sitt försvar utåt utan att falla sönder inifrån.",["race:Orc"]="Som orch vet du att Burning Blade förkroppsligar det mörka förflutna som ditt folk kämpar för att övervinna. Att driva bort infiltratörer som Fizzle hjälper till att skydda Thralls fria nation."},sec={{t="Ett hot i ravinen",b="Orgnil Soulscar har fått veta att mörk magi har fått fäste i Thunder Ridge, nordväst om Razor Hill. Burning Blade-kultister stryker omkring i ravinen medan unga Horde-försvarare patrullerar Durotars gränser. Deras närvaro ödelägger djurlivet och landet."},{t="Svartkonstnären Fizzle Darkstorm",b="Fizzle Darkstorm, en goblinhäxmästare som samarbetar med Burning Blade, leder kultisterna i Thunder Ridge. Han brukar felkraft för kulten i stället för att tjäna handelns eller kartellernas intressen. Om du dödar honom och tar tillbaka hans förvridna klo visar du Orgnil att kultens ledare i ravinen har fällts."},{t="Rensa ut sekten",b="Burning Blade står för demoniskt slaveri, korruption och blodtörstigt vansinne, sådant som Thralls nya Horde försöker lämna bakom sig. Fizzles död avlägsnar en aktiv konspiratör från Durotars inre. Skuggan över orchernas hemland sträcker sig bortom isolerade läger."}},faq={{q="Vem är Fizzle Darkstorm?",a="Fizzle Darkstorm är en goblinhäxmästare som arbetar för Burning Blade-kulten. Han och hans anhängare håller till i Thunder Ridge och sprider demoniskt kaos genom ravinen, tills Orgnil Soulscar kräver att han avrättas.",al={"vem är fizzle","fizzle darkstorms bakgrund","fizzle goblin"}},{q="Var ligger Thunder Ridge?",a="Thunder Ridge ligger i nordvästra Durotar, norr om Razor Hill och sydväst om Orgrimmar. Blixtladdade bestar och Burning Blade-kultister håller till i dess oländiga kanjon.",al={"var ligger thunder ridge","thunder ridges plats","hur hittar man thunder ridge"}},{q="Varför finns Burning Blade i Durotar?",a="Burning Blade försöker undergräva Thralls Horde och återupprätta demoniskt herravälde över orcherna. Dess medlemmar gömmer sig i raviner, grottor och kanjoner över hela Durotar och sprider korruption inifrån.",al={"burning blade i durotar","varför finns kultister i durotar","burning blades motiv"}},{q="Varför vill Orgnil Soulscar särskilt ha Fizzles klo?",a="Orgnil vill ha Fizzles klo som ett otvetydigt bevis på att häxmästaren är död. Den bekräftar att ledaren för kultisterna i Thunder Ridge inte längre kan styra deras verksamhet.",al={"varför fizzle har en klo","vad fizzle's claw betyder","bevis på fizzles död"}},{q="Vad händer efter att Fizzle dödats?",a="När Fizzle har fallit återvänder du till Orgnil Soulscar med beskedet. Han skickar dig till Margoz, en schaman som vet mer om Burning Blades korruption, så att du kan nysta upp fler konspirationer.",al={"vad händer efter dark storms","fortsättning på dark storms","nästa uppdrag efter dark storms"}},{q="Varför skulle en goblin arbeta för Burning Blade?",a="En del gobliner lockas av skuggmagi för dess kraft, inflytande och mörka konster. Fizzle gav sig hän åt felmagi och ställde sin hänsynslösa list i kultisternas tjänst.",al={"goblin i burning blade","varför är fizzle med i sekten","fizzle häxmästare"}}},fx={["18f009de"]={q="Varför vill Orgnil Soulscar att Fizzle Darkstorm undanröjs?",a="Orgnil fruktar att Burning Blade kommer att sprida sin korrumpering och sitt demoniska inflytande okontrollerat om de tillåts få ens ett litet fäste i Durotar. Fizzle Darkstorm och hans församling har befäst sig i Thunder Ridge och sprider aktivt kaos alldeles vid det spirande orchernas hemlands tröskel. Om de slås ner omedelbart hindras en fullskalig demonisk infiltration från att få fäste.",al={"varför döda fizzle darkstorm","orgnil soulscars motiv","varför uppdraget dark storms"}}},fp="11,179,21.246.0,16.291.0,20.284.1,24.204.0,31.169.0,36.193.0,57.166.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="Minshina's Skull",s="I Sen'jin Village hör Master Gadrin sin döde bror Minshinas desperata rop. Zalazane dödade Minshina på Echo Isles och band hans själ med mörk magi till hans avhuggna skalle. För att befria honom från plågan måste du återta skallen från Zalazanes ritualplats.",h="I Sen'jin Village hör Master Gadrin sin döde bror Minshinas desperata rop.",kw={"maktcirkel","darkspear","echo isles","gadrin","minshina","sen'jin village","kranium","voodoo","zalazane"},ang={["class:Priest"]="Som präst känner du till en bortgången själs helgd och fasorna i den nekromantiska ritual som hindrar en fallen bror från att finna evig frid.",["class:Shaman"]="Som shaman vördar du förfädernas andar. När du bryter Zalazanes cirkel befriar du en plågad själ och återställer balansen mellan andevärlden och de levande.",["faction:Horde"]="Som medlem av Horde hedrar du dess band till Darkspear-stammen genom att hjälpa Master Gadrin. Din hjälp visar att alla delar en allierads sorg.",["race:Troll"]="Som Darkspear-troll hedrar du familjen och stammen genom att återta Minshinas skalle. Du slår mot Zalazanes förvanskning av förfädernas voodootraditioner."},sec={{t="En vädjan från skuggorna",b="Master Gadrin är en av Darkspear-stammens andliga grundpelare i Sen'jin Village, men mörka syner plågar honom. Hans bror Minshina föll när Zalazane förrådde stammen och tog kontroll över Echo Isles. Minshina dog i konflikten, men döden har inte gett honom någon frid. Enligt trolltradition och voodoomystik kan kroppen dö medan anden förblir bunden. Nu når Minshinas plågade röst Gadrin i hans drömmar och ber om att räddas från ett öde värre än döden."},{t="Zalazanes maktcirkel",b="Zalazane nöjer sig inte med att döda sina forna bröder och systrar; han fångar deras själar för att ge kraft åt sin mörka trolldom. Han band Minshinas ande till sin egen skalle, som nu står i en hädisk kraftcirkel på den största av Echo Isles. Hexade troll vaktar cirkeln, där ljus brinner under ritualerna och skallen fokuserar Zalazanes förvridna mojo. Så länge den är där är Minshina fånge under häxdoktorns vilja."},{t="Frihet i döden",b="För att befria Minshina korsar du vattnet öster om Sen'jin Village till den södra delen av Echo Isles. Du bryter dig in i ritualringen och tar skallen från Zalazane. När du återlämnar Minshinas kvarlevor till Master Gadrin brister de mörka bojorna. Minshinas tacksamma ande visar sig en kort stund, bugar vördnadsfullt och beger sig sedan till förfädernas rike."}},faq={{q="Vem var Minshina?",a="Minshina var Master Gadrins bror. Zalazane mördade honom under upproret på Echo Isles och vanhelgade sedan hans kvarlevor med mörk trolldom.",al={"minshinas identitet","vem är minshina","gadrins bror"}},{q="Varför är Minshinas ande fångad i hans kranium?",a="Zalazane använder mörk voodoo och häxmästarmagi för att förslava andarna hos stupade Darkspear-troll. Han band Minshinas själ till hans fysiska skalle och placerade den i en kraftcirkel. Därmed nekade han Minshina tillträde till livet efter döden och utnyttjade hans ande.",al={"varför fånga kraniet","zalazanes själsfångst","minshinas själ"}},{q="Var ligger maktcirkeln?",a="Kraftcirkeln ligger på en höjd längst i söder, på den största av Echo Isles utanför Durotars sydöstra kust. Ritualens ljus, dansande hexade troll och uppvisningar av skallar märker ut platsen.",al={"var finns kraniet","maktcirkelns plats","var minshinas kranium finns"}},{q="Vad händer när kraniet förs tillbaka till Sen'jin Village?",a="När Master Gadrin tar emot skallen krossas de nekromantiska bojorna. Minshinas vålnad visar sig för Gadrin och dig, bugar tacksamt och försvinner sedan för att vila i frid hos förfäderna.",al={"lämna in uppdrag","vad händer med minshina","visar sig minshina"}},{q="Vem är Zalazane och varför gjorde han detta?",a="Zalazane var en gång en respekterad Darkspear-häxdoktor. Maktbegär drev honom till vansinne. Han vände sig mot sin stam, använde hexar för att ta kontroll över sina bröder och systrar och drev de återstående Darkspear-flyktingarna till Durotars fastland.",al={"vem är zalazane","varför är zalazane ond","zalazanes historia"}},{q="Varför kan inte Gadrin hämta kraniet själv?",a="Master Gadrin kan inte lämna Sen'jin Village utan skydd. Han håller samman bosättningen, vägleder det unga Darkspear-ledarskapet, ger råd åt hövdingen Vol'jin och arbetar för att hejda Zalazanes hexar som sprider sig längs kusten.",al={"varför går inte gadrin","gadrins plikter"}}},fx={["2001e9be"]={q="Varför vill Master Gadrin att det här görs?",a="Master Gadrin plågas i sina drömmar av sin bror Minshinas rop på honom. Den förrädiske häxdoktorn Zalazane dödade Minshina på Echo Isles, men döden gav honom ingen frid. Zalazane band Minshinas själ direkt till hans avhuggna skalle och fjättrade honom med mörk magi. Gadrin står inte ut med att låta sin brors ande förbli dömd till evigt slaveri, och han behöver desperat någon som bryter trollkarlens grepp och ger Minshina evig vila.",al={"varför behöver gadrin minshina skull","master gadrins motiv","varför befria minshina"}},["5583848b"]={q="Vad används Minshina's Skull till?",a="Minshina's Skull är ett magiskt kärl som håller den fångade essensen av Master Gadrins mördade bror. Zalazane placerade den i en kraftcirkel på den största av Echo Isles och använde vidrig trolldom för att förslava Minshinas ande även efter döden. När skallen tas bort från det mörka altaret störs trollkarlens bindande magi, så att Gadrin äntligen kan befria sin brors själ när du har levererat den säkert tillbaka till Sen'jin Village.",al={"vad är minshina skull","syftet med minshinas skalle","minshinas skalle föremål"}}},fp="16,254,23.468.0,26.384.0,16.345.1,17.142.0,46.259.0,37.197.0,63.199.1,39.230.0,44.220.0"}
P.entries["quest:809"] = {n="Ak'Zeloth",s="Neeru Fireblade skickar dig från Orgrimmar in i The Barrens när tecken på demonisk fördärv visar sig. Hans kontakt väntar nära gränsen.",h="Neeru Fireblade skickar dig från Orgrimmar in i The Barrens när tecken på demonisk fördärv visar sig.",kw={"ak'zeloth","the barrens","burning blade","cleft of shadow","demon seed","dreadmist peak","far watch post","neeru fireblade"},ang={["class:Warlock"]="Som häxmästare kanske du märker att till och med Neeru Fireblades assistent ifrågasätter ordern att förstöra en demonisk relik.",["faction:Horde"]="Som medlem av Horde hjälper du till att skydda de unga handels- och färdvägarna mellan Durotar och The Barrens genom att säkra Far Watch Post och rensa Dreadmist Peak.",["race:Orc"]="Som ork känner du till priset för Burning Legions grepp. Burning Blade-sekten och demoniska reliker vid din tröskel hotar den frihet som vunnits med stora uppoffringar."},sec={{t="Ett spår av skuggor",b="Neeru Fireblade säger att Burning Blade fortfarande hotar Horde med demonisk fördärv. När du har hämtat en halskrage med Burning Blade-insignier åt honom från Durotar skickar han dig till The Barrens. En sekt samlas kring Demon Seed, en artefakt med ondskefull kraft, och Neeru vill att du hittar hans kontakt nära gränsen."},{t="Kontakten vid utposten",b="Ak'Zeloth väntar nära Far Watch Post, vid gränsen mellan Durotar och The Barrens. Neerus assistent undrar högt om hans mästare verkligen vill att Demon Seed ska förstöras. Sedan berättar han hur du ska hantera artefakten på toppen av Dreadmist Peak."}},faq={{q="Vem ger uppdraget?",a="Neeru Fireblade, en häxmästare i Orgrimmars Cleft of Shadow, ger dig detta uppdrag när du visar honom en halskrage från Burning Blade.",al={"uppdragsgivare","var hittar man ak'zeloth","neeru fireblade-uppdrag"}},{q="Var finns Ak'Zeloth?",a="Ak'Zeloth väntar strax utanför Far Watch Post, längs den östra gränsen till The Barrens där bron går över från Durotar.",al={"ak'zeloths plats","var finns ak'zeloth","hitta ak'zeloth"}},{q="Vad är Demon Seed?",a="Demon Seed är en artefakt med demonisk kraft som Burning Blade-sekten håller på toppen av Dreadmist Peak i norra The Barrens.",al={"demon seed-bakgrund","vad är fröet"}},{q="Varför tycker Ak'Zeloth att Neerus order är märklig?",a="Ak'Zeloth säger bara att det är märkligt att Neeru vill att Demon Seed ska förstöras, men går sedan med på att förklara hur du tar bort den.",al={"varför är ak'zeloth förvånad","ak'zeloths märkliga reaktion"}},{q="Vilket uppdrag följer efter detta?",a="När du har talat med Ak'Zeloth skickar han dig att bestiga Dreadmist Peak och oskadliggöra den fördärvande reliken.",al={"nästa uppdrag efter ak'zeloth","uppföljning till ak'zeloth"}},{q="Är uppdraget en del av berättelsen om Burning Blade?",a="Ja. Burning Blades verksamhet i Durotar leder vidare till den större, organiserade sektverksamheten i The Barrens.",al={"burning blade-uppdragskedja","orgrimmar kultuppdrag"}}},fx={["91b6b00f"]={q="Varför vill Neeru Fireblade att Demon Seed förstörs?",a="Neeru Fireblade hävdar att han sedan Burning Legions nederlag har ägnat sig åt att spåra upp kvarvarande demonisk korrumpering i orchernas länder. När du kom med en Burning Blade-kultkrage förklarade han att den bekräftade hans värsta farhågor. Enligt Neeru hämtar kulten sin styrka från Demon Seed på toppen av Dreadmist Peak, och det är avgörande att krossa denna demoniska relik för att hejda dess mörka inflytande över Horden.",al={"neeru fireblades motiv","varför förstöra demon seed","varför skickar neeru dig"}}},fp="9,122,17.313.0,19.224.1,21.126.0,27.120.0,23.122.0,47.116.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="Need for a Cure",s="Rhinag ligger förgiftad på Durotars nordvästra klippor, långt från botemedlet han behöver. Darkspear-trollet har ont om tid innan giftet dödar honom, så han skickar en förbipasserande kurir till Orgrimmar efter Kor'ghans motgift.",h="Rhinag ligger förgiftad på Durotars nordvästra klippor, långt från botemedlet han behöver.",kw={"motgift","cleft of shadow","durotar","kor'ghan","behov av botemedel","orgrimmar","rhinag","scorpid","venomtail"},ang={["faction:Horde"]="Som medlem av Horde möter du Durotars steniga, obarmhärtiga terräng, en prövning för försvarare som nyligen anlänt till Thralls unga rike.",["race:Troll"]="Som troll kan du förstå varför Rhinag fruktar att hans släkte i Sen'jin Village ska håna honom. Bland Darkspear leder oförsiktighet i vildmarken till hårt hån."},sec={{t="En scorpidstjärnas sting",b="Rhinag kämpade mot venomtail-scorpider nära Durotars gräns när en av dem stack honom. Deras gift kan döda på mindre än en timme. Giftet hindrar honom från att gå till Orgrimmar, så hans överlevnad hänger på att en resenär hinner fram till hans avlägsna läger i tid."},{t="Hemligheter i skuggorna",b="Rhinag skickar resenärer till Cleft of Shadow under Orgrimmar, där Kor'ghan vet hur man motverkar gifterna i Durotars ödemarker. Kor'ghan kan brygga ett botemedel, även om han sällan hjälper dem som inte har bevisat sitt värde."}},faq={{q="Vem är Rhinag?",a="Rhinag är en Darkspear-trolläventyrare som klamrar sig fast vid livet på Durotars nordvästra klippor. En venomtail-scorpider stack honom, och han fruktar att hans släkte i Sen'jin Village ska håna honom om han återvänder i ett så förödmjukat tillstånd.",al={"rhinags bakgrund","vem är rhinag","rhinag trollet"}},{q="Varför är Kor'ghan i Cleft of Shadow?",a="Kor'ghan bor i Cleft of Shadow under Orgrimmar. Trollkarlar, skurkar och andra som utövar mörka konster verkar där utom synhåll för Thralls ärade krigare, och Kor'ghans kunskap om giftiga brygder och utmattande prövningar passar grottorna väl.",al={"var är korgan","vem är korghan","kor'ghans plats"}},{q="Varför söker Rhinag inte upp en schaman eller läkare i Sen'jin Village?",a="Rhinag säger att stoltheten hindrar honom från att söka hjälp i Sen'jin Village. Han fruktar att hans trollfränder ska håna honom för att han återvänder oförsiktig och förgiftad, så han söker ett diskret botemedel från Kor'ghan.",al={"varför inte gå till sen'jin","varför rhinag undviker sen'jin"}},{q="Vad händer när Rhinag får motgiftet?",a="Rhinag dricker motgiftet och återhämtar sig, men Kor'ghan kräver mer av honom. Botaren förväntar sig att han ska klara utmattande prövningar, däribland att döda vildsvin och samla in scorpidstjärtar, innan han åter vinner Kor'ghans gunst.",al={"överlever rhinag","vad händer rhinag sedan"}},{q="Var kan Rhinag hittas?",a="Rhinag finns i de karga klipporna i nordvästra Durotar, nära bergspassen vid gränsen som leder västerut mot The Barrens.",al={"rhinags plats","var är rhinag"}},{q="Varför är det så bråttom att hämta botemedlet?",a="Venomtail-scorpidergiftet är så starkt att det kan slå ut offrets livsviktiga organ på mindre än en timme utan behandling.",al={"varför är det tidsbegränsat","rhinags giftklocka"}}},fx={["0710a7b2"]={q="Vad är Venomtail Antidote till för?",a="Motgiftet motverkar det dödliga giftet från venomtail-scorpiderna som håller till i nordvästra Durotar. Rhinag blev djupt stungen under en oförsiktig skärmytsling med bestarna, och giftet sprider sig snabbt i hans blod. Utan den särskilda brygd som Kor'ghan har blandat i Orgrimmar har Rhinag mindre än en timme kvar innan giftet tar hans liv.",al={"vad är motgiftet till för","venomtail antidotes användning","varför behövs venomtail antidote"}}},fp="15,218,17.239.0,22.216.0,14.215.0,39.260.0,67.197.0,48.222.1,26.121.0,47.113.0"}
P.entries["quest:813"] = {n="Finding the Antidote",s="Kor'ghan i Orgrimmar skyndar sig att brygga ett botemedel åt den förgiftade jägaren Rhinag. Du samlar giftkörtlar från venomtail-skorpioner utanför stadsmurarna innan deras gift blir dödligt. Durotars vilda djur är skoningslösa, och överlevnad beror på förberedelser inför vildmarken.",h="Kor'ghan i Orgrimmar skyndar sig att brygga ett botemedel åt den förgiftade jägaren Rhinag.",kw={"motgift","durotar","kor'ghan","orgrimmar","gift","rhinag","skorpion","venomtail-skorpion"},ang={["class:Hunter"]="Som jägare hör du Kor'ghans stränga påminnelse: lär känna en bests gift och bär med dig rätt botemedel, tillsammans med bågen och spårningsförmågan.",["faction:Horde"]="Som medlem av Horde i Durotar tar du hand om dina egna. Ensamma skogsvakter och spejare vid gränsen kan lita på att Orgrimmar hjälper dem.",["race:Orc"]="Som en ork som nyligen slagit sig ner i Durotar ställs du på prov. Även en rutinerad spejare kan falla offer för landets naturliga faror genom slarv."},sec={{t="En kamp mot giftet",b="Rhinag, en Darkspear-troll, jagade i Durotar när han mötte venomtail-skorpioner utan motgift. Deras kraftiga gift verkade snabbt och lämnade honom i akut behov av hjälp. Kor'ghan, en erfaren jägare i Orgrimmar, måste blanda till en brygd innan giftet dödar honom."},{t="Att brygga botemedlet",b="Fullvuxna venomtail-skorpioner utanför Orgrimmars portar bär på de körtlar Kor'ghan behöver för att tillverka ett motgift. Han säger att det kommer finnas tid att läxa upp Rhinag för att han gav sig av oförberedd, men varje ögonblick är viktigt nu. Ta med körtlarna tillbaka till staden, så kan Kor'ghan brygga en brygd åt den döende jägaren."}},faq={{q="Vem är Rhinag?",a="Rhinag är en Darkspear-trolljägare i Durotar. Venomtail-skorpioner stack honom medan han spårade bestar, och utan motgift är han nu beroende av hjälp från Orgrimmar innan giftet övermannar honom.",al={"rhinags bakgrund","vem är förgiftad","vem behöver motgiftet"}},{q="Vem är Kor'ghan?",a="Kor'ghan är en erfaren Darkspear-trolljägare i Orgrimmars Cleft of Shadow. Han känner till Durotars bestar och kan brygga ett motgift av giftkörtlar från venomtail-skorpioner.",al={"kor'ghan","vem är korphan","korgan orgrimmar"}},{q="Varifrån kommer giftblåsorna?",a="Giftkörtlarna kommer från venomtail-skorpioner utanför Orgrimmar, på den steniga, torra marken nära stadens ingång.",al={"var finns venomtail-skorpioner","var finns giftblåsorna","giftblåsor från venomtail-skorpioner"}},{q="Varför finns det en tidsgräns för uppdraget?",a="Rhinags hälsa sviktar ute i fält. Venomtail-gift verkar snabbt, så Kor'ghan behöver ingredienserna i tid för att brygga ett botemedel innan Rhinag dör av förgiftningen.",al={"varför finns en tidsgräns","need for a cure tidsgräns","tidsbegränsat uppdrag"}},{q="Vilken lärdom betonar Kor'ghan under jakten?",a="Kor'ghan varnar jägare för att studera sitt byte och dess faror innan de går till angrepp. Att ge sig ut i vildmarken utan ordentliga förberedelser eller motåtgärder kan kosta en krigare livet.",al={"kor'ghans lärdom","lärdom om jakt","kor'ghans råd"}},{q="Hur hänger uppdraget ihop med 'Need for a Cure'?",a="'Need for a Cure' sätter igång nödläget och startar timern. Finding the Antidote är mellansteget: du samlar de råvaror Kor'ghan behöver för att brygga den färdiga blandningen.",al={"kopplingen till need for a cure","förutsättningsuppdrag","hur hänger det ihop"}}},fx={["837950c2"]={q="Varför vill Kor'ghan att det här görs?",a="Kor'ghan inser att Rhinag gjorde ett dumdristigt misstag när han jagade Durotars farligaste scorpider oförberedd, men han tänker inte låta en av Darkspear dö för sitt dåliga omdöme. För Kor'ghan går det före tillrättavisningar att rädda livet på en av de sina. Han vill blanda ett motgift genast så att Rhinag överlever den dödliga förgiftningen.",al={"varför hjälpa rhinag","kor'ghans motiv","varför bryr sig kor'ghan"}},["20540779"]={q="Vad är Venomtail Poison Sac till för?",a="Kor'ghan behöver de färska giftsäckarna för att framställa ett motgift åt Rhinag. Genom att utvinna giftämnena direkt från Durotars venomtail-scorpider kan han blanda ett motmedel som är starkt nog att neutralisera det snabbverkande giftet som strömmar genom den förgiftade jägarens blod.",al={"venomtail-giftsäckens användning","vad används venomtail-giftsäckar till","varför samla giftsäckar"}},d062d72d={q="Vad är venomtails nära Orgrimmar för några?",a="Venomtails är rovgiriga scorpider som hör hemma i Durotars torra ödemarker och stryker omkring bland klippbranterna utanför Orgrimmar. Orchernas jägare känner dem som några av regionens dödligaste varelser. Deras giftiga sting kan snabbt bli dödliga om de inte behandlas, så de är farliga bestar som kräver försiktighet och respekt.",al={"vad är venomtails","venomtail-scorpider","varför döda venomtails"}}},fp="20,262,24.232.0,17.282.0,14.180.0,16.164.0,43.114.0,47.160.0,53.181.0,46.202.0"}
P.entries["quest:815"] = {n="Break a Few Eggs",s="Break a Few Eggs är ett ärende där du hjälper en jäktad kock som måste hinna med ändlösa matförberedelser. Att skaffa färska, ömtåliga ingredienser utan att krossa dem håller köket igång och maten på tid.",h="Break a Few Eggs är ett ärende där du hjälper en jäktad kock som måste hinna med ändlösa matförberedelser.",kw={"break a few eggs","frukost","kock","matlagning","ägg","kök","måltider"},ang={["profession:Cooking"]="Varje yrkeskock känner till den obevekliga pressen att hålla folk mätta. Att hämta ömtåliga ingredienser utan att krossa dem är halva kampen i varje kök."},sec={{t="Ändlösa måltider",b="Att mätta många är ett utmattande, ändlöst arbete. Mellan frukost, lunch och middag finns knappt tid att lämna spisen, än mindre köket för att leta efter råvaror. I Break a Few Eggs ber en hårt pressad kock förbipasserande äventyrare att hämta färska ägg innan nästa måltid blir försenad."},{t="En kocks tacksamhet",b="Ägg måste hanteras varsamt, något råstyrka inte kan ersätta. Kocken kanske fäller vassa kommentarer och ger sparsamt med beröm, men hela ingredienser talar för sig själva. När äggen har levererats oskadda skickar kocken genast iväg den som hämtat dem och återgår till arbetet vid elden."}},faq={{q="Vad är uppdraget Break a Few Eggs?",a="Break a Few Eggs är en matlagningsuppgift där en äventyrare hjälper en upptagen kock som är överväldigad av den ständiga efterfrågan på mat. Uppgiften går ut på att leverera äggen hela så att matlagningen inte blir försenad.",al={"uppdraget break a few eggs","vad är break a few eggs","ägguppdrag"}},{q="Vem är kocken i Break a Few Eggs?",a="Kocken är Cook Torka från Razor Hill i Durotar, som lagar mat dygnet runt. Torka är rättfram och jäktad, men förlitar sig på skickliga händer som kan hämta Taillasher-ägg från Echo Isles utan att knäcka dem före måltiden.",al={"vem ger break a few eggs","kocken i ägguppdraget","vem lagar mat"}},{q="Varför behöver kocken ägg?",a="Kocken behöver dem till de pågående matförberedelserna, vare sig det gäller frukost, lunch eller middag. Att mätta folk är ett ändlöst arbete, och färska ägg är en viktig basvara som behövs genast vid spisen.",al={"varför ägg","vad används ägg till","varför behövs ägg"}},{q="Varför säger kocken åt en att inte vara klumpig?",a="Ägg är ömtåliga och lätta att förstöra under transporten. Kocken värdesätter uttryckligen någon som inte är klumpig, eftersom knäckta skal och spillda gulor förstör ingredienser som behövs till måltiden.",al={"varför vara försiktig med ägg","knäck inte äggen","varför inte vara klumpig"}},{q="Vad syftar titeln Break a Few Eggs på?",a="Namnet anspelar på det vanliga ordspråket att man inte kan göra en omelett utan att knäcka några ägg. Det passar en uppgift där du ska samla ömtåliga köksingredienser inför en hektisk måltid.",al={"betydelsen av break a few eggs","uttryckets betydelse","varför heter det break a few eggs"}},{q="Varför är kocken så otålig?",a="Kocken är helt upptagen med att hinna med måltiderna, från frukost till lunch och middag. Med så mycket matlagning kvar har kocken lite tålamod med småprat och vill bara återvända till spisen.",al={"kockens attityd","varför är kocken otrevlig","butter kock"}}},fp="16,147,13.350.0,18.256.0,35.121.0,36.209.0,28.139.0,46.105.0,46.139.0,29.163.0"}
P.entries["quest:816"] = {n="Lost But Not Forgotten",s="Misha Tor'kren väntar på sin gård på besked om sin son Kron. Han gav sig västerut för att jaga krokolisker längs Southfury River, och hon fruktar det värsta.",h="Misha Tor'kren väntar på sin gård på besked om sin son Kron.",kw={"amulett","krokolisk","dreadmaw","kron","misha","razor hill","southfury","tor'kren"},ang={["class:Hunter"]="Som jägare vet du att en spårare måste bedöma bytenas vildsinthet. Kron gjorde inte det, och krokoliskerna dödade honom.",["faction:Horde"]="Som medlem av Horde vet du att livet i Durotar är hårt. Familjer kämpar mot det obarmhärtiga landet och de dödliga rovdjuren längs dess gränser.",["race:Orc"]="Som ork vet du att stolthet och ära i strid betyder mycket i din kultur. Krons öde visar vad det kostar att möta farliga bestar utan respekt för deras styrka."},sec={{t="En mors fruktan",b="Misha Tor'kren bor på en gård nordväst om Razor Hill i Durotar. För några dagar sedan gav sig hennes son Kron av västerut mot Southfury River, längs gränsen till The Barrens, för att jaga de våldsamma krokoliskerna där. Misha varnade honom för hur dödliga bestarna var, men stoltheten drev honom att ge sig av och bevisa sin styrka. Ingen har sett honom sedan dess."},{t="En dyster bekräftelse",b="Misha ber dig söka längs Southfury Rivers stränder efter något spår av Kron, även inuti krokoliskerna. Dreadmaw-krokoliskerna bär på svaret: bland deras kvarlevor hittar du Krons amulett, som de svalt. När du kommer tillbaka med den inser Misha att hennes son inte överlevde. Minnesföremålet ger henne det avslut hon behöver för att börja sörja."}},faq={{q="Vem är Misha Tor'kren?",a="Misha Tor'kren är en orkmor som bor på en gård nordväst om Razor Hill i Durotar. Hon fruktar för sin försvunne son Kron och ber resande att leta efter spår av honom.",al={"misha torkren","vem ger lost but not forgotten","krons mor"}},{q="Vem var Kron?",a="Kron var Misha Tor'krens egensinnige son. Han gav sig av för att jaga farliga krokolisker nära Southfury River, i hopp om att bevisa sin styrka, och dog där.",al={"vem är kron","vad hände med kron","mishas son"}},{q="Var försvann Kron?",a="Kron reste västerut genom Durotar mot gränsen till The Barrens för att jaga längs Southfury Rivers stränder.",al={"var är kron","var ska man leta efter kron","krons plats"}},{q="Hur kan du bevisa för Misha vad som hände Kron?",a="Du hittar Krons amulett, som svalts av en krokolisk, bland kvarlevorna av Dreadmaw-krokolisker i Southfury River. När du lämnar den till Misha bekräftar det att han är död.",al={"krons amulett","tecken på krons öde","krokoliskmage"}},{q="Vilken belöning ger Misha?",a="Misha ger dig en gåva som hon hade förberett åt Kron inför hans triumferande återkomst från jakten. Efter att ha fått veta att han dött står hon inte ut med att se på den och ger den till dig, resenären som gav henne ett avslut.",al={"belöning för lost but not forgotten","mishas gåva"}},{q="Varför gav sig Kron av från början?",a="Kron gav sig av av stolthet och för att han ville bevisa sin skicklighet som jägare. När Misha varnade honom för de farliga krokoliskerna blev han arg och stormade ändå iväg för att jaga dem.",al={"varför jagade kron","krons stolthet"}}},fx={ad2ab742={q="Varför vill Misha Tor'kren att det här görs?",a="Misha plågas av att inte veta vad som hänt hennes son. Kron stormade iväg för flera dagar sedan efter ett gräl, fast besluten att visa vad han går för mot farliga bestar. Hon fruktar det värsta, men kan inte börja sörja eller finna ro förrän hon har säkra bevis för hans öde.",al={"varför behöver misha hjälp","misha tor'krens motiv","varför leta efter kron"}},a54100a0={q="Vad är Kron's Amulet till för?",a="Kron's Amulet var en personlig ägodel som Misha's son bar med sig när han gav sig av för att jaga. Den hittades i magen på ett flodvidunder och är ett dystert, obestridligt bevis för hans mor på att Kron dödades längs Southfury River.",al={"krons amulets bakgrund","vad är amuletten","kron amulets syfte"}},a107a32d={q="Vad är det för krokolisker längs Southfury River?",a="Dreadmaw-krokolisker är aggressiva, kraftfulla reptiler som hör hemma i vattendragen och på de leriga stränderna som skiljer Durotar från The Barrens. De är våldsamma och opportunistiska och slukar alla byten som är dumdristiga nog att ensamma ta sig in på deras jaktmarker längs floden.",al={"krokolisker i southfury","varför döda krokolisker","dreadmaw-krokolisker"}}},fp="22,156,16.286.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="Practical Prey",s="Vel'rin Fang behöver jägare som kan föra tigerhudar från Echo Isles till Sen'jin Village. Darkspear behöver förråden när stammen växer och lagren börjar sina.",h="Vel'rin Fang behöver jägare som kan föra tigerhudar från Echo Isles till Sen'jin Village.",kw={"darkspear","durotar tiger","echo isles","jakt","läderarbete","practical prey","sen'jin village","tigerpäls","vel'rin fang"},ang={["class:Hunter"]="Som jägare vet du att tålamod och precision spelar roll. Vel'rin spårade en gång sitt byte i tystnad under en hel dag innan han slog till med sin fälla.",["faction:Horde"]="Som medlem av Horde hjälper du till att försörja den unga enklaven Darkspear och säkra Hordes södra flank längs Great Sea.",["race:Troll"]="Som Darkspear-troll jagar du över Echo Isles, en bitter påminnelse om hemmet som Zalazane tog från ditt folk, samtidigt som du försörjer klanen."},sec={{t="En fråga om överlevnad",b="Darkspear i Sen'jin Village måste hushålla med varje resurs längs Durotars karga kust. Tigerröskinn kan bli tält, filtar och rustningar. När flyktingar anländer och spejare återvänder har byns förråd krympt, och läderarbetaren Vel'rin Fang har skickat ut jägare efter fler hudar."},{t="Balans och jakt",b="Darkspear låter Durotars tigrar vara i stort sett ifred och jagar dem bara när stammen behöver mer förnödenheter. Jägarna tar sig över vattnet till Echo Isles för att spåra rovdjuren. För trollen prövar jakten också tålamod, disciplin och skicklighet i vildmarken."}},faq={{q="Vem är Vel'rin Fang?",a="Vel'rin Fang är en läderarbetare från Darkspear i Sen'jin Village. Han skickar ut jägare för att samla de hudar stammen behöver till kläder, skydd och utrustning.",al={"vel'rin fang","vem ger practical prey","velrin fang"}},{q="Varför behöver Sen'jin Village tigerpälsar?",a="Sen'jin Village behöver tigerröskinn till tält, filtar och rustningar. Den växande befolkningen har tärt på byns förråd.",al={"varför tigerskinn","syftet med practical prey","vad används pälsar till"}},{q="Var finns Durotars tigrar?",a="Durotars tigrar strövar omkring på Echo Isles, strax utanför Durotars sydöstra kust.",al={"var finns tigrarna","tigrarnas plats","tigrar på echo isles"}},{q="Varför jagar trollen inte alla tigrar i närheten?",a="Darkspear låter tigrarna vara tills stammen behöver mer förnödenheter. De jagar bara så mycket som behövs och låter samtidigt rovdjuren frodas.",al={"varför låta tigrar frodas","gallra bland beståndet"}},{q="Har tigerjakt betydelse för Darkspears kultur?",a="Ja. Darkspear ser tigerjakt som ett prov på tålamod och list. Vel'rin väntade en gång nästan en hel dag på Echo Isles innan han tog hem sin första stora jaktseger.",al={"tradition kring tigerjakt","första tigerjakten"}},{q="Varför måste jägarna resa till Echo Isles om Zalazane håller öarna?",a="Zalazane och hans förhäxade undersåtar håller en stor del av Echo Isles, men det finns fortfarande gott om vilda djur. Jakt och födosök längs de yttre stränderna innebär fortfarande risker som Darkspear måste ta.",al={"tigrar på echo isles","varför resa till echo isles"}}},fx={b158745d={q="Vad används Durotar Tiger Fur till?",a="Darkspear-folket gör pälsarna till nödvändiga varor som skyddar och försörjer deras växande bosättning. Vel'rin Fang använder skinnen till att tillverka slitstarka läderrustningar, varma filtar och vädertåliga tält, så att invånarna i Sen'jin Village håller sig skyddade och inte fryser när årstiderna växlar.",al={"vad används durotar tiger fur till","vad är tigerpäls till för","tigerpäls och practical prey"}}},fp="14,137,20.267.0,20.236.0,20.144.0,41.131.0,35.79.0,48.138.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="A Solvent Spirit",s="Master Vornal prövar blivande elever i Sen'jin Village medan synen sviker honom. Han ber dem samla makruraögon och krälarsekret längs Durotars kust. Även om han hånar tanken på att ta en lärling, prövar arbetet tålamod och beslutsamhet.",h="Master Vornal prövar blivande elever i Sen'jin Village medan synen sviker honom.",kw={"alkemi","krälslem","darkspear strand","durotar","helt makruraöga","makrura","master vornal","sen'jin village"},ang={["faction:Horde"]="Kustlandet i Durotar är fortfarande farligt för den spirande Horde. Att röja undan aggressiva makrura och strandkrälarna hjälper till att säkra fiskestränderna kring Sen'jin Village.",["race:Orc"]="Vornal tvivlar öppet på att orcher har den stillsamma disciplin som alkemin kräver. Arbetet ger dig en chans att visa att solidaritet inom Horde också innebär lärd tålamod.",["race:Troll"]="För Darkspear, som återuppbygger Sen'jin Village, hjälper det till att föra stammens mystiska och alkemiska traditioner vidare när du visar dig värdig inför äldre utövare som Master Vornal."},sec={{t="En mästares sviktande syn",b="Master Vornal bor i Sen'jin Village, där åldern har försvagat hans syn. Primalmagi kom en gång lätt till hans fingertoppar, men nu förlitar han sig på alkemi för att skärpa sina sinnen och väva sina konster. Trots att kroppen försvagas vägrar den envisa trollet att ta en lärling. Han säger att varken Darkspear eller Durotars orcher har visat sig värdiga hans undervisning."},{t="På prov",b="Vornal ber om råmaterial från den hårda kusten: intakta makruraögon och flaskor med krälarsekret. Att ta oskadade ögon från bepansrade makrura som snappar efter en kräver varsamma slag. Att samla tillräckligt med sekret prövar om en blivande elev kan stå ut med enformigt arbete. För Vornal handlar jakten på dessa kustvarelser mindre om ingredienserna och mer om att ta reda på vem som kan behålla fokus."},{t="Ett mått på viljan",b="För Master Vornal mäts styrka i tid och tålamod. Han väntar sig att hetsiga ungdomar ska bli frustrerade eller ge upp arbetet. Att återvända till Sen'jin Village med förstklassiga ingredienser visar både överlevnadsförmåga längs de farliga reven i kanalen vid Echo Isles och den disciplin som krävs för att bemästra alkemins subtila konster."}},faq={{q="Vem är Master Vornal?",a="Master Vornal är en ålderstigen trollal kemist och magiker som bor i Sen'jin Village. Åldern försämrar hans syn, så han använder alkemiska lösningsmedel och brygder för att utöva magi som en gång kom lätt för honom.",al={"master vornal","vem är vornal","vornals historia"}},{q="Varför behöver Vornal makruraögon och krälslem?",a="Vornal använder alkemiska blandningar för att hjälpa sin magi och kompensera för den sviktande synen. Han behöver sekretet och de intakta makruraögonen som reagenser, och insamlingen prövar blivande lärlingar.",al={"varför krälslem","varför makruraögon","vad tillverkar vornal"}},{q="Varför är Vornal så ovillig att lära upp en lärling?",a="Vornal förväntar sig stor hängivenhet och tålamod, och har föga överseende med arrogans. Han anser att ingen troll eller orch har visat den hängivenhet han kräver, och ser de flesta blivande elever som stolta och lättmodfällda.",al={"vornals lärling","varför ingen lärling","söker vornal en elev"}},{q="Var finns de här varelserna kring Sen'jin Village?",a="Krälarna och makrura strövar omkring på de grunda vattnen längs Darkspear Strand och i farlederna mellan fastlandet och de närliggande Echo Isles.",al={"var finns makruror","var finns krälar","djur vid darkspear strand"}},{q="Varför måste makruraögonen vara hela?",a="Vornal behöver oskadade sinnesorgan till brygder som skärper sinnena. Ett kraftfullt slag kan krossa en makruras känsliga ögon, så jägaren måste agera precist och behärskat.",al={"helt öga","hela makruraögon","varför hela ögon"}},{q="Vilken läxa försöker Vornal lära ut?",a="Vornal anser att tålamod prövar karaktären. Det enformiga, smutsiga arbetet med att samla längs bränningarna låter honom se om en novis ger efter för brådska eller behåller en alkemists lugna fokus.",al={"vornals läxa","uppdragets innebörd","tålamodsprov"}}},fx={["4926ebef"]={q="Varför behöver Master Vornal en äventyrare i stället för att samla in ingredienserna själv?",a="Master Vornal medger att synen försämras med åldern, så farligt fältarbete längs kusten är olämpligt. Än viktigare är att han använder sysslan som ett avsiktligt prov. Vornal har länge vägrat att ta sig an en lärling eftersom han inte anser att någon troll eller orc han mött är värdig. Genom att skicka dig att samla känsliga ingredienser från fientliga kustvarelser prövar han ditt tålamod, din styrka och din beslutsamhet, för att se om dina handlingar motsvarar ditt självförtroende.",al={"varför jag åt vornal","varför behöver vornal mig","varför skicka en äventyrare"}},cab96330={q="Vilket hot utgör makruror och strandkrypare mot Durotars kust?",a="Makruror är aggressiva, kräftdjursliknande humanoider som hör hemma i Durotars vatten och längs dess stränder, medan strandkrypare är vilda, revirhävdande krabbor som ilar fram längs stränderna och i det grunda vattnet nära Echo Isles. Båda lever i vattnen utanför Darkspear Strand, vilket gör kusten farlig för traktens fiskare och samlare. För Master Vornal är de däremot värdefulla källor till särskilda alkemiska ingredienser som behövs för att kompensera för hans försämrade sinnen.",al={"vad är makruror","makruror i durotar","strandkrypare i sen'jin"}}},fp="16,194,23.343.0,20.348.0,17.315.0,21.196.0,52.200.0,50.212.0,55.127.0,42.180.0,38.161.0"}
P.entries["quest:819"] = {n="Chen's Empty Keg",s="En tunna med Chen Stormstouts märke ligger övergiven i The Barrens. Fyndet pekar mot den kringvandrande bryggmästarens gamla band till Durotar.",h="En tunna med Chen Stormstouts märke ligger övergiven i The Barrens.",kw={"the barrens","bryggning","brewmaster drohn","chen stormstout","tom kagge","pandaren","ratchet","rexxar"},ang={["faction:Horde"]="Som medlem av Horden kan du minnas Chen Stormstout som en ärad allierad som kämpade vid Rexxars och Rokhans sida för att bygga upp Durotar och skydda Horden under dess första dagar.",["profession:Cooking"]="Som kock kan du se Chens tunna som arvet efter en hantverkskunnig bryggare. Hans smak och jakt på sällsynta ingredienser inspirerade hantverkare i hela Kalimdor."},sec={{t="En vandrande relik",b="Resande hittar ibland en övergiven trätunna ute i det torra The Barrens. Razormane quilboar och Kolkar centaur lämnar vanliga tunnor efter sig, men den här är omsorgsfullt tillverkad och har en plakett: ”Chen Stormstout – Må din själ lyftas och alltid lyfta ditt humör.” Det är en märklig relik under Kalimdors sol. För att ta reda på hur den hamnade i The Barrens söker du upp någon som kan bryggning."},{t="Ekon från Durotars grundande",b="Brewmaster Drohn i Ratchet känner igen tunnans hantverk och säger att Chen Stormstout äger den. Chen, en kringvandrande Pandaren, reste med Rexxar under striderna som säkrade Durotar åt Thralls Horde. Många år har gått sedan Chen vandrade på Kalimdors röda jord, men erfarna bryggare minns fortfarande hans recept och kringflackande själ."}},faq={{q="Vad är Chen's Empty Keg?",a="Det är en övergiven bryggningstunna som hittats i The Barrens. Inskriften hedrar den kringvandrande Pandaren-bryggmästaren Chen Stormstout.",al={"tom kagge","chens kagge","vad är den här tunnan"}},{q="Vem är Chen Stormstout?",a="Chen Stormstout är en kringvandrande Pandaren-bryggmästare som reste genom Kalimdor. Han är mest känd för att ha hjälpt Rexxar, en halvojätte och bestmästare, att försvara och bygga upp Durotar.",al={"vem är chen","chen i berättelsen","pandarenbryggmästare"}},{q="Vem ska jag ta kaggen till?",a="Ta tunnan till Brewmaster Drohn, en orcbryggare som är stationerad längs vägen nära Ratchet. Han känner igen Chens märke och vet hur man återskapar hans recept.",al={"var lämnar jag in kaggen","vem vill ha chens kagge","lämna in kagge"}},{q="Varför ligger Chens kagge i The Barrens?",a="Chen strövade runt i Kalimdor för många år sedan på jakt efter exotiska bryggingredienser. Han reste medan han hjälpte den unga Horden att säkra sitt hemland mot Admiral Proudmoores styrkor.",al={"varför ligger kaggen i the barrens","hur hamnade kaggen här"}},{q="Visar sig Chen Stormstout personligen?",a="Nej. Chen har lämnat regionen och har inte synts till i Kalimdor på länge. Hans gamla tunnor, recept och Drohns och Rexxars varma minnen av honom finns kvar.",al={"kan jag hitta chen","var finns chen stormstout","är chen med i classic"}},{q="Vad gör Brewmaster Drohn med kaggen?",a="Drohn välkomnar reliken och utmanar äventyrslystna vandrare att samla in ingredienser från traktens bestar. Han tänker använda dem för att återskapa Chens kraftfulla, legendariska brygder.",al={"drohns uppdragskedja","vad händer sedan med kaggen"}}},fp="16,124,17.383.0,28.343.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:81924"] = {n="Wisdom of the Guardians",s="Bland Feralas sönderslagna ruiner försöker Tyrisius återfinna Kaldoreis forntida läror innan de går förlorade. De gamla stenarna ligger i spillror, men den förlorade visdomens andliga väsen lever kvar i avlägsna helgedomar.",h="Bland Feralas sönderslagna ruiner försöker Tyrisius återfinna Kaldoreis forntida läror innan de går förlorade.",kw={"azshara","feralas","andeväktare","the hinterlands","kaldorei","helgedomar","tyrisius","väktarnas visdom"},ang={["race:NightElf"]="Kaldoreis forntida lärdomar lever kvar, inte i sten, utan i de vilda helgedomarnas uthålliga andar."},sec={{t="Ekon av forntida visdom",b="Tyrisius varnar för att de fysiska nedteckningarna av Kaldoreis kunskap har försvunnit från Feralas stenar. Sten vittrar sönder, men de forntida nattalvernas andliga arv lever kvar på äldre heliga platser i Kalimdor och Eastern Kingdoms.\n\nFör att återfinna det som man trodde var glömt måste du resa till heliga helgedomar spridda över Feralas, Azshara och The Hinterlands. Tyrisius ber dig stå inför andeväktarna som vakar över dessa platser, visa att du är värdig och ta emot de forntida lärorna innan de för alltid bleknar bort."}},faq={{q="Vem är Tyrisius?",a="Tyrisius vakar över Kaldoreis forntida ruiner i Feralas och vägleder dem som söker efter kunskap som finns kvar.",al={"vem är tyrisius","var finns tyrisius"}},{q="Var finns andeväktarna?",a="Andeväktarna vakar över helgedomar i Feralas, Azshara och The Hinterlands.",al={"var finns andarna","andeväktarnas platser","vilka områden ska besökas"}},{q="Varför måste man söka upp andeväktarna?",a="Tyrisius vill bevara Kaldoreis forntida visdom i levande minne innan den för alltid bleknar bort från världen.",al={"varför besöka helgedomarna","vad är målet"}},{q="Hur hittar du andeväktarna?",a="Varje andeväktare finns vid sin egen helgedom i de forntida länderna.",al={"hur känner man igen andarna","hitta helgedomarna"}},{q="Vilka ruiner vakar Tyrisius över?",a="Tyrisius står bland Kaldoreis fallna ruiner, där de fysiska nedteckningarna av alvernas forntida kunskap har vittrat sönder.",al={"vilka ruiner är det här","ruiner i feralas"}},{q="Vart återvänder du efter att ha talat med andarna?",a="När du har visat dig värdig inför varje ande väntar Tyrisius på dig i Feralas.",al={"vart efter helgedomarna","vem ska man återvända till"}}},fp="23,221,24.533.0,16.110.0,40.81.0,40.112.0,37.70.0,36.117.0,52.85.0"}
P.entries["quest:8193"] = {n="Master Angler",s="Varje söndag söker en fisketävling de främsta sportfiskarna. Var bland de första femtio som lämnar in Tastyfish från stimmen längs kusterna i Stranglethorn för att utses till Master Angler.",h="Varje söndag söker en fisketävling de främsta sportfiskarna.",kw={"fisketävling","fiske","fiskstim","master angler","stranglethorn","söndag","tastyfish"},sec={{t="Söndagens tävling",b="Tävlingen är öppen varje söndag, och du kan få titeln Master Angler genom att vara bland de första femtio som lämnar in Tastyfish till arrangören. Fiskarna finns i stim längs kusterna i Stranglethorn, och de blir snabbt dåliga."},{t="Ett andra erbjudande",b="Om du kommer för sent för att ta en av de första femtio platserna betalar arrangörens lärling dig ändå för Tastyfish. Fiskarna håller sig inte till nästa söndag."}},faq={{q="När är fisketävlingen?",a="Tävlingen äger rum varje söndag.",al={"dag för master angler","vilken dag är fisketävlingen"}},{q="Var hittar jag Tastyfish?",a="Stim med Tastyfish finns längs kusterna i Stranglethorn.",al={"plats för tastyfish","var fiskas tastyfish"}},{q="Hur blir jag Master Angler?",a="Var bland de första femtio som lämnar in Tastyfish till tävlingens arrangör.",al={"krav för master angler","vinna fisketävlingen"}},{q="Vad händer om jag kommer för sent?",a="Arrangörens lärling betalar dig för Tastyfish om du kommer för sent för att vara bland de första femtio.",al={"missat tävlingen","för långsamt fiske"}},{q="Kan jag spara Tastyfish till nästa vecka?",a="Nej. Tastyfish blir snabbt dåliga, så de kan inte sparas till nästa söndag.",al={"blir tastyfish dåliga","spara fisk till söndag"}}},fp="13,169,18.231.0,14.157.0,28.37.0,26.62.0,32.70.0,26.104.0,35.73.0"}
P.entries["quest:81947"] = {n="Sanguine Sorcery",s="En bibliotekarie söker magiska verk till biblioteket i Ironforge. Ditt bidrag utökar samlingen och kunskapen.",h="En bibliotekarie söker magiska verk till biblioteket i Ironforge.",kw={"samling","ironforge","kunskap","bibliotek","magiska verk","sanguine sorcery"},sec={{t="En växande samling",b="På biblioteket i Ironforge ber en bibliotekarie dig ta med något till samlingen. Ditt bidrag hjälper till att utöka bibliotekets kunskap."}},faq={{q="Vad vill bibliotekarien ha?",a="Bibliotekarien ber dig ta med något till samlingen.",al={"vad vill de ha","biblioteksförfrågan","sanguine sorcery"}},{q="Varifrån kommer förfrågan?",a="Förfrågan kommer från biblioteket i Ironforge.",al={"var finns bibliotekarien","biblioteket i ironforge","bibliotekets plats"}},{q="Varför ta med magiska verk till biblioteket?",a="Bibliotekarien säger att magiska verk kan komma biblioteket till nytta och utöka dess kunskap.",al={"varför magiska böcker","vad är det till för","bibliotekets samling"}}},fp="16,117,20.144.0,29.67.0,27.48.0,39.82.0"}
P.entries["quest:81949"] = {n="Legends of the Tidesages",s="En bok med sällsynt lärdom har nått biblioteket i Ironforge. Där välkomnar de lärde sådana tillskott och vill utöka sin samling av magisk kunskap.",h="En bok med sällsynt lärdom har nått biblioteket i Ironforge.",kw={"samling","ironforge","legends of the tidesages","bibliotek","magiska verk","tidesages","bok"},sec={{t="Att samla kunskap",b="De lärde i Ironforge vill bredda sin förståelse för magisk och historisk lärdom. Varje volym som hämtas från världen bevarar kunskap som annars kanske skulle falla i glömska."}},faq={{q="Vad är Legends of the Tidesages?",a="Det är en magisk bok som levererats för att utöka arkiven i biblioteket i Ironforge.",al={"vad är legends of the tidesages","vad är det här för bok","tidesages bok"}},{q="Vem vill ha boken?",a="De lärde vid biblioteket i Ironforge tar emot verket för att bevara dess kunskap och utöka sin samling.",al={"vem vill ha legends of the tidesages","vart lämnar jag legends of the tidesages","vem tar emot boken"}},{q="Går det att ta fler böcker till biblioteket?",a="De lärde ber dig ta med alla andra magiska skrifter du hittar som kan vara till nytta för biblioteket.",al={"vad händer efter legends of the tidesages","fler böcker till biblioteket","kan jag ta med fler böcker"}}},fp="24,161,19.190.0,33.82.0,19.107.0,41.105.0"}
P.entries["quest:81952"] = {n="Everyday Etiquette",s="En biblioteksvärd söker magiska verk att lägga till i samlingen. Ditt bidrag hjälper till att utöka bibliotekets kunskap.",h="En biblioteksvärd söker magiska verk att lägga till i samlingen.",kw={"samling","vardagsetikett","ironforge","kunskap","bibliotek","magiska verk"},sec={{t="En växande samling",b="Väktaren vid Library i Ironforge ber dig ta med magiska verk som kan vara till nytta för samlingen. Dina insatser hjälper bibliotekets kunskap att växa."}},faq={{q="Vad vill biblioteksväktaren ha?",a="Väktaren söker magiska verk som kan vara till nytta för biblioteket.",al={"biblioteksböcker","magiska verk","vad du ska ta med"}},{q="Var utspelar sig detta?",a="Förfrågan gäller Library i Ironforge.",al={"bibliotekets plats","var ligger biblioteket","biblioteket i ironforge"}},{q="Varför samlas magiska verk in?",a="Väktaren säger att varje bidrag utökar bibliotekets kunskap.",al={"varför samla böcker","syftet med bibliotekssamlingen","vad till"}}},fp="18,120,20.155.0,34.62.0,27.46.0,38.68.0"}
P.entries["quest:82"] = {n="Noxious Lair Investigation",s="Senior Surveyor Fizzledowser vill veta vem fienden är. Insekter har tömt vattenhålorna där The Noxious Lair nu ligger, och mycket lite annat är känt om dem. Du får i uppdrag att ta fem insektsdelar från Centipaar i hålan och föra dem till Alchemist Pestlezugg i Gadgetzan.",h="Senior Surveyor Fizzledowser vill veta vem fienden är.",kw={"centipaar","fizzledowser","gadgetzan","insekter","the noxious lair","pestlezugg","tanaris"},sec={{t="Delar från hålan",b="Efter Gadgetzan Water Survey vänder sig Senior Surveyor Fizzledowser till rapporterna om insekterna. Det enda man vet är att de tömmer vattenhålorna som en gång låg där The Noxious Lair nu finns. Fizzledowser vill först ta reda på vem fienden är och ber dig gå in i hålan, ta fem delar från Centipaar där och bära dem tillbaka till Gadgetzan, till alkemisten Pestlezugg, för undersökning."},{t="Vad Pestlezugg upptäcker",b="Pestlezugg börjar genast undersöka delarna och säger direkt att de inte liknar någon tidigare känd insektsform, nästan som om en yttre kraft styrde insekterna. Pestlezugg skickar dig sedan tillbaka till Fizzledowser, för du behövs i ett nödläge som kan beröra fler insekter i Tanaris."}},faq={{q="Varför vill Senior Surveyor Fizzledowser ha insektsdelar?",a="Insekter tömmer vattenhålorna som en gång låg där The Noxious Lair nu finns, och mycket lite annat är känt om dem. Delar från Centipaar ska hjälpa Pestlezugg att ta reda på vad de är.",al={"varför samla insektsdelar","fizzledowser insektsdelar","noxious lairs syfte"}},{q="Var finns Centipaar?",a="Centipaar finns i The Noxious Lair, där det tidigare låg vattenhålor.",al={"var ligger noxious lair","centipaars plats","var hittar man centipaar"}},{q="Vem tar emot insektsdelarna i Gadgetzan?",a="Alchemist Pestlezugg i Gadgetzan, som ska undersöka dem.",al={"vem ska få delarna","pestlezzugs plats","vem vill ha insektsdelarna"}},{q="Vad kommer före det här steget?",a="Det följer efter Gadgetzan Water Survey.",al={"föregående uppdrag","förutsättningsuppdrag","vad leder hit"}}},fp="26,219,19.364.0,21.280.1,56.176.0,30.72.0,43.76.0,28.38.0"}
P.entries["quest:821"] = {n="Chen's Empty Keg",s="I Ratchet hoppas Brewmaster Drohn återuppliva Chen Stormstouts kraftfulla brygd med vilda ingredienser från The Barrens.",h="I Ratchet hoppas Brewmaster Drohn återuppliva Chen Stormstouts kraftfulla brygd med vilda ingredienser från...",kw={"brewmaster drohn","chen stormstout","tunna","plainstrider kidney","ratchet","savannah lion tusk","the barrens","thunder lizard horn","troggbrygd"},ang={["faction:Horde"]="Chen Stormstout kämpade sida vid sida med Rexxar för att hjälpa till att grunda Durotar, vilket ger minnen från hans resa en särskild kulturell betydelse för Horden.",["profession:Cooking"]="För en kock är det här en oroväckande blandning av gränsbygdens slakt och fin bryggkonst i skapandet av legendariska spritsorter från Kalimdor.",["race:Orc"]="Som orc kan du se Drohn som ett exempel på hur orcer tar till sig urgamla bryggmästartraditioner, förmedlade av resenärer som vandrade med den tidiga Horden."},sec={{t="Ett arv på fat",b="En märkt kagge får Brewmaster Drohn i Ratchet att tänka på Chen Stormstout. Chen anförtrodde hemligheterna bakom sin brygd, som bär hans namn, åt Drohns mentor, som i sin tur överlät dem åt Drohn. Receptet kräver råa, kraftfulla ämnen direkt från The Barrens vilda djurliv, ett ovanligt val för den som står utanför bryggaryrket."},{t="Skörd på savannen",b="För att återuppliva Chens kraftfulla brygd samlar du in plainstrider njurar, savannlejonbetar och ett thunder lizard-horn. Ingredienserna måste komma från tåliga bestar, så jakten går över de dammiga slätterna. När du tar dem till Drohn minns han med värme tidigare satser av troggbrygd. Att återuppliva det gamla receptet värmer magen nästan lika mycket som de forna brygderna."}},faq={{q="Vem är Brewmaster Drohn?",a="Brewmaster Drohn är en orcisk bryggmästare i hamnstaden Ratchet. Hans mentor fick recept av den kringvandrande Chen Stormstout och förde bryggarkonsten vidare till Drohn.",al={"brewmaster drohn","vem är drohn","drohn i ratchet"}},{q="Varför kräver ett ölrecept djurnjurar och horn?",a="Pandarenbryggningens traditioner och anpassningar vid gränsbygderna använder kraftfulla, esoteriska ingredienser från det lokala djurlivet. De ger kraft, sting och tydliga naturliga essenser åt starka brygder.",al={"varför djurdelar","plainstridernjurar i brygd","lejonbetar i öl"}},{q="Var hittar man ingredienserna?",a="Plainstriders och savannlejon strövar över The Barrens öppna gräsmarker. Thunder lizards betar i de torrare eller stenigare delarna.",al={"var hittar man betar","var finns åsködlor","hitta bryggingredienser"}},{q="Vem var Chen Stormstout?",a="Chen Stormstout är en kringvandrande pandarenbryggmästare som färdades genom Kalimdor under grundandet av Durotar. Han hjälpte Horden medan han sökte sällsynta, exotiska ingredienser för att fullända sina kraftfulla ölsorter.",al={"vem är chen","chen stormstout-lore","chen"}},{q="Vad händer när man lämnar ingredienserna till Drohn?",a="När du ger Drohn lejonbetarna, plainstridernjurarna och thunder lizard-hornet blir han överlycklig. Ingredienserna påminner honom om hans tidiga bryggardagar och leder in i den sista fasen av att återskapa brygden.",al={"nästa uppdrag efter chens empty keg","drohns belöning","vad händer sedan"}},{q="Vad är troggbrygden som Drohn nämner?",a="Drohn minns med värme troggbrygd när han ser de vilda ingredienserna. Hans minnen visar hans excentriska historia av att jäsa sträva, ovanliga brygder i gränsbygden.",al={"troggbrygd","drohn och troggbrygd","troggöl"}}},fx={cd71a987={q="Varför vill Brewmaster Drohn ha de här ingredienserna?",a="Brewmaster Drohn vill återskapa det legendariska Stormstout-brygget, en exotisk och kraftfull dryck som fördes vidare från Chen Stormstout till Drohns mentor och slutligen till honom. Att tillreda brygget väcker nostalgi och stolthet hos Drohn, påminner honom varmt om berömda brygder från förr och hedrar teknikerna som den kringvandrande pandarenmästaren lämnade efter sig.",al={"varför vill drohn ha detta","drohns motiv","varför brygga drycken"}}},fp="16,109,17.301.0,23.360.1,24.167.0,56.181.0,44.124.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="Chen's Empty Keg",s="I Ratchet vänder sig Brewmaster Drohn till ännu ett recept som Chen Stormstout delade med sig av. Troggöl kräver sällsynta organ och körtlar från Barrens vilda djur.",h="I Ratchet vänder sig Brewmaster Drohn till ännu ett recept som Chen Stormstout delade med sig av.",kw={"barrens","brewmaster drohn","chen stormstout","chen's empty keg","kodo liver","ratchet","stormhide","thunderhawk","trogg ale"},ang={["faction:Horde"]="Som medlem av Horde delar du en historia med Chen Stormstout, som stred tillsammans med Horde i försvaret av Durotar. Hans tid där gjorde ett bestående intryck på orcher som Drohn.",["profession:Cooking"]="Troggöl kanske stöter sig med finsmakare, men bruket att använda mustigt organkött och kraftfulla körtlar följer gränslandets sed att inte slösa något från ett fällt djur.",["race:Orc"]="Som orch kanske du tycker att Drohns väg är ovanlig: han valde Chens exotiska bryggmetoder framför den traditionella krigarbanan och driver sin verksamhet i Ratchet."},sec={{t="En andra pandarenformel",b="Efter att ha hjälpt Brewmaster Drohn återskapa Chen Stormstouts första brygd får du veta att den vandrande pandaren delade med sig av mer än en brygghemlighet. Drohn har formeln för troggöl, en märklig dryck som inte görs på spannmål, utan på kraftfulla delar från de vilda djuren i centrala Kalimdor."},{t="Ingredienserna i trogg ale",b="För att brygga troggöl behöver Drohn blixtkörtlar från stormhides, en Thunderhawk Saliva Gland från greater thunderhawks och en rejäl lever från Barrens kringströvande kodoer. När ingredienserna destilleras blir de en intensivt uppiggande dryck för livet i vildmarken."},{t="Ett långvarigt samarbete",b="Brewmaster Drohn håller överenskommelsen öppen för resenärer och legoknektar som passerar genom Ratchet. Ta med en ny omgång djurorgan till honom, så brygger han gärna mer troggöl."}},faq={{q="Vem är Chen Stormstout?",a="Chen Stormstout är en svårfångad pandarenbryggmästare som vandrade genom Kalimdor under grundandet av Durotar. Han delade några av sina kraftfulla bryggmetoder med Drohn i Ratchet innan han fortsatte sina resor.",al={"vem är chen","chens historia","pandaren chen"}},{q="Var finns Brewmaster Drohn?",a="Brewmaster Drohn finns i Ratchet, den neutrala hamnen på Barrens östra kust. Han ägnar dagarna åt att förfina brygder han lärde sig av Chen.",al={"drohns plats","var finns brewmaster drohn","drohn npc"}},{q="Vad är trogg ale?",a="Troggöl är en kraftfull brygd som Chen lärde Drohn att göra. Den innehåller djurkörtlar och organ i stället för vanliga humlekottar, vilket ger den en rejäl kick för härdade äventyrare.",al={"trogg ale","vad är det här för dryck","vad brygger drohn"}},{q="Var samlar man in blixtkörtlar?",a="Du kan samla blixtkörtlar från stormhide-djur som strövar omkring i Barrens torra marker. Deras kroppar bär på naturliga elektriska laddningar.",al={"källa till blixtkörtel","stormhides plats","var får man blixtkörtel"}},{q="Vilka bestar lämnar thunderhawks spottkörtlar efter sig?",a="Greater thunderhawks har de spottkörtlar Drohn behöver. Dessa fågelrovdjur jagar i den öppna himlen över Barrens.",al={"thunderhawk saliva gland","var finns större thunderhawks","thunderhawks plats"}},{q="Kan jag brygga trogg ale mer än en gång?",a="Ja. Brewmaster Drohn brygger mer troggöl när äventyrare kommer med färska körtlar och en kodo-lever.",al={"går det att upprepa","kan jag göra det igen","upprepa trogg ale"}}},fx={["72ec56fd"]={q="Varför vill Brewmaster Drohn ha de här ingredienserna?",a="Drohn vill gärna dela med sig av ännu ett exotiskt recept som han lärde sig direkt av den kringvandrande bryggmästaren Chen Stormstout. Efter att redan ha väglett dig i att återskapa Chens uppskattade stout vill Drohn brygga en sats kraftfullt troggöl, en brygd med rejäl styrka som ska stärka och hjälpa de tåliga äventyrare som trotsar farorna i The Barrens.",al={"varför vill drohn ha detta","brewmaster drohns motiv","varför brygga troggöl"}},["63499675"]={q="Vad används Lightning Gland till?",a="Lightning Gland är en av ingredienserna i Chens recept på troggöl. Drohn ber om fem stycken, insamlade från stormhudar i The Barrens.",al={"varför lightning gland","lightning gland i historien","vad används lightning gland till"}},["4ecc81d9"]={q="Vad används Thunderhawk Saliva Gland till?",a="Drohn behöver en salivkörtel från en större åskhök för att brygga Chens troggöl. Han förklarar inte vilken exakt roll körteln har i bryggningen.",al={"varför thunderhawk saliva gland","thunderhawk saliva gland användning","vad används åskhökssaliv till"}},["315602f6"]={q="Vad används Kodo Liver till?",a="En kodo-lever är en av ingredienserna Drohn behöver till Chens troggöl. Han godtar en lever från vilken kodo som helst i The Barrens.",al={"varför kodo liver","kodo liver i historien","vad är kodo liver till för"}}},fp="16,154,25.261.0,28.252.0,23.181.1,23.209.0,34.145.0,18.176.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:8225"] = {n="Rare Fish - Brownell's Blue Striped Racer",s="Ett fiskerekord markerar Brownell's Blue Striped Racer som identifierad. Identifieringen är slutförd.",h="Ett fiskerekord markerar Brownell's Blue Striped Racer som identifierad.",kw={"brownell's blue striped racer","brownell's racer","fiskidentifiering","sällsynt fisk","belöning"},sec={{t="Rekordet",b="En kort signal följer efter identifieringen av Brownell's Racer. Brownell's Blue Striped Racer markeras som slutförd, och en belöning finns tillgänglig."}},faq={{q="Vad är Brownell's Blue Striped Racer?",a="Brownell's Blue Striped Racer är fisken vars identifiering markeras som slutförd.",al={"brownells racer","blårandig fisk"}},{q="Är identifieringen slutförd?",a="Ja. Identifieringen av Brownell's Racer är slutförd.",al={"fiskidentifiering","racer identifierad"}},{q="Finns det en belöning?",a="Ja. En belöning finns tillgänglig när identifieringen är slutförd.",al={"fiskbelöning","vad får jag"}}},fp="41,99,10.139.0,38.82.0,31.56.0,22.64.0"}
P.entries["quest:8228"] = {n="Could I get a Fishing Flier?",s="En Fishing Contest utlyses i Booty Bay till på söndag. Flygbladet anger tävlingsreglerna för dig som vill delta.",h="En Fishing Contest utlyses i Booty Bay till på söndag.",kw={"booty bay","fisketävling","fiskeflygblad","fiskeregler","turnering"},sec={{t="Turneringsregler",b="Meddelandet ger dig reglerna för Fishing Contest i Booty Bay. Tävlingen hålls på söndag, och du kan läsa på flygbladet hur den går till innan du bestämmer dig för att delta."}},faq={{q="När hålls Fishing Contest?",a="Fishing Contest i Booty Bay hålls på söndag.",al={"när är fisketävlingen","vilken dag är det"}},{q="Var hålls Fishing Contest?",a="Fishing Contest hålls i Booty Bay.",al={"fisketävlingens plats","var är tävlingen"}},{q="Vad står det på fiskeflygbladet?",a="Flygbladet anger reglerna för Fishing Contest.",al={"information om fiskeflygblad","vad står på flygbladet"}},{q="Kan jag delta i turneringen?",a="Meddelandet innehåller reglerna för dig som vill delta i Fishing Contest.",al={"delta i fisketurnering","delta i tävlingen"}}},fp="28,124,16.195.0,28.48.0,29.36.0,36.53.0,36.78.0"}
P.entries["quest:823"] = {n="Report to Orgnil",s="Master Gadrin skickar bud från Sen'jin Village till Razor Hill om Burning Blade. Denna tidiga rapport från Horde varnar för demonisk korruption som sprider sig genom Durotar.",h="Master Gadrin skickar bud från Sen'jin Village till Razor Hill om Burning Blade.",kw={"burning blade","durotar","master gadrin","orgnil soulscar","razor hill","report to orgnil","sen'jin village"},ang={["faction:Horde"]="Som medlem av Horde förlitar du dig på ett viktigt samarbete mellan de nyligen allierade Darkspear-trollen och Durotars orcher när de möter gemensamma hot.",["race:Orc"]="Som ork kan du se Orgnil Soulscar som en försvarare av ditt hemland, som arbetar för att hindra demonisk korruption från att slå rot i Durotar.",["race:Troll"]="Även om Darkspear är upptagna med sin kamp mot Zalazane visar Master Gadrin trollens engagemang för Horde genom att varna orchledarna för faror i hela regionen."},sec={{t="Ett samordnat försvar",b="Sen'jin Village har egna problem, särskilt Zalazanes förräderi på Echo Isles. Ändå pekar rapporterna om Burning Blade på en fara som sträcker sig långt bortom byns bekymmer. Demonisk korruption upptäcktes i Valley of Trials, och Master Gadrin vet att hotet inte kan mötas på egen hand. Han skickar dig norrut längs vägen till Razor Hill, där orcherna vakar över Durotar."},{t="Orgnil Soulscar",b="Orgnil Soulscar är stationerad vid Razor Hills militärläger, med uppdraget att utrota ondskan i Durotar och skydda dess centrala landområden. När du överlämnar Gadrins varning sammanför Orgnil rapporterna från Sen'jin Village och Valley of Trials. Burning Blades räckvidd är oroväckande nära, så han mobiliserar snabbt styrkor för att skingra kultisterna innan deras ritualer kan rubba den unga nationen."}},faq={{q="Vem ger uppdraget Report to Orgnil?",a="Master Gadrin, Darkspear-trollens häxdoktor och andlige ledare i Sen'jin Village, skickar iväg dig efter att du hjälpt trollen med deras första lokala problem.",al={"vem ger report to orgnil","var får man report to orgnil","uppdragsgivare för report to orgnil"}},{q="Var finns Orgnil Soulscar?",a="Orgnil Soulscar finns i Razor Hill, den befästa bosättningen norr om Sen'jin Village i centrala Durotar.",al={"var finns orgnil soulscar","orgnil soulscars plats","hitta orgnil soulscar"}},{q="Varför skickar Master Gadrin dig till Razor Hill?",a="Master Gadrin inser att demonisk kultverksamhet i Valley of Trials och runt Durotar hotar alla, inte bara trollen. Han skickar dig till Orgnil Soulscar, orchen som har i uppdrag att skydda regionen mot Burning Blade.",al={"varför report to orgnil","varför gå till razor hill","syftet med report to orgnil"}},{q="Vad är Burning Blade som nämns i uppdraget?",a="Burning Blade är en hemlig kult av demondyrkare som verkar i Durotars skuggor och bortom dem. Dess dolda närvaro i närliggande raviner och grottor hotar den unga Hordes säkerhet och stabilitet.",al={"vilka är burning blade","burning blade-kulten","vad är burning blade"}},{q="Vilket uppdrag följer efter Report to Orgnil?",a="När du överlämnar rapporten till Orgnil Soulscar i Razor Hill ger han dig genast Dark Storms och skickar dig för att undersöka och bekämpa det växande kultisthotet.",al={"nästa uppdrag efter report to orgnil","uppföljning till report to orgnil","vad kommer efter report to orgnil"}},{q="Vilket förkunskapskrav måste uppfyllas innan du får det här uppdraget?",a="Detta följer på din ankomst till Sen'jin Village i Report to Sen'jin Village och knyter det du upptäckte i Valley of Trials till den större kampanjen i Durotar.",al={"förkunskapskrav för report to orgnil","hur låser man upp report to orgnil","föregående uppdrag till report to orgnil"}}},fp="16,138,21.361.0,15.375.0,37.151.0,33.103.0,46.230.0,49.194.0,36.156.0,64.158.0"}
P.entries["quest:8234"] = {n="Sealed Azure Bag",s="I Azshara ombeds du hämta en förseglad påse från en Timbermaw Shaman och ta den till Archmage Xylem. Begäran knyter shamanen och magikern samman genom påsen.",h="I Azshara ombeds du hämta en förseglad påse från en Timbermaw Shaman och ta den till Archmage Xylem.",kw={"archmage xylem","azshara","påse","sealed azure bag","timbermaw shaman"},sec={{t="En förseglad påse",b="En Timbermaw Shaman i Azshara har Sealed Azure Bag, och Archmage Xylem väntar på den i samma land. Du ombeds bära påsen från den ena till den andra."}},faq={{q="Vem har Sealed Azure Bag?",a="En Timbermaw Shaman i Azshara har Sealed Azure Bag.",al={"vem har påsen","timbermaw-påse"}},{q="Vem vill ha påsen?",a="Archmage Xylem i Azshara ska få Sealed Azure Bag.",al={"vem får påsen","var ta påsen"}},{q="Var hittar jag påsen?",a="Sealed Azure Bag finns hos en Timbermaw Shaman i Azshara.",al={"påsens plats","var finns sealed azure bag"}},{q="Var finns Archmage Xylem?",a="Archmage Xylem finns i Azshara.",al={"xylems plats","var finns xylem"}}},fp="16,164,12.164.0,29.55.0,18.61.0,24.59.0,24.29.0"}
P.entries["quest:824"] = {n="Je'neu of the Earthen Ring",s="Det här uppdraget skickar Horde-äventyrare för att lämna en fördärvad vattenkula, återfunnen bland Ashenvales elementarvarelser, till Je'neu Sancrea i Earthen Ring. Som schaman hängiven elementär harmoni vill Je'neu förstå hur fördärvet sprider sig längs The Zoram Strand och inne i Blackfathom Deeps. Att studera reliken ger hopp om att hejda den onaturliga farsot som förgiftar regionens vatten.",h="Det här uppdraget skickar Horde-äventyrare för att lämna en fördärvad vattenkula, återfunnen bland Ashenvales...",kw={"befouled water globe","blackfathom deeps","earthen ring","elementarvarelser","je'neu sancrea","mastok wrilehiss","the zoram strand","zoram'gar outpost"},ang={["class:Shaman"]="Uppgiften berör direkt schamanernas plikt att upprätthålla elementär balans. Genom att lämna över den fördärvade kulan hjälper du en annan medlem av Earthen Ring att diagnostisera en farlig andlig sjukdom.",["faction:Horde"]="När Horde upprättar befästa läger som Zoram'gar Outpost i Ashenvale är det viktigt att avslöja de mörka ursprungen till den lokala fientligheten från elementarvarelserna för att säkra kusten.",["race:Troll"]="Je'neu Sancrea visar Darkspears djupa andliga visdom och använder sitt förfädersband till andarna i Earthen Rings tjänst."},sec={{t="En budbärare åt elementen",b="När märkliga, förorenade elementarvarelser började dyka upp i Ashenvale lade spejare märke till den onaturliga kraft som gav dem liv. Bland lämningarna låg en besudlad vattenkula, ett intakt kärl som pulserade av fördärvad magi. Eftersom vanliga soldater och spejare saknade den andliga insikt som krävdes för att förstå en sådan avvikelse, skickade Mastok Wrilehiss Horde-resenärer för att söka upp någon med djup kunskap om forntida legender och elementär lära: Je'neu Sancrea."},{t="Earthen Rings ögon",b="Je'neu Sancrea tillhör Earthen Ring, en orden av schamaner som arbetar för att bevara balansen mellan Azeroths urkrafter. Medan Horde-styrkor vaktar gränsen längs The Zoram Strand koncentrerar sig Je'neu på det andliga sår som ruttnar i de närbelägna tempelruinerna i Blackfathom Deeps. För honom är en elementarvarelse som hämtar kraft ur ett besmittat kärl inte bara ett isolerat hot, utan ett oroande omen om att osedda, uråldriga krafter förvrider den naturliga ordningen."}},faq={{q="Vem är Je'neu Sancrea?",a="Je'neu Sancrea är en trollschaman som företräder Earthen Ring i norra Kalimdor. Han ägnar sitt liv åt att tala med och studera elementen och håller till nära The Zoram Strand för att undersöka mörka störningar som stiger upp från Blackfathom Deeps.",al={"vem är jeneu","jeneu sancreas bakgrund","vad gör jeneu här"}},{q="Vad är Earthen Ring?",a="Earthen Ring är en organisation av schamaner som arbetar för att hålla Azeroths uråldriga element i harmoni. De utforskar forntida kunskap, bortglömda andar och gamla legender för att råda bot på elementärt kaos och läka andligt fördärv världen över.",al={"vad är earthen ring","vilka är earthen ring","earthen rings bakgrund"}},{q="Var finns Je'neu Sancrea?",a="Je'neu finns vid Zoram'gar Outpost på kusten vid The Zoram Strand i Ashenvale, där han studerar de elementära störningar som stiger upp från närbelägna Blackfathom Deeps.",al={"var finns jeneu","jeneus plats","hitta jeneu sancrea"}},{q="Vad är Befouled Water Globe?",a="Kulan är en magisk ledare genom vilken mäktiga vattenelementarvarelser kanaliserar sin styrka. Att hitta en som är fördärvad men intakt tyder på att mörka krafter i området medvetet förvrider och förslavar de lokala andarna.",al={"vad är kulan","befouled globes bakgrund","vattenkula"}},{q="Vem skickar dig för att tala med Je'neu?",a="Mastok Wrilehiss, en Horde-officer stationerad i Ashenvale, skickar äventyrare för att lämna den besmittade reliken till Je'neu efter att ha insett att armén inte kan tyda dess märkliga magiska natur.",al={"vem ger uppdraget","mastoks uppdrag"}},{q="Vad ska Je'neu göra med kulan?",a="Je'neu tar hand om kärlet så att Earthen Ring kan undersöka fördärvets natur. Han hoppas att forskningen ska avslöja ett sätt att rena vattnet och återställa freden bland regionens plågade elementarvarelser.",al={"vad händer med kulan","bota fördärvet"}}},fx={["5c718e13"]={q="Varför skickar Mastok Wrilehiss dig till Je'neu?",a="Mastok inser att Befouled Water Globe ligger långt utanför hans expertis. Förståelsen av förvriden magi, gamla legender och störda elementaler hör helt till The Earthen Rings område. Han skickar dig till Je'neu Sancrea eftersom Je'neu är en lokal schaman inom ringen med den djupa elementarkunskap som krävs för att reda ut klotets verkliga betydelse och hot.",al={"mastok wrilehiss motiv","varför skicka till je'neu","varför vill mastok att detta görs"}}},fp="26,308,28.440.0,28.407.0,22.235.0,25.234.0,34.173.0,33.220.0,35.168.0,35.188.0"}
P.entries["quest:8241"] = {n="Restoring Fiery Flux Supplies via Iron",s="Efter What the Flux? tar Master Smith Burninate itu med att fylla på det sinande förrådet av Fiery Flux i Searing Gorge. Burninate vill ha incendosaur scales, iron bars och coal, och tar emot allt du kan erbjuda.",h="Efter What the Flux?",kw={"kol","fiery flux","incendosaur scale","järnstång","master smith burninate","fylla på fiery flux med järn","searing gorge","thorium brotherhood"},sec={{t="Fiery Flux sökes",b="Master Smith Burninate har inte tid med tomt prat. Förrådet av Fiery Flux börjar sina, och Burninate ber om incendosaur scales, iron bars och coal: två scales, fyra iron bars och coal. Burninate tar emot allt du kan erbjuda."}},faq={{q="Vem ber om varorna?",a="Master Smith Burninate i Searing Gorge, som tar emot varorna personligen.",al={"vem ger uppdraget","burninate fiery flux","var lämnar man in"}},{q="Vilka material vill Burninate ha?",a="Två incendosaur scales, fyra iron bars och lite coal.",al={"vilka föremål behöver jag","material till fiery flux","föremål att lämna till burninate"}},{q="Vad kom före den här begäran?",a="Steget som heter What the Flux?, som Burninate gav dig tidigare.",al={"förutsättning för uppdraget","föregående uppdrag fiery flux","what the flux som förutsättning"}},{q="Varför vill Burninate ha varorna?",a="Burninate säger att förrådet av Fiery Flux sinar och vill fylla på det.",al={"varför fiery flux","burninates motiv"}}},fp="38,190,17.196.0,25.91.0,35.65.0,30.70.0,36.88.0"}
P.entries["quest:8242"] = {n="Restoring Fiery Flux Supplies via Heavy Leather",s="Efter What the Flux? tar Master Smith Burninate itu med att fylla på det sinande förrådet av Fiery Flux i Searing Gorge. Burninate vill ha incendosaurfjäll, Heavy Leather och kol, och tar emot allt du kan erbjuda.",h="Efter What the Flux?",kw={"burninate","kol","fiery flux","heavy leather","incendosaurfjäll","searing gorge","thorium brotherhood"},sec={{t="Fiery Flux sökes",b="Master Smith Burninate har inte tid med tomt prat. Förrådet av Fiery Flux börjar sina, och Burninate ber om incendosaurfjäll, Heavy Leather och kol: två fjäll, tio stycken Heavy Leather och kol. Burninate tar emot allt du kan erbjuda."}},faq={{q="Vem ber om varorna?",a="Master Smith Burninate i Searing Gorge, som tar emot varorna personligen.",al={"vem ger uppdraget","burninate fiery flux","var lämnar jag in"}},{q="Vilka material vill Burninate ha?",a="Två incendosaurfjäll, tio stycken Heavy Leather och lite kol.",al={"vilka föremål behöver jag","material till fiery flux","föremål att lämna till burninate"}},{q="Vad föregick den här begäran?",a="Steget som heter What the Flux?, som Burninate gav dig tidigare.",al={"förkunskapskrav för uppdraget","föregående uppdrag fiery flux","förkunskapskrav what the flux"}},{q="Varför vill Burninate ha varorna?",a="Burninate säger att förrådet av Fiery Flux håller på att sina och vill fylla på det.",al={"varför fiery flux","burninates motiv"}}},fp="47,202,17.200.0,25.91.0,35.78.0,30.55.0,36.75.0"}
P.entries["quest:8249"] = {n="Junkboxes Needed",s="På Ravenholdt Manor behöver Fahrad ständigt rejäla, låsta behållare för att träna gillets lovande skurkar. Eftersom övningslåsen från herrgårdens egen hantverkare är för enkla för avancerade elever byter Fahrad specialgjorda kastknivar mot äkta tunga skräplådor från alla som vill leverera dem.",h="På Ravenholdt Manor behöver Fahrad ständigt rejäla, låsta behållare för att träna gillets lovande skurkar.",kw={"tung skräplåda","hillsbrad","skräplådor","låsdyrkning","ficktjuveri","ravenholdt","fahrad","zan"},ang={["class:Rogue"]="För att få tag på de här tunga kistorna måste man helt förlita sig på fickstölder från härdade motståndare. Det gör Ravenholdt till den självklara knutpunkten för en skurks olagliga färdigheter.",["faction:Alliance"]="Ravenholdt ligger gömt i det omstridda Lordaeron, men verkar självständigt och tar emot uppdrag från alliansens vandrare utan hänsyn till fraktionsgränser.",["faction:Horde"]="Hordens operativa medlemmar som vågar sig upp i bergen i Hillsbrad märker att Ravenholdt är helt likgiltigt inför fraktionstillhörighet och värderar användbara olagliga varor högst av allt."},sec={{t="Vässar Ravenholdts klor",b="I Ravenholdt Manors dolda fäste, högt uppe i bergen ovanför Hillsbrad Foothills, pågår träningen utan uppehåll. Mästerstjuven Fahrad leder gillets operativa medlemmar och lägger stor vikt vid praktisk låsdyrkning. Zan tillhandahåller övningsmekanismer åt nya rekryter, men Fahrad anser att de är alltför enkla för erfarna medlemmar som måste dyrka upp riktiga, trilskande lås ute på fältet."},{t="Ett märkligt öppet erbjudande",b="För att förse herrgården med verkliga låsmekanismer anlitar Fahrad folk för att stjäla tunga skräplådor från farliga mål runtom Azeroth. Bara skickliga tjuvar kan lyfta lådorna från sina offer ute i vildmarken, men Fahrad begränsar inte affärerna till skurkar. Den som levererar låsta kistor i omgångar – även om de redan länsats på de värdefullaste föremålen – vinner Fahrads gunst och får herrgårdens livsfarligt välbalanserade kastknivar. Det krävs bara att ett mynt finns kvar i varje kista för att sporra lärlingarna."}},faq={{q="Varför vill Fahrad ha de här skräplådorna?",a="Ravenholdts skurkrekryter behöver realistiska låsmekanismer att öva låsdyrkning på. Fahrad tycker att övningskistorna från herrgårdens egen hantverkare Zan är alldeles för enkla för alla utom rena nybörjare. Därför behövs riktiga låsta kistor från farliga offer.",al={"varför skräplådor","skräplådornas syfte","varför fahrad vill ha lådor"}},{q="Var äger uppdraget rum?",a="Bytet sker vid Ravenholdt Manor, en hemlig tillflyktsort för tjuvgillet, gömd bland bergen norr om Hillsbrad Foothills.",al={"plats för uppdraget junkboxes needed","var finns fahrad","var ligger ravenholdt"}},{q="Är det bara skurkar som kan lämna in lådorna?",a="De tunga skräplådorna kommer ursprungligen från fickstölder, en skurkkonst, men Fahrad tar emot leveranser från alla som kan föra dem till herrgården.",al={"är uppdraget bara för skurkar","kan alla göra junkboxes needed","skräplådor för andra klasser"}},{q="Varför måste det finnas mynt kvar i lådorna?",a="Fahrad kräver att några mynt lämnas kvar i varje kista, eftersom även skurkar under utbildning behöver ett konkret incitament och en påtaglig belöning för att lägga manken till med låsdyrkningen.",al={"varför lämna mynt i lådan","måste det finnas byte i lådorna","tomma skräplådor"}},{q="Vad erbjuder Ravenholdt i utbyte?",a="Fahrad belönar sina bidragsgivare med anseende hos gillet och fint tillverkade kastknivar, som han syrligt hoppas ska finna vägen rakt in i någons hjärta.",al={"belöning för junkboxes needed","vad ger fahrad","ravenholdts kastknivar"}},{q="Vem är Zan, som Fahrad klagar på?",a="Zan levererar lås till Ravenholdt. Fahrad anser att Zans övningsmekanismer är grovhuggna och bara passar de mest oerfarna nybörjarna, inte seriösa operativa medlemmar.",al={"vem är zan","zan i ravenholdt","zans lås"}}},fx={["45d1fe22"]={q="Varför behöver Ravenholdt en utomstående skurk för att samla in lådor?",a="Ravenholdts nuvarande lärlingar är fortfarande gröna och saknar helt enkelt färdigheten att dyrka upp komplicerade lås på egen hand. Övningsmekanismerna som deras egen uppfinnare Zan har tillverkat är alltför grova för avancerad träning. Fahrad förlitar sig på skickliga agenter som du, som kan ta sig in i farliga områden och stjäla riktiga, högsäkrade lådor som innebär en verklig utmaning.",al={"varför ber de mig om lådor","varför behöver winstone wolfe mig","varför skaffar ravenholdt inte egna lådor"}}},fp="16,166,30.335.0,28.382.0,37.257.0,32.131.0,35.136.0,52.128.0,39.138.0,39.148.0"}
P.entries["quest:825"] = {n="From The Wreckage....",s="Gar'Thok skickar ut hordens spejare till vraken utanför Scuttle Coast för att hämta Gnomish Tools. Horden hoppas kunna studera alliansens ingenjörskonst och använda dess fördel för egen vinning.",h="Gar'Thok skickar ut hordens spejare till vraken utanför Scuttle Coast för att hämta Gnomish Tools.",kw={"durotar","gar'thok","gnomish tools","proudmoore","razor hill","bärgning","scuttle coast","tiragarde keep","vrak"},ang={["faction:Horde"]="Som medlem av Horden vet du att Gar'Thok ser alliansens metall både som kunskap för att besegra framtida invasioner och som material för att bygga upp Durotar.",["profession:Engineering"]="Som mekaniker visar Gnomish Tools den tidiga kollisionen mellan alliansens mekaniska precision och hordens växande hantverksindustri.",["race:Gnome"]="Som gnom sätter du din prägel överallt där alliansen seglar. Horden respekterar din avancerade utrustning så mycket att den skickar spejare för att bärga den."},sec={{t="Flottans ekon",b="Storamiral Daelin Proudmoore förde Kul Tiras flotta till Kalimdor, där skeppen trängdes längs stranden nära Tiragarde Keep. Efter hans nederlag sjönk sönderslagna skrov längs Scuttle Coast. Kul Tiras soldater som överlevde befäster borgen, medan flottans vrak ligger utspridda på grunden under tidvattnet."},{t="Gnomiska konstruktioner",b="Horden vet att alliansens uppfinningsrikedom kan ge dess fiender ett övertag över orkernas styrka, järn och blod. Gnomiska tekniker seglade med expeditionsflottan och utrustade skeppen med komplicerade maskiner och precisa verktyg. Gar'Thok vill att verktygen bärgas från vraken så att Horden kan lära sig hur de fungerar."},{t="På väg till Orgrimmar",b="Gar'Thok skickar de bärgade verktygen med karavan från Razor Hill till Orgrimmar. Hordens hantverkare och taktiker hoppas kunna studera de gnomiska instrumenten och bättre bemöta alliansens redskap i framtida konflikter, samtidigt som de stärker sin egen industri."}},faq={{q="Varför bärgar Horden verktyg från de här vraken?",a="Horden vill förstå alliansens avancerade teknologi. Gnomer tillverkar invecklade maskiner åt människornas styrkor, och genom att studera deras verktyg kan hordens taktiker kanske lära sig att bemöta alliansens redskap och anpassa användbara konstruktioner för sina egna hantverkare.",al={"varför hämta gnomiska verktyg","varför bärga vrak","gar'thoks anledning till verktygen"}},{q="Vem ägde skeppen som förliste utanför Scuttle Coast?",a="De skeppsbrutna fartygen tillhörde storamiral Daelin Proudmoores flotta från Kul Tiras. Efter landstigningen i Durotar för att strida mot Thralls nygrundade nation förstördes flera längs kusten, strax öster om Tiragarde Keep.",al={"vems skepp är det här","vem sänkte skeppen vid durotar","proudmoores flottvrak"}},{q="Vart förs de bärgade verktygen efter Razor Hill?",a="Gar'Thok skickar de återfunna Gnomish Tools med karavan från Razor Hill till Orgrimmar. Ingenjörer och hantverkare där kan studera dem för att stärka huvudstadens försvar och industri.",al={"vad händer med verktygen","vart förs gnomiska verktyg","vem får bärgningen"}},{q="Varför finns gnomiska verktyg på människornas krigsskepp?",a="Gnomer är nära allierade till människorna i den stora alliansen. De bidrar ofta med mekanisk expertis, belägringsutrustning och precisionsverktyg för att hålla människornas krigsfartyg i drift.",al={"varför samarbetar gnomer och människor","gnomer på proudmoores skepp","alliansens gnomiska teknik"}},{q="Vad är Scuttle Coast?",a="Scuttle Coast är Durotars östra kust och sträcker sig förbi Tiragarde Keep. I det grunda vattnet ligger halvt nedsänkta och sjunkna skepp kvar efter striderna mot Proudmoores expedition.",al={"var ligger scuttle coast","scuttle coast läge","område med sjunkna skepp i durotar"}},{q="Hur hänger det här uppdraget ihop med hotet vid Tiragarde Keep?",a="När anfallet mot Tiragarde Keep har rensat ut Kul Tiras marinsoldater passar Gar'Thok på att lägga beslag på de återstående alliansresurserna. Horden kan dra nytta av nederlaget genom att plundra vraken i närheten innan asätare eller tidvattnet tar allt.",al={"koppling till tiragarde keep","koppling till vanquish the betrayers","varför göra detta efter tiragarde"}}},fp="21,158,19.294.0,20.317.0,22.254.0,51.247.0,46.219.0,49.182.0,46.159.0,26.186.0,58.246.0"}
P.entries["quest:826"] = {n="Zalazane",s="På Echo Isles har Zalazanes förräderi drivit bort Darkspear Trolls från deras hem. Master Gadrin i Sen'jin Village skickar Horde-mästare för att göra slut på häxdoktorns välde. Mörk magi drev Zalazane till vansinne, och han förslavade sina stamfränder, tog Darkspear-trollens rättmätiga hem i besittning och tvingade dem i exil vid Durotars kust.",h="På Echo Isles har Zalazanes förräderi drivit bort Darkspear Trolls från deras hem.",kw={"darkspear","durotar","echo isles","besvärjelseförhäxat troll","master gadrin","sen'jin village","vol'jin","voodoo-troll","zalazane"},ang={["class:Shaman"]="Som schaman känner du till de andliga hantverken och ursprungliga krafter som trollschamaner och häxdoktorer utövar. Zalazane förvrider bindande magi och vänder den mot sina egna fränder.",["faction:Horde"]="Som medlem av Horde hjälper du till att försvara de fördrivna Darkspear. Allierade från hela Durotar samlas för deras sak i ett av den unga Hordes första stora prov på enighet.",["race:Troll"]="Som Darkspear-troll har du en personlig plikt: straffa förrädaren som stal ditt folks hem och förslavade dina fränder."},sec={{t="Förräderi på öarna",b="Darkspear Trolls slog sig ner på Echo Isles efter att ha flytt från sin sjunkna ö och följt Thrall över det stora havet. Öarna ligger strax utanför Durotars sydöstra kust. Zalazane, som en gång var en respekterad och mäktig häxdoktor i stammen, törstade efter makt. Han använde förbannelser för att förslava sina fränders sinnen och inledde ett våldsamt uppror. Vol'jin ledde de Darkspear som fortfarande var fria, men de drevs bort från sina förfäders läger på andra sidan vattnet. De tvingades bygga en tillfällig tillflykt i Sen'jin Village."},{t="En stams plåga",b="Zalazane skickar fortfarande ut plundrartrupper från sitt fäste på kullen på den största av Echo Isles. De korsar sundet för att ta fler Darkspear och kuva dem under hans kontroll. De tillfångatagna trollen blir tanklösa voodoo- och förbannelseslavar, förlorade för sin stam. Master Gadrin ser mer än en ockupation av Darkspears land: Zalazane hotar stammens överlevnad. Ingen Darkspear kan vara trygg förrän hans avhuggna huvud förs fram inför de äldste."}},faq={{q="Vem är Zalazane?",a="Zalazane var en framstående häxdoktor bland Darkspear-trollen. Törsten efter mörk makt fördärvade honom, och han vände sig mot sina fränder, använde voodoo som styrde sinnena för att förslava dem och ta Echo Isles i besittning.",al={"zalazanes bakgrund","vem är bossen på echo isles","häxdoktorn zalazane"}},{q="Varför flydde Darkspear från Echo Isles?",a="Darkspear flydde efter att Zalazane genomfört en överraskningskupp på öarna och använt trolldom för att förvandla sina fränder till tanklösa slavar. Vol'jin och de fria Darkspear var för få för att möta sina förtrollade fränder, så de drog sig tillbaka till Durotars fastland och grundade Sen'jin Village som en tillfällig tillflykt.",al={"varför är troll i sen'jin village","echo isles bakgrund","hur förlorade trollen echo isles"}},{q="Vad händer med trollen som Zalazane kontrollerar?",a="Förbannelser har berövat trollen under Zalazanes kontroll deras sinnen. De tjänar honom, patrullerar öarna och plundrar fastlandet för att fånga fler offer. Master Gadrin betraktar dem som förlorade för stammen, och avrättning är deras enda nåd.",al={"besvärjelseförhäxade troll","voodoo-troll","kan zalazanes slavar botas"}},{q="Var befinner sig Zalazane?",a="Zalazane har sitt näste på den största av Echo Isles, strax öster om Durotars sydkust. Han patrullerar från den höga toppen på öns centrala kulle ner till klungan av trollhyddor nedanför.",al={"zalazanes plats","hitta zalazane","var finns zalazane"}},{q="Vem ger uppdraget att döda Zalazane?",a="Master Gadrin, en stammens äldste i Sen'jin Village på Durotars sydkust, ber dig döda Zalazane. Du möter honom efter att ha hanterat lokala hot och anlänt från Valley of Trials.",al={"vem startar zalazane-uppdraget","var får man zalazane-uppdraget"}},{q="Varför leder Vol'jin inte anfallet själv?",a="Vol'jin styr stammen och samordnar Darkspears försvar tillsammans med krigshövding Thrall i Orgrimmar. I Sen'jin Village vägleder äldste som Master Gadrin invånarna i hur de ska klara sig, och Gadrin värvar dugliga äventyrare för att slå tillbaka mot Zalazane.",al={"var är vol'jin","varför slåss inte vol'jin mot zalazane"}}},fx={ae6e25c2={q="Varför vill Master Gadrin att Zalazane dödas?",a="Zalazane nöjer sig inte med att ha stulit Echo Isles. Han skickar ständigt sina förtrollade troll över vattnet för att plundra fastlandet och förslava fler Darkspear-troll så att hans styrkor växer. Master Gadrin vet att Sen'jin Village aldrig kommer att vara tryggt så länge den avfällige häxdoktorn lever och plågar och rövar bort hans folk.",al={"gadrin och zalazane, varför","varför döda zalazane","varför vill master gadrin detta"}},a3c2387d={q="Vad används Zalazane's Head till?",a="Master Gadrin kräver Zalazanes avhuggna huvud som obestridligt bevis på häxdoktorns död. Först när Gadrin ser huvudet med egna ögon kan han vara säker på att Zalazanes mörka inflytande är brutet och att Darkspear-stammen äntligen kan sova i fred.",al={"vad är zalazanes huvud till för","varför ta med zalazanes huvud","zalazanes huvud som uppdragsföremål"}}},fp="8,304,21.444.0,17.430.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="Skull Rock",s="Margoz skickar dig in i Skull Rock, öster om Orgrimmar. Burning Blade-kultister har tagit över grottan och använder plågsamma demoniska anordningar för att binda sig till mörk magi. Margoz behöver de förbannade artefakterna för att undersöka kultens närvaro nära huvudstaden.",h="Margoz skickar dig in i Skull Rock, öster om Orgrimmar.",kw={"burning blade","kultister","demonisk","durotar","avgrundsmagi","margoz","orgrimmar","searing collar","skull rock"},ang={["class:Warlock"]="Som häxmästare kan du se hur Searing Collars binder sina bärare med avgrundsmagi. Deras grova förtrollningar visar hur kulten omvandlar demoniska offer till kraft.",["faction:Horde"]="Som medlem av Horden står du inför en demonisk kult som slagit rot alldeles utanför Orgrimmars murar och hotar ditt folks hjärta och säkerhet.",["race:Orc"]="Som orch står du inför Burning Blade, en kvarleva från det mörka förflutna som ditt folk kämpar för att lämna bakom sig. Att driva bort kulten från Durotars klippor är en fråga om överlevnad och ära."},sec={{t="En håla av skuggor",b="I nordöstra Durotar samlas kultister nära Orgrimmars portar. Grottan ligger bland kullarna, långt från de öppna vägarna men nära hövdingens säte. Burning Blade, en demonisk kult som länge har plågat orchernas samhälle, har slagit sig ner i tunnlarna. Dess anhängare utför ritualer där medan hövdingens spejare håller uppsikt i närheten."},{t="Demonisk samklang",b="Burning Blade-kultister bär Searing Collars runt halsen, metallband som bränner och märker deras hud. Margoz tror att smärtan och avgrundsmagin i halsbanden gör bärarna mottagliga för demonisk kraft. Han ber dig hämta halsbanden så att han kan studera besvärjelserna och bojorna som ger kultisterna deras kraft."},{t="Ett hot tornar upp sig",b="Burning Blades Searing Collars visar att kulten är organiserad i Durotar. Dess trolldom hotar Hordens nyetablerade territorier. Margoz studie av halsbanden leder till fler undersökningar bland Orgrimmars dolda kretsar."}},faq={{q="Var ligger Skull Rock?",a="Skull Rock ligger i nordöstra Durotar, öster om Orgrimmar och norr om Sen'jin Village. Ingången ramas in av en klippig bergssida längs stranden.",al={"skull rock läge","var ligger skull rock","skull rock-grottan i durotar"}},{q="Vilka är Burning Blade?",a="Burning Blade är en kult av orcher och avgrundsdyrkare som hängivit sig åt demoner och mörk magi. Den moderna Horden bröt sig fri från demoniskt slaveri, men utbrytargrupper som Burning Blade utövar fortfarande förbjudna riter och försöker korrumpera Horden från skuggorna.",al={"vad är burning blade","vilka är burning blades kultister","burning blade bakgrund"}},{q="Vad använder kultisterna Searing Collars till?",a="Kultister bär Searing Collars runt halsen, där den glödande metallen bränner deras hud. Margoz misstänker att smärtan och den demoniska förtrollningen hjälper dem att kanalisera och anpassa sig till mörka avgrundsenergier.",al={"searing collars syfte","varför bära searing collars","vad är searing collars"}},{q="Vem är Margoz?",a="Margoz är en orchisk eremit som bor i ett litet läger på Durotars höjder, nära Skull Rock. Han bevakar kultisternas rörelser längs kusten och arbetar för att slå sönder Burning Blades verksamhet.",al={"vem är margoz","margoz i durotar","margoz uppdragsgivare"}},{q="Varför låter Horden kulten hålla till så nära Orgrimmar?",a="Horden tolererar inte medvetet kulten nära Orgrimmar. Burning Blades anhängare gömmer sig i grottor och ödsliga raviner utom räckhåll för vanliga patruller, och äventyrare undersöker saken när kultens ritualer avslöjar dess fästen.",al={"varför ligger skull rock nära orgrimmar","burning blade nära orgrimmar"}},{q="Vad händer efter att Margoz har undersökt halsringarna?",a="Margoz planerar att undersöka Searing Collars. Hans utredning fortsätter tillsammans med Neeru Fireblade i Orgrimmar.",al={"nästa uppdrag efter skull rock","vart leder halsringarna","margoz besvärjelse"}}},fx={cfe1a49d={q="Varför vill Margoz ha Searing Collars?",a="Margoz tror att kultisterna genom att bränna sitt kött med dessa halskragar stämmer sig till demoniska krafter. Han behöver en samling intakta halskragar att studera och undersöka med sin magi, i hopp om att avslöja Burning Blades mörka hemligheter och hur djup deras demoniska korrumpering är.",al={"varför behöver margoz halskragar","margoz och searing collars, motiv","varför samla in searing collars"}},["50396613"]={q="Vilka skickas du att bekämpa i Skull Rock?",a="Du skickas mot Burning Blades kultister som gömmer sig inne i Skull Rock, en grotta öster om Orgrimmar. De har samlats där mitt framför näsan på Horden för att utföra vidriga ritualer, binda sig till demoniska herrar och smida planer mot Durotars säkerhet.",al={"vilka finns i skull rock","fiender i skull rock","burning blades kultister i skull rock"}}},fp="10,216,16.308.0,18.283.0,18.239.1,28.145.0,25.257.0,49.201.0,14.192.0,56.219.0,47.107.1"}
P.entries["quest:8273"] = {n="Oran's Gratitude",s="Efter Rin'ji's Secret når kedjan som började med Rin'ji is Trapped! sitt slut hos Oran Snakewrithe, som du tar med en tavla till.",h="Efter Rin'ji's Secret når kedjan som började med Rin'ji is Trapped!",kw={"den mörka damen","hinterlands","oran snakewrithe","klipporna vid the overlook","rin'ji","tavla"},sec={{t="En tavla till Oran",b="Rin'ji is Trapped! inledde kedjan, och Rin'ji's Secret var steget före det här. Oran Snakewrithe tar emot tavlan du bär med dig."},{t="Orans svar",b="Oran frågar var tavlan hittades, och du berättar om en liten, öde ö vid klipporna vid The Overlook. Oran tycker att det är mycket intressant, lägger försiktigt undan tavlan och säger att den mörka damen kommer att bli mycket nöjd med upptäckten."}},faq={{q="Vem är Oran Snakewrithe?",a="Oran Snakewrithe avslutar kedjan som började med Rin'ji is Trapped! och fortsatte genom Rin'ji's Secret.",al={"oran","vem är oran","oran snakewrithe bakgrund"}},{q="Vad kommer före det här i kedjan?",a="Före det kommer Rin'ji's Secret, och före det Rin'ji is Trapped!.",al={"föregående uppdrag","förkunskapsuppdrag för oran's gratitude","hur startar man oran's gratitude"}}},fp="16,72,17.91.0,13.220.1,24.134.0,36.66.0"}
P.entries["quest:828"] = {n="Margoz",s="I norra Durotar håller Margoz utkik efter det växande hotet från Burning Blade. Efter sammandrabbningen med felkorruption vid Thunder Ridge skickar Orgnil Soulscar mästare för att söka upp den isolerade orkschamanen innan de anfaller ett närliggande kultistfäste. Margoz avslöjar var Skull Rock ligger, Burning Blades dolda grottbas.",h="I norra Durotar håller Margoz utkik efter det växande hotet från Burning Blade.",kw={"burning blade","drygulch ravine","durotar","margoz","orgnil soulscar","orgrimmar","shaman","skull rock"},ang={["class:Shaman"]="Som schaman ser du Margoz tålmodiga visdom i hur han vakar över vildmarkens utkanter, där han känner av andlig korruption innan den leder till krig.",["faction:Horde"]="Som medlem av Horden hör du Margoz varning: demonkulter lurar inom anfallsavstånd från Orgrimmar.",["race:Orc"]="Som ork påminner mötet med Margoz dig om den kvardröjande frestelsen från felmakt och manar den nya generationen att följa en ren och hedervärd väg."},sec={{t="En eremits vaka",b="Efter Thunder Ridge stod det klart hur djup felbesmittelsen var, och Orgnil Soulscar inser att styrka ensam inte kan rena Durotar. Han skickar mästare till Margoz, en erfaren orkschaman som håller till i ett ensligt läger bland klipporna nordost om Razor Hill. Mellan Drygulch Ravine och det östra havet håller Margoz utkik över de norra trakterna efter mörka omen som Orgrimmars upptagna krigare ofta missar."},{t="Hotet från Skull Rock",b="Margoz känner till Burning Blades maktbas i norra Durotar: Skull Rock, ett dolt grottsystem uthugget i bergsklipporna utanför Orgrimmars södra portar. Kultisterna är närmare Thralls huvudstad än Hövdingens vakter inser, och Skull Rocks dolda gångar kan gömma ett demoniskt bakhåll. Margoz ger dem som skickas mot coven råd så att de inte går in blint."}},faq={{q="Vem är Margoz?",a="Margoz är en erfaren orkschaman som är lojal mot Horden och håller till i ett avskilt läger i nordöstra Durotar. Han studerar mörk magi och håller uppsikt över den demoniska korruption som sprider sig genom området.",al={"margoz historia","vem är margoz","margoz npc"}},{q="Var hittar jag Margoz?",a="Du hittar Margoz i hans läger bland de karga kullarna i nordöstra Durotar, mellan Drygulch Ravine och den östra kusten, sydost om Orgrimmar.",al={"margoz plats","hitta margoz","var finns margoz"}},{q="Varför skickar Orgnil Soulscar mig till Margoz?",a="Orgnil Soulscar skickar dig till Margoz eftersom schamanen har studerat de lokala Burning Blade-kultisterna. Innan du anfaller deras fäste vill Orgnil att du tar del av Margoz andliga visdom och praktiska råd.",al={"varför prata med margoz","orgnil soulscar margoz"}},{q="Vad är Skull Rock?",a="Skull Rock är ett dolt system av bergsgrottor strax söder om Orgrimmars östra murar. Det är ett befäst Burning Blade-coven där kultister som dyrkar demoner utför ritualer nära Hordens huvudstad.",al={"skull rock historia","vad är skull rock"}},{q="Vad händer när jag har hittat Margoz?",a="När du rapporterar till Margoz erkänner han att din styrka har vuxit och skickar dig in i Skull Rock för att döda kultisterna och återta deras korrumperade insignier.",al={"nästa uppdrag efter margoz","margoz fortsättning"}},{q="Tillhör Margoz Burning Blade?",a="Nej. Margoz är en hängiven schaman för Horden som arbetar för att driva ut demoniskt inflytande och hålla unga mästare på en hedervärd, okorrumperad väg.",al={"är margoz ond","är margoz kultist"}}},fp="6,333,16.370.0,24.392.0,14.189.0,23.151.0,43.211.0,19.186.0,34.153.1,36.137.0"}
P.entries["quest:829"] = {n="Neeru Fireblade",s="I Orgrimmar studerar Neeru Fireblade mörka konster som han säger kan skydda horden. Margoz skickar dig från Durotar med en Searing Collar från Burning Blade-kulten. Han hoppas att trollkarlen kan förklara dess demoniska kraft.",h="I Orgrimmar studerar Neeru Fireblade mörka konster som han säger kan skydda horden.",kw={"burning blade","cleft of shadow","durotar","margoz","neeru fireblade","orgrimmar","searing collar","skull rock","häxmästare"},ang={["class:Shaman"]="Som shaman vet du att elementen inte kommer att kommunicera med felartefakter. Margoz har nått gränsen för sitt kunnande och behöver hjälp av en trollkarl.",["class:Warlock"]="Som trollkarl möter du Neeru Fireblade i Cleft of Shadow, Orgrimmars främsta trollkarl. Ditt förbjudna hantverk kan vara till praktisk nytta för horden.",["faction:Horde"]="Som medlem av horden ser du en bräcklig vapenvila i Orgrimmar: hövdingens shamaner förlitar sig ibland på de skugglika utstötta i Cleft of Shadow för att skydda Durotar."},sec={{t="En shaman och hans gränser",b="Margoz har nått gränsen för shamanernas konster. Halskragarna från Burning Blade-kultister vid Skull Rock bär på demonisk trolldom som han inte kan reda ut. Shamaner hämtar kraft från elementen och förfädernas andar. Därför skickar Margoz dig till en trollkarl i huvudstaden för att ta reda på vad halskragarna gör."},{t="In i Cleft of Shadow",b="Orgrimmars Cleft of Shadow ligger under de röda klipporna. Där verkar trollkarlar och andra utövare av förbjuden magi under Thralls vaksamma blick. Neeru Fireblade bor i grottan och säger att han studerar felkraft för att motverka demoniska hot. När du tar med halskragen till honom riktar hans nyfikenhet Durotars undersökning mot trollkarlarnas enklav."}},faq={{q="Varför skickar Margoz mig till en häxmästare?",a="Margoz är en shaman som hämtar kraft från elementen och förfädernas andar. Searing Collars från Skull Rock är demoniska, så han behöver någon som behärskar felmagi och mörka konster för att förstå deras förtrollningar och ursprung.",al={"varför häxmästare","varför neeru","margoz häxmästare"}},{q="Var hittar jag Neeru Fireblade?",a="Du hittar Neeru Fireblade i Cleft of Shadow under Orgrimmar, där trollkarlar, lönnmördare och skuggmagiker samlas.",al={"neerus plats","var finns neeru fireblade","neeru i cleft of shadow"}},{q="Går det att lita på Neeru Fireblade?",a="Margoz tvivlar på Neerus påstående att hans ockulta forskning är harmlös och avsedd att bekämpa demoner. Thrall tillåter trollkarlar i Orgrimmar under strikt övervakning, men det är fortfarande osäkert om Neeru går att lita på.",al={"är neeru ond","pålitlig neeru","kan jag lita på fireblade"}},{q="Vad är Example Collar?",a="Example Collar är en av Searing Collars som togs från Burning Blade-kultister vid Skull Rock. Margoz ger den till dig för att du ska ta den till Neeru Fireblade för magiska studier.",al={"example collar","vad är kragen","uppdragsföremål searing collar"}},{q="Vad händer när jag ger kragen till Neeru?",a="Neeru undersöker halskragen noggrant och fördjupar dig i utredningen av kultens närvaro i Durotar. Sökandet efter Ak'Zeloth börjar.",al={"nästa uppdrag efter neeru","vad gör neeru","uppdragskedja efter neeru"}},{q="Varför tillåter horden häxmästare i Orgrimmar?",a="Thrall tillåter trollkarlar i Orgrimmar av pragmatisk nödvändighet. Han håller dem i Cleft of Shadow, där deras farliga forskning kan övervakas, kontrolleras och ibland användas för att förstå demoniska fiender.",al={"varför tillåts häxmästare","häxmästare i cleft of shadow","thrall och häxmästare"}}},fx={["273c9fa7"]={q="Varför skickar Margoz dig i stället för att gå själv?",a="Margoz är fortfarande stationerad utanför Razor Hill, där han håller uppsikt över den andliga oro som råder i Durotar. Du är äventyraren som först hämtade Searing Collars från Skull Rock och därmed visade att du kan hantera kultens mörka artefakter. Eftersom han inte kan tyda deras demoniska verksamhet enbart med schamanism förlitar han sig på att du snabbt tar med ett prov till The Cleft of Shadow.",al={"varför jag åt margoz","varför skicka mig till neeru","varför går inte margoz till orgrimmar"}}},fp="15,210,17.276.0,24.342.0,37.237.0,33.121.0,31.198.0,27.167.0,46.147.0,47.205.0"}
P.entries["quest:83"] = {n="Red Linen Goods",s="På Eastvale Logging Camp behöver Sara Timberlain tyg till sin sömnad. Hon ber äventyrare på genomresa att jaga Defias-banditer och ta deras linnebandanas. Sedan använder hon tyget för att tillverka varor åt resande.",h="På Eastvale Logging Camp behöver Sara Timberlain tyg till sin sömnad.",kw={"säckväv","defias brotherhood","eastvale logging camp","elwynn forest","red linen bandana","red linen goods","sara timberlain","sömnad"},ang={["faction:Alliance"]="Som resande i Alliansen kan du försvaga Defias Brotherhood i Elwynn och samtidigt ta med användbart tyg till Eastvale.",["profession:Tailoring"]="Som skräddare ser du hur brist på tyg kan få en sömmerska att återvinna tyg från banditernas kläder."},sec={{t="Banditer och säckväv",b="Defias-banditer i hela Elwynn bär röda linnebandanas. Deras mindre organiserade fränder i Northshire Valley får nöja sig med billiga masker av säckväv. För lokala hantverkare som har ont om material erbjuder bandanorna tyg att använda."},{t="Återvunnet tyg vid lägret",b="Sara Timberlain arbetar som sömmerska på Eastvale Logging Camp, nära Elwynns östra gräns. Hon behöver användbara textilier i sitt yrke och ber därför äventyrare att rensa ut Defias-lägren som ligger utspridda i skogarna. Tyget håller hennes sömnadsarbete försörjt samtidigt som banditernas intrång i området hejdas."}},faq={{q="Vem erbjuder uppdraget Red Linen Goods?",a="Sara Timberlain, en sömmerska på Eastvale Logging Camp i östra Elwynn Forest, erbjuder arbetet.",al={"vem ger red linen goods","uppdragsgivare för red linen goods","sara timberlains uppdrag"}},{q="Vilka föremål behövs till Red Linen Goods?",a="Du behöver sex Red Linen Bandanas från Defias-gängmedlemmar som finns utspridda i Elwynn Forest.",al={"vad ska jag samla till red linen goods","föremål till red linen goods","bandanas som behövs"}},{q="Var hittar jag Defias-banditer i Elwynn Forest?",a="Defias-banditer har läger runtom i Elwynn Forest, bland annat kring Brackwell Pumpkin Patch, The Stonefield Farm och skogarna runt Jerod's Landing.",al={"defias platser i elwynn","var finns defias-lägren","var får man röda bandanas"}},{q="Varför bär Defias i Elwynn linne i stället för säckväv?",a="Defias-medlemmar med låg rang i Northshire bär masker av säckväv, medan bättre utrustade medlemmar runtom i Elwynn bär rött linne. Bandanorna visar att Brotherhood är bättre organiserat och försörjt.",al={"varför rött linne","säckväv eller linne hos defias","material i defias-masker"}},{q="Varför vill Sara Timberlain ha banditernas bandanas?",a="Sara Timberlain behöver tyg till sin sömnad. Hon återanvänder linne från Defias-maskerna för att sy praktiska varor åt skogshuggare och resande vid timmerlägret.",al={"varför samla bandanas","vad gör sara med maskerna"}},{q="Var ligger Eastvale Logging Camp?",a="Eastvale Logging Camp ligger längst österut i Elwynn Forest, strax norr om huvudvägen mot bron till Redridge Mountains.",al={"eastvales plats","var ligger eastvale","hitta sara timberlain"}}},fx={["18a4a024"]={q="Vad används Red Linen Bandana till?",a="Banditer ur Defias Brotherhood bär de röda linnesnussnäsdukarna som masker när de stryker omkring i Elwynn Forest. Medan skurkarna i Northshire får nöja sig med grov säckväv använder tjuvarna i resten av skogen tyg av bättre kvalitet. Sara Timberlain repar upp och väver om de beslagtagna maskerna för att tillverka användbara linnesplagg.",al={"vad är red linen bandana till för","red linen bandana användning","varför red linen bandana"}},["8ac6c8ef"]={q="Varför finns Defias-banditer i Elwynn Forest?",a="Defias Brotherhood har upprättat läger runt om i Elwynn Forest för att trakassera resande, råna försörjningskaravaner och undergräva Stormwinds makt. Deras växande närvaro hotar lokala bosättningar som Eastvale Logging Camp. De utnyttjar att kungarikets vakter är hårt ansatta för att utöka sin laglösa verksamhet alldeles utanför huvudstaden.",al={"defias i elwynn","varför är defias här","defias brotherhood i elwynn forest"}},fea06053={q="Varför behöver Sara Timberlain dig i stället för vakterna?",a="Sara Timberlain är skräddare vid Eastvale Logging Camp, inte soldat, och hon har inte möjlighet att bekämpa laglösa på egen hand. Stormwinds vakter och den lokala garnisonen är redan överbelastade med att försöka hejda utbredda räder från Defias och gnollattacker. Därför måste enkla hantverkare förlita sig på förbipasserande äventyrare för material och skydd.",al={"varför frågar sara mig","varför inte vakterna i elwynn","varför behöver timberlain hjälp"}}},fp="15,169,18.181.0,19.200.0,37.109.0,42.92.0,49.138.0,54.180.0,46.153.0,43.127.0"}
P.entries["quest:830"] = {n="The Admiral's Orders",s="De här väderbitna pappren hittades i en låst kista högst upp i Tiragarde Keep. De bär den avlidne storamiralen Daelin Proudmoores personliga sigill. Orderna visar att den kul tiranska garnisonen längs Durotars kust är betydligt mer förskansad och organiserad än några skeppsbrutna överlevande. När du lämnar dem till Gar'Thok i Razor Hill avslöjas kvarvarande militärplaner som hotar den unga orciska nationen.",h="De här väderbitna pappren hittades i en låst kista högst upp i Tiragarde Keep.",kw={"admirals orders","aged envelope","daelin proudmoore","gar'thok","kul tiras","löjtnant benedict","razor hill","tiragarde keep"},ang={["faction:Horde"]="Proudmoores order visar att Alliansens närvaro vid Durotars stränder var en planerad utrotningskampanj. Det bekräftar varför Horde måste försvara sitt nyfunna hem med vaksamhet.",["race:Orc"]="För orcherna som kämpar för att bygga en framtid i Durotar är dokumenten en bister påminnelse om Daelin Proudmoores obevekliga hat och om resterna av hans styrkor, som fortfarande söker deras undergång."},sec={{t="Ett förseglat arv",b="I en tung kista på de övre våningarna i Tiragarde Keep överlever ett gammalt kuvert under löjtnant Benedicts bevakning. Pergamentet är förseglat med storamiralen Daelin Proudmoores vapen och beskriver direkta sjöorder från Kul Tiras blodiga invasion av Durotar. Även efter storamiralens fall vid Theramore höll hans officerare fast vid sina befästningar och sitt uppdrag att utrota Horde-bosättningen."},{t="Oro i Razor Hill",b="När du lämnar de återfunna dokumenten till Gar'Thok, befälhavare i Razor Hill, bekräftas den lokala försvarsstyrkans värsta farhågor. Människostyrkorna som förskansat sig längs den östra kusten är inget planlöst skeppsbrutet folk, utan ett etablerat brohuvud som väntar på förstärkningar. Gar'Thok inser genast att det är en fråga om överlevnad för Durotar att slå ut Tiragardes befälsstruktur."}},faq={{q="Var hittar man Admiral's Orders?",a="Orderna finns i ett Aged Envelope i en låst kista på tredje våningen i Tiragarde Keep i Durotar. För att öppna kistan måste du först besegra löjtnant Benedict på andra våningen och ta hans nyckel.",al={"var finns orderna","var finns aged envelope","hitta admirals orders"}},{q="Vem var Admiral Proudmoore?",a="Storamiral Daelin Proudmoore var Kul Tiras härskare och befälhavare för Alliansens flotta under det andra kriget. Han vägrade tro att orcher någonsin kunde leva i fred och seglade till Kalimdor för att föra ett utrotningskrig mot Durotar, innan han mötte sin död vid Theramore.",al={"vem är amiralen","daelin proudmoore bakgrund","vem utfärdade orderna"}},{q="Varför finns kul tiranska soldater fortfarande i Tiragarde Keep?",a="När Daelin Proudmoore invaderade Durotar anlade han befästa kustfästen som Tiragarde Keep. Efter hans nederlag höll överlevande officerare och marinsoldater under löjtnant Benedict sina poster, fast beslutna att fortsätta hans kampanj mot Horde.",al={"varför finns människor i durotar","soldater i tiragarde keep","kul tiras i durotar"}},{q="Varför oroar sig Gar'Thok så mycket för de här orderna?",a="Som militär befälhavare i Razor Hill har Gar'Thok till uppgift att skydda centrala Durotar. De organiserade sjöorderna visar att Tiragarde Keep utgör ett aktivt och planerat militärt hot mot orchernas hemland, inte bara hyser skeppsbrutna överlevande utan organisation.",al={"gar'thoks reaktion","varför bryr sig gar'thok"}},{q="Vem har nyckeln till Admiral's Orders-kistan?",a="Löjtnant Benedict, den befälhavande kul tiranska officeren på andra våningen i Tiragarde Keep, bär nyckeln till kistan med Aged Envelope.",al={"benedicts nyckel","vem tappar nyckeln"}},{q="Vad händer när man ger orderna till Gar'Thok?",a="När Gar'Thok granskar orderna inser han faran: Proudmoores planer lades upp före hans död, och fler vågor av hans män kan fortfarande landa på Durotars stränder. Han skickar genast orderna vidare till Orgrimmar så att krigshövdingens råd får en varning.",al={"uppföljning till admirals orders","nästa uppdrag"}}},fp="20,262,15.398.0,19.327.1,37.156.0,27.252.0,51.244.0,48.191.0,41.146.0,49.204.0"}
P.entries["quest:831"] = {n="The Admiral's Orders",s="Gar'Thok skickar dig för att överlämna Admiral Proudmoore's Orders till Nazgrel i Orgrimmar. Ordern väcker farhågor om ännu en människolandstigning vid Hordes stränder.",h="Gar'Thok skickar dig för att överlämna Admiral Proudmoore's Orders till Nazgrel i Orgrimmar.",kw={"admiral proudmoore","gar'thok","horde","människolandstigning","nazgrel","order","orgrimmar","thrall"},ang={["faction:Horde"]="Som medlem av Horde bär du på en varning som Gar'Thok anser gäller säkerheten vid Hordes stränder."},sec={{t="En varning till Nazgrel",b="Gar'Thok i Durotar befarar att Admiral Proudmoore's planer fortfarande hotar Horde. Han skickar dig med amiralens order till Nazgrel i Thralls kammare i Orgrimmar."},{t="I Thralls kammare",b="Nazgrel tar emot ordern och säger att krigshövdingen genast måste få höra om saken. Han tackar dig för att du tjänar Horde hedervärt och vänder sig sedan till Thrall för att ge råd."}},faq={{q="Vem skickar mig till Orgrimmar?",a="Gar'Thok skickar dig från Durotar för att överlämna Admiral Proudmoore's Orders till Nazgrel.",al={"vem gav mig detta","gar'thoks order"}},{q="Vem ska ta emot ordern?",a="Nazgrel ska ta emot Admiral Proudmoore's Orders i Thralls kammare i Orgrimmar.",al={"överlämna till vem","nazgrels order"}},{q="Varför är ordern brådskande?",a="Gar'Thok befarar att Admiral Proudmoore's planer kan föra fler av hans män till Hordes stränder.",al={"varför brådskande","människohot"}},{q="Vad gör Nazgrel med varningen?",a="Nazgrel säger att han måste rådgöra med Thrall om saken.",al={"vad gör nazgrel","rådgöra med thrall"}}},fp="20,145,21.167.0,19.159.1,26.82.0,30.83.0,26.89.0,38.53.0"}
P.entries["quest:8311"] = {n="Hallow's End Treats for Jesper!",s="Jesper ligger sjuk i Stormwind under Hallow's End och längtar efter godsakerna och allt det roliga utanför barnhemmet. Han är för sjuk för att gå ut och ber Alliansens äventyrare samla godis åt honom.",h="Jesper ligger sjuk i Stormwind under Hallow's End och längtar efter godsakerna och allt det roliga utanför...",kw={"darnassus","gumdrop","hallow's end","ironforge","jesper","marsipan","näktergal","nougat","stormwind","talvash","bus eller godis"},ang={["faction:Alliance"]="För Alliansen för högtiden samman avlägsna huvudstäder. Du reser från Stormwinds ståtliga gator till Ironforges salar i bergen och Darnassus trädgrenar för att glädja ett föräldralöst barn.",["race:Gnome"]="Som gnome har du förlorat ditt hem till troggar och strålning. I Ironforge ser Talvash del Kissel till att Gnomeregan Gumdrop förblir en del av högtiden."},sec={{t="Ett skyddat barn",b="Jesper bor på barnhemmet i Cathedral Square i Stormwind och är sjuk under Hallow's End. Han kan inte njuta av barndomens nöje att samla godis runtom i Azeroth, så han hoppas att äventyrare på genomresa delar högtidens glädje och hämtar godsaker åt honom."},{t="Bus eller godis i hela Alliansen",b="För att ge Jesper godiset han längtar efter reser du bortom Elwynn Forest. Du besöker värdshusvärdarna i Stormwind, Ironforge och Darnassus, samt gnomexilen Talvash del Kissel. Var och en ber dig uppträda innan du får en godsak. Du kacklar som en höna, dansar, spänner musklerna eller tuffar som ett tåg och får regionala sötsaker som Stormwind Nougat och Gnomeregan Gumdrop."}},faq={{q="Vem är Jesper?",a="Jesper är ett ungt föräldralöst barn på barnhemmet i Stormwind. Under Hallow's End längtar han efter högtidens godis, men är för sjuk för att samla det själv.",al={"jesper stormwind","föräldralösa jesper","vem är jesper"}},{q="Varför kan Jesper inte själv gå bus eller godis?",a="Jesper är sjuk och måste stanna inne på barnhemmet medan resten av staden firar Hallow's End.",al={"varför kan jesper inte gå ut","är jesper sjuk","jesper bus eller godis"}},{q="Vilka godsaker vill Jesper ha?",a="Jesper ber om fyra regionala sötsaker: Stormwind Nougat, Ironforge Mints, Darnassus Marzipan och Gnomeregan Gumdrop.",al={"jespers godsaker","lista över hallow's end-godsaker","godis som jesper behöver"}},{q="Var får du tag på Gnomeregan Gumdrop?",a="Talvash del Kissel delar ut Gnomeregan Gumdrop medan han håller till i Mystic Ward i Ironforge.",al={"gnomeregan gumdrop plats","vem delar ut gumdrop","talvash godis"}},{q="Vilka konster ber värdshusvärdarna dig utföra?",a="Värdshusvärdarna ber dig spänna musklerna i Stormwind, dansa i Darnassus, kackla som en höna i Ironforge och låta som ett tåg åt Talvash.",al={"hallow's end-konster","värdshusvärdarnas konster","bus eller godis i alliansen"}},{q="Vad ger Jesper dig i utbyte mot godiset?",a="När Jesper har fått alla fyra högtidssötsakerna ger han resenären några pumpagodisar som han har sparat.",al={"jespers belöning","slutföra godsaker åt jesper"}}},fx={["103fae29"]={q="Varför vill Jesper att man samlar in Hallow's End-godsaker?",a="Jesper är ett sjukt föräldralöst barn som hålls på Stormwinds barnhem under Matron Nightingales vakande öga, så han kan inte delta i Hallow's End-firandet i Alliansens huvudstäder. För att få uppleva högtiden som andra barn hoppas han få smaka på de festliga sötsaker som är unika för varje allierad huvudstad. Han erbjuder sina egna pumpagodsaker i utbyte, så att han inte går miste om allt.",al={"varför vill jesper ha godsaker","jesper och godis, motiv","varför hallow's end-godsaker till jesper"}},["423b280b"]={q="Vad är Stormwind Nougat till för?",a="Stormwind Nougat är en traditionell lokal sötsak som Trade Districts värdshusvärd delar ut under Hallow's End. Den står för människorikets bidrag till festgodiset som Jesper vill att du samlar åt honom, och du får den genom att visa värdshusvärden din styrka.",al={"stormwind nougat användning","vad är stormwind nougat","vem vill ha stormwind nougat"}},["37e1df8a"]={q="Vad är Gnomeregan Gumdrop till för?",a="Gnomeregan Gumdrop är en välkänd sötsak som Talvash del Kissel delar ut i Ironforge på de förvisade gnomernas vägnar. Det är en av de fyra unika sötsaker som Jesper ber dig samla, så att han får smaka festgodis från alla alliansens folk.",al={"gnomeregan gumdrop användning","vad är gnomeregan gumdrop","vem vill ha gnomeregan gumdrop"}},e8e502ad={q="Vad är Ironforge Mint till för?",a="Ironforge Mint är en dvärgisk sötsak som värdshusvärden i Ironforge delar ut under hösthelgen. Jesper behöver den till sin kompletta samling Hallow's End-godis från fyra städer. Du får den efter att ha roat värdshusvärden med en livfull imitation av en kyckling.",al={"ironforge mint användning","vad är ironforge mint","vem vill ha ironforge mint"}},["61787ad3"]={q="Vad är Darnassus Marzipan till för?",a="Darnassus Marzipan är en utsökt Night Elf-sötsak som värdshusvärden på Craftsmen's Terrace i Darnassus delar ut. Den kompletterar urvalet av regionala Hallow's End-delikatesser som Jesper längtar efter att få njuta av medan han sitter fast på barnhemmet i Stormwind.",al={"darnassus marzipan användning","vad är darnassus marzipan","vem vill ha darnassus marzipan"}}},fp="31,175,17.236.0,37.367.0,14.135.0,46.101.0,30.117.0,43.90.0,47.135.0,50.92.0"}
P.entries["quest:8312"] = {n="Hallow's End Treats for Spoops!",s="Hallow's End Treats for Spoops! är ett säsongsuppdrag där en äventyrare samlar högtidssötsaker åt Spoops, som är för sjuk för att gå bus eller godis. I utbyte mot godsaker från stadens värdshusvärdar och Kali Remik i Sen'jin Village erbjuder Spoops magiskt godis som förvandlar den som äter det till lustiga och skrämmande skepnader.",h="Hallow's End Treats for Spoops!",kw={"godis","hallow's end","värdshusvärd","kali remik","sen'jin village","spoops","godsaker","bus eller godis"},ang={["faction:Horde"]="Uppdraget skickar Horde-äventyrare på bus eller godis genom de större städerna och vidare till Darkspear Trolls bosättning Sen'jin Village, för ett sjukt barns räkning.",["race:Troll"]="Darkspear Trolls i Durotar deltar i festligheterna, och Kali Remik delar ut säsongens sötsaker direkt från Sen'jin Village."},sec={{t="En sjuk högtid",b="Hallow's End bjuder på fest, rackartyg och högtidliga godsaker i hela riket, men alla kan inte delta utomhus. Spoops måste stanna inne på grund av sjukdom medan resten av världen firar. Eftersom Spoops inte kan ströva omkring på gatorna ber hen kringvandrande resenärer ge sig ut och samla godsaker åt sig, i utbyte mot ett märkligt lager av förvandlande sötsaker."},{t="Bus och godis i hela riket",b="För att få tag på godsakerna måste du resa genom rikets bosättningar. Värdshusvärdar i de stora städerna har lager av högtidsgodis, men kräver att besökare visar sin högtidsanda med bus innan de delar med sig. Traditionen sträcker sig bortom stadens livliga värdshus, ända till Durotars kust, där Kali Remik i Sen'jin Village delar ut godsaker till dem som tar sig dit."}},faq={{q="Vem är Spoops?",a="Spoops är en sjuk ung person som inte kan gå ut och göra bus eller godis under Hallow's End. Spoops vill delta i högtiden och ber därför resenärer samla säsongens godsaker från värdshusvärdar och försäljare över hela världen.",al={"vem är spoops","spoops","vad är spoops"}},{q="Varför kan Spoops inte gå bus eller godis?",a="Spoops mår dåligt och är för sjuk för att gå ut och fira Hallow's End. Sjukdomen håller Spoops sängliggande, så hen förlitar sig på hjälpsamma äventyrare som besöker stadens olika värdshusvärdar och samlar högtidssötsaker.",al={"varför kan spoops inte gå bus eller godis","varför stannar spoops inne","spoops sjuk"}},{q="Vilket godis erbjuder Spoops i utbyte?",a="I utbyte mot högtidssötsakerna från värdshusvärdarna lovar Spoops särskilt godis med magiska, förvandlande egenskaper. Om du äter det kan du förvandlas till olika varelser och skepnader som är både komiska och skrämmande.",al={"vilket godis ger spoops","spoops belöningsgodis","särskilt godis"}},{q="Var hittar du godsaker åt Spoops?",a="Värdshusvärdar i huvudstäderna delar ut högtidsgodis och ber resenärer utföra bus i utbyte mot godsaker. Förutom stadens värdshus delar även trollet Kali Remik i Sen'jin Village ut säsongens sötsaker.",al={"var får jag tag på godis","vem delar ut godsaker","godisställen"}},{q="Vem är Kali Remik?",a="Kali Remik är ett troll som bor i Sen'jin Village i Durotar och deltar i Hallow's End genom att dela ut högtidsgodis till festklädda resenärer som tittar förbi.",al={"vem är kali remik","kali remik godis","sen'jin village godis"}},{q="Varför ber värdshusvärdarna om bus?",a="Under Hallow's End kräver värdshusvärdar i större bosättningar att besökare visar sin högtidsanda genom att utföra olika fåniga bus eller gester innan de delar med sig av högtidssötsakerna.",al={"vad vill värdshusvärdarna ha","värdshusvärdarnas bus","hur får man godis av värdshusvärdarna"}}},fp="31,209,19.201.0,34.230.0,14.198.0,38.150.0,41.130.0,40.137.0,18.128.0,33.153.0"}
P.entries["quest:832"] = {n="Burning Shadows",s="Den här mystiska, lysande amuletten återfanns hos Burning Blade-kultisten Gazz'uz, djupt inne i Skull Rock. Den viskar brådskande varningar i bärarens sinne. Rösten hotar särskilt Gazz'uz med Neeru Fireblades vrede. Han är en orchisk häxmästare i Orgrimmar.",h="Den här mystiska, lysande amuletten återfanns hos Burning Blade-kultisten Gazz'uz, djupt inne i Skull Rock.",kw={"burning blade","burning shadows","cleft of shadow","durotar","eye of burning shadow","gazz'uz","neeru fireblade","orgrimmar","skull rock"},ang={["class:Warlock"]="För en häxmästare som tränar i Cleft of Shadow är det en skarp påminnelse om hur tunn gränsen är mellan statsanknutna studier i demonmagi och öppet förräderi att höra Burning Blade nämna en annan utövares namn.",["faction:Horde"]="När man avslöjar viskningar mellan kultister alldeles utanför huvudstadens portar blir det tydligt att den demoniska korruptionen från den gamla Horden fortfarande frodas oroväckande nära Durotars hjärta.",["race:Orc"]="Orcher som kämpade sida vid sida med Thrall för att rena världen från Legionens smitta ser Burning Blades närvaro i Durotar som en outhärdlig skändning av deras nya hemland."},sec={{t="En röst i stenen",b="När Gazz'uz dödas djupt inne i Skull Rock hittar man en olycksbådande amulett som kallas Eye of Burning Shadow bland hans kvarlevor. Stenen är ingen livlös magisk prydnad, utan vibrerar av telepatisk kommunikation. En krävande röst talar direkt in i sinnet på den som håller den. Den begär rapporter från Gazz'uz och varnar honom för att hans hemliga verksamhet öster om Orgrimmar har avslöjats."},{t="Ett märkligt hot",b="Det som överraskar varje lojal spejare från Horden är röstens desperata ultimatum: svara, annars får Neeru Fireblade i uppdrag att jaga rätt på Gazz'uz med skoningslös brutalitet. Neeru Fireblade håller öppet till i Orgrimmars Cleft of Shadow, där han uppges utöva mörka konster under Thralls stränga uppsikt. När man överlämnar talismanen till Neeru låtsas han bli förvånad och nyfiken. Häxmästaren förundras över att hans namn användes som ett skrämmande hot mot kulten."}},faq={{q="Vad är Eye of Burning Shadow?",a="Eye of Burning Shadow är en förtrollad amulett som Burning Blade-ledaren Gazz'uz tappar inne i Skull Rock. Den fungerar som en tvåvägs telepatisk förbindelse mellan kultens agenter och deras osedda herrar.",al={"eye of burning shadow","vad är den här amuletten","gazz'uz öga"}},{q="Vem talar genom amuletten?",a="En oidentifierad överordnad inom Shadow Council eller Burning Blade försöker kontakta Gazz'uz, utan att veta att kultisten redan har dödats i Skull Rock.",al={"vem talade till mig","rösten i amuletten","vem talar genom ögat"}},{q="Varför hotar rösten Gazz'uz med Neeru Fireblade?",a="Rösten hävdar att Neeru Fireblade kommer att slå till mot Gazz'uz med brutal kraft om han inte rapporterar. Neeru säger själv att han är känd för att jaga ner hövdingens fiender, men tycker det är märkligt att just han pekades ut.",al={"varför nämna neeru","neeru fireblades hot","neerus koppling"}},{q="Var lämnar jag Eye of Burning Shadow?",a="Ta amuletten till Neeru Fireblade. Du hittar honom lutad över kittlar och böcker djupt inne i Cleft of Shadow i Orgrimmar.",al={"var lämnar jag burning shadows","var finns neeru fireblade"}},{q="Hur reagerar Neeru Fireblade när han får ögat?",a="Neeru blir nyfiken på att rösten nämnde just hans namn, och tycker det är ännu märkligare att Burning Blade-kultisterna har ett namn som liknar hans så mycket. Han behåller amuletten för att studera den och fundera över vad meddelandet betyder.",al={"neerus reaktion","vad säger neeru"}},{q="Var finns Gazz'uz?",a="Gazz'uz håller till längst in i Skull Rock, en grotta gömd bland klipporna på Durotars östra kust, strax öster om Orgrimmar.",al={"var finns gazz'uz","gazz'uz plats","bossen i skull rock"}}},fx={["286b7c01"]={q="Varför vill rösten i Eye of Burning Shadow ha en rapport?",a="Rösten som viskar genom hänget försöker få kontakt med Gazz'uz, en ledare för Burning Blade i Skull Rock. Nyheten har nått kultens ledning att Horde har upptäckt deras dolda enklav, och den osynlige befälhavaren försöker desperat samla Gazz'uz så att de kan förbereda försvaret innan ett oundvikligt anfall utplånar deras fäste.",al={"varför talar hänget","varför vill eye of burning shadow ha en rapport","röstens motiv i eye of burning shadow"}}},fp="15,139,20.260.0,16.347.1,34.212.0,36.152.0,57.213.0,42.109.0,50.205.1,25.137.0"}
P.entries["quest:833"] = {n="A Sacred Burial",s="A Sacred Burial är ett uppdrag som anförtrotts av Lorekeeper Raintotem. Det går ut på att Horde-äventyrare ska skydda Red Rocks i östra Mulgore. De heliga förfädersgravarna har intagits av härjande Bristleback quilboar, som skändar gravarna efter aktade taurenkrigare. När du driver bort inkräktarna återställs äran och friden för dem som gav sina liv för att grunda och försvara Thunder Bluff.",h="A Sacred Burial är ett uppdrag som anförtrotts av Lorekeeper Raintotem.",kw={"a sacred burial","förfäder","bristleback interloper","lorekeeper raintotem","mulgore","quilboar","red rocks","thunder bluff"},ang={["class:Shaman"]="Skändningen av helig mark oroar de ärade förfädernas andar, så ditt ingripande behövs för att återställa jordens balans.",["faction:Horde"]="När du hjälper taurenäldste att säkra sina heliga monument befäster du Hordens löfte att försvara Mulgore tillsammans med sina allierade.",["race:Tauren"]="Att försvara Red Rocks handlar om djup vördnad för förfäderna och om att se till att krigarna som möjliggjorde ditt folks förenade hemland får vila ostörda."},sec={{t="Shu'halos heliga mark",b="Red Rocks är en av de mest vördade helgedomarna i hela Mulgore. Platsen ligger undangömd bland klipporna nedanför de östra bergen och är den sista viloplatsen för de allra tappraste tauren. Hjältarna som vilar här är legendariska krigare som utgjutit blod för att skydda sina stammar, stödja sina hövdingar och skapa ett permanent hemland uppe på Thunder Bluffs platåberg. För Shu'halo är det en kränkning av både traditionen och själva Jordmodern att störa deras vila."},{t="Bristlebacks skändning",b="Bristleback-stammens nomadiska quilboar har länge utmanat taurens kontroll över centrala Kalimdor, men deras senaste framryckning mot Red Rocks innebär en allvarlig upptrappning. Grupper av Bristleback Interlopers har smugit sig in på den heliga marken, härjat jorden och stört gravfriden. Väktaren Lorekeeper Raintotem är för gammal för att ensam driva bort inkräktarna, så Hordens unga mästare måste ta till vapen, rensa platsen från inkräktare och försvara de ärade döda."}},faq={{q="Vad är Red Rocks?",a="Red Rocks är en helig förfäderskyrkogård vid Mulgorets östra berg. Den är reserverad för de allra tappraste taurenkrigarna, särskilt dem som dog när de försvarade sina stammar och grundade Thunder Bluff.",al={"var ligger red rocks","red rocks mulgore","taurenernas gravplats"}},{q="Vem är Lorekeeper Raintotem?",a="Lorekeeper Raintotem är en äldre tauren som har fått i uppgift att vårda och skydda Red Rocks heliga mark. Han vet att hans bästa år är bakom honom och att han inte kan slå tillbaka de invaderande Bristleback quilboar på egen hand. Därför ber han dugliga äventyrare att försvara de döda.",al={"raintotem","lorekeeper raintotem","vem ger uppdraget a sacred burial"}},{q="Varför är Bristleback quilboar vid Red Rocks?",a="Bristleback-stammen tränger ständigt in på taurenområden i Mulgore och The Barrens. Grupper av inkräktare, som desperat söker mark och resurser, har trängt in bland klipporna vid Red Rocks och skändat gravarna.",al={"varför är quilboar vid red rocks","bristleback interlopers","quilboar-invasion"}},{q="Varför är den här skändningen så kränkande för tauren?",a="Taurenkulturen hyser stor vördnad för förfäderna och för att leva i balans med de fallnas andar. Att låta vilda quilboar härja jorden och störa benen efter hjältar som dog för Thunder Bluff är en djup andlig kränkning.",al={"taurenernas begravningsseder","varför bryr sig tauren om begravningar"}},{q="Vart leder uppdraget härnäst?",a="A Sacred Burial är ett fristående försvarsuppdrag från Lorekeeper Raintotem. När Bristleback Interlopers har tagits om hand upphör den omedelbara skändningen.",al={"fortsättning på sacred burial","vad händer efter sacred burial"}},{q="Vilka är begravda vid Red Rocks?",a="Platsen är reserverad för taurenmästare som kämpade för sina stammars och hövdingars överlevnad, särskilt dem vars uppoffringar gjorde det möjligt att grunda och försvara Thunder Bluff.",al={"vilka är begravda här","red rocks gravar"}}},fx={e11b84bd={q="Varför ber Lorekeeper Raintotem dig om hjälp i stället för att själv driva bort dem?",a="Lorekeeper Raintotem är en äldste som helt enkelt är för gammal och har passerat sin bästa tid för att ta till vapen mot ett våldsamt krigarfölje. Han har fått i uppgift att vårda och hedra andarna vid Red Rocks, inte att strida vid frontlinjen, så han förlitar sig på dugliga resenärer som du för att ta hand om den fysiska faran och driva bort Bristleback-inkräktarna.",al={"varför kan inte raintotem göra det","varför behöver raintotem hjälp","varför strider inte raintotem"}}},fp="15,241,31.385.0,27.398.0,18.206.0,28.186.0,46.201.0,51.200.0,32.154.0,27.180.0"}
P.entries["quest:834"] = {n="Winds in the Desert",s="En stulen försörjningskaravan lämnar Rezlak väntande i Durotar. Dustwind harpies överföll den i Razorwind Canyon och spred byggmaterialet bland klipporna.",h="En stulen försörjningskaravan lämnar Rezlak väntande i Durotar.",kw={"karavan","durotar","dustwind-harpyor","gazlowe","orgrimmar","ratchet","razorwind canyon","rezlak","förnödenheter"},ang={["faction:Horde"]="Varje försändelse som går förlorad till ravinens bestar hotar Hordes snabba expansion och befästandet av dess fäste i Durotar.",["profession:Engineering"]="Som ingenjör förstår du varför Rezlak värdesätter hållbara planer och leveranser i tid, även när traktens djurliv ställer till problem.",["race:Orc"]="Som orch förlitar du dig på goblinernas skicklighet och utländska förnödenheter för att göra Durotars hårda, torra jord till ett befäst hemland."},sec={{t="En goblin med bråttom",b="Rezlak kom direkt från Ratchet, utsänd av chefsingenjör Gazlowe för att hjälpa Horde att bygga ut Durotar. Det hårda, karga landet gör redan befästningsarbetet svårt. Nu försvinner försändelser innan de når byggplatserna, och utan lasten stannar arbetet. Den lättretlige goblinförmannen har inget att bygga med."},{t="Överfall i ravinen",b="Dustwind harpies överföll den senaste försörjningskaravanen i Razorwind Canyon. De håller till i de höga ravinerna längs vägen från Razor Hill till Orgrimmar och störtar sedan ner över vagnar som passerar. Dessa asätare äter eller förstör inte lasten. De samlar lådorna och säckarna nära sina bon, där förnödenheterna finns kvar för den som vågar kämpa sig igenom deras revir."}},faq={{q="Vem är Rezlak?",a="Rezlak är en goblinarbetare som är anställd av Gazlowe, Ratchets chef. Gazlowe skickade honom till Durotar för att hjälpa orcherna med bygget utanför Orgrimmars portar.",al={"rezlak","vem är rezlak","vem gav uppdraget"}},{q="Varför hjälper gobliner till att bygga i Durotar?",a="Gazlowe och Steamwheedle Cartel har ett handels- och ingenjörssamarbete med Warchief Thrall. Gobliningenjörer och maskiner hjälpte till att lägga Orgrimmars grund, och Gazlowe förser fortfarande Horde med arbetskraft och material enligt avtal.",al={"varför hjälper gobliner orcher","gazlowe durotar","gobliners samarbete med horden"}},{q="Varifrån kom förnödenheterna?",a="Rezlak berättar inte var försändelsen började sin färd. Han säger bara att en karavan transporterade förnödenheter till hans arbete med orcherna i Durotar.",al={"varifrån kommer förnödenheterna","karavanens ursprung"}},{q="Vad gör harpyorna i Durotar?",a="Dustwind harpies är aggressiva, rovgiriga asätare som härjar på klipporna och i ravinerna i centrala Durotar. De trakasserar resenärer, plundrar handeln längs Razorwind Canyon och samlar allt glänsande eller användbart till sina bon.",al={"varför finns harpyor i durotar","dustwind-harpyornas historia","harpyor i razorwind"}},{q="Var ligger Razorwind Canyon?",a="Razorwind Canyon förgrenar sig från den stora södra ravinen mellan Orgrimmar och Razor Hill. Raviner skär in i båda klippväggarna och ger Dustwind harpies högt belägna boplatser där de gömmer stulet gods.",al={"var ligger razorwind canyon","var hittar man förnödenheterna","var finns säckarna med förnödenheter"}},{q="Varför skyddade inte orchvakterna karavanen?",a="Rezlak säger att det är svårt att skydda karavaner och att den här försändelsen hade utlovats säker passage. Han säger inte vilka vakter som följde med eller varför de inte lyckades stoppa Dustwind harpies.",al={"varför misslyckades karavanen","säkerhet i durotar","orchernas karavaner"}}},fx={["5ac1923e"]={q="Varför vill Rezlak att det här ska göras?",a="Gazlowe skickade Rezlak direkt för att övervaka Hordes ingenjörs- och byggnadsarbeten i Durotar. Utan det här nödvändiga materialet har arbetet helt stannat, och han står tomhänt och frustrerad. Han kan inte uppfylla sitt kontrakt eller slutföra de projekt han fått i uppdrag förrän lasten har bärgats.",al={"rezlaks motiv","varför behöver rezlak förnödenheter","varför bryr sig rezlak"}},ef031f2c={q="Vad är Sack of Supplies till för?",a="Säckarna innehåller ingenjörsmaterial och byggförnödenheter avsedda för Hordes byggnadsarbeten i Durotar. Rezlak och hans besättning behöver dem för att slutföra byggprojekten åt orcherna, men materialet spreds ut över Razorwind Canyon när Dustwind-harpiorna överföll leveranskaravanen.",al={"sack of supplies användning","vad är sack of supplies","rezlaks förnödenhetssäckar"}}},fp="19,156,22.315.0,20.349.0,14.145.0,41.237.0,33.129.0,38.220.0,34.190.0,46.182.0"}
P.entries["quest:835"] = {n="Securing the Lines",s="Nära Razorwind Canyon behöver Rezlak skydd för goblinernas försörjningsleder genom Durotar. Harpyor i Drygulch Ravine fortsätter att genskjuta och plundra karavaner, så han anlitar hjälp för att driva bort dem.",h="Nära Razorwind Canyon behöver Rezlak skydd för goblinernas försörjningsleder genom Durotar.",kw={"drygulch ravine","dustwind savage","dustwind storm witch","gazlowe","ratchet","razorwind canyon","rezlak","securing the lines"},ang={["faction:Horde"]="När harpyorna i östra Razorwind Canyon rensas bort kan varor och förstärkningar färdas mellan Durotars utposter vid gränsen och handelsknutpunkterna längs kusten.",["profession:Engineering"]="När Rezlaks laster hålls säkra kan goblinkomponenter färdas från Ratchet till lokala uppfinnare."},sec={{t="En led plågad av harpyor",b="Dustwind-harpyor gör resor genom Durotars torra dalar farliga. Rezlak ansvarar för regionens försörjningsverksamhet åt sin chef, Gazlowe. Harpyorna som häckar i Drygulch Ravine anfaller karavaner i Razorwind Canyon och beslagtar laster innan de når sina mål."},{t="Affärer och blodsutgjutelse",b="Rezlak tror att rätt pris kan få vad som helst gjort. I stället för att själv gå in i ravinen anlitar han äventyrare för att bryta upp boet genom att döda Dustwind Savages och Dustwind Storm Witches. När harpyorna rensas bort hålls handelslederna öppna, ingenjörsprylarna kommer fram säkert och hjälpsamma resenärer får tips om större möjligheter i Ratchet."}},faq={{q="Vem arbetar Rezlak åt?",a="Rezlak arbetar för Gazlowe, chefsingenjör och Ratchets ledare, i den neutrala goblinhamnstaden. Gazlowe övervakar omfattande handel och infrastrukturprojekt i Durotar och The Barrens.",al={"rezlaks chef","vem arbetar rezlak för","rezlaks arbetsgivare"}},{q="Varför angriper harpyorna karavaner?",a="Dustwind-harpyorna häckar i Drygulch Ravine, som löper längs Razorwind Canyons främsta färdvägar. De anfaller inkräktare och plundrar närliggande vagnar och varor.",al={"varför angriper harpyor","dustwind-harpyornas motiv","varför drygulch ravine"}},{q="Var ligger Drygulch Ravine?",a="Drygulch Ravine ligger djupt i de östra delarna av Razorwind Canyon i norra Durotar, uthuggen i de torra, karmosinröda kullarna.",al={"drygulch ravines läge","var ligger drygulch ravine","hur hittar man drygulch"}},{q="Vad händer efter att du hjälpt Rezlak?",a="När Dustwind-harpyorna har decimerats och försörjningsleden är säkrad hänvisar Rezlak äventyrarna över gränsen till Ratchet i The Barrens. Han uppmuntrar dem att söka upp Gazlowe för fler lukrativa uppdrag.",al={"efter securing the lines","rezlaks nästa uppdrag","vad händer efter rezlak"}},{q="Varför tar inte Horden hand om harpyorna i stället för goblinerna?",a="Horden har utposter i Durotar, men resurserna är hårt ansträngda av kentaurer, quilboar och bosättningarnas behov. Goblinhandlare som Rezlak tycker ofta att det går snabbare och kostar mindre att anlita fristående äventyrare för att skydda sina egna affärer.",al={"varför anlitar gobliner","varför tar inte orgrimmar hand om det här","horden och harpyorna"}},{q="Vilka slags harpyor bor i Drygulch Ravine?",a="Boet i Drygulch Ravine hyser vilda Dustwind Savages, som anfaller på nära håll, och Dustwind Storm Witches, som använder vind och blixtar mot karavaner som kommer in på deras område.",al={"harpytyper","dustwind-harpytyper","fiender i drygulch"}}},fx={bafa495b={q="Varför vill Rezlak att harpiorna ska drivas bort?",a="Rezlak ansvarar för att lasten kommer fram genom Durotar, men Dustwind-harpiorna i Drygulch Ravine har överfallit och plundrat hans försörjningskaravaner. Varje förlorad vagn kostar guld, försenar livsviktigt material och äventyrar kommande leveranser, däribland specialutrustning som han själv väntar på från Ratchet.",al={"rezlaks motiv","varför döda harpiorna i drygulch ravine","rezlaks problem med karavanen"}}},fp="18,182,26.278.0,22.363.0,26.191.0,39.168.0,33.125.0,34.209.0,60.259.0,48.172.0"}
P.entries["quest:8353"] = {n="Chicken Clucking for a Mint",s="Chicken Clucking for a Mint är ett lättsamt säsongsuppdrag för Alliansen i Ironforge under Hallow's End. För att få ett traditionellt Ironforge Mint åt det unga föräldralösa barnet Jesper måste äventyrarna lägga sin stridshärdade värdighet åt sidan och flaxa med armarna medan de kacklar som en höna för att roa gästerna på värdshuset. Innkeeper Firebrew belönar gärna alla som sväljer sin stolthet för att sprida högtidsglädje till ett barn.",h="Chicken Clucking for a Mint är ett lättsamt säsongsuppdrag för Alliansen i Ironforge under Hallow's End.",kw={"höna","kackla","firebrew","hallow's end","värdshusvärd","ironforge mint","jesper","godsaker"},ang={["faction:Alliance"]="Det här säsongsärendet lyfter fram kamratskapen mellan Alliansens huvudstäder och knyter Ironforges dvärggästfrihet direkt till att muntra upp ett föräldralöst barn i Stormwind.",["race:Dwarf"]="Dvärgar uppskattar god humor, rejäla drycker och högtidstraditioner. Firebrews krav visar att ingen gäst i Ironforge tar sig själv på alltför stort allvar."},sec={{t="En Hallow's End-tradition",b="Under Hallow's End är stämningen hög över hela Azeroth när folk firar skiftet mellan skörd och vinter med maskerad fest och säsongens godsaker. Även om erfarna hjältar vanligtvis kan känna sig för gamla för att gå från dörr till dörr och tigga godis, ger sjuka eller föräldralösa barns situation en hedervärd ursäkt. I Stormwind längtar den unge Jesper efter högtidens sötsaker, så Alliansens hjältar på besök samlar in välkända regionala godsaker från värdshusvärdar i Alliansens huvudstäder."},{t="Innkeeper Firebrews pris",b="Bakom disken på det livliga värdshuset i Ironforge står Innkeeper Firebrew, väktare av de berömda Ironforge Mints. Firebrew låter aldrig en äventyrare komma undan så lätt och vägrar lämna över godsaken bara för att någon ber om den. Hen kräver underhållning och begär att härdade krigare och stoisk magiker ska flaxa och kackla som hönsfåglar innan de får priset. Allt är för högtidsfirandets skull och ger värdshusets gäster ett gott skratt på hjältens bekostnad."}},faq={{q="Varför vill Innkeeper Firebrew att jag ska kackla som en höna?",a="Innkeeper Firebrew tar till sig Hallow's Ends lekfulla anda. Eftersom erfarna äventyrare är alldeles för gamla för att vanligtvis gå bus eller godis kräver hen ett komiskt bus innan hen lämnar över sitt godis. Hen tycker att det är bra underhållning på värdshuset att se en mäktig hjälte flaxa med armarna och kackla, och byter glatt bort ett Ironforge Mint mot lite offentlig förödmjukelse.",al={"varför kackla som en höna","varför firebrew kräver hönekackel","varför måste jag kackla"}},{q="Vem är Jesper och varför hämtar jag mintgodis åt honom?",a="Jesper är ett sjukt föräldralöst barn som bor i Stormwind och inte själv kan delta i stadens Hallow's End-festligheter. För att göra honom glad utför Alliansens äventyrare säsongsärenden runt om i världen och samlar in fyra särskilda högtidsgodisar från varje större stad i Alliansen, däribland det krispiga Ironforge Mint från Dun Morogh.",al={"vem är jesper","varför får jag mintgodis","jesper föräldralöst barn"}},{q="Hur passar uppdraget in i Hallow's End-högtiden?",a="Uppdraget är ett av fyra regionala ärenden som ingår i det övergripande säsongsuppdraget 'Hallow's End Treats for Jesper!', tillsammans med önskemål från värdshusvärdarna i Stormwind och Darnassus samt från Talvash del Kissel i Ironforge. Var och en kräver en särskild förödmjukande eller teatralisk emote innan de lämnar över stadens signaturgodis.",al={"hallow's end-uppdragskedja","jespers godisuppdrag","uppdragsordning"}},{q="Var hittar jag Innkeeper Firebrew?",a="Innkeeper Firebrew står bakom baren vid eldstaden inne på Stonefire Tavern i Ironforges Commons. Hen serverar drycker och erbjuder resande logi mitt i dvärgarnas huvudstad.",al={"var är firebrew","firebrews plats","värdshusvärd i ironforge"}},{q="Vad får jag för att kackla?",a="När du kacklar ger Innkeeper Firebrew dig ett Ironforge Mint, ett högtidsgodis som bara finns under evenemanget. Du behöver ta med det tillbaka till Stormwind för att komplettera Jespers samling av Hallow's End-godsaker.",al={"uppdragsbelöning","vad är mintgodiset","ironforge mint"}},{q="Kan Horde-spelare slutföra uppdraget?",a="Nej, uppdraget är exklusivt för Alliansen. Horde-äventyrare har en egen motsvarighet hos det föräldralösa barnet Spoops, som skickar hjältar till Horde-huvudstäderna för att samla in godsaker från värdshusvärdar i Orgrimmar, Undercity och Thunder Bluff.",al={"är uppdraget bara för alliansen","horde-uppdrag med hönekackel","kan horde göra det här"}}},fp="27,193,24.246.0,26.296.0,60.230.0,49.232.0,56.254.0,36.124.0,31.127.0,37.160.0"}
P.entries["quest:8354"] = {n="Chicken Clucking for a Mint",s="Under festligheterna kring Hallow's End erbjuder Innkeeper Norman i Undercity en karamell till resenärer som hjälper ett sjukt barn. För att få Undercity Mint måste äventyrarna lägga värdigheten åt sidan och flaxa runt som en kyckling.",h="Under festligheterna kring Hallow's End erbjuder Innkeeper Norman i Undercity en karamell till resenärer som...",kw={"kyckling","kackla","hallow's end","innkeeper norman","spoops","trade quarter","undercity","undercity mint"},ang={["faction:Horde"]="Äventyrare från Horde reser mellan alla huvudstäder under Hallow's End och uthärdar löjliga förödmjukelser i varje stad för att glädja ett föräldralöst barn.",["race:Undead"]="Det är ovanligt att hitta fånig humor bland Undercitys ruttnande salar, så Normans säsongsbundna krav blir ett bisarrt avbrott från vardagens nekromantiska pragmatism."},sec={{t="En sällsynt glimt av munterhet",b="Undercity förknippas sällan med skratt eller värme, eftersom staden byggdes under Ruins of Lordaeron av de befriade Forsaken. Men när Hallow's End kommer deltar även de dystra invånarna i Trade Quarter i säsongens festligheter. Innkeeper Norman har ett förråd av Undercity Mints som är avsedda för dem som samlar godsaker åt unge Spoops, ett sjukt föräldralöst barn som behöver lite högtidsglädje."},{t="Förtjäna godsaken",b="Norman ger inte godsaken till erfarna äventyrare utan vidare, utan kräver en förödmjukande uppvisning. Han tycker att vuxna krigare och magiker ska förtjäna sina sötsaker och vägrar lämna ifrån sig myntet förrän den som ber om det härmar en hönsgårdskyckling precis framför hans disk."}},faq={{q="Varför vill Innkeeper Norman att jag ska kackla som en kyckling?",a="Innkeeper Norman tycker att vuxna hjältar är för gamla för att gå runt och bus eller godis utan att bjuda på en uppvisning. För att lätta upp stämningen under Hallow's End kräver han ett löjligt framträdande – att flaxa och kackla som en kyckling – innan han lämnar över sin högtidsgåva.",al={"varför kycklingemote","varför kackla åt norman","normans kycklingdans"}},{q="Vem är godsaken avsedd för?",a="Undercity Mint samlas in åt Spoops, ett sjukt föräldralöst barn som vilar i Orgrimmar och inte själv kan gå bus eller godis under Hallow's End-festivalen.",al={"vem får myntet","vad är myntet till för","varför skaffa undercity mint"}},{q="Var finns Innkeeper Norman?",a="Innkeeper Norman driver den centrala tavernan i Undercitys Trade Quarter, där han serverar Forsaken-gäster och besökande resenärer från Horde.",al={"normans plats","var finns värdshusvärden i undercity"}},{q="Är det här ett säsongsbundet festivaluppdrag?",a="Ja. Uppdraget är en del av det årliga Hallow's End-firandet, som både Horde och Alliance firar runtom i Azeroth.",al={"är det här hallows end","när är uppdraget tillgängligt"}},{q="Brukar Forsaken fira Hallow's End?",a="Forsaken firar Hallow's End med stor entusiasm och bränner en enorm halmgubbe utanför Ruins of Lordaeron för att högtidlighålla sin befrielse och brytning med sina tidigare liv som dödliga.",al={"forsakens hallows end","odöd högtid"}},{q="Vad händer när jag har fått Undercity Mint?",a="Myntet kombineras med andra särskilda godsaker som samlats in från Hordes olika rashuvudstäder, så att en fullständig högtidsgåva kan sättas ihop åt unge Spoops.",al={"nästa uppdrag","vad gör jag med myntet"}}},fp="27,181,19.303.0,17.222.0,58.201.0,30.121.0,34.130.0,34.105.0,44.183.0,46.129.0"}
P.entries["quest:8355"] = {n="Incoming Gumdrop",s="Incoming Gumdrop är ett säsongsuppdrag under Hallow's End i Ironforge, som ges av gnomhantverkaren Talvash del Kissel. För att få en festlig godsak till ett sjukt barn i Stormwind måste äventyrarna först härma ett tåg så att den förtjuste gnomen skrattar.",h="Incoming Gumdrop är ett säsongsuppdrag under Hallow's End i Ironforge, som ges av gnomhantverkaren Talvash...",kw={"gnomeregan gumdrop","hallow's end","incoming gumdrop","ironforge","jesper","talvash del kissel","tinker town","tågemot"},ang={["faction:Alliance"]="Jakten på festivalens gumdrop skickar Alliansens hjältar genom kungadömena för att se till att ett sjukt barn i Stormwind också får ta del av högtiden.",["race:Gnome"]="För de förvisade gnomerna i Tinker Town är en Gnomeregan Gumdrop under Hallow's End en glad påminnelse om hemmet och gnomernas mekaniska uppfinningsrikedom mitt i fördrivningen."},sec={{t="Ett lekfullt pris",b="Under höstens Hallow's End-firande letar de som går bus eller godis genom Alliansens främsta fästen efter unika regionala sötsaker. I Mystic Ward i Ironforge har gnomen Talvash del Kissel den eftertraktade Gnomeregan Gumdrop. Han känner med den unga föräldralösas längtan efter den, men insisterar på att hålla fast vid högtidens busiga anda innan han lämnar ifrån sig sötsaken. Han kräver att den som vill få en ska härma ett tåg övertygande."},{t="Högtidsgåva",b="Uppdraget ingår i ett större säsongsäventyr för att sprida glädje till Jesper, en sjuk föräldralös som vilar i Stormwind City. Jesper längtar efter fyra olika godsaker från Alliansens områden: nougat från Stormwind, en mint från Ironforge, en bit marsipan från Darnassus och en gumdrop från Gnomeregan. Genom att härma ett pustande lok för att roa Talvash får kämparna gnomens sötsak och kan uppfylla den unge pojkens önskan inför högtiden."}},faq={{q="Vad behöver jag göra för att slutföra Incoming Gumdrop?",a="Du måste rikta in dig på Talvash del Kissel och använda tågemoten för att härma ett tåg. När han hör tågljudet ger han dig gärna Gnomeregan Gumdrop.",al={"hur gör man incoming gumdrop","målet med incoming gumdrop","talvash gumdrop bus"}},{q="Vem är Talvash del Kissel?",a="Talvash del Kissel är en gnomjuvelerare från Gnomeregan som bor i Mystic Ward i bergsstaden Ironforge, där dvärgarna håller till. Under Hallow's End delar han ut Gnomeregans signaturgumdrops åt Alliansen.",al={"vem är talvash","talvash del kissels bakgrund"}},{q="Vad används Gnomeregan Gumdrop till?",a="Gnomeregan Gumdrop är en av fyra olika festgodisar som samlas in för att uppfylla Jespers önskan under Hallow's End. Jesper är en föräldralös pojke som vilar på barnhemmet i Stormwind City.",al={"vad används gnomeregan gumdrop till","vad är gumdropen till för"}},{q="Var hittar jag Talvash del Kissel?",a="Talvash finns i Mystic Ward i Ironforge.",al={"var finns talvash","talvashs plats"}},{q="Varför får Talvash dig att härma ett tåg?",a="Hallow's End bygger på traditionen att gå bus eller godis. Talvash ber skämtsamt om ett harmlöst bus, en lokhärmning, innan han lämnar ifrån sig sin festliga godsak.",al={"varför tågljud","varför härma tåg åt talvash"}},{q="Är uppdraget tillgängligt året runt?",a="Nej, uppdraget är bara tillgängligt under den årliga höstfestivalen Hallow's End.",al={"kan jag göra incoming gumdrop när som helst","är det här säsongsbundet"}}},fp="16,150,16.308.0,15.323.0,50.116.0,26.176.0,40.135.0,38.61.0,42.143.0,35.75.0"}
P.entries["quest:8356"] = {n="Flexing for Nougat",s="Under Hallow's End på hösten samlar du festliga sötsaker åt ett föräldralöst barn i Stormwind. Innkeeper Allison på Gilded Rose ber dig spänna musklerna innan hon ger dig Stormwind Nougat.",h="Under Hallow's End på hösten samlar du festliga sötsaker åt ett föräldralöst barn i Stormwind.",kw={"flexing for nougat","gilded rose","hallow's end","innkeeper allison","jesper","stormwind city","stormwind nougat","bus eller godis"},ang={["class:Warrior"]="Som krigare känner du blodiga slagfält väl. Att spänna musklerna för en värdshusvärd är en harmlös, om än något ovärdig, styrkeuppvisning.",["faction:Alliance"]="För Alliansen speglar detta lekfulla utbyte Stormwinds lättsammare gemenskapsanda under Hallow's End och andra säsongshögtider, och för samman invånare och kringvandrande hjältar för ett gott skratt.",["race:Human"]="Som människa i Stormwind vet du att det är en uppskattad årstidstradition att skämma bort barn och byta spratt mot godsaker. Den ger en kort paus från de mörkare faror som hotar riket."},sec={{t="En tradition vid Hallow's End",b="Hallow's End sprider en lättare stämning på Stormwinds gator. Högtiden markerar årstidernas växling och håller mörka andar borta. Vanligt folk firar med förklädnader, festligheter och bus eller godis. Alliansens värdshusvärdar deltar och erbjuder traditionella sötsaker åt dem som utför ett harmlöst spratt."},{t="Underhålla värdshusvärden",b="På Gilded Rose i Trade District ber Innkeeper Allison dig visa upp dig innan hon delar ut högtidsgodis, även när du samlar sötsaker åt Jesper, en föräldralös pojke. Hon kommenterar lekfullt din fysik och ber dig spänna musklerna. När du gör det ger hon dig en bit seg Stormwind Nougat."}},faq={{q="Varför ber Innkeeper Allison folk att spänna musklerna?",a="Under Hallow's End byter man spratt mot godsaker, så Innkeeper Allison ber dig visa upp musklerna innan hon ger dig sötsaken.",al={"varför spänna musklerna för nougat","vad vill allison","varför använda spänningsgesten"}},{q="Var utspelar sig uppdraget?",a="Du träffar Innkeeper Allison på Gilded Rose, mitt i Stormwinds Trade District, där hon sköter värdshusets disk.",al={"var finns flexing for nougat","allisons plats","värdshusvärden på gilded rose"}},{q="Vem är Stormwind Nougat avsett för?",a="Nougaten är till Jesper, en föräldralös pojke som bor i Stormwind. Under Hallow's End hoppas han få smaka på traditionella festgodsaker från varje större alliansstad.",al={"vem får nougaten","vem vill ha stormwind nougat","jespers godis"}},{q="Vad är Stormwind Nougat?",a="Stormwind Nougat är en lokal sötsak som värdshusvärdarna i Stormwind delar ut under Hallow's End. Festbesökare känner den som en av människorikets särskilda godsaker.",al={"stormwind nougat-lore","hallow's end-nougat","stormwind-godis"}},{q="Kan hordespelare få den här sötsaken från Allison?",a="Nej. Innkeeper Allison bor djupt inne i allianskontrollerade Stormwind City och betjänar alliansmedlemmar. Hordens äventyrare utför egna festliga spratt för värdshusvärdar i sina huvudstäder.",al={"kan horden spänna musklerna för nougat","hordens version av nougat"}},{q="Pågår uppdraget året runt?",a="Nej. Innkeeper Allison erbjuder det här uppdraget endast under Hallow's End, den säsongsbundna högtiden då bus eller godis fyller städerna.",al={"när går det att göra flexing for nougat","är uppdraget säsongsbundet","när infaller hallow's end"}}},fp="18,176,24.276.0,26.304.0,44.116.0,33.112.0,38.158.0,25.165.0,49.179.0,34.114.0"}
P.entries["quest:8357"] = {n="Dancing for Marzipan",s="Under den festliga säsongen Hallow's End får äventyrare som färdas genom Darnassus i uppdrag att samla festligt godis åt ett sjukt föräldralöst barn i Stormwind. Innkeeper Saelienne håller fast vid bus eller godis-traditionen och kräver en spontan dansuppvisning innan hon lämnar ifrån sig sin uppskattade Darnassus Marzipan.",h="Under den festliga säsongen Hallow's End får äventyrare som färdas genom Darnassus i uppdrag att samla...",kw={"dansa","darnassus","hallow's end","värdshusvärd","jesper","marsipan","saelienne","teldrassil"},ang={["faction:Alliance"]="Den här festliga uppgiften visar den enighet och lättsamma gemenskap som delas mellan Alliansens huvudstäder, när godsaker förs hela vägen från avlägsna Teldrassil till ett ungt föräldralöst barn i Stormwind.",["race:NightElf"]="För nattalverna är deltagandet i Hallow's End ett kärleksfullt anammande av Alliansens säsongsseder, där deras fridfulla liv i skogen blandas med lekfullt festande."},sec={{t="En tradition att upprätthålla",b="Även i skogsstaden Darnassus, som är helig för nattalverna, gör festligheterna under Hallow's End deras långlivade folk mer lättsinnigt. När resenärer kommer för att samla högtidsgodis åt Jesper, ett sjukt barn som återhämtar sig i Stormwind, insisterar Innkeeper Saelienne på att säsongens regler ska följas. Välgörenhet eller inte, först krävs ett ordentligt bus för att få godis."},{t="Priset för marsipanen",b="För att få Darnassus Marzipan måste äventyrarna lägga sin värdiga uppsyn åt sidan och bjuda på en föreställning mitt på värdshusgolvet. Saelienne kräver inget mindre än en dans och belönar gärna dem som är villiga att släppa stoltheten och hänge sig åt feststämningen med konfekten som behövs för att färdigställa högtidspaketet som ska skickas tvärs över kontinenten."}},faq={{q="Vad är syftet med Dancing for Marzipan?",a="Uppdraget är en del av Alliansens säsongsfirande under Hallow's End. Du dansar för Innkeeper Saelienne i Darnassus för att få Darnassus Marzipan, ett av flera högtidsgodisar som behövs för att muntra upp ett sjukt föräldralöst barn vid namn Jesper i Stormwind.",al={"varför dansa för marsipan","vad är det här för uppdrag","marsipanuppdrag"}},{q="Vem är Innkeeper Saelienne?",a="Innkeeper Saelienne driver värdshuset i Darnassus och erbjuder resenärer skydd och vila under Teldrassils grenar. Under Hallow's End ansvarar hon för utdelningen av lokalt högtidsgodis till dem som är villiga att följa traditionen.",al={"vem är saelienne","saeliannes bakgrund"}},{q="Varför insisterar Saelienne på en dans?",a="Saelienne håller strikt fast vid Hallow's Ends anda. Även om godiset är avsett för ett sjukt barn håller hon fast vid seden ”bus eller godis” och ber lekfullt om ett prov på dansförmågan som bus innan hon lämnar över sötsaken.",al={"varför dansa","varför vill saelienne att jag ska dansa"}},{q="Vart tar marsipanen vägen sedan?",a="När du har fått den packas Darnassus Marzipan tillsammans med säsongsgodis från värdshusen i Ironforge och Stormwind och från Talvash del Kissel i Ironforge, för att slutföra uppdraget att sprida högtidsglädje till unge Jesper i Stormwind.",al={"vem får marsipanen","vad gör man med marsipan"}},{q="Vad är Darnassus Marzipan?",a="Darnassus Marzipan är en sockrig konfekt som tillverkas i nattalvernas huvudstad. Den är Darnassus signaturgodis för besökande bus eller godis-firare under Hallow's End.",al={"darnassus marzipans bakgrund","vad är det för sorts godis"}},{q="Kan Horde-spelare slutföra det här uppdraget?",a="Nej. Dancing for Marzipan är ett säsongsuppdrag som bara är tillgängligt för Alliansen. Darnassus är ett fäste för Alliansen, och marsipanen samlas särskilt in åt ett föräldralöst barn från Alliansen som återhämtar sig i Stormwind City.",al={"är uppdraget bara för alliansen","horde marsipanuppdrag"}}},fp="20,206,18.289.0,21.165.0,44.162.0,27.197.0,37.130.0,38.214.0,27.132.0,38.155.0"}
P.entries["quest:8359"] = {n="Flexing for Nougat",s="I Orgrimmar erbjuder Innkeeper Gryshka nougat till den som spelar med. Under Hallow's End ber hon dig spänna musklerna för att få en bit som ska muntra upp Spoops, ett sängliggande barn.",h="I Orgrimmar erbjuder Innkeeper Gryshka nougat till den som spelar med.",kw={"godis","visa musklerna","gryshka","hallow's end","nougat","orgrimmar","spoops","bus eller godis"},ang={["class:Warrior"]="Som krigare kan du vara stolt över dina förödande bedrifter vid fronten, men ändå tycka att det är roligt eller ödmjukande att posera som en scenartist för festgodis.",["faction:Horde"]="Till och med veteraner bland Hordens hjältar, som möter dödliga krigsherrar, spänner bicepsen för värdshusvärdar för att samla festgodis åt barnen.",["race:Orc"]="Som orc ställs din stolthet på prov under högtiden när värdshusvärden i Orgrimmar ber dig visa upp dina muskler."},sec={{t="Bus eller godis",b="Hallow's End för med sig upptåg och godisjakt till Azeroths huvudstäder. På värdshuset i Orgrimmar har Innkeeper Gryshka högtidsgodis åt dem som deltar i säsongens sed. Du möter drakar och mörk trolldom på dina resor, men här är bytet enkelt: gör ett trick eller gå utan godis."},{t="Musklerna visas upp",b="Innkeeper Gryshka vill se prov på orcisk styrka innan hon ger dig Orgrimmar Nougat åt unge Spoops. Oavsett vilken förklädnad eller rustning du bär ber hon dig inta en muskulös pose. Till och med Hordens fruktade stridskämpar kan få underhålla vanligt folk för godis."}},faq={{q="Vem ber om att få se musklerna?",a="Innkeeper Gryshka, som driver huvudvärdshuset i Orgrimmars Valley of Strength, ber dig göra ett trick innan hon räcker över högtidsgodis.",al={"vem ger uppdraget","gryshka","innkeeper gryshka"}},{q="Varför måste jag visa musklerna för godis?",a="Enligt seden under Hallow's End ska man göra ett litet trick i utbyte mot godis. Gryshka retas med dig genom att be dig visa prov på ren fysisk styrka innan hon ger dig godis.",al={"varför visa musklerna","vad är buset","villkor för nougat"}},{q="Vad används Orgrimmar Nougat till?",a="Nougaten är en av fyra sorters godis som samlas in i Hordens huvudstäder för att muntra upp Spoops, en sjuk föräldralös pojke som är sängliggande och inte kan gå bus eller godis på egen hand.",al={"varför behöver jag nougat","vad används nougaten till","godis åt spoops"}},{q="Var bor Innkeeper Gryshka?",a="Innkeeper Gryshka sköter disken på huvudvärdshuset i Orgrimmars Valley of Strength, där hon betjänar trötta resenärer och lokalbor.",al={"var är gryshka","var finns värdshusvärden i orgrimmar"}},{q="Kan alla i Horden delta?",a="Ja. Alla medlemmar i Horden kan besöka Innkeeper Gryshka under Hallow's End, inta en pose och få säsongens godis.",al={"vem kan visa musklerna","fraktionsbegränsningar","endast horden"}},{q="Vilken högtid hör detta till?",a="Det är en del av Hallow's End, en höstfestival som markerar skördens slut och trotsar dödligheten med kostymer, upptåg och godis.",al={"vilket evenemang","vilken högtid","hallow's end-uppdrag"}}},fp="18,148,17.282.0,17.237.0,27.143.0,32.161.0,38.159.0,36.131.0,41.122.0,31.136.0"}
P.entries["quest:836"] = {n="Rescue OOX-09/HL!",s="När fyren har väckt den fallna navigeringsroboten talar Oglethorpe Obnoticus genom roboten. OOX-09/HL behöver en öppen och säker plats för att påbörja starten, så den ska eskorteras till stranden bortom Overlook Cliff. Sedan väntar Oglethorpe i Booty Bay.",h="När fyren har väckt den fallna navigeringsroboten talar Oglethorpe Obnoticus genom roboten.",kw={"booty bay","kamouflage","navigeringsrobot","oglethorpe obnoticus","overlook cliff","oox-09/hl"},sec={{t="En promenad till stranden",b="Oglethorpes röst sprakar åter genom roboten. Maskinen behöver en öppen och säker plats för att påbörja en lång startprocedur, och stranden bortom Overlook Cliff passar utmärkt. Dess inbyggda kamouflage kan ännu inte användas, och Oglethorpe behöver tid för att få det att fungera igen."},{t="Nytt från Booty Bay",b="När roboten har förts säkert till stranden ber Oglethorpe Obnoticus dig att komma och prata i Booty Bay."}},faq={{q="Vart ska roboten eskorteras?",a="OOX-09/HL ska föras till stranden bortom Overlook Cliff, en öppen plats där den kan påbörja starten.",al={"vart ska oox-09","hinterlands kyckling eskort mål","stranden vid overlook cliff"}},{q="Vem ligger bakom skapandet av den här navigeringsroboten?",a="Roboten är skapad av gnomen Oglethorpe Obnoticus, som befinner sig i Booty Bay.",al={"vem skapade oox-09","oox skapare","vem byggde kycklingen"}},{q="Varför kan roboten inte bara lyfta där den hittades?",a="Startproceduren är lång och kräver en öppen och säker plats. Under tiden behöver Oglethorpe tid för att få robotens kamouflage att fungera igen.",al={"varför går kycklingen","varför eskortera oox-09"}},{q="Vart går du när eskorteringen nått stranden?",a="Oglethorpe Obnoticus ber dig komma till Booty Bay när roboten är säkert framme vid stranden.",al={"var lämnar man in rescue oox-09","vem ska jag rapportera till","oglethorpes plats"}},{q="Vad hände före den här eskorteringen?",a="Uppdraget följer efter Find OOX-09/HL!, där nödsignalen fördes till den kraschade roboten.",al={"föregående uppdrag för oox-09","förkunskapskrav för rescue oox-09"}}},fp="17,187,19.257.0,17.102.0,41.96.0,50.69.0,55.115.0,50.94.0,29.88.0"}
P.entries["quest:8360"] = {n="Dancing for Marzipan",s="Dancing for Marzipan är ett festligt uppdrag under Hallow's End som Innkeeper Pala erbjuder i Thunder Bluff. För att samla en godsak åt ett sjukt föräldralöst barn måste äventyrarna lägga sin stridshärdade värdighet åt sidan och bjuda värdshusvärden på en glad dans. Uppdraget lyfter fram högtidens lekfulla gemenskap, även högt uppe på Mulgore vindpinade platåer.",h="Dancing for Marzipan är ett festligt uppdrag under Hallow's End som Innkeeper Pala erbjuder i Thunder Bluff.",kw={"dancing for marzipan","hallow's end","innkeeper pala","marsipan","mulgore","thunder bluff","bus eller godis"},ang={["faction:Horde"]="Ett lättsammare inslag i hordens hårda vardag, som visar fraktionens hjärta när resenärer färdas mellan huvudstäder för att sprida högtidsglädje till ett föräldralöst barn.",["race:Tauren"]="Innkeeper Pala sprider traditionell högtidsglädje ända till Mulgore och visar att även resliga, lugna taurer gärna dansar för en god sak."},sec={{t="En dans på höjden",b="Under Hallow's Ends höstfestival går festyran hög i Azeroth, även på Thunder Bluffs fridfulla höjder. Innkeeper Pala, som sköter gästfriheten på de höga platåerna, rycks med i feststämningen och kräver ett spratt innan hon delar ut godsaker. Även när en äventyrare kommer för ett sjukt barns räkning håller traditionen i sig: Pala vill se en festlig dans innan hon lämnar ifrån sig sin uppskattade Thunder Bluff Marzipan."},{t="Spratt mot godsaker",b="Högtidsseden att byta underhållning mot sötsaker lockar fram en ovanligt lättsam sida av hordens kultur. Pala ber dig bara att kliva fram, skaka av dig resans trötthet och visa dina bästa danssteg. När hon blivit ordentligt underhållen lämnar värdshusvärden gärna över marsipanen och skickar varma hälsningar till den sjuka unga mottagaren."}},faq={{q="Vad går Dancing for Marzipan ut på?",a="Uppdraget går ut på att utföra en dansgest åt Innkeeper Pala i Thunder Bluff. I gengäld får du en bit Thunder Bluff Marzipan, som ingår i en större samling högtidsgodsaker åt ett sjukt föräldralöst barn under Hallow's End.",al={"varför dansa för marsipan","målet med marsipanuppdraget","syftet med dancing for marzipan"}},{q="Vem ger uppdraget?",a="Innkeeper Pala, en tauren som driver värdshus åt besökare och lokalbefolkningen i Thunder Bluff, erbjuder uppdraget under Hallow's End.",al={"vem startar dancing for marzipan","pala uppdrag","innkeeper pala thunder bluff"}},{q="Varför kräver Pala en dans när godiset är till ett sjukt barn?",a="Pala betonar att högtidstraditioner måste respekteras, även när ärendet är ädelt. Enligt bus eller godis-seden måste man utföra ett spratt för att förtjäna den söta belöningen, så att Hallow's End förblir glatt och livfullt.",al={"varför måste jag dansa","varför vill pala se en dans"}},{q="Vad får du för att dansa?",a="Du får en bit Thunder Bluff Marzipan, en lokal festlig sötsak som behövs för att slutföra den större samlingen Hallow's End-godsaker åt det sjuka barnet.",al={"marsipanbelöning","föremål från dancing for marzipan"}},{q="Kan alliansspelare slutföra uppdraget?",a="Nej. Innkeeper Pala är en handelsman från horden som håller till mitt i Thunder Bluff, så just detta stopp under högtidens godisrunda är bara tillgängligt för hordens medlemmar.",al={"är uppdraget bara för horden","alliansen dancing for marzipan"}},{q="När är uppdraget tillgängligt?",a="Uppdraget är bara tillgängligt under den årliga hösthögtiden Hallow's End, då värdshusvärdar i Azeroth erbjuder särskilda sötsaker och festliga lekar.",al={"när kan jag få marsipan","hallow's end marsipanuppdrag"}}},fp="20,185,20.215.0,17.180.0,44.168.0,21.123.0,65.123.0,39.138.0,41.125.0,29.133.0"}
P.entries["quest:837"] = {n="Encroachment",s="Encroachment är ett Horde-uppdrag som Gar'Thok ger vid Razor Hill i centrala Durotar. Hjältarna ska slå till djupt inne i de västra snårnästena och utrota de förskansade Razormane quilboar som hotar den unga orcnationens gränser.",h="Encroachment är ett Horde-uppdrag som Gar'Thok ger vid Razor Hill i centrala Durotar.",kw={"snår","durotar","encroachment","gar'thok","quilboar","razor hill","razormane"},ang={["faction:Horde"]="Det är avgörande att säkra Durotar mot de inhemska Razormane quilboar för att skapa ett tryggt, permanent hemland åt det gryende Horde.",["race:Orc"]="Orcherna har gjort anspråk på Durotar som sitt nya självständiga land och ser de kvarvarande snårnästena från Razormane som ett oacceptabelt hot mot sina bosättningar."},sec={{t="En tagg i Durotars sida",b="När Thrall ledde orcherna till Kalimdor och grundade Durotar fann de att stora delar av det hårda, torra landet redan beboddes av Razormane quilboar. Dessa aggressiva, vildsvinslika varelser blev en ständig nagel i ögat på den nya bosättningen. Efter ihärdiga militära insatser drev Horde tillbaka flertalet av dem, men befästa grupper av Razormane klamrar sig envist fast vid sina taggiga tillhåll väster om Razor Hill."},{t="Gar'Thoks offensiv",b="Gar'Thok, en officer stationerad vid Razor Hill, leder arbetet med att en gång för alla undanröja det kvarvarande hotet från Razormane. Han ger erfarna försvarare i uppdrag att slå till direkt mot snårlägren i väster och utrota deras spejare, krigare och dustrunners. För Gar'Thok och Horde-ledningen skulle varje fotfäste för quilboar nära Razor Hill innebära en katastrof, och ett angrepp här ses som första steget mot att säkra Kalimdor."},{t="Röj snåren",b="När quilboar-försvararna har utrotats får Horde-styrkorna fri väg att bränna snårnästena och hindra Razormane från att återta de västra kullarna. Genom att bränna ner byggnaderna till grunden undanröjer Horde ett långvarigt hot och säkrar Durotars västra gräns, så att de viktiga försörjningsvägarna mellan Razor Hill och det större riket skyddas."}},faq={{q="Vem ger uppdraget Encroachment?",a="Uppdraget ges av Gar'Thok, en orcofficer stationerad vid Razor Hill i centrala Durotar.",al={"vem ger encroachment","var får man encroachment","uppdragsgivare för encroachment"}},{q="Varför slåss Horde mot Razormane quilboar i Durotar?",a="När orcherna anlände till Durotar behärskade Razormane quilboar stora delar av området. Horde drev visserligen tillbaka de flesta av dem, men befästa grupper finns kvar väster om Razor Hill och hotar säkerheten och gränserna i orchernas nya hemland.",al={"varför slåss mot quilboar i durotar","varför angripa razormane","quilboar-konflikten i durotar"}},{q="Var finns Razormane-lägren?",a="Razormanes läger ligger väster om Razor Hill. Du ser lätt deras område på de täta snåren av taggiga buskar.",al={"var finns quilboar-lägren","hitta razormane-lägren","encroachment-plats"}},{q="Vilka är Razormane?",a="Razormane är en fientlig quilboarstam som hör hemma på Kalimdors torra slätter. De bygger försvarade snårnästen och gör hårt motstånd mot Hordes bosättning i Durotar och The Barrens.",al={"vilka är razormane","razormane-lore","vad är razormane"}},{q="Vad händer när quilboar har besegrats?",a="När du lämnar in uppdraget skickar Gar'Thok bud om att bränna ner de röjda quilboar-snåren och byggnaderna. Därmed befästs Hordes kontroll över området och Durotars gränser säkras.",al={"vad händer efter encroachment","lämna in encroachment","quilboar-lägrens öde"}},{q="Vilken roll spelar Razor Hill i konflikten?",a="Razor Hill är en befäst orcbosättning i centrala Durotar och fungerar som militärt och logistiskt nav mellan Valley of Trials och Orgrimmar.",al={"var ligger razor hill","vad är razor hill"}}},fp="12,142,25.351.0,20.359.0,21.296.0,33.85.0,60.213.0,38.83.0,22.184.0,44.173.0,43.140.0"}
P.entries["quest:8370"] = {n="Conquering Arathi Basin",s="En Horde Warbringer ber dig ta med tre Arathi Basin Marks of Honor. De är de nödvändiga symbolerna för den här begäran.",h="En Horde Warbringer ber dig ta med tre Arathi Basin Marks of Honor.",kw={"arathi basin","slagfält","erövra arathi basin","horde warbringer","mark of honor"},faq={{q="Vad ber Horde Warbringer om?",a="Horde Warbringer ber dig ta med tre Arathi Basin Marks of Honor.",al={"vad behöver jag","warbringers begäran"}},{q="Var lämnar jag in symbolerna?",a="Lämna in symbolerna till en Horde Warbringer utanför slagfälten.",al={"var lämna in","warbringers plats"}},{q="Hur många Marks of Honor behövs?",a="Du behöver tre Arathi Basin Marks of Honor.",al={"hur många märken","tre märken"}}},fp="23,118,39.73.0,27.64.0,35.43.0"}
P.entries["quest:8372"] = {n="Fight for Warsong Gulch",s="En brigadgeneral i Alliance ber dig ta med Warsong Gulch Marks of Honor. Tecknen behövs utanför slagfälten.",h="En brigadgeneral i Alliance ber dig ta med Warsong Gulch Marks of Honor.",kw={"alliance","slagfält","brigadgeneral","marks of honor","warsong gulch"},ang={["faction:Alliance"]="Som medlem i Alliance kan du ta med Warsong Gulch Marks of Honor till en brigadgeneral i Alliance."},sec={{t="Tecknen",b="Efter att ha stridit i Warsong Gulch kan du ta med tre Marks of Honor till en brigadgeneral i Alliance utanför slagfälten. Generalen ber om tecknen, och du vet vad du måste ta med till generalen."}},faq={{q="Vad vill brigadgeneralen ha?",a="En brigadgeneral i Alliance ber dig ta med tre Warsong Gulch Marks of Honor.",al={"vilka tecken vill de ha","brigadgeneralens begäran"}},{q="Vart ska jag ta med tecknen?",a="Ta med tecknen till en brigadgeneral i Alliance utanför slagfälten.",al={"var lämnar man in tecken","var finns generalen"}},{q="Hur många Marks of Honor behövs?",a="Generalen ber om tre Warsong Gulch Marks of Honor.",al={"hur många tecken","antal hederstecken"}}},fp="23,125,9.202.0,37.83.0,27.75.0,35.56.0"}
P.entries["quest:8373"] = {n="The Power of Pine",s="Under Hallow’s End ber Sergeant Hartman dig att röja undan stinkbomber från Forsaken i Southshore. Ett talldoftande rengöringsmedel hjälper till att hålla byn ren.",h="Under Hallow’s End ber Sergeant Hartman dig att röja undan stinkbomber från Forsaken i Southshore.",kw={"forsaken","hallow's end","tallrengöringsmedel","sergeant hartman","southshore","stink bomb cleaner","stinkbomber"},ang={["faction:Alliance"]="Som resenär från Alliance kan du hjälpa Sergeant Hartman att hålla Southshore fritt från stinkbomber från Forsaken."},sec={{t="Southshores stank",b="Under Hallow’s End smutsar Forsaken ner Southshore med stinkbomber. Bomberna fördärvar firandet av befrielsen. Sergeant Hartman ber dig att ta bort alla som har landat i byn med en Stink Bomb Cleaner."}},faq={{q="Vem ber mig att röja undan stinkbomberna?",a="Sergeant Hartman i Southshore ber dig att röja undan stinkbomberna från Forsaken.",al={"vem gav mig detta","sergeant hartman"}},{q="Var finns stinkbomberna?",a="Stinkbomberna finns i Southshore.",al={"stinkbomber plats","var städa"}},{q="Vem använder stinkbomber mot Southshore?",a="Forsaken använder stinkbomber mot Southshore under Hallow’s End.",al={"vem stinkbomber","forsaken bomber"}},{q="Vad gör rengöringsmedlet?",a="Stink Bomb Cleaner använder tall för att bekämpa dålig lukt.",al={"tallrengöringsmedel","stink bomb cleaner"}},{q="Varför städas Southshore?",a="Stinkbomberna från Forsaken smutsar ner och sprider stank under Southshores firande av Hallow’s End.",al={"varför städa southshore","hallow's end stank"}}},fp="17,148,20.213.0,40.74.0,26.34.0,35.65.0,25.54.0,32.93.0"}
P.entries["quest:8374"] = {n="Claiming Arathi Basin",s="En Alliance Brigadier General utanför Arathi Basin ber dig ta med tre Arathi Basin Marks of Honor. Det är märkena generalen ber dig om.",h="En Alliance Brigadier General utanför Arathi Basin ber dig ta med tre Arathi Basin Marks of Honor.",kw={"alliance","alliance-brigadgeneral","arathi basin","göra anspråk på arathi basin","marks of honor"},ang={["faction:Alliance"]="Som medlem i Alliance ombeds du ta med tre Arathi Basin Marks of Honor till en Alliance Brigadier General."},faq={{q="Vem ber om märkena?",a="En Alliance Brigadier General utanför slagfälten ber dig ta med tre Arathi Basin Marks of Honor.",al={"vem vill ha märken","brigadgeneral"}},{q="Hur många Marks of Honor behövs?",a="Generalen ber dig ta med tre Arathi Basin Marks of Honor.",al={"hur många märken","tre märken"}},{q="Vart ska jag ta märkena?",a="Ta märkena till en Alliance Brigadier General utanför slagfälten.",al={"vart märkena ska tas","lämna in märken"}}},fp="21,153,23.108.0,35.64.0,27.75.0"}
P.entries["quest:8386"] = {n="Fight for Warsong Gulch",s="En uppmaning att kämpa för Warsong Gulch bidrar till att bevara Ashenvales naturliga försvar. Dina insatser håller det intakt ännu en dag.",h="En uppmaning att kämpa för Warsong Gulch bidrar till att bevara Ashenvales naturliga försvar.",kw={"ashenvale","försvar","kämpa för warsong gulch","naturligt försvar","warsong gulch"},sec={{t="Ashenvales försvar",b="I Ashenvale ombeds du att kämpa för Warsong Gulch. Ditt arbete bidrar till att hålla områdets naturliga försvar intakt ännu en dag."}},faq={{q="Varför kämpa för Warsong Gulch?",a="Dina insatser bidrar till att bevara Ashenvales naturliga försvar ännu en dag.",al={"kampen om warsong gulch","varför warsong"}},{q="Vad hjälper detta till att skydda?",a="Kampen bidrar till att hålla Ashenvales naturliga försvar intakt ännu en dag.",al={"vilket försvar","skydd av ashenvale"}},{q="Var ligger Warsong Gulch?",a="Warsong Gulch nämns i samband med Ashenvales naturliga försvar.",al={"warsongs läge","var ligger warsong gulch"}}},fp="23,125,20.128.0,28.72.0,28.73.0,23.71.0"}
P.entries["quest:8389"] = {n="Battle of Warsong Gulch",s="Horde ber dig hjälpa till att säkra dess ägande av Warsong Gulch. Din hjälp betyder mycket för Hordes anspråk där.",h="Horde ber dig hjälpa till att säkra dess ägande av Warsong Gulch.",kw={"slag","anspråk","horde","ägande","warsong gulch"},ang={["faction:Horde"]="Som medlem av Horde bidrar din hjälp till att säkra dess ägande av Warsong Gulch."},sec={{t="Hordes anspråk",b="Hordes anspråk på Warsong Gulch gör att din hjälp behövs. Genom att hjälpa till stöder du dess ägande av dalen."}},faq={{q="Vad vill Horde här?",a="Horde strävar efter att säkra sitt ägande av Warsong Gulch.",al={"horde warsong gulch","hordes anspråk","vem äger warsong gulch"}},{q="Hur kan jag hjälpa till?",a="Din hjälp bidrar till att säkra Hordes ägande av Warsong Gulch.",al={"hjälpa horde","vad gör jag","slaget om warsong gulch"}},{q="Varför vill Horde ha Warsong Gulch?",a="Den tillgängliga redogörelsen säger att Horde strävar efter att säkra sitt ägande av Warsong Gulch.",al={"varför warsong gulch","varför horde vill ha den","orsak till warsong gulch"}}},fp="23,112,11.116.0,30.57.0,15.63.0,38.84.0"}
P.entries["quest:8393"] = {n="Claiming Arathi Basin",s="En brigadgeneral i Alliance utanför Arathi Basin ber dig ta med tre Arathi Basin Marks of Honor. Märkena är det enda som nämns i begäran.",h="En brigadgeneral i Alliance utanför Arathi Basin ber dig ta med tre Arathi Basin Marks of Honor.",kw={"alliance","arathi basin","brigadgeneral","göra anspråk på arathi basin","hedersmärken"},ang={["faction:Alliance"]="Som medlem i Alliance ombeds du ta med tre Arathi Basin Marks of Honor till en brigadgeneral i Alliance."},faq={{q="Vad ber brigadgeneralen om?",a="Brigadgeneralen i Alliance ber dig ta med tre Arathi Basin Marks of Honor.",al={"arathimärken","tre märken","vad ska jag ta med"}},{q="Var lämnar jag in märkena?",a="Ta med märkena till en brigadgeneral i Alliance utanför slagfälten.",al={"var lämnar jag in","brigadgeneralens plats","var lämnar jag in märkena"}},{q="Vem ber om märkena?",a="En brigadgeneral i Alliance utanför slagfälten ber om märkena.",al={"vem vill ha dem","arathi-general","vem ger det här"}}},fp="21,155,40.83.0,27.75.0,28.75.0"}
P.entries["quest:8399"] = {n="Fight for Warsong Gulch",s="En alliansbrigadgeneral utanför Warsong Gulch ber dig ta med tre Marks of Honor. Märkena behövs för att besvara kallelsen att kämpa där.",h="En alliansbrigadgeneral utanför Warsong Gulch ber dig ta med tre Marks of Honor.",kw={"alliance","brigadgeneral","kamp","hedersmärken","warsong gulch"},ang={["faction:Alliance"]="Som krigare för Alliance ombeds du ta med Marks of Honor till en alliansbrigadgeneral utanför Warsong Gulch."},sec={{t="Brigadgeneralens begäran",b="Alliansbrigadgeneralen utanför slagfälten söker märken från Warsong Gulch. Ta med tre Marks of Honor till generalen, så räknas din kamp för Warsong Gulch till Alliance insatser."}},faq={{q="Vad vill alliansbrigadgeneralen ha?",a="Alliansbrigadgeneralen utanför Warsong Gulch ber dig ta med tre Marks of Honor.",al={"brigadgeneralens märken","vilka märken behöver jag"}},{q="Var ska jag lämna in Marks of Honor?",a="Lämna Marks of Honor till en alliansbrigadgeneral utanför slagfälten.",al={"var lämnar jag in märken","var finns warsong-märken"}},{q="Hur många Marks of Honor behövs?",a="Du behöver tre Marks of Honor från Warsong Gulch.",al={"hur många märken","tre märken"}}},fp="23,147,23.219.0,46.92.0,36.84.0,35.44.0"}
P.entries["quest:84"] = {n="Back to Billy",s="Du bär Auntie Bernice Stonefields nybakade paj över vägen till Billy Maclure, som vet något om hennes försvunna halsband. Leveransen fortsätter fejden mellan familjerna Stonefield och Maclure i centrala Elwynn Forest.",h="Du bär Auntie Bernice Stonefields nybakade paj över vägen till Billy Maclure, som vet något om hennes...",kw={"back to billy","bernice stonefield","billy maclure","elwynn forest","the maclure vineyards","pork belly pie","the stonefield farm","stonefields halsband"},ang={["faction:Alliance"]="Som resande i Alliansen upptäcker du att det uppstår tvister mellan människornas gårdar även i fridfulla Elwynn Forest. Att hjälpa lokalbefolkningen innebär ofta att hantera sådana gräl.",["profession:Cooking"]="Som kock känner du till fläskpaj som en mättande rätt från gårdarna i Elwynn, gjord på kött från skogens strövande vildsvin."},sec={{t="En bitter paj",b="Den gamla fejden mellan familjerna Stonefield och Maclure lämnar föga utrymme för vänlighet. Auntie Bernice Stonefield bakade en fläskpaj eftersom Billy Maclure vägrade berätta vad han visste om familjeklenoden utan att få den. Hon räcker dig pajen med tydlig irritation och hoppas att Billy sätter varje tugga i halsen."},{t="En muta till pojken",b="På The Maclure Vineyards, på andra sidan vägen, väntar Billy Maclure hungrig och oförmögen att minnas vad som hände med halsbandet. Rivaliteten mellan de två gårdarna når till och med deras barn, som byter skvaller och stulna småsaker mot godsaker från gården. När pajen är framme återvänder Billys minne, och sökandet efter halsbandets rätta plats kan börja."}},faq={{q="Vad är syftet med den här leveransen?",a="Billy Maclure säger att han vet var Auntie Bernice Stonefields förlorade halsband finns, men han vägrar prata förrän du hämtar en hemlagad fläskpaj åt honom. När du levererar pajen uppfyller du hans krav, så att han avslöjar vad som hände med familjeklenoden.",al={"varför leverera paj","vad vill billy ha","målet med back to billy"}},{q="Varför är Auntie Bernice så arg på Billy?",a="Familjerna Stonefield och Maclure har legat i en bitter lantlig fejd i åratal. Bernice ogillar att behöva laga en godsak åt ett besvärligt barn från familjen Maclure för att få tillbaka en familjeklenod som försvann vid deras ägor.",al={"varför ogillar bernice billy","bråket mellan stonefield och maclure","varför hoppas hon att han sätter i halsen"}},{q="Var säger Billy att halsbandet egentligen finns?",a="Efter att ha ätit pajen avslöjar Billy att han inte behöll halsbandet. Det hamnade hos Goldtooth, en ökänd kobold i Fargodeep Mine.",al={"var finns halsbandet","vem tog halsbandet","goldtooths koppling"}},{q="Var finns Billy Maclure?",a="Billy Maclure finns på The Maclure Vineyards, strax söder om vägen i centrala Elwynn Forest, mittemot The Stonefield Farm.",al={"billy maclures plats","var är billy","hitta billy"}},{q="Vem bakade Pork Belly Pie?",a="Auntie Bernice Stonefield bakade pajen på The Stonefield Farm efter att du samlat färska bitar av vildsvinskött i vildmarken i närheten.",al={"vem gjorde pajen","vem bakade pajen"}},{q="Löser uppdraget fejden mellan familjerna?",a="Nej. Pajleveransen uppfyller Billys personliga mutkrav, medan den djupa fiendskapen mellan de vuxna i familjerna Stonefield och Maclure består.",al={"tar fejden slut","fred mellan stonefield och maclure"}}},fx={["6d42dc77"]={q="Varför skickar Auntie Bernice en främling för att ta hand om Billy?",a="Den bittra fejden mellan familjerna Stonefield och Maclure gör direkt kontakt mellan dem nästan omöjlig. Auntie Bernice står inte ut med tanken på att själv sätta sin fot på Maclures mark, än mindre att personligen passa upp på ett ouppfostrat barn som kräver mat i utbyte mot stöldgods. En resenär på genomresa kan agera neutral budbärare, gå över vägen, lämna pajen och få fram sanningen ur unge Billy utan att utlösa ett öppet slagsmål mellan grannklanerna.",al={"varför skicka mig tillbaka till billy","varför går inte bernice själv","varför behöver auntie bernice en äventyrare"}}},fp="13,218,12.304.0,13.343.1,37.224.0,42.209.0,46.131.1,31.124.0,29.135.0,54.122.0"}
P.entries["quest:840"] = {n="Conscript of the Horde",s="Längs Durotars västra väg skickar Conscript of the Horde rekryter mot The Barrens. Takrin Pathseeker vakar bortom Razor Hill och ger dem ett brev till Kargal Battlescar, vars utpost bevakar övergången.",h="Längs Durotars västra väg skickar Conscript of the Horde rekryter mot The Barrens.",kw={"the barrens","conscript of the horde","the crossroads","kargal battlescar","razor hill","recruitment letter","southfury river","takrin pathseeker"},ang={["faction:Horde"]="Som medlem i Horde markerar den här inkallelsen din övergång från att skydda Durotar till att försvara Hordes länder i Kalimdor.",["race:Orc"]="Som ung ork som lämnar Valley of Trials och Razor Hill är det en övergångsrit att hörsamma Kargal Battlescars kallelse och tjäna Hordes överhövding.",["race:Troll"]="Som Darkspear-troll ansluter du dig till dina orkkamrater i den här insatsen för att hjälpa Horde att utvidga sitt välde och säkra länderna som gränsar till Great Sea."},sec={{t="Över Southfury River",b="När du har bevisat din styrka kring Razor Hill kallas du västerut för att tjäna den större Horde. Takrin Pathseeker vakar över vägen ut ur Durotar för sin vän, veteranen Kargal Battlescar. Han ger dugliga resenärer ett rekryteringsbrev att bära över Southfury River. För en rekryt markerar brevet ett första formellt uppdrag bortom orkernas nya hemland."},{t="Gränsförsvar",b="Kargal Battlescar håller utposten bortom bron, mellan Durotars röda raviner och det torra The Barrens. Han samlar rekryter för att bevaka gränslandet, där kentaurer, quilboar och expeditioner från Alliance prövar gränsen. Horde behöver mer än vakter där: rå arbetskraft skickas till bosättningen The Crossroads."}},faq={{q="Var ska jag lämna rekryteringsbrevet?",a="Ta den västra vägen ut från Razor Hill och korsa träbron över Southfury River. Kargal Battlescar väntar vid Hordes vakttorn precis på andra sidan gränsen, på The Barrens sida.",al={"vart ska jag gå","kargal battlescar plats","plats att lämna in uppdrag"}},{q="Vem är Takrin Pathseeker?",a="Takrin Pathseeker är en scout för Horde på den västra vägen utanför Razor Hill. Han håller uppsikt över vägen och skickar dugliga krigare västerut till sin vapenkamrat Kargal Battlescar.",al={"takrins roll","vem ger uppdraget","uppdragsgivare"}},{q="Vem är Kargal Battlescar?",a="Kargal Battlescar är en barsk veteranofficer vid den östra utposten i The Barrens. Han granskar anländande frivilliga, undertecknar deras inkallelsepapper och skickar dem västerut över savannen för att hjälpa The Crossroads.",al={"vem är kargal","battlescar bakgrund"}},{q="Vad händer efter att Kargal har skrivit under brevet?",a="När Kargal har tagit emot brevet tar han dig i tjänst och skickar dig västerut längs huvudvägen för att rapportera till Sergra Darkthorn vid The Crossroads.",al={"nästa uppdrag","vad händer efter conscript of the horde","vart sedan"}},{q="Varför rekryterar Horde soldater till The Barrens?",a="The Barrens är ett öppet gränsland som förbinder Orgrimmar med Mulgore. Hårdföra quilboarstammar, kentaurplundrare och intrång från Alliance hotar försörjningsvägarna, så Horde behöver alla arbetsföra för att hålla vägarna säkra.",al={"varför inkallelse","faror i the barrens","varför rekrytera"}},{q="Kan Alliance-spelare göra det här uppdraget?",a="Nej. Den här tjänsten är endast till för medlemmar i Horde som går från den tidiga berättelsen i Durotar till The Barrens.",al={"kan alliance göra det här","är det här bara för horde"}}},fx={dfa16f64={q="Varför vill Takrin Pathseeker att jag ska lämna rekryteringsbrevet?",a="Takrin Pathseeker tjänstgör som framskjuten spejare och bevakar vägen från Durotar till de torra slätterna. Hans gamle stridskamrat Kargal Battlescar befaller gränsutposten på andra sidan floden och har ständigt brist på dugliga krigare. Takrin ser att du har potential och vill skicka nya krafter direkt till Barrens garnison för att stärka Hordes försvar, i stället för att låta dugliga händer gå sysslolösa i Razor Hill.",al={"varför skickar takrin mig","takrin pathseekers motiv","varför rekrytera åt kargal"}},["788e36ab"]={q="Varför skickar Takrin en äventyrare i stället för att själv rapportera till Kargal?",a="Takrin har fått i uppdrag att bevaka den viktiga korsningen mellan Durotar och den västra gränstrakten och hålla uppsikt över resenärer och hot längs landsvägen. Om han lämnade sin post för att bära enskilda meddelanden skulle han överge sin plikt. Än viktigare är att han spanar efter blivande soldater som kan hjälpa Kargal. När du rapporterar direkt till utpostens befälhavare visar du att du är villig och tar initiativ till att tjäna Horde.",al={"varför går inte takrin själv","varför skicka mig till kargal","varför jag som hordes rekryt"}}},fp="22,229,22.363.0,14.326.0,39.186.0,25.160.0,25.208.0,43.155.0,53.221.0,44.96.0"}
P.entries["quest:8400"] = {n="Fight for Warsong Gulch",s="Alliance söker bevis på ditt mod vid frontlinjen i Warsong Gulch. En Alliance Brigadier General utanför slagfälten begär tre Marks of Honor som du vunnit mot Horde.",h="Alliance söker bevis på ditt mod vid frontlinjen i Warsong Gulch.",kw={"alliance","ashenvale","slagfält","brigadgeneral","marks of honor","warsong gulch"},ang={["faction:Alliance"]="Som soldat i Alliance bevisar du din tjänst genom att ta med dina stridsmärken till brigadgeneralen i den pågående kampen mot Horde i Warsong Gulch."},sec={{t="Generalens maning",b="En Alliance Brigadier General nära slagfältet kallar på soldater som återvänder från fronten. Om du har stridit i Warsong Gulch bevisar tre Marks of Honor din ställning och dina bedrifter mot Horde. När du för dessa tecken tillbaka till överkommandot visar det att Alliance håller stånd i den omstridda ravinen."}},faq={{q="Vem tar emot Marks of Honor från Warsong Gulch?",a="En Alliance Brigadier General utanför slagfältet samlar in märkena för att följa krigsinsatsen.",al={"vem vill ha marks of honor","brigadgeneralens märken"}},{q="Hur många märken behöver du ta med?",a="Du behöver tre Marks of Honor från Warsong Gulch för att bevisa dina bedrifter på slagfältet.",al={"hur många märken wsg","märken som behövs warsong"}},{q="Var finns Alliance Brigadier General?",a="Brigadgeneralen väntar utanför slagfälten där Alliance samordnar sina trupper.",al={"var finns brigadgeneralen","alliancegeneralens plats"}}},fp="23,198,18.327.0,43.107.0,36.85.0,40.96.0"}
P.entries["quest:841"] = {n="Another Power Source?",s="Chief Engineer Bilgewhizzle i Gadgetzan har fler kraftkällor och säljer dig gärna en till för tio Wastewander Water Pouches.",h="Chief Engineer Bilgewhizzle i Gadgetzan har fler kraftkällor och säljer dig gärna en till för tio Wastewander...",kw={"bilgewhizzle","gadgetzan","kraftkälla","tanaris","wastewander","vattenpåsar"},sec={{t="En kostsam ersättning",b="Chief Engineer Bilgewhizzle gissar att den första kraftkällan från Slake That Thirst tog slut eller kanske försvann i sanden. Oavsett orsaken har Bilgewhizzle fler kraftkällor till salu. Den här gången kostar det tio Wastewander Water Pouches, för tiderna är hårda för alla och kraftkällor växer inte på träd."}},faq={{q="Varför vill Chief Engineer Bilgewhizzle ha Wastewander Water Pouches?",a="Bilgewhizzle säljer ytterligare en kraftkälla för tio Wastewander Water Pouches och säger att tiderna är hårda för alla.",al={"bilgewhizzle vattenpåsar","varför vattenpåsar"}},{q="Vem erbjuder det här bytet?",a="Chief Engineer Bilgewhizzle, som har fler kraftkällor till salu.",al={"vem startar another power source","uppdragsgivare för kraftkälla"}},{q="Vad hände innan du behövde ytterligare en kraftkälla?",a="Det här följer på Slake That Thirst, där du först fick en kraftkälla till din utrustning.",al={"förutsättning another power source","föregående uppdrag kraftkälla"}}},fp="21,108,20.225.0,68.132.0,25.83.0,52.84.0"}
P.entries["quest:842"] = {n="Crossroads Conscription",s="Rekryter anländer från Far Watch Post för tjänstgöring vid Crossroads Conscription. Med Kargal Battlescars undertecknade brev rapporterar du till Sergra Darkthorn vid The Barrens centrala knutpunkt.",h="Rekryter anländer från Far Watch Post för tjänstgöring vid Crossroads Conscription.",kw={"the barrens","battlescar","värnplikt","the crossroads","darkthorn","far watch","kargal","sergra","thrall"},ang={["class:Shaman"]="Som shaman ser du hur Sergra Darkthorn leder både som andlig rådgivare och som militär befälhavare och administratör vid en strategisk utpost.",["faction:Horde"]="Som medlem av Horde lämnar du ditt hemlands trygghet för att tjänstgöra i The Barrens omstridda vildmark.",["race:Orc"]="Som orc ser du hur Thralls Horde förändras, när duglighet och andlig insikt utmanar de gamla klansederna med traditionellt grovarbete."},sec={{t="Inställelse i tjänst",b="När du bevisat ditt värde skickar Kargal Battlescar dig västerut från Far Watch Post. Han ger dig ett undertecknat rekryteringsbrev att ta med längs den hårt packade jordvägen genom The Barrens torra snår. Vägen når en central korsning där The Crossroads förbinder norra Kalimdor med den södra vildmarken."},{t="The Crossroads schaman",b="Sergra Darkthorn tar emot nyanlända vid The Crossroads. Hövding Thrall valde den rappkäftade orc-schamanen att leda verksamheten där. Kargal Battlescar muttrar att hon är besvärlig och pratar för mycket, men Thrall håller henne högt. Sergra är sträng och orubblig. Hon påminner rekryter, särskilt arroganta män, om att kvinnliga krigare och ledare är jämlikar i Thralls Horde, och hon tolererar ingen fräckhet."}},faq={{q="Vem skickar mig på det här uppdraget?",a="Kargal Battlescar, en orc-veteran vid Far Watch Post strax väster om bron mellan Durotar och The Barrens, skickar dig västerut med ett brev till Sergra.",al={"vem ger uppdraget crossroads conscription","uppdragsgivare för crossroads conscription","kargals uppdrag"}},{q="Var finns Sergra Darkthorn?",a="Sergra Darkthorn håller till nära vägkorsningen mitt i The Crossroads, där karavaner och budbärare möts.",al={"var finns sergra darkthorn","var är sergra","hitta sergra darkthorn"}},{q="Varför klagar Kargal på Sergra?",a="Kargal tycker att Sergra är påfrestande. Han kallar henne en otrevlig shaman som pratar i cirklar innan någon kan ta itu med det praktiska, men han respekterar Thralls order att skicka rekryter till henne.",al={"varför ogillar kargal sergra","kargal mot sergra","förbannelse över henne"}},{q="Varför talar Sergra olika till manliga och kvinnliga rollfigurer?",a="Sergra är stolt över Thralls uppdrag att säkerställa jämlikhet för kvinnliga krigare i Horde. Hon uppmuntrar kvinnliga rekryter och varnar manliga rekryter för att hon inte tolererar respektlöshet eller fräckhet.",al={"sergra talar till män och kvinnor","sergra darkthorns dialog","sergra jämlik ställning"}},{q="Vilken väg ska jag ta för att nå The Crossroads?",a="Följ huvudvägen västerut från Far Watch Post till en T-korsning. Sväng vänster och följ den södra vägen in i The Crossroads.",al={"hur tar man sig till the crossroads","vägbeskrivning till the crossroads","vägen till the crossroads"}},{q="Vad händer efter att jag rapporterat till Sergra Darkthorn?",a="Sergra tar emot din hjälp vid The Crossroads och skickar dig för att hjälpa till med lokala hot, jakt och säkerheten vid utposterna i centrala The Barrens.",al={"vad händer efter crossroads conscription","nästa uppdrag från sergra","nästa steg för rekryter i the barrens"}}},fx={["3243ab88"]={q="Varför skickar Kargal Battlescar mig till The Crossroads?",a="Som befälhavare för Far Watch Post tar Kargal hand om nya rekryter som kommer in i Barrens från Durotar. I stället för att hålla kvar alla dugliga kämpar vid en gränsutpost är det hans plikt mot Horde att skicka nya rekryter längre in i gränslandet. The Crossroads är centrum för Hordes myndigheter och militära mobilisering i Barrens, där det desperat behövs manskap för att säkra de omgivande områdena under Sergra Darkthorns uppsikt.",al={"varför skicka mig till the crossroads","kargals motiv för rekrytering vid the crossroads","varför rapportera till sergra"}},["07e83289"]={q="Varför skickar Kargal mig i stället för en av sina vakter?",a="Du är en ny rekryt som vill bevisa ditt värde och förtjäna din plats inom Horde. Kargals utpostvakter är redan upptagna med att försvara gränsposten mot lokala hot. Genom att skicka dig med ett undertecknat rekryteringsbrev förstärker han utposten vid The Crossroads och prövar om en ny rekryt har disciplin nog att ta sig ensam genom de vilda slätterna och följa order.",al={"varför behöver kargal mig","varför inte skicka en vakt till the crossroads","varför jag åt kargal"}}},fp="23,184,18.318.0,28.425.0,27.153.0,34.111.0,38.185.0,64.193.0,49.130.0,49.145.0"}
P.entries["quest:8426"] = {n="Battle of Warsong Gulch",s="En Horde Warbringer ber dig att ta med tre Warsong Gulch Marks of Honor. Märkena är beviset som efterfrågas i denna uppmaning.",h="En Horde Warbringer ber dig att ta med tre Warsong Gulch Marks of Honor.",kw={"slagfält","horde","hedersmärken","warbringer","warsong gulch"},ang={["faction:Horde"]="Som medlem i Horde kan du ta med Warsong Gulch Marks of Honor till en Horde Warbringer."},sec={{t="Ett återlämnat märke",b="Du tar med de tre Warsong Gulch Marks of Honor till en Horde Warbringer utanför slagfälten. Warbringer ber om dessa märken, och det är allt som denna uppmaning kräver."}},faq={{q="Vad ber Warbringer om?",a="Horde Warbringer ber dig att ta med tre Warsong Gulch Marks of Honor.",al={"vilka märken","warbringer vill ha","ta med vad"}},{q="Vart ska jag ta märkena?",a="Ta med märkena till en Horde Warbringer utanför slagfälten.",al={"var finns warbringer","lämna in märken","vart ska märkena"}},{q="Hur många märken behövs?",a="Warbringer ber om tre Warsong Gulch Marks of Honor.",al={"hur många märken","antal märken","tre märken"}}},fp="23,121,15.170.0,33.74.0,27.64.0,26.59.0"}
P.entries["quest:8427"] = {n="Battle of Warsong Gulch",s="En Warbringer från Horde utanför Warsong Gulch ber dig ta med tre Warsong Gulch Marks of Honor. Märkena behövs för bytet.",h="En Warbringer från Horde utanför Warsong Gulch ber dig ta med tre Warsong Gulch Marks of Honor.",kw={"strid","slagfält","horde","marks of honor","warbringer","warsong gulch"},faq={{q="Vad ber Warbringer om?",a="Warbringer från Horde ber dig ta med tre Warsong Gulch Marks of Honor.",al={"warsong gulch-märken","marks of honor","vad ska tas med"}},{q="Var ska jag lämna in märkena?",a="Ta med märkena till en Warbringer från Horde utanför slagfälten.",al={"var finns warbringer","lämna in märken","warsong gulch-warbringer"}},{q="Hur många märken behövs?",a="Warbringer ber om tre Warsong Gulch Marks of Honor.",al={"hur många märken","tre märken","antal märken"}}},fp="23,136,33.74.0,27.64.0,26.59.0"}
P.entries["quest:843"] = {n="Gann's Reclamation",s="I södra The Barrens söker Gann Stonespire resande som vill slå tillbaka mot Bael Modan. Den kringvandrande taurenflyktingen drevs bort från sin klans uråldriga hem och jaktmarker och ber dig döda grävarbetarna och hämta ledarens dagbok.",h="I södra The Barrens söker Gann Stonespire resande som vill slå tillbaka mot Bael Modan.",kw={"bael modan","bael'dun","dvärgarnas utgrävningsplats","gann stonespire","khazgorm","southern barrens"},ang={["class:Shaman"]="Som shaman vet du att sprängningarna och de djupa skyttegravarna vid Bael Modan sårar jordandarna i trakten. Ganns kampanj är en nödvändig rening av denna elementära störning.",["faction:Horde"]="Som medlem av Horden ser du Bael Modan som ett befäst fäste för Alliansen djupt inne i Kalimdor. Att försvara Ganns anspråk är en hederssak och ett sätt att hålla fästet i schack.",["race:Tauren"]="Som Shu'halo är Ganns öde en upprörande påminnelse om att Alliansen visar liten respekt för Jordmodern. Dynamit och järnkugghjul sliter sönder förfädernas gravmarker."},sec={{t="En fördriven stam",b="Gann Stonespire vandrar ensam längs den södra vägen och söker blodig gottgörelse för sin fallna släkt. Hans klans uråldriga födelseplats och jaktmarker låg bland de röda klipporna söder om The Barrens. Dvärgar från Ironforge kom för att bygga Bael Modan och drev bort tauren eller dödade dem för att ge plats åt stenbrott och skyttegravar. Gann säger att fredliga protester och diplomati misslyckades. Nu söker han hämnd för klanen som fördrevs och slaktades."},{t="Ruinerna vid Bael Modan",b="Vid Bael Modan gräver dvärgiska utgrävare sig in i kullarna med ångmaskiner och sprängämnen. Prospector Khazgorm leder utgrävningen djupt ner i jorden. Gann ber dig decimera leden av Bael'dun-utgrävare och förmän, döda Khazgorm och ta prospektörens personliga utgrävningsanteckningar. Han vill läsa anteckningarna för att förstå vad Alliansexpeditionen söker i den heliga jorden."}},faq={{q="Vem är Gann Stonespire?",a="Gann Stonespire är en ensam taurenöverlevare vars stam en gång levde i södra The Barrens. Efter att dvärgiska utgrävare drev hans folk från deras land och dödade dem som gjorde motstånd, vandrar han längs den södra landsvägen och söker rättvisa och hämnd mot Alliansens utgrävningsplats.",al={"gann","vem ger gann's reclamation","gann stonespire berättelse"}},{q="Varför är dvärgarna i The Barrens?",a="Dvärgarna tillhör en Ironforge-expedition som kallas Bael'dun. De byggde en borg och en utgrävning vid Bael Modan i södra The Barrens, där deras sprängningar och bullriga maskiner sliter sönder kullarna trots att taurenfolk bor där.",al={"varför är dvärgarna vid bael modan","bael modans syfte","ironforge i the barrens"}},{q="Vem är Prospector Khazgorm?",a="Prospector Khazgorm leder dvärgarnas utgrävning söder om fästningen Bael Modan. Gann håller honom ansvarig för vanhelgandet av sina förfäders marker och kräver Khazgorms dagbok som bevis på hans död.",al={"khazgorm","prospector khazgorm","bael modans ledare"}},{q="Var hittar man Gann Stonespire?",a="Gann Stonespire vandrar längs vägen längst söderut i The Barrens, väster om fästningen Bael Modan och norr om vägen mot The Great Lift och Thousand Needles.",al={"ganns plats","hitta gann","var finns gann"}},{q="Försökte Gann lösa det här fredligt?",a="Ja. Gann säger att han försökte med diplomati och andra fredliga vägar för att stoppa förstörelsen av sina förfäders marker. Dvärgarna avfärdade försöken och fortsatte spränga kullarna, så han tog till våld.",al={"försökte tauren med diplomati","ganns diplomati"}},{q="Vad händer efter det här uppdraget?",a="När Gann får Khazgorms dagbok studerar han prospektörens anteckningar för att förstå dvärgarnas teknik och planer. Det leder vidare till 'Revenge of Gann', där han försöker sabotera deras tunga maskineri.",al={"nästa uppdrag efter gann's reclamation","uppföljning på gann"}}},fx={["5ecef431"]={q="Varför vill Gann Stonespire driva bort dvärgarna?",a="Bael Modan ligger mitt på Ganns stams förfäders marker. När dvärgarna kom drev deras skoningslösa grävande, högljudda maskiner och sprängningar tauren från deras hem och kostade många oskyldiga livet. Efter att alla fredliga försök har misslyckats söker Gann hämnd och vill med våld återta sitt folks heliga hemland.",al={"ganns motiv","varför döda dvärgarna i bael modan","varför vill gann ha hämnd"}},fd3e714a={q="Vad är Khazgorm's Journal till för?",a="Journalen tillhör Prospector Khazgorm, ledaren som övervakar den destruktiva utgrävningen i Bael Modan. Gann vill studera sidorna för att få insikt i dvärgarnas verksamhet och deras motiv i området, och ta reda på hur han bäst kan stoppa den pågående förstörelsen av sitt folks förfäders marker.",al={"khazgorm's journal användning","varför hämta khazgorm's journal","vad vill gann med journalen"}},["4442e883"]={q="Varför ber Gann dig om hjälp i stället för att själv ta hand om utgrävningen?",a="Gann strövar helt ensam omkring i södra Barrens. Han är en landsflykting vars stam dödades eller skingrades när dvärgarna kom. Han står inför en befäst bosättning bemannad av dussintals beväpnade utgrävare, förmän och deras ledare, och kan inte hoppas driva bort inkräktarna utan en duglig kämpe som strider för honom.",al={"varför kan inte gann göra det själv","varför behöver gann hjälp","varför jag åt gann"}}},fp="18,202,17.379.0,23.355.0,23.270.0,35.238.0,27.190.0,35.163.0,40.195.0,30.158.1"}
P.entries["quest:8431"] = {n="Battle of Warsong Gulch",s="Horde försöker säkra sitt ägande av Warsong Gulch. Din hjälp stärker dess anspråk.",h="Horde försöker säkra sitt ägande av Warsong Gulch.",kw={"slag","dal","horde","ägande","warsong gulch"},ang={["faction:Horde"]="Du hjälper Horde att säkra sitt ägande av Warsong Gulch."},sec={{t="Ett anspråk i dalen",b="Hordes anspråk på Warsong Gulch står på spel, och du bidrar med din styrka för att säkra det. Dina insatser hjälper Horde att behålla ägandet av dalen."}},faq={{q="Vad händer vid Warsong Gulch?",a="Horde försöker behålla ägandet av Warsong Gulch.",al={"slaget vid warsong gulch","vad händer i dalen"}},{q="Vem hjälper jag?",a="Du hjälper Horde att säkra sitt ägande av Warsong Gulch.",al={"vem ber om hjälp","vilken sida gäller det"}},{q="Vad vill Horde?",a="Horde vill behålla ägandet av Warsong Gulch.",al={"hordes mål","varför slåss man i warsong gulch"}}},fp="23,88,20.153.0,35.62.0,17.64.0,25.55.0"}
P.entries["quest:8436"] = {n="Conquering Arathi Basin",s="En Horde Warbringer ber dig om tre Arathi Basin Marks of Honor. Ta med dem från slagfältet till krigsbringaren utanför.",h="En Horde Warbringer ber dig om tre Arathi Basin Marks of Honor.",kw={"arathi basin","slagfält","horde warbringer","mark of honor","marks of honor"},sec={{t="En Warbringers begäran",b="Warbringern väntar utanför slagfälten, dit du kan ta med märkena. Du ombeds ta med tre Arathi Basin Marks of Honor till Horde."}},faq={{q="Vad vill Horde Warbringer ha?",a="Horde Warbringer ber dig ta med tre Arathi Basin Marks of Honor.",al={"vad warbringern vill ha","vad som ska tas med","arathi basin-märken"}},{q="Var ska jag lämna märkena?",a="Ta med märkena till en Horde Warbringer utanför slagfälten.",al={"var märken ska lämnas","warbringerns plats","utanför slagfältet"}},{q="Hur många Marks of Honor behövs?",a="Du ombeds ta med tre Arathi Basin Marks of Honor.",al={"antal märken","tre märken"}},{q="Vilka märken ber Warbringern om?",a="Begäran gäller Arathi Basin Marks of Honor.",al={"vilka märken","arathi basin-märke","marks of honor"}}},fp="23,129,22.149.0,36.73.0,27.64.0,35.57.0,40.47.0"}
P.entries["quest:84396"] = {n="Magma or Lava?",s="Ironforges lärda söker magiska verk till stadens bibliotek. Nya skrifter på hyllorna hjälper dem att utöka sina kunskaper om det arkana.",h="Ironforges lärda söker magiska verk till stadens bibliotek.",kw={"samling","ironforge","bibliotek","magiska verk","magma eller lava","lärda"},sec={{t="Sidor till hyllorna",b="De lärda i Ironforges bibliotek vill utöka sin samling av kunskap om det arkana. När du färdas genom världen och hittar magiska verk ber de dig att bära skrifterna tillbaka till deras hyllor. Varje ny text vidgar stadens förståelse av världen."}},faq={{q="Vem vill ha magiska verk till biblioteket?",a="De lärda i Ironforges bibliotek samlar magiska verk för att utöka sin samling.",al={"magma eller lava bibliotek","var lämnar man magiska verk","ironforge biblioteksbok"}},{q="Vad samlas till samlingen?",a="Samlingen växer när resenärer lämnar magiska skrifter och dokument till biblioteket.",al={"vad behöver biblioteket","vad samlar de in"}},{q="Varför söker biblioteket efter dessa skrifter?",a="De lärda förlitar sig på att resenärer hittar och lämnar in skriftlig kunskap så att deras vetande fortsätter att växa.",al={"varför lämna böcker till biblioteket","magma eller lava syfte"}}},fp="14,141,19.252.0,42.81.0,26.88.0,48.127.0"}
P.entries["quest:84399"] = {n="Ka-Boom!",s="De lärda vid Library ber dig ta med magiska skrifter som du hittar under dina resor. Varje bidrag hjälper till att utöka deras växande kunskapssamling.",h="De lärda vid Library ber dig ta med magiska skrifter som du hittar under dina resor.",kw={"samling","ironforge","ka-boom!","bibliotek","magiska skrifter"},sec={{t="Utöka samlingen",b="De lärda vid Library vill utöka sin kunskapssamling. När du hittar magiska skrifter under dina resor ber de dig ta med dem för att hjälpa till att bygga upp samlingen."}},faq={{q="Vad söker biblioteket efter?",a="Biblioteket söker magiska skrifter för att utöka sin kunskapssamling.",al={"vad vill biblioteket ha","vad ska man ta med till biblioteket","vilka skrifter samlar biblioteket på"}},{q="Vem ber om de här magiska skrifterna?",a="De lärda vid Library välkomnar tillskott till sin samling och ber resenärer lämna in magiska skrifter och handlingar de hittar.",al={"vem vill ha magiska skrifter","vart ska magiska skrifter","vem samlar kunskap i ironforge"}},{q="Kan du ta med fler magiska skrifter senare?",a="Du ombeds ta med alla fler magiska skrifter du hittar direkt till Library för att hjälpa till att bygga upp samlingen.",al={"ska jag behålla magiska böcker","kan jag ta med fler böcker","vad gör man med magiska skrifter man hittar"}}},fp="8,155,16.172.0,29.72.0,38.131.0,43.120.0"}
P.entries["quest:844"] = {n="Plainstrider Menace",s="Vid The Crossroads skickar Sergra Darkthorn nya äventyrare från Horde för att jaga plainstriders öster om utposten. Fåglarna hotar matförråden, och jakten ger nykomlingarna en första känsla för The Barrens.",h="Vid The Crossroads skickar Sergra Darkthorn nya äventyrare från Horde för att jaga plainstriders öster om...",kw={"the barrens","näbb","the crossroads","darkthorn","jakt","plainstrider","sergra","förråd"},ang={["class:Hunter"]="Som ung jägare lär du dig att smyga på, spåra och fälla villebråd på den vidsträckta, öppna savannen.",["faction:Horde"]="Som medlem av Horde hjälper du till att skydda The Crossroads, en viktig knutpunkt för logistiken, och säkra matförråden så att Horde kan behålla sitt fotfäste över Kalimdor.",["race:Orc"]="Som ork hedrar du jaktens disciplin. Sergra förväntar sig att du bevisar ditt mod mot traktens bestar innan du tar dig an tyngre uppgifter."},sec={{t="Trygghet vid The Crossroads",b="The Crossroads samordnar förnödenheter över Kalimdor, men plainstriders öster om utposten har börjat hacka på matlådorna. Sergra Darkthorn, en orkschaman, skickar nyanlända äventyrare från Horde för att jaga fåglarna innan de skadar förråden. Deras angrepp hotar de proviantförråd som bosättningen är beroende av."},{t="Den första jakten",b="Sergra Darkthorn använder jakten både för att pröva nykomlingarna och skydda förråden. Hon ser plainstriders som enkelt byte, lämpligt för att lära unga jägare att uthärda elementen och spåra villebråd över de solstekta slätterna. Att komma tillbaka med deras vassa näbbar visar att en jägare har tålamod och de grundläggande stridsfärdigheter som krävs för att möta farligare bestar i The Barrens."}},faq={{q="Varför jagas plainstriders?",a="Plainstriders öster om The Crossroads har blivit djärva, plundrar matförråd och trakasserar förbipasserande försörjningskaravaner. Sergra Darkthorn beordrar att de ska jagas för att skydda bosättningens proviant.",al={"varför döda plainstriders","plainstriderproblemet","vad gjorde plainstriders"}},{q="Vem är Sergra Darkthorn?",a="Sergra Darkthorn är en erfaren orkschaman som är stationerad vid The Crossroads. Hon övervakar jaktprov, tränar nyanlända äventyrare och leder dem mot vilda bestar som hotar Hordes verksamhet.",al={"vem är sergra","sergra darkthorns roll","uppdragsgivare vid the crossroads"}},{q="Varför vill Sergra särskilt ha deras näbbar?",a="En plainstrider använder sin hårda, vassa näbb både som främsta vapen och för att leta efter föda. Att ta med näbben tillbaka bevisar att fågeln har dödats.",al={"varför plainstrider-näbbar","plainstrider-näbb som bevis"}},{q="Vad händer efter den här jakten?",a="Efter plainstriders skickar Sergra dig för att jaga zhevra, snabbare och livligare villebråd som strövar över slätterna.",al={"vad händer härnäst","nästa uppdrag efter plainstriders","jaktserie"}},{q="Var håller plainstriders till?",a="Plainstriders strövar på savannens gräsmarker öster och sydöst om The Crossroads och letar efter föda längs handelsvägarna.",al={"var finns plainstriders","plainstrider-platser","jaktmarker"}},{q="Är detta en del av en större jaktserie?",a="Ja. Det här inleder Sergra Darkthorns jaktprov i The Barrens, som blir farligare när de går vidare till våldsammare bestar på savannen.",al={"jakten i the barrens","sergras uppdragsserie"}}},fx={["416dd73a"]={q="Varför behöver Sergra Darkthorn en äventyrare i stället för vakterna vid The Crossroads?",a="Vakterna vid The Crossroads har fullt upp med att hålla försvaret mot quilboar-räder och säkra de lokala vägarna. För Sergra fyller jakten på besvärliga asätare ute på slätterna två syften: den minskar trycket på bosättningens matförråd och prövar om nyanlända har de spårnings- och stridskunskaper som krävs för att överleva i Barrens.",al={"varför skicka mig","varför dödar inte vakterna plainstriders","varför en äventyrare mot plainstriders"}}},fp="19,188,23.286.0,14.345.0,35.186.0,24.201.0,46.142.0,27.107.0,38.111.0,40.150.0"}
P.entries["quest:845"] = {n="The Zhevra",s="Vid The Crossroads skickar Sergra Darkthorn unga krigare från Horde efter zhevra. Jakten prövar färdigheterna som krävs för att möta The Barrens farligare bestar.",h="Vid The Crossroads skickar Sergra Darkthorn unga krigare från Horde efter zhevra.",kw={"barrens","crossroads","hovar","jaktprov","sergra darkthorn","zhevra","zhevrahäst"},ang={["class:Hunter"]="Som jägare som lär dig om The Barrens kan du vässa ditt spårsinne och ditt sikte genom att smyga på snabba zhevrahjordar.",["faction:Horde"]="Som medlem i Horde hjälper du The Crossroads att sköta djurlivet i området och hålla försörjningsvägarna fria.",["race:Tauren"]="Som tauren vet du hur kraftfull en zhevras spark kan vara. Sergra varnar för att den kan slå omkull en fullvuxen tauren."},sec={{t="Ett steg upp på savannen",b="Efter plainstriders skickar Sergra Darkthorn dig efter tuffare byte. Zhevras strövar i hjordar över de norra och södra delarna av The Barrens. De är inte savannens våldsammaste bestar, men de är snabba och envisa, och deras sparkar kan knäcka ben."},{t="Darkthorns prövningar",b="Sergra använder jakten för att pröva hur dina färdigheter utvecklas. Hon ber om fyra hela hovar som bevis på bytet och varnar för att en zhevras bakutspark kan få en vuxen tauren att falla på ändan. Klarar du prövningen kommer du närmare att möta slätternas rovdjur."}},faq={{q="Vem ger jakten?",a="Sergra Darkthorn, en erfaren orkschaman vid The Crossroads i centrala The Barrens, utformar prövningen för att testa unga krigare från Horde.",al={"vem ger zhevrauppdraget","uppdragsgivare för zhevra","sergra darkthorns uppdrag"}},{q="Var finns zhevrahästarna?",a="Zhevra strövar över de öppna slätterna norr och söder om The Crossroads i centrala The Barrens.",al={"var finns zhevrahästar","zhevraplats","karta över zhevra i barrens"}},{q="Varför vill Sergra ha zhevrahovar?",a="Hovarna bevisar att du dödade en zhevra. Att ta med fyra visar att du övervann ett odjur vars kraftiga ben kan fälla även en mäktig tauren.",al={"varför zhevrahovar","zhevrahovar som bevis","varför jaga zhevra"}},{q="Vad kommer efter det här uppdraget?",a="När du har bevisat dig mot zhevra prövar Sergra dig mot The Barrens rovdjur i Prowlers of the Barrens.",al={"nästa uppdrag efter zhevra","fortsättningsuppdrag för zhevra","darkthorns nästa uppdrag"}},{q="Är zhevrahästar farliga?",a="Zhevra är vanligtvis fridfulla betare, men deras ben är kraftfulla. Sergra varnar för att en skrämd eller trängd löpare kan fälla även en stadig tauren med en enda spark.",al={"hur farliga är zhevrahästar","zhevrafara","zhevraspark"}},{q="Varför jagade man plainstriders först?",a="Sergra gör sina prövningar svårare steg för steg. Plainstriders är det första målet; zhevra är snabbare och starkare byte som förbereder dig på att möta aggressiva savannrovdjur.",al={"föregående uppdrag","samband med plainstrider menace"}}},fx={["6d2e3590"]={q="Varför vill Sergra Darkthorn att zhevra ska jagas?",a="Sergra Darkthorn prövar din jaktförmåga och härdar dig inför Barrens brutala vildmark. Plainstriders ger grundläggande måltavlor att öva på, medan zhevra är tåligare bestar vars kraftfulla sparkar prövar dina reflexer och din uthållighet. Genom att skicka dig efter dem ser Sergra till att du kan hantera farliga vilda djur innan hon skickar dig mot områdets toppredatorer.",al={"varför jaga zhevra","segr as motiv","sergra darkthorns anledning"}},["1cbbdcd0"]={q="Vad är zhevra runners?",a="Zhevra runners är snabba, randiga hästdjur som hör hemma på Barrens torra savanner. De färdas i hjordar över slätterna norr och söder om The Crossroads och förlitar sig på sin snabbhet och sina kraftfulla bakben för att överleva bland smygjägare och rovfåglar. De är inga rovdjur och angriper inte utan anledning, men deras sparkar kan fälla en fullvuxen tauren.",al={"vad är zhevra","zhevra runners","vem jagar vi"}}},fp="10,144,24.232.0,23.248.0,22.129.0,27.93.0,35.145.0,28.116.0,22.164.0,42.169.0"}
P.entries["quest:846"] = {n="Revenge of Gann",s="I södra Barrens förbereder Gann Stonespire ett motangrepp mot dvärgarna i Bael Modan. Efter Prospector Khazgorms död skickar han Horde-allierade in i fästningen för att hämta explosiv ammunition till sin attack.",h="I södra Barrens förbereder Gann Stonespire ett motangrepp mot dvärgarna i Bael Modan.",kw={"bael modan","the barrens","dynamit","sprängämnen","gann stonespire","ironforge","khazgorm","nitroglycerin","sodium nitrate","wood pulp"},ang={["faction:Horde"]="Som medlem av Horde hjälper du till att hindra Alliance från att etablera ett militärt fotfäste i södra Barrens, som skulle kunna skära av färdvägen mellan Mulgore, Crossroads och den södra gränsmarken.",["profession:Engineering"]="Som ingenjör känner du igen den klassiska industriella dvärgformeln: nitroglycerin stabiliserat med pappersmassa och blandat med Sodium Nitrate. Gann anpassar den för en ojämn kamp.",["race:Tauren"]="Som tauren ser du Bael Modan som ett svårt sår på Jordmodern. Att sabotera dvärgarnas maskiner är en plikt mot din ande och ditt hemland."},sec={{t="En smak av deras egen medicin",b="Gann Stonespire vet att Prospector Khazgorms död bara sinkade utgrävningarna i Bael Modan. Dvärgarnas arbete kommer att återupptas, och snart kommer en ny arbetsledare att övervaka maskinerna som sliter upp Ganns förfäders marker. Han vägrar se jorden utsättas för mer grävande. I stället planerar Gann att vända inkräktarnas sprängutrustning mot dem och spränga deras fäste inifrån."},{t="Anfall mot fästet",b="Fästningen i Bael Modan rymmer en utgrävningsbas och en garnison med soldater, gevärsskyttar och officerare som skyddar dvärgarnas intressen i Barrens. Gann har fått veta att försvararna bär på nitroglycerin, Wood Pulp och Sodium Nitrate, material som används vid industriell sprängning. Han skickar Horde-allierade förbi försvarslinjen för att ta dessa flyktiga förnödenheter från dvärgarna. Med tillräckligt mycket kan han sätta ihop en kraftfull sprängladdning."}},faq={{q="Varför vill Gann Stonespire hämnas?",a="Dvärgarna från Ironforge i Bael Modan tog över Ganns förfäders hemland, vanhelgade jorden och drev bort hans folk för att anlägga sin utgrävningsplats. Efter att ha dödat prospektörernas ledare och återfått hans dagbok försöker Gann sätta stopp för förstörelsen för gott.",al={"varför är gann arg","gann stonespires motiv","vad gjorde dvärgarna mot gann"}},{q="Var finns sprängämnena?",a="Försvararna i Bael Modan bär på ingredienserna. Gevärsskyttar, soldater och officerare inne i och runt den befästa utgrävningsplatsen i södra Barrens har flaskor med nitroglycerin, buntar med Wood Pulp och prover av Sodium Nitrate.",al={"var får man tag på nitroglycerin","hur får man tag på wood pulp","var finns sodium nitrate"}},{q="Varför behöver Gann Wood Pulp och kemikalier?",a="Dvärgarnas utgrävningsritningar visar att Wood Pulp stabiliserar flyktigt nitroglycerin, medan Sodium Nitrate hjälper till att skapa ett tillförlitligt industriellt sprängämne. Gann planerar att forma blandningen till en sprängladdning som kan rasera viktiga dvärgbyggnader.",al={"varför wood pulp","vad tillverkar gann","ingredienser till ganns bomb"}},{q="Vad händer när du har samlat ihop förnödenheterna?",a="När du återlämnar råvarorna sätter Gann ihop en sprängladdning och skickar dig för att förstöra dvärgarnas flygmaskin vid utgrävningen i Bael Modan, en viktig del av anläggningens infrastruktur.",al={"vad händer sedan i revenge of gann","efter att ingredienserna samlats in"}},{q="Varför räcker det inte att döda Khazgorm för att stoppa dvärgarna?",a="Khazgorm var bara chefsprospektör. Dvärgstyrkorna i Bael Modan har förskansat sig bakom försvarsmurar och försörjningslinjer, och Ironforge kan skicka en ny arbetsledare för att fortsätta gräva om inte basen drabbas av ett förödande slag.",al={"varför räckte det inte att döda khazgorm","har bael modan stoppats"}},{q="Vilket strategiskt hot utgör Bael Modan mot Horde?",a="Bael Modan började som ett fort som försvarade utgrävningsplatsen, men har vuxit till ett välbemannat Alliance-fäste. Läget längs handelsvägarna i södra Barrens gör det till ett militärt hot mot närliggande bosättningar tillhörande Horde i Kalimdor.",al={"varför bryr sig horde om bael modan","hotet från bael modan"}}},fx={["410ab5f4"]={q="Vem har förnödenheterna som behövs till sprängämnet?",a="Förnödenheterna finns hos den dvärggarnison som är stationerad vid Bael Modan. Gevärsskyttarna, soldaterna och officerarna i utgrävningen och fästningen använder ofta sprängkrut och maskiner för att riva upp marken. Därför har de stora lager av flyktiga kemikalier och stabilisatorer nära till hands.",al={"vem har sprängämnena","dvärgarna vid bael modan","mål i revenge of gann"}},["5f27d24f"]={q="Varför behöver Gann din hjälp i stället för att själv slå till mot Bael Modan?",a="Gann Stonespire är en utstött överlevare från en splittrad stam och agerar ensam, utan stöd från någon stor krigshär. Han klarar inte av att ensam slå ut en hel befäst garnison av dvärgar från Ironforge. Därför förlitar han sig på en skicklig mästare från Horden som kan infiltrera fästningen och hämta det han behöver.",al={"varför behöver gann mig","varför gör inte gann det själv","varför jag i revenge of gann"}}},fp="15,210,29.372.0,16.376.0,39.259.0,40.216.0,43.251.0,42.200.1,52.222.0,51.231.0"}
P.entries["quest:8465"] = {n="Speak to Salfa",s="Salfa håller vakt utanför Timbermaw Hold. Du ombeds passera genom fästet och tala med honom i Winterspring.",h="Salfa håller vakt utanför Timbermaw Hold.",kw={"ingång","vakt","salfa","tala","timbermaw hold","winterspring"},sec={{t="Vid fästet",b="Utanför Timbermaw Hold står Salfa på vakt. Du ombeds ta dig genom fästet, komma ut i Winterspring och tala med honom där."}},faq={{q="Vem är Salfa?",a="Salfa står vakt utanför ingången till Timbermaw Hold.",al={"vem är salfa"}},{q="Var hittar jag Salfa?",a="Salfa står vakt utanför ingången till Timbermaw Hold i Winterspring.",al={"salfa plats","var finns salfa"}},{q="Vad vill Salfa att jag ska göra?",a="Du ombeds ta dig genom Timbermaw Hold, komma ut i Winterspring och tala med Salfa.",al={"uppdrag tala med salfa","vad gör salfa"}}},fp="14,116,11.139.0,13.58.0,23.75.0,30.93.0"}
P.entries["quest:8467"] = {n="Feathers for Nafien",s="Nafien samlar fjädrar och tar gärna emot varje fjäder du lyckas hitta. Som tack lovar han att hans folk ska få höra om dina hjälpsamma dåd.",h="Nafien samlar fjädrar och tar gärna emot varje fjäder du lyckas hitta.",kw={"dåd","fjädrar","nafien","gåvor","anseende"},sec={{t="Fjädergåvor",b="Nafien söker fjädrar från vildmarken och erbjuder gott anseende bland sitt folk i gengäld. När du hittar sådana fjädrar tar han gärna emot dem och lovar att ryktet om din hjälp snabbt ska spridas bland hans folk."}},faq={{q="Vem är Nafien?",a="Nafien är en varelse som lovar att tala väl om dina dåd inför sitt folk i utbyte mot fjädrar.",al={"vem är nafien","nafien identitet"}},{q="Varför vill Nafien ha fjädrar?",a="Nafien söker fjädrar och lovar att sprida ordet om din hjälp bland sitt folk för varje bunt du ger honom.",al={"varför samla fjädrar","fjädrarnas syfte","vad används fjädrar till"}},{q="Tar Nafien emot fler fjädrar?",a="Nafien tar emot så många fjädrar du kan samla så länge hans folk behöver dem.",al={"fler fjädrar","kan jag ta med fler fjädrar","lämna fjädrar igen"}}},fp="19,177,20.220.0,14.101.0,30.117.0,39.88.0"}
P.entries["quest:847"] = {n="Guile of the Raptor",s="Efter att Tor'gan's Orb gav Gor'mul rovfågelns essens undrar han över shamanernas magi, efter att ha känt kraften. Han skickar dig för att säga till Tor'gan att han tills vidare har blivit övertygad och kommer att lyssna.",h="Efter att Tor'gan's Orb gav Gor'mul rovfågelns essens undrar han över shamanernas magi, efter att ha känt...",kw={"arathi highlands","gor'mul","guile of the raptor","hammerfall","shaman","tor'gan"},sec={{t="En övertygad krigare",b="Gor'mul undrar högt om kraften som genomströmmar honom är shamanernas kraft som Tor'gan försökte visa honom. Han tycker att det är intressant. Han ber dig säga till Tor'gan att han tills vidare har blivit övertygad och vill höra vad Tor'gan har att säga."},{t="Tor'gans svar",b="Tor'gan säger att han ska tala med Gor'mul när förtrollningen har klingat av. Han tackar dig för att du hjälpte till att återföra Gor'mul till de levandes skara och räknar med att Gor'mul också är tacksam."}},faq={{q="Vem skickar dig för att tala med Tor'gan?",a="Det gör Gor'mul. Efter att ha känt klotets kraft ber han dig säga till Tor'gan att han tills vidare har blivit övertygad.",al={"vem startar guile of the raptor 3","vem ger uppdraget","var börjar det"}},{q="Varför ändrar Gor'mul uppfattning om Tor'gan?",a="Han undrar om kraften han kände är shamanernas kraft som Tor'gan försökte visa honom, och han tycker att det är intressant. Han är tills vidare övertygad och kommer att lyssna på Tor'gan.",al={"varför ändrade gormul uppfattning","gormul shamanmagi","är gormul övertygad"}},{q="Vad hände före det här steget?",a="Det följer på det tidigare steget där du tog Tor'gan's Orb till Gor'mul.",al={"föregående uppdrag","förutsättning för guile of the raptor"}}},fp="19,142,19.218.0,15.169.1,36.115.0,47.176.0,27.57.0"}
P.entries["quest:848"] = {n="Fungal Spores",s="Vid oaserna i The Barrens samlar hordens äventyrare Fungal Spores åt Apothecary Helbrim från Royal Apothecary Society. Märkliga, förändrande energier strömmar genom källorna och förvandlar de lokala växterna till kraftfulla ingredienser. Helbrim vill ha exemplaren för att brygga brygder åt sin kollega i Thunder Bluff.",h="Vid oaserna i The Barrens samlar hordens äventyrare Fungal Spores åt Apothecary Helbrim från Royal Apothecary...",kw={"apothecary helbrim","apothecary zamah","barrens","crossroads","the forgotten pools","fungal spores","lushwater oasis","royal apothecary society","the stagnant oasis"},ang={["class:Druid"]="Oaserna rymmer en onaturligt våldsam våg av naturmagi som orsakar aggressiva mutationer i det omgivande ekosystemet.",["faction:Horde"]="Genom att undersöka Barrens störda vatten kan man skydda de viktiga lederna mellan Orgrimmar, Crossroads och Thunder Bluff.",["profession:Herbalism"]="Fyllda svampar kring oaserna i The Barrens visar hur plötsliga tillskott av energi från omgivningen kan förvandla vanliga växter till kraftfulla ingredienser.",["race:Undead"]="Långt från Lordaeron fortsätter Forsaken-forskare sitt alkemiska arbete och vänder Kalimdors naturliga avvikelser mot Royal Apothecary Societys mål."},sec={{t="Frodig och muterad flora",b="The Barrens är en torr savann, men The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis sjuder av onaturlig livskraft. En märklig våg av livsenergi strömmar från vattnen och förvrider och livar upp växter och djur som dricker där. Fyllda svampar växer längs de leriga stränderna och absorberar dessa strömmar. Deras sporer har sällsynta egenskaper som väcker förbipasserande alkemisters nyfikenhet."},{t="Royal Apothecary Society i Kalimdor",b="Apothecary Helbrim arbetar vid The Crossroads, långt från Undercity, men är fortfarande hängiven Royal Apothecary Societys forskning. Han samlar de förändrade sporerna eftersom Kalimdors inhemska ingredienser har märklig kraft, och använder dem till att skapa mäktiga blandningar. Exemplaren är avsedda för Apothecary Zamah i Thunder Bluff och ingår i Forsaken-folkets vetenskapliga arbete i de allierades länder."}},faq={{q="Var växer svampsporerna?",a="Fyllda svampar växer vid vattenbrynet kring oaserna i The Barrens, däribland The Forgotten Pools, Lushwater Oasis och The Stagnant Oasis.",al={"var hittar man svampsporer","svampsporernas plats","var finns fyllda svampar"}},{q="Varför har svamparna förändrats nära oaserna?",a="En kraftfull våg av livsenergi strömmar genom oasernas vatten i The Barrens. Den förändrar djur- och växtlivet omkring sig kraftigt, i stället för att bara ge näring åt vanlig växtlighet.",al={"varför är svamparna muterade","livsenergi i oaser","vad är fel med oaserna"}},{q="Vem är Apothecary Helbrim?",a="Apothecary Helbrim är en Forsaken-medlem i Royal Apothecary Society, stationerad vid The Crossroads i The Barrens. Han studerar regionens ovanliga biologi och samlar lokala material för alkemiska studier.",al={"helbrims historia","vem är helbrim","apotekare vid crossroads"}},{q="Vad tänker Helbrim göra med sporerna?",a="Helbrim använder de kraftfulla sporerna för att brygga en särskild brygd åt sin forskningskollega Apothecary Zamah i Thunder Bluff.",al={"vad används sporerna till","svampsporernas syfte"}},{q="Varför är Forsaken-apotekare verksamma i Barrens?",a="Som allierade till horden studerar Forsaken-forskare Kalimdors främmande miljöer och ovanliga växtlighet i jakten på nya ingredienser till läkemedel, gifter och brygder.",al={"varför finns odöda i barrens","royal apothecary society i kalimdor"}},{q="Från vilken oas är det säkrast att samla sporer?",a="The Forgotten Pools, nordväst om The Crossroads, har djur på lägre nivå än Lushwater Oasis eller The Stagnant Oasis i söder, vilket gör platsen säkrast för att samla svampar.",al={"enklaste oasen att hitta sporer i","säkraste oasen i barrens"}}},fx={f81deb18={q="Varför vill Apothecary Helbrim att svampsporerna samlas in?",a="Apothecary Helbrim undersöker de märkliga livsenergier som flödar genom Barrens oaser och muterar den omgivande floran och faunan. Royal Apothecary Society anser att de förändrade svamparnas kraftfulla egenskaper är särskilt värdefulla för deras forskning. Helbrim behöver proverna omedelbart för att bereda en särskild brygd som måste skickas vidare till hans kollega Apothecary Zamah, stationerad i Thunder Bluff.",al={"varför vill helbrim ha sporer","helbrims motiv","varför samla svampsporer"}}},fp="13,297,25.365.0,40.385.0,34.129.0,45.170.0,26.205.0,45.124.0,55.155.0,49.175.0"}
P.entries["quest:849"] = {n="Revenge of Gann",s="Vid Bael Modan vänder Gann Stonespire dvärgarnas egna planer mot deras flygmaskin. Horde-agenten söker hämnd för den fallna Stonespire-stammen.",h="Vid Bael Modan vänder Gann Stonespire dvärgarnas egna planer mot deras flygmaskin.",kw={"bael modan","explosive stick of gann","flygmaskin","gann stonespire","khazgorm","stonespire-stammen","the barrens","thunder bluff"},ang={["faction:Horde"]="När Bael Modans flygmaskin lamslås försvagas ett luftburet Alliance-vapen som kan spana och slå till långt in i södra Barrens.",["profession:Engineering"]="Sprängladdningen vänder ritningar från Ironforge mot en gyrokopter och blir därmed en listig sabotagehandling ute i fält.",["race:Tauren"]="Att förstöra dvärgarnas krigsmaskiner för att hämnas Stonespire-klanen berör alla taurer som försvarar sitt förfädershem mot skändning."},sec={{t="En symbol för herravälde",b="Vid Bael Modan ligger dvärgarnas utgrävning ovanpå Stonespire-taurernas förfäders marker, som de fördrivits från. Prospectors förlitar sig på en gyrokopter för att nå långt och visa sin militära styrka. Den står på ett vakttorn ovanför utgrävningen, där den spanar över det omgivande Barrens och skyddar dvärgarnas försörjningslinjer. För Gann visar maskinen också att Alliance trängt in på kalimdorisk mark."},{t="Vänt mot sina skapare",b="Efter att ha återfått Prospector Khazgorms planer tillverkar Gann Stonespire en specialladdning som kallas Explosive Stick of Gann. När den fästs på flygmaskinen vänds dvärgarnas egen uppfinning mot dem. Explosionen förstör en viktig militär tillgång, förödmjukar styrkan vid Bael'dun och hedrar andarna från Ganns förlorade stam."}},faq={{q="Varför vill Gann förstöra just flygmaskinen?",a="Flygmaskinen hjälper Bael Modans infrastruktur och ger dvärgarna spaning från luften. För Gann förkroppsligar den också dvärgarnas makt och tornar upp sig över mark som hans mördade stam en gång kallade sitt hem.",al={"varför förstöra gyrokoptern","flygmaskinens syfte","varför rikta in sig på flygmaskinen"}},{q="Var finns flygmaskinen vid Bael Modan?",a="Flygmaskinen står på en plattform av trä halvvägs nerför rampen till den stora utgrävningsgropen, åtskild från dvärgarnas huvudsakliga fästning.",al={"var finns flygmaskinen","flygmaskinens plats","var finns gyrokoptern i bael modan"}},{q="Hur skapade Gann sprängladdningen?",a="Gann tillverkade Explosive Stick of Gann utifrån tekniska scheman och ingenjörsplaner som återfanns hos Prospector Khazgorm. Han använde dvärgarnas egna ritningar mot dem.",al={"hur tillverkades bomben","sprängladdningens ursprung","khazgorms planer för sprängladdningen"}},{q="Vilken stam tillhör Gann?",a="Gann tillhör Stonespire-stammen, en taurenklan som en gång levde i södra Barrens. Dvärgarnas utgrävning från Ironforge drev bort dem med våld och förstörde deras bosättning.",al={"ganns stam","vad är stonespire-stammen","vilka är stonespire-taurenerna"}},{q="Stoppar utgrävningen för gott om man förstör maskinen?",a="Förstörelsen av maskinen lamslår Bael Modans luftstyrka och infrastruktur och ger Gann personlig hämnd. De välbefästa dvärggrävarna och fästningen är fortfarande ett aktivt Alliance-fäste i området.",al={"stoppas bael modan","faller bael modan","vann gann"}},{q="Vilket erkännande ger Gann när uppdraget är slutfört?",a="Gann säger att hjälten som förstörde maskinen kommer att vördas i Thunder Bluff som en försvarare av taurernas heliga marker och en varaktig mästare för hans förlorade stam.",al={"ganns uppdrag slutfört","slutet på ganns uppdrag","vad säger gann"}}},fx={["947c7a95"]={q="Vad är den flygande maskinen vid Bael Modan?",a="Målet är en dvärgisk gyrokopter som står vid Bael Modan. Dvärgexpeditionen har byggt och underhåller den här flygmaskinen. Den är avgörande för utgrävningen, fungerar som ett luftburet vapen och står som en hotfull symbol för dvärgarnas intrång, som drev bort Ganns folk från deras förfäders hem.",al={"flygmaskinen vid bael modan","vad är målet i revenge of gann","dvärgarnas flygmaskin vid bael modan"}}},fp="15,139,22.352.0,22.343.1,62.197.0,50.143.0,41.172.0,31.181.0,60.216.0,61.156.1"}
P.entries["quest:85"] = {n="Lost Necklace",s="I södra Elwynn söker Bernice Stonefield efter sitt försvunna halsband. Hon misstänker Billy Maclure, den unga sonen i grannfamiljen, och ber dig leta efter honom på andra sidan vägen.",h="I södra Elwynn söker Bernice Stonefield efter sitt försvunna halsband.",kw={"bernice","billy","elwynn","gård","maclure","halsband","stonefield","vingårdar"},ang={["faction:Alliance"]="Som nybörjare i Alliansen i Elwynn Forest får du en försmak av livet vid gränstrakten genom att lösa en småsakstvist mellan de grälsjuka familjerna Stonefield och Maclure.",["race:Human"]="Som människa ser du att konflikterna i Stormwinds kungarike inte bara kommer från Defias fredlösa och gnollkrigsskaror. Även gamla gräl mellan grannar på landsbygden går djupt."},sec={{t="En grannes anklagelse",b="Familjerna Stonefield och Maclure bor på varsin sida om gränsen mellan sina ägor i södra Elwynn Forest, men de hyser föga välvilja mot varandra. När \"Auntie\" Bernice Stonefield upptäcker att hennes älskade halsband är borta, skyller hon på den yngste Maclure. Övertygad om att Billy Maclure smugit in på hennes gård och tagit det ber den bittra änkan dig att gå över vägen till vingården, hitta pojken och kräva tillbaka det."},{t="En hungrig pojke",b="På den närliggande vingården nekar Billy Maclure till att ha tagit halsbandet och hävdar att han inte är någon tjuv. Med ett menande leende antyder han att han kanske vet vad som hänt med det. Först vill han att någon stillar hans hunger med en färsk fläskpaj."}},faq={{q="Vem är Auntie Bernice Stonefield?",a="Auntie Bernice Stonefield är en äldre änka som bor på The Stonefield Farm i södra Elwynn Forest. Hon misstror grannfamiljen Maclure, särskilt deras bråkiga unge son, Billy.",al={"vem är auntie bernice","bernice stonefield","vem ger uppdraget försvunnet halsband"}},{q="Stal Billy Maclure verkligen halsbandet?",a="Billy Maclure förnekar bestämt att han stulit halsbandet. Han antyder att han vet vem som tog det, men vägrar berätta vad han vet förrän någon ger honom mat.",al={"är billy en tjuv","stal billy det","tog billy halsbandet"}},{q="Var hittar jag Billy Maclure?",a="Du hittar Billy Maclure bland vinrankorna vid The Maclure Vineyards, strax österut på andra sidan vägen från The Stonefield Farm.",al={"billy maclures plats","var är billy","hitta billy maclure"}},{q="Varför tycker familjerna Stonefield och Maclure illa om varandra?",a="Grannfamiljerna Stonefield och Maclure har varit indragna i en bitter lantlig fejd i åratal. Ägodelar, stolthet och gamla personliga oförrätter håller spänningarna vid liv, så båda sidor misstänker det värsta om den andra.",al={"familjefejd","fejden mellan stonefield och maclure","varför tycker de illa om varandra"}},{q="Vad händer efter att jag pratat med Billy Maclure?",a="Billy säger att han är för hungrig för att minnas vart halsbandet tog vägen. Han skickar dig tillbaka till Auntie Bernice för att baka en fläskpaj åt honom i utbyte mot informationen.",al={"vad händer sedan","efter försvunnet halsband","nästa uppdrag"}},{q="Var utspelar sig det här uppdraget?",a="Du färdas genom södra Elwynn Forest mellan The Stonefield Farm och den intilliggande The Maclure Vineyards.",al={"uppdragszon","var finns försvunnet halsband"}}},fx={b7900c48={q="Varför vill Auntie Bernice ha tillbaka sitt halsband?",a="Auntie Bernice är en äldre änka, och halsbandet är en mycket kär personlig ägodel. Förlusten gör henne förtvivlad, och hon misstänker genast den rivaliserande familjen intill, särskilt unge Billy Maclure, för att ha stulit det. Att få tillbaka arvegodset skulle ge henne sinnesro och värma en gammal änkas hjärta.",al={"varför vill bernice ha halsbandet","bernices motiv för halsbandet","varför är stonefields halsband viktigt"}},["27b02d6f"]={q="Varför konfronterar inte Auntie Bernice Billy Maclure själv?",a="Den bittra fejden mellan familjerna Stonefield och Maclure gör det nästan omöjligt för någondera sidan att tala sansat utan att ett slagsmål bryter ut. Bernice kan inte bara gå över till Maclure Vineyards själv, och Stormwinds vakter är alldeles för upptagna med att hantera gnoller och Defias-banditer för att medla i smågräl mellan grannbönder. En förbipasserande äventyrare kan agera neutral part och fråga ut pojken direkt.",al={"varför behöver bernice mig","varför skicka en äventyrare till billy","varför inte fråga stormwinds vakter"}}},fp="13,169,23.376.0,22.225.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.102.0"}
P.entries["quest:850"] = {n="Kolkar Leaders",s="Kolkar Leaders inleder en kampanj ledd av orchen Regthar Deathgate för att krossa framväxande centaurkrigsherrar i The Barrens. De nomadiska Kolkar har plågat tauren i generationer, men nya hövdingar organiserar sina splittrade grupper till ett verkligt militärt hot. Regthar ger Hordens mästare i uppdrag att fälla Barak Kodobane vid The Forgotten Pools innan hans inflytande sprider sig.",h="Kolkar Leaders inleder en kampanj ledd av orchen Regthar Deathgate för att krossa framväxande...",kw={"barak","the barrens","centaur","the crossroads","deathgate","the forgotten pools","kodobane","kolkar","regthar"},ang={["faction:Horde"]="Vägarna i The Barrens utgör den livsviktiga förbindelsen mellan Mulgore, Durotar och Hordens utposter längre bort. Genom att oskadliggöra Kolkars ledare skyddas de sårbara försörjningskaravanerna från förödande bakhåll.",["race:Orc"]="Thrall lovade att Horden skulle försvara tauren, och erfarna veteraner som Regthar Deathgate tar den trohetseden på allvar. De ser centaurernas krigsherrar som omedelbara strategiska hot mot orkisk överhöghet i The Barrens.",["race:Tauren"]="För tauren handlar det om överlevnad och hämnd att fälla Kolkars befälhavare. Centaurklanerna slaktade stammar och drev bort shu'halo från deras förfäders betesmarker i årtionden innan Horden fick fotfäste i Kalimdor."},sec={{t="Ett växande hot i ödemarken",b="I oräkneliga år har de hästkroppade centaurerna terroriserat Kalimdor och drivit de nomadiska tauren nästan till utrotning innan Thralls Horde anlände och vände utvecklingen. I The Barrens strövar den dominerande Kolkar-stammen vanligtvis omkring i splittrade, utspridda plundrargrupper. På senare tid har aggressiva hövdingar dock börjat ena de skilda grupperna och förvandla enkla plundrarband till ett samlat militärt hot som kan utmana Hordens befästa utposter."},{t="Att hugga av odjurets huvud",b="Orkkrigaren Regthar Deathgate, som är stationerad i ett läger väster om The Crossroads, insåg att Kolkar i hög grad förlitar sig på ren djärvhet och råstyrka för att hålla ihop. Utan starka befälhavare förfaller deras plundrare till inbördes strider. För att hejda deras framryckning uppmanar Regthar Hordens äventyrare att hugga av ormens huvud, med början hos Barak Kodobane, en äregirig ledare som slagit läger nära The Forgotten Pools grönskande vatten."},{t="Den första av många",b="Att döda Barak Kodobane är ett hårt slag mot Kolkars norra läger, men Regthar vet att Barak bara är förtruppen i en större rörelse. Hans död inleder en samordnad kampanj för att slå sönder Kolkars högsta befäl och banar väg för jakten på medhövdingarna Verog the Dervish och Hezrul Bloodmark runtom i The Barrens."}},faq={{q="Vem är Barak Kodobane?",a="Barak Kodobane är en våldsam Kolkar-centaurledare som samlade plundrare kring The Forgotten Pools norr om The Crossroads. Han är känd för sin kvickhet och grymhet och visade sig vara långt farligare än vanliga nomadiska plundrare när han organiserade skilda klaner till ett offensivt hot mot Horden.",al={"barak","vem är barak","barak kodobanes historia"}},{q="Var hittar jag Barak Kodobane?",a="Barak Kodobane har ett läger vid The Forgotten Pools, en grönskande oas norr om The Crossroads i centrala The Barrens. Han omges vanligtvis av lojala Kolkar-vakter.",al={"baraks plats","var finns barak","barak vid the forgotten pools"}},{q="Vem är Regthar Deathgate?",a="Regthar Deathgate är en orkkrigsveteran som håller till i ett litet bunkerläger strax väster om The Crossroads. Han bevakar centaurernas rörelser i The Barrens och organiserar förebyggande anfall för att skydda Hordens bosättningar mot samordnade räder.",al={"regthar","vem ger uppdraget kolkar leaders","regthar deathgates historia"}},{q="Varför är Kolkar ett så stort problem för Horden?",a="Centaurerna har i generationer fört ett hänsynslöst, närapå folkmordsartat krig mot tauren. Som fullvärdiga medlemmar av Horden förlitar sig tauren på sina allierade för att skydda sina förfäders jaktmarker och handelsvägar genom The Barrens mot fortsatt centaurisk expansion.",al={"varför bekämpa kolkar","kolkars hot","centaurernas rivalitet med horden"}},{q="Vad händer efter att Barak dödats?",a="När du besegrar Barak Kodobane avslöjas det att andra hövdingar samlar styrkor på andra håll i The Barrens. Regthar skickar dig genast för att lönnmörda Verog the Dervish vid The Stagnant Oasis och därefter Hezrul Bloodmark vid Lushwater Oasis, vilket leder fram till ett försvar mot ett direkt Kolkar-anfall.",al={"nästa uppdrag efter barak","fortsättning på kolkar leaders","what comes next"}},{q="Varför samlas Kolkar kring oaserna?",a="Vatten och bördig mark är dyrbara skatter i The Barrens torra klimat. Genom att ta över naturliga källor som The Forgotten Pools säkrar Kolkar viktiga vattenförråd och berövar samtidigt resenärer och taurenjägare strategiska viloplatser.",al={"varför finns centaurer vid oaser","kolkar och vatten","centaurer vid the forgotten pools"}}},fx={["55ee765d"]={q="Varför vill Regthar Deathgate att Kolkar-ledarna dödas?",a="Centaurstammar har trakasserat taurerna i generationer, men Kolkar i Barrens är vanligtvis splittrade och oorganiserade. På senare tid har karismatiska hövdingar börjat samla de kringströvande krigshorderna till ett enat hot mot Hordens bosättningar. Regthar vet att Hordens fäste i Barrens kan falla samman om de nya befälhavarna tillåts organisera sig. Genom att röja ledare som Barak Kodobane ur vägen slår han mot upprorets topp innan det kan övermanna försvaret i området.",al={"varför döda kolkar-ledarna","regthar deathgates motiv","varför vill regthar att det görs"}},["4347847a"]={q="Vad ska Baraks huvud användas till?",a="Regthar behöver obestridliga bevis för att centaurernas befälhavare har fallit. I Barrens hårda gränsland räcker rykten och påståenden inte för att garantera säkerheten. När du kommer med Baraks avhuggna huvud bekräftar det att Kolkar-krigshorden vid Forgotten Pools verkligen har förlorat sin ledare och sin vilja att samordna fler anfall.",al={"varför baraks huvud","vad ska baraks huvud användas till","vad gör jag med baraks huvud"}}},fp="14,323,31.376.0,22.400.0,17.282.1,22.270.0,32.143.0,25.212.0,48.271.0,35.253.1,42.224.0"}
P.entries["quest:851"] = {n="Verog the Dervish",s="I södra Barrens håller Verog the Dervish sig i rörelse, medan Regthar Deathgate försöker locka fram honom. Orchen skickar Hordens mästare att anfalla Kolkars kommandotält vid The Stagnant Oasis, i hopp om att tvinga ut den nomadiska ledaren.",h="I södra Barrens håller Verog the Dervish sig i rörelse, medan Regthar Deathgate försöker locka fram honom.",kw={"the barrens","kentaur","the crossroads","dervish","kolkar","regthar deathgate","the stagnant oasis","verog"},ang={["faction:Horde"]="Som medlem av Horden vet du att oaserna är livsviktiga för överlevnaden i det torra The Barrens. Genom att besegra kentaurernas befälhavare hjälper du till att hålla vattenvägarna öppna för försörjningskaravaner.",["race:Orc"]="Som ork vet du att Regthar Deathgate anser att Kolkar-krigsherrarna måste besegras för att säkra vägen mellan The Crossroads och Stonetalon Mountains för Durotars resenärer.",["race:Tauren"]="Som tauren vet du att Kolkar har jagat och trakasserat ditt nomadfolk över dessa slätter i generationer. Verogs avrättning innebär en länge väntad vedergällning."},sec={{t="Locka fram dervischen",b="Efter att Barak Kodobane fallit vände sig Regthar Deathgate till de kvarvarande Kolkar-krigsherrarna. Barak höll till nära vattnen i norr vid The Forgotten Pools, men Verog the Dervish strövar över de solstekta slätterna och stannar sällan länge i ett läger. Hordens spejare kan inte lätt följa hans spår över det vidsträckta området. Deras chans är att få befälhavaren att komma till dem."},{t="The Stagnant Oasis",b="Verog utgår från Kolkars kommandopost vid The Stagnant Oasis, sydost om The Crossroads. Regthar skickar dig mot lägret, där du angriper Kolkar-krigarna nära deras kommandotält. Deras alarmrop kallar tillbaka Verog för att försvara utposten och för honom inom räckhåll för Hordens klingor."}},faq={{q="Vem är Verog the Dervish?",a="Verog the Dervish leder Kolkars kentaurer i The Barrens. Han befaller från The Stagnant Oasis men strövar omkring i de södra ödemarkerna, vilket gör honom svår att ringa in.",al={"vem är verog","verogs historia","verog the dervish"}},{q="Varför stannar Verog inte i sitt läger?",a="Verog strövar omkring i The Barrens i stället för att stanna i ett läger. Hans rörelser gör det svårt för Hordens krigssällskap att hitta honom, så hans fiender måste provocera honom att återvända.",al={"var finns verog","varför strövar verog omkring","verog saknas"}},{q="Hur lockar man fram Verog?",a="Hotta Verogs stam vid kommandoposten vid The Stagnant Oasis. Om du anfaller Kolkar nära deras kommandotält går larmet och han återvänder för att försvara platsen.",al={"hur får man fram verog","hitta verog","verog syns inte"}},{q="Vem beordrar Verogs död?",a="Regthar Deathgate beordrar att Verog ska dö. Den erfarne orchen slår läger väster om The Crossroads, längs huvudvägen till Stonetalon Mountains, och jagar Kolkars regionala befälhavare en efter en.",al={"vem ger uppdraget","regthar deathgate"}},{q="Vad händer när Verog faller?",a="När Verog faller tar du hans avhuggna huvud till Regthar, som sätter det bredvid Barak Kodobanes. Regthar riktar sedan uppmärksamheten mot Hezrul Bloodmark, kentaurernas krigsherre vid Lushwater Oasis i söder.",al={"what comes next","efter verog"}},{q="Varför är kentaurerna i Kolkar ett sådant problem i The Barrens?",a="Kolkar hotar The Barrens genom att lägga beslag på områdets livsviktiga vattenkällor och plundra karavaner, utposter och taurenhjordar som hör hemma där. Deras angrepp hotar Hordens späda närvaro i centrala Kalimdor.",al={"varför slåss man mot kolkar","kolkarhotet"}}},fx={["42943e7a"]={q="Varför vill Regthar Deathgate att Verog dödas?",a="Regthar Deathgate bryter systematiskt ner Kolkar-centaurernas ledarskap, som hotar norra Barrens och The Crossroads. Verog the Dervish leder centaurernas krigshord kring Stagnant Oasis. Genom att döda honom och de andra Kolkar-hövdingarna vill Regthar slå sönder deras befälsordning och försvaga deras grepp om de viktiga oaserna innan deras styrkor kan övermanna Hordens bosättningar.",al={"varför döda verog","regthar deathgates motiv","varför vill regthar ha verog död"}},f05e98a6={q="Vad används Verogs huvud till?",a="Regthar Deathgate tar Verogs avhuggna huvud som obestridligt bevis på dervischens död. Han tänker spetsa det på en påle vid sin utpost, bredvid Barak Kodobanes huvud. Det ska både visa vilka fiendebefälhavare som fallit och varna Kolkar som närmar sig längs vägen väster om The Crossroads.",al={"vad ska verogs huvud användas till","vad gör regthar med verogs huvud","varför ta verogs huvud"}}},fp="17,236,23.334.0,18.273.0,25.141.0,35.159.0,24.147.0,25.187.0,31.193.1,57.195.0"}
P.entries["quest:852"] = {n="Hezrul Bloodmark",s="Vid Lushwater Oasis leder Hezrul Bloodmark Kolkarernas intrång genom The Barrens. Regthar Deathgate skickar dig för att göra slut på hans befäl och bryta kentaurernas grepp om området.",h="Vid Lushwater Oasis leder Hezrul Bloodmark Kolkarernas intrång genom The Barrens.",kw={"bloodmark","centaur","crossroads","deathgate","hezrul","kolkar","lushwater","oas","regthar"},ang={["faction:Horde"]="Som medlem av Horden vet du att säkrandet av The Crossroads och The Barrens kräver att kentaurernas grepp bryts över de tre stora oaser som gör det möjligt att färdas genom området.",["race:Orc"]="Som ork hör du Regthar Deathgate bedöma Kolkar utifrån orkernas sätt att föra krig. Kentaurerna är stridslystna, men deras vilda raseri saknar den järnhårda disciplin som Horden har slipat fram.",["race:Tauren"]="Som tauren känner du till generationer av brutal fördrivning och blodsutgjutelse för kentaurernas hand. Att besegra krigsherrar som Hezrul är en dyrköpt vedergällning."},sec={{t="Halshuggning av Kolkar",b="Efter att Barak Kodobane och Verog the Dervish fallit är Hezrul Bloodmark fortfarande den främste hövdingen bland Kolkar i The Barrens. Regthar Deathgate kallar honom brutal och listig, spjutspetsen bakom kentaurernas intrång över savannen. Horden hoppas att hans död ska så kaos och splittra Kolkarklanen bortom all återhämtning, innan de hinner övermanna Hordens bosättningar."},{t="Lushwaters fäste",b="Hezrul leder sina krigsband från Lushwater Oasis, söder om The Crossroads. De få vattenhålen i The Barrens är livsviktiga för överlevnaden, vilket gör oasen till en strategisk knutpunkt och samlingsplats för Kolkarrövare. På Hezruls egen mark nekar du kentaurerna deras viktigaste fäste och skär av deras grepp om de södra stigarna."},{t="En farlig följd",b="Regthar lovordar segern över Hezrul och påpekar att kentaurerna saknar orkernas fokuserade disciplin. Men Kolkar skingras inte stillsamt. Rasande samlar de sina återstående styrkor och inleder ett desperat angrepp i full skala mot Regthars läger för blodig hämnd."}},faq={{q="Vem är Hezrul Bloodmark?",a="Hezrul Bloodmark leder Kolkar-kentaurerna genom The Barrens. Hård, listig och brutal styr han deras klaner och rövare från Lushwater Oasis.",al={"vem är hezrul","hezrul bloodmarks bakgrund","centaurledare i barrens"}},{q="Var finns Hezrul Bloodmark?",a="Hezrul patrullerar i södra The Barrens längs stränderna vid Lushwater Oasis, söder om The Crossroads, med Kolkarlivvakter vid sin sida.",al={"var finns hezrul","hezruls plats","var hittar man hezrul"}},{q="Vem ger uppdraget att döda Hezrul?",a="Regthar Deathgate, en orkerkämpe, ger ordern vid ett litet läger väster om The Crossroads, längs vägen mot Stonetalon Mountains.",al={"vem ger uppdraget hezrul bloodmark","regthar deathgates uppdrag","uppdragsgivare för hezrul"}},{q="Varför vill Horde se Hezrul död?",a="Kolkar hotar Hordens handelsvägar och bosättningar. Regthar tror att om deras främste hövding dödas kommer klanens sammanhållning att splittras och dess förmåga att föra samordnat krig att försvagas kraftigt.",al={"varför döda hezrul","syftet med hezrul bloodmark","kolkarhotet i barrens"}},{q="Vad händer efter att Hezrul dödats?",a="De överlevande Kolkar vägrar att ge upp. De enas i vrede och inleder omedelbart en motattack mot Regthar Deathgates utpost väster om The Crossroads.",al={"motattack efter hezrul","vad händer sedan","följder av att döda hezrul"}},{q="Hur förhåller sig Hezrul till Barak och Verog?",a="Barak Kodobane och Verog the Dervish ledde enskilda oaser och krigsband som underordnade Kolkarledare. Hezrul Bloodmark befäl över hela klanen genom The Barrens.",al={"barak verog hezrul","kolkarhövdingar","tre centaurledare"}}},fx={ca31e908={q="Vad ska Hezruls huvud användas till?",a="Regthar Deathgate behöver Hezrul's Head som obestridligt bevis för att den högsta ledaren bland Kolkar i Barrens har fallit. Precis som med Barak Kodobane och Verog the Dervish före honom bekräftar det avhuggna huvudet för Horden att centaurernas ledarskap har slagits sönder och hotet avvärjts.",al={"vad används hezruls huvud till","varför ta hezruls huvud","hezruls huvud"}}},fp="16,177,23.354.0,24.339.0,21.276.1,24.147.0,36.133.0,35.135.0,36.193.0,35.158.1,42.157.0"}
P.entries["quest:853"] = {n="Apothecary Zamah",s="Det här ärendet får en äventyrare att skynda från The Barrens torra ödemarker till Thunder Bluff med en flyktig, koncentrerad svampemulsion. Apothecary Helbrim behöver få den kraftfulla blandningen snabbt levererad till sin kollega, Apothecary Zamah, som håller till i de skuggiga djupen under Spirit Rise.",h="Det här ärendet får en äventyrare att skynda från The Barrens torra ödemarker till Thunder Bluff med en...",kw={"apothecary helbrim","apothecary zamah","fungal spores","the pools of vision","rendered spores","royal apothecary society","spirit rise","the barrens","thunder bluff"},ang={["faction:Horde"]="Snabb kommunikation mellan utposterna i The Barrens och Thunder Bluffs höga platå håller regionens försörjningskedjor samman.",["race:Tauren"]="Även när de välkomnar sina nya allierade betraktar traditionella tauren ofta med skepsis de märkliga bubblande brygder som Forsaken tillreder djupt inne i The Pools of Vision, som är heligt för dem.",["race:Undead"]="När du för Helbrims arbete till Zamah stärker du det hemliga forskningsnätverk som Royal Apothecary Society upprätthåller längs centrala Kalimdors dammiga gränsland."},sec={{t="En ömtålig last",b="Efter att ha studerat de egendomliga svampar som frodas kring oaserna i The Barrens kokar Apothecary Helbrim ner en sats till en känslig emulsion. Brygden är instabil och bryts snabbt ner när den väl har tillretts. Helbrim har inte tid att själv resa till Mulgore, så han anförtror flaskan åt en pålitlig budbärare som får ta sig uppför klipporna innan lösningen förlorar sin kemiska styrka."},{t="Under schamanernas blickar",b="Apothecary Zamah har sitt laboratorium långt från Mulgore öppna slätter, undangömt inne i The Pools of Vision. Den underjordiska grottan ligger djupt under Spirit Rises heliga höjder och delas med Forsaken-magiker och präster. Här, under golvet i taurenhelgedomen, bedriver Royal Apothecary Society i tysthet sin forskning med råmaterial som samlats in över hela kontinenten."}},faq={{q="Varför har leveransen en tidsgräns?",a="Helbrims koncentrerade svampemulsion är kemiskt flyktig. Om den lämnas oskyddad eller obehandlad för länge bryts ämnena ner och förlorar sin styrka, vilket gör blandningen oanvändbar i Zamahs arbete.",al={"varför tidsgräns","uppdragets tidsgräns","tidsgräns för koncentrerade sporer"}},{q="Var hittar jag Apothecary Zamah?",a="Apothecary Zamah finns i The Pools of Vision i Thunder Bluff. Ingången till grottan är något dold på Spirit Rise och leder ner under schamanernas tält.",al={"var finns zamah","zam ahs plats","hitta zamah"}},{q="Vem är Apothecary Helbrim?",a="Apothecary Helbrim är en alkemist från Royal Apothecary Society, stationerad vid The Crossroads i The Barrens. Han analyserar den lokala floran och faunan för att se hur Kalimdors inhemska organismer kan tjäna Forsaken.",al={"vem är helbrim","helbrim vid crossroads"}},{q="Vad gör Royal Apothecary Society i Thunder Bluff?",a="Som allierade inom Horde har Forsaken representanter, som Zamah, stationerade i Thunder Bluff. De arbetar i tysthet i The Pools of Vision under jord, analyserar prover från hela Kalimdor och upprätthåller försörjningsförbindelser med andra utposter.",al={"varför forsaken i thunder bluff","apotekare i the pools of vision"}},{q="Vad användes svampsporerna till från början?",a="Sporerna växer kring de frodiga oaserna i The Barrens och frodas onaturligt väl i öknen. Helbrim kokade ner dem för att studera deras biologiska egenskaper och alkemiska användningsområden innan han lämnade över dem till Zamah.",al={"varför sporer","användning av svampar i the barrens"}},{q="Vad händer om tiden tar slut?",a="När tiden går ut bryts emulsionen ner och förstörs. Du måste återvända till Apothecary Helbrim vid The Crossroads för att hämta en ny sats och leverera den till Thunder Bluff.",al={"tiden gick ut","sporerna förstördes"}}},fx={f0da41d1={q="Varför vill Apothecary Helbrim att de bearbetade sporerna levereras så snabbt?",a="Apothecary Helbrim har lyckats bearbeta de märkliga svampsporerna från Barrens till en instabil emulsion. Blandningen bryts snabbt ner, och bara hans kollega Apothecary Zamah har de särskilda reagenserna och anläggningarna i Pools of Vision som krävs för att stabilisera, försegla om och analysera den innan den förlorar sin kraft för alltid.",al={"varför skicka sporer till zamah","helbrims motiv","varför vill helbrim att det levereras"}}},fp="16,153,15.241.0,30.269.0,43.165.0,34.139.0,26.209.0,60.238.0,48.184.0,35.165.0"}
P.entries["quest:854"] = {n="Journey to the Crossroads",s="Vid Camp Taurajo skickar Kirge Sternhorn resenärer norrut för att hjälpa Thork vid The Crossroads. Färden för dem från Mulgore in i The Barrens och vidare in i Hordens större konflikter.",h="Vid Camp Taurajo skickar Kirge Sternhorn resenärer norrut för att hjälpa Thork vid The Crossroads.",kw={"barrens","camp taurajo","crossroads","jordemodern","kirge sternhorn","thork","thunder bluff"},ang={["faction:Horde"]="Som medlem av Horden ser du samarbetet växa mellan stammarna i Thunder Bluff och krigshövdingens förtrupp i centrala Kalimdor.",["race:Orc"]="Som orch vet du att Thork behöver förstärkning söderifrån för att hålla marken som Thralls spejare säkrat i The Barrens.",["race:Tauren"]="Som tauren lämnar du Jordemoderns heliga mesatrygg och ger dig in i Hordens större konflikter."},sec={{t="Från vaggan",b="Camp Taurajo är platsen där många tauren först möter The Barrens bortom Mulgore. Strax efter bergspasset vakar mystikern Kirge Sternhorn över resenärer som tar sig ner i de torra gräsmarkerna. När Sternhorn ser att en resenär är redo att fortsätta pekar Kirge norrut längs den dammiga handelsvägen mot The Crossroads."},{t="Ett gemensamt band",b="Tauren från Thunder Bluff och Thralls nya Horde delar nu samma öde. Kirge säger att de två folkens öden är sammanflätade, och orcherna vid The Crossroads behöver förstärkning medan de kämpar för att etablera en utpost. Vid bosättningen välkomnar Thork resenärer även från de höga klipporna, redo att pröva sin styrka mot savannens faror."}},faq={{q="Vem ger uppdraget Journey to the Crossroads?",a="Kirge Sternhorn, en taurenmystiker vid Camp Taurajo, skickar resenärer norrut. Lägret ligger i södra The Barrens, strax öster om bergspasset från Mulgore.",al={"vem ger uppdraget","uppdragsgivare","kirge sternhorn uppdrag"}},{q="Var finns Thork?",a="Thork finns innanför Stockades murar vid The Crossroads, Hordens bosättning i centrala The Barrens. Den ligger norr om Camp Taurajo längs huvudvägen.",al={"var finns thork","thorks plats","hitta thork"}},{q="Varför skickar Kirge Sternhorn resenärer till The Crossroads?",a="Kirge Sternhorn ser att en resenär är redo för större prövningar och vet att tauren och orcher nu delar ett sammanflätat öde. Den orciska garnisonen vid The Crossroads utsätts ständigt för lokala hot och behöver dugliga allierade.",al={"varför åka till crossroads","crossroads syfte","varför skicka mig till orcer"}},{q="Vad är The Crossroads?",a="The Crossroads är Hordens viktigaste strategiska knutpunkt och handelsplats i centrala Kalimdor. Viktiga leder från norr till söder och från öster till väster möts där, och bosättningen är en bas för att skapa ordning i den vilda gränsbygden.",al={"vad är crossroads","crossroads bosättning","knutpunkt i barrens"}},{q="Är det bara tauren som får uppdraget?",a="Ja. Kirge Sternhorn skickar bara tauren på den här färden, välkomnar fränder ända från Thunder Bluff och hänvisar dem till Thork.",al={"är uppdraget bara för tauren","hordens vägvisaruppdrag"}},{q="Vilka hot väntar längs vägen till The Crossroads?",a="Vägen norrut går över torra slätter där aggressiva plainstriders, smygande savannlejon och kringströvande grupper av Razormane quilboar stryker omkring. Håller du dig till den upptrampade vägen undviker du lättare de mer revirhävdande rovdjuren i den centrala savannen.",al={"är vägen farlig","vägen från taurajo till crossroads"}}},fx={fc69c860={q="Varför väljer Kirge Sternhorn dig för den här resan?",a="Kirge Sternhorn förutser din ankomst och förstår att du har vuxit bortom lokala prövningar. Han anar att du är ämnad för större dåd i Hordens länder och ser dig som rätt sändebud att träda fram och hjälpa dina orciska allierade.",al={"varför jag i journey to the crossroads","varför väljer kirge mig","varför skicka mig till the crossroads"}}},fp="25,171,18.279.0,13.352.0,37.156.0,23.149.0,58.220.0,23.203.0,33.137.0,52.239.0"}
P.entries["quest:855"] = {n="Centaur Bracers",s="Väster om The Crossroads efterlyser Regthar Deathgate Centaur Bracers. Kolkar-centaurer utmanar Horde om kontrollen över de centrala delarna av The Barrens och hotar dess herravälde över slätterna.",h="Väster om The Crossroads efterlyser Regthar Deathgate Centaur Bracers.",kw={"the barrens","belöning","armskenor","centaur","the crossroads","horden","kolkar","regthar deathgate"},ang={["faction:Horde"]="Att rensa bort Kolkar skyddar försörjningsvägarna mellan Orgrimmar och Thunder Bluff.",["race:Orc"]="Som orc hjälper du till att skapa ett permanent och stabilt hemland genom att säkra Durotars gränser mot nomadiska rövare.",["race:Tauren"]="Som tauren vet du att centaurerna i århundraden har härjat bland tauren-stammar och begått folkmord på dem. Att minska deras antal i The Barrens är personlig vedergällning."},sec={{t="Säkra slätterna",b="Den unga Horde kämpar för att säkra territorium över Kalimdor. The Barrens ligger mellan Durotar och Mulgore, men Kolkar-centaurer gör anspråk på dess vattenhål och öppna slätter. De anfaller försörjningståg och spaningspatruller. Regthar Deathgate, en orcisk krigare, leder försvaret från sin bunker väster om The Crossroads."},{t="En blodig räkenskap",b="Regthar ber om bevis på att Kolkar-krigare har stupat. Soldater som tar sig in på Kolkar-territorium återvänder med armband tagna från stupade centaurer. Troféerna styrker anspråk på Horde-belöningar och är tänkta att skrämma överlevande Kolkar-rövare."}},faq={{q="Vem är Regthar Deathgate?",a="Regthar Deathgate är en orcisk befälhavare i en befäst bunker väster om The Crossroads. Han leder Hordes försök att slå ner centaurernas räder i The Barrens.",al={"vem är regthar","regthar deathgate bakgrund","vem ger centaur bracers"}},{q="Varför vill Horden ha centaurernas armskenor?",a="Centaurarmband bevisar att fiendekrigare har stupat i strid. Regthar använder dem för att se till att belöningar bara går till dem som faktiskt tillfogar de fientliga Kolkar-stammarna förluster.",al={"varför armskenor","vad används centaur bracers till","varför samla armskenor"}},{q="Varför anfaller Kolkar Horden?",a="Kolkar är en brutal centaurklan från centrala Kalimdor som vill utöka sitt territorium. De gör anspråk på The Barrens som jaktmarker och bekämpar de nya bosättningarna, lägren och allianserna som orcher och tauren har bildat.",al={"varför hatar centaur horden","centaurkonflikt","kolkaraggression"}},{q="Var finns Kolkar-centaurerna i The Barrens?",a="Kolkar-rövarläger ligger kring oaser och oländiga bergsryggar i de centrala och södra delarna av The Barrens. Centaurerna strider ofta om tillgången till vatten och färdvägar genom området.",al={"var hittar man centaurer","kolkarplatser","centaurläger"}},{q="Upphör Kolkar-attackerna om man samlar in armskenorna?",a="Nej. Regthar hoppas att förlusterna ska skrämma de överlevande rövarna, men han tvivlar på att Kolkar frivilligt kommer att upphöra med sina anfall.",al={"fungerade centaur bracers","slutar centaurerna"}},{q="Vilket strategiskt värde har The Crossroads?",a="The Crossroads förbinder Durotar, Mulgores tauren-slätter och de norra färdvägarna in i Ashenvale. Att besegra närliggande centaurkrigare hjälper till att hålla Hordes försörjningslinjer intakta.",al={"varför försvara the crossroads","the crossroads betydelse"}}},fx={["5627e76a"]={q="Varför vill Regthar Deathgate att centaurernas armskenor samlas in?",a="Regthar Deathgate ser Kolkar-centaurerna som ett direkt hot mot Hordens fäste i Barrens. Genom att utlova en belöning för deras armskenor vill han nöta ner deras stridsstyrka. Han hoppas att de stora förlusterna ska skrämma de överlevande klanerna och hejda deras fortsatta anfall.",al={"varför vill regthar ha armskenorna","regthar deathgates motiv","varför centaurernas armskenor"}},["566bd14b"]={q="Vilka är Kolkar-centaurerna som du skickas ut för att strida mot?",a="Du skickas mot Kolkar-klanen, en brutal centaurstam som dominerar viktiga oaser i centrala och södra Barrens. De är våldsamt revirhävdande och blodtörstiga, och för krig mot både taurerna och de nyanlända orcerna för att driva bort Horden från Kalimdors slätter för gott.",al={"vilka är kolkar","vilka centaurer finns i barrens","vilken centaur ska bekämpas för armskenorna"}}},fp="15,132,19.328.0,21.249.0,25.157.0,40.169.0,39.210.0,53.170.0,54.125.0,46.170.0"}
P.entries["quest:8551"] = {n="The Captain's Chest",s="Captain Hecklebury Smotts brukade segla mellan Booty Bay och Ratchet i Kalimdor, tills havsjättar slog sönder skeppet, dödade besättningen och skickade iväg Smotts i en livbåt mot Booty Bay. Jätten Gorlash tog Smotts Captain's Chest, och Smotts vill ha tillbaka den.",h="Captain Hecklebury Smotts brukade segla mellan Booty Bay och Ratchet i Kalimdor, tills havsjättar slog sönder...",kw={"booty bay","gorlash","ratchet","havsjätte","smotts","snusdosa","stranglethorn"},sec={{t="En ruinerad kapten",b="Smotts säger att resorna till Ratchet i Kalimdor gav honom en framgångsrik karriär och ett gott rykte. Havsjättarna satte stopp för allt det: de slog sönder skeppet, dödade besättningen och skickade iväg Smotts i en livbåt mot Booty Bay."},{t="Den stulna kistan",b="Jätten Gorlash tog Smotts Captain's Chest och sa att han ville ha den som snusdosa. Kistan var Smotts favorit, med ett hemligt fack där de största skatterna förvarades. Smotts har hört att Gorlash strövar längs stranden öster om Booty Bay."},{t="Smotts tack",b="Smotts är överlycklig över att ha fått tillbaka kistan, och ilskan har lagt sig en aning, men hämnden är inte fullbordad."}},faq={{q="Vem är Captain Hecklebury Smotts?",a="Smotts är en skeppskapten i Booty Bay som en gång seglade mellan orten och Ratchet i Kalimdor, tills havsjättar slog sönder skeppet och dödade besättningen.",al={"kapten smotts","vem är smotts","hecklebury smotts"}},{q="Vem tog kistan?",a="Gorlash, en av havsjättarna, tog den och sa att han ville ha den som snusdosa.",al={"vem stal kistan","vem har smotts kista","gorlash"}},{q="Var hittar man Gorlash?",a="Öster om Booty Bay, längs stranden. Det är där Smotts har hört att jätten strövar omkring.",al={"var finns gorlash","gorlash plats","hitta gorlash"}},{q="Varför vill Smotts ha tillbaka kistan?",a="Det var Smotts favoritkista, och dess dolda fack förvarade de största skatterna.",al={"vad finns i kistan","varför vill smotts ha kistan"}}},fp="19,310,16.259.0,16.224.0,14.125.1,33.170.0,19.87.0,27.55.0,36.112.0"}
P.entries["quest:8552"] = {n="The Monogrammed Sash",s="Ett fint skärp med broderade initialer antyder att dess rättmätiga ägare finns någonstans i Stranglethorn Vale. Att hitta sjöfararen som tappade det leder vidare till The Captain's Cutlass.",h="Ett fint skärp med broderade initialer antyder att dess rättmätiga ägare finns någonstans i Stranglethorn...",kw={"hecklebury smotts","hs","mok'rash","monogramskärp","sjöjätte","stranglethorn vale"},sec={{t="Ett märkt plagg",b="Det här fina skärpet har bokstäverna ”HS” broderade längs fållen. Den som tappade det kan bara spåras med hjälp av dessa två bokstäver."},{t="Kopplingen till Smotts",b="När Captain Hecklebury Smotts får tillbaka plagget bekräftas det att det tillhör honom. När det återfinns visar det sig att sjöjätten Mok'rash har dräpts, vilket blir en lättnad för kaptenen efter att besten flera gånger varit med och förstört hans fartyg och dödat hans besättning."}},faq={{q="Vilka bokstäver är broderade på skärpet?",a="Det fina skärpets fåll har initialerna ”HS” broderade på sig.",al={"vilka initialer finns på skärpet","initialer på monogramskärp","bokstäver på skärp"}},{q="Vart leder detta härnäst?",a="När skärpet har återlämnats till sin ägare är nästa steg The Captain's Cutlass.",al={"vilket uppdrag kommer efter monogramskärp","nästa uppdrag efter monogramskärp","nästa steg"}}},fp="20,145,16.120.0,21.255.1,40.49.0,26.85.0"}
P.entries["quest:8553"] = {n="The Captain's Cutlass",s="Captain Hecklebury Smotts köpte ett andra fartyg, Smotts' Revenge, för att jaga havsjättarna som tog hans första skepp, men led ännu ett nederlag. Jättarna slog sönder fartyget och dödade besättningen, och en av dem, Negolash, stal kaptenens huggare. Smotts ber dig rådfråga hans före detta skeppskock, Sprogger, för att spåra upp besten.",h="Captain Hecklebury Smotts köpte ett andra fartyg, Smotts' Revenge, för att jaga havsjättarna som tog hans...",kw={"huggare","hecklebury smotts","negolash","havsjättar","smotts revenge","sprogger","stranglethorn"},sec={{t="En andra katastrof",b="Efter att ha förlorat sitt första skepp skaffade Captain Hecklebury Smotts ett andra fartyg, Smotts' Revenge, och samlade en ny besättning och förnödenheter för att hämnas på havsjättarna. Företaget slutade i katastrof när jättarna krossade skeppet och dödade besättningen, så att Smotts återigen drev omkring i en livbåt. Under angreppet tog jätten Negolash kaptenens huggare."},{t="Rådfråga kocken",b="Smotts är fast besluten att återfå sin stulna klinga och förlitar sig på sin kock. Sprogger, som tjänstgjorde ombord på Smotts' Revenge, överlevde attacken och kan hjälpa dig att hitta Negolash."}},faq={{q="Vilket skepp förlorade Captain Hecklebury Smotts i den här attacken?",a="Smotts köpte och utrustade ett skepp som hette Smotts' Revenge för att jaga jättarna som förstörde hans första fartyg, men jättarna förstörde även det.",al={"vad hette det andra skeppet","smotts andra skepp","vilket skepp slogs sönder"}},{q="Vem stal kaptenens huggare?",a="Negolash, en av havsjättarna som slog sönder Smotts' Revenge och dödade besättningen, tog vapnet.",al={"vem har huggaren","vilken jätte tog huggaren","vem tog smotts huggare"}},{q="Vem är Sprogger?",a="Sprogger arbetade som kock ombord på Smotts' Revenge och överlevde attacken som förstörde fartyget. Captain Smotts hänvisar resenärer till honom för att få hjälp att hitta Negolash.",al={"vem är sprogger","sproggers roll","vem var kocken"}},{q="Var passar det här steget in i jakten på havsjättarna?",a="Det här steget följer efter The Monogrammed Sash och leder direkt till Facing Negolash.",al={"vilket uppdrag kommer före det här","vilket är nästa uppdrag","huggarens uppdragskedja"}}},fp="21,216,17.330.0,19.188.0,60.148.0,32.120.0,16.170.0,58.77.0"}
P.entries["quest:8555"] = {n="The Charge of the Dragonflights",s="Anachronos från den bronsfärgade drakflykten möter dig i Tanaris för att avsluta den första delen av Scepter of the Shifting Sands. Den kedjan leder fram till att öppna Gates of Ahn'Qiraj.",h="Anachronos från den bronsfärgade drakflykten möter dig i Tanaris för att avsluta den första delen av Scepter...",kw={"anachronos","azuregos","eranikus","gates of ahn'qiraj","scepter of the shifting sands","tanaris","vaelastrasz"},sec={{t="Början tar slut",b="Mötet avslutar den första delen av Scepter of the Shifting Sands, kedjan som leder fram till att öppna Gates of Ahn'Qiraj. Anachronos avslutar den här första delen tillsammans med dig."},{t="De tre väktarna",b="Anachronos nämner tre drakar, Eranikus, Vaelastrasz och Azuregos, som har spelat inflytelserika roller som världens väktare. Enligt Anachronos har var och en av dessa beskyddare drabbats av tragedi, antingen genom de gamla gudarnas agenter eller genom förräderi från dem som kallade dem vänner. Anachronos medger att han delvis bär skulden på grund av sin godtrogenhet och säger att allt detta har väckt misstro mot dödliga. Du får i uppdrag att söka upp de tre och förbereda dig på det värsta."}},faq={{q="Vem är Anachronos?",a="Anachronos är en drake från bronsdrakflykten, som du möter här i Tanaris.",al={"vem är anachronos","anachronos tanaris","bronsdrake"}},{q="Vad är Scepter of the Shifting Sands?",a="Det är den långa kedjan som leder fram till att öppna Gates of Ahn'Qiraj. Mötet avslutar dess första del.",al={"scepter-kedjan","scepter of the shifting sands","gates of ahn'qiraj-kedjan"}}},fp="31,167,24.155.0,18.387.1,18.75.0,42.155.0"}
P.entries["quest:8569"] = {n="Past Efforts in Warsong Gulch",s="I Warsong Gulch kämpar soldater för Ashenvale medan befälhavare hedrar deras uppoffringar. Huvudstädernas officerare tar emot Ribbon of Sacrifice som ett tecken på trogen tjänst, även när striderna inte leder till någon tydlig seger.",h="I Warsong Gulch kämpar soldater för Ashenvale medan befälhavare hedrar deras uppoffringar.",kw={"ashenvale","brigadgeneral","orgrimmar","tidigare insatser","ribbon of sacrifice","stormwind","warbringer","warsong gulch"},ang={["class:Warrior"]="Som krigare känner du till de brutala närstriderna i dalen. Disciplin innebär att kämpa hårt även när segern står och väger.",["faction:Alliance"]="Som soldat i Alliansen bekräftar du ditt löfte att försvara de uråldriga skogarna och stödja dina nattalviska allierade mot Warsongs aggression när du överlämnar ett band till en Brigadier General.",["faction:Horde"]="Som medlem av Horden bekräftar du att blodet som spillts för att säkra virke och överlevnad i Ashenvale inte var förgäves när du överlämnar en gåva till en Warbringer."},sec={{t="Att hedra de fallna och de tappra",b="Silverwing Sentinels och Warsong Outriders utkämpar brutala skärmytslingar längs Ashenvales södra gräns. Många strider slutar utan en tydlig seger. Stormwind, Orgrimmar och andra huvudstäder hedrar dem som håller stånd trots oddsen. Ribbon of Sacrifice utmärker krigare som gett allt i kampen."},{t="Krigsinsatsen därhemma",b="Långt från fronten leder Alliance Brigadier Generals och Horde Warbringers sina styrkor. Rekryterare skickar nya krigare till Warsong Gulch, medan kvartermästare och taktiker räknar in veteraner som återvänder från hårda fälttåg. Genom att hedra mod i dödläge eller nederlag hjälper ledarna soldaterna att fortsätta försvara Ashenvale."}},faq={{q="Vad är syftet med den här utmärkelsen?",a="Utmärkelsen hedrar krigare som gav allt i Warsong Gulch. Huvudstädernas befälhavare tar emot Ribbon of Sacrifice för att uppmärksamma deras uthållighet och stärka moralen.",al={"varför tidigare insatser","syftet med tidigare insatser","vad betyder tidigare insatser"}},{q="Vem tar emot dessa offergåvor?",a="Alliance Brigadier Generals och Horde Warbringers tar emot gåvorna i större städer, däribland Stormwind och Orgrimmar.",al={"vem tar emot tidigare insatser","var lämnar man in tidigare insatser","vem är brigadgeneralen"}},{q="Varför belönar militären insatser som inte ledde till seger?",a="Befälhavarna vet att striderna i Ashenvales skogar kräver många offer. Att hedra soldaternas hängivenhet visar att deras uppoffringar betyder något, även när de inte segrar.",al={"varför belöna ribbon of sacrifice","varför belöna nederlag","betydelsen av hjältemodiga insatser"}},{q="Var utspelar sig konflikten i Warsong Gulch?",a="Warsong Gulch ligger längs Ashenvales södra gräns. Warsong Outriders samlar timmer där medan Silverwing Sentinels gör motstånd.",al={"var ligger warsong gulch","warsong gulchs plats","vad är warsong gulch"}},{q="Kan medlemmar av både Alliansen och Horden göra det här?",a="Ja. Båda fraktionerna hedrar återvändande soldater genom sina militära ledare i respektive huvudstäder.",al={"gäller det båda fraktionerna","horden eller alliansen tidigare insatser","kan horden lämna in det här"}},{q="Vad står Ribbon of Sacrifice för?",a="Ribbon of Sacrifice hedrar krigare som uthärdat våldsamma sammandrabbningar i Warsong Gulch och fortfarande är villiga att kämpa för sitt folk.",al={"bakgrund om ribbon of sacrifice","vad är ribbon of sacrifice","uppoffringens band"}}},fp="29,193,35.318.0,22.329.0,41.158.0,38.119.0,66.147.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="The Tear of the Moons",s="Vid Bael Modan har en relik kallad Tear of the Moons gjort Feegly the Exiled galen och besatt. General Twinbraid har låst in den som en förbannelse, men Feegly kräver fortfarande att få tillbaka den.",h="Vid Bael Modan har en relik kallad Tear of the Moons gjort Feegly the Exiled galen och besatt.",kw={"bael modan","barrens","dvärgförbannelse","feegly","feegly the exiled","general twinbraid","tear of the moons"},ang={["faction:Horde"]="Genom att anfalla Bael Modan för att återta reliken får Horde en chans att störa dvärgarnas verksamhet, som gör intrång i The Barrens."},sec={{t="Uppgrävd vid Bael Modan",b="Dvärgarna fann Tear of the Moons när de högg ut Bael Modan ur kullarna i södra Kalimdor. Det var deras första stora upptäckt, och dess märkliga inflytande drabbade genast Feegly, en av expeditionens arbetare."},{t="Twinbraids isolering",b="Feegly hävdade att Tear gav honom enorm kraft och vände sig våldsamt mot sina kamrater för att skydda den. General Twinbraid såg hur reliken fördärvade honom, kallade den förbannad, tog den från Feegly och låste in den i fästet. Feegly förvisades från utgrävningslägret och sökte skydd bland klipporna. Bitter och besatt ber han förbipasserande resenärer att stjäla tillbaka Tear."},{t="Det fruktansvärda priset",b="General Twinbraids varningar visar sig stämma när Feegly återfår Tear of the Moons. Relikens dolda förvandlingsmagi slukar honom och förvandlar dvärgen till en vild trogg. Hans liv tar slut sekunder efter att han återtagit skatten."}},faq={{q="Vad är Tear of the Moons?",a="Tear of the Moons är en kraftfull relik som dvärgiska utgrävare fann under sina första grävningar vid Bael Modan i södra The Barrens. Den fördärvar dem som hanterar den och fyller dem med en berusande makthunger.",al={"vad är tear of the moons","tear of the moons relik","bael modan artefakt"}},{q="Vem är Feegly the Exiled?",a="Feegly the Exiled var utgrävare i General Twinbraids expedition vid Bael Modan. Efter att Tear of the Moons hittades blev han besatt och våldsam, och Twinbraid kastade ut honom ur fästet.",al={"vem är feegly","feeglys bakgrund","feegly dvärg"}},{q="Varför låser General Twinbraid in Tear?",a="General Twinbraid låste in Tear eftersom han insåg att den var en farlig förbannelse. Efter att Feegly vänt sig mot sina medutgrävare säkrade Twinbraid reliken inne i Bael Modans fäste.",al={"varför twinbraid låste in tear","twinbraids förbannelse","relik i bael modans fäste"}},{q="Vad händer när du återlämnar Tear till Feegly?",a="När Tear återlämnas får Feegly som han begär, men vad som händer sedan är ännu okänt.",al={"vad händer med feegly","feeglys slut","återlämna tear"}},{q="Är Tears magi helt förstådd?",a="General Twinbraid kallar Tear förbannad, medan Feegly längtar efter kraften som han tror att den ger. Dess magi förblir oförklarad.",al={"tear-magi","tear of the moons förbannelse","hur fungerar tear"}},{q="Varför är detta ett Horde-uppdrag om Feegly är en dvärg?",a="Feegly är en utstött som gömmer sig i The Barrens, där han avskyr Alliansens styrkor som ockuperar Bael Modan. Han vädjar till äventyrare från Horde, som är fientliga mot Twinbraids utgrävning, att plundra fästet och återta reliken.",al={"varför horde-uppdrag","tillhör feegly horde","bael modan horde"}}},fx={["76d5a92c"]={q="Varför vill Feegly the Exiled ha tillbaka Tear of the Moons?",a="Feegly är helt besatt av Tear of the Moons. Artefakten grävdes fram vid Bael Modan och gav honom en märklig, berusande kraft innan General Twinbraid förklarade den förbannad och tog den ifrån honom. Efter våldsamma bråk om reliken förvisade Twinbraid Feegly från utgrävningsplatsen. Feegly har blivit uppslukad av paranoia och längtan efter kraften han en gång hade. Han är desperat efter att återta det han anser vara hans med rätta.",al={"varför vill feegly ha tear of the moons","feeglys motiv","varför vill feegly the exiled ha tear of the moons"}},["7effe162"]={q="Varför ber Feegly dig i stället för att själv hämta Tear of the Moons?",a="General Twinbraid förvisade Feegly med våld från Bael Modan och låste in artefakten djupt inne i fästningen. Feegly är utstött och persona non grata bland sina dvärgkamrater. Så fort han satte sin fot i fästningen igen skulle Twinbraids vakter gripa eller döda honom. Eftersom han inte kan infiltrera sitt gamla hem ensam vänder han sig till en utomstående äventyrare som kan smyga in och stjäla artefakten åt honom.",al={"varför behöver feegly dig","varför kan feegly inte hämta artefakten själv","varför behöver feegly min hjälp"}}},fp="21,100,23.213.0,22.360.0,17.221.1,30.216.0,25.192.0,46.187.0,48.82.1,37.124.1,47.213.0"}
P.entries["quest:8576"] = {n="Translating the Ledger",s="Du tar Azuregos ledger till Narain Soothfancy, som måste ta reda på vad som står i den. Det är ett steg på vägen mot att öppna Gates of Ahn'Qiraj.",h="Du tar Azuregos ledger till Narain Soothfancy, som måste ta reda på vad som står i den.",kw={"arcanite buoy","azuregos","draconic","ledger","narain soothfancy","tanaris"},sec={{t="Ledgern når Narain",b="Du tar Azuregos ledger till Narain Soothfancy. Någon måste ta reda på vad Azuregos skrev i den, och det faller på Narain."},{t="Vad Narain kommer fram till",b="Narain får höra att Azuregos har satt dig på att bygga en arcanite buoy och att ledgern innehåller ritningen. Narain tycker det är märkligt att Azuregos skrev den på Draconic, som Narain inte kan läsa. För att få det att fungera behöver Narain spårningsglasögonen, en kyckling på femhundra pund och den andra volymen av Draconic for Dummies, i valfri ordning."}},faq={{q="Vems ledger är det?",a="Det är Azuregos ledger. Du ska ta den till Narain Soothfancy.",al={"vems ledger","azuregos ledger","vem skrev ledgern"}},{q="Vem läser ledgern?",a="Narain Soothfancy, som måste ta reda på vad Azuregos skrev i den.",al={"vem översätter ledgern","narain soothfancy","vart tar man ledgern"}}},fp="22,150,26.140.0,23.326.1,19.64.0,21.66.0"}
P.entries["quest:8577"] = {n="Stewvul, Ex-B.F.F.",s="Efter att ha översatt Ledger säger Narain Soothfancy att ingenting kan översättas utan spådomsglasögonen. Narains före detta bästa vän för alltid, Stewvul, stal dem, och du ska hitta Stewvul och ta tillbaka dem.",h="Efter att ha översatt Ledger säger Narain Soothfancy att ingenting kan översättas utan spådomsglasögonen.",kw={"the greymane wall","oansenlig låda","ledger","narain soothfancy","spådomsglasögon","silverpine","stewvul","tanaris"},sec={{t="De stulna glasögonen",b="Narain Soothfancy behöver spådomsglasögonen innan något kan översättas. De stals för ett tag sedan av Stewvul, Narains före detta bästa vän för alltid, som krossade Narains hjärta på fem ställen och sedan övergav Narain här."},{t="Var du ska leta",b="Med hjälp av en pålitlig kristallkula har Narain ringat in Stewvuls vistelseort till två platser. Den ena är The Greymane Wall i Silverpine. Den andra är en värld bortom en portal. Det är du som ska spåra upp Stewvul och få tillbaka glasögonen."},{t="Vad Stewvul säger",b="Stewvul kan inte tro att Narain har hittat dem. Stewvul tänker inte återvända och har fått nog av att bara vara vän ibland och slav resten av tiden."}},faq={{q="Varför behöver Narain spådomsglasögonen?",a="Narain säger att ingenting kan översättas utan dem.",al={"varför behövs glasögonen","narains syfte med glasögonen","spådomsglasögon användning"}},{q="Vem är Stewvul?",a="Stewvul är Narain Soothfancys före detta bästa vän för alltid. Stewvul stal spådomsglasögonen, krossade Narains hjärta på fem ställen och övergav sedan Narain här.",al={"vem är stewvul","stewvuls historia","narains vän"}},{q="Var tror Narain att Stewvul är?",a="Narains kristallkula ringar in två platser: The Greymane Wall i Silverpine eller en avlägsen portalvärld.",al={"var är stewvul","stewvuls platser","the greymane wall"}},{q="Vad kommer före det här?",a="Translating the Ledger, där du tog Azuregos ledger till Narain.",al={"föregående uppdrag","förutsättning","vad leder hit"}}},fp="18,124,18.223.0,13.191.0,17.140.1,41.66.0,15.154.0,35.112.0,23.79.0"}
P.entries["quest:858"] = {n="Ignition",s="I ett läger tillhörande Venture Company i norra Barrens behöver en instängd pilot en tändningsnyckel innan täckmanteln spricker. Operatören kapade en shredder utan nyckel och behöver någon som hämtar den hos platschefen.",h="I ett läger tillhörande Venture Company i norra Barrens behöver en instängd pilot en tändningsnyckel innan...",kw={"borrtorn","ignition","ignition key","ratchet","flismaskin","sputtervalve","the barrens","venture company","wizzlecrank"},ang={["faction:Horde"]="Venture Companys hänsynslösa skogsskövling hotar norra Barrens. Att sabotera eller stjäla deras tunga maskiner stör arbetet.",["profession:Engineering"]="Venture Companys shredder har precisa armreglage och följsamma rotationsregulatorer, långt bättre än det vanliga tekniska pysslet i Ratchet."},sec={{t="En kupp som gick snett",b="En spion utsänd av Sputtervalve har smugit sig in i en shredder tillhörande Venture Company vid borrplatsen i norra Barrens. Operatören tänker ta över maskinen och undersöka hur den fungerar. Men styr- och rörelsesystemet förblir låst utan dess tändningsnyckel."},{t="En bluff under press",b="En goblinarbetare har lagt märke till att shreddern står stilla, så kaparen bluffar om att motorn har gått sönder. Instängd under glastaket med arbetare i närheten visar operatören dig till det centrala borrtornet. Platschefen förvarar reservnycklar till tändningen på kontrollkontoret högst upp, enda vägen ut innan bluffen spricker."},{t="Företagsavund",b="Nyckeln vrids om och tjuven undersöker shredderns reglage. De precisa armspakarna, rotationsreglagen och stabilitetsdämparna överträffar de klumpiga maskiner som används i Ratchet. Maskinen är nu ett byte inom industrispionage och pilotens chans att överleva."}},faq={{q="Vem sitter i flismaskinen?",a="En operatör med koppling till Sputtervalve, en ingenjör i Ratchet, befinner sig inne i shreddern. Piloten tog sig in i Venture Companys verksamhet för att stjäla en av deras avancerade maskiner för röjning av skog.",al={"flismaskinens pilot","vem sitter i wizzlecrank shredder","wizzlecrank"}},{q="Varför kan flismaskinen inte bara köra därifrån?",a="Shredderns rörelsesystem är låst utan tändningsnyckeln. Kaparen tog sig in i förarhytten, men maskinen kan inte röra sig förrän nyckeln låser upp drivreglagen.",al={"varför behövs nyckeln","varför har den fastnat","flismaskinen är låst"}},{q="Var hittar man Ignition Key?",a="Platschefen hos Venture Company har tändningsnyckeln. Platschefen befinner sig i kontrollrummet högst upp i det närliggande träborrtornet.",al={"var finns tändningsnyckeln","var är arbetsledaren","hur hittar man nyckeln"}},{q="Varför vill Ratchet ha en flismaskin från Venture Company?",a="Ratchet vill ha en shredder från Venture Company eftersom dess ingenjörskonst överträffar standardmodellerna som används där. En intakt maskin skulle låta lokala uppfinnare studera dess armreglage, hastighetsregulatorer och stabilitetssystem.",al={"varför stjäla flismaskinen","ratchets flismaskin","sputtervalves flismaskin"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en gobliningenjör och operatör i Ratchet. Sputtervalve håller uppsikt över Venture Companys expansion och söker efter deras mekaniska innovationer.",al={"vem är sputtervalve","vem skickade wizzlecrank","sputtervalve i ratchet"}},{q="Vad händer när flismaskinen startas?",a="När nyckeln vrids om låses shredderns rörelsesystem upp. Piloten försöker sedan köra den kapade maskinen ut ur det fientliga borrningslägret och tillbaka i säkerhet, medan en eskortinsats pågår.",al={"vad händer efter ignition","efter tändningsnyckeln","fortsättning på ignition"}}},fx={["52fc6a42"]={q="Varför måste det här göras genast åt Wizzlecrank?",a="Wizzlecrank smög sig in på Venture Companys borrplats för att lägga beslag på en av deras avancerade skördare åt Ratchet. Men han blev fast i förarhytten utan startmekanismen. Ännu värre blev det när en annan operatör kom fram, så han fick panik och bluffade om att maskinen hade gått sönder. Det är bara en tidsfråga innan besättningen kommer tillbaka eller genomskådar lögnen. Då förvandlas en stillsam stöld till en avrättning om han inte kan starta motorn och fly omedelbart.",al={"wizzlecranks motiv","varför är det bråttom med ignition","varför behöver wizzlecrank nyckeln"}},edef521b={q="Vem har nyckeln till skördaren?",a="Nyckeln förvaras av Venture Companys arbetsledare, som befinner sig högt uppe i kontrollrummet på borrtornet. Venture Company håller sina avverknings- och borrningsarbeten i Barrens under hård kontroll och ser till att vanliga arbetare inte kommer åt viktiga reglage, för att förhindra stöld och sabotage. För att ta nyckeln måste du infiltrera deras kommandopost och konfrontera arbetsledaren som styr hela platsen.",al={"vem har ignition key","venture companys arbetsledares nyckel"}},e6f51bdb={q="Varför ber Wizzlecrank dig hämta nyckeln i stället för att göra det själv?",a="Wizzlecrank sitter fast i förarhytten, omgiven av misstänksamma arbetare från Venture Company. Om han klättrar ut och smyger över lägret mot kommandotornet röjer han sig genast och larmar hela arbetsplatsen. Han måste stanna kvar och låtsas undersöka de trasiga reglagen, medan han förlitar sig på en utomstående som kan ta sig upp till arbetsledarens plats.",al={"varför kan inte wizzlecrank hämta nyckeln","varför behöver wizzlecrank hjälp","varför jag för wizzlecrank"}}},fp="8,200,21.239.0,23.341.0,18.277.1,27.188.0,41.172.0,32.122.0,49.215.0,20.152.0,43.201.1"}
P.entries["quest:8584"] = {n="Never Ask Me About My Business",s="Narain Soothfancy har en plan som han vägrar förklara, och den kräver en kyckling på femhundra pund. Du beger dig till Gadgetzan för att tala med Dirge Quikcleave, som kan hjälpa dig att hitta en lämplig fågel.",h="Narain Soothfancy har en plan som han vägrar förklara, och den kräver en kyckling på femhundra pund.",kw={"kyckling på 500 pund","black chicken of death","dirge quikcleave","gadgetzan","narain soothfancy","tanaris"},sec={{t="Planering och hämtning",b="Narain Soothfancy vill inte ha fler frågor om sina förehavanden, som rör saker du aldrig skulle kunna begripa. Planeringen sköter han, och hämtningen sköter du. Som han sa tidigare behöver planen en kyckling på femhundra pund, och Dirge Quikcleave på värdshuset i Gadgetzan kan visa dig var du hittar en."},{t="Dirges svar",b="Dirge Quikcleave kliar sig i huvudet. Det går inte längre att hitta en kyckling med den vikten, säger han, även om han en gång kände till en, Black Chicken of Death, och ingen som såg den fågeln överlevde för att berätta om den. Sedan säger han att han har en idé som kan vara bra för er båda."}},faq={{q="Varför behöver Narain Soothfancy en kyckling på femhundra pund?",a="Narain tänker inte berätta. Hans förehavanden handlar om sådant du inte skulle förstå, som en psychotronic muzzledorf, och han sköter planeringen själv medan du får sköta hämtningen.",al={"varför kyckling på 500 pund","narains kycklingaffärer","varför vill narain ha en kyckling"}},{q="Vem behöver du prata med i Gadgetzan?",a="Narain skickar dig till Dirge Quikcleave, som finns på värdshuset i Gadgetzan och kan hjälpa dig att börja leta efter en lämplig kyckling.",al={"vart ska man gå","vem ska man träffa i gadgetzan","var finns dirge quikcleave"}},{q="Vilket uppdrag kommer före det här?",a="Translating the Ledger kommer först. Narain Soothfancy tar upp kycklingen efter det.",al={"förutsättningsuppdrag","vilket uppdrag kommer först","föregående steg"}},{q="Var finns Narain Soothfancy?",a="Narain Soothfancy finns i Tanaris.",al={"var finns narain","narains plats","narain soothfancy plats tanaris"}}},fp="30,143,21.284.0,14.214.1,61.175.0,40.98.0,29.86.0,35.32.0"}
P.entries["quest:8586"] = {n="Dirge's Kickin' Chimaerok Chops",s="Dirge Quikcleave i Gadgetzan har räknat ut sitt recept. Han behöver fortfarande tjugo Goblin Rocket Fuel och tjugo Deeprock Salt av dig, och han vill ha dem snabbt så att köttet du gav honom inte blir dåligt.",h="Dirge Quikcleave i Gadgetzan har räknat ut sitt recept.",kw={"chimaerok","chops","deeprock salt","dirge","gadgetzan","narain","quikcleave","raketbränsle"},sec={{t="Vad Dirge fortfarande behöver",b="Dirge Quikcleave sköter kryddorna själv, och köttet du gav honom utgör resten av rätten. Det enda han saknar är raketbränsle och deeprock-salt, tjugo av varje. När han har fått dem är fågeln redo att skickas tillbaka till Narain Soothfancy. Dirge uppmanar dig att skynda dig, eftersom han inte vill att köttet ska bli dåligt."}},faq={{q="Vem ber om de här förnödenheterna?",a="Dirge Quikcleave i Gadgetzan ber om dem för att göra klart sitt recept.",al={"vem startar uppdraget","vem ger dirge's kickin chimaerok chops","dirge quikcleaves uppdrag"}},{q="Vilka ingredienser behöver Dirge Quikcleave?",a="Dirge vill ha tjugo Goblin Rocket Fuel och tjugo Deeprock Salt. Kryddorna sköter han själv, och köttet du gav honom räcker till resten.",al={"vilka föremål behöver jag","ingredienser till dirges chops","föremål till dirges chops"}},{q="Vem är den färdiga rätten avsedd för?",a="Dirge säger att fågeln är redo att bäras tillbaka till Narain Soothfancy när du har gett honom det han bad om.",al={"vem äter chopsen","vem får kycklingen","vem är maten till"}},{q="Vad händer när ingredienserna har lämnats över?",a="Nästa steg är att återvända till Narain.",al={"nästa uppdrag","vad gör jag efter dirge chops","vad följer efter uppdraget"}}},fp="31,172,22.289.0,28.77.0,44.132.0,38.78.0,46.63.0"}
P.entries["quest:8587"] = {n="Return to Narain",s="Dirge Quikcleave håller sitt löfte och lämnar över den femhundra pund tunga kycklingen. Du tar den till Narain Soothfancy i Tanaris. Det här sker efter Dirge's Kickin' Chimaerok Chops.",h="Dirge Quikcleave håller sitt löfte och lämnar över den femhundra pund tunga kycklingen.",kw={"500 pund tung kyckling","chimaerok","dirge quikcleave","narain soothfancy","tanaris"},sec={{t="Ett infriat löfte",b="Dirge Quikcleave ger dig kycklingen han lovade och säger att han är en goblin som håller sitt ord. Han kan inte föreställa sig vad en gnom skulle vilja med en så stor fågel och muttrar att den måste vara till att sova i. Härifrån tar du den till Narain Soothfancy i Tanaris."},{t="Narains välkomst",b="Doften av kycklingen fångar Narain Soothfancys uppmärksamhet. Han trycker båda nävarna mot fågeln och vräker i sig Dirges matlagning. Han förklarar att det är den bästa kyckling han någonsin ätit."}},faq={{q="Vad hände före den här leveransen?",a="Först kommer Dirge's Kickin' Chimaerok Chops, där Dirge Quikcleave bad om raketbränslet och saltet för att färdigställa sitt recept.",al={"föregående uppdrag","vad gjorde jag före detta","förutsättning"}},{q="Vem tar emot den enorma kycklingen?",a="Narain Soothfancy i Tanaris.",al={"vem får kycklingen","vem ska jag ta den till","inlämningsplats"}},{q="Varför lagade Dirge en femhundra pund tung kyckling?",a="Dirge håller sitt löfte genom att lämna över kycklingen. Han säger att han aldrig kommer att förstå vad en gnom vill med en så stor fågel.",al={"varför en 500 pund tung kyckling","vad ska kycklingen användas till","dirges kyckling"}},{q="Vad händer efter att kycklingen har levererats?",a="The Good News and The Bad News följer, men Narain erbjuder den först när två andra delar av arbetet också är färdiga: Narain's Scrying Goggles och Draconic For Dummies: Volume II.",al={"nästa uppdrag","vad följer efter detta","vart härnäst"}}},fp="16,169,14.251.0,16.190.1,31.113.0,33.58.0,51.148.0,40.142.0"}
P.entries["quest:8597"] = {n="Draconic for Dummies",s="Narain Soothfancy minns en bok som han gömde på en säker plats. Leta efter hans kraschade gyrokopter på Land's End Beach och simma sedan söderut därifrån till en ö i South Seas. Detta följer efter Translating the Ledger.",h="Narain Soothfancy minns en bok som han gömde på en säker plats.",kw={"draconic for dummies","nyligen uppgrävd jord","gyrokopter","land's end beach","narain soothfancy","south seas","tanaris"},sec={{t="En undangömd bok",b="Narain Soothfancy säger att boken säkert kommer till nytta och att han gömde den där ingen kunde hoppas hitta den. Första gången behövde han en gyrokopter för att ta sig dit, och på vägen tillbaka kraschade han den på stranden. Han säger att kraschen gav honom sina supergnomiska psykiska krafter. Vraket ligger någonstans längs Land's End Beach, och därifrån simmar du söderut. Narain är säker på att du genast kommer att känna igen platsen. Ön där boken ligger begravd finns ute i South Seas."},{t="På ön",b="På ön hittar du en jordhög, men boken är borta. I dess ställe ligger en lapp ovanpå jordhögen."}},faq={{q="Vem skickar dig för att hitta boken?",a="Narain Soothfancy skickar dig efter boken när du har avslutat Translating the Ledger åt honom.",al={"vem ger draconic for dummies","narain uppdragsgivare","vem ger det här uppdraget"}},{q="Var kraschade Narain sin gyrokopter?",a="Narain säger att han kraschade den på en strand när han var på väg tillbaka efter att ha gömt boken. Du hittar vraket någonstans på Land's End Beach.",al={"var finns gyrokoptern","platsen för den kraschade gyrokoptern","kraschen på lands end beach"}},{q="Var ska boken vara gömd?",a="Narain Soothfancy säger att den ligger begravd på en ö ute i South Seas. Simma söderut från vraket på Land's End Beach. Han säger att platsen blir uppenbar när du ser den.",al={"bokens plats","var ligger ön","var ska man simma"}},{q="Hur fick Narain sina psykiska krafter?",a="Narain säger att kraschen med gyrokoptern på stranden gav honom hans psykiska krafter.",al={"narains psykiska krafter","hur blev narain synsk"}}},fp="20,193,18.441.0,13.101.1,32.90.0,38.120.0,40.172.0,38.74.0"}
P.entries["quest:8598"] = {n="rAnS0m",s="Vid den nygrävda jorden där Narain Soothfancys bok borde ligga har en lösensummalapp lämnats i dess ställe. Du tar brevet tillbaka till Narain Soothfancy i Tanaris. Detta följer efter Draconic for Dummies.",h="Vid den nygrävda jorden där Narain Soothfancys bok borde ligga har en lösensummalapp lämnats i dess ställe.",kw={"draconic for dummies","nygrävd jord","narain soothfancy","lösensumma","lösensummabrev","tanaris"},sec={{t="En lapp av pappersbitar",b="Lappen består av många olika typsnitt som klistrats fast på pergament. Den säger till Narain, som den kallar en gnom, att hans dyrbara bok är i brevskrivarnas händer och att han bara får se den igen om han gör precis som han blir tillsagd. Detaljerade instruktioner fyller tre sidor och avslutas med ett krav på att ta med pengarna och komma ensam. Du tar brevet till Narain Soothfancy i Tanaris."},{t="Nარains svar",b="Narain Soothfancy frågar vad saken gäller, läser sedan brevet och blir alldeles röd i ansiktet. Han är rasande över att någon har stulit hans bok och svär att visa de skyldiga vad det innebär att sätta sig upp mot en psykisk gnom."}},faq={{q="Vad kräver lösensummalappen?",a="Brevskrivarna hävdar att de har Narains bok, och han får bara se den igen om han gör precis som de ber om. Instruktionerna sträcker sig över tre sidor och avslutas med ett krav på pengar och att han ska komma ensam. Lappen säger inte vem som skrev den.",al={"vad står det på lappen","lösensummabrevets text","vem tog boken"}},{q="Vart leder det här steget härnäst?",a="När brevet har överlämnats till Narain Soothfancy i Tanaris fortsätter kedjan med Decoy!",al={"vad kommer efter lösensumman","fortsättning på lösensumman","nästa uppdrag efter lösensumman"}},{q="Vad hände innan lösensummalappen hittades?",a="Draconic for Dummies kommer före den, sökandet efter Narains begravda bok som slutar vid den nygrävda jorden.",al={"föregående uppdrag","förkunskapskrav för lösensumman"}}},fp="6,199,21.346.0,15.198.1,34.234.0,31.91.0,41.103.0"}
P.entries["quest:8599"] = {n="Love Song for Narain",s="Meridith the Mermaiden har ett meddelande till Narain Soothfancy, gnomen hon en gång räddade ur vraket efter en kraschad flygmaskin. Hon ber dig ta med hennes kärleksbrev till honom i Tanaris. Du kan ta dig an detta uppdrag medan du söker efter Narains bok i Draconic for Dummies.",h="Meridith the Mermaiden har ett meddelande till Narain Soothfancy, gnomen hon en gång räddade ur vraket efter...",kw={"flygmaskin","kärleksbrev","meridith","sjöjungfru","narain soothfancy","tanaris","vrak"},sec={{t="Ett meddelande till stranden",b="Meridith the Mermaiden får sällan besök. Den senaste besökaren var gnomen hon räddade ur vraket efter en kraschad flygmaskin. Hon blickar ut i tomma intet en stund, försjunken i minnet. Hon frågar om du känner Narain Soothfancy, för hon måste berätta hur hon känner, och hon är säker på att det är kärlek. Hon ber dig att överlämna ett meddelande till honom och lovar att stå i evig tacksamhetsskuld till dig."},{t="Narains svar",b="Narain Soothfancy påpekar att du luktar fisk. När han får veta vad brevet säger blir han rastlös och invänder att hon är en fisk och han en gnom, så det skulle aldrig kunna fungera."}},faq={{q="Vem är Meridith?",a="Meridith är en sjöjungfru som sällan får besök. Den senaste besökaren var gnomen Narain Soothfancy, som hon räddade ur vraket efter en kraschad flygmaskin.",al={"vem är meridith","meridith the mermaiden","sjöjungfrulegend"}},{q="Hur känner Meridith Narain Soothfancy?",a="Hon räddade honom ur vraket efter hans kraschade flygmaskin, och hon tror att hon är kär i honom.",al={"hur träffade meridith narain","narain och meridiths relation","narains flygkrasch"}},{q="Vad är kärleksbrevet?",a="Det är Meridiths meddelande till Narain Soothfancy, där hon berättar hur hon känner. Hon vill att det överlämnas till honom i Tanaris.",al={"meridiths kärleksbrev","kärleksbrev till narain","vad står i meddelandet"}},{q="Vad hände före det här uppdraget?",a="Draconic for Dummies kommer före det. Meridith erbjuder uppdraget till dem som redan söker efter Narains begravda bok.",al={"föregående uppdrag","förkunskapskrav för love song for narain"}}},fp="20,194,23.355.0,15.188.1,16.141.0,41.105.0,24.133.0,30.108.0"}
P.entries["quest:86"] = {n="Pie for Billy",s="Auntie Bernice Stonefields försvunna halsband har fått Billy Maclure att kräva en fläskpaj i utbyte. Familjerna Stonefield och Maclure har legat i fejd i generationer, och Billy tänker inte säga vem som har halsbandet förrän han får sin paj.",h="Auntie Bernice Stonefields försvunna halsband har fått Billy Maclure att kräva en fläskpaj i utbyte.",kw={"bernice stonefield","billy maclure","elwynn forest","försvunnet halsband","the maclure vineyards","pork belly pie","the stonefield farm","mört vildsvinskött"},ang={["profession:Cooking"]="Auntie Bernice säger att vildsvinskött kan vara segt och smaklöst, men att rätt kryddor och lång sjudning gör det till en utsökt, smakrik pajfyllning.",["race:Human"]="Som människa ser du de envisa, slutna fejderna mellan Elwynns lantliga gårdsägare, strax söder om Stormwinds portar."},sec={{t="En pojkes muta",b="Billy Maclure ber inte om ursäkt när han får frågor om Auntie Bernice Stonefields försvunna halsband. Han tänker varken lämna tillbaka det eller säga vem som har det innan han får en nygräddad fläskpaj. Han vet att Bernice är dalens bästa kock och tänker njuta av uppgörelsen."},{t="Bakning trots gammalt groll",b="Familjerna Maclure och Stonefield har utbytt förolämpningar, hamnat i slagsmål och anklagat varandra på varsin sida av pumpafälten i generationer. Bernice blir rasande av tanken på att mata pojken som hon tror stal familjens smycken, men går ändå med på att baka. Du samlar mört kött från vildsvinen som strövar omkring på de närliggande betesmarkerna, och hon lägger stoltheten åt sidan för att få tillbaka sitt dyrbara halsband."}},faq={{q="Varför vill Billy ha en paj innan han pratar?",a="Billy Maclure vet var Auntie Bernices halsband finns och använder den kunskapen för att förhandla till sig mat. Han tänker inte säga vem som har det förrän han får en av Bernices fläskpajer.",al={"varför billy vill ha paj","paj som muta till billy","billys fläskpaj"}},{q="Varför går Auntie Bernice med på att baka åt en tjuv?",a="Auntie Bernice är rasande på pojken som hon tror stal hennes halsband, men ser inget annat sätt att få tillbaka det. Hon går med på att baka när du kommer med vildsvinskött och sätter återlämnandet av sin egendom framför sin stolthet.",al={"varför bernice bakar","varför bernice stonefield bakar paj","stonefield bakar åt maclure"}},{q="Varifrån kommer köttet till pajen?",a="Köttet kommer från vildsvin som bökar på ängarna och längs kanterna av familjerna Stonefields och Maclures gårdar i Elwynn Forest.",al={"var man får tag på kött","källa till mört vildsvinskött"}},{q="Vad har familjerna Stonefield och Maclure för historia?",a="Familjerna Stonefield och Maclure är grannbönder med en bitter rivalitet som har pågått i åratal. De misstänker varandra för stöld, skadegörelse och osämja i ond tro över tomtgränserna.",al={"fejden mellan stonefield och maclure","gårdsrivalitet","maclure mot stonefield"}},{q="Stal Billy verkligen halsbandet?",a="Auntie Bernice anklagar Billy direkt. Han undviker att erkänna rakt ut, men vet uppenbart var halsbandet hamnade och använder den kunskapen för att förhandla till sig mat.",al={"stal billy halsbandet","vem tog halsbandet","billy tjuven som tog halsbandet"}},{q="Vad händer när Bernice får köttet?",a="När du kommer med det möra vildsvinsköttet bakar Auntie Bernice en fläskpaj som du ska ta med till Billy. Hon hoppas att han då avslöjar vem som har hennes halsband.",al={"nästa steg efter pajen","vad händer efter pajen till billy"}}},fp="13,179,13.238.0,24.273.0,41.175.0,50.208.0,42.129.0,57.207.0,38.162.0,41.152.0"}
P.entries["quest:860"] = {n="Sergra Darkthorn",s="Efter att ha visat grundläggande färdigheter i spårning och smygjakt bland Mulgore böljande kullar skickas unga tauren ut i The Barrens torra vildmark. Melor Stonehoof sänder blivande jägare norrut över gränsen för att rapportera till Sergra Darkthorn vid The Crossroads. Resan markerar jägarens formella övergång från lokala prövningar till Kalimdors vidsträckta slätters krävande rovdjurshierarki.",h="Efter att ha visat grundläggande färdigheter i spårning och smygjakt bland Mulgore böljande kullar skickas...",kw={"the crossroads","jägarens väg","melor stonehoof","mulgore","plainstrider","sergra darkthorn","the barrens","thunder bluff"},ang={["class:Hunter"]="Resan markerar steget från enkel spårning av lokala villebråd till att bemästra de aggressiva rovdjuren och hårda förhållandena på Kalimdors inre savanner.",["faction:Horde"]="The Crossroads är den unga Hordens pulserande logistiska hjärta, där orchernas uthållighet, Darkspear-trollens list och taurentraditionen förenas under veteraner som Sergra.",["race:Tauren"]="För tauren som växt upp på Mulgore gröna betesmarker markerar rapporteringen till Sergra deras första betydande färd utanför förfädernas gränser, in i den större Hordens krävande tjänst."},sec={{t="De heliga kullarna lämnas bakom",b="För en nybörjare bland taurenjägarna är de första riterna i Mulgore bara början. De frodiga dalarna i deras förfäders hemland är skyddade och välbekanta, och där lever djur som prövar tålamodet snarare än den rena överlevnadsförmågan. Melor Stonehoof märker när en jägares själ har vuxit sig stark nog att behöva hårdare prövningar. Han säger åt sina lärlingar att packa sin utrustning, lämna tryggheten i Bloodhoof Village och färdas österut genom bergspasset till The Barrens stekheta buskmarker."},{t="Vägen till The Crossroads",b="Stigen genom de röda klippkanjonerna leder rakt ut på den vidsträckta, solstekta savannen där den unga Horden gör anspråk på marken. Där Kalimdors centrala handelsvägar möts ligger The Crossroads, en befäst bosättning full av orcher, troll och tauren. Där väntar Sergra Darkthorn, en erfaren orcisk shaman som är känd för sina skoningslösa krav. Hon vägleder alla som vågar jaga The Barrens vilda djur och lovar att förvandla rå entusiasm till hårdnad disciplin i vildmarken."}},faq={{q="Vem ger uppdraget och var hittar jag personen?",a="Uppdraget ges av Melor Stonehoof, en taurenjägare som handleder andra jägare och bor på Hunter Rise i Thunder Bluff.",al={"vem ger sergra darkthorns uppdrag","var finns melor stonehoof","var börjar man"}},{q="Var finns Sergra Darkthorn?",a="Sergra Darkthorn finns vid The Crossroads i centrala The Barrens, nära bosättningens östra sida, vakttornen och fållorna.",al={"var finns sergra darkthorn","var är sergra","hitta sergra"}},{q="Hur tar jag mig från Mulgore till The Crossroads?",a="Lämna Thunder Bluff söderut förbi Bloodhoof Village och ta sedan den östra vägen ut ur Mulgore genom kanjonpasset till The Barrens. När du passerat gränsporten följer du huvudvägen av grus österut tills den delar sig, och fortsätter sedan norrut till The Crossroads.",al={"vägbeskrivning till the crossroads","från mulgore till the barrens","hur tar man sig till the crossroads från thunder bluff"}},{q="Vad är syftet med uppdraget?",a="Det fungerar som ett vägvisaruppdrag som leder spelare som började sin resa i Mulgore till nästa stora nivåområde, The Crossroads i The Barrens, där de får kontakt med de lokala jaktuppdragen.",al={"varför göra uppdraget","sergra darkthorns syfte","är det här ett vägvisaruppdrag"}},{q="Får orcher och troll det här uppdraget?",a="Orcher och troll får ett motsvarande vägvisaruppdrag som heter ”Conscript of the Horde” i Durotar. Det skickar dem från Razor Hill till The Barrens, men de kan fortfarande träffa Sergra och ta uppdrag av henne när de kommer fram.",al={"orcernas version","trollens version","vägvisaruppdrag i durotar"}},{q="Vad lär Sergra Darkthorn jägarna?",a="Sergra prövar de anländande jägarna mot de inhemska djuren i The Barrens, först med plainstriders och prowlers. Hon lär dem att verklig skicklighet kräver uthållighet, respekt för landet och mental styrka, inte råstyrka.",al={"sergras roll","vad gör sergra","sergra och jakt"}}},fx={["94d282e7"]={q="Varför skickar Melor Stonehoof dig till Sergra Darkthorn?",a="Melor Stonehoof inser att du har vuxit ifrån Mulgore:s milda jaktmarker. För att verkligen vandra jägarens stig och pröva din själ måste du mäta dig med The Barrens vilda, viljestarka bestar. Melor skickar dig till Sergra Darkthorn vid The Crossroads, eftersom hon har den erfarna kunskap som krävs för att vägleda din träning över dessa hårda, solstekta slätter.",al={"varför skicka till sergra","melor stonehoofs motiv","varför bege sig till the crossroads"}},bb525daf={q="Varför väljer Melor dig för den här resan?",a="Den här resan är ingen syssla eller ett ärende åt Thunder Bluffs vakter; den är en viktig övergångsrit för en blivande jägare. Melor kan inte vandra stigen åt dig. Du har visat den hängivenhet och själ som krävs för att utveckla din träning, och bara genom att själv färdas ut i det vilda The Barrens kan du vässa dina instinkter och bli en mästare på jakt.",al={"varför jag, melor","varför skickar melor mig"}}},fp="16,206,24.348.0,26.479.0,46.113.0,34.113.0,44.227.0,34.122.0,34.182.0,41.183.0"}
P.entries["quest:8606"] = {n="Decoy!",s="Narain Soothfancy har en plan för lösensumman: en säck med stenar i stället för pengar, och du i hans ställe. Du tar hans förklädnad till överlämningsplatsen som boktjuvarna angav i Winterspring. Det här följer på lösensummebrevet.",h="Narain Soothfancy har en plan för lösensumman: en säck med stenar i stället för pengar, och du i hans ställe.",kw={"boktjuvar","lockbete","narain soothfancy","nummer två","lösensumma","winterspring"},sec={{t="Narains plan",b="I lösensummebrevet stod det att Narain själv skulle leverera, och på sätt och vis tänker han göra det. Han fyller en säck med stenar, synar dig uppifrån och ner och bestämmer sig för att du duger. Hans specialutrustning består av en turban, en mantel och säcken, och du tar den till överlämningsplatsen som boktjuvarna angav i Winterspring. När boktjuvarna dyker upp för att hämta bytet vill Narain göra sig av med dem, som en läxa i vad som händer när man går emot honom."},{t="Narains dom",b="När du kommer tillbaka erkänner Narain att han och du kanske underskattade de här boktjuvarna."}},faq={{q="Varför vill Narain att du ska bära en förklädnad?",a="I lösensummebrevet stod det att Narain själv skulle leverera. Hans plan är att skicka dig i sitt ställe, med turbanen och manteln från hans specialutrustning.",al={"varför bära turbanen","varför förklädnaden","varför klä ut sig till narain"}},{q="Var sker överlämningen?",a="På överlämningsplatsen i Winterspring som boktjuvarna angav, där säcken med stenar ska lämnas.",al={"var är avlämningsplatsen","var ska jag ta väskan","var ligger avlämningsplatsen"}},{q="Vad finns i lösensummeväskan?",a="Narain fyller säcken med stenar i stället för pengar.",al={"vad finns i väskan","är det riktigt guld","vad packade narain"}},{q="Vilket uppdrag kom före det här?",a="Först kom lösensummebrevet, med kravet på pengar för Narains stulna bok, som du tog med tillbaka till honom.",al={"förutsättningsuppdrag","föregående uppdrag","vad ledde fram till det här"}}},fp="6,184,15.384.0,16.87.1,44.171.0,35.127.0,30.50.0,28.102.0"}
P.entries["quest:861"] = {n="The Hunter's Way",s="The Hunter's Way är en övergångsrit som den äldre Skorn Whitecloud erbjuder blivande spårare i Mulgore. För att bevisa sin växande skicklighet och respekt för vildmarken måste vandrarna fälla de listiga slättströvarna och överlämna deras klor till Melor Stonehoof på Hunter Rise i Thunder Bluff.",h="The Hunter's Way är en övergångsrit som den äldre Skorn Whitecloud erbjuder blivande spårare i Mulgore.",kw={"slättströvare","slättströvarnas klor","hunter rise","melor stonehoof","mulgore","skorn whitecloud","the hunter's way","thunder bluff"},ang={["class:Hunter"]="Provet prövar direkt vildmarkens grundprinciper: att smyga sig på ett bakhållsrovdjur innan det hinner slå till och att tyda grässlätternas subtila tecken.",["faction:Horde"]="Denna rit ger allierade Horde-vandrare en möjlighet att förstå taurenfolkets vördnad för naturen och vinna deras förtroende på Thunder Bluffs höjder.",["race:Tauren"]="För unga tauren är det en grundläggande övergångsrit att överlämna strövarnas klor på Hunter Rise. Den knyter dem till generationer av förfäder som jagade på samma vidsträckta slätter."},sec={{t="En tradition från slätterna",b="För tauren är jakt varken enbart nöje eller ett sätt att överleva; den betraktas som en av folkets största hedersbetygelser. Den kräver tålamod, insikt i Jordmoderns balans och vördnad för djuren som strövar över de vidsträckta slätterna. Den äldre Skorn Whitecloud, som vilar i Mulgore efter årtionden av spårning genom Kalimdor, känner igen denna rastlöshet hos unga äventyrare. I stället för att låta dem ströva planlöst leder han deras ambition in i ett traditionellt prov på mognad och disciplin."},{t="Grässlätternas jägare",b="För att visa att deras spårningsinstinkter är äkta får aspiranterna i uppgift att fälla slättströvarna i Mulgore. Dessa stora kattdjur är snabba, smygande och listiga rovdjur som lätt smälter in i slätternas höga gräs. Att samla in fyra uppsättningar klor visar att en spirande vandrare kan upptäcka ett rovdjur innan hen själv blir ett byte och vända jägarens egen vildhet mot den."},{t="Framme vid Hunter Rise",b="När troféerna är säkrade klättrar den invigde uppför de höga trätornen och broarna som leder till Thunder Bluff. Där, på Hunter Rise, tar Melor Stonehoof emot klorna. Som mästerspåraren som värdesätter Skorn Whiteclouds uråldriga visdom godtar Stonehoof gåvan som bevis på att den invigde har rätt sinnelag för att vägledas vidare längs Kalimdors rovdjursstigar."}},faq={{q="Vem erbjuder uppgiften att följa The Hunter's Way?",a="Uppgiften erbjuds av Skorn Whitecloud, en vördnadsvärd tauren som vandrat över slätterna och nu vilar i Mulgore. Han vägleder unga äventyrare som vill bemästra vildmarken.",al={"uppdragsgivare","vem ger uppdraget","skorn whitecloud"}},{q="Var ska jag lämna in slättströvarnas klor?",a="Lämna klorna till Melor Stonehoof, som håller till på Hunter Rise i taurenhuvudstaden Thunder Bluff.",al={"var finns melor stonehoof","var lämnar man in uppdraget","hunter rise"}},{q="Varför är slättströvarnas klor den valda tributgåvan?",a="Slättströvare är smygande och farliga toppredatorer på Mulgores grässlätter. Att spåra upp och besegra dem visar att en invigd har den skarpa blicken, det tålamod och den stridsdisciplin som krävs för avancerad jakt.",al={"varför slättströvare","lore om strövarnas klor","vad är strövare"}},{q="Är uppdraget bara för jägarklassen?",a="Nej. Trots namnet erbjuder Skorn Whitecloud detta prövande prov till alla unga Horde-äventyrare som längtar efter att vandra och lära sig slätternas traditioner.",al={"bara jägare?","kan andra klasser göra detta","är det för jägare"}},{q="Vart leder jägarens resa efter samtalet med Melor?",a="När Melor Stonehoof ser din växande talang börjar han leda dig ut mot The Barrens kargare områden. Till slut skickar han dig till erfarna spårare som Sergra Darkthorn.",al={"what comes next","nästa uppdrag","vart efter melor"}},{q="Vilken betydelse har jakten i taurenkulturen?",a="Enligt tauren är jakt en av de största hedersbetygelserna. Den kräver att man lever i direkt harmoni med Jordmoderns skapelse, bara tar det man behöver och visar djup respekt för bytet som försörjer stammarna.",al={"taurenjaktens historia","jaktens heder bland tauren","varför är jakt viktig för tauren"}}},fx={["1c4e016d"]={q="Varför vill Skorn Whitecloud att det här ska göras?",a="Skorn Whitecloud är en äldre jägare vars egna kringströvande dagar är förbi, men hans själ brinner fortfarande starkt. När han ser din rastlöshet och upptäckarlust vill han styra din ambition mot jaktens hedervärda traditioner. Genom att pröva din förmåga och hänvisa dig till Melor Stonehoof på Hunter's Rise ser Skorn till att taurenfolkets heliga jakttradition förs vidare till en lovande ny generation.",al={"varför ger skorn uppdraget","skorn whiteclouds motiv","varför skicka mig till melor"}},["837cf763"]={q="Vad är Flatland Prowler Claw till för?",a="Klorna är ett obestridligt bevis på din spårningsskicklighet, list och stridsvilja. Flatland prowlers är vilda och svårfångade rovdjur på Mulgore:s slätter. När du visar upp fyra av deras klor för Melor Stonehoof bevisar du att du både har tålamod att jaga farligt villebråd och styrka nog att besegra det. Därmed visar du mästarna på Hunter's Rise att du förtjänar vidare träning.",al={"flatland prowler claws syfte","varför samla klor","hyllning med prowler claws"}},d784e285={q="Vad är flatland prowlers och var finns de?",a="Flatland prowlers är stora rovkatter som hör hemma på Mulgore:s öppna gräsmarker. De strövar över slätterna och smyger sig på villebråd. Med smygande steg, snabbhet och rakbladsvassa klor fäller de sina byten. Tack vare sin naturliga list och styrka anses de vara idealiskt villebråd för att pröva om en blivande jägare behärskar grundläggande färdigheter för att spåra och fälla vilda bestar.",al={"flatland prowlers","prowlers i mulgore","vad är prowlers"}},["3cad1e98"]={q="Varför skickar Skorn Whitecloud dig i stället för att själv jaga prowlers?",a="Skorn har jagat över hela Mulgore i många år, men hans kropp har åldrats även om hans själ förblivit skarp. Än viktigare är att uppgiften inte bara handlar om att samla förnödenheter till lägret; det är en övergångsrit för dig. Skorn ser din ungdomliga upptäckarlust och prövar din beslutsamhet direkt, så att du kan visa att du förtjänar Melor Stonehoofs vägledning.",al={"varför jagar inte skorn","varför jag, skorn whitecloud","varför måste jag hämta klorna"}}},fp="16,232,25.357.0,30.265.0,20.305.0,45.116.0,43.87.0,53.181.0,50.121.0,61.158.1,54.193.0"}
P.entries["quest:862"] = {n="Dig Rat Stew",s="Grub väntar hungrig öster om The Crossroads på en gryta med Dig Rat-gryta. Han skickar resenärer till Bael Modan i södra The Barrens för att hämta Dig Rats till sitt recept.",h="Grub väntar hungrig öster om The Crossroads på en gryta med Dig Rat-gryta.",kw={"bael modan","the barrens","matlagning","crossroads","dig rat stew","dvärgar","grub","råttor"},ang={["faction:Horde"]="Att ta Dig Rats från Bael Modan ger ett sätt att håna dvärgarnas utgrävning samtidigt som man samlar proviant i södra The Barrens.",["profession:Cooking"]="Att tillaga Dig Rat-gryta lär ut hur man samlar mat i gränslandet: skadedjur blir en mättande, illaluktande lägereldsmåltid.",["race:Undead"]="Grub låter gärna kött ruttna i veckor innan han kokar det, en smak som få levande kockar delar med de Fördömda."},sec={{t="Delikatesser från The Barrens",b="Över de torra The Barrens fäller jägare zhevras, plainstriders och raptors. Grub, en orch som slagit läger öster om The Crossroads, längtar efter något annat: Dig Rats. Han säger att han är hungrig hela dagen och erbjuder sig att dela sitt recept med alla resenärer som vill fånga de grävande gnagarna."},{t="Dvärgarnas skadedjur",b="Bael Modan ligger djupt inne i södra The Barrens, där dvärgiska prospektörer gräver i den röda jorden. Deras arbete har stört bon med Dig Rats. Dvärgarna ser de små gnagarna som skadedjur, medan Grub ser en festmåltid nära utgrävningen."},{t="En fråga om smak",b="Grub säger att Dig Rats smakar bäst efter att ha ruttnat i flera veckor. För en hungrig resenär som vill ha mat nu godtar han färskare kött. Hans recept visar hur förlåtande matlagning längs vägen kan vara vid Kalimdors gränsland."}},faq={{q="Vem är Grub?",a="Grub är en orch som slagit läger längs stigen öster om The Crossroads i The Barrens. Han är alltid hungrig, har en märklig smak och lär resenärer att tillaga lokala skadedjur.",al={"grub","vem är grub","orc öster om crossroads"}},{q="Var kommer dig rats ifrån?",a="Dig Rats hemsöker Bael Modan, en alliansutgrävning längst i södra The Barrens, söder om Camp Taurajo och norr om Razorfen Kraul. Dvärgarnas gruvdrift störde marken och drev upp svärmar av de små varelserna.",al={"var finns dig rats","dig rat plats","hitta dig rats"}},{q="Varför vill Grub ha just dig rats?",a="Grub kallar Dig Rats allas favoritfestmåltid och säger att jakt på skadedjur är en övergångsrit för erfarna resenärer. De är huvudingrediensen i hans mättande, starkt luktande gryta.",al={"varför råttor","varför dig rats","grubs motiv"}},{q="Smakar Dig Rat Stew verkligen gott?",a="Grub kallar den läcker, men hans smak är extrem. Han föredrar köttet efter att det har ruttnat i några veckor, vilket gör grytan till en förvärvad smak även med Hordens robusta mått mätt.",al={"smakar grytan gott","äta dig rats","smaken på grubs recept"}},{q="Varför finns det dvärgar i Bael Modan?",a="Dvärgarna i Bael Modan tillhör en expedition från Ironforge. De byggde ett fäste och en utgrävning i södra The Barrens och sprängde och grävde djupt i marken. Deras närvaro har ökat spänningarna med Horden och rört upp traktens skadedjur.",al={"dvärgar i the barrens","varför bael modan","alliansen i södra the barrens"}},{q="Behöver man särskilda matlagningskunskaper för att laga grytan?",a="Grubs metod kräver grundläggande härdmatlagning och fältstyckning. Alla med grundläggande erfarenhet av matlagning kan lära sig att sjuda gnagarna till en mättande måltid.",al={"krav på matlagning","behöver jag matlagningsfärdighet"}}},fx={["76cb3c44"]={q="Vad används Dig Rat till?",a="Dig rats är huvudingrediensen i Grubs smakrika anrättning. De flesta rynkar på näsan åt skadedjur, men Grub ser dem som förstklassig mat och kokar ner dem till en tjock gryta. I hemlighet föredrar han att låta dem ruttna i några veckor så att deras mustiga, starka smak utvecklas, men han lagar gärna till färska fångster direkt åt hungriga vandrare i det torra The Barrens.",al={"vad dig rat används till","vad är dig rat till för","varför samla dig rats"}}},fp="12,150,18.249.0,18.202.0,18.208.0,12.159.0,28.209.0,41.172.0,37.168.0,36.239.0,55.160.0"}
P.entries["quest:863"] = {n="The Escape",s="Du hjälper Wizzlecrank att fly från Venture Companys borrplats i The Sludge Fen i norra The Barrens. Instängd i en stulen prototyphuggare behöver goblinpiloten skydd mot företagets legosoldater medan han tar sig upp ur industrigropen. Därefter rapporterar du till hans kontakt, Sputtervalve, i Ratchet.",h="Du hjälper Wizzlecrank att fly från Venture Companys borrplats i The Sludge Fen i norra The Barrens.",kw={"the barrens","eskort","antändning","prototyp","ratchet","skärmaskin","the sludge fen","sputtervalve","venture company","wizzlecrank"},ang={["faction:Horde"]="Som medlem i Horde kan du uppskatta störningarna i Venture Companys förorenande oljeverksamhet i The Sludge Fen, en skamfläck i The Barrens.",["profession:Engineering"]="Prototyphuggaren visar Venture Companys pneumatik och konstruktioner för förarhytten, vilket ger ingenjörer värdefulla insikter att studera bland bärgningsfynden.",["race:Gnome"]="Som gnom kanske du känner igen Wizzlecranks vilja att styra en oberäknelig maskin på ren gissning. Goblinuppfinnare, liksom gnomiska, skruvar ofta först och ställer frågor sedan."},sec={{t="En klumpig flykt",b="Wizzlecrank kämpar för att kontrollera den stulna huggaren i The Sludge Fen. Han har startat prototypen djupt inne på Venture Companys borrplats, men kan föga om dess spakar och reglage. Den tunga maskinen rycker fram över det leriga stenbrottsgolvet, och dess oberäkneliga körning och dånande leder uppmärksammar arbetare och beväpnade vakter i närheten. En smygande flykt blir till en strid på flykt uppför utgrävningsgropens västra ramp."},{t="Venture Company förföljer",b="Venture Company skickar legosoldater för att stoppa den stulna prototypen. När maskinen klöser sig uppför sluttningen mot öppen mark rör sig grupper för att genskjuta och oskadliggöra den. Huggaren slår tillbaka, men kan inte stå emot deras sabotage utan ditt skydd. Den tar sig över kanten och stapplar bort från den stora borrgropen, men snart drabbas maskinen av ett kritiskt fel."},{t="Bärgning och belöning",b="Wizzlecrank överlever flykten från den kraschade prototyphuggaren. När den omedelbara faran är över går maskinen sönder och kollapsar på savannens gräsmark. Wizzlecrank kravlar ut och säger åt dig att rapportera till Sputtervalve i Ratchet, medan han stannar vid vraket. Sputtervalve är ivrig att studera Venture Companys konstruktioner innan tillfället går honom ur händerna och skickar genast en goblinbärgningsgrupp för att frakta de intakta mekanismerna tillbaka till hamnen."}},faq={{q="Vem är Wizzlecrank och varför sitter han i en skärmaskin?",a="Wizzlecrank är en agent och mekaniker som arbetar med Sputtervalve i Ratchet. Han tog sig in på Venture Companys norra borrplats för att stjäla företagets senaste experimentella prototyphuggare, men blev sedan instängd medan han försökte lära sig de okända reglagen i förarhytten.",al={"vem är wizzlecrank","varför sitter en goblin i en skärmaskin","wizzlecranks skärmaskin"}},{q="Var äger flykten rum?",a="Flyktförsöket börjar djupt inne i The Sludge Fen, en förorenad industriell borrplats som drivs av Venture Company i norra The Barrens, strax norr om den torra savannbassängen.",al={"var finns uppdraget the escape","the escapes plats","eskort vid the sludge fen"}},{q="Måste du eskortera skärmaskinen hela vägen till Ratchet?",a="Nej. Du eskorterar Wizzlecrank ut ur borrgropen och uppför den västra rampen. När ni kommit över stenbrottskanten går maskinen sönder, och Wizzlecrank säger åt dig att ta dig till Ratchet och rapportera på egen hand.",al={"hur långt ska jag gå","eskortväg","ska man ta sig till ratchet"}},{q="Vem är Sputtervalve?",a="Sputtervalve är en goblintekniker som håller till nära Ratchets hamn. Han samlar in industriell underrättelse om rivalen Venture Company och vill åt dess mekaniska konstruktioner för att tjäna på företagets tekniska framsteg.",al={"vem är sputtervalve","lämna in till npc sputtervalve","sputtervalves historia"}},{q="Varför välter skärmaskinen i slutet?",a="Wizzlecrank kan knappt reglagen, och den experimentella maskinen pressas till bristningsgränsen i bakhållet. Den utsätts för svår mekanisk påfrestning när den bryter sig genom avspärrningen och ger sedan upp så fort den lämnar borrplatsen.",al={"varför går skärmaskinen sönder","skärmaskinsvrak","prototypfel"}},{q="Vad händer efter att prototypen kraschar?",a="Wizzlecrank stannar vid den havererade maskinen medan du rapporterar till Sputtervalve i Ratchet. Sputtervalve förbereder genast ett goblinbärgningsteam som ska ta vara på prototypens värdefulla delar innan Venture Company kan återta dem.",al={"bärgningsteam","vad händer sedan","uppdraget the escape avslutning"}}},fx={["07b3d38e"]={q="Varför måste Wizzlecrank fly från The Sludge Fen?",a="Wizzlecrank stal en experimentell prototypskördare mitt framför näsan på Venture Company. Han är fast djupt inne på fientligt territorium vid borrplatsen och måste styra den obekanta, klumpiga krigsmaskinen genom ringar av ilskna legosoldater och arbetare för att överleva och överlämna den stulna tekniken till sin partner i Ratchet.",al={"varför fly från the sludge fen","wizzlecranks motiv","varför fly från venture company"}},fce70664={q="Varför förlitar sig Wizzlecrank på att du ska eskortera honom ut?",a="Att styra den stulna prototypen kräver all Wizzlecranks koncentration. Han vet knappt vilka spakar och knappar som får den att röra sig, än mindre hur man strider effektivt. Omgiven av fientliga Venture Company-styrkor och oförmögen att försvara sig medan han styr den tröga maskinen ut från borrplatsen, förlitar han sig helt på ditt svärd och din magi för att hålla angriparna på avstånd.",al={"varför behöver wizzlecrank mig","varför kan wizzlecrank inte fly ensam","varför en äventyrare"}}},fp="10,269,16.406.0,23.354.0,18.429.1,51.252.0,34.158.0,58.198.1,20.215.0,43.226.1,41.234.1"}
P.entries["quest:8642"] = {n="Silvervein the Elder",s="Silvervein the Elder är en vördad förfädersande som visar sig under Lunar Festival på kullarna med utsikt över Thelsamar i Loch Modan. Resande visar honom sin respekt för att hedra de urgamla banden mellan Azeroths äldre folk. Som tack för att de erkänner hans närvaro och arv skänker han sin förfäders välsignelse.",h="Silvervein the Elder är en vördad förfädersande som visar sig under Lunar Festival på kullarna med utsikt...",kw={"förfader","coin of ancestry","äldste","loch modan","lunar festival","silvervein","thelsamar"},ang={["faction:Alliance"]="För Alliance-resande som färdas genom Loch Modan erbjuder höjden ovanför Thelsamar en stilla paus från troggjakten, där de kan hedra de forntida döda.",["race:Dwarf"]="Elder Silvervein vilar alldeles intill dvärgbosättningen Thelsamar och delar ett uppskattande band med det härdade stenfolket och deras vördnad för forntida historia."},sec={{t="En väktare över Thelsamar",b="Elder Silvervein står på de böljande höjderna ovanför Thelsamar som en stillsam väktare och påminnelse om forna tider. Som en gestalt som hedras under Lunar Festival står han för minnena från svunna epoker, som lever vidare. Medan länderna kring Loch Modan brottas med trogginvasioner och lokala tvister vakar Silvervein fridfullt från sin utsiktsplats."},{t="Att hedra de forntida folken",b="Andar som Silvervein överbryggar klyftan mellan dagens folk och forntida släkten. När äventyrare söker upp honom uttrycker han sin tacksamhet över att resande fortfarande hedrar Azeroths forntida folk. Hans hälsning bär på förfädernas varma uppskattning, och han ger en minnesgåva till dem som hedrar honom."}},faq={{q="Vem är Elder Silvervein?",a="Elder Silvervein är en förfädersande som visar sig under Lunar Festival. Under festivalen vilar han på de höga klipporna nära Thelsamar i Loch Modan.",al={"silvervein","vem är silvervein","elder silvervein loch modan"}},{q="Var hittar jag Elder Silvervein?",a="Han finns på en gräsbevuxen kulle med utsikt över staden Thelsamar i Loch Modan.",al={"silverveins plats","var finns elder silvervein","hitta silvervein"}},{q="Varför söker man upp Elder Silvervein?",a="Under Lunar Festival söker äventyrare upp honom för att visa förfäderna och de forntida folken sin respekt. I gengäld får de en festgåva och en välsignelse.",al={"varför besöka silvervein","vad gör silvervein","silverveins syfte"}},{q="Vad menar han med ”de forntida folken”?",a="Han syftar på de forntida folken i Azeroth, som levde och formade världen långt innan dagens konflikter hamnade i centrum. Han hedrar den bestående andan i deras arv.",al={"forntida folk betydelse","varför forntida folk"}},{q="Är Elder Silvervein vänligt inställd till Horde-resande?",a="Ja. Förfädersäldste som hedras under Lunar Festival välkomnar resande av alla ursprung som kommer i fred för att hedra förfäderna.",al={"kan horde tala med silvervein","horde silvervein"}},{q="Har Elder Silvervein någon koppling till trogginvasionen?",a="Nej. Loch Modan plågas av troggangrepp och problem med utgrävare, men Elder Silvervein står helt utanför de lokala militära konflikterna och ägnar sig enbart åt vördnad för förfäderna.",al={"silvervein trogger","strider silvervein mot trogger"}}},fp="20,217,22.210.0,24.167.0,24.146.0,34.70.0,52.151.0,39.151.0,48.122.0,64.161.0"}
P.entries["quest:8646"] = {n="Hammershout the Elder",s="Under Lunar Festival visar sig Hammershout the Elder i Stormwinds Park. Resande hedrar de gamla folken och får en ceremoniell gåva av honom.",h="Under Lunar Festival visar sig Hammershout the Elder i Stormwinds Park.",kw={"förfader","hammershout the elder","parken","hammershout","lunar festival","gamla folk","stormwind"},ang={["faction:Alliance"]="När du besöker Stormwinds Park påminner Hammershout the Elder om vördnad, fred och världens gemensamma förfädersarv.",["faction:Horde"]="För att nå Hammershout the Elder måste du ta dig in i Stormwind och bege dig till Park, en djärv resa för en pilgrim från Horde.",["race:Human"]="I Stormwinds Park påminner Hammershout the Elder dig om att respektera Azeroths historia, som sträcker sig tillbaka till tiden före det moderna människoriket."},sec={{t="Att hedra forntida folk",b="Under Lunar Festival visar sig vördnadsvärda förfädersandar runtom i Azeroth med visdom och välsignelser för resande som visar dem sin respekt. Hammershout the Elder visar sig i Stormwinds Park-distrikt. Hans närvaro nära den mänskliga civilisationens hjärta påminner om de forntida folken som vandrade på denna jord innan dagens kungariken uppstod."},{t="Förfäders vördnadsgåvor",b="Hammershout the Elder kräver ingen prövning eller ed, bara ett erkännande av det förflutna. Han känner lättnad och tacksamhet över att människor fortfarande hedrar de gamla folken. I gengäld ger han resande en ceremoniell gåva, ett tecken på bandet mellan de levande och andarna som kom före dem."}},faq={{q="Vem är Hammershout the Elder?",a="Hammershout the Elder är en förfädersande som visar sig under Lunar Festival. Han representerar Azeroths forntida släktlinjer och erbjuder välsignelser och gåvor i Stormwind till dem som hedrar honom.",al={"hammershout","vem är hammershout","hammershouts identitet"}},{q="Var finns Hammershout the Elder?",a="Hammershout the Elder visar sig i Stormwinds Park-distrikt under Lunar Festival.",al={"hammershouts plats","var finns hammershout","hammershout elwynn"}},{q="Varför nämner Hammershout the Elder ”de gamla folken”?",a="Hans ord speglar Lunar Festivals hyllning till forntiden och förfädersdyrkan. Festivalen hedrar de forntida folken och traditionerna som formade Azeroth innan dagens bosättningar uppstod.",al={"betydelsen av gamla folk","vad betyder hammershout"}},{q="Vilken gåva erbjuder Hammershout the Elder?",a="Hammershout the Elder erbjuder en Coin of Ancestry, en ceremoniell gåva från Lunar Festivals andar till resande som söker upp äldste och visar dem sin respekt.",al={"hammershouts belöning","hammershouts gåva","vad ger han"}},{q="Kan Horde-äventyrare tala med Hammershout the Elder?",a="Ja. Resande från Horde kan tala med Hammershout the Elder, men de måste vara försiktiga i Stormwind, Alliances huvudstad.",al={"kan horde tala med hammershout","hammershout horde"}},{q="Är mötet kopplat till en pågående högtid?",a="Hammershout the Elder visar sig under den årliga Lunar Festival och skänker välsignelser innan han åter försvinner till andevärlden.",al={"är hammershout alltid där","äldste under lunar festival"}}},fp="21,126,22.248.0,29.224.0,25.199.0,37.91.0,53.165.0,40.156.0,51.100.0,44.121.0"}
P.entries["quest:8648"] = {n="Darkcore the Elder",s="Darkcore the Elder är ett säsongsuppdrag under Lunar Festival i Undercity. Genom att söka upp Elder Darkcore hyllar resenärer de uråldriga andar som vördas i Azeroth och får en Coin of Ancestry i gengäld.",h="Darkcore the Elder är ett säsongsuppdrag under Lunar Festival i Undercity.",kw={"förfader","coin of ancestry","darkcore the elder","elder darkcore","äldste","lunar festival","undercity"},ang={["faction:Horde"]="Elder Darkcore låter medlemmar i Horde delta i Lunar Festivals ceremonier över hela kontinenten, mitt i en allierad huvudstads trygghet.",["race:Undead"]="För Forsaken som vandrar bland ruinerna av sitt forna kungarike är Elder Darkcore en kuslig påminnelse om tiden före Scourge och Lordaerons fall."},sec={{t="En ande i Undercity",b="Under Lunar Festival visar sig uråldriga nattalviska och jordbundna förfäders andar på kontinenterna för att dela med sig av sin visdom och sina välsignelser. Elder Darkcore vistas i Undercitys dunkla salar, där han bevittnar den moderna världen och hedrar minnet av dem som söker världens rötter."},{t="Att hedra förfäderna",b="När du närmar dig Elder Darkcore följer du en uråldrig sed att visa respekt för de vördnadsvärda döda och Azeroths tidlösa väktare. Som erkänsla för denna pilgrimsfärd ger anden resenärer en Coin of Ancestry, en symbol för välvilja och bestående minnen."}},faq={{q="Varför besöker man Elder Darkcore?",a="När du besöker Elder Darkcore under Lunar Festival kan du hylla Azeroths uråldriga folk. Tala med honom för att slutföra uppdraget och få en Coin of Ancestry.",al={"elder darkcore mål","varför besöka darkcore","darkcore uppdragets syfte"}},{q="Var hittar man Elder Darkcore?",a="Elder Darkcore visar sig i Lordaerons förstörda tronrum, ovanför Forsakens huvudstad Undercity.",al={"elder darkcore plats","var finns elder darkcore","darkcore plats i undercity"}},{q="Vad är Lunar Festival?",a="Lunar Festival är en årlig högtid för hågkomst och förnyelse som firas i hela Azeroth. Den uppmärksammar segern över Burning Legion och vördar forntida äldste som vägledde de dödligas folk.",al={"lunar festival berättelse","varför visar sig de äldste","vad är de äldste"}},{q="Vad står de äldste för?",a="De äldste är uråldriga andar, oftast knutna till nattalver eller tidiga jordbundna kulturer. De visar sig under Lunar Festival för att välsigna dem som minns deras gärningar och för vidare forntidens lärdomar.",al={"vilka är de äldste","lunar festival de äldste berättelse","förfäders andar"}},{q="Kan äventyrare från Alliance tala med Elder Darkcore?",a="Elder Darkcore hälsar på alla resenärer som lyckas ta sig fram till honom, men spelare i Alliance måste trotsa Forsakens hårt försvarade huvudstad för att nå dit.",al={"alliance darkcore","kan alliance nå darkcore","elder darkcore alliance"}},{q="Vad är en Coin of Ancestry?",a="En Coin of Ancestry är ett festligt tecken som de äldste skänker under Lunar Festival. Den symboliserar vördnad för forntiden och kan bytas mot festkläder och säsongsbetonade minnessaker.",al={"vad är ancestry coins","coin of ancestry användning","lunar festival mynt"}}},fp="18,158,25.298.0,22.242.0,47.127.0,34.102.0,27.180.0,29.195.0,49.138.0,27.166.0"}
P.entries["quest:8649"] = {n="Stormbrow the Elder",s="Nära Goldshire väntar Stormbrow the Elder vid vattnet under Lunar Festival. Resande hedrar forntida traditioner och Azeroths gamla folk och får en minnesgåva i gengäld.",h="Nära Goldshire väntar Stormbrow the Elder vid vattnet under Lunar Festival.",kw={"förfader","elder stormbrow","elwynn forest","smedja","goldshire","lunar festival","gåva"},ang={["faction:Alliance"]="Som Alliance-resande på genomresa i Goldshire hittar du Stormbrow the Elder mitt i Elwynn Forest, bland de mest lättillgängliga förfädersandarna för unga äventyrare.",["race:Human"]="Som människa bosatt i Elwynn kan du se Stormbrow the Elder som en påminnelse om forntida historia bortom Stormwinds murar och dess senaste krig."},sec={{t="En ande i Goldshire",b="En stilla damm ligger strax bakom smedjan i Goldshire, där Stormbrow the Elder visar sig. Vakterna, hantverkarna och trötta resande passerar genom staden på väg in i skogen. Under Elwynn Forests trädkronor välkomnar den ärade anden alla som kommer för att hedra rikets långa historia."},{t="Att hedra de gamla folken",b="Under Lunar Festival återvänder mäktiga förfäders andar för att vandra bland de levande. Stormbrow the Elder prisar resande som minns dem som kom före. För att hedra de äldre folkens visdom och arv ger han en välsignelse och ett minnesmynt för högtiden."}},faq={{q="Var hittar jag Elder Stormbrow?",a="Du hittar Stormbrow the Elder vid dammen strax bakom smedjan i Goldshire, i Elwynn Forest.",al={"stormbrow plats","var finns elder stormbrow","äldste i goldshire"}},{q="Vem är Elder Stormbrow?",a="Stormbrow the Elder är en förfädersande som visar sig under Lunar Festival och representerar de vördnadsvärda äldste bland Azeroths gamla folk.",al={"vem är stormbrow","stormbrows bakgrund","elder stormbrows identitet"}},{q="Varför besöker man Elder Stormbrow?",a="Resande besöker Stormbrow the Elder för att hedra forntida förfäder under högtiden. Han hälsar dem och ger en uppskattningsgåva i gengäld.",al={"varför besöka stormbrow","elder stormbrow uppdrag","stormbrow the elders syfte"}},{q="Kan Horde-spelare tala med Elder Stormbrow?",a="Lunar Festivals äldste hedrar alla som söker upp dem i fred, men Goldshire är hårt bevakat Alliance-territorium, vilket gör besöket farligt för resande från Horde.",al={"horde stormbrow","kan horde besöka stormbrow"}},{q="Vilken gåva erbjuder den äldste?",a="Stormbrow the Elder erbjuder ett Coin of Ancestry, en traditionell gåva som visar respekt och hågkomst och som delas ut av de äldste under hela högtiden.",al={"stormbrows belöning","vilken gåva","lunar festival-mynt stormbrow"}},{q="Varför nämner Stormbrow de ”gamla folken”?",a="Stormbrow prisar resande för att de minns att dagens civilisationer lever i länder som formats av forntida folk och bestående seder, långt innan de moderna kungarikena uppstod.",al={"gamla folkens betydelse","varför gamla folk","stormbrows dialog"}}},fp="19,182,21.239.0,24.262.0,33.104.0,23.150.0,48.150.0,43.152.0,32.135.0,45.191.0"}
P.entries["quest:865"] = {n="Raptor Horns",s="I Ratchet vill Mebok Mizzyrix ha hela rovfågelhorn till en egen plan. Goblinen tror att The Barrens rovfåglars list sitter i hornen och anlitar resenärer för att jaga Sunscale Scytheclaws.",h="I Ratchet vill Mebok Mizzyrix ha hela rovfågelhorn till en egen plan.",kw={"the barrens","intact raptor horn","mebok mizzyrix","rovraptorhorn","ratchet","smart drinks","steamwheedle cartel","sunscale scytheclaw"},ang={["class:Hunter"]="Som jägare med god kännedom om Kalimdors rovfågelflockar känner du till deras dödliga list. Meboks tro att deras klokhet kan tappas på flaska är goblinsk kvacksalveri.",["faction:Alliance"]="Som Alliance-äventyrare kan du hitta en neutral utpost i det Horde-dominerade The Barrens vid Ratchet. Ströjobb som Meboks ger dig en chans att tjäna mynt och Steamwheedle Cartels välvilja."},sec={{t="Gobliners företagsamhet",b="Mebok Mizzyrix söker lyckan i Ratchet, där gobliner jagar den ena planen efter den andra. Han har sett hur rovfåglarna i The Barrens agerar med ovanlig skicklighet och samordning jämfört med bestar på andra håll. Mebok drog slutsatsen att deras intelligens måste finnas i hornen. Han har ingen formell undersökning i åtanke; han vill tjäna pengar på idén."},{t="Sunscale Scytheclaws",b="Mebok vill ha oskadade horn från Sunscale Scytheclaws, bland de farligaste rovdjuren i The Barrens. De strövar omkring i de södra delarna av The Barrens och vid de norra gränserna nära Ashenvale. Rovfåglarna jagar i flock och försvarar sitt revir häftigt, så det krävs stor stridsvana för att fälla en och ta hornen hela."},{t="Ett recept på rikedom",b="Mebok tänker mala de hela hornen till fint pulver och brygga drycker av det. Han kallar brygderna ”smartdrycker” och hoppas sälja dem till kunder som gärna köper klokhet på flaska. Mebok är övertygad om att planen kommer att göra honom rik över en natt."}},faq={{q="Varför vill Mebok Mizzyrix ha rovraptorhorn?",a="Mebok tror att The Barrens rovfåglars list finns lagrad i deras horn. Han tänker mala dem till pulver, brygga ”smartdrycker” och sälja dem med vinst.",al={"varför rovraptorhorn","meboks mål","vad vill mebok"}},{q="Var finns Sunscale Scytheclaws?",a="Sunscale Scytheclaws strövar omkring i de södra delarna av The Barrens och i de norra trakterna nära gränsen till Ashenvale.",al={"var finns scytheclaws","sunscale scytheclaws plats","plats för rovraptorhorn"}},{q="Är rovraptorhorn verkligen magiska eller intelligenshöjande?",a="Meboks påstående att rovfågelhorn innehåller deras klokhet är goblinsk pseudovetenskap driven av vinstintresse. Rovfåglarna i The Barrens är listiga, men texten ger inget stöd för att kalla hornen magiska eller intelligenshöjande.",al={"fungerar smart drinks","är rovraptorer smarta","rovraptorers intelligens i historien"}},{q="Vem är Mebok Mizzyrix?",a="Mebok Mizzyrix är en ambitiös goblinhandlare i hamnstaden Ratchet. Han jagar tvivelaktiga planer och brygder för att göra sig en förmögenhet på resenärer som passerar.",al={"vem är mebok","mebok mizzyrix historia","mebok ratchet"}},{q="Vad händer när hornen har samlats in?",a="Mebok tänker mala de hela hornen till pulver och brygga drycker som han kallar ”smartdrycker”.",al={"nästa uppdrag efter raptor horns","smart drinks-uppdraget","kedjan med rovraptorhorn"}},{q="Kan alliansspelare hjälpa Mebok med uppgiften?",a="Ja. Ratchet är en öppen hamn som sköts av Steamwheedle Cartel, och Mebok är en neutral goblin som gör affärer med både Horde och Alliance.",al={"är uppdraget bara för horde","rovraptorhorn för alliance","kan alliance göra raptor horns"}}},fx={["3bee14c6"]={q="Vad är Intact Raptor Horn till för?",a="Mebok Mizzyrix tänker mala ner de hela hornen till fint pulver och blanda det med vin. Han är övertygad om att The Barrens raptors lagrar sin intelligens direkt i hornen. Han tänker buteljera och sälja blandningen som en intelligenshöjande dryck kallad \"smart drink\" och hoppas tjäna en rejäl slant på godtrogna köpare.",al={"intact raptor horn användning","varför hela raptorhorn","raptorhornens syfte"}},["5cf02a79"]={q="Vad är Sunscale Scytheclaws och varför jagar man dem?",a="Sunscale scytheclaws är aggressiva och listiga raptors som hör hemma i The Barrens torra vidder. De strövar både i söder och på de norra slätterna nära gränsen till Ashenvale. De är ovanligt samspelta och våldsamma jämfört med andra vilda bestar, och deras skärpa gör dem till Meboks främsta mål för att utvinna intelligenshöjande hornpulver.",al={"sunscale scytheclaws","varför sunscale raptors","sunscale scytheclaws bakgrund"}},["57350450"]={q="Varför anlitar Mebok Mizzyrix dig i stället för att själv jaga raptors?",a="Mebok är en ambitiös goblinföretagare, inte en erfaren spårare eller storviltsjägare. Att ge sig ut på The Barrens hårda slätter och möta dödliga bestar med rakbladsvassa klor är alldeles för riskabelt när han kan betala en äventyrare för att trotsa vildmarken och hämta fina exemplar. Själv kan han hålla händerna rena och blanda sin produkt i trygghet.",al={"varför jag, mebok","varför behöver mebok mig","varför anlita en äventyrare"}}},fp="12,192,23.321.0,24.322.0,19.230.1,42.158.0,39.100.0,52.187.0,22.166.0,40.104.1,47.146.0"}
P.entries["quest:8652"] = {n="Graveborn the Elder",s="Graveborn the Elder är ett möte under Lunar Festival, nära staden Brill i Tirisfal Glades. Under firandet söker resenärer upp Elder Graveborn bland de fördärvade dungarna för att hedra Azeroths forntida förfäder. Om du visar anden din vördnad får du hans välsignelse och en högtidsgåva.",h="Graveborn the Elder är ett möte under Lunar Festival, nära staden Brill i Tirisfal Glades.",kw={"brill","coin of ancestry","elder graveborn","graveborn","lunar festival","tirisfal glades"},ang={["class:Druid"]="Druider vördar Lunar Festivals äldste som förbindelser till den forntida världen före Sundering, utan hänsyn till de oroliga fraktionsgränser de vistas inom.",["faction:Alliance"]="Äventyrare från Alliance som söker upp Elder Graveborn måste ta sig försiktigt genom Tirisfal Glades, eftersom Brill är ett välbefäst fäste för Forsaken.",["race:Undead"]="För Forsaken som bor i Brill är de forntida förfädernas ankomst en skarp påminnelse om Azeroths djupare historia, bortom Scourges senaste tragedier."},sec={{t="En andevakt i Brill",b="Forsaken bor bland ruinerade herrgårdar och gravplatser i Tirisfal Glades, men Lunar Festival ger en oväntad kontakt med forntiden. Elder Graveborn visar sig som en spektral äldste strax utanför Brill. Även i ett land som härjats av Scourge och återtagits av de odöda välkomnar han pilgrimer som stannar till för att hedra de gamla sederna."},{t="Hedra de gamla folken",b="Lunar Festival är en tid då de mäktiga andarna från svunna tider återvänder för att erbjuda visdom och tacksamhet. När resenärer närmar sig Elder Graveborn säger han att det gläder honom att invånarna i Tirisfal fortfarande hyllar sina förfäder trots landets nuvarande förfall. Han ger en Coin of Ancestry till dem som hälsar på honom."}},faq={{q="Var finns Elder Graveborn?",a="Elder Graveborn finns nära bosättningen Brill i Tirisfal Glades. Han står tyst vid vägkanten utanför staden.",al={"elder graveborns plats","var finns graveborn","graveborns koordinater"}},{q="Vad händer när du talar med Elder Graveborn?",a="När du hälsar på honom berömmer Elder Graveborn dig för att hedra Azeroths forntida folk och ger dig en Coin of Ancestry som en del av firandet under Lunar Festival.",al={"graveborns belöning","graveborn under lunar festival","vad ger han dig"}},{q="Varför står en forntida äldste i Tirisfal Glades?",a="Under Lunar Festival visar sig de forntida förfädernas andar över hela Azeroth, från kaldorei-skogarna till länder som härjats av krig och pest. Elder Graveborn vakar över Lordaerons nordliga områden för att se till att dess historia inte helt överskuggas av döden.",al={"varför är han i tirisfal","graveborns bakgrund","vem är elder graveborn"}},{q="Kan spelare från Alliance besöka Elder Graveborn?",a="Elder Graveborn är själv en neutral visdomsande och talar med medlemmar av både Alliance och Horde. Men eftersom han står precis utanför Forsaken-staden Brill måste äventyrare från Alliance se upp för de lokala vakterna.",al={"kan alliance tala med graveborn","alliance graveborn the elder","är graveborn fientlig"}},{q="Vad används Coin of Ancestry till?",a="Coins of Ancestry från äldste som Graveborn kan bytas mot festkläder, fyrverkerirecept och andra högtidsgåvor i Moonglade under Lunar Festival.",al={"coin of ancestry användning","vad används lunar-mynt till"}},{q="Tillhör Elder Graveborn Forsaken?",a="Nej. Trots sitt namn och sitt spöklika utseende nära Brill är Elder Graveborn en av de forntida andar som firas under Lunar Festival. Han tillhör Azeroths långa led av äldste, inte Sylvanas Forsaken.",al={"är graveborn odöd","tillhör elder graveborn forsaken"}}},fp="19,216,24.295.0,24.274.0,33.71.0,47.144.0,52.231.0,43.192.0,38.177.0,39.205.0"}
P.entries["quest:8653"] = {n="Goldwell the Elder",s="Goldwell the Elder är ett uppdrag under Lunar Festival som ges av Elder Goldwell i Kharanos, Dun Morogh. Att hedra honom speglar den långvariga traditionen att söka upp förfädernas andar i dvärgarnas snötäckta land. Som tack för din vördnad ger han dig en symbol för förfädernas välsignelse.",h="Goldwell the Elder är ett uppdrag under Lunar Festival som ges av Elder Goldwell i Kharanos, Dun Morogh.",kw={"förfader","coin of ancestry","dun morogh","elder goldwell","goldwell","ironforge","kharanos","lunar festival","thunderbrew"},ang={["faction:Alliance"]="Goldwell ligger tryggt i Alliance-territorium och är en av de lättaste äldste för unga Alliance-hjältar att besöka på vägen mellan Coldridge Valley och Ironforge.",["faction:Horde"]="För att nå Goldwell måste du smyga djupt in i Dun Morogh och trotsa dvärgarnas vakter och den bitande kylan precis utanför Ironforges höga portar.",["race:Dwarf"]="För dvärgar som återvänder från Ironforge förenar mötet med en äldste av forntida släkt precis utanför Kharanos främsta värdshus tidlös vördnad med stolthet över hembygden."},sec={{t="En hälsning från bergen",b="I den bitande kylan intill Thunderbrew Distillery i Kharanos vakar Elder Goldwell över den livliga handelsvägen som leder till Ironforges portar. Under Lunar Festival välkomnar denna vördnadsvärda gestalt trötta resenärer, äventyrare och lokalbor, och förkroppsligar minnet av forna tider då de första dödliga vandrade under Azeroths stjärnor."},{t="Att hedra förfäderna",b="Ett besök hos Goldwell ger en stund till eftertanke i Dun Moroghs hårda vintervindar. Han uttrycker lättnad och glädje över att dödliga fortfarande minns de forntida folken och deras bedrifter, och tackar alla som gör uppehåll på sin resa för att visa vördnad. Som gengäld ger han en helig Coin of Ancestry som ett tecken på sin välsignelse."}},faq={{q="Var hittar jag Elder Goldwell?",a="Elder Goldwell står precis utanför värdshuset Thunderbrew Distillery i staden Kharanos, vid den snöiga vägen i Dun Morogh, strax sydväst om Ironforges portar.",al={"elder goldwells plats","var finns elder goldwell","goldwells plats"}},{q="Varför ska man söka upp Elder Goldwell?",a="Elder Goldwell besöks under Lunar Festival som en del av att hedra världens forntida andar. Att visa honom vördnad bevisar att de dödliga folken inte har glömt forntidens uppoffringar och visdom.",al={"varför besöka elder goldwell","vad gör elder goldwell","goldwells uppdrag"}},{q="Vilken belöning ger Elder Goldwell?",a="Han belönar resenärer med en Coin of Ancestry, en välsignad symbol som festivalens äldste skänker och som kan lämnas till Cenarion Circle i Moonglade i utbyte mot festliga varor.",al={"elder goldwells belöning","vad får jag av elder goldwell","coin of ancestry goldwell"}},{q="Är uppdraget tillgängligt för resenärer från Horde?",a="Ja. Festivalens äldste, som Goldwell, är neutrala förfädersandar som välkomnar äventyrare från alla fraktioner, men resenärer från Horde måste vara försiktiga och undvika dvärgarnas vaksamma bergsvakter som patrullerar Kharanos.",al={"kan horde prata med elder goldwell","horde elder goldwell","är elder goldwell vänligt inställd till horde"}},{q="Varför bor Elder Goldwell i Dun Morogh?",a="Lunar Festivals äldste visar sig överallt i Azeroth där dödliga civilisationer har skapat varaktiga samhällen. Goldwell valde Kharanos för att dela sina välsignelser med dem som bor nära hjärtat av dvärgarnas rike.",al={"varför är goldwell i kharanos","varför dun morogh","goldwell i dvärgarnas land"}},{q="Kan du slutföra uppdraget mer än en gång?",a="Nej. Vördnaden för Elder Goldwell visas en gång per festivalsäsong, och varje äventyrare som söker hans råd får en enda välsignelse och ett mynt.",al={"kan elder goldwell-uppdraget upprepas","elder goldwell dagligt uppdrag","goldwell återställning"}}},fp="18,181,19.257.0,22.184.0,32.154.0,50.187.0,40.168.0,43.186.0,45.195.0,43.109.0"}
P.entries["quest:86574"] = {n="Stonetalon Supply Run",s="På Stonetalon Peak väntar Innkeeper Faralia på förnödenheter efter att en kurir dödats och försändelsen försvunnit. Pridewing-wyverns kan ha fört bort buntarna.",h="På Stonetalon Peak väntar Innkeeper Faralia på förnödenheter efter att en kurir dödats och försändelsen...",kw={"kurir","innkeeper faralia","försvunnen försändelse","pridewing wyverns","stonetalon supplies","stonetalon supply run"},sec={{t="En försvunnen försändelse",b="En död kurir ligger bredvid en utspridd packning, och en lapp anger Innkeeper Faralia på Stonetalon Peak som mottagare. Du ombeds återta de försvunna Stonetalon Supplies från Pridewing Wyverns. Faralia hoppas att försändelsen kommer snart."},{t="Faralias tack",b="Faralia får veta att kuriren inte överlevde. Hon säger att hon ska använda de återfunna förnödenheterna, så att kurirens död inte blir förgäves."}},faq={{q="Vem skulle få förnödenheterna?",a="Lappen anger Innkeeper Faralia på Stonetalon Peak som mottagare.",al={"vem får förnödenheterna","faralias försändelse"}},{q="Vad hände med kuriren?",a="Kuriren dödades, och kroppen bär spår av många slag från Pridewing-wyverns.",al={"död kurir","vad hände här"}},{q="Vad försvann?",a="En försändelse med förnödenheter avsedd för Innkeeper Faralia saknas i kurirens övergivna packning.",al={"försvunna förnödenheter","vad fanns i packningen"}},{q="Var kan förnödenheterna finnas?",a="Pridewing Wyverns kan ha fört bort buntarna med förnödenheter för att fodra sina bon.",al={"wyvernförnödenheter","var finns buntarna"}},{q="Vad behöver Faralia?",a="Faralia väntar på den försvunna försändelse med förnödenheter som är avsedd för henne på Stonetalon Peak.",al={"vad vill värdshusvärden ha","stonetalon supply run"}}},fp="21,168,15.251.0,16.139.1,25.74.0,29.88.0,18.96.0,28.83.0,23.92.0"}
P.entries["quest:86576"] = {n="Bloodfury Trinkets",s="Mor'rogal ber dig hämta solstenar åt honom från Bloodfury-harpyorna i The Charred Vale. Han säger att de är knutna till himlens ljus.",h="Mor'rogal ber dig hämta solstenar åt honom från Bloodfury-harpyorna i The Charred Vale.",kw={"bloodfury-harpyor","bloodfury trinkets","the charred vale","glittering sunstones","himlens ljus","mor'rogal","helgedomar","solstenar"},sec={{t="Harpyornas stenar",b="Bloodfury-harpyorna samlar på glänsande saker, bland annat guldgula solstenar. Mor'rogal befinner sig uppe på kullarna ovanför dig och har nämnt att han använder dem. Han ber dig ta med alla Glittering Sunstones du hittar till honom."},{t="Ljus i sten",b="Mor'rogal säger att solstenar återspeglar solens prakt. De kan pryda helgedomar och hem med små ljusglimtar. På natten lånar månen dem sin silverskimrande skönhet. För honom påminner de om ett band till himlens ljus."}},faq={{q="Vad samlar Bloodfury-harpyorna på?",a="Bloodfury-harpyorna samlar på glänsande föremål, däribland guldgula solstenar.",al={"harpyor glänsande saker","bloodfury trinkets","vad samlar harpyor på"}},{q="Vem vill ha solstenarna?",a="Mor'rogal, som befinner sig uppe på kullarna ovanför dig, har nämnt att han använder solstenar.",al={"vem behöver solstenar","mor rogal prydnadssaker","solstenarnas givare"}},{q="Vad använder Mor'rogal solstenar till?",a="Mor'rogal säger att solstenar kan pryda helgedomar och hem med små ljusglimtar.",al={"varför vill morrogal ha stenar","solstenars användning","vad är stenarna till för"}},{q="Vad betyder solstenarna för Mor'rogal?",a="Solstenarna påminner Mor'rogal om ett band till himlens ljus.",al={"solstenars betydelse","himlens ljus stenar","varför är stenarna speciella"}}},fp="18,140,15.207.0,14.217.0,42.78.0,24.75.0,38.79.0,40.70.0"}
P.entries["quest:86585"] = {n="Banner of the Fallen",s="Banner of the Fallen berättar den mörka historien om Mountaineer Ylva, en modig dvärg som gav sig in i troggarnas område för att spåra upp försvunna kamrater. Efter att ha stupat i strid och fått sin fana från Ironforge trampad på lockar det fram hennes baneman att möta rättvisan när fanan hissas på nytt.",h="Banner of the Fallen berättar den mörka historien om Mountaineer Ylva, en modig dvärg som gav sig in i...",kw={"banner of the fallen","captain rugelfuss","headsplitter","ironforge-fana","mountaineer ylva","troggar","ylva"},ang={["faction:Alliance"]="Fanan från Ironforge står för dvärgarnas trohet och trots i troggarnas område. Att säkra den hedrar de fallna soldater som håller stånd för Alliansen.",["race:Dwarf"]="Mountaineer Ylva dog när hon försvarade Ironforges heder och sökte efter försvunna fränder. Att återta hennes trampade fana och hämnas hennes död träffar hjärtat av dvärgarnas stolthet och plikt."},sec={{t="Den trampade fanan",b="En trampad fana från Ironforge markerar platsen där en spejare från Alliansen mötte ett brutalt slut. Mountaineer Ylva gav sig in i ett område fullt av troggar, fast besluten att hitta kamrater som försvunnit under en patrull. Hon bar stadens fana som en trotsig markering. Hennes beslutsamhet fick ett abrupt slut när en mäktig trogg slog henne med sådan kraft att hennes försvar krossades och den stolta fanan blev liggande i smutsen."},{t="Hämnd för Ylva",b="Troggaren som låg bakom dådet, en best känd som Headsplitter, kände igen fanan och hotet den utgjorde. Att hissa den fallna fanan blir en öppen utmaning som lockar fram monstret igen för att försvara sitt byte. När Headsplitter har besegrats kan den tilltufsade fanan återlämnas till Captain Rugelfuss. Han ser till att Ylvas vapen förs vidare och att fanan rengörs och bevaras som ett minnesmärke över dvärgarnas uthållighet."}},faq={{q="Vem var den fallna bergsvakten?",a="Den fallna dvärgen är Mountaineer Ylva, en självständig soldat som gav sig in i troggarnas område för att leta efter bergsvakter som aldrig återvände från en patrull. Beväpnad med en fana från Ironforge ville hon visa dvärgarnas beslutsamhet gentemot troggarna, innan hon slogs ner.",al={"vem var bergsvakten","ylvas historia","vem dog med fanan"}},{q="Vad handlar uppdraget Banner of the Fallen om?",a="I Banner of the Fallen hittar du Mountaineer Ylvas kropp och den trampade fana från Ironforge som hon bar. När fanan hissas på nytt lockas hennes baneman, troggen Headsplitter, fram så att du kan hämnas hennes död innan du återlämnar fanan till Captain Rugelfuss.",al={"vad är banner of the fallen","vad händer i banner of the fallen","ironforge-fanans uppdrag"}},{q="Vem dödade Mountaineer Ylva?",a="Ylva dödades av en trogg som kallas Headsplitter, troligen med ett tungt spikförsett påk som gav henne ett dödande slag mot skallen och slog av hjälmen. När fanan från Ironforge hissas provoceras varelsen att återvända.",al={"vem dödade ylva","vilken trogg dödade bergsvakten","headsplitter trogg"}},{q="Vem är Captain Rugelfuss?",a="Captain Rugelfuss är dvärgofficeren som leder bergsvakternas verksamhet och tar emot den återfunna fanan. Han erkänner Ylvas mod och starka självständighet och lovar att rengöra och ställa ut fanan till hennes ära.",al={"vem är rugelfuss","var lämnar jag in fanan","captain rugelfuss fana"}},{q="Varför gav sig Mountaineer Ylva ensam in i troggarnas område?",a="Ylva gav sig av på egen hand för att undersöka varför flera bergsvakter inte hade återvänt från en patrull genom troggarnas område. Hon var känd för sin starka självständighet och bar fanan för att visa att Ironforge aldrig skulle böja sig för troggar.",al={"varför gav sig ylva in i troggarnas område","varför var ylva ensam","ylvas försvunna patrull"}},{q="Hur lockar man fram troggen Headsplitter?",a="Headsplitter minns fanan från Ironforge från när den slog ner Mountaineer Ylva. När den trampade fanan planteras och hissas på nytt provoceras troggen att återvända för att avsluta det den påbörjade.",al={"hur tillkallar man headsplitter","locka fram headsplitter","att hissa fanan"}}},fp="20,177,21.319.0,18.399.1,31.250.0,45.216.0,28.206.0,25.230.0,55.217.0,40.186.0"}
P.entries["quest:86611"] = {n="Stag Lord's Bauble",s="På botten av en förorenad sjö ligger en sliten hjortstaty med en medaljong som bär en sjukligt grön sten. Slammet har suddat ut dess historia, men nattalverna i Talonbranch Glade kanske känner igen den uråldriga ristningen.",h="På botten av en förorenad sjö ligger en sliten hjortstaty med en medaljong som bär en sjukligt grön sten.",kw={"smycke","kristall","felenergi","malorne","medaljong","stag lord","talonbranch glade"},ang={["class:Druid"]="The Great Stag är helig för Cenarion Circle. Att hitta ens en bit av Malornes monument, besudlad av grön magi, kräver svar från gläntans äldste.",["race:NightElf"]="Malorne vördas i dina uråldriga länder. Att se en relik från Stag Lord angripen av demonisk förruttnelse kräver snabba åtgärder för att hindra smittan från att spridas."},sec={{t="Ett sjunket monument",b="Djupt nere i en pöl av stinkande slem ligger en stenhjort, nött av smutsen. Ingen vet hur ristningen hamnade på sjöbottnen, men en medaljong hänger fortfarande kring dess hals. Den enda kristallen i stenen lyser med ett osunt grönt sken. Om du tar föremålet till Talonbranch Glade kanske du får veta var monumentet en gång stod."},{t="Besudlad av Legion",b="Medaljongen prydde en gång en staty vid Malornes helgedom. Under kriget störtade demoner monumentet nedför bergssluttningarna. Med åren sög stenen åt sig felmagi, tills mörk kraft slog rot djupt därinne. Då krossade väktarna i Talonbranch Glade kristallen för gott."}},faq={{q="Var hittades hjortstatyn?",a="Det eroderade hjortmonumentet ligger under stinkande slem på botten av en sjö.",al={"var finns statyn","hjortstaty sjö"}},{q="Vad är Stag Lord's Bauble?",a="Det är en medaljong med en enda kristallsten som lyser med ett osunt grönt sken.",al={"vad är smycket","hjortkristall"}},{q="Vart ska medaljongen föras?",a="Folket i Talonbranch Glade kanske minns varifrån det sjunkna monumentet och dess besudlade sten kommer.",al={"vem känner till historien","vart föra smycket"}},{q="Vem är Stag Lord?",a="Stag Lord är Malorne, den uråldriga vita hjorten som vördas i de nordliga skogarna.",al={"vem är stag lord","stag lords namn"}}},fp="18,220,17.329.0,21.288.1,32.74.0,31.94.0,36.101.0,21.89.0"}
P.entries["quest:86613"] = {n="Excavation Tools",s="Magmar Fellhew ber dig återlämna verktyg som övergavs när troggar drev bort dvärgarna från deras utgrävning. Verktygen kan hjälpa utgrävarna att återuppta arbetet när invasionen är under kontroll.",h="Magmar Fellhew ber dig återlämna verktyg som övergavs när troggar drev bort dvärgarna från deras utgrävning.",kw={"läger","utgrävningsplats","dvärgar","utgrävning","utgrävningsverktyg","magmar fellhew","troggar"},sec={{t="Kvarlämnade verktyg",b="Magmar Fellhew behöver utgrävningsverktygen som dvärgarna lämnade kvar när troggar stormade deras läger. Du kan återlämna dem till utgrävarna, vars arbete har avstannat på grund av invasionen."}},faq={{q="Varför behöver Magmar utgrävningsverktygen?",a="Dvärgarna lämnade kvar de flesta av sina verktyg när troggar stormade deras läger. Verktygen kommer att hjälpa utgrävarna att arbeta igen när invasionen är under kontroll.",al={"varför verktyg","magmars verktyg","utgrävningsverktyg"}},{q="Vem är Magmar Fellhew?",a="Magmar Fellhew är utgrävaren som ber dig återlämna de övergivna verktygen.",al={"vem är magmar","magmar","mannen med verktygen"}},{q="Varför lämnade dvärgarna kvar verktygen?",a="Dvärgarna var tvungna att lämna kvar de flesta av sina verktyg när troggar stormade deras läger.",al={"dvärgarna flydde","varför övergivna","troggar verktyg"}},{q="Vad är problemet vid utgrävningen?",a="Troggar stormade lägret och tvingade dvärgarna att lämna kvar de flesta av sina verktyg och avbryta arbetet tills invasionen är under kontroll.",al={"problem vid utgrävningsplatsen","vad hände i lägret","problem med utgrävningen"}}},fp="16,184,17.181.0,42.157.0,22.75.0,36.83.0,33.137.0"}
P.entries["quest:86614"] = {n="Silver of the Waves",s="Silver of the Waves handlar om att hitta en missfärgad silverhårklämma med monogram, som lämnats bland kasserat fiskeskräp. När det borttappade minnessmycket återlämnas får ägaren en välkommen paus från sina dagliga sysslor och tillbaka en kär ägodel som troddes ha gått förlorad i tidvattnet.",h="Silver of the Waves handlar om att hitta en missfärgad silverhårklämma med monogram, som lämnats bland...",kw={"sysslor","fiskeskräp","hårklämma","k.d.","monogram","minnessmycke i silver","silver of the waves"},sec={{t="Ett minnessmycke bland drivgodset",b="När en uppmärksam resenär letar bland kasserat skräp och fiskerester, bland rostiga krokar och trasiga trådrullar, kan hen hitta något mycket ömtåligare: en utsmyckad silverhårklämma med monogrammet ”K.D.”. Fukt och väder har missfärgat den en aning, men hantverket syns tydligt under korrosionen."},{t="Återfå glansen",b="När ägaren spåras upp visar det sig vara en hårt arbetande ortsbo som är mitt uppe i dagens sysslor. Lättnaden är omedelbar när arvegodset återlämnas. Silverföremålet, som antogs vara förlorat för alltid i vattnet, behöver bara putsas lite för att återfå sin ursprungliga glans, och upphittaren får ett varmt tack."}},faq={{q="Vad är Silver of the Waves?",a="Silver of the Waves börjar när en äventyrare letar bland kasserade fiskesaker och drivgods. Bland rostiga krokar och trassliga trådar ligger en missfärgad silverhårklämma med ingraverade initialer, vilket sätter igång sökandet efter dess rättmätiga ägare.",al={"silver of the waves","vad är silver of the waves","uppdrag med hårklämma"}},{q="Vem äger hårklämman som hittas bland skräpet?",a="Klämman har initialerna ”K.D.” ingraverade. Skräpet ger ingen omedelbar ledtråd om ägarens fullständiga namn, men någon som är upptagen med dagens sysslor känner genast igen den när den återlämnas och är tacksam över att få tillbaka en borttappad accessoar som hen trodde var borta för alltid.",al={"kd-monogram","vems hårklämma är det","vem är kd"}},{q="Var tappades hårklämman bort?",a="Hårklämman hittades bland diverse skräp tillsammans med vanlig fiskeutrustning, däribland trasiga trådrullar och rostiga krokar. Den verkar ha tappats nära vattnet eller följt med fiskeskräp innan den plockades upp.",al={"var hittades hårklämman","hårklämmans plats"}},{q="I vilket skick är hårklämman?",a="Silverhårklämman är lite korroderad efter att ha utsatts för vatten och väder, men är fortfarande utsmyckad och hel. Ägaren säger att den enkelt kan glänsa igen med lite arbete och putsning.",al={"silverklämmans skick","är hårklämman trasig"}},{q="Hur börjar uppdraget?",a="Uppdraget börjar när du undersöker en hög med kasserat fiskeskräp. När du hittar hårklämman med monogram bland förstörda trådrullar och krokar får du i uppgift att ta reda på vem som kan ha tappat den.",al={"vem ger uppdraget","hur startar man silver of the waves"}},{q="Varför är det viktigt att lämna tillbaka hårklämman?",a="Att återlämna ett personligt minnessmycke som gått förlorat vid tidvattnet eller strandkanten är en enkel välgärning. Ägaren blir lättad över att få tillbaka en accessoar som hen trodde var borta för alltid och avbryter gärna sina hektiska sysslor för att belöna upphittaren för besväret.",al={"belöning för hårklämman","varför lämna tillbaka hårklämman"}}},fp="19,171,25.231.0,19.232.0,28.126.0,39.141.0,29.141.0,35.147.0,26.128.0,43.160.0"}
P.entries["quest:86667"] = {n="Snowbound",s="Snowbound är ett lokalt leveransuppdrag i Loch Modan på uppdrag av Grenhild, som studerar traktens elementaler. Hennes tidigare mentor, Norric Lochthane, har bett om en burk osmält snö från South Gate Pass till sina shamanistiska ritualer. Den kyliga ingrediensen blottar det starka bandet och den stilla längtan mellan en åldrande shaman och hans före detta elev.",h="Snowbound är ett lokalt leveransuppdrag i Loch Modan på uppdrag av Grenhild, som studerar traktens...",kw={"grenhild","burk med snö","loch modan","mindre elemental","norric lochthane","shamanistiska ritualer","snowbound","south gate pass","the loch"},ang={["class:Shaman"]="Norric Lochthanes tillit till mindre elementaler som budbärare och till frusna ingredienser visar hur shamanistiska traditioner och elementarforskning bedrivs lokalt i Khaz Modan.",["race:Dwarf"]="Utbytet mellan Norric Lochthane och Grenhild ger en inblick i dvärgisk handledning och elementarforskning kring Loch Modans toppar och stränder."},sec={{t="En ovanlig begäran",b="Under sitt fältarbete med Loch Modans lokala elementaler fick Grenhild oväntat besök av ett bud: en mindre elemental som hennes tidigare mentor, Norric Lochthane, sänt. Norric meddelade att han snarast behövde färsk, osmält snö till sina shamanistiska ritualer. I stället för att ifrågasätta sin gamle lärares egenartade metoder bad Grenhild en äventyrare hämta snön, så att hon kunde fortsätta sina studier av elementaler. Uppdraget gick ut på att samla snö vid South Gate Pass, där iskalla vindar bevarar snödrivorna året runt, och försluta den väl i en särskilt tillverkad keramikburk som isolerar mot dalens värme."},{t="Lärare och elev",b="Norric Lochthane bor i en stillsam stuga vid Lochens nordvästra kust, där han ägnar sig åt shamanism på avstånd från livliga bosättningar. När burken med snö levereras till hans tröskel blir Norric synligt glad över att få den kalla ingrediensen till sin mystiska forskning, men hans reaktion antyder ett djupare motiv. Han beklagar öppet att Grenhild inte kom själv för att hälsa på. Begäran gällde inte bara magiska ingredienser, utan också en åldrande mentors stilla hopp om att återknyta kontakten med en före detta elev som gått sin egen väg."}},faq={{q="Vem är Norric Lochthane?",a="Norric Lochthane är en erfaren shaman som bor i en stuga vid Lochens nordvästra kust i Loch Modan. Han är Grenhilds tidigare lärare och fortsätter att ägna sig åt shamanistiska ritualer på egen hand. Han behärskar elementarmagi så väl att han kan använda mindre elementaler som budbärare genom vildmarken.",al={"norric lochthane bakgrund","vem är norric","norric i loch modan"}},{q="Vem är Grenhild?",a="Grenhild är en elementarforskare stationerad i Loch Modan. Hon studerade magi under Norric Lochthane och respekterar hans hantverk, men har ägnat sig åt att undersöka lokala elementalers beteende ute i fält. Därför har hon knappt tid att resa.",al={"vem är grenhild","grenhild i loch modan","grenhilds mentor"}},{q="Varför behöver Norric en burk snö?",a="Norric bad särskilt om snön till sina shamanistiska ritualer och sin mystiska forskning. Samtidigt hoppades han att begäran skulle få hans tidigare elev, Grenhild, att komma hem till honom på besök.",al={"varför vill norric ha snö","snö till shamanistiska ritualer","syftet med snöburken"}},{q="Var samlas snön till uppdraget?",a="Snön skopas upp nära tunnelöppningen vid South Gate Pass, högt uppe i bergen mellan Dun Morogh och Loch Modan. Tack vare den kalla höjden ligger snön kvar året runt, så resenärer kan packa den i en isolerad keramikburk.",al={"var hittar man snö","var snön finns vid south gate pass","hur får man en burk snö"}},{q="Varför kunde inte Grenhild leverera snön själv?",a="Grenhild är upptagen med att observera och studera Loch Modans lokala elementaler. Eftersom hennes fältarbete kräver ständig uppmärksamhet kan hon inte lämna sin post för att ta sig till South Gate Pass och vidare ner till Norric vid sjön.",al={"varför kan inte grenhild åka","varför behöver grenhild hjälp","grenhild är upptagen"}},{q="Hur skickade Norric sin begäran till Grenhild?",a="I stället för att skicka en vanlig dvärgisk kurir eller postgång åkallade Norric en mindre elemental och skickade den med sitt meddelande till Grenhild. Den ovanliga budbäraren visar hur väl han behärskar elementalernas konst och shamanistiska bruk.",al={"norric kurir","elemental som budbärare","hur kontaktade norric grenhild"}}},fp="9,202,18.448.0,17.379.0,24.260.0,16.202.0,35.152.0,42.224.0,47.181.0,44.157.0"}
P.entries["quest:867"] = {n="Harpy Raiders",s="Witchwing-harpior anfaller försörjningskaravaner på Barrens nordvästra leder. Darsok Swiftdagger vid The Crossroads skickar dig för att jaga deras plundrare och roguefeathers och ta deras klor som bevis.",h="Witchwing-harpior anfaller försörjningskaravaner på Barrens nordvästra leder.",kw={"barrens","crossroads","darsok","harpy","roguefeather","swiftdagger","klor","witchwing"},ang={["class:Rogue"]="Som rogue kan du uppskatta Darsok Swiftdaggers metod: spana på målet, studera dess ranger och slå ut dess ledarskap bit för bit.",["faction:Horde"]="Att hålla lederna genom The Barrens säkra hjälper till att försörja de nygrundade utposterna och hålla dem enade under Orgrimmars baner."},sec={{t="Hot från ovan",b="Witchwing-harpior anfaller karavaner som färdas genom The Barrens. Från klippiga stup i nordväst störtar de ner över handelskaravaner och försörjningsvagnar. De dödar lastdjur och tar varor som är på väg till orchernas utposter, vilket gör varje resa genom området farlig."},{t="Darsoks plan",b="Darsok Swiftdagger, en orchisk rogue, har i flera dagar iakttagit flockens vanor och rangordning. Han tror att ett oplanerat anfall mot deras bergsbon skulle skingra dem. Hans plan är att krossa Witchwing-flocken nerifrån och upp, med början bland plundrarna innan han ger sig på deras befälhavare."}},faq={{q="Varför angriper Horde Witchwing-harpyorna?",a="Witchwing-harpiorna häckar i de nordvästra klipporna i The Barrens och anfaller regelbundet Hordens försörjningskaravaner som färdas längs huvudlederna.",al={"varför döda harpyor","witchwing-problemet","varför angripa harpyor"}},{q="Vem är Darsok Swiftdagger?",a="Darsok Swiftdagger är en orchisk spejare och rogue som är stationerad vid The Crossroads. Han håller uppsikt över lokala hot och har studerat harpiornas befälsordning för att planera ett metodiskt anfall.",al={"darsok","darsok swiftdaggers historia","vem är darsok"}},{q="Varför vill Darsok ha Witchwing-klor?",a="Darsok vill ha de avhuggna klorna som bevis för varje dödad harpia. Han samlar dem som troféer och för att bekräfta att flockens lägsta plundrarranger blir färre.",al={"varför klor","vad harpyklor används till"}},{q="Var finns harpyorna?",a="Harpiorna håller till i törnbeklädda klippor och raviner längst i nordvästra The Barrens, norr om vägen till Stonetalon.",al={"var hittar man harpyor","witchwings plats","harpy raiders plats"}},{q="Vad händer när plundrarna har gallrats ut?",a="När plundrarna och roguefeathers har decimerats skickar Darsok dig vidare mot flockens högre ranger, däribland dess löjtnanter och matriark.",al={"nästa uppdrag","efter harpy raiders","what comes next"}},{q="Arbetar harpyorna åt någon annan?",a="Witchwing-harpiorna är vilda, revirhävdande asätare som lyder under sin matriark i boet, Serena Bloodfeather, snarare än någon yttre fraktion.",al={"vem leder harpyorna","harpyornas lojalitet","witchwings ledare"}}},fx={["8e2506f2"]={q="Vilka är Witchwing-harpierna?",a="Witchwing är en flock våldsamma, fågelliknande humanoider som häckar bland klipporna och ravinerna i nordvästra The Barrens. De är kända för sitt skrikande ursinne och störtar ner från höjderna för att överfalla resande och plundra Horde-karavaner på de torra slätterna. Darsok har pekat ut deras vanliga plundrare, däribland Witchwing Roguefeathers, som grunden för flockens plundringsstyrka.",al={"witchwing-harpiernas mål","vilka är harpierna","witchwing roguefeathers"}}},fp="13,196,17.209.0,13.284.0,49.123.0,26.178.0,38.147.0,32.118.0,41.137.1,40.141.0"}
P.entries["quest:8670"] = {n="Runetotem the Elder",s="Under Lunar Festival kan resande i Durotar hedra Elder Runetotem, en Ancestral Spirit. Hon väntar i Razor Hill under en stråle av himmelskt ljus och ger välsignelser och festivalpolletter till dem som minns det förflutna.",h="Under Lunar Festival kan resande i Durotar hedra Elder Runetotem, en Ancestral Spirit.",kw={"durotar","elder darkhorn","elder high mountain","elder runetotem","lunar festival","razor hill","runetotem"},ang={["faction:Alliance"]="Som resande från Alliance måste du ta dig genom fiendens linjer in i Durotar för att hedra Elder Runetotem och riskera vreden hos Razor Hills orciska vakter.",["faction:Horde"]="Som medlem av Horde kan du hedra Elder Runetotem innanför Razor Hill. Därför är hon en av de säkraste och mest lättillgängliga förfäderna att besöka tidigt på din resa.",["race:Tauren"]="Som tauren påminner ett möte med en ande ur Runetotem-familjen bortom Mulgore dig om ditt folks djupa andliga arv över hela Kalimdor."},sec={{t="En ande i Razor Hill",b="Under Lunar Festival visar sig andar av forntida äldste över hela Azeroth för att möta de levande. Elder Runetotem väntar innanför Razor Hill, strax efter den södra ingången. En stråle av stjärnljus faller på henne medan hon vakar över orchernas bosättning. Resande kan stanna där för att hedra visdomen hos dem som kom före."},{t="Vägledning över land och rike",b="När du hyllar Elder Runetotem ger hon dig en festivalpollett som bringar lycka och berättar var andra andar finns. Hennes vägbeskrivningar leder till Elder Darkhorn och Elder High Mountain på andra håll på kontinenten."}},faq={{q="Var finns Elder Runetotem?",a="Elder Runetotem väntar innanför Razor Hill i Durotar, strax till höger när du kommer in genom den södra ingången.",al={"elder runetotem plats","var finns elder runetotem","hitta elder runetotem"}},{q="Varför lyser en ljusstråle på henne?",a="En stråle av himmelskt ljus utmärker Elder Runetotem som en vördad äldste, liksom de Ancestral Spirits som visar sig under Lunar Festival.",al={"ljusstråle äldste","varför lyser runetotem","äldstes ljusstråle"}},{q="Vad får du för att hedra Elder Runetotem?",a="Du får en festivalpollett när du hedrar Elder Runetotem, och hon visar vägen till andar som Elder Darkhorn och Elder High Mountain.",al={"runetotem belöning","vad ger runetotem","lämna in till elder runetotem"}},{q="Kan spelare från Alliance besöka Elder Runetotem?",a="Elder Runetotem tar emot hyllningar från alla dödliga, oavsett lojalitet, men Razor Hill är en bevakad utpost för Horde som kan vara farlig för resande från Alliance att ta sig till.",al={"alliance elder runetotem","kan alliance prata med runetotem"}},{q="Vilka äldste nämner Runetotem?",a="Elder Runetotem visar vägen till Elder Darkhorn och Elder High Mountain.",al={"runetotems vägbeskrivning","vem säger runetotem att du ska hitta"}},{q="Är Elder Runetotem en levande tauren eller ett spöke?",a="Elder Runetotem är en Ancestral Spirit som visar sig under Lunar Festival för att välsigna dem vars andar brinner av liv.",al={"är runetotem död","är runetotem ett spöke"}}},fp="19,215,22.289.0,25.220.0,33.116.0,44.140.0,49.142.0,43.172.0,36.75.0,46.121.0"}
P.entries["quest:8673"] = {n="Bloodhoof the Elder",s="Bloodhoof the Elder är ett möte med en av de vördnadsbjudande förfädersandarna som visar sig under Lunar Festival. Denna ärade ande står strax utanför Bloodhoof Village i Mulgore, erkänner resande vandrares respekt och ger en förfädratoken i gengäld.",h="Bloodhoof the Elder är ett möte med en av de vördnadsbjudande förfädersandarna som visar sig under Lunar...",kw={"förfader","bloodhoof village","coin of ancestry","elder bloodhoof","lunar festival","mulgore"},ang={["class:Druid"]="Druider håller Lunar Festivals andar i stor vördnad och samtalar med de äldste för att stärka sitt naturliga band till jorden och stjärnorna.",["class:Shaman"]="För en schaman stärker samtal med förfäder som Elder Bloodhoof direkt den levande gemenskapen mellan de dödligas värld och förfädersandarna.",["faction:Alliance"]="För att nå Elder Bloodhoof måste du ta dig in i hjärtat av Mulgore, vilket gör färden till en djärv resa genom fientliga hordslätter.",["race:Tauren"]="Att hälsa på Elder Bloodhoof är en helig plikt på hemmaplan och hedrar arvet från stammen som hjälpte tauren att finna sin fridfulla fristad i Mulgore."},sec={{t="Ett besök från förfäderna",b="Under firandet av Lunar Festival återvänder stora hjältars och äldstes andar från svunna tider till Azeroth. Omgiven av himmelsk strålglans visar sig Elder Bloodhoof strax norr om Bloodhoof Village, nära bron. Att närma sig dessa vördnadsbjudande förfäder är ett sätt att hedra gångna tiders uppoffringar, och i gengäld erbjuder Elder Bloodhoof uppmuntrande ord och ett heligt Coin of Ancestry."},{t="Bloodhoofs arv",b="På Mulgore förfädersmarker fungerar Elder Bloodhoof som en bro mellan de levande taurenstammarna och minnet av deras förfäder. För tauren är vördnaden för de döda en grundpelare i det andliga livet, som stärker harmonin mellan Earth Mother, förfäderna och dem som nu vandrar över slätterna."}},faq={{q="Var hittar jag Elder Bloodhoof?",a="Elder Bloodhoof står upplyst av en stråle himmelskt ljus strax utanför Bloodhoof Village i Mulgore, nära bron.",al={"elder bloodhoof plats","var finns elder bloodhoof","bloodhoof äldste plats"}},{q="Varför söker man upp Elder Bloodhoof?",a="Resande söker upp Elder Bloodhoof under Lunar Festival för att visa förfäderna sin vördnad. Som erkänsla för denna hedersbetygelse belönar anden besökarna med ett Coin of Ancestry och visdom om närliggande andar, som Elder Proudhorn.",al={"varför prata med elder bloodhoof","bloodhoof äldstes syfte","vad ger elder bloodhoof"}},{q="Varför lyser en ljusstråle på honom?",a="Ljusstrålen markerar andens närvaro som en förfädersuppenbarelse under Lunar Festival och symboliserar en helig förbindelse med himlen och det förflutnas andar.",al={"varför lyser elder bloodhoof","ljus på elder bloodhoof"}},{q="Kan allianskaraktärer hylla Elder Bloodhoof?",a="Lunar Festivals förfäder hedrar alla dödliga som visar vördnad, oavsett fraktion. Alliansens resande måste dock vara försiktiga, eftersom Elder Bloodhoof står precis vid tröskeln till hordterritorium.",al={"kan alliansen göra uppdraget","är elder bloodhoof bara för horden"}},{q="Vem är Elder Proudhorn som den här äldsten nämner?",a="Elder Proudhorn är en annan förfädersande som hedras under festivalen och finns i Thunder Bluff. Elder Bloodhoof kan vägleda dig till var du hittar honom.",al={"elder wheathoof","vem är wheathoof"}},{q="Vad står Coins of Ancestry för?",a="Coins of Ancestry är tecken på gunst från Azeroths ärade andar. De visar att en resande har visat det förflutna respekt, och festivalfirare byter in dem mot festkläder, ritningar och festliga varor.",al={"vad är coins of ancestry","lunar festival polletter"}}},fp="19,159,26.277.0,20.250.0,33.117.0,51.191.0,49.170.0,54.191.0,48.134.0,40.209.0"}
P.entries["quest:86746"] = {n="The Legashi Threat",s="Ekkal ber dig försvara Blackmaw furbolg mot Legashi satyr vid Ruins of Eldarath. Satyrerna har korrumperat medlemmar av stammen och drivit överlevande till provisoriska läger.",h="Ekkal ber dig försvara Blackmaw furbolg mot Legashi satyr vid Ruins of Eldarath.",kw={"blackmaw","ekkal","furbolg","legashi","ruins of eldarath","satyr","timbermaw"},sec={{t="En hotad stam",b="Ekkal ber om din hjälp vid Ruins of Eldarath, där Legashi satyr har invaderat Blackmaw-hålan. Deras korruption har fått fäste bland furbolg och skiljt stammen från dess Timbermaw-allierade. Överlevande samlas nu i provisoriska läger, medan korruptionen sprider sig över landet. Ekkal hoppas att varje dödad Legashi ska rädda livet på en furbolg."}},faq={{q="Vem ber om hjälp?",a="Ekkal ber dig hjälpa till att försvara Blackmaw furbolg mot Legashi satyr.",al={"vem är ekkal","hjälp från ekkal","furbolg-uppdragsgivare"}},{q="Vad gör Legashi mot Blackmaw?",a="Legashi har invaderat Blackmaw-hålan, korrumperat många furbolg och skiljt stammen från dess Timbermaw-allierade.",al={"legashis hot","vad satyrerna gör","blackmaw attackerade"}},{q="Var håller Legashi till?",a="Ekkal säger att Legashi håller till bland ruinerna nordost om Blackmaw-hålan.",al={"legashis plats","var satyrerna finns","ruinerna i eldarath"}},{q="Vilka Legashi vill Ekkal att du besegrar?",a="Ekkal ber dig besegra Legashi Satyr, Legashi Rogues och Legashi Hellcallers.",al={"legashi-typer","vilka satyrer ska dödas","legashi-fiender"}},{q="Varför ber Ekkal om hjälp?",a="Legashi hotar den redan utsatta Blackmaw-stammen, och Ekkal tror att varje dödad Legashi kan rädda livet på en furbolg.",al={"varför hjälpa ekkal","furbolg behöver hjälp","varför döda legashi"}}},fp="18,179,20.344.0,23.74.0,43.117.0,26.74.0,44.80.0,28.118.0"}
P.entries["quest:86747"] = {n="Legashi Horns",s="En furbolg från Ursolan ber dig hämta horn från dödade Legashi-satyrer. Varje bunt visar att du tjänar Blackmaw.",h="En furbolg från Ursolan ber dig hämta horn från dödade Legashi-satyrer.",kw={"blackmaw","furbolg","legashi","legashi-horn","satyrer","ursolan"},sec={{t="Bland Blackmaw",b="De andra furbolgerna i Blackmaw är svårare att övertyga, så du fortsätter kampen mot Legashi. Hornen finns på de satyrer du dödar och ska hämtas tillbaka. Varje bunt visar stammen att du tjänar den, och furbolgerna i Ursolan får höra om dina bedrifter."}},faq={{q="Vem vill ha Legashi-hornen?",a="En furbolg från Blackmaw ber dig hämta horn från dödade Legashi-satyrer.",al={"vem ber om horn","horn åt vem"}},{q="Varför vill de ha hornen?",a="Varje bunt visar att du tjänar Blackmaw och hjälper till att övertyga stammens andra medlemmar.",al={"varför horn","vad ska hornen användas till"}},{q="Vad är Legashi?",a="Legashi är satyrer, och Blackmaw ber dig hämta horn från dem du dödar.",al={"legashi-satyrer","vilka är legashi"}},{q="Vad hände innan det här?",a="Du har redan visat vad du går för för furbolgen som talar för Blackmaw, men resten av stammen är svårare att övertyga.",al={"vad hände innan","blackmaws förtroende"}},{q="Var får furbolgerna höra om mina bedrifter?",a="Furbolgen som talar för Blackmaw säger att ryktet om dina bedrifter kommer att spridas bland furbolgerna i Ursolan.",al={"var ryktet sprids","ursolans furbolger"}}},fp="13,118,18.269.0,28.75.0,27.97.0,21.83.0,26.125.0,40.105.0"}
P.entries["quest:8675"] = {n="Skychaser the Elder",s="Under Lunar Festival visar sig Skychaser the Elder högst upp i Sentinel Tower i Westfall. Resande klättrar upp för att hedra henne och får hennes välsignelse i gengäld.",h="Under Lunar Festival visar sig Skychaser the Elder högst upp i Sentinel Tower i Westfall.",kw={"coin of ancestry","elder skychaser","lunar festival","sentinel hill","sentinel tower","skychaser","westfall"},ang={["class:Druid"]="Som druid hedrar du Lunar Festival och dess förfädersandar. Skychaser förenar forntida traditioner med djup vördnad för naturen.",["faction:Alliance"]="Som resande från Alliance hittar du Elder Skychaser vid People's Militia-baslägret på Sentinel Hill. Det är lätt att hedra henne när du färdas genom Westfall.",["faction:Horde"]="Som resande från Horde möter du fientliga Alliance-vakter och milisspejare vid Sentinel Hill. För att nå Elder Skychaser krävs smygande, snabbhet eller råstyrka."},sec={{t="En fyr i dammet",b="Sentinel Hill står emot Defias-rövare och kringströvande asätare i Westfalls oroliga buskmarker. Under Lunar Festival visar sig en förfädersande vid namn Elder Skychaser på den öppna plattformen högst upp i Sentinel Tower. Högt ovanför dammet och vinden vakar hon över de utmattade soldaterna och de hårt ansatta nybyggarna nedanför. Vem som helst kan klättra upp i tornet och visa henne sin vördnad."},{t="Att hedra förfäderna",b="Över hela Azeroth hedrar Lunar Festival visdom, arv och gärningarna hos forntida andar som vandrade på jorden före dagens strider. När du närmar dig känner Elder Skychaser igen livsgnistan inom dig. Hon tar emot din hyllning och ger dig en gåva som tecken på sin ynnest, ett band mellan de levande och de hedrade döda."}},faq={{q="Var hittar jag Elder Skychaser?",a="Elder Skychaser väntar högst upp i Sentinel Tower vid Sentinel Hill i Westfall. Klättra uppför tornets spiraltrappa till den övre utkiksplatsens murkrön.",al={"skychasers plats","var finns elder skychaser","skychaser i westfall"}},{q="Varför står Elder Skychaser högst upp i Sentinel Tower?",a="Under Lunar Festival visar sig förfädersandar på framträdande, symboliska platser över hela Azeroth. Från Sentinel Towers höjder blickar man ut över Westfalls bäcken, där den äldste kan se resande trotsa gränslandet.",al={"varför är hon i sentinel tower","skychaser i tornet"}},{q="Vad är syftet med det här uppdraget?",a="Du hedrar förfädernas äldste under Lunar Festival genom att söka upp Elder Skychaser. Din vördnad ger dig ett Coin of Ancestry och en välsignelse som firar din levande ande.",al={"skychasers uppdragsbelöning","varför hedra elder skychaser"}},{q="Kan Horde-spelare hedra Elder Skychaser?",a="Elder Skychaser välkomnar alla pilgrimer, men Sentinel Hill är en välförsvarad Alliance-utpost. Det är farligt för Horde-äventyrare att ta sig fram till henne.",al={"kan horde besöka skychaser","är skychaser fientlig mot horde"}},{q="Hjälper Elder Skychaser till med att försvara Sentinel Hill?",a="Nej. Lunar Festivals äldste är andliga gestalter som ägnar sig åt tradition och hågkomst. Elder Skychaser deltar inte i People's Militia-skärmytslingar mot Defias Brotherhood.",al={"strider skychaser mot defias","tillhör skychaser people's militia"}},{q="Vad säger Skychaser när du hälsar på henne?",a="Elder Skychaser säger att din ande brinner klart av liv. Hon tar emot din hyllning och erbjuder en förfädersgåva i gengäld.",al={"skychasers dialog","vad säger den äldste"}}},fp="19,189,20.334.0,22.268.0,33.126.0,57.197.0,34.169.0,40.144.0,65.195.0,43.133.0"}
P.entries["quest:86757"] = {n="Slowing the Orc Advance",s="Shandrina ber dig hjälpa till att driva bort orcher från östra Ashenvale. Deras spejare och fotsoldater gör det farligt för hennes folk att färdas genom skogen.",h="Shandrina ber dig hjälpa till att driva bort orcher från östra Ashenvale.",kw={"ashenvale","böjda knivar","fotsoldater","tandade svärd","orcher","spejare","shandrina","vapen"},sec={{t="Orcher i skogen",b="I Ashenvale söker Shandrina din hjälp medan orcher sprider sig genom den östra skogen. Deras spejare och fotsoldater lurar nu överallt i skogen och gör det farligt för hennes folk att färdas där. Du ombeds att ge henne de tandade svärd och böjda knivar som orcherna använder, så att hon kan ta till vara dem och använda dem till annat."}},faq={{q="Vad behöver Shandrina?",a="Shandrina ber dig ge henne de tandade svärd och böjda knivar som orcherna använder.",al={"vad vill hon ha","shandrina behöver","föremål till shandrina"}},{q="Varför är Ashenvale farligt?",a="Orcher har tagit över den östra skogen, och deras spejare och fotsoldater lurar bland träden.",al={"varför farligt","orcher i askskogen","vad händer i ashenvale"}},{q="Vad ska Shandrina göra med vapnen?",a="Shandrina planerar att ta till vara orchernas vapen och använda dem till annat.",al={"vapnens syfte","vad ska svärden användas till","återanvända orchvapen"}},{q="Vilka är orcherna i skogen?",a="Orcherna har tagit över den östra skogen, där deras spejare och fotsoldater nu lurar.",al={"orchspejare","orchfotsoldater","vem tog över östra delen"}}},fp="23,142,17.288.0,25.85.0,24.92.0,40.57.0,30.84.0"}
P.entries["quest:86758"] = {n="Twisting the Knife",s="Marek ber dig jaga Daggerfang, krokolisken som tog hans kniv. Odjuret stryker längs sjöstranden, där andra jägare kan vara i fara.",h="Marek ber dig jaga Daggerfang, krokolisken som tog hans kniv.",kw={"krokolisk","daggerfang","jakt","jägare","kniv","sjö","marek"},sec={{t="Mareks kniv",b="Marek berättar att en krokolisk nästan bet av honom handen och fick honom att fly hals över huvud från sjön. Han tror att hans kniv fortfarande finns någonstans i närheten. Han kallar odjuret Daggerfang och ber dig hitta det längs sjöstranden, där andra jägare kan vara i fara."}},faq={{q="Vem är Daggerfang?",a="Daggerfang är en krokolisk som enligt Marek jagar längs sjöstranden.",al={"daggerfang","daggerfang krokolisk","stor krokolisk"}},{q="Vad hände med Mareks kniv?",a="Marek tror att han lämnade sin kniv nära sjön efter att ha använt den mot en krokolisk.",al={"mareks kniv","borttappad kniv","var finns kniven"}},{q="Varför vill Marek att Daggerfang jagas?",a="Marek tror att Daggerfang kan hota de andra jägarna nära sjön.",al={"varför döda daggerfang","krokolisk fara","jaga krokolisken"}},{q="Var finns Daggerfang?",a="Marek säger att Daggerfang jagar längs sjöstranden.",al={"daggerfang plats","krokolisk vid sjön","var finns krokolisken"}},{q="Vad ber Marek mig att ta med tillbaka?",a="Marek ber dig hitta och besegra Daggerfang och ta med hans kniv tillbaka.",al={"vad ska tas med tillbaka","kniv och krokolisk","mareks begäran"}},{q="Vad säger Marek om krokolisken?",a="Marek säger att krokolisken nästan bet av honom handen och att han använde sin kniv mot den för att komma undan.",al={"mareks berättelse om krokolisken","förlorade nästan handen","kniv i käften"}}},fp="18,147,15.256.0,18.70.0,33.80.0,38.71.0,20.55.0,37.70.0,40.90.0"}
P.entries["quest:8677"] = {n="Darkhorn the Elder",s="Under Lunar Festival tar Elder Darkhorn emot resenärer i Orgrimmar. Hon vördas bland förfäderna och förkroppsligar ålder, överlevnad och stolthet över sina förfäder.",h="Under Lunar Festival tar Elder Darkhorn emot resenärer i Orgrimmar.",kw={"förfader","coin of ancestry","darkhorn","elder darkhorn","äldste","lunar festival","orgrimmar","valley of wisdom"},ang={["class:Shaman"]="Som shaman vördar du bandet mellan den levande världen och uråldriga andar. Att besöka förfädersäldste som Darkhorn är en djupgående andlig plikt.",["faction:Alliance"]="Som Alliance-resenär måste du smyga förbi Orgrimmars hårt försvarade portar och gator för att nå Elder Darkhorn. Färden prövar din smidighet eller din styrka.",["faction:Horde"]="Som Horde-mästare kan du hedra förfädernas tradition genom att besöka Elder Darkhorn i hjärtat av din huvudstad."},sec={{t="Att hedra förfadern",b="Under Lunar Festival visar sig vördnadsvärda förfäder över hela Azeroth för att dela sin visdom med de levande. Elder Darkhorn vilar innanför Orgrimmars befästa murar och vakar över den unga krigarstaden. Du kan närma dig henne för att hedra dem som vandrade på jorden för generationer sedan, oavsett om du strider för Horde eller vågar dig genom portarna som Alliance-resenär."},{t="Festivalens ande",b="Resenärer hälsar på Elder Darkhorn och visar henne vördnad, och hon känner igen livets gnista i dem. När du hedrar de gamla sederna får du ett Coin of Ancestry och hennes välsignelse. Polletterna firar segern över uråldriga faror och påminner de levande om att värdesätta styrkan som förts vidare genom obrutna släktled."}},faq={{q="Vem är Elder Darkhorn?",a="Elder Darkhorn är en förfädersande som visar sig i Orgrimmar under Lunar Festival. Som sändebud från det förflutna ger hon välsignelser och polletter till resenärer som hedrar de äldre.",al={"elder darkhorn","vem är darkhorn","darkhorns historia"}},{q="Var hittar jag Elder Darkhorn?",a="Du hittar Elder Darkhorn i Valley of Wisdom, strax utanför Grommash Hold i Orgrimmar. Under festivalen vakar hon över vardagslivet i Hordes huvudstad.",al={"darkhorns plats","var finns darkhorn","elder darkhorn orgrimmar"}},{q="Vad är syftet med de äldste under Lunar Festival?",a="Under Lunar Festival visar sig de äldre så att du kan hedra förfädernas visdom, mod och uppoffringar. Visa en äldre respekt och få ett Coin of Ancestry, en symbol för arv och gemensamma minnen.",al={"varför söka upp de äldste","äldste under lunar festival","förfädersmynt"}},{q="Kan alliansspelare hedra Elder Darkhorn?",a="Ja, du kan hedra Elder Darkhorn som Alliance-resenär. Hon bor djupt inne i Orgrimmar, ett Horde-fäste, så du måste våga dig förbi fientliga vakter och spelare för att nå henne.",al={"kan alliansen tala med darkhorn","alliansen elder darkhorn","alliansen äldste orgrimmar"}},{q="Vilken belöning ger Elder Darkhorn?",a="När du hedrar Elder Darkhorn ger hon dig ett Coin of Ancestry och sin välsignelse.",al={"darkhorns belöning","vad ger darkhorn","coin of ancestry darkhorn"}},{q="Kan uppdraget upprepas?",a="Nej, du kan hedra varje förfädersäldste bara en gång per karaktär under den årliga Lunar Festival.",al={"kan jag göra darkhorn igen","kan darkhorn upprepas","darkhorn dagligt uppdrag"}}},fp="18,155,21.328.0,26.311.0,22.184.0,32.163.0,49.200.0,42.174.0,38.82.0,25.96.0"}
P.entries["quest:86776"] = {n="Ingredients for the Forge",s="Ingredients for the Forge är ett lokalt uppdrag i Thelsamar där dvärghantverkaren Morhan Coppertongue ber om bronsbarr för att fylla på de sinande förråden i sin verkstad. Den lantliga bosättningen saknar Ironforges enkla tillgång till handel och är beroende av resande för att hålla smedjan försedd med viktiga metaller till verktyg och vardagsföremål.",h="Ingredients for the Forge är ett lokalt uppdrag i Thelsamar där dvärghantverkaren Morhan Coppertongue ber om...",kw={"smed","bronsbarr","smedja","ingredients for the forge","loch modan","morhan coppertongue","thelsamar"},ang={["profession:Blacksmithing"]="Morhan Coppertongue är beroende av smeder och metallarbetare för att förse Thelsamar med vardagsutrustning, från vattenkokare och grytor till fältverktyg.",["profession:Mining"]="Gruvarbetare som kan smälta koppar och tenn till bronsbarr tillhandahåller råmaterialen som behövs för att hålla verkstäderna på landsbygden i Loch Modan igång.",["race:Dwarf"]="Även små dvärgbosättningar som Thelsamar är starkt beroende av en fungerande smedja, så brist på metall är ett ständigt bekymmer för samhället."},sec={{t="Brist på förnödenheter i Thelsamar",b="Livet i Thelsamar går lugnare till än i Ironforges Great Forge, men avståndet till huvudstaden innebär logistiska utmaningar. Den lokala smeden Morhan Coppertongue arbetar hårt för att förse staden med viktig utrustning, kokkärl och verktyg, men drabbas ofta av brist på råmetaller som brons. Utan regelbundna leveranser från staden är de lokala hantverkarna beroende av förbipasserande resande och prospektörer för att hålla städet klingande."},{t="Hålla elden vid liv",b="När Morhan får tag på smält brons kan han lösa sitt omedelbara hantverksproblem och fylla på stadens hushållsvaror och nyttosaker. Ändå har den lantliga smedjan fortsatt svårt med försörjningen, särskilt eftersom det saknas en pålitlig handelsväg som regelbundet för in bränsle som kol i Loch Modan."}},faq={{q="Vem erbjuder Ingredients for the Forge?",a="Uppdraget erbjuds av Morhan Coppertongue, en dvärghantverkare som arbetar vid smedjan i staden Thelsamar i Loch Modan.",al={"vem ger ingredienser till smedjan","morhan coppertongue uppdrag","smeduppdrag i thelsamar"}},{q="Vilka material behöver Morhan Coppertongue?",a="Morhan Coppertongue behöver bronsbarr för att hålla verkstaden igång och kunna tillverka viktiga vardagsföremål som grytor, vattenkokare och verktyg åt lokalbefolkningen.",al={"vad behöver morhan","material till ingredients for the forge","vilka barr behöver smedjan i thelsamar"}},{q="Varför börjar metallen ta slut i Thelsamar?",a="Thelsamar är en trivsam bosättning, men saknar Ironforges omfattande industrianläggningar och stadiga handelsflöde. Därför riskerar de lokala hantverkarna att få slut på råmaterial.",al={"varför saknar thelsamar brons","varför har thelsamar inte metall"}},{q="Vad smider Morhan av bronset?",a="Morhan använder främst brons till praktiska hushålls- och arbetsföremål, däribland köksutrustning, vattenkokare, grytor och olika arbetsverktyg åt stadsborna.",al={"vad används brons till i thelsamar","vad tillverkar morhan"}},{q="Vilka andra förnödenheter har smedjan svårt att få tag på?",a="Utöver metalltackor nämner Morhan att han behöver en regelbunden handelsman som för in kol i staden, eftersom bränsle behövs för att hålla smedjans eld brinnande.",al={"vilket bränsle behöver morhan","kolbristen i thelsamar"}},{q="Var slutförs uppdraget?",a="Uppdraget utspelar sig i Thelsamar, den främsta dvärgbosättningen bland kullarna i Loch Modan, strax öster om Dun Morogh.",al={"var utspelar sig ingredients for the forge","platsen för ingredients for the forge"}}},fp="25,198,27.374.0,25.163.0,37.93.0,45.132.0,38.106.0,39.131.0,51.112.0,30.99.0"}
P.entries["quest:8678"] = {n="Proudhorn the Elder",s="Proudhorn the Elder är en vördad taurenande från förfäderna som hedras under Lunar Festival på höjderna i Thunder Bluff. Att besöka honom är en handling av djup vördnad och ett erkännande av förfädernas visdom när de vakar över Mulgore och Horde.",h="Proudhorn the Elder är en vördad taurenande från förfäderna som hedras under Lunar Festival på höjderna i...",kw={"förfader","coin of ancestry","äldre","lunar festival","mulgore","ande","thunder bluff","proudhorn"},ang={["class:Shaman"]="För en schaman är det en djupgående ritual att kommunicera med en äldre förfädersande, en gemenskap med andevärlden som består genom tiderna.",["faction:Horde"]="Denna äldre välkomnar alla allierade till Horde som bestiger Thunder Bluff för att hylla honom, mitt i taurenfolkets maktcentrum.",["race:Tauren"]="Att hedra Elder Proudhorn är en helig hemkomst för taurenhjältar och bekräftar deras eviga band till andarna som vakar över Mulgore."},sec={{t="En ande från Mulgore",b="Högt uppe på Thunder Bluffs vindpinade platåberg visar sig Proudhorn the Elder som en närvaro från förfäderna under Lunar Festival. Taurenkulturen håller sina förfäders röster i högsta aktning och tror att forna ledares och vises andar dröjer kvar för att ge de levande vägledning och styrka."},{t="Hylla och välsignelse från förfäderna",b="Resenärer som bestiger höjderna för att visa Elder Proudhorn sin vördnad välkomnas inte som främlingar, utan som livets dyrbara lågor. Som svar på resenärens hyllning ger den äldre en Coin of Ancestry, en symbol för gemenskapen mellan det bestående förflutna och de levande hjältar som kämpar för världens framtid."}},faq={{q="Vem är Proudhorn the Elder?",a="Han är en vördad taurenande från förfäderna som visar sig ovanför staden Thunder Bluff under Lunar Festival för att ta emot hyllningar från hjältar från hela Azeroth.",al={"wheathoof","elder wheathoof","vem är wheathoof"}},{q="Var hittar jag Proudhorn the Elder?",a="Elder Proudhorn finns i taurenfolkets huvudstad Thunder Bluff, på de vidsträckta centrala platåbergen med utsikt över Mulgore-slätterna.",al={"var finns elder wheathoof","wheathoof plats","åldste i thunder bluff"}},{q="Varför ska man besöka honom?",a="Genom att besöka Elder Proudhorn kan spelare hedra det förflutnas andar under Lunar Festival och få hans välsignelse och en Coin of Ancestry i gengäld.",al={"varför besöka wheathoof","wheathoof uppdrag","åldste under lunar festival"}},{q="Kan spelare från Alliance besöka Elder Proudhorn?",a="Anden välsignar alla respektfulla resenärer, men det är mycket farligt för en äventyrare från Alliance att ta sig in i Thunder Bluff på grund av stadsvakternas och Hordes försvarares vaksamhet.",al={"kan alliance tala med wheathoof","alliance åldste i thunder bluff"}},{q="Vad är en Coin of Ancestry?",a="Det är en ceremoniell symbol som forntida andar ger under Lunar Festival och som står för respekt och gemenskap mellan de levande och förfäderna.",al={"coin of ancestry","mynt från lunar festival"}},{q="Hur ser tauren på sina äldre?",a="Tauren vördar sina förfäder som beskyddare och lärare. Deras andliga närvaro förblir invävd i landet och ger ständig vägledning åt dem som står i samklang med Jordmodern.",al={"taurenernas förfädersdyrkan","taurenäldstes historia"}}},fp="19,202,19.253.0,29.258.0,27.123.0,37.118.0,36.145.0,43.142.0,27.170.0,36.141.0"}
P.entries["quest:86784"] = {n="Sticks and Bones",s="Sticks and Bones är ett lokalt uppdrag som Deathguard Bartholomew erbjuder i Tirisfal Glades. Han skickar resenärer att samla torra grenar i den fördärvade skogen och lämna dem till Eleanor Shackleton, en erfaren överlevare som slagit läger i de västra kullarna.",h="Sticks and Bones är ett lokalt uppdrag som Deathguard Bartholomew erbjuder i Tirisfal Glades.",kw={"samlingskorg","deathguard bartholomew","torr gren","eleanor shackleton","ved","sticks and bones","överlevnad","tirisfal glades"},ang={["faction:Horde"]="Avlägsna läger som Eleanors erbjuder unga Horde-äventyrare trevliga rastplatser när de ger sig ut genom Tirisfal Glades.",["race:Undead"]="Även i Lordaerons fördärvade skogar måste Forsaken-resenärer som Eleanor Shackleton anpassa gamla överlevnadsvanor till sitt nya odöda liv."},sec={{t="En vänlig gest",b="Medan Deathguards i Tirisfal Glades oftast är upptagna med militära patrulluppdrag och att hålla Scourge eller Scarlet crusaders stången, tar Deathguard Bartholomew en stund för att bry sig om en bekant. Eftersom han vet att Eleanor Shackleton tillbringar sitt odöda liv ute i det hårda vädret uppmuntrar han förbipasserande äventyrare att samla torra grenar till hennes lägereld."},{t="Livet i vildmarken",b="Eleanor Shackleton är stolt över att klara sig ensam i Tirisfals fördärvade vildmark. Trots att de är odöda känner Forsaken fortfarande den fuktiga, bitande kylan som sveper in över de nordliga hedarna. Eleanors filosofi om vedinsamling är enkel: samla fem gånger mer ved än du tror att du behöver. Tacksam för den extra veden låter hon budbäraren behålla Bartholomews korg och dela värmen från hennes eld."}},faq={{q="Vem ger uppdraget Sticks and Bones?",a="Deathguard Bartholomew i Tirisfal Glades ger uppdraget till förbipasserande äventyrare och ber dem hjälpa hans bekanta Eleanor Shackleton.",al={"vem ger sticks and bones","sticks and bones uppdragsgivare"}},{q="Var har Eleanor Shackleton slagit läger?",a="Eleanor Shackleton har ett litet läger ute i kullarna västerut i Tirisfal Glades, där hon klarar väder och vind långt från bosättningarna.",al={"eleanor shackleton plats","var är eleanor","var lämnar man in sticks and bones"}},{q="Varför behöver Forsaken ved när de är odöda?",a="Forsaken fryser inte ihjäl som levande, men de känner ändå den ihållande fukten och bitande kylan i Tirisfals vildmark. En lägereld ger dem tröst, håller deras stela leder varma och gör lägret beboeligt ute i vildmarken.",al={"blir odöda kalla","varför ved till odöda","forsaken kyla"}},{q="Vilket råd ger Eleanor om att samla ved?",a="Enligt Deathguard Bartholomew lyder Eleanors främsta överlevnadsregel: ”När du tror att du har tillräckligt med ved, samla fem gånger mer.”",al={"eleanors vedregel","eleanors råd"}},{q="Vilket föremål använder du för att samla grenarna?",a="Deathguard Bartholomew ger dig en samlingskorg att bära de sex torra grenarna som finns utspridda över gläntorna i. När du har lämnat dem låter Eleanor dig behålla den.",al={"korg för torra grenar","hur samlar man grenar"}},{q="Leder uppdraget vidare till överlevnadsträning?",a="Eleanor välkomnar dig till sitt läger och delar med sig av råd om hur du reser genom vildmarken som äventyrare. Hon blir en vänlig kontaktpunkt i Tirisfals vildmark.",al={"fortsättning på sticks and bones","vad gör eleanor sedan"}}},fx={e518ee9d={q="Varför vill Deathguard Bartholomew att ved ska lämnas till Eleanor?",a="Deathguard Bartholomew håller ett öga på sin kollega Eleanor Shackleton, en erfaren överlevare som trotsar de farliga kullarna i väster. Han minns hennes valspråk om att alltid ha gott om ved i förråd och föreslår att du tar med extra bränsle. Det hjälper henne med hennes vakthållning och låter dig lära känna en erfaren resenär som kan lära dig att överleva i vildmarken.",al={"varför hjälpa eleanor","bartholomews motiv","varför sticks and bones"}},["8ea276ef"]={q="Vad ska Dry Branches användas till?",a="De torra grenarna är nödvändigt bränsle till Eleanor Shackletons lägereld ute i vildmarken. Trots att de vandrande döda saknar levande andedräkt behöver Eleanor en varm eld för att hålla kylan från nätterna i Tirisfal borta medan hon slår läger ensam bland kullarna.",al={"användning för torr gren","vad är torr gren till för","ved till eleanor"}},faf72368={q="Varför ber Bartholomew dig i stället för att själv samla veden?",a="Som Deathguard i Tirisfal Glades är Bartholomews främsta uppgift att hålla vakt och skydda vägarna. Han kan inte lämna sin post för att leta efter bränsle, så en självständig resenär som du är den perfekta budbäraren för att bära ved till Eleanors läger i vildmarken.",al={"varför jag, sticks and bones","varför behöver bartholomew mig","varför gör inte bartholomew det"}}},fp="16,193,18.306.0,17.364.0,38.106.0,35.125.0,53.197.0,51.72.0,45.146.0,50.145.0"}
P.entries["quest:868"] = {n="Egg Hunt",s="Över The Barrens söker Korran efter silithidägg att studera. Horde-lärde vid The Crossroads har hört talas om intelligenta insektsvarelser i söder och vill få hela ägg förda till Orgrimmar.",h="Över The Barrens söker Korran efter silithidägg att studera.",kw={"the barrens","the crossroads","digging claw","egg hunt","field of giants","korran","silithider"},ang={["faction:Horde"]="Horde är beroende av spanare som Korran för att hålla uppsikt över Kalimdors karga marker. Deras rapporter hjälper till att upptäcka märkliga hot innan de utsätter Durotar och Mulgore för fara.",["race:Troll"]="Som troll vet du att uråldriga varelser kan vara farliga. Silithiderna är inga vanliga småkryp, och Korran aktar sig för deras beräknande sinnen."},sec={{t="Ögon vid The Crossroads",b="Korran håller uppsikt över The Barrens från The Crossroads och rapporterar till Orgrimmar. Medan Horde står inför stamkonflikter och Alliance-infall studerar han märkliga förändringar i landet. Intelligenta insektsvarelser som delar ett bikupemedvetande har börjat gräva gångar i södra The Barrens."},{t="Gräva fram svärmen",b="Korran behöver prover för att ta reda på var silithiderna kommer ifrån och vad som driver dem. Med en utgrävningsklo beger du dig till Field of Giants och tar hela ägg ur jordhögarna. När du stör en hög kommer den närliggande yngelkullen till dess försvar, vilket visar svärmens kusliga samordning."}},faq={{q="Vem ger uppdraget Egg Hunt?",a="Korran erbjuder arbete vid The Crossroads i The Barrens. Trollet håller uppsikt över regionens växter, djur och märkliga förändringar åt sina uppdragsgivare i Orgrimmar.",al={"uppdragsgivare","korrans plats","vem startar egg hunt"}},{q="Var finns silithidäggen?",a="Silithidägg ligger i jordhögar vid Field of Giants i södra The Barrens. Högarna samlas runt bikupetunnlar i marken.",al={"äggenas plats","var hittar man ägg","ägg i field of giants"}},{q="Vilket verktyg behövs för att samla äggen?",a="Korran tillhandahåller en Digging Claw för att lyfta äggen utan att spräcka skalen. Du återlämnar den tillsammans med tolv oskadade ägg.",al={"grävverktyg","digging claw","hur får man ägg"}},{q="Vad skiljer insekterna från vanliga bestar?",a="Silithider agerar med kuslig samordning och list. Korran har upptäckt att deras intelligens vida överträffar vanliga djurs, som om de delar ett gemensamt syfte.",al={"varför är silithider speciella","insektsintelligens","silithidernas natur"}},{q="Varför vill Orgrimmar ha silithidägg?",a="Orgrimmar vill lära sig mer om okända hot nära Hordes landområden. Studier av äggen kan avslöja hur silithider växer, deras styrkor och deras biologi innan angreppet sprider sig.",al={"orgrimmars silithidstudie","varför studera ägg","korrans syfte"}},{q="Vad händer när man stör en äggkulle?",a="När en silithidhög störs blir svärmen upprörd. Silithider i närheten anfaller för att skydda ynglen.",al={"överfall vid kullen","silithidernas försvarare"}}},fx={cd75534e={q="Vad används Silithid Egg till?",a="Korrans överordnade i Orgrimmar placerade honom vid The Crossroads för att bevaka The Barrens och rapportera om nya hot. Man vet lite om de insektslika silithiderna som svärmar i de södra delarna, och hela ägg ger det råa biologiska material som behövs för att studera deras utveckling, fysiologi och ursprung innan kolonin sprider sig ytterligare.",al={"silithid eggs användning","varför samla silithidägg","silithidäggens syfte i the barrens"}},["2bb4e4c0"]={q="Vad är silithiderna i Field of Giants?",a="Silithiderna är en främmande och mycket aggressiv insektsart som gräver gångar genom södra The Barrens. Till skillnad från vanliga bestar, som enbart följer sina djuriska instinkter, uppvisar dessa varelser en oroväckande kollektiv intelligens och organiserade samhällen. Därför är deras plötsliga närvaro i Field of Giants ett allvarligt bekymmer för Horde.",al={"vad är silithiderna","kryp i field of giants","silithidernas mål i the barrens"}}},fp="8,193,22.260.0,20.272.0,29.153.0,34.131.0,40.120.0,55.150.0,38.179.0,43.92.0"}
P.entries["quest:8680"] = {n="Windtotem the Elder",s="Under Lunar Festival tar Windtotem the Elder emot resenärer på en klippa ovanför Ratchet. Hon välkomnar dem som vördar gångna tiders visdom och erbjuder en förfäders välsignelse och vägledning till andra äldste runtom på Kalimdor.",h="Under Lunar Festival tar Windtotem the Elder emot resenärer på en klippa ovanför Ratchet.",kw={"förfader","coin of ancestry","elder windtotem","lunar festival","ratchet","the barrens","windtotem the elder"},ang={["class:Druid"]="Som druid delar du Lunar Festivals firande av gemenskap med naturens och himlens kretslopp, som Cenarion Circle vakar över.",["class:Shaman"]="Som shaman hedrar du de döda och vårdar landets andliga hälsa när du talar med förfädersandar nära elementens mötesplatser.",["race:Tauren"]="Som tauren hedrar du en förfader ur den uråldriga Windtotem-släkten ovanför goblinernas hamn och knyter an till slätternas förfädersminne."},sec={{t="Vakt över viken",b="På en gräsbevuxen kulle strax nordväst om Ratchets flygmästare vakar Windtotem the Elder över goblinernas hamn och det öppna havet. Järn, krut och mynt passerar genom hamnen nedanför, medan stilla vindar från The Barrens och en stråle himmelskt ljus når den äldste."},{t="Visdom över The Barrens",b="Under Lunar Festival vägleder Windtotem the Elder vandrande dödliga, liksom de andra förfädersandarna. De som söker upp henne får hennes välsignelse och en gåva som tecken på hennes välvilja, tillsammans med viskningar som visar vägen till närliggande äldste runtom på kontinenten, däribland Elder Runetotem och Elder Bloodhoof."}},faq={{q="Var finns Elder Windtotem?",a="Windtotem the Elder står på en kulle strax nordväst om Ratchets flygmästare och blickar ut över hamnen i The Barrens.",al={"windtotems plats","var finns windtotem","karta över elder windtotem i ratchet"}},{q="Varför söker man upp Elder Windtotem?",a="Under Lunar Festival söker resenärer upp Windtotem the Elder för att hedra en förfader. Hon ger dig en Coin of Ancestry och berättar var du hittar andra andar runtom i landet.",al={"varför tala med windtotem","elder windtotems syfte","vad gör windtotem"}},{q="Varför lyser en ljusstråle ner på henne?",a="Lunar Festivals gestaltade förfäder står var och en i en egen pelare av himmelskt månljus, som markerar deras närvaro mellan förfädernas rike och de levandes värld.",al={"ljusstråle över äldre","varför lyser windtotem","ljus som faller på den äldre"}},{q="Kan både Alliansen och Horden tala med Elder Windtotem?",a="Ja. Ratchet är en neutral hamn som förvaltas av Steamwheedle Cartel, och Lunar Festivals äldste välkomnar både medlemmar av Alliance och Horde.",al={"kan alliansen tala med windtotem","är windtotem neutral","hordens och alliansens äldre"}},{q="Vilka andra äldste berättar Elder Windtotem om?",a="Windtotem the Elder vägleder dig till närliggande förfäder, däribland Elder Bloodhoof, Elder Runetotem, Elder Morningdew, Elder Darkhorn, Elder High Mountain, Elder Moonwarden och Elder Proudhorn.",al={"äldste som windtotem nämner","vem hänvisar windtotem till"}},{q="Vad händer när du visar den äldre din vördnad?",a="När du närmar dig Windtotem the Elder och hedrar henne prisar hon din livskraft, tar emot din vördnad och ger dig en Coin of Ancestry.",al={"lämna in hos elder windtotem","vad säger elder windtotem"}}},fp="19,213,20.259.0,25.285.0,33.115.0,51.169.0,49.180.0,61.142.0,55.193.0,51.163.0"}
